        .e_dec,
        .e_dec_small,
        .e_typed_int,
        .e_typed_frac,
        .e_typed_num_from_numeral,
        .e_empty_list,
        .e_empty_record,
        .e_zero_argument_tag,
        .e_runtime_error,
        .e_ellipsis,
        .e_anno_only,
        .e_derived_method,
        .e_crash,
        .e_closure,
        .e_lambda,
