        .e_tuple,
        .e_block,
        .e_match,
        .e_if,
        .e_call,
        .e_record,
        .e_tag,
        .e_nominal,
        .e_nominal_external,
        .e_binop,
        .e_unary_minus,
        .e_unary_not,
        .e_field_access,
        .e_interpolation,
        .e_structural_eq,
        .e_structural_hash,
        .e_method_eq,
        .e_type_method_call,
        .e_type_dispatch_call,
        .e_tuple_access,
        => true,
