    };
}

fn methodCallPreservesIteratorSourceInput(self: *Self, expr: CIR.Expr.Idx, call: anytype) bool {
    if (self.hoist_iterator_source_memo) |memo| {
        if (memo.expr == expr) return memo.preserves;
    }
    const preserves = self.computeMethodCallPreservesIteratorSourceInput(expr, call);
    self.hoist_iterator_source_memo = .{ .expr = expr, .preserves = preserves };
    return preserves;
}

fn computeMethodCallPreservesIteratorSourceInput(self: *Self, expr: CIR.Expr.Idx, call: anytype) bool {
    // Every def that can answer true is reachable only through the registry's
    // hoist-preserving method names: its producer table, the delegating
    // Dict/Set wrappers, and the FieldNames intrinsic all bind those names,
    // and a user-defined conversion is recognized by result type under the
    // same names (`static_dispatch_registry.zig` pins this by comptime
    // check). Anything else skips receiver resolution and the cross-module
    // binding lookup.
    if (!methodNameIsHoistPreservingCandidate(self.cir.getIdentText(call.method_name))) return false;
    var owner_var = ModuleEnv.varFrom(call.receiver);
    const nominal = while (true) {
        const resolved = self.types.resolveVar(owner_var);
        switch (resolved.desc.content) {
            .alias => |alias| owner_var = self.types.getAliasBackingVar(alias),
            .flex, .rigid, .field_presence, .structure, .err => break resolved.desc.content.unwrapNominalType() orelse return false,
        }
    };
    const owner_env = self.getNominalOriginEnv(nominal);
    const method = self.lookupStaticDispatchMethodBinding(
        owner_env,
        nominal.sourceDeclOptional(),
        self.cir,
        call.method_name,
    ) orelse return false;
    if (method.env.module_role == .builtin) {
        return static_dispatch.procedurePreservesHoistableSourceInputForEnvDef(
            method.env,
            method.binding.def_idx,
        );
    }
    // A user-defined conversion has no registry entry, so its result type
    // decides: an `Iter` holds its step closure by value, and selecting the
    // conversion itself as a static-data root would bake that closure instead
    // of the receiver collection it reads.
    return self.varIsIteratorNominal(ModuleEnv.varFrom(expr));
}

fn methodNameIsHoistPreservingCandidate(method_text: []const u8) bool {
    for (static_dispatch.hoist_preserving_method_names) |candidate| {
        if (Ident.textEql(method_text, candidate)) return true;
    }
    return false;
}

/// Whether this type is the builtin `Iter` nominal, looking through
/// transparent aliases.
fn varIsIteratorNominal(self: *Self, var_: Var) bool {
    const iter_source_decl = self.iteratorNominalSourceDecl() orelse return false;
    var walk = var_;
    while (true) {
        const resolved = self.types.resolveVar(walk);
        switch (resolved.desc.content) {
            .alias => |alias| walk = self.types.getAliasBackingVar(alias),
            .flex, .rigid, .field_presence, .structure, .err => {
                const nominal = resolved.desc.content.unwrapNominalType() orelse return false;
                const source_decl = nominal.sourceDeclOptional() orelse return false;
                return source_decl == iter_source_decl;
            },
        }
    }
}

fn iteratorNominalSourceDecl(self: *const Self) ?u32 {
    if (self.builtin_ctx.builtin_indices) |indices| return @intFromEnum(indices.iter_type);
    if (self.cir.module_role != .builtin) return null;
    const iter_stmt_idx = self.findLocalTypeDeclByName(self.cir.idents.builtin_iter) orelse return null;
    return @intFromEnum(iter_stmt_idx);
}

fn stringHasInterpolation(self: *Self, span: CIR.Expr.Span) bool {
    for (self.cir.store.sliceExpr(span)) |segment| {
        if (self.cir.store.getExpr(segment) != .e_str_segment) return true;
    }
    return false;
}
/// In debug builds, verifies that region and type arrays have matching lengths.
pub inline fn debugAssertArraysInSync(self: *const Self) void {
    if (builtin.mode == .Debug) {
        const region_nodes = self.regions.len();
        const type_nodes = self.types.len();
        if (!(region_nodes == type_nodes)) {
            std.debug.panic(
                "Arrays out of sync:\n type_nodes={}\n  region_nodes={}\n ",
                .{ type_nodes, region_nodes },
            );
        }
    }
}

/// Fills the type store with fresh variables up to the number of regions
inline fn ensureTypeStoreIsFilled(self: *Self) Allocator.Error!void {
    const region_nodes: usize = @intCast(self.regions.len());
    const type_nodes: usize = @intCast(self.types.len());
    if (type_nodes >= region_nodes) return;
    try self.types.ensureTotalCapacity(region_nodes);
    for (type_nodes..region_nodes) |_| {
        _ = self.types.appendFromContentAssumeCapacity(.{ .flex = Flex.init() }, Rank.outermost);
    }
}

// import caches //

/// Key for the import cache: module index + expression index in that module
const ImportCacheKey = struct {
    resolved_module_idx: u32,
    node_idx: CIR.Node.Idx,
};

/// Cache for imported types to avoid repeated copying
///
/// When we import a type from another module, we need to copy it into our module's
/// type store because type variables are module-specific. However, since we use
/// "preserve" mode unification with imported types (meaning the imported type is
/// read-only and never modified), we can safely cache these copies and reuse them;
/// they will never be mutated during unification.
///
/// Benefits:
/// - Reduces memory usage by avoiding duplicate copies of the same imported type
/// - Improves performance by avoiding redundant copying operations
/// - Particularly beneficial for commonly imported values/functions
///
/// Example: If a module imports `List.map` and uses it 10 times, without caching
/// we would create 10 separate copies of the `List.map` type. With caching, we
/// create just one copy and reuse it.
const ImportCache = std.HashMapUnmanaged(ImportCacheKey, Var, struct {
    pub fn hash(_: @This(), key: ImportCacheKey) u64 {
        var hasher = std.hash.Wyhash.init(0);
        hasher.update(std.mem.asBytes(&key.resolved_module_idx));
        hasher.update(std.mem.asBytes(&key.node_idx));
        return hasher.final();
    }

    pub fn eql(_: @This(), a: ImportCacheKey, b: ImportCacheKey) bool {
        return a.resolved_module_idx == b.resolved_module_idx and a.node_idx == b.node_idx;
    }
}, 80);

const OpenNumeralLiteral = struct {
    var_: Var,
    constraint: StaticDispatchConstraint,
    source_node: ?CIR.Node.Idx,
};

const PendingTupleAccess = struct {
    tuple_var: Var,
    result_var: Var,
    elem_index: u32,
    region: Region,
};

// env //

/// Solver env
const Env = struct {
    /// Pool of variables created during solving, use by let-polymorphism
    var_pool: VarPool,
    /// Deferred static dispatch constraints - accumulated during type checking,
    /// then solved for at the end
    deferred_static_dispatch_constraints: DeferredConstraintCheck.SafeList,

    fn init(
        gpa: std.mem.Allocator,
        at: Rank,
    ) std.mem.Allocator.Error!Env {
        var pool = try VarPool.init(gpa);
        pool.current_rank = at;
        try pool.ensureRanksThrough(at);

        return .{
            .var_pool = pool,
            .deferred_static_dispatch_constraints = try DeferredConstraintCheck.SafeList.initCapacity(gpa, 32),
        };
    }

    fn deinit(self: *Env, gpa: std.mem.Allocator) void {
        self.var_pool.deinit();
        self.deferred_static_dispatch_constraints.deinit(gpa);
    }

    /// Resets internal state of env and set rank to generalized
    fn reset(self: *Env, to: Rank) Allocator.Error!void {
        self.var_pool.current_rank = to;
        self.var_pool.clearRetainingCapacity();
        try self.var_pool.ensureRanksThrough(to);
        self.deferred_static_dispatch_constraints.items.clearRetainingCapacity();
    }

    fn rank(self: *const Env) Rank {
        return self.var_pool.current_rank;
    }
};

// unify //

/// Build the borrowed dependency bundle the unifier needs. Cheap (9 pointers);
/// constructed per call and inlined.
fn unifyEnv(self: *Self) unifier.Env {
    return .{
        // problems is owned by self.gpa.
        .problems_gpa = self.gpa,
        .ident_store = self.cir.getIdentStoreConst(),
        .self_module_identity = self.cir.selfModuleIdentity(),
        .types = self.types,
        .problems = &self.problems,
        .snapshots = &self.snapshots,
        .type_writer = &self.type_writer,
        .unify_scratch = &self.unify_scratch,
        .occurs_scratch = &self.occurs_scratch,
        .construction_probe = .{ .ctx = self, .isRecordConstruction = probeRecordConstruction },
    };
}

fn probeRecordConstruction(ctx: *const anyopaque, var_: Var) bool {
    const self: *const Self = @ptrCast(@alignCast(ctx));
    return self.sourceRecordConstructionForVar(var_) != null;
}

fn sourceRecordConstructionForVar(self: *const Self, var_: Var) ?CIR.Expr.Idx {
    const raw = @intFromEnum(var_);
    if (raw < self.cir.store.nodes.len()) {
        const node = self.cir.store.nodes.get(@enumFromInt(raw));
        if (node.tag == .expr_record or node.tag == .expr_empty_record) {
            return @enumFromInt(raw);
        }
    }
    return null;
}

fn recordAbsorbedDefaults(self: *Self, construction_var: ?Var, a: Var, b: Var) std.mem.Allocator.Error!void {
    for (self.unify_scratch.absorbed_record_defaults.items.items) |absorbed| {
        var mb_expr = self.sourceRecordConstructionForVar(absorbed.record_var);
        // The pair enclosing the absorption names the construction directly,
        // including when it is nested inside the operands (a record literal in
        // a tag payload, say), which the outer operand vars cannot reach.
        if (mb_expr == null) {
            if (absorbed.enclosing_records) |pair| {
                mb_expr = self.sourceRecordConstructionForVar(pair[1]) orelse
                    self.sourceRecordConstructionForVar(pair[0]);
            }
        }
        if (mb_expr == null) {
            if (construction_var) |owner| mb_expr = self.sourceRecordConstructionForVar(owner);
        }
        if (mb_expr == null) mb_expr = self.sourceRecordConstructionForVar(b);
        if (mb_expr == null) mb_expr = self.sourceRecordConstructionForVar(a);
        const expr = mb_expr orelse
            std.debug.panic("type checker invariant violated: defaulted-field width absorption lost its source record construction", .{});

        var already_recorded = false;
        for (self.cir.record_omitted_defaults.items.items) |existing| {
            if (existing.expr == expr and existing.field_name == absorbed.name and
                existing.origin_module == absorbed.default.origin_module and
                existing.default_expr_node == absorbed.default.expr_node)
            {
                already_recorded = true;
                break;
            }
        }
        if (already_recorded) continue;

        _ = try self.cir.record_omitted_defaults.append(self.cir.gpa, .{
            .expr = expr,
            .field_name = absorbed.name,
            .origin_module = absorbed.default.origin_module,
            .default_expr_node = absorbed.default.expr_node,
        });
    }
}

/// The single core: run unification, then assign ranks/regions to fresh vars,
/// copy out deferred constraints, and assert array sync.
fn runUnify(self: *Self, a: Var, b: Var, env: *Env, opts: unifier.Options) std.mem.Allocator.Error!unifier.Result {
    const trace = tracy.trace(@src());
    defer trace.end();

    const construction_var = opts.record_construction_var orelse if (self.instantiation_source_expr) |source|
        if (self.exprIsFreshRecordConstruction(source)) ModuleEnv.varFrom(source) else null
    else
        null;
    const unify_env = self.unifyEnv();
    // The unifier decides whether a defaulted row may be absorbed at all, so it
    // needs the same owner the absorption will later be attributed to.
    var unify_opts = opts;
    unify_opts.record_construction_var = construction_var;
    const result = try unifier.unify(&unify_env, a, b, unify_opts);

    if (result.isAccepted()) {
        try self.recordAbsorbedDefaults(construction_var, a, b);
    }

    // Set regions and add to the current rank all variables created during unification.
    //
    // We assign all fresh variables the region of `b` (the "actual" type), since `a` is
    // typically the "expected" type from an annotation. This policy works well for
    // most cases but can be imprecise for deeply nested unifications where fresh variables
    // are created for sub-components (e.g., record fields, tag payloads). In those cases,
    // error messages may point to the outer expression rather than the specific field.
    //
    // A more precise solution would track the origin of each fresh variable during
    // unification and propagate that back, but the current approach is sufficient for
    // typical error reporting scenarios.
    const region = self.getRegionAt(b);
    for (self.unify_scratch.fresh_vars.items.items) |fresh_var| {
        // Set the rank
        const fresh_rank = self.types.resolveVar(fresh_var).desc.rank;
        try env.var_pool.addVarToRank(fresh_var, fresh_rank);

        // Set the region
        try self.fillInRegionsThrough(fresh_var);
        self.setRegionAt(fresh_var, region);
    }

    // Copy any constraints created during unification into our own array. A
    // where-clause obligation that becomes concrete while checking a scheme use
    // belongs to that use; ordinary dispatch and literal constraints retain
    // their own creation-time provenance. The group whose checking ran this
    // unification owns each obligation's boundary-time resolution.
    const failure_expr = self.discarded_binding_rhs_expr orelse self.instantiation_source_expr;
    for (self.unify_scratch.deferred_constraints.items.items) |deferred_constraint| {
        var owned_constraint = deferred_constraint;
        if (failure_expr) |expr_idx| {
            if (owned_constraint.failure_expr == .none) {
                for (self.types.sliceStaticDispatchConstraints(owned_constraint.constraints)) |constraint| {
                    if (constraint.origin == .where_clause) {
                        owned_constraint.failure_expr = .from(@intFromEnum(expr_idx));
                        break;
                    }
                }
            }
        }
        try self.enqueueDeferredDispatchConstraint(env, owned_constraint, .current_group);
    }

    // Ensure arrays are in sync
    self.debugAssertArraysInSync();

    return result;
}

/// Unify two types where `a` is the expected type and `b` is the actual type.
fn unify(self: *Self, a: Var, b: Var, env: *Env) std.mem.Allocator.Error!unifier.Result {
    return self.runUnify(a, b, env, .{});
}

fn fieldPresenceRelationForContext(
    ctx: problem.Context,
    row_width_relation: unifier.RowWidthRelation,
) unifier.FieldPresenceRelation {
    if (ctx == .record_access) {
        return if (ctx.record_access.mode == .required) .required_access else .ordinary;
    }
    return if (row_width_relation == .exact) .committed_value else .ordinary;
}

fn unifyOptionsForContext(ctx: problem.Context, on_mismatch: unifier.MismatchBehavior) unifier.Options {
    const row_width_relation: unifier.RowWidthRelation = if (std.meta.activeTag(ctx) == .platform_requirement)
        .exact
    else
        .construction;
    return .{
        .context = ctx,
        .on_mismatch = on_mismatch,
        .row_width_relation = row_width_relation,
        .field_presence_relation = fieldPresenceRelationForContext(ctx, row_width_relation),
    };
}

/// Unify two types with a context for error reporting.
fn unifyInContext(self: *Self, a: Var, b: Var, env: *Env, ctx: problem.Context) std.mem.Allocator.Error!unifier.Result {
    return self.runUnify(a, b, env, unifyOptionsForContext(ctx, .poison_to_err));
}

fn exprIsFreshRecordConstruction(self: *const Self, expr_idx: CIR.Expr.Idx) bool {
    const expr = self.cir.store.getExpr(expr_idx);
    return expr == .e_record or expr == .e_empty_record;
}

/// Check one relation owned by a single expression without letting a rejected
/// relation poison the operand type graphs. Those graphs can be shared with
/// otherwise valid producer expressions—a callee, an argument, or the record
/// a field access reads from—so only the owning expression becomes erroneous.
fn unifyOwnedRelation(
    self: *Self,
    expected: Var,
    actual: Var,
    env: *Env,
    ctx: problem.Context,
    row_width_relation: unifier.RowWidthRelation,
) std.mem.Allocator.Error!unifier.Result {
    return self.unifyOwnedRootRelation(expected, actual, env, ctx, row_width_relation, .ordinary);
}

/// `unifyOwnedRelation` for a relation whose initial pair carries a root
/// relation beyond ordinary unification.
fn unifyOwnedRootRelation(
    self: *Self,
    expected: Var,
    actual: Var,
    env: *Env,
    ctx: problem.Context,
    row_width_relation: unifier.RowWidthRelation,
    root_relation: unifier.RootRelation,
) std.mem.Allocator.Error!unifier.Result {
    const result = try self.runUnify(expected, actual, env, .{
        .context = ctx,
        .on_mismatch = .write_no_report,
        .root_relation = root_relation,
        .row_width_relation = row_width_relation,
        .field_presence_relation = fieldPresenceRelationForContext(ctx, row_width_relation),
        .record_construction_var = if (row_width_relation == .construction) actual else null,
    });
    if (result.isAccepted()) return result;
    return .{ .problem = try self.appendTypeMismatch(expected, actual, ctx) };
}

/// Record a type mismatch between two vars under a context. Every caller that
/// owns its own rejection reports through here, so a rejection re-decided at
/// the settled state renders exactly like the relation-time one.
fn appendTypeMismatch(
    self: *Self,
    expected: Var,
    actual: Var,
    ctx: problem.Context,
) std.mem.Allocator.Error!problem.Problem.Idx {
    const expected_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, expected);
    const actual_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, actual);
    return self.problems.appendProblem(self.gpa, .{ .type_mismatch = .{
        .types = .{
            .expected_var = expected,
            .expected_snapshot = expected_snapshot,
            .actual_var = actual,
            .actual_snapshot = actual_snapshot,
        },
        .context = ctx,
    } });
}

/// The constructor's operand is an ordinary value expression whose solved class
/// is shared with everything else that value flows through—in the very case
/// this relation exists to reject, `..receiver` has already lifted the update to
/// the nominal, so the operand's class *is* the receiver's. Rejecting the
/// constructor therefore owns the diagnostic and poisons only the constructor
/// node; the receiver keeps the type it legitimately has.
fn unifyNominalConstructorBacking(
    self: *Self,
    expected_backing: Var,
    actual_backing: Var,
    env: *Env,
    ctx: problem.Context.NominalConstructorContext,
    row_width_relation: unifier.RowWidthRelation,
) std.mem.Allocator.Error!unifier.Result {
    return self.unifyOwnedRootRelation(
        expected_backing,
        actual_backing,
        env,
        .{ .nominal_constructor = ctx },
        row_width_relation,
        .nominal_constructor_backing,
    );
}

/// Check if a variable contains an infinite type after solving a binding.
/// This catches cases like `f = |x| f([x])` which creates `a = List(a)`.
///
/// Runs at binding roots: top-level defs (`CIR.Def.Idx`, the settled-state
/// sweep), local bindings (`CIR.Pattern.Idx`, when their statement finishes
/// solving), and standalone checked expressions (`CIR.Expr.Idx`, REPL roots).
fn checkForInfiniteType(self: *Self, comptime Idx: anytype, idx: Idx) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    std.debug.assert(Idx == CIR.Def.Idx or Idx == CIR.Expr.Idx or Idx == CIR.Pattern.Idx);

    const var_ = ModuleEnv.varFrom(idx);
    const occurs_result = try occurs.occurs(self.types, &self.occurs_scratch, var_);

    switch (occurs_result) {
        .valid => {
            // This is fine - no cycle, or valid recursion through a nominal type
        },
        .recursive_anonymous => {
            // Anonymous recursion (a recursive type not routed through a
            // nominal) is always disallowed, at every binding root—top-level
            // defs, checked expression roots, and local bindings alike. A
            // recursive type must go through a nominal to be valid. The
            // `.recursive_anonymous` vs `.infinite` classification only selects
            // a clearer error message; it never permits the type.
            std.debug.assert(self.occurs_scratch.err_var != null);
            const err_var = self.occurs_scratch.err_var.?;

            const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, err_var);
            _ = try self.problems.appendProblem(self.gpa, .{ .anonymous_recursion = .{
                .var_ = var_,
                .snapshot = snapshot,
                .def_name = self.bindingRootName(Idx, idx),
            } });
            try self.types.setVarContent(var_, .err);
        },
        .infinite => {
            std.debug.assert(self.occurs_scratch.err_var != null);
            const err_var = self.occurs_scratch.err_var.?;

            // Infinite type (like `a = List(a)`)
            const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, err_var);
            _ = try self.problems.appendProblem(self.gpa, .{ .infinite_recursion = .{
                .var_ = var_,
                .snapshot = snapshot,
                .def_name = self.bindingRootName(Idx, idx),
            } });
            try self.types.setVarContent(var_, .err);
        },
    }
}

/// The settled-state occurs sweep: check every binding root—top-level defs
/// and recorded local bindings—for infinite/anonymous-recursive types, after
/// all deferred constraints have been solved.
fn checkBindingRootsForInfiniteTypes(self: *Self) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Local bindings first: when a local binding's cycle is also reachable
    // from the enclosing top-level def's type, reporting (and poisoning) the
    // local binding attributes the error to the tighter root and suppresses a
    // duplicate report at the def.
    for (self.local_binding_roots.items) |pattern_idx| {
        try self.checkForInfiniteType(CIR.Pattern.Idx, pattern_idx);
    }
    for (0..self.cir.all_defs.span.len) |def_offset| {
        const def_idx = self.cir.store.defAt(self.cir.all_defs, def_offset);
        try self.checkForInfiniteType(CIR.Def.Idx, def_idx);
    }
}

/// The settled-state re-decision of every accepted explicit nominal constructor
/// backing relation.
///
/// The relation rejects lifting an already-nominal operand back through an
/// anonymous expected backing. That is decided from the operand's solved shape,
/// and unification can widen the shape after the relation runs: an operand that
/// was still an open row when the constructor was checked lifts to the nominal
/// once a later call pins it, which is exactly the shape the rule exists to
/// reject. Re-deciding here is what makes the rule's verdict independent of
/// where the constructor happens to be written.
///
/// A constructor rejected here has already handed its result type to every
/// consumer, so poisoning the target var would corrupt the annotation classes it
/// merged into. Only the constructor expression becomes a runtime error.
fn recheckNominalConstructorBackings(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    var rejected: std.ArrayListUnmanaged(u32) = .empty;
    defer rejected.deinit(self.gpa);

    // Indexed rather than over a captured slice: nothing here appends to the
    // list today, and a captured slice would be the thing that breaks first if
    // that ever changed.
    var index: usize = 0;
    while (index < self.accepted_nominal_constructor_backings.items.len) : (index += 1) {
        const accepted = self.accepted_nominal_constructor_backings.items[index];
        const lifted = unifier.constructorBackingActualIsNominal(self.types, accepted.actual_backing) orelse continue;
        if (!lifted) continue;
        if (self.cir.store.getExpr(accepted.expr_idx) == .e_runtime_error) continue;
        try rejected.append(self.gpa, @intCast(index));
    }
    if (rejected.items.len == 0) return;

    // Source order, widest first where two rejections start together: this is
    // the order the reports come out in, and it puts an enclosing rejection
    // ahead of the ones its own replacement is about to discard.
    const RejectionOrder = struct {
        check: *const Self,
        fn lessThan(check: *const Self, a: u32, b: u32) bool {
            const region_a = check.rejectedNominalConstructorRegion(a);
            const region_b = check.rejectedNominalConstructorRegion(b);
            if (region_a.start.offset != region_b.start.offset) {
                return region_a.start.offset < region_b.start.offset;
            }
            if (region_a.end.offset != region_b.end.offset) {
                return region_a.end.offset > region_b.end.offset;
            }
            return a < b;
        }
    };
    std.mem.sort(u32, rejected.items, @as(*const Self, self), RejectionOrder.lessThan);

    var reported_regions: std.ArrayListUnmanaged(Region) = .empty;
    defer reported_regions.deinit(self.gpa);

    for (rejected.items) |entry_index| {
        const accepted = self.accepted_nominal_constructor_backings.items[entry_index];
        const region = self.rejectedNominalConstructorRegion(entry_index);
        if (self.expressionErrorAlreadyEncloses(region, reported_regions.items)) continue;

        // One var rebuilt from the declared backing's own content. It describes
        // the expected side the merged class can no longer show, and minting it
        // touches nothing the solved graph already holds.
        const expected_backing = try self.freshFromContent(accepted.expected_backing_content, env, region);
        _ = try self.appendTypeMismatch(
            expected_backing,
            accepted.actual_backing,
            .{ .nominal_constructor = accepted.context },
        );

        const diagnostic_idx = try self.cir.addDiagnostic(.{ .erroneous_value_expr = .{ .region = region } });
        try self.replaceExprWithRuntimeError(accepted.expr_idx, diagnostic_idx);
        try reported_regions.append(self.gpa, region);
    }
}

fn rejectedNominalConstructorRegion(self: *const Self, entry_index: u32) Region {
    return self.cir.store.getExprRegion(self.accepted_nominal_constructor_backings.items[entry_index].expr_idx);
}

/// Whether an expression already destined to become a runtime error encloses
/// this region. The enclosing error replaces the whole subtree, so a second
/// report would describe source the checked module no longer contains—which is
/// exactly what a relation-time rejection avoids by poisoning its own node and
/// letting the enclosing relations read `.err`.
fn expressionErrorAlreadyEncloses(self: *const Self, region: Region, reported: []const Region) bool {
    for (reported) |outer| {
        if (outer.start.offset <= region.start.offset and region.end.offset <= outer.end.offset) return true;
    }
    var queued = self.erroneous_value_exprs.keyIterator();
    while (queued.next()) |expr_idx| {
        const outer = self.cir.store.getExprRegion(expr_idx.*);
        if (outer.start.offset <= region.start.offset and region.end.offset <= outer.end.offset) return true;
    }
    return false;
}

/// The display name for a binding root being occurs-checked, when it has one.
fn bindingRootName(self: *const Self, comptime Idx: anytype, idx: Idx) ?Ident.Idx {
    if (comptime Idx == CIR.Def.Idx) {
        const def = self.cir.store.getDef(idx);
        return self.getPatternIdent(def.pattern);
    }
    if (comptime Idx == CIR.Pattern.Idx) {
        return self.getPatternIdent(idx);
    }
    return null;
}

fn propagateTypeDeclarationInvalidity(
    self: *Self,
    dependent_offsets: []const usize,
    dependents: []const u32,
    propagated: []bool,
    worklist: *std.ArrayListUnmanaged(u32),
) void {
    worklist.clearRetainingCapacity();
    for (self.type_decl_invalid.items, propagated, 0..) |invalid, *was_propagated, dense_idx| {
        if (!invalid or was_propagated.*) continue;
        was_propagated.* = true;
        worklist.appendAssumeCapacity(@intCast(dense_idx));
    }

    var next: usize = 0;
    while (next < worklist.items.len) : (next += 1) {
        const dependency = worklist.items[next];
        for (dependents[dependent_offsets[dependency]..dependent_offsets[dependency + 1]]) |dependent| {
            if (self.type_decl_invalid.items[dependent]) continue;
            self.type_decl_invalid.items[dependent] = true;
            propagated[dependent] = true;
            worklist.appendAssumeCapacity(dependent);
        }
    }
}

fn poisonInvalidTypeDeclarations(self: *Self, poisoned: []bool) std.mem.Allocator.Error!void {
    const self_origin = self.cir.selfModuleIdentity();
    for (self.type_decl_statements.items, self.type_decl_invalid.items, poisoned) |decl_idx, invalid, *was_poisoned| {
        if (!invalid or was_poisoned.*) continue;
        was_poisoned.* = true;

        const backing_var: ?Var = switch (self.cir.store.getStatement(decl_idx)) {
            .s_alias_decl => |alias| if (alias.anno == .placeholder) null else ModuleEnv.varFrom(alias.anno),
            .s_nominal_decl => blk: {
                const nominal_idx = self.types.lookupNominalDeclByKey(
                    self_origin,
                    @intFromEnum(decl_idx),
                ) orelse unreachable;
                const nominal = self.types.getNominalDecl(nominal_idx);
                self.types.markNominalDeclInvalid(nominal_idx);
                break :blk nominal.backing;
            },
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => unreachable,
        };

        try self.types.setVarContent(ModuleEnv.varFrom(decl_idx), .err);
        if (backing_var) |var_| try self.types.setVarContent(var_, .err);
    }
}

/// Close declaration-template invalidity over local declaration references,
/// validate nominal recursion, and poison every transitively invalid declaration.
fn finalizeTypeDeclarationValidity(self: *Self) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    const decl_count = self.type_decl_statements.items.len;
    if (decl_count == 0) return;

    var dependent_counts = try self.gpa.alloc(usize, decl_count);
    defer self.gpa.free(dependent_counts);
    @memset(dependent_counts, 0);

    for (self.type_decl_dependencies.items) |edge| {
        dependent_counts[edge.dependency] += 1;
    }

    var dependent_offsets = try self.gpa.alloc(usize, decl_count + 1);
    defer self.gpa.free(dependent_offsets);
    dependent_offsets[0] = 0;
    for (dependent_counts, 0..) |count, dense_idx| {
        dependent_offsets[dense_idx + 1] = dependent_offsets[dense_idx] + count;
    }

    var fill_offsets = try self.gpa.dupe(usize, dependent_offsets[0..decl_count]);
    defer self.gpa.free(fill_offsets);
    const dependents = try self.gpa.alloc(u32, self.type_decl_dependencies.items.len);
    defer self.gpa.free(dependents);

    for (self.type_decl_dependencies.items) |edge| {
        const offset = fill_offsets[edge.dependency];
        dependents[offset] = edge.dependent;
        fill_offsets[edge.dependency] += 1;
    }

    var worklist: std.ArrayListUnmanaged(u32) = .empty;
    defer worklist.deinit(self.gpa);
    try worklist.ensureTotalCapacity(self.gpa, decl_count);

    const propagated = try self.gpa.alloc(bool, decl_count);
    defer self.gpa.free(propagated);
    @memset(propagated, false);

    const poisoned = try self.gpa.alloc(bool, decl_count);
    defer self.gpa.free(poisoned);
    @memset(poisoned, false);

    self.propagateTypeDeclarationInvalidity(dependent_offsets, dependents, propagated, &worklist);
    try self.poisonInvalidTypeDeclarations(poisoned);

    try self.validateNominalDeclRecursion();

    self.propagateTypeDeclarationInvalidity(dependent_offsets, dependents, propagated, &worklist);
    try self.poisonInvalidTypeDeclarations(poisoned);
}

/// Validate every local nominal type declaration's backing recursion, after
/// all type declarations have been generated and before any value checking.
///
/// The traversal resolves nominal backings through the store's declaration
/// table by key (`occurs.occursDeclarationGraph`), so recursive references
/// close cycles by declaration identity—including mutual recursion that
/// per-use instantiation copies disconnect. Classification matches the
/// value-graph occurs rules: a cycle is valid only when it passes through
/// both a recursion-allowed position (tag payload / record field) and a
/// nominal backing.
///
/// An invalid declaration is reported once, here, at the declaration; the
/// declaration is marked invalid in the table and its decl var and backing
/// template are poisoned to `.err`, so every use is suppressed instead of
/// re-reporting the same cycle.
fn validateNominalDeclRecursion(self: *Self) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    const self_origin = self.cir.selfModuleIdentity();
    const decl_count = self.types.nominalDeclCount();
    var decl_int: u32 = 0;
    while (decl_int < decl_count) : (decl_int += 1) {
        const decl_idx: types_mod.NominalDecl.Idx = @enumFromInt(decl_int);
        const decl = self.types.getNominalDecl(decl_idx);

        // Imported declarations were validated by their own module; module
        // imports are acyclic, so no cycle involving a local declaration can
        // route through them except via type arguments, which the local
        // traversal covers.
        if (decl.origin_module != self_origin) continue;

        const decl_var: Var = @enumFromInt(decl.statement());
        const resolved = self.types.resolveVar(decl_var).desc.content;
        // A declaration whose generation already failed (malformed backing)
        // has nothing further to validate.
        if (resolved != .structure or resolved.structure != .nominal_type) continue;

        const occurs_result = try occurs.occursDeclarationGraph(self.types, &self.occurs_scratch, decl_var);
        const kind: problem.InvalidNominalDeclRecursion.Kind = switch (occurs_result) {
            .valid => continue,
            .infinite => .infinite,
            .recursive_anonymous => .anonymous,
        };

        // Snapshot the declaration's backing template (not the cycle var,
        // which resolves to the bare nominal application and would render as
        // just the type's name).
        const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, decl.backing);
        _ = try self.problems.appendProblem(self.gpa, .{ .invalid_nominal_decl_recursion = .{
            .decl_var = decl_var,
            .snapshot = snapshot,
            .type_name = decl.ident.ident_idx,
            .kind = kind,
        } });

        // Poison the declaration: uses instantiate `.err` and are suppressed,
        // and no later stage can walk the cyclic template graph.
        self.markTypeDeclInvalid(@enumFromInt(decl.statement()));
        self.types.markNominalDeclInvalid(decl_idx);
        try self.types.setVarContent(decl_var, .err);
        try self.types.setVarContent(decl.backing, .err);
    }
}

fn resolvePendingTupleAccess(
    self: *Self,
    pending: PendingTupleAccess,
    env: *Env,
    final: bool,
) Allocator.Error!bool {
    const tuple_resolved = self.types.resolveVar(pending.tuple_var);
    switch (tuple_resolved.desc.content) {
        .structure => |structure| switch (structure) {
            .tuple => |tuple| {
                const elems = self.types.sliceVars(tuple.elems);
                if (pending.elem_index < elems.len) {
                    _ = try self.unify(pending.result_var, elems[pending.elem_index], env);
                } else {
                    _ = try self.problems.appendProblem(self.gpa, .{ .invalid_tuple_access = .{
                        .region = pending.region,
                        .elem_index = pending.elem_index,
                        .reason = .{ .index_out_of_bounds = @intCast(elems.len) },
                    } });
                    try self.markErroneous(pending.result_var);
                }
                return true;
            },
            .record,
            .record_unbound,
            .nominal_type,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => {
                _ = try self.problems.appendProblem(self.gpa, .{ .invalid_tuple_access = .{
                    .region = pending.region,
                    .elem_index = pending.elem_index,
                    .reason = .not_tuple,
                } });
                try self.markErroneous(pending.result_var);
                return true;
            },
        },
        .alias => |alias| {
            const backing_var = self.types.getAliasBackingVar(alias);
            const alias_pending = PendingTupleAccess{
                .tuple_var = backing_var,
                .result_var = pending.result_var,
                .elem_index = pending.elem_index,
                .region = pending.region,
            };
            return try self.resolvePendingTupleAccess(alias_pending, env, final);
        },
        .err, .field_presence => {
            try self.markErroneous(pending.result_var);
            return true;
        },
        .flex, .rigid => {
            if (!final) return false;

            _ = try self.problems.appendProblem(self.gpa, .{ .tuple_access_needs_annotation = .{
                .region = pending.region,
                .elem_index = pending.elem_index,
            } });
            try self.markErroneous(pending.result_var);
            try self.markErroneous(pending.tuple_var);
            return true;
        },
    }
}

fn resolvePendingTupleAccesses(
    self: *Self,
    env: *Env,
    final: bool,
) Allocator.Error!void {
    var write_i: usize = 0;
    var read_i: usize = 0;
    while (read_i < self.pending_tuple_accesses.items.len) : (read_i += 1) {
        const pending = self.pending_tuple_accesses.items[read_i];
        if (try self.resolvePendingTupleAccess(pending, env, final)) continue;

        self.pending_tuple_accesses.items[write_i] = pending;
        write_i += 1;
    }
    self.pending_tuple_accesses.shrinkRetainingCapacity(write_i);
}

// instantiate  //

const InstantiateRegionBehavior = union(enum) {
    explicit: Region,
    use_root_instantiated,
    use_last_var,
};

fn typeSchemeIndexForRoot(self: *Self, root_var: Var) ?usize {
    const raw_index = self.type_scheme_by_var.get(root_var) orelse return null;
    const index: usize = raw_index;
    std.debug.assert(index < self.type_schemes.items.len);
    return index;
}

fn isBindingSchemeVar(self: *const Self, var_: Var) bool {
    const raw_var: usize = @intFromEnum(var_);
    if (raw_var < self.binding_scheme_nodes.bit_length) {
        return self.binding_scheme_nodes.isSet(raw_var);
    }
    return self.synthetic_binding_schemes.contains(var_);
}

fn markBindingSchemeVar(self: *Self, var_: Var) Allocator.Error!void {
    const raw_var: usize = @intFromEnum(var_);
    if (raw_var < self.binding_scheme_nodes.bit_length) {
        if (self.binding_scheme_nodes.isSet(raw_var)) return;
        self.binding_scheme_nodes.set(raw_var);
        return;
    }
    try self.synthetic_binding_schemes.put(self.gpa, var_, {});
}

/// Publish the dense checker-local classification as the compact sorted table
/// stored in checked module output. Scanning node order once avoids maintaining
/// a sorted list while dependency-order checking discovers schemes.
fn finalizeBindingSchemeNodes(self: *Self) Allocator.Error!void {
    self.cir.binding_schemes.items.clearRetainingCapacity();
    var raw_node: usize = 0;
    while (raw_node < self.binding_scheme_nodes.bit_length) : (raw_node += 1) {
        if (self.binding_scheme_nodes.isSet(raw_node)) {
            try self.cir.recordBindingScheme(@enumFromInt(raw_node));
        }
    }
}

fn bindBindingSchemeVar(self: *Self, scheme_var: Var, alias_var: Var) Allocator.Error!void {
    if (self.isBindingSchemeVar(scheme_var)) {
        try self.markBindingSchemeVar(alias_var);
    }
}

/// Whether the post-generalization graph reachable from `root_var` contains a
/// quantified variable. This exact producer-side walk classifies a rank-1
/// binding once; use sites consume the recorded classification in O(1).
fn typeHasGeneralizedVar(self: *Self, root_var: Var) Allocator.Error!bool {
    if (self.types.resolveVar(root_var).desc.rank == .generalized) return true;

    self.binding_scheme_classification_seen.clearRetainingCapacity();
    self.binding_scheme_classification_stack.clearRetainingCapacity();
    defer self.binding_scheme_classification_stack.clearRetainingCapacity();

    try self.binding_scheme_classification_stack.append(self.gpa, root_var);
    while (self.binding_scheme_classification_stack.pop()) |pending_var| {
        const resolved = self.types.resolveVar(pending_var);
        if (resolved.desc.rank == .generalized) return true;
        const seen = try self.binding_scheme_classification_seen.getOrPut(self.gpa, resolved.var_);
        if (seen.found_existing) continue;

        switch (resolved.desc.content) {
            .err, .field_presence => {},
            .flex, .rigid => {},
            .alias => |alias| try self.binding_scheme_classification_stack.appendSlice(
                self.gpa,
                self.types.sliceAliasArgs(alias),
            ),
            .structure => |flat| switch (flat) {
                .empty_record, .empty_tag_union => {},
                .tuple => |tuple| try self.binding_scheme_classification_stack.appendSlice(
                    self.gpa,
                    self.types.sliceVars(tuple.elems),
                ),
                .nominal_type => |nominal| try self.binding_scheme_classification_stack.appendSlice(
                    self.gpa,
                    self.types.sliceNominalArgs(nominal),
                ),
                .fn_pure, .fn_effectful, .fn_unbound => |func| {
                    try self.binding_scheme_classification_stack.appendSlice(self.gpa, self.types.sliceVars(func.args));
                    try self.binding_scheme_classification_stack.append(self.gpa, func.ret);
                    try self.binding_scheme_classification_stack.appendSlice(self.gpa, self.types.sliceVars(func.effect_deps));
                },
                .record => |record| {
                    const presences = self.types.getRecordFieldsSlice(record.fields).items(.presence);
                    for (presences) |presence| {
                        try self.binding_scheme_classification_stack.append(self.gpa, presence.typeVar());
                        if (presence.presenceVar()) |presence_var| {
                            try self.binding_scheme_classification_stack.append(self.gpa, presence_var);
                        }
                    }
                    try self.binding_scheme_classification_stack.append(self.gpa, record.ext);
                },
                .record_unbound => |fields_range| {
                    const presences = self.types.getRecordFieldsSlice(fields_range).items(.presence);
                    for (presences) |presence| {
                        try self.binding_scheme_classification_stack.append(self.gpa, presence.typeVar());
                        if (presence.presenceVar()) |presence_var| {
                            try self.binding_scheme_classification_stack.append(self.gpa, presence_var);
                        }
                    }
                },
                .tag_union => |tag_union| {
                    const tag_args = self.types.getTagsSlice(tag_union.tags).items(.args);
                    for (tag_args) |args| {
                        try self.binding_scheme_classification_stack.appendSlice(self.gpa, self.types.sliceVars(args));
                    }
                    try self.binding_scheme_classification_stack.append(self.gpa, tag_union.ext);
                },
            },
        }
    }
    return false;
}

fn publishBindingScheme(self: *Self, root_var: Var) Allocator.Error!void {
    if (try self.typeHasGeneralizedVar(root_var)) {
        try self.markBindingSchemeVar(root_var);
    }
}

/// Instantiate a variable
///
/// * Substituting generalized flex vars with fresh flex vars
/// * Substituting generalized rigid vars with fresh flex vars
///
/// Note that the the rigid var structure will be preserved.
/// E.g. In `a -> a`, all `a` will reference the same new flex var
fn instantiateVar(
    self: *Self,
    var_to_instantiate: Var,
    env: *Env,
    region_behavior: InstantiateRegionBehavior,
) std.mem.Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();

    var instantiate_ctx = Instantiator{
        .store = self.types,
        .idents = self.cir.getIdentStoreConst(),
        .var_map = &self.var_map,

        .current_rank = env.rank(),
        .rigid_behavior = .fresh_flex,
    };
    return self.instantiateVarHelp(var_to_instantiate, &instantiate_ctx, env, region_behavior, false);
}

/// Instantiate a binding explicitly classified as a rank-1 type scheme.
fn instantiateTypeScheme(
    self: *Self,
    var_to_instantiate: Var,
    env: *Env,
    region_behavior: InstantiateRegionBehavior,
) std.mem.Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();
    std.debug.assert(self.isBindingSchemeVar(var_to_instantiate));

    var instantiate_ctx = Instantiator{
        .store = self.types,
        .idents = self.cir.getIdentStoreConst(),
        .var_map = &self.var_map,
        .current_rank = env.rank(),
        .rigid_behavior = .fresh_flex,
    };
    return self.instantiateVarHelp(var_to_instantiate, &instantiate_ctx, env, region_behavior, true);
}

fn instantiateBindingVar(
    self: *Self,
    binding_var: Var,
    env: *Env,
    region_behavior: InstantiateRegionBehavior,
) std.mem.Allocator.Error!Var {
    if (self.isBindingSchemeVar(binding_var)) {
        return self.instantiateTypeScheme(binding_var, env, region_behavior);
    }
    if (self.types.resolveVar(binding_var).desc.rank == .generalized) {
        return self.instantiateVar(binding_var, env, region_behavior);
    }
    self.var_map.clearRetainingCapacity();
    return binding_var;
}

/// Cross-module graph copies are cached templates whose descriptors all carry
/// generalized rank. Every use must therefore receive an independent copy
/// before unification, even when source binding metadata says the value is a
/// monotype. Scheme metadata selects the partial-scheme operation; monotypes
/// use the ordinary imported-template copy.
fn instantiateImportedBindingVar(
    self: *Self,
    imported_var: Var,
    env: *Env,
    region_behavior: InstantiateRegionBehavior,
) std.mem.Allocator.Error!Var {
    if (self.isBindingSchemeVar(imported_var)) {
        return self.instantiateTypeScheme(imported_var, env, region_behavior);
    }
    return self.instantiateVar(imported_var, env, region_behavior);
}

/// You probably are looking for `instantiateVar`.
///
/// Copy/paste a variable. This does NOT respect rank or normal instantiation rules.
fn instantiateVarOrphan(
    self: *Self,
    var_to_instantiate: Var,
    env: *Env,
    rank: Rank,
    region_behavior: InstantiateRegionBehavior,
) std.mem.Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();
    std.debug.assert(@intFromEnum(rank) <= @intFromEnum(env.rank()));
    var instantiate_ctx = Instantiator{
        .store = self.types,
        .idents = self.cir.getIdentStoreConst(),
        .var_map = &self.var_map,
        .current_rank = env.rank(),
        .rigid_behavior = .fresh_rigid,
        .rank_behavior = .ignore_rank,
    };
    return self.instantiateVarHelp(var_to_instantiate, &instantiate_ctx, env, region_behavior, false);
}

/// Like `instantiateVarOrphan`, but rigids in the copy become fresh FLEX
/// vars: the copy is a strictly looser view of the type. Used to seed a
/// branch accumulator from the expected type—the copy carries the
/// annotation's concrete structural facts (e.g. `optional` field kinds) into
/// the branch meet without capturing its rigids, which the branches' own
/// types bind (design.md "Field Kinds (All-Dynamic Optional Fields)").
fn instantiateVarOrphanFlexed(
    self: *Self,
    var_to_instantiate: Var,
    env: *Env,
    region_behavior: InstantiateRegionBehavior,
) std.mem.Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();
    var instantiate_ctx = Instantiator{
        .store = self.types,
        .idents = self.cir.getIdentStoreConst(),
        .var_map = &self.var_map,
        .current_rank = env.rank(),
        .rigid_behavior = .fresh_flex,
        .rank_behavior = .ignore_rank,
    };
    return self.instantiateVarHelp(var_to_instantiate, &instantiate_ctx, env, region_behavior, false);
}

/// Instantiate a variable, substituting any encountered rigids with
/// user-provided variables.
///
/// Based on the provided map, the caller can specifically set specified rigids
/// to be a specific var. This is used when evaluating type annotation.
///
/// If a rigid is is encountered that's not in the provided map, a debug assertion
/// will fail. In production mode, that rigid var will be set as an `.err`
fn instantiateVarWithSubs(
    self: *Self,
    var_to_instantiate: Var,
    subs: *std.AutoHashMapUnmanaged(Ident.Idx, Var),
    env: *Env,
    region_behavior: InstantiateRegionBehavior,
) std.mem.Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();

    var instantiate_ctx = Instantiator{
        .store = self.types,
        .idents = self.cir.getIdentStoreConst(),
        .var_map = &self.var_map,

        .current_rank = env.rank(),
        .rigid_behavior = .{ .substitute_rigids = subs },
    };
    return self.instantiateVarHelp(var_to_instantiate, &instantiate_ctx, env, region_behavior, false);
}

/// Map a requirement's recorded creation relation through an instantiation
/// substitution. The origin names the constraint attached to its receiver, and
/// that attached relation is copied exactly when the receiver is: a receiver
/// the substitution leaves shared keeps its original attached fn var, so the
/// origin fn var must stay original too. Mapping the fn var alone would point
/// the origin at this use's independent callable copy—a relation never
/// attached to the shared receiver—and publication could then never match the
/// origin against the receiver's constraint list to retire the copy.
fn substitutedStructuralOrigin(
    self: *Self,
    origin: StructuralSchemeRequirementOrigin,
    var_map: *const std.AutoHashMap(Var, Var),
) StructuralSchemeRequirementOrigin {
    const receiver_root = self.types.resolveVar(origin.receiver_var).var_;
    const fn_root = self.types.resolveVar(origin.constraint_fn_var).var_;
    const substituted_receiver = var_map.get(receiver_root) orelse return .{
        .receiver_var = receiver_root,
        .constraint_fn_var = fn_root,
    };
    return .{
        .receiver_var = substituted_receiver,
        .constraint_fn_var = var_map.get(fn_root) orelse fn_root,
    };
}

/// Instantiate a variable
fn instantiateVarHelp(
    self: *Self,
    var_to_instantiate: Var,
    instantiator: *Instantiator,
    env: *Env,
    region_behavior: InstantiateRegionBehavior,
    force_type_scheme_root: bool,
) std.mem.Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();

    const nested_function_use = self.pending_nested_function_use;
    self.pending_nested_function_use = null;
    const shape_validation = self.pending_shape_validation_instantiation;
    self.pending_shape_validation_instantiation = false;

    // First, reset state
    instantiator.var_map.clearRetainingCapacity();

    // Then, instantiate the variable with the provided context
    const instantiated_var = if (force_type_scheme_root)
        try instantiator.instantiateTypeScheme(var_to_instantiate)
    else
        try instantiator.instantiateVar(var_to_instantiate);

    // A scheme is the root type plus its explicit pending dispatch
    // requirements. Copy both under this one var_map so generalized variables
    // shared between the root and a requirement remain shared in the copy,
    // while every use receives an independent callable relation.
    var instantiated_requirements: std.ArrayListUnmanaged(InstantiatedSchemeDispatchRequirement) = .empty;
    defer instantiated_requirements.deinit(self.gpa);
    if (self.typeSchemeIndexForRoot(var_to_instantiate)) |scheme_idx| {
        try self.copySchemeDispatchRequirements(
            scheme_idx,
            instantiator,
            shape_validation,
            &instantiated_requirements,
        );
    }

    // If we had to insert any new type variables, ensure that we have
    // corresponding regions for them. This is essential for error reporting.
    const root_instantiated_region = self.regions.get(@enumFromInt(@intFromEnum(var_to_instantiate))).*;
    self.scratch_evidence_pairs.clearRetainingCapacity();
    if (instantiator.var_map.count() > 0) {
        var iterator = instantiator.var_map.iterator();
        while (iterator.next()) |x| {
            // Get the newly created var
            const fresh_var = x.value_ptr.*;

            const fresh_resolved = self.types.resolveVar(fresh_var);

            // A constrained scheme var was copied: remember (scheme var → fresh
            // var) so the whole instantiation can be recorded as static-dispatch
            // evidence below. Rigid copies (annotation-kept rigidity) are
            // included alongside flex copies. The scheme-side constraints' fn
            // vars are paired too: nested evidence (a chosen method target that
            // is itself constrained) is keyed by the instantiated constraint fn
            // var at discharge time, and publication reaches that key through
            // these pairs.
            const fresh_constraints_len = switch (fresh_resolved.desc.content) {
                .flex => |flex| flex.constraints.len(),
                .rigid => |rigid| rigid.constraints.len(),
                .alias, .field_presence, .structure, .err => 0,
            };
            if (fresh_constraints_len > 0) {
                try self.scratch_evidence_pairs.append(self.gpa, .{
                    .old_var = @intFromEnum(x.key_ptr.*),
                    .fresh_var = @intFromEnum(fresh_var),
                });
                const old_resolved = self.types.resolveVar(x.key_ptr.*);
                const old_constraints_range = switch (old_resolved.desc.content) {
                    .flex => |flex| flex.constraints,
                    .rigid => |rigid| rigid.constraints,
                    .alias, .field_presence, .structure, .err => types_mod.StaticDispatchConstraint.SafeList.Range.empty(),
                };
                for (self.types.sliceStaticDispatchConstraints(old_constraints_range)) |old_constraint| {
                    // `var_map` keys are resolved roots (see `Instantiator`).
                    const old_fn_root = self.types.resolveVar(old_constraint.fn_var).var_;
                    const fresh_fn_var = instantiator.var_map.get(old_fn_root) orelse continue;
                    try self.scratch_evidence_pairs.append(self.gpa, .{
                        .old_var = @intFromEnum(old_fn_root),
                        .fresh_var = @intFromEnum(fresh_fn_var),
                    });
                }
            }

            // Register newly instantiated open-literal flex vars on the worklist
            // so the defaulting passes see them. Separately, a fresh flex
            // receiver carrying a non-literal static-dispatch constraint is
            // a per-instantiation dispatcher: record it for the end-of-check
            // constraint fixpoint and as an ambiguity candidate. This hook
            // closes the holes where a polymorphic helper hides an ambiguous
            // dispatch that only manifests at an unpinned call site. We only
            // RECORD here, not enqueue a deferred re-check: the normal
            // constraint solver already validates the receiver once this
            // call's arguments unify, so an extra enqueue would only
            // double-process and shift error attribution.
            if (fresh_resolved.desc.content == .flex) {
                const flex = fresh_resolved.desc.content.flex;
                if (flex.constraints.len() > 0) {
                    // Every constraint copied out of a selected dispatch
                    // target belongs to that edge's derivation chain,
                    // literal conversions included: recursive-dispatch
                    // detection walks exactly this lineage.
                    if (self.evidence_target_site) |target| {
                        try self.recordDispatchDerivations(flex.constraints, target.constraint_fn_var);
                    }
                    const constraints = self.types.sliceStaticDispatchConstraints(flex.constraints);
                    var has_literal_constraint = false;
                    var has_other_constraint = false;
                    for (constraints) |c| {
                        if (self.constraintIsLiteralConversion(c)) {
                            has_literal_constraint = true;
                        } else {
                            has_other_constraint = true;
                        }
                    }
                    if (has_literal_constraint) {
                        try self.recordOpenLiteralVar(fresh_var, constraints, null);
                    }
                    if (has_other_constraint) {
                        try self.registerInstantiatedAttachedDispatch(
                            fresh_var,
                            flex.constraints,
                            self.discarded_binding_rhs_expr orelse self.instantiation_source_expr,
                        );
                    }
                }
            }

            // Add to pool
            try env.var_pool.addVarToRank(fresh_var, fresh_resolved.desc.rank);

            // Set the region
            try self.fillInRegionsThrough(fresh_var);
            switch (region_behavior) {
                .explicit => |region| {
                    self.setRegionAt(fresh_var, region);
                },
                .use_root_instantiated => {
                    self.setRegionAt(fresh_var, root_instantiated_region);
                },
                .use_last_var => {
                    const old_var = x.key_ptr.*;
                    const old_region = self.regions.get(@enumFromInt(@intFromEnum(old_var))).*;
                    self.setRegionAt(fresh_var, old_region);
                },
            }
        }
    }

    // Persist every constrained-scheme edge, including an edge that reused
    // already-shared vars and therefore copied no constrained vars. The
    // checked-module producer still needs the scheme root for that use.
    const value_use_source: ?CIR.Expr.Idx = if (nested_function_use == null and self.evidence_target_site == null)
        if (self.instantiation_source_expr) |source_expr| blk: {
            const tag = self.cir.store.nodes.get(@enumFromInt(@intFromEnum(source_expr))).tag;
            break :blk if (tag == .expr_var or tag == .expr_external_lookup or tag == .expr_required_lookup or tag == .expr_field_access)
                source_expr
            else
                null;
        } else null
    else
        null;
    try self.appendSchemeRequirementEvidencePairs(instantiated_requirements.items);
    try self.canonicalizeSchemeUsePairs(&self.scratch_evidence_pairs);
    const needs_evidence = try self.schemeHasEvidenceParams(var_to_instantiate);
    if (self.scratch_evidence_pairs.items.len > 0 or needs_evidence) {
        if (nested_function_use) |source_expr| {
            try self.cir.recordSchemeUse(
                @intFromEnum(source_expr),
                .nested_function_use,
                0,
                var_to_instantiate,
                self.scratch_evidence_pairs.items,
            );
        } else if (self.evidence_target_site) |target| {
            try self.cir.recordSchemeUse(
                target.node_idx,
                .dispatch_target,
                @intFromEnum(target.constraint_fn_var),
                var_to_instantiate,
                self.scratch_evidence_pairs.items,
            );
        } else if (value_use_source) |source_expr| {
            try self.cir.recordSchemeUse(
                @intFromEnum(source_expr),
                .value_use,
                0,
                var_to_instantiate,
                self.scratch_evidence_pairs.items,
            );
        }
    }
    self.scratch_evidence_pairs.clearRetainingCapacity();

    // Explicit scheme requirements are pending facts of this particular use,
    // not constraints merged onto a shared receiver descriptor. Enqueue every
    // copy independently, register it for the same final compatibility
    // fixpoint and ambiguity judgment as a structurally attached constraint,
    // and propagate an unresolved outer-rank relation into an enclosing scheme.
    const requirement_parent = if (self.evidence_target_site) |target| target.constraint_fn_var else null;
    for (instantiated_requirements.items) |requirement| {
        try self.registerInstantiatedSchemeRequirement(
            requirement,
            self.discarded_binding_rhs_expr orelse self.instantiation_source_expr,
            requirement_parent,
            env,
        );
    }

    // Add the var to the right rank
    try env.var_pool.addVarToRank(instantiated_var, instantiator.current_rank);

    // Assert that we have regions for every type variable
    self.debugAssertArraysInSync();

    // Return the instantiated var
    return instantiated_var;
}

fn schemeHasEvidenceParams(self: *Self, root: Var) std.mem.Allocator.Error!bool {
    var scratch: dispatch_evidence.Scratch = .{};
    defer scratch.deinit(self.gpa);
    var params = std.ArrayListUnmanaged(dispatch_evidence.EvidenceParam).empty;
    defer params.deinit(self.gpa);
    try dispatch_evidence.enumerateEvidenceParams(self.gpa, self.types, root, &scratch, &params);
    return params.items.len != 0;
}

fn recordSharedSchemeUse(
    self: *Self,
    node_idx: u32,
    slot: ModuleEnv.SchemeUseRecord.Slot,
    slot_data: u32,
    scheme_root: Var,
) std.mem.Allocator.Error!void {
    try self.cir.recordSchemeUse(node_idx, slot, slot_data, scheme_root, &.{});
}

// regions //

/// Fill slots in the regions array up to and including the target var
fn fillInRegionsThrough(self: *Self, target_var: Var) Allocator.Error!void {
    const idx = @intFromEnum(target_var);

    if (idx >= self.regions.len()) {
        // Use Check's allocator since regions is owned by Check
        try self.regions.items.ensureTotalCapacity(self.gpa, idx + 1);

        const empty_region = Region.zero();
        while (self.regions.len() <= idx) {
            self.regions.items.appendAssumeCapacity(empty_region);
        }
    }
}

/// Set the region for a var
fn setRegionAt(self: *Self, target_var: Var, new_region: Region) void {
    self.regions.set(@enumFromInt(@intFromEnum(target_var)), new_region);
}

/// Get the region for a var
fn getRegionAt(self: *Self, target_var: Var) Region {
    return self.regions.get(@enumFromInt(@intFromEnum(target_var))).*;
}

// fresh vars //

/// Create fresh flex var
fn fresh(self: *Self, env: *Env, new_region: Region) Allocator.Error!Var {
    return self.freshFromContent(.{ .flex = Flex.init() }, env, new_region);
}

/// Create fresh var with the provided content
fn freshFromContent(self: *Self, content: Content, env: *Env, new_region: Region) Allocator.Error!Var {
    const var_ = try self.types.freshFromContentWithRank(content, env.rank());
    try self.fillInRegionsThrough(var_);
    self.setRegionAt(var_, new_region);
    try env.var_pool.addVarToRank(var_, env.rank());
    return var_;
}

/// Create fresh var with the provided content and an explicit rank.
fn freshFromContentAtRank(
    self: *Self,
    content: Content,
    env: *Env,
    new_region: Region,
    rank: Rank,
) Allocator.Error!Var {
    const var_ = try self.types.freshFromContentWithRank(content, rank);
    try self.fillInRegionsThrough(var_);
    self.setRegionAt(var_, new_region);
    try env.var_pool.addVarToRank(var_, rank);
    return var_;
}

/// Create a bool var
fn freshBool(self: *Self, env: *Env, new_region: Region) Allocator.Error!Var {
    // Use the copied Bool type from the type store (set by copyBuiltinTypes)
    return try self.instantiateVar(self.bool_var, env, .{ .explicit = new_region });
}

/// Create a str var
fn freshStr(self: *Self, env: *Env, new_region: Region) Allocator.Error!Var {
    // Use the copied Str type from the type store (set by copyBuiltinTypes)
    return try self.instantiateVar(self.str_var, env, .{ .explicit = new_region });
}

/// Create a U64 var
fn freshU64(self: *Self, env: *Env, new_region: Region) Allocator.Error!Var {
    // Use the copied U64 type from the type store (set by copyBuiltinTypes)
    return try self.instantiateVar(self.u64_var, env, .{ .explicit = new_region });
}

const BuiltinNominalDecl = union(enum) {
    list,
    box,
    dict,
    set,
    try_type,
    fields,
    field,
    numeral,
    num: CIR.NumKind,
};

const BuiltinParseSpecDecl = enum {
    bool,
    str,
    null,
    list_start,
    list_next,
    list_after_item,
    tuple_start,
    tuple_next,
    tuple_end,
    u8,
    i8,
    u16,
    i16,
    u32,
    i32,
    u64,
    i64,
    u128,
    i128,
    dec,
    f32,
    f64,
    record_start,
    record_field,
    record_after_field,
    tag_union,
};

fn builtinOriginModule(self: *const Self) base.ModuleIdentity.Idx {
    return self.builtin_origin_identity;
}

fn isCheckingBuiltinModuleDirectly(self: *const Self) bool {
    return self.cir.module_role == .builtin;
}

fn builtinNumTypeIdent(self: *const Self, num_kind: CIR.NumKind) Ident.Idx {
    return switch (num_kind) {
        .u8 => self.cir.idents.u8_type,
        .i8 => self.cir.idents.i8_type,
        .u16 => self.cir.idents.u16_type,
        .i16 => self.cir.idents.i16_type,
        .u32 => self.cir.idents.u32_type,
        .i32 => self.cir.idents.i32_type,
        .u64 => self.cir.idents.u64_type,
        .i64 => self.cir.idents.i64_type,
        .u128 => self.cir.idents.u128_type,
        .i128 => self.cir.idents.i128_type,
        .f32 => self.cir.idents.f32_type,
        .f64 => self.cir.idents.f64_type,
        .dec => self.cir.idents.dec_type,
        .num_unbound, .int_unbound => unreachable,
    };
}

fn builtinNumStmtFromIndices(indices: CIR.BuiltinIndices, num_kind: CIR.NumKind) CIR.Statement.Idx {
    inline for (CIR.builtin_type_specs) |spec| {
        if (spec.num_kind == num_kind) return @field(indices, spec.type_field);
    }
    unreachable;
}

fn builtinNominalIdent(self: *const Self, decl: BuiltinNominalDecl) Ident.Idx {
    return switch (decl) {
        .list => self.cir.idents.builtin_list,
        .box => self.cir.idents.builtin_box,
        .dict => self.cir.idents.builtin_dict,
        .set => self.cir.idents.builtin_set,
        .try_type => self.cir.idents.builtin_try,
        .fields => self.cir.idents.builtin_encoding_field_names,
        .field => self.cir.idents.builtin_encoding_field_name,
        .numeral => self.cir.idents.builtin_numeral,
        .num => |num_kind| self.builtinNumTypeIdent(num_kind),
    };
}

fn builtinNominalLabel(decl: BuiltinNominalDecl) []const u8 {
    return switch (decl) {
        .list => "List",
        .box => "Box",
        .dict => "Dict",
        .set => "Set",
        .try_type => "Try",
        .fields => "Encoding.FieldName.FieldNames",
        .field => "Encoding.FieldName",
        .numeral => "Num.Numeral",
        .num => |num_kind| switch (num_kind) {
            .u8 => "Num.U8",
            .i8 => "Num.I8",
            .u16 => "Num.U16",
            .i16 => "Num.I16",
            .u32 => "Num.U32",
            .i32 => "Num.I32",
            .u64 => "Num.U64",
            .i64 => "Num.I64",
            .u128 => "Num.U128",
            .i128 => "Num.I128",
            .f32 => "Num.F32",
            .f64 => "Num.F64",
            .dec => "Num.Dec",
            .num_unbound, .int_unbound => unreachable,
        },
    };
}

const SourceDeclKind = enum {
    alias,
    nominal,
};

fn debugAssertSourceDeclKind(self: *const Self, source_decl: u32, kind: SourceDeclKind) void {
    debugAssertSourceDeclKindInEnv(self.cir, source_decl, kind);
}

fn debugAssertSourceDeclKindInEnv(env: *const ModuleEnv, source_decl: u32, kind: SourceDeclKind) void {
    if (builtin.mode != .Debug) return;

    if (source_decl >= env.store.nodes.len()) {
        std.debug.panic("type checker invariant violated: source declaration {} is outside node store", .{source_decl});
    }

    const node = env.store.nodes.get(@enumFromInt(source_decl));
    const ok = switch (kind) {
        .alias => node.tag == .statement_alias_decl,
        .nominal => node.tag == .statement_nominal_decl,
    };
    if (!ok) {
        std.debug.panic("type checker invariant violated: source declaration {} has tag {}, expected {s}", .{
            source_decl,
            node.tag,
            @tagName(kind),
        });
    }
}

fn sourceDeclForBuiltinNominal(self: *const Self, decl: BuiltinNominalDecl) u32 {
    if (!self.isCheckingBuiltinModuleDirectly() and self.builtin_ctx.builtin_indices != null) {
        const indices = self.builtin_ctx.builtin_indices.?;
        const stmt_idx = switch (decl) {
            .list => indices.list_type,
            .box => indices.box_type,
            .dict => indices.dict_type,
            .set => indices.set_type,
            .try_type => indices.try_type,
            .fields => indices.fields_type,
            .field => indices.field_type,
            .numeral => indices.numeral_type,
            .num => |num_kind| builtinNumStmtFromIndices(indices, num_kind),
        };
        const owner_env = self.builtin_ctx.builtin_module orelse self.cir;
        debugAssertSourceDeclKindInEnv(owner_env, @intFromEnum(stmt_idx), .nominal);
        return @intFromEnum(stmt_idx);
    }

    if (!self.isCheckingBuiltinModuleDirectly() and self.builtin_ctx.builtin_module != null) {
        if (builtin.mode == .Debug) {
            std.debug.panic("type checker invariant violated: builtin module env present without builtin indices", .{});
        }
        unreachable;
    }

    const stmt_idx = self.findLocalTypeDeclByName(self.builtinNominalIdent(decl)) orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic("type checker invariant violated: Builtin.{s} declaration not found while checking Builtin", .{builtinNominalLabel(decl)});
        }
        unreachable;
    };
    self.debugAssertSourceDeclKind(@intFromEnum(stmt_idx), .nominal);
    return @intFromEnum(stmt_idx);
}

fn sourceDeclForBuiltinParseSpec(self: *const Self, decl: BuiltinParseSpecDecl) u32 {
    if (!self.isCheckingBuiltinModuleDirectly() and self.builtin_ctx.builtin_indices != null) {
        const indices = self.builtin_ctx.builtin_indices.?;
        const stmt_idx = switch (decl) {
            .tag_union => indices.parse_tag_union_spec_type,
            .bool, .str, .null, .list_start, .list_next, .list_after_item, .tuple_start, .tuple_next, .tuple_end, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .dec, .f32, .f64, .record_start, .record_field, .record_after_field => {
                if (builtin.mode == .Debug) {
                    std.debug.panic("type checker invariant violated: this parse method does not have a builtin parse spec declaration", .{});
                }
                unreachable;
            },
        };
        const owner_env = self.builtin_ctx.builtin_module orelse self.cir;
        debugAssertSourceDeclKindInEnv(owner_env, @intFromEnum(stmt_idx), .nominal);
        return @intFromEnum(stmt_idx);
    }

    if (!self.isCheckingBuiltinModuleDirectly() and self.builtin_ctx.builtin_module != null) {
        if (builtin.mode == .Debug) {
            std.debug.panic("type checker invariant violated: builtin module env present without builtin indices", .{});
        }
        unreachable;
    }

    const ident = switch (decl) {
        .tag_union => self.cir.idents.builtin_encoding_parse_tag_union_spec,
        .bool, .str, .null, .list_start, .list_next, .list_after_item, .tuple_start, .tuple_next, .tuple_end, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .dec, .f32, .f64, .record_start, .record_field, .record_after_field => {
            if (builtin.mode == .Debug) {
                std.debug.panic("type checker invariant violated: this parse method does not have a builtin parse spec declaration", .{});
            }
            unreachable;
        },
    };
    const stmt_idx = self.findLocalTypeDeclByName(ident) orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic("type checker invariant violated: Builtin parse spec declaration not found while checking Builtin", .{});
        }
        unreachable;
    };
    self.debugAssertSourceDeclKind(@intFromEnum(stmt_idx), .nominal);
    return @intFromEnum(stmt_idx);
}

/// Create a nominal List type with the given element type
fn mkListContent(self: *Self, elem_var: Var) Allocator.Error!Content {
    const trace = tracy.trace(@src());
    defer trace.end();

    const list_ident = types_mod.TypeIdent{
        .ident_idx = self.cir.idents.list,
    };

    // The application carries only identity + the element arg; List's backing
    // ([ProvidedByCompiler]) lives in the declaration table.
    const type_args = [_]Var{elem_var};

    return try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
        list_ident,
        &type_args,
        self.builtinOriginModule(),
        self.sourceDeclForBuiltinNominal(.list),
        false, // List is nominal (not opaque)
        true,
    );
}

/// Instantiate the builtin Iter type declaration and bind its item parameter.
fn mkIterVar(self: *Self, item_var: Var, env: *Env, region: Region) Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();

    const iter_decl_var = if (self.builtin_ctx.builtin_module) |builtin_env| blk: {
        const indices = self.builtin_ctx.builtin_indices orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("type checker invariant violated: builtin module env present without builtin indices", .{});
            }
            unreachable;
        };
        const copied_var = try self.copyVar(ModuleEnv.varFrom(indices.iter_type), builtin_env, region);
        break :blk copied_var;
    } else blk: {
        const iter_stmt_idx = self.findLocalTypeDeclByName(self.cir.idents.builtin_iter) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("type checker invariant violated: Builtin.Iter declaration not found while checking Builtin", .{});
            }
            unreachable;
        };
        break :blk ModuleEnv.varFrom(iter_stmt_idx);
    };

    const iter_var = try self.instantiateVar(iter_decl_var, env, .{ .explicit = region });
    const iter_content = self.types.resolveVar(iter_var).desc.content;
    const nominal = iter_content.unwrapNominalType() orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic("type checker invariant violated: Builtin.Iter declaration did not instantiate to a nominal type", .{});
        }
        unreachable;
    };
    const args = self.types.sliceNominalArgs(nominal);
    if (args.len != 1) {
        if (builtin.mode == .Debug) {
            std.debug.panic("type checker invariant violated: Builtin.Iter expected one type argument, found {d}", .{args.len});
        }
        unreachable;
    }

    _ = try self.unify(args[0], item_var, env);
    return iter_var;
}

/// Instantiate the builtin Num.Range type declaration and bind its numeric parameter.
fn mkRangeVar(self: *Self, num_var: Var, env: *Env, region: Region) Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();

    const range_decl_var = if (self.builtin_ctx.builtin_module) |builtin_env| blk: {
        const indices = self.builtin_ctx.builtin_indices orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("type checker invariant violated: builtin module env present without builtin indices", .{});
            }
            unreachable;
        };
        break :blk try self.copyVar(ModuleEnv.varFrom(indices.range_type), builtin_env, region);
    } else blk: {
        const range_stmt_idx = self.findLocalTypeDeclByName(self.cir.idents.builtin_range) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("type checker invariant violated: Builtin.Num.Range declaration not found while checking Builtin", .{});
            }
            unreachable;
        };
        break :blk ModuleEnv.varFrom(range_stmt_idx);
    };

    const range_var = try self.instantiateVar(range_decl_var, env, .{ .explicit = region });
    const range_content = self.types.resolveVar(range_var).desc.content;
    const nominal = range_content.unwrapNominalType() orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic("type checker invariant violated: Builtin.Num.Range did not instantiate to a nominal type", .{});
        }
        unreachable;
    };
    const args = self.types.sliceNominalArgs(nominal);
    if (args.len != 1) {
        if (builtin.mode == .Debug) {
            std.debug.panic("type checker invariant violated: Builtin.Num.Range expected one type argument, found {d}", .{args.len});
        }
        unreachable;
    }

    _ = try self.unify(args[0], num_var, env);
    return range_var;
}

const IteratorStepBuild = struct {
    content: Content,
    topology: ModuleEnv.IteratorStepTopology,
};

fn mkIteratorStepContent(self: *Self, item_var: Var, iter_var: Var, env: *Env) Allocator.Error!IteratorStepBuild {
    const trace = tracy.trace(@src());
    defer trace.end();

    const item_ident = try @constCast(self.cir).insertIdent(base.Ident.for_text("item"));
    const rest_ident = try @constCast(self.cir).insertIdent(base.Ident.for_text("rest"));
    const record_ext = try self.freshFromContent(.{ .structure = .empty_record }, env, Region.zero());
    const record_fields = [_]types_mod.RecordField{
        .{ .name = item_ident, .presence = .required(item_var) },
        .{ .name = rest_ident, .presence = .required(iter_var) },
    };
    const record_fields_range = try self.types.appendRecordFields(&record_fields);
    const payload_record = try self.freshFromContent(.{ .structure = .{ .record = .{
        .fields = record_fields_range,
        .ext = record_ext,
    } } }, env, Region.zero());

    const skip_record_ext = try self.freshFromContent(.{ .structure = .empty_record }, env, Region.zero());
    const skip_record_fields = [_]types_mod.RecordField{
        .{ .name = rest_ident, .presence = .required(iter_var) },
    };
    const skip_record_fields_range = try self.types.appendRecordFields(&skip_record_fields);
    const skip_payload_record = try self.freshFromContent(.{ .structure = .{ .record = .{
        .fields = skip_record_fields_range,
        .ext = skip_record_ext,
    } } }, env, Region.zero());

    const done_ident = try @constCast(self.cir).insertIdent(base.Ident.for_text("Done"));
    const one_ident = try @constCast(self.cir).insertIdent(base.Ident.for_text("One"));
    const skip_ident = try @constCast(self.cir).insertIdent(base.Ident.for_text("Skip"));

    const tags = [_]types_mod.Tag{
        try self.types.mkTag(done_ident, &.{}),
        try self.types.mkTag(one_ident, &.{payload_record}),
        try self.types.mkTag(skip_ident, &.{skip_payload_record}),
    };
    const ext_var = try self.freshFromContent(.{ .structure = .empty_tag_union }, env, Region.zero());
    return .{
        .content = try self.types.mkTagUnion(&tags, ext_var),
        .topology = .{
            .done_tag_ident = @bitCast(done_ident),
            .one_tag_ident = @bitCast(one_ident),
            .skip_tag_ident = @bitCast(skip_ident),
            .item_field_ident = @bitCast(item_ident),
            .rest_field_ident = @bitCast(rest_ident),
            .one_payload_var = @intFromEnum(payload_record),
            .skip_payload_var = @intFromEnum(skip_payload_record),
        },
    };
}

/// Create a nominal number type content (e.g., U8, I32, Dec)
/// Number types are defined in Builtin.roc nested inside Num module: Num.U8 :: [].{...}
/// They have no type parameters and their backing is the empty tag union []
fn mkNumberTypeContent(self: *Self, num_kind: CIR.NumKind) Allocator.Error!Content {
    const trace = tracy.trace(@src());
    defer trace.end();

    const type_ident = types_mod.TypeIdent{
        .ident_idx = self.builtinNumTypeIdent(num_kind),
    };

    // Number types have no type arguments; their backing lives in the
    // declaration table.
    const no_type_args: []const Var = &.{};

    return try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
        type_ident,
        no_type_args,
        self.builtinOriginModule(),
        self.sourceDeclForBuiltinNominal(.{ .num = num_kind }),
        true, // Number types are opaque (defined with ::)
        true,
    );
}

fn builtinNumKindFromTypeName(self: *const Self, type_name: Ident.Idx) ?CIR.NumKind {
    if (type_name.eql(self.cir.idents.u8) or type_name.eql(self.cir.idents.u8_type)) return .u8;
    if (type_name.eql(self.cir.idents.i8) or type_name.eql(self.cir.idents.i8_type)) return .i8;
    if (type_name.eql(self.cir.idents.u16) or type_name.eql(self.cir.idents.u16_type)) return .u16;
    if (type_name.eql(self.cir.idents.i16) or type_name.eql(self.cir.idents.i16_type)) return .i16;
    if (type_name.eql(self.cir.idents.u32) or type_name.eql(self.cir.idents.u32_type)) return .u32;
    if (type_name.eql(self.cir.idents.i32) or type_name.eql(self.cir.idents.i32_type)) return .i32;
    if (type_name.eql(self.cir.idents.u64) or type_name.eql(self.cir.idents.u64_type)) return .u64;
    if (type_name.eql(self.cir.idents.i64) or type_name.eql(self.cir.idents.i64_type)) return .i64;
    if (type_name.eql(self.cir.idents.u128) or type_name.eql(self.cir.idents.u128_type)) return .u128;
    if (type_name.eql(self.cir.idents.i128) or type_name.eql(self.cir.idents.i128_type)) return .i128;
    if (type_name.eql(self.cir.idents.f32) or type_name.eql(self.cir.idents.f32_type)) return .f32;
    if (type_name.eql(self.cir.idents.f64) or type_name.eql(self.cir.idents.f64_type)) return .f64;
    if (type_name.eql(self.cir.idents.dec) or type_name.eql(self.cir.idents.dec_type)) return .dec;
    return null;
}

fn builtinNominalDeclForSourceDecl(source_env: *const ModuleEnv, source_decl: ?u32) ?BuiltinNominalDecl {
    if (source_env.module_role != .builtin) return null;
    const raw_decl = source_decl orelse return null;
    if (raw_decl >= source_env.store.nodes.len()) return null;

    const node: CIR.Node.Idx = @enumFromInt(raw_decl);
    const node_tag = source_env.store.nodes.get(node).tag;
    if (node_tag != .statement_alias_decl and node_tag != .statement_nominal_decl) return null;
    const statement_idx: CIR.Statement.Idx = @enumFromInt(raw_decl);
    const header_idx = switch (source_env.store.getStatement(statement_idx)) {
        .s_alias_decl => |alias| alias.header,
        .s_nominal_decl => |nominal| nominal.header,
        .s_decl,
        .s_var,
        .s_var_uninitialized,
        .s_reassign,
        .s_crash,
        .s_dbg,
        .s_expr,
        .s_expect,
        .s_for,
        .s_while,
        .s_infinite_loop,
        .s_breakable_loop,
        .s_break,
        .s_return,
        .s_import,
        .s_where_alias_decl,
        .s_type_anno,
        .s_type_var_alias,
        .s_runtime_error,
        => return null,
    };
    const header = source_env.store.getTypeHeader(header_idx);
    return builtinNominalDeclForIdentInEnv(source_env, header.name);
}

fn builtinNominalDeclForIdentInEnv(source_env: *const ModuleEnv, type_ident: Ident.Idx) ?BuiltinNominalDecl {
    const common = source_env.idents;
    if (type_ident.eql(common.list) or type_ident.eql(common.builtin_list)) return .list;
    if (type_ident.eql(common.box) or type_ident.eql(common.builtin_box)) return .box;
    if (type_ident.eql(common.dict) or type_ident.eql(common.builtin_dict)) return .dict;
    if (type_ident.eql(common.set) or type_ident.eql(common.builtin_set)) return .set;
    if (type_ident.eql(common.@"try") or type_ident.eql(common.builtin_try)) return .try_type;
    if (type_ident.eql(common.builtin_encoding_field_names)) return .fields;
    if (type_ident.eql(common.builtin_encoding_field_name)) return .field;
    if (type_ident.eql(common.builtin_numeral)) return .numeral;
    if (type_ident.eql(common.u8) or type_ident.eql(common.u8_type)) return .{ .num = .u8 };
    if (type_ident.eql(common.i8) or type_ident.eql(common.i8_type)) return .{ .num = .i8 };
    if (type_ident.eql(common.u16) or type_ident.eql(common.u16_type)) return .{ .num = .u16 };
    if (type_ident.eql(common.i16) or type_ident.eql(common.i16_type)) return .{ .num = .i16 };
    if (type_ident.eql(common.u32) or type_ident.eql(common.u32_type)) return .{ .num = .u32 };
    if (type_ident.eql(common.i32) or type_ident.eql(common.i32_type)) return .{ .num = .i32 };
    if (type_ident.eql(common.u64) or type_ident.eql(common.u64_type)) return .{ .num = .u64 };
    if (type_ident.eql(common.i64) or type_ident.eql(common.i64_type)) return .{ .num = .i64 };
    if (type_ident.eql(common.u128) or type_ident.eql(common.u128_type)) return .{ .num = .u128 };
    if (type_ident.eql(common.i128) or type_ident.eql(common.i128_type)) return .{ .num = .i128 };
    if (type_ident.eql(common.f32) or type_ident.eql(common.f32_type)) return .{ .num = .f32 };
    if (type_ident.eql(common.f64) or type_ident.eql(common.f64_type)) return .{ .num = .f64 };
    if (type_ident.eql(common.dec) or type_ident.eql(common.dec_type)) return .{ .num = .dec };
    return null;
}

fn builtinNominalDeclForBuiltinSourceDecl(self: *const Self, source_decl: ?u32) ?BuiltinNominalDecl {
    const raw_decl = source_decl orelse return null;

    if (self.cir.module_role == .builtin) {
        return builtinNominalDeclForSourceDecl(self.cir, raw_decl);
    }

    const indices = self.builtin_ctx.builtin_indices orelse return null;
    if (raw_decl == @intFromEnum(indices.list_type)) return .list;
    if (raw_decl == @intFromEnum(indices.box_type)) return .box;
    if (raw_decl == @intFromEnum(indices.dict_type)) return .dict;
    if (raw_decl == @intFromEnum(indices.set_type)) return .set;
    if (raw_decl == @intFromEnum(indices.try_type)) return .try_type;
    if (raw_decl == @intFromEnum(indices.fields_type)) return .fields;
    if (raw_decl == @intFromEnum(indices.field_type)) return .field;
    if (raw_decl == @intFromEnum(indices.numeral_type)) return .numeral;
    if (raw_decl == @intFromEnum(indices.u8_type)) return .{ .num = .u8 };
    if (raw_decl == @intFromEnum(indices.i8_type)) return .{ .num = .i8 };
    if (raw_decl == @intFromEnum(indices.u16_type)) return .{ .num = .u16 };
    if (raw_decl == @intFromEnum(indices.i16_type)) return .{ .num = .i16 };
    if (raw_decl == @intFromEnum(indices.u32_type)) return .{ .num = .u32 };
    if (raw_decl == @intFromEnum(indices.i32_type)) return .{ .num = .i32 };
    if (raw_decl == @intFromEnum(indices.u64_type)) return .{ .num = .u64 };
    if (raw_decl == @intFromEnum(indices.i64_type)) return .{ .num = .i64 };
    if (raw_decl == @intFromEnum(indices.u128_type)) return .{ .num = .u128 };
    if (raw_decl == @intFromEnum(indices.i128_type)) return .{ .num = .i128 };
    if (raw_decl == @intFromEnum(indices.f32_type)) return .{ .num = .f32 };
    if (raw_decl == @intFromEnum(indices.f64_type)) return .{ .num = .f64 };
    if (raw_decl == @intFromEnum(indices.dec_type)) return .{ .num = .dec };
    return null;
}

fn builtinNumKindFromBuiltinSourceDecl(self: *const Self, source_decl: ?u32) ?CIR.NumKind {
    return switch (self.builtinNominalDeclForBuiltinSourceDecl(source_decl) orelse return null) {
        .num => |num_kind| num_kind,
        .list, .box, .dict, .set, .try_type, .fields, .field, .numeral => null,
    };
}

fn mkBuiltinNumberTypeContentFromKind(
    self: *Self,
    num_kind: CIR.NumKind,
) Allocator.Error!Content {
    return switch (num_kind) {
        .num_unbound, .int_unbound => unreachable,
        .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => try self.mkNumberTypeContent(num_kind),
    };
}

fn findLocalTypeDeclByName(self: *const Self, type_name: Ident.Idx) ?CIR.Statement.Idx {
    if (self.findLocalTypeDeclByNameInSpan(self.cir.type_decls, type_name)) |stmt_idx| return stmt_idx;
    if (self.findLocalTypeDeclByNameInSpan(self.cir.forward_type_decls, type_name)) |stmt_idx| return stmt_idx;
    if (self.findLocalTypeDeclByNameInSpan(self.cir.all_statements, type_name)) |stmt_idx| return stmt_idx;
    if (self.findLocalTypeDeclByNameInSpan(self.cir.builtin_statements, type_name)) |stmt_idx| return stmt_idx;
    return null;
}

fn findLocalTypeDeclByNameInSpan(
    self: *const Self,
    span: CIR.Statement.Span,
    type_name: Ident.Idx,
) ?CIR.Statement.Idx {
    const stmts = self.cir.store.sliceStatements(span);
    for (stmts) |stmt_idx| {
        const stmt = self.cir.store.getStatement(stmt_idx);
        const header_idx = switch (stmt) {
            .s_alias_decl => |alias| alias.header,
            .s_nominal_decl => |nominal| nominal.header,
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => continue,
        };

        const header = self.cir.store.getTypeHeader(header_idx);
        if (header.name.eql(type_name) or header.relative_name.eql(type_name)) return stmt_idx;
    }
    return null;
}

fn unifyLiteralWithSuffixTarget(
    self: *Self,
    flex_var: Var,
    suffix_target: ModuleEnv.NumericSuffixTarget,
    region: Region,
    env: *Env,
) Allocator.Error!void {
    switch (suffix_target.target()) {
        .builtin => |num_kind| {
            try self.unifyWith(flex_var, try self.mkBuiltinNumberTypeContentFromKind(num_kind), env);
        },
        .local => |stmt_idx| {
            const local_decl_var = ModuleEnv.varFrom(stmt_idx);
            const resolved_var = if (self.isForClauseAliasStatement(stmt_idx))
                local_decl_var
            else
                try self.instantiateVar(local_decl_var, env, .{ .explicit = region });

            _ = try self.unify(flex_var, resolved_var, env);
        },
        .external => |external| {
            if (try self.resolveVarFromExternal(external.import_idx, external.target_node_idx)) |ext_ref| {
                const instantiated_var = try self.instantiateVar(
                    ext_ref.local_var,
                    env,
                    .{ .explicit = region },
                );
                _ = try self.unify(flex_var, instantiated_var, env);
            } else {
                try self.markErroneous(flex_var);
            }
        },
        .invalid => {
            try self.markErroneous(flex_var);
        },
    }
}

fn explicitTypeSuffixVar(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    expr_region: Region,
    env: *Env,
) Allocator.Error!?Var {
    const suffix_target = self.cir.numericSuffixTargetForNode(ModuleEnv.nodeIdxFrom(expr_idx)) orelse return null;
    const suffix_var = try self.fresh(env, expr_region);
    try self.unifyLiteralWithSuffixTarget(suffix_var, suffix_target, expr_region, env);
    return suffix_var;
}

fn recordOpenLiteralVar(
    self: *Self,
    literal_var: Var,
    constraints: []const StaticDispatchConstraint,
    source_node: ?CIR.Node.Idx,
) Allocator.Error!void {
    var has_literal = false;
    for (constraints) |constraint| {
        if (self.constraintIsLiteralConversion(constraint)) {
            has_literal = true;
        }
        // Exact-value range validation needs the numeral payload, which only a
        // `from_literal` origin carries—a `where`-clause hook has no literal
        // value to validate.
        switch (constraint.origin) {
            .from_literal => |lit| switch (lit) {
                .numeral => try self.open_numeral_literals.append(self.gpa, .{
                    .var_ = literal_var,
                    .constraint = constraint,
                    .source_node = source_node,
                }),
                .quote, .interpolation => {},
            },
            .desugared_binop, .desugared_unaryop, .method_call, .where_clause => {},
        }
    }

    if (has_literal) {
        try self.open_literal_vars.append(self.gpa, literal_var);
    }
}

fn contentConstraintRange(content: Content) ?StaticDispatchConstraint.SafeList.Range {
    return switch (content) {
        .flex => |flex| flex.constraints,
        .rigid => |rigid| rigid.constraints,
        .alias, .field_presence, .structure, .err => null,
    };
}

/// Create a flex variable with a from_numeral constraint for numeric literals.
/// This constraint will be checked during deferred constraint checking to validate
/// that the numeric literal can be converted to the unified type.
/// Returns the flex var which has the constraint attached, and the dispatcher var
/// (first arg of from_numeral) is unified with the flex var so they share the same name.
fn mkFlexWithFromNumeralConstraint(
    self: *Self,
    source_node: ?CIR.Node.Idx,
    num_literal_info: types_mod.NumeralInfo,
    env: *Env,
) Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();

    const from_numeral_ident = self.cir.idents.from_numeral;

    // Create the flex var first - this represents the target type `a`
    const flex_rank = env.rank();
    const flex_var = try self.freshFromContentAtRank(.{ .flex = Flex.init() }, env, num_literal_info.region, flex_rank);

    // Create the argument type: Numeral (from Builtin.Num.Numeral)
    // For from_numeral, the actual method signature is: Numeral -> Try(a, [InvalidNumeral(Str)])
    const numeral_content = try self.mkNumeralContent();
    const arg_var = try self.freshFromContent(numeral_content, env, num_literal_info.region);

    // Create the error type: [InvalidNumeral(Str)] (closed tag union).
    // Use a fresh Str instance, not the shared `self.str_var`: this Str lands in
    // the literal's deferred from_numeral constraint, and embedding the module's
    // one canonical Str var here would make every numeric literal's constraint
    // alias it. A dispatch failure poisons its operands to `.err`, so a shared Str
    // would carry that `.err` into every other literal's constraint and silently
    // suppress their own (independent) dispatch errors.
    const str_var = try self.freshStr(env, num_literal_info.region);
    const invalid_numeral_tag_ident = try @constCast(self.cir).insertIdent(
        base.Ident.for_text("InvalidNumeral"),
    );
    const invalid_numeral_tag = try self.types.mkTag(
        invalid_numeral_tag_ident,
        &.{str_var},
    );
    // Use empty_tag_union as extension to create a closed tag union [InvalidNumeral(Str)]
    const err_ext_var = try self.freshFromContent(.{ .structure = .empty_tag_union }, env, num_literal_info.region);
    const err_type = try self.types.mkTagUnion(&.{invalid_numeral_tag}, err_ext_var);
    const err_var = try self.freshFromContent(err_type, env, num_literal_info.region);

    // Create Try(flex_var, err_var) as the return type
    // Try is a nominal type with two type args: the success type and the error type
    const try_type_content = try self.mkTryContent(flex_var, err_var);
    const ret_var = try self.freshFromContent(try_type_content, env, num_literal_info.region);

    const func_content = types_mod.Content{
        .structure = types_mod.FlatType{
            .fn_unbound = types_mod.Func{
                .args = try self.types.appendVars(&.{arg_var}),
                .ret = ret_var,
            },
        },
    };
    const fn_var = try self.freshFromContent(func_content, env, num_literal_info.region);

    // Create the constraint with numeric literal info
    const constraint = types_mod.StaticDispatchConstraint{
        .fn_name = from_numeral_ident,
        .fn_var = fn_var,
        .origin = .{ .from_literal = .{ .numeral = num_literal_info } },
    };
    if (source_node != null) try self.recordCurrentExpectDispatchWatcher(fn_var);

    // Store it in the types store
    const constraint_range = try self.types.appendStaticDispatchConstraints(&.{constraint});

    // Update the flex var to have the constraint attached
    const flex_content = types_mod.Content{
        .flex = types_mod.Flex{
            .name = null,
            .constraints = constraint_range,
        },
    };
    try self.unifyWith(flex_var, flex_content, env);

    if (source_node) |node_idx| {
        try self.cir.recordNumeralDispatchPlan(node_idx, flex_var, fn_var);
    }
    try self.recordOpenLiteralVar(flex_var, &.{constraint}, source_node);

    return flex_var;
}

/// Create a flex variable with a from_quote constraint for string literals.
/// The constraint's function type is `Str -> Try(a, [BadQuotedBytes(Str)])`,
/// where the Str is the literal's content after escape processing.
fn mkFlexWithFromQuoteConstraint(
    self: *Self,
    source_node: ?CIR.Node.Idx,
    region: Region,
    env: *Env,
) Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();

    const from_quote_ident = self.cir.idents.from_quote;

    // Create the flex var first - this represents the target type `a`
    const flex_rank = env.rank();
    const flex_var = try self.freshFromContentAtRank(.{ .flex = Flex.init() }, env, region, flex_rank);

    // Create the argument type: Str
    const arg_var = try self.freshStr(env, region);

    // Create the error type: [BadQuotedBytes(Str)] (closed tag union).
    // Use a fresh Str instance, not the shared `self.str_var`: this Str lands in
    // the literal's deferred from_quote constraint, and embedding the module's one
    // canonical Str var here would make every string literal's constraint alias
    // it. A dispatch failure poisons its operands to `.err`, so a shared Str would
    // carry that `.err` into every other literal's constraint and silently
    // suppress their own (independent) dispatch errors.
    const str_var = try self.freshStr(env, region);
    const bad_quoted_bytes_tag_ident = try @constCast(self.cir).insertIdent(
        base.Ident.for_text("BadQuotedBytes"),
    );
    const bad_quoted_bytes_tag = try self.types.mkTag(
        bad_quoted_bytes_tag_ident,
        &.{str_var},
    );
    const err_ext_var = try self.freshFromContent(.{ .structure = .empty_tag_union }, env, region);
    const err_type = try self.types.mkTagUnion(&.{bad_quoted_bytes_tag}, err_ext_var);
    const err_var = try self.freshFromContent(err_type, env, region);

    // Create Try(flex_var, err_var) as the return type
    const try_type_content = try self.mkTryContent(flex_var, err_var);
    const ret_var = try self.freshFromContent(try_type_content, env, region);

    const func_content = types_mod.Content{
        .structure = types_mod.FlatType{
            .fn_unbound = types_mod.Func{
                .args = try self.types.appendVars(&.{arg_var}),
                .ret = ret_var,
            },
        },
    };
    const fn_var = try self.freshFromContent(func_content, env, region);
    if (source_node) |node_idx| {
        try self.cir.recordQuoteDispatchPlan(node_idx, flex_var, fn_var);
    }

    const constraint = types_mod.StaticDispatchConstraint{
        .fn_name = from_quote_ident,
        .fn_var = fn_var,
        .origin = .{ .from_literal = .quote },
    };
    if (source_node != null) try self.recordCurrentExpectDispatchWatcher(fn_var);

    const constraint_range = try self.types.appendStaticDispatchConstraints(&.{constraint});

    const flex_content = types_mod.Content{
        .flex = types_mod.Flex{
            .name = null,
            .constraints = constraint_range,
        },
    };
    try self.unifyWith(flex_var, flex_content, env);
    try self.recordOpenLiteralVar(flex_var, &.{constraint}, source_node);

    return flex_var;
}

fn recordedNumeralLiteralForNode(self: *const Self, node_idx: CIR.Node.Idx) ModuleEnv.NumeralLiteral {
    return self.cir.numeralLiteralForNode(node_idx) orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic("missing recorded exact numeral for source node {}", .{@intFromEnum(node_idx)});
        }
        unreachable;
    };
}

fn exactNumeralInfoForLiteral(self: *const Self, literal: ModuleEnv.NumeralLiteral, region: Region) Allocator.Error!types_mod.NumeralInfo {
    const exact = self.cir.exactNumeral(literal);
    // A literal whose digits were never recorded (too huge to materialize as
    // a `Num.Numeral`, e.g. `3e6000000000`) fits no builtin type: its exact
    // value is unknowable, so every concrete candidate must refute it rather
    // than silently reading the empty digit buffers as zero.
    const fit_set = if (literal.isMaterialized())
        try exact_numeral.computeFitSet(self.gpa, exact)
    else
        exact_numeral.FitSet.initEmpty();
    return types_mod.NumeralInfo.fromExact(exact, fit_set, literal.isMaterialized(), region);
}

const NumeralOccurrence = enum { expression, pattern };

/// Check one exact numeric source occurrence. Exact digits and the optional
/// resolved suffix target are producer-owned node data shared by expressions
/// and patterns; patterns add only the equality requirement needed for matching.
fn checkNumeralLiteral(
    self: *Self,
    node_idx: CIR.Node.Idx,
    occurrence_var: Var,
    region: Region,
    comptime occurrence: NumeralOccurrence,
    env: *Env,
) Allocator.Error!void {
    const suffix_target = self.cir.numericSuffixTargetForNode(node_idx);
    const literal = self.recordedNumeralLiteralForNode(node_idx);
    var num_literal_info = try self.exactNumeralInfoForLiteral(literal, region);
    const is_int_unbound = switch (occurrence) {
        .expression => blk: {
            const expr_idx: CIR.Expr.Idx = @enumFromInt(@intFromEnum(node_idx));
            const expr = self.cir.store.getExpr(expr_idx);
            break :blk expr == .e_num and expr.e_num.kind == .int_unbound;
        },
        .pattern => blk: {
            const pat_idx: CIR.Pattern.Idx = @enumFromInt(@intFromEnum(node_idx));
            const pat = self.cir.store.getPattern(pat_idx);
            break :blk pat == .num_literal and pat.num_literal.kind == .int_unbound;
        },
    };

    num_literal_info.explicit_suffix = suffix_target != null;
    const flex_var = try self.mkFlexWithFromNumeralConstraint(node_idx, num_literal_info, env);
    if (is_int_unbound) {
        try self.int_unbound_vars.put(self.types.resolveVar(flex_var).var_, {});
    }

    if (suffix_target) |target| {
        try self.unifyLiteralWithSuffixTarget(flex_var, target, region, env);
        const targets_dec = switch (target.target()) {
            .builtin => |kind| kind == .dec,
            .local, .external, .invalid => false,
        };
        if (targets_dec) {
            _ = try self.reportInvalidBuiltinFromNumeralInfo(flex_var, .dec, num_literal_info, env);
        }
    }

    _ = try self.unify(occurrence_var, flex_var, env);
    if (occurrence == .pattern) {
        try self.mkPatternLiteralEqConstraint(occurrence_var, env, region);
    }
}

/// Create a nominal Box type with the given element type
fn mkBoxContent(self: *Self, elem_var: Var) Allocator.Error!Content {
    const trace = tracy.trace(@src());
    defer trace.end();

    const box_ident = types_mod.TypeIdent{
        .ident_idx = self.cir.idents.box,
    };

    // The application carries only identity + the element arg; Box's backing
    // (the element itself) lives in the declaration table.
    const type_args = [_]Var{elem_var};

    return try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
        box_ident,
        &type_args,
        self.builtinOriginModule(),
        self.sourceDeclForBuiltinNominal(.box),
        false, // Box is nominal (not opaque)
        true,
    );
}

/// Create a nominal Try type with the given success and error types.
/// This is used for creating Try types in function signatures (e.g., from_numeral).
fn mkTryContent(self: *Self, ok_var: Var, err_var: Var) Allocator.Error!Content {
    const trace = tracy.trace(@src());
    defer trace.end();

    const try_ident = types_mod.TypeIdent{
        .ident_idx = self.cir.idents.builtin_try,
    };

    // The application carries only identity + the ok/err args; Try's backing
    // ([Ok(ok), Err(err)]) lives in the declaration table.
    const type_args = [_]Var{ ok_var, err_var };

    return try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
        try_ident,
        &type_args,
        self.builtinOriginModule(),
        self.sourceDeclForBuiltinNominal(.try_type),
        false, // Try is nominal (not opaque)
        true,
    );
}

/// The error type of an optional field access: the closed tag union
/// `[MissingField]`, used as the Err side of `Try(field_type, [MissingField])`.
///
/// Closed (empty ext), matching the other builtin error unions minted by the
/// checker (`[InvalidNumeral(Str)]`, `[BadQuotedBytes(Str)]`): the access
/// itself can only fail one way, and a consumer's open union can still absorb
/// it at the use site.
fn makeFieldMissingTag(self: *Self, env: *Env, region: Region) Allocator.Error!Var {
    const missing_field_tag = try self.types.mkTag(self.cir.idents.missing_field, &.{});
    const err_ext_var = try self.freshFromContent(.{ .structure = .empty_tag_union }, env, region);
    const err_type = try self.types.mkTagUnion(&.{missing_field_tag}, err_ext_var);
    return try self.freshFromContent(err_type, env, region);
}

fn mkParseSpecVar(
    self: *Self,
    decl: BuiltinParseSpecDecl,
    shape_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!Var {
    const ident_idx = switch (decl) {
        .tag_union => self.cir.idents.builtin_encoding_parse_tag_union_spec,
        .bool, .str, .null, .list_start, .list_next, .list_after_item, .tuple_start, .tuple_next, .tuple_end, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .dec, .f32, .f64, .record_start, .record_field, .record_after_field => {
            if (builtin.mode == .Debug) {
                std.debug.panic("type checker invariant violated: this parse method does not have a builtin parse spec declaration", .{});
            }
            unreachable;
        },
    };
    return try self.freshFromContent(try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
        .{ .ident_idx = ident_idx },
        &.{shape_var},
        self.builtinOriginModule(),
        self.sourceDeclForBuiltinParseSpec(decl),
        true,
        true,
    ), env, region);
}

fn mkFieldsVar(
    self: *Self,
    shape_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!Var {
    return try self.mkBuiltinShapeHandleVar(.fields, shape_var, env, region);
}

fn mkFieldVar(
    self: *Self,
    shape_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!Var {
    return try self.mkBuiltinShapeHandleVar(.field, shape_var, env, region);
}

fn mkBuiltinShapeHandleVar(
    self: *Self,
    decl: BuiltinNominalDecl,
    shape_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!Var {
    return try self.freshFromContent(try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
        .{ .ident_idx = self.builtinNominalIdent(decl) },
        &.{shape_var},
        self.builtinOriginModule(),
        self.sourceDeclForBuiltinNominal(decl),
        true,
        true,
    ), env, region);
}

/// Create the transparent builtin Numeral type used by from_numeral.
fn mkNumeralContent(self: *Self) Allocator.Error!Content {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Use the pre-interned builtin ident instead of reconstructing the text.
    const numeral_ident = types_mod.TypeIdent{
        .ident_idx = self.cir.idents.builtin_numeral,
    };

    // The application carries only identity; Numeral's backing (the Literal
    // record) lives in the declaration table, where custom from_numeral
    // implementations open it (Numeral is transparent).
    return try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
        numeral_ident,
        &.{}, // No type args
        self.builtinOriginModule(),
        self.sourceDeclForBuiltinNominal(.numeral),
        false, // Numeral is transparent so custom from_numeral methods can inspect it.
        true,
    );
}

// updating vars //

/// Whether the fresh var built by `unifyWithFresh` uses the current
/// generalization rank or the target var's own rank.
const FreshRank = enum { current, target };

/// Unify `target_var` against freshly-built `content`. When `target_var` is a
/// root flex placeholder we mutate its descriptor in place (the common case),
/// saving a typeslot and a full unification run.
fn unifyWithFresh(
    self: *Self,
    target_var: Var,
    content: types_mod.Content,
    env: *Env,
    comptime rank_policy: FreshRank,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    const resolved_target = self.types.resolveVar(target_var);
    switch (rank_policy) {
        .current => {
            if (resolved_target.is_root and resolved_target.desc.rank == env.rank() and resolved_target.desc.content == .flex) {
                // The vast majority of the time, we call unify with on a placeholder
                // CIR var. In this case, we can safely replace the type descriptor
                // directly, saving a typeslot and unifcation run
                var desc = resolved_target.desc;
                desc.content = content;
                try self.types.dangerousSetVarDesc(target_var, desc);
                return;
            }
            const fresh_var = try self.freshFromContent(content, env, self.getRegionAt(target_var));
            if (builtin.mode == .Debug) {
                const target_var_rank = self.types.resolveVar(target_var).desc.rank;
                const fresh_var_rank = self.types.resolveVar(fresh_var).desc.rank;
                if (@intFromEnum(target_var_rank) > @intFromEnum(fresh_var_rank)) {
                    std.debug.panic("trying unifyWith unexpected ranks {} & {}", .{ @intFromEnum(target_var_rank), @intFromEnum(fresh_var_rank) });
                }
            }
            _ = try self.unify(target_var, fresh_var, env);
        },
        .target => {
            if (resolved_target.is_root and resolved_target.desc.content == .flex) {
                var desc = resolved_target.desc;
                desc.content = content;
                try self.types.dangerousSetVarDesc(target_var, desc);
                return;
            }
            const target_rank = resolved_target.desc.rank;
            const fresh_var = try self.freshFromContentAtRank(content, env, self.getRegionAt(target_var), target_rank);
            _ = try self.unify(target_var, fresh_var, env);
        },
    }
}

/// Unify the provided variable with the provided content
///
/// If the var is a flex at the current rank, skip unifcation and simply update
/// the type descriptor
///
/// This should primarily be use to set CIR node vars that were initially filled with placeholders
fn unifyWith(self: *Self, target_var: Var, content: types_mod.Content, env: *Env) std.mem.Allocator.Error!void {
    return self.unifyWithFresh(target_var, content, env, .current);
}

fn unifyWithTargetRank(self: *Self, target_var: Var, content: types_mod.Content, env: *Env) std.mem.Allocator.Error!void {
    return self.unifyWithFresh(target_var, content, env, .target);
}

/// Mark the solved class owned by an already-reported erroneous checker node.
fn markErroneous(self: *Self, target_var: Var) std.mem.Allocator.Error!void {
    try self.types.setVarContent(target_var, .err);
}

/// Give a var, ensure it's not a redirect and set its rank.
/// If the var is already a redirect, this is a no-op - the root's rank was set when
/// the redirect was created during unification. This can happen when a variable is
/// unified with another before its rank is explicitly set, which is benign.
fn setVarRank(self: *Self, target_var: Var, env: *Env) std.mem.Allocator.Error!void {
    const resolved = self.types.resolveVar(target_var);
    if (resolved.is_root) {
        try self.types.setDescRank(resolved.desc_idx, env.rank());
        try env.var_pool.addVarToRank(target_var, env.rank());
    }
    // If not root, the variable is a redirect - its rank is determined by the root
    // variable it points to, which was handled when the redirect was created.
}

// file //

/// Check the types for all defs
/// Copy builtin types from their modules into the current module's type store
/// This is necessary because type variables are module-specific - we can't use Vars from
/// other modules directly. The Bool and Try types are used in language constructs like
/// `if` conditions and need to be available in every module's type store.
fn copyBuiltinTypes(self: *Self) Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    if (self.builtin_types_copied) return;

    const checking_builtin_directly = self.isCheckingBuiltinModuleDirectly();
    const bool_stmt_idx = if (checking_builtin_directly)
        self.findLocalTypeDeclByName(self.cir.idents.bool_type) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("type checker invariant violated: local Builtin.Bool declaration not found while checking Builtin", .{});
            }
            unreachable;
        }
    else
        self.builtin_ctx.bool_stmt;
    const str_stmt_idx = if (checking_builtin_directly)
        self.findLocalTypeDeclByName(self.cir.idents.builtin_str) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("type checker invariant violated: local Builtin.Str declaration not found while checking Builtin", .{});
            }
            unreachable;
        }
    else
        self.builtin_ctx.str_stmt;
    const u64_stmt_idx = if (checking_builtin_directly)
        self.findLocalTypeDeclByName(self.cir.idents.u64_type) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("type checker invariant violated: local Builtin.U64 declaration not found while checking Builtin", .{});
            }
            unreachable;
        }
    else blk: {
        const indices = self.builtin_ctx.builtin_indices orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("type checker invariant violated: builtin indices missing while copying Builtin.U64", .{});
            }
            unreachable;
        };
        break :blk indices.u64_type;
    };

    if (!checking_builtin_directly and self.builtin_ctx.builtin_module != null) {
        const builtin_env = self.builtin_ctx.builtin_module.?;
        // Copy Bool type from Builtin module using the direct reference
        const bool_type_var = ModuleEnv.varFrom(bool_stmt_idx);
        self.bool_var = try self.copyVar(bool_type_var, builtin_env, Region.zero());

        // Copy Str type from Builtin module using the direct reference
        const str_type_var = ModuleEnv.varFrom(str_stmt_idx);
        self.str_var = try self.copyVar(str_type_var, builtin_env, Region.zero());

        // Copy U64 type from Builtin module using the direct reference
        const u64_type_var = ModuleEnv.varFrom(u64_stmt_idx);
        self.u64_var = try self.copyVar(u64_type_var, builtin_env, Region.zero());
    } else {
        // If Builtin module reference is null, use the statement from the current module
        // This happens when compiling the Builtin module itself
        self.bool_var = ModuleEnv.varFrom(bool_stmt_idx);
        self.str_var = ModuleEnv.varFrom(str_stmt_idx);
        self.u64_var = ModuleEnv.varFrom(u64_stmt_idx);
    }

    // Try type is accessed via external references, no need to copy it here

    // Ensure this module's type store carries a declaration-table entry for
    // every builtin nominal declaration. The checker synthesizes applications
    // of these directly (List, Box, Try, number types, ...) without going
    // through copyVar, so the entries must be present up front for keyed
    // declaration lookups to resolve.
    try self.ensureBuiltinNominalDeclEntries();

    self.builtin_types_copied = true;
}

/// Copy the declaration-table entries for all builtin nominal declarations
/// from the Builtin module env into this module's type store. No-op when
/// checking the Builtin module itself (its declarations register locally
/// during type-decl processing).
fn ensureBuiltinNominalDeclEntries(self: *Self) Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    if (self.isCheckingBuiltinModuleDirectly()) return;
    const builtin_env = self.builtin_ctx.builtin_module orelse return;
    const indices = self.builtin_ctx.builtin_indices orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic("type checker invariant violated: builtin module env present without builtin indices", .{});
        }
        unreachable;
    };

    self.var_map.clearRetainingCapacity();
    const first_new_var: usize = @intCast(self.types.len());

    inline for (CIR.builtin_type_specs) |spec| {
        try copy_import.ensureNominalDeclForStatement(
            &builtin_env.types,
            self.types,
            @intFromEnum(@field(indices, spec.type_field)),
            &self.var_map,
            builtin_env,
            self.cir,
            self.gpa,
        );
    }

    try self.postProcessCopiedVars(first_new_var, Region.zero());
}

/// Public `checkFile` function.
const OptionalFieldAccess = struct {
    presence_var: Var,
    field_name: Ident.Idx,
    region: Region,
};

/// One record-literal field's minted kind var (see `literal_field_kinds`).
/// The region is the literal's, reused when the finalize sweep mints the
/// `required` content it commits the kind to.
const LiteralFieldKind = struct {
    presence_var: Var,
    region: Region,
};

const PendingRecordUpdate = struct {
    presence_var: Var,
    region: Region,
};

const PendingDefaultCheck = struct {
    default_expr: CIR.Expr.Idx,
    field_type_var: Var,
    field_name: Ident.Idx,
};

/// One record-destructure field awaiting the kind-directed binder judgment
/// (see `pending_record_destructs` and `judgeRecordDestructBinds`).
const PendingRecordDestruct = struct {
    /// The field's kind-flexible presence var (the destructure's probe).
    presence_var: Var,
    /// The field's value type in the probed row—a FRESH var, so the binder
    /// stays independent until the judgment decides plain-vs-Try binding.
    payload_var: Var,
    /// The destructure binder (the sub-pattern's var).
    binder_var: Var,
    field_name: Ident.Idx,
    region: Region,
};

/// Type-check every def in the module, including the numeric-literal
/// defaulting rounds at finalize (see `checkFileInternal`).
pub fn checkFile(self: *Self) std.mem.Allocator.Error!void {
    return self.checkFileInternal(false);
}

fn checkFileInternal(self: *Self, skip_numeric_defaults: bool) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Fill in types store up to the size of CIR nodes
    try ensureTypeStoreIsFilled(self);

    // Create a solver env
    var env = try self.env_pool.acquire();
    defer self.env_pool.release(env);

    std.debug.assert(env.rank() == .generalized);

    // Copy builtin types (Bool, Try) into this module's type store
    // Note that bool_var and try_var will have generalized rank
    try self.copyBuiltinTypes();

    // First, iterate over the builtin statements, generating types for each type declaration
    // Note that any types generated will be generalized
    for (0..self.cir.builtin_statements.span.len) |stmt_offset| {
        const builtin_stmt_idx = self.cir.store.statementAt(self.cir.builtin_statements, stmt_offset);
        // If the statement is a type declaration, then generate the it's type
        // The resulting generalized type is saved at the type var slot at `stmt_idx`
        try self.generateStmtTypeDeclType(builtin_stmt_idx, &env);
    }

    // Reserve every canonical type constructor from canonicalization's explicit
    // type-declaration table before generating type bodies. Transparent nominal
    // backing types and recursive declarations both rely on these constructor
    // shells being present before any later checking work consumes them.
    for (0..self.cir.type_decls.span.len) |stmt_offset| {
        const stmt_idx = self.cir.store.statementAt(self.cir.type_decls, stmt_offset);
        const stmt = self.cir.store.getStatement(stmt_idx);
        const stmt_var = ModuleEnv.varFrom(stmt_idx);

        switch (stmt) {
            .s_alias_decl => |alias| {
                try self.setVarRank(stmt_var, &env);
                try self.predeclareAliasDecl(stmt_var, alias, &env);
            },
            .s_nominal_decl => |nominal| {
                try self.setVarRank(stmt_var, &env);
                try self.predeclareNominalDecl(stmt_var, nominal, &env);
            },
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => {},
        }
    }

    // First pass: generate types for each type declaration
    // Note that any types generated will be generalized
    for (0..self.cir.all_statements.span.len) |stmt_offset| {
        const stmt_idx = self.cir.store.statementAt(self.cir.all_statements, stmt_offset);
        const stmt = self.cir.store.getStatement(stmt_idx);
        const stmt_var = ModuleEnv.varFrom(stmt_idx);

        switch (stmt) {
            .s_alias_decl, .s_nominal_decl, .s_where_alias_decl => {
                _ = try self.ensureTypeDeclGenerated(stmt_idx, &env);
            },
            .s_runtime_error => {
                try self.setVarRank(stmt_var, &env);
                try self.markErroneous(stmt_var);
            },
            .s_type_anno => |type_anno| {
                try self.setVarRank(stmt_var, &env);
                try self.generateStandaloneTypeAnno(stmt_var, type_anno, &env);
            },
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_type_var_alias,
            => {
                // All other stmt types are invalid at the top level
            },
        }
    }

    // With every declaration generated, validate nominal declaration
    // recursion before any value checking consumes the declarations.
    try self.finalizeTypeDeclarationValidity();

    // Next, capture all top level defs
    // This is used to support out-of-order defs
    for (0..self.cir.all_defs.span.len) |def_offset| {
        const def_idx = self.cir.store.defAt(self.cir.all_defs, def_offset);
        const def = self.cir.store.getDef(def_idx);
        self.setTopLevelPattern(def.pattern, DefProcessed{
            .def_idx = def_idx,
            .def_name = null,
            .status = .not_processed,
        });
    }

    // Set the rank to be outermost
    try env.var_pool.pushRank();
    std.debug.assert(env.rank() == .outermost);

    // Process requires_types annotations for platforms
    // This ensures the type store has the actual types for platform requirements
    try self.processRequiresTypes(&env);

    try self.processAppPlatformRequirements(&env);

    // Declare every annotated def's scheme before any body is checked, then
    // check defs as binding groups in dependency order. A name reference
    // between groups always points at an already-checked (or pre-declared)
    // def; dispatch-discovered dependencies resolve at group boundaries.
    try self.setupCheckOrder();
    try self.predeclareAnnotatedDefSchemes(&env);
    const group_count: u32 = @intCast(self.check_order.?.sccs.len);
    var group_index: u32 = 0;
    while (group_index < group_count) : (group_index += 1) {
        try self.ensureGroupChecked(group_index, &env);
        std.debug.assert(env.rank() == .outermost);
    }

    // Finally, type-check top-level statements (like expect)
    // These are separate from defs and need to be checked after all defs are processed
    // so that lookups can find their definitions
    for (0..self.cir.all_statements.span.len) |stmt_offset| {
        const stmt_idx = self.cir.store.statementAt(self.cir.all_statements, stmt_offset);
        const stmt = self.cir.store.getStatement(stmt_idx);
        const stmt_var = ModuleEnv.varFrom(stmt_idx);
        const stmt_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(stmt_idx));

        switch (stmt) {
            .s_expect => |expr_stmt| {
                // Check the body expression
                _ = try self.checkExpectBody(expr_stmt.body, &env, Expected.none(), stmt_region);
                const body_var: Var = ModuleEnv.varFrom(expr_stmt.body);

                // Unify with Bool (expects must be bool expressions)
                const bool_var = try self.freshBool(&env, stmt_region);
                _ = try self.unifyInContext(bool_var, body_var, &env, .expect);

                // Unify statement var with body var
                _ = try self.unify(stmt_var, body_var, &env);
            },
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_alias_decl,
            .s_nominal_decl,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => {},
        }
    }

    try self.finalizeTypes(&env, .{ .module = .{ .skip_numeric_defaults = skip_numeric_defaults } });

    // After solving all deferred constraints, check every binding root
    // (top-level defs and local bindings) for infinite types
    try self.checkBindingRootsForInfiniteTypes();
    try self.recheckNominalConstructorBackings(&env);

    try self.poisonErroneousValueUses();
    try self.poisonErroneousValueExprs();

    try self.reportPolymorphicTopLevelValues();

    try self.checkPlatformHostedSection();

    // Ambiguity was judged locally as each definition generalized (see
    // `judgeAmbiguityCandidatesAtGeneralization`). Two steps remain, both
    // gated on recorded worklist data and skipped entirely for a clean module:
    // judge the residual candidates that never generalized (value-restricted
    // bindings stay open to pinning by later defs and the final constraint
    // fixpoint, so they can only be judged here, at the settled state), then
    // apply every verdict—problem reports plus runtime-error poisoning—in
    // one batch so problem order and CIR mutation timing stay deterministic
    // against the settled end state.
    try self.judgeResidualAmbiguityCandidates();
    try self.applyAmbiguityVerdicts();
    try self.finalizeTypeSchemeRequirementsAtCheckedBoundary();

    try self.reportPolymorphicExecutableRootResults();

    try self.reportNonExhaustiveLambdaParams(&env);
    try self.reportNonExhaustiveForPatterns(&env);

    try self.pruneSelectedHoistedRootsAfterSolving();
    try self.finalizeLiteralDispatchResolutions();
    try self.finalizeTopLevelDemandDependencies(&env);
    try self.finalizeExpectEffectSlots();

    try self.finalizeBindingSchemeNodes();

    try self.finalizePlatformRequirementSolutions();

    self.debugAssertNominalDeclTableComplete();
}

/// Turn every provisional platform-requirement row into the explicit
/// successful-binding or checked-error outcome consumed by artifact
/// publication. This runs after all checker error poisoning, while the checker
/// still owns the exact source def and solved vars.
fn finalizePlatformRequirementSolutions(self: *Self) Allocator.Error!void {
    for (self.platform_requirement_solutions.items) |*solution| {
        const def = self.cir.store.getDef(solution.def);
        var checked_error = self.erroneous_value_exprs.contains(def.expr) or
            self.erroneous_value_patterns.contains(def.pattern);

        if (!checked_error) {
            checked_error = try canonical_type_keys.containsError(
                self.gpa,
                self.types,
                self.cir,
                ModuleEnv.varFrom(def.expr),
            );
        }
        if (!checked_error) {
            checked_error = try canonical_type_keys.containsError(
                self.gpa,
                self.types,
                self.cir,
                solution.solved_var,
            );
        }
        if (!checked_error) {
            for (solution.identity_vars) |identity_var| {
                if (try canonical_type_keys.containsError(
                    self.gpa,
                    self.types,
                    self.cir,
                    identity_var,
                )) {
                    checked_error = true;
                    break;
                }
            }
        }

        solution.outcome = if (checked_error) .checked_error else .success;
    }
}

/// Finish canonicalization's strict-demand relation with the exact local
/// literal-conversion targets selected by checking, then reject any value
/// cycle that only became visible through those calls. The rebuilt graph is
/// the durable producer output consumed by checked-root scheduling and CTFE.
fn finalizeTopLevelDemandDependencies(self: *Self, env: *Env) Allocator.Error!void {
    var literal_targets = std.ArrayList(DependencyGraph.ResolvedLiteralTarget).empty;
    defer literal_targets.deinit(self.gpa);
    for (self.dispatch_target_instantiations.items) |target| {
        if (!target.is_literal_conversion or target.target_env != self.cir) continue;
        try literal_targets.append(self.gpa, .{
            .fn_var = target.constraint_fn_var,
            .target_def = target.target_binding.def_idx,
        });
    }

    // Imported conversion methods cannot participate in a same-module value
    // cycle: their checked constants have already been finalized in the owner
    // artifact. Preserve canonicalization's relation when there is no local
    // target overlay to apply.
    if (literal_targets.items.len == 0) return;

    var graph = try DependencyGraph.buildDependencyGraphWithResolvedLiteralTargets(
        self.cir,
        self.cir.all_defs,
        literal_targets.items,
        self.gpa,
    );
    defer graph.deinit();

    var dependencies = try DependencyGraph.collectDependencies(&graph, self.gpa);
    errdefer dependencies.deinit(self.gpa);
    var eval_order = try DependencyGraph.computeSCCs(&graph, self.gpa);
    defer eval_order.deinit();

    try self.poisonCheckedStrictDemandCycles(&eval_order, env);
    self.cir.setTopLevelDemandDependencies(dependencies);
    dependencies = .{};

    // The new cycle poisoning happens after the ordinary erroneous-use sweep,
    // so propagate it once more before checked bodies are published.
    try self.poisonErroneousValueUses();
    try self.poisonErroneousValueExprs();
}

fn poisonCheckedStrictDemandCycles(
    self: *Self,
    eval_order: *const DependencyGraph.EvaluationOrder,
    env: *Env,
) Allocator.Error!void {
    const RecursiveNonFunctionDef = struct {
        def_idx: CIR.Def.Idx,
        ident: Ident.Idx,
        region: Region,
    };

    for (eval_order.sccs) |scc| {
        if (!scc.is_recursive) continue;

        var defs_to_poison = std.ArrayList(RecursiveNonFunctionDef).empty;
        defer defs_to_poison.deinit(self.gpa);

        for (scc.defs) |def_idx| {
            const def = self.cir.store.getDef(def_idx);
            if (isFunctionDef(&self.cir.store, self.cir.store.getExpr(def.expr))) continue;
            const ident = self.getPatternIdent(def.pattern) orelse continue;
            try defs_to_poison.append(self.gpa, .{
                .def_idx = def_idx,
                .ident = ident,
                .region = self.cir.store.getPatternRegion(def.pattern),
            });
        }

        std.mem.sort(RecursiveNonFunctionDef, defs_to_poison.items, {}, struct {
            fn lessThan(_: void, a: RecursiveNonFunctionDef, b: RecursiveNonFunctionDef) bool {
                if (a.region.start.offset != b.region.start.offset) {
                    return a.region.start.offset < b.region.start.offset;
                }
                if (a.region.end.offset != b.region.end.offset) {
                    return a.region.end.offset < b.region.end.offset;
                }
                return @intFromEnum(a.def_idx) < @intFromEnum(b.def_idx);
            }
        }.lessThan);

        for (defs_to_poison.items) |def_to_poison| {
            _ = try self.problems.appendProblem(self.gpa, .{ .circular_value_definition = .{
                .ident = def_to_poison.ident,
                .region = def_to_poison.region,
            } });
            try self.poisonRecursiveNonFunctionProcessingDef(.{
                .def_idx = def_to_poison.def_idx,
                .def_name = def_to_poison.ident,
                .status = .processed,
            }, null, env);
        }
    }
}

/// Debug-only invariant check: every nominal application in this store that
/// carries a source declaration can resolve its declaration in this store's
/// declaration table. Local declarations register during type-decl
/// processing; imported ones are copied in by `copy_import`; builtin ones are
/// ensured up front by `ensureBuiltinNominalDeclEntries`. A miss here means a
/// nominal application was minted without its declaration being reachable.
fn debugAssertNominalDeclTableComplete(self: *const Self) void {
    if (builtin.mode != .Debug) return;

    var var_int: u32 = 0;
    const num_vars: u32 = @intCast(self.types.len());
    while (var_int < num_vars) : (var_int += 1) {
        const resolved = self.types.resolveVar(@enumFromInt(var_int));
        if (!resolved.is_root) continue;
        const content = resolved.desc.content;
        if (content != .structure) continue;
        if (content.structure != .nominal_type) continue;
        const nominal = content.structure.nominal_type;
        if (!nominal.sourceDecl().present) continue;
        if (self.types.lookupNominalDecl(nominal) == null) {
            std.debug.panic(
                "type checker invariant violated: nominal application '{s}' (origin {}, statement {}) has no declaration table entry in its store",
                .{
                    self.cir.getIdentStoreConst().getText(nominal.ident.ident_idx),
                    @intFromEnum(nominal.origin_module),
                    nominal.sourceDecl().statement,
                },
            );
        }
    }
}

fn pruneSelectedHoistedRootsAfterSolving(self: *Self) Allocator.Error!void {
    const root_count = self.selected_hoisted_roots.items.len;
    const keep_roots = try self.gpa.alloc(bool, root_count);
    defer self.gpa.free(keep_roots);
    @memset(keep_roots, false);

    var keep_oracle = try HoistedRootKeepOracle.init(self.gpa, self.selected_hoisted_roots.items, keep_roots);
    defer keep_oracle.deinit(self.gpa);

    var kept_count: usize = 0;
    var kept_expr_count: u32 = 0;
    var kept_pattern_count: u32 = 0;
    var kept_validation_count: u32 = 0;
    for (self.selected_hoisted_roots.items, 0..) |*root, i| {
        keep_oracle.current_root_index = i;
        const intrinsic = !self.hoistExprInvalidated(root.expr) and try self.hoistedRootIsIntrinsicallyKept(root);
        const deps = intrinsic and try self.hoistedRootDependenciesAreKept(root.expr, &keep_oracle);
        if (!intrinsic) continue;
        if (!deps) continue;

        keep_roots[i] = true;
        kept_count += 1;
        switch (root.body) {
            .expr => kept_expr_count += 1,
            .pattern_extraction => {},
            .pattern_validation => kept_validation_count += 1,
        }
        if (root.pattern != null) kept_pattern_count += 1;
    }

    // A validation keeps its dedicated root until solving has proved that the
    // prospective maximal expression root is itself publishable. Only a kept
    // owner may subsume the validation.
    for (self.selected_hoisted_roots.items, 0..) |root, validation_index| {
        if (!keep_roots[validation_index]) continue;
        if (root.body != .pattern_validation) continue;
        const owner_expr = root.validation_owner_expr orelse continue;
        const owner_index = self.hoist_selected_exprs.get(owner_expr) orelse continue;
        if (!keep_roots[owner_index]) continue;
        keep_roots[validation_index] = false;
        kept_count -= 1;
        kept_validation_count -= 1;
    }

    // A kept extraction evaluates the same scrutinee and complete source
    // pattern as its validation root. Let it own that exhaustiveness site so
    // the right-hand side is not evaluated twice. If the extraction's result
    // type is not concrete, pruning leaves the unit-valued validation root in
    // place instead.
    for (self.selected_hoisted_roots.items, 0..) |root, i| {
        if (!keep_roots[i]) continue;
        const extraction = switch (root.body) {
            .pattern_extraction => |extraction| extraction,
            .expr, .pattern_validation => continue,
        };
        const validation_index = self.hoist_selected_pattern_validations.get(extraction.scrutinee_pattern) orelse continue;
        if (!keep_roots[validation_index]) continue;
        keep_roots[validation_index] = false;
        kept_count -= 1;
        kept_validation_count -= 1;
    }

    try self.hoist_selected_exprs.ensureTotalCapacity(self.gpa, kept_expr_count);
    try self.hoist_selected_bindings.ensureTotalCapacity(self.gpa, kept_pattern_count);
    try self.hoist_selected_pattern_validations.ensureTotalCapacity(self.gpa, kept_validation_count);

    self.hoist_selected_exprs.clearRetainingCapacity();
    self.hoist_selected_bindings.clearRetainingCapacity();
    self.hoist_selected_pattern_validations.clearRetainingCapacity();

    var kept: usize = 0;
    for (self.selected_hoisted_roots.items, keep_roots, 0..) |*root, keep, i| {
        if (!keep) {
            hoist_roots.deinitSelectedRoot(self.gpa, root);
            continue;
        }

        if (kept != i) {
            self.selected_hoisted_roots.items[kept] = root.*;
            root.body = .expr;
        }
        const root_index: u32 = @intCast(kept);
        switch (self.selected_hoisted_roots.items[kept].body) {
            .expr => self.hoist_selected_exprs.putAssumeCapacityNoClobber(self.selected_hoisted_roots.items[kept].expr, root_index),
            .pattern_extraction => {},
            .pattern_validation => |validation| self.hoist_selected_pattern_validations.putAssumeCapacityNoClobber(validation.scrutinee_pattern, root_index),
        }
        if (self.selected_hoisted_roots.items[kept].pattern) |pattern| {
            self.hoist_selected_bindings.putAssumeCapacityNoClobber(pattern, root_index);
        }
        kept += 1;
    }

    std.debug.assert(kept == kept_count);
    self.selected_hoisted_roots.shrinkRetainingCapacity(kept);
    self.debugAssertHoistSelectionConsistent();
    try self.debugVerifyKeptHoistedRootDependencies();
}

fn hoistedRootIsIntrinsicallyKept(
    self: *Self,
    root: *hoist_roots.SelectedHoistedRoot,
) Allocator.Error!bool {
    if (root.body == .pattern_validation) {
        root.value_kind = .discarded;
        return true;
    }

    const type_var = if (root.pattern) |pattern|
        ModuleEnv.varFrom(pattern)
    else
        ModuleEnv.varFrom(root.expr);

    if (root.body == .pattern_extraction) {
        const is_function = self.varIsFunctionType(type_var);
        if (is_function or self.selectedHoistedRootIsTopLevel(root.*)) {
            root.value_kind = if (is_function) .callable_binding else .data_constant;
            return if (self.selectedHoistedRootIsTopLevel(root.*))
                true
            else
                try self.varIsConcreteCallableRootType(type_var);
        }
    }

    if (self.varIsFunctionType(type_var)) {
        return false;
    }

    root.value_kind = .data_constant;
    if (self.cir.store.getExpr(root.expr) == .e_runtime_error) return true;
    if (isFunctionDef(&self.cir.store, self.cir.store.getExpr(root.expr))) return false;
    return try self.varIsConcreteHoistedConstType(type_var);
}

fn debugVerifyKeptHoistedRootDependencies(self: *Self) Allocator.Error!void {
    if (builtin.mode != .Debug) return;

    const root_count = self.selected_hoisted_roots.items.len;
    const keep_roots = try self.gpa.alloc(bool, root_count);
    defer self.gpa.free(keep_roots);
    @memset(keep_roots, true);

    var keep_oracle = try HoistedRootKeepOracle.init(self.gpa, self.selected_hoisted_roots.items, keep_roots);
    defer keep_oracle.deinit(self.gpa);

    for (self.selected_hoisted_roots.items, 0..) |root, i| {
        keep_oracle.current_root_index = i;
        if (!try self.hoistedRootDependenciesAreKept(root.expr, &keep_oracle)) {
            hoistSelectionInvariant("kept selected hoisted root has unavailable dependency");
        }
    }
}

fn varIsConcreteHoistedConstType(self: *Self, var_: Var) Allocator.Error!bool {
    self.var_set.clearRetainingCapacity();
    return try self.varIsConcreteHoistedConstTypeInternal(.value_graph, .data_constant, var_, &self.var_set);
}

fn varIsConcreteCallableRootType(self: *Self, var_: Var) Allocator.Error!bool {
    if (builtin.mode == .Debug) std.debug.assert(self.varIsFunctionType(var_));
    self.var_set.clearRetainingCapacity();
    return try self.varIsConcreteHoistedConstTypeInternal(.value_graph, .callable_binding, var_, &self.var_set);
}

/// Resolve a nominal application's declaration backing TEMPLATE for read-only
/// structural queries, or null when the declaration is invalid or source-less.
/// A source-backed nominal missing from the declaration table is a checker
/// invariant violation. In the template, the declaration's formals (rigid vars)
/// stand at exactly the positions where the application's args are substituted,
/// so a query that checks the args separately can walk the template as long as
/// its rigid handling is neutral (or explicitly template-aware).
fn nominalDeclBackingTemplate(self: *const Self, nominal: types_mod.NominalType) ?Var {
    const decl_idx = self.types.lookupNominalDecl(nominal) orelse {
        if (nominal.sourceDecl().present) {
            if (builtin.mode == .Debug) {
                std.debug.panic(
                    "type checker invariant violated: nominal application '{s}' has a source declaration but no declaration table entry",
                    .{self.cir.getIdentStoreConst().getText(nominal.ident.ident_idx)},
                );
            }
            unreachable;
        }
        return null;
    };
    const decl = self.types.getNominalDecl(decl_idx);
    if (!decl.isValid()) return null;
    return decl.backing;
}

/// Which graph a hoisted-const concreteness walk is inspecting: the value
/// graph (rigids are NOT concrete) or a declaration backing template (rigids
/// are the declaration's formals, standing for args the caller has already
/// checked, so they count as concrete).
const HoistedConstWalk = enum { value_graph, decl_template };

/// The representation whose complete checked type this walk is proving.
/// Data archived in ConstStore must not contain a callable. A callable binding
/// instead has an exact callable payload, so its signature may itself contain
/// function types in argument and result positions.
const HoistedRootTypePurpose = enum { data_constant, callable_binding };

/// Copy a record's field value-type variables onto `scratch_record_field_vars`
/// and return the start mark of the pushed batch. The batch is
/// `[mark, scratch_record_field_vars.top())`; the caller reads it *by index* and
/// releases it with `scratch_record_field_vars.clearFrom(mark)` (typically via
/// `defer`). The presence axis is never runtime data, so it is not collected
/// here (one value-type var per field, in field order).
///
/// The copy exists because a caller's loop body may reallocate the record-fields
/// store—a borrowed column view into `self.types` would then dangle—so the
/// vars must be read out first. Every caller here also *recurses back into this
/// function* from inside that loop, pushing a nested batch on top of the parent's.
/// Because the scratch is index-addressed and each nested batch is released before
/// the parent resumes, stacked use composes. The caller must therefore iterate by
/// index rather than hold a `[]Var` view: a nested push that grows the backing
/// buffer relocates it, which would invalidate a borrowed slice but not an index.
fn dupeRecordFieldTypeVars(self: *Self, presences: []const types_mod.RecordField.Presence) Allocator.Error!u32 {
    const mark = self.scratch_record_field_vars.top();
    for (presences) |presence| {
        try self.scratch_record_field_vars.append(presence.typeVar());
    }
    return mark;
}

fn varIsConcreteHoistedConstTypeInternal(
    self: *Self,
    comptime walk: HoistedConstWalk,
    comptime purpose: HoistedRootTypePurpose,
    var_: Var,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    if (visited.contains(resolved.var_)) return true;
    try visited.put(resolved.var_, {});

    return switch (resolved.desc.content) {
        .err,
        .flex,
        .field_presence,
        => false,
        .rigid => walk == .decl_template,
        .alias => |alias| (try self.varsAreConcreteHoistedConstTypes(walk, purpose, self.types.sliceAliasArgs(alias), visited)) and
            try self.varIsConcreteHoistedConstTypeInternal(walk, purpose, self.types.getAliasBackingVar(alias), visited),
        .structure => |flat| try self.flatTypeIsConcreteHoistedConst(walk, purpose, flat, visited),
    };
}

fn varsAreConcreteHoistedConstTypes(
    self: *Self,
    comptime walk: HoistedConstWalk,
    comptime purpose: HoistedRootTypePurpose,
    vars: []const Var,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    for (vars) |var_| {
        if (!try self.varIsConcreteHoistedConstTypeInternal(walk, purpose, var_, visited)) return false;
    }
    return true;
}

fn flatTypeIsConcreteHoistedConst(
    self: *Self,
    comptime walk: HoistedConstWalk,
    comptime purpose: HoistedRootTypePurpose,
    flat: FlatType,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    return switch (flat) {
        .empty_record,
        .empty_tag_union,
        => true,
        .fn_pure, .fn_effectful, .fn_unbound => |func| purpose == .callable_binding and
            (try self.varsAreConcreteHoistedConstTypes(walk, purpose, self.types.sliceVars(func.args), visited)) and
            try self.varIsConcreteHoistedConstTypeInternal(walk, purpose, func.ret, visited),
        .record => |record| blk: {
            const fields = self.types.getRecordFieldsSlice(record.fields);
            for (fields.items(.presence)) |presence| {
                const field_var = presence.typeVar();
                if (!try self.varIsConcreteHoistedConstTypeInternal(walk, purpose, field_var, visited)) break :blk false;
            }
            break :blk try self.varIsConcreteHoistedConstTypeInternal(walk, purpose, record.ext, visited);
        },
        .record_unbound => |fields| blk: {
            const fields_slice = self.types.getRecordFieldsSlice(fields);
            for (fields_slice.items(.presence)) |presence| {
                const field_var = presence.typeVar();
                if (!try self.varIsConcreteHoistedConstTypeInternal(walk, purpose, field_var, visited)) break :blk false;
            }
            break :blk true;
        },
        .tuple => |tuple| try self.varsAreConcreteHoistedConstTypes(walk, purpose, self.types.sliceVars(tuple.elems), visited),
        .tag_union => |tag_union| blk: {
            const tags = self.types.getTagsSlice(tag_union.tags);
            for (tags.items(.args)) |tag_args| {
                if (!try self.varsAreConcreteHoistedConstTypes(walk, purpose, self.types.sliceVars(tag_args), visited)) break :blk false;
            }
            break :blk try self.varIsConcreteHoistedConstTypeInternal(walk, purpose, tag_union.ext, visited);
        },
        .nominal_type => |nominal| blk: {
            if (!try self.varsAreConcreteHoistedConstTypes(walk, purpose, self.types.sliceNominalArgs(nominal), visited)) break :blk false;
            if (self.builtinNominalDeclForBuiltinSourceDecl(nominal.sourceDeclOptional())) |builtin_decl| {
                switch (builtin_decl) {
                    .list,
                    .box,
                    .dict,
                    .set,
                    .fields,
                    .field,
                    .num,
                    => break :blk true,
                    .try_type,
                    .numeral,
                    => {},
                }
            }
            // Non-builtin nominal: inspect the declaration's backing template.
            // Formals in the template stand for the args checked above, so the
            // template walk admits rigids. Opacity hides the backing from
            // source, not from archiving, which copies it.
            const template = self.nominalDeclBackingTemplate(nominal) orelse break :blk false;
            break :blk try self.varIsConcreteHoistedConstTypeInternal(.decl_template, purpose, template, visited);
        },
    };
}

const HoistedDependencyBindingKind = enum {
    internal,
    contextual,
};

const HoistedDependencyBinding = struct {
    pattern: CIR.Pattern.Idx,
    kind: HoistedDependencyBindingKind,
};

const HoistedCallableKey = struct {
    module_addr: usize,
    def: CIR.Def.Idx,
};

const HoistedCallableState = enum {
    visiting,
    stable,
    unstable,
};

const HoistedDependencyContext = struct {
    bindings: std.ArrayListUnmanaged(HoistedDependencyBinding) = .empty,
    callable_stability: std.AutoHashMapUnmanaged(HoistedCallableKey, HoistedCallableState) = .{},

    fn deinit(self: *@This(), allocator: Allocator) void {
        self.bindings.deinit(allocator);
        self.callable_stability.deinit(allocator);
    }

    fn mark(self: *const @This()) usize {
        return self.bindings.items.len;
    }

    fn pop(self: *@This(), start: usize) void {
        self.bindings.shrinkRetainingCapacity(start);
    }

    fn contains(self: *const @This(), pattern: CIR.Pattern.Idx) bool {
        for (self.bindings.items) |binding| {
            if (binding.pattern == pattern) return true;
        }
        return false;
    }

    fn append(
        self: *@This(),
        allocator: Allocator,
        pattern: CIR.Pattern.Idx,
        kind: HoistedDependencyBindingKind,
    ) Allocator.Error!void {
        try self.bindings.append(allocator, .{
            .pattern = pattern,
            .kind = kind,
        });
    }
};

fn hoistSelectionInvariant(comptime message: []const u8) noreturn {
    if (builtin.mode == .Debug) {
        std.debug.panic("check invariant violated: " ++ message, .{});
    }
    unreachable;
}

const HoistedRootKeepOracle = struct {
    pattern_roots: std.AutoHashMapUnmanaged(CIR.Pattern.Idx, u32) = .{},
    expr_roots: std.AutoHashMapUnmanaged(CIR.Expr.Idx, u32) = .{},
    keep_roots: []const bool,
    current_root_index: usize = 0,

    fn init(
        allocator: Allocator,
        roots: []const hoist_roots.SelectedHoistedRoot,
        keep_roots: []const bool,
    ) Allocator.Error!HoistedRootKeepOracle {
        var oracle = HoistedRootKeepOracle{ .keep_roots = keep_roots };
        errdefer oracle.deinit(allocator);
        try oracle.pattern_roots.ensureTotalCapacity(allocator, @intCast(roots.len));
        try oracle.expr_roots.ensureTotalCapacity(allocator, @intCast(roots.len));

        for (roots, 0..) |root, i| {
            const root_index: u32 = @intCast(i);
            switch (root.body) {
                .expr => {
                    const entry = oracle.expr_roots.getOrPutAssumeCapacity(root.expr);
                    if (entry.found_existing) hoistSelectionInvariant("duplicate selected hoisted expression root");
                    entry.value_ptr.* = root_index;
                },
                .pattern_extraction => {},
                .pattern_validation => {},
            }
            if (root.pattern) |pattern| {
                const entry = oracle.pattern_roots.getOrPutAssumeCapacity(pattern);
                if (entry.found_existing) hoistSelectionInvariant("duplicate selected hoisted binding root");
                entry.value_ptr.* = root_index;
            }
        }

        return oracle;
    }

    fn deinit(self: *HoistedRootKeepOracle, allocator: Allocator) void {
        self.pattern_roots.deinit(allocator);
        self.expr_roots.deinit(allocator);
    }

    fn selectedPatternIsKept(self: *const HoistedRootKeepOracle, pattern: CIR.Pattern.Idx) ?bool {
        const root_index = self.pattern_roots.get(pattern) orelse return null;
        if (root_index >= self.current_root_index) {
            hoistSelectionInvariant("selected hoisted root depended on a later selected root");
        }
        return self.keep_roots[root_index];
    }
};

fn hoistedRootDependenciesAreKept(
    self: *Self,
    expr: CIR.Expr.Idx,
    keep_oracle: *const HoistedRootKeepOracle,
) Allocator.Error!bool {
    var context = HoistedDependencyContext{};
    defer context.deinit(self.gpa);
    return try self.hoistedRootDependenciesAreKeptInternal(expr, &context, keep_oracle);
}

fn hoistedRootDependenciesAreKeptInternal(
    self: *Self,
    expr: CIR.Expr.Idx,
    context: *HoistedDependencyContext,
    keep_oracle: *const HoistedRootKeepOracle,
) Allocator.Error!bool {
    if (self.hoistExprInvalidated(expr)) return false;
    if (self.exprHasDedicatedLiteralConversionRoot(expr)) return false;

    return switch (self.cir.store.getExpr(expr)) {
        .e_lookup_local => |lookup| self.patternIsTopLevel(lookup.pattern_idx) or
            context.contains(lookup.pattern_idx) or
            (keep_oracle.selectedPatternIsKept(lookup.pattern_idx) orelse false),
        .e_lookup_external,
        .e_lookup_associated_local,
        .e_lookup_associated,
        .e_lookup_associated_resolved,
        .e_str_segment,
        .e_bytes_literal,
        .e_num,
        .e_num_from_numeral,
        .e_frac_f32,
        .e_frac_f64,
        .e_dec,
        .e_dec_small,
        .e_typed_int,
        .e_typed_frac,
        .e_typed_num_from_numeral,
        .e_empty_list,
        .e_empty_record,
        .e_zero_argument_tag,
        .e_runtime_error,
        => true,
        .e_lookup_required,
        .e_ellipsis,
        .e_anno_only,
        .e_derived_method,
        .e_crash,
        .e_closure,
        .e_lambda,
        .e_hosted_lambda,
        .e_dbg,
        .e_expect_err,
        .e_expect,
        .e_for,
        .e_return,
        .e_break,
        .e_run_low_level,
        => false,
        .e_str => |str| self.hoistedRootExprSpanDependenciesAreKept(str.span, context, keep_oracle),
        .e_list => |list| self.hoistedRootExprSpanDependenciesAreKept(list.elems, context, keep_oracle),
        .e_tuple => |tuple| self.hoistedRootExprSpanDependenciesAreKept(tuple.elems, context, keep_oracle),
        .e_block => |block| self.hoistedRootBlockDependenciesAreKept(block.stmts, block.final_expr, context, keep_oracle),
        .e_match => |match| self.hoistedRootMatchDependenciesAreKept(match, context, keep_oracle),
        .e_if => |if_expr| self.hoistedRootIfDependenciesAreKept(if_expr.branches, if_expr.final_else, context, keep_oracle),
        .e_call => |call| (try self.hoistedRootCalleeAllowsStoredConst(call.func, context)) and
            (try self.hoistedRootDependenciesAreKeptInternal(call.func, context, keep_oracle)) and
            try self.hoistedRootExprSpanDependenciesAreKept(call.args, context, keep_oracle),
        // Surface method calls must have been rewritten to checked dispatch
        // calls before the settled hoistability walk can classify them.
        .e_method_call => false,
        .e_dispatch_call => |call| (try self.staticDispatchAllowsHoistedRoot(
            ModuleEnv.varFrom(call.receiver),
            call.constraint_fn_var,
        )) and
            (try self.hoistedRootDependenciesAreKeptInternal(call.receiver, context, keep_oracle)) and
            try self.hoistedRootExprSpanDependenciesAreKept(call.args, context, keep_oracle),
        .e_record => |record| self.hoistedRootRecordDependenciesAreKept(record.fields, record.ext, context, keep_oracle),
        .e_tag => |tag| self.hoistedRootExprSpanDependenciesAreKept(tag.args, context, keep_oracle),
        .e_nominal => |nominal| self.hoistedRootDependenciesAreKeptInternal(nominal.backing_expr, context, keep_oracle),
        .e_nominal_external => |nominal| self.hoistedRootDependenciesAreKeptInternal(nominal.backing_expr, context, keep_oracle),
        .e_binop => |binop| (try self.hoistedRootDependenciesAreKeptInternal(binop.lhs, context, keep_oracle)) and
            try self.hoistedRootDependenciesAreKeptInternal(binop.rhs, context, keep_oracle),
        .e_unary_minus => |unary| self.hoistedRootDependenciesAreKeptInternal(unary.expr, context, keep_oracle),
        .e_unary_not => |unary| self.hoistedRootDependenciesAreKeptInternal(unary.expr, context, keep_oracle),
        .e_field_access => |field| self.hoistedRootDependenciesAreKeptInternal(field.receiver, context, keep_oracle),
        .e_interpolation => |interpolation| blk: {
            const fn_var = interpolation.constraint_fn_var orelse break :blk false;
            const dispatcher_var = interpolation.dispatcher_var orelse break :blk false;
            if (!try self.staticDispatchAllowsHoistedRoot(
                dispatcher_var,
                fn_var,
            )) break :blk false;
            break :blk (try self.hoistedRootDependenciesAreKeptInternal(interpolation.first, context, keep_oracle)) and
                try self.hoistedRootExprSpanDependenciesAreKept(interpolation.parts, context, keep_oracle);
        },
        .e_structural_eq => |eq| (try self.hoistedRootDependenciesAreKeptInternal(eq.lhs, context, keep_oracle)) and
            try self.hoistedRootDependenciesAreKeptInternal(eq.rhs, context, keep_oracle),
        .e_structural_hash => |h| (try self.hoistedRootDependenciesAreKeptInternal(h.value, context, keep_oracle)) and
            try self.hoistedRootDependenciesAreKeptInternal(h.hasher, context, keep_oracle),
        .e_method_eq => |eq| (try self.staticDispatchAllowsHoistedRoot(
            ModuleEnv.varFrom(eq.lhs),
            eq.constraint_fn_var,
        )) and
            (try self.hoistedRootDependenciesAreKeptInternal(eq.lhs, context, keep_oracle)) and
            try self.hoistedRootDependenciesAreKeptInternal(eq.rhs, context, keep_oracle),
        // Like value method calls, surface type-method calls are not checked
        // dispatch plans and therefore cannot establish compile-time safety.
        .e_type_method_call => false,
        .e_type_dispatch_call => |call| (try self.staticDispatchAllowsHoistedRoot(
            self.typeDispatchOwnerVar(call.type_dispatch_stmt),
            call.constraint_fn_var,
        )) and
            try self.hoistedRootExprSpanDependenciesAreKept(call.args, context, keep_oracle),
        .e_tuple_access => |access| self.hoistedRootDependenciesAreKeptInternal(access.tuple, context, keep_oracle),
    };
}

const HoistedCallableDef = struct {
    module: *const ModuleEnv,
    def: CIR.Def.Idx,
};

fn hoistedRootCalleeAllowsStoredConst(
    self: *Self,
    callee: CIR.Expr.Idx,
    context: *HoistedDependencyContext,
) Allocator.Error!bool {
    const callable_def = self.hoistedCallableDefForExpr(self.cir, callee) orelse return true;
    return try self.hoistedCallableDefAllowsStoredConst(callable_def, context);
}

fn hoistedCallableDefAllowsStoredConst(
    self: *Self,
    callable_def: HoistedCallableDef,
    context: *HoistedDependencyContext,
) Allocator.Error!bool {
    const key = HoistedCallableKey{
        .module_addr = @intFromPtr(callable_def.module),
        .def = callable_def.def,
    };
    if (context.callable_stability.get(key)) |state| {
        return switch (state) {
            .stable, .visiting => true,
            .unstable => false,
        };
    }

    try context.callable_stability.put(self.gpa, key, .visiting);
    const def = callable_def.module.store.getDef(callable_def.def);
    const stable = try self.hoistedExprAllowsStoredConst(callable_def.module, def.expr, context);
    const state: HoistedCallableState = if (stable) .stable else .unstable;
    context.callable_stability.getPtr(key).?.* = state;
    return stable;
}

fn hoistedExprAllowsStoredConst(
    self: *Self,
    module: *const ModuleEnv,
    expr: CIR.Expr.Idx,
    context: *HoistedDependencyContext,
) Allocator.Error!bool {
    if (self.moduleHoistExprInvalidated(module, expr)) return false;
    return switch (module.store.getExpr(expr)) {
        .e_run_low_level => |run| run.op != .dict_pseudo_seed and
            try self.hoistedExprSpanAllowsStoredConst(module, run.args, context),
        .e_lookup_local,
        .e_lookup_external,
        .e_lookup_associated_local,
        .e_lookup_associated,
        .e_lookup_associated_resolved,
        .e_lookup_required,
        .e_str_segment,
        .e_bytes_literal,
        .e_num,
        .e_num_from_numeral,
        .e_frac_f32,
        .e_frac_f64,
        .e_dec,
        .e_dec_small,
        .e_typed_int,
        .e_typed_frac,
        .e_typed_num_from_numeral,
        .e_empty_list,
        .e_empty_record,
        .e_zero_argument_tag,
        .e_runtime_error,
        .e_ellipsis,
        .e_anno_only,
        .e_derived_method,
        .e_crash,
        .e_hosted_lambda,
        => true,
        .e_str => |str| self.hoistedExprSpanAllowsStoredConst(module, str.span, context),
        .e_list => |list| self.hoistedExprSpanAllowsStoredConst(module, list.elems, context),
        .e_tuple => |tuple| self.hoistedExprSpanAllowsStoredConst(module, tuple.elems, context),
        .e_block => |block| self.hoistedBlockAllowsStoredConst(module, block.stmts, block.final_expr, context),
        .e_match => |match| self.hoistedMatchAllowsStoredConst(module, match, context),
        .e_if => |if_expr| self.hoistedIfAllowsStoredConst(module, if_expr.branches, if_expr.final_else, context),
        .e_call => |call| (try self.hoistedCalleeAllowsStoredConstInModule(module, call.func, context)) and
            (try self.hoistedExprAllowsStoredConst(module, call.func, context)) and
            try self.hoistedExprSpanAllowsStoredConst(module, call.args, context),
        .e_method_call => |call| (try self.hoistedExprAllowsStoredConst(module, call.receiver, context)) and
            try self.hoistedExprSpanAllowsStoredConst(module, call.args, context),
        .e_dispatch_call => |call| (try self.hoistedExprAllowsStoredConst(module, call.receiver, context)) and
            try self.hoistedExprSpanAllowsStoredConst(module, call.args, context),
        .e_record => |record| self.hoistedRecordAllowsStoredConst(module, record.fields, record.ext, context),
        .e_tag => |tag| self.hoistedExprSpanAllowsStoredConst(module, tag.args, context),
        .e_nominal => |nominal| self.hoistedExprAllowsStoredConst(module, nominal.backing_expr, context),
        .e_nominal_external => |nominal| self.hoistedExprAllowsStoredConst(module, nominal.backing_expr, context),
        .e_binop => |binop| (try self.hoistedExprAllowsStoredConst(module, binop.lhs, context)) and
            try self.hoistedExprAllowsStoredConst(module, binop.rhs, context),
        .e_unary_minus => |unary| self.hoistedExprAllowsStoredConst(module, unary.expr, context),
        .e_unary_not => |unary| self.hoistedExprAllowsStoredConst(module, unary.expr, context),
        .e_field_access => |field| self.hoistedExprAllowsStoredConst(module, field.receiver, context),
        .e_interpolation => |interpolation| (try self.hoistedExprAllowsStoredConst(module, interpolation.first, context)) and
            try self.hoistedExprSpanAllowsStoredConst(module, interpolation.parts, context),
        .e_structural_eq => |eq| (try self.hoistedExprAllowsStoredConst(module, eq.lhs, context)) and
            try self.hoistedExprAllowsStoredConst(module, eq.rhs, context),
        .e_structural_hash => |h| (try self.hoistedExprAllowsStoredConst(module, h.value, context)) and
            try self.hoistedExprAllowsStoredConst(module, h.hasher, context),
        .e_method_eq => |eq| (try self.hoistedExprAllowsStoredConst(module, eq.lhs, context)) and
            try self.hoistedExprAllowsStoredConst(module, eq.rhs, context),
        .e_type_method_call => |call| self.hoistedExprSpanAllowsStoredConst(module, call.args, context),
        .e_type_dispatch_call => |call| self.hoistedExprSpanAllowsStoredConst(module, call.args, context),
        .e_tuple_access => |access| self.hoistedExprAllowsStoredConst(module, access.tuple, context),
        .e_dbg,
        .e_expect_err,
        .e_expect,
        .e_break,
        => false,
        .e_for => |for_expr| (try self.hoistedExprAllowsStoredConst(module, for_expr.expr, context)) and
            try self.hoistedExprAllowsStoredConst(module, for_expr.body, context),
        .e_return => |ret| self.hoistedExprAllowsStoredConst(module, ret.expr, context),
        .e_closure => |closure| self.hoistedExprAllowsStoredConst(module, closure.lambda_idx, context),
        .e_lambda => |lambda| self.hoistedExprAllowsStoredConst(module, lambda.body, context),
    };
}

fn hoistedCalleeAllowsStoredConstInModule(
    self: *Self,
    module: *const ModuleEnv,
    callee: CIR.Expr.Idx,
    context: *HoistedDependencyContext,
) Allocator.Error!bool {
    const callable_def = self.hoistedCallableDefForExpr(module, callee) orelse return true;
    return try self.hoistedCallableDefAllowsStoredConst(callable_def, context);
}

fn hoistedCallableDefForExpr(
    self: *Self,
    module: *const ModuleEnv,
    expr: CIR.Expr.Idx,
) ?HoistedCallableDef {
    return switch (module.store.getExpr(expr)) {
        .e_lookup_local => |lookup| hoistedTopLevelDefForPattern(module, lookup.pattern_idx),
        .e_lookup_external => |external| blk: {
            const imported_module = self.hoistedImportedModule(module, external.module_idx) orelse break :blk null;
            break :blk hoistedTopLevelDefForNode(imported_module, @enumFromInt(external.target_node_idx));
        },
        .e_lookup_associated_resolved => |resolved| blk: {
            const target_module = self.moduleEnvForIdentity(resolved.module_identity) orelse break :blk null;
            break :blk HoistedCallableDef{ .module = target_module.env, .def = resolved.target_def_idx };
        },
        .e_lookup_associated_local, .e_lookup_associated => null,
        .e_str,
        .e_str_segment,
        .e_bytes_literal,
        .e_num,
        .e_num_from_numeral,
        .e_frac_f32,
        .e_frac_f64,
        .e_dec,
        .e_dec_small,
        .e_typed_int,
        .e_typed_frac,
        .e_typed_num_from_numeral,
        .e_empty_list,
        .e_empty_record,
        .e_zero_argument_tag,
        .e_lookup_required,
        .e_list,
        .e_tuple,
        .e_record,
        .e_block,
        .e_tag,
        .e_nominal,
        .e_nominal_external,
        .e_match,
        .e_if,
        .e_call,
        .e_closure,
        .e_lambda,
        .e_binop,
        .e_unary_minus,
        .e_unary_not,
        .e_field_access,
        .e_method_call,
        .e_dispatch_call,
        .e_interpolation,
        .e_structural_eq,
        .e_structural_hash,
        .e_method_eq,
        .e_type_method_call,
        .e_type_dispatch_call,
        .e_tuple_access,
        .e_dbg,
        .e_expect_err,
        .e_expect,
        .e_for,
        .e_hosted_lambda,
        .e_run_low_level,
        .e_runtime_error,
        .e_ellipsis,
        .e_anno_only,
        .e_derived_method,
        .e_crash,
        .e_return,
        .e_break,
        => null,
    };
}

fn hoistedImportedModule(
    self: *Self,
    module: *const ModuleEnv,
    import_idx: CIR.Import.Idx,
) ?*const ModuleEnv {
    const module_idx = module.imports.getResolvedModule(import_idx) orelse return null;
    if (module_idx >= self.imported_modules.len) return null;
    return self.imported_modules[module_idx];
}

fn hoistedTopLevelDefForPattern(
    module: *const ModuleEnv,
    pattern: CIR.Pattern.Idx,
) ?HoistedCallableDef {
    const pattern_node = ModuleEnv.nodeIdxFrom(pattern);
    return hoistedTopLevelDefForNode(module, pattern_node);
}

fn hoistedTopLevelDefForNode(
    module: *const ModuleEnv,
    node: CIR.Node.Idx,
) ?HoistedCallableDef {
    for (module.store.sliceDefs(module.global_value_defs)) |def_idx| {
        const def = module.store.getDef(def_idx);
        if (ModuleEnv.nodeIdxFrom(def_idx) == node or ModuleEnv.nodeIdxFrom(def.pattern) == node or ModuleEnv.nodeIdxFrom(def.expr) == node) {
            return .{ .module = module, .def = def_idx };
        }
    }
    return null;
}

fn hoistedExprSpanAllowsStoredConst(
    self: *Self,
    module: *const ModuleEnv,
    span: CIR.Expr.Span,
    context: *HoistedDependencyContext,
) Allocator.Error!bool {
    for (module.store.sliceExpr(span)) |expr| {
        if (!try self.hoistedExprAllowsStoredConst(module, expr, context)) return false;
    }
    return true;
}

fn hoistedBlockAllowsStoredConst(
    self: *Self,
    module: *const ModuleEnv,
    statements: CIR.Statement.Span,
    final_expr: CIR.Expr.Idx,
    context: *HoistedDependencyContext,
) Allocator.Error!bool {
    for (module.store.sliceStatements(statements)) |statement| {
        if (!try self.hoistedStatementAllowsStoredConst(module, statement, context)) return false;
    }
    return try self.hoistedExprAllowsStoredConst(module, final_expr, context);
}

fn hoistedStatementAllowsStoredConst(
    self: *Self,
    module: *const ModuleEnv,
    statement: CIR.Statement.Idx,
    context: *HoistedDependencyContext,
) Allocator.Error!bool {
    return switch (module.store.getStatement(statement)) {
        .s_decl => |decl| self.hoistedExprAllowsStoredConst(module, decl.expr, context),
        .s_var => |var_stmt| self.hoistedExprAllowsStoredConst(module, var_stmt.expr, context),
        .s_reassign => |reassign| self.hoistedExprAllowsStoredConst(module, reassign.expr, context),
        .s_expr => |expr_stmt| self.hoistedExprAllowsStoredConst(module, expr_stmt.expr, context),
        .s_dbg,
        .s_expect,
        => false,
        .s_for => |for_stmt| (try self.hoistedExprAllowsStoredConst(module, for_stmt.expr, context)) and
            try self.hoistedExprAllowsStoredConst(module, for_stmt.body, context),
        .s_while => |while_stmt| (try self.hoistedExprAllowsStoredConst(module, while_stmt.cond, context)) and
            try self.hoistedExprAllowsStoredConst(module, while_stmt.body, context),
        .s_infinite_loop => |loop_stmt| (try self.hoistedExprAllowsStoredConst(module, loop_stmt.cond, context)) and
            try self.hoistedExprAllowsStoredConst(module, loop_stmt.body, context),
        .s_breakable_loop => |loop_stmt| (try self.hoistedExprAllowsStoredConst(module, loop_stmt.cond, context)) and
            try self.hoistedExprAllowsStoredConst(module, loop_stmt.body, context),
        .s_return => |ret| self.hoistedExprAllowsStoredConst(module, ret.expr, context),
        .s_var_uninitialized,
        .s_import,
        .s_alias_decl,
        .s_nominal_decl,
        .s_where_alias_decl,
        .s_type_anno,
        .s_type_var_alias,
        .s_crash,
        .s_break,
        .s_runtime_error,
        => true,
    };
}

fn hoistedRecordAllowsStoredConst(
    self: *Self,
    module: *const ModuleEnv,
    fields: CIR.RecordField.Span,
    ext: ?CIR.Expr.Idx,
    context: *HoistedDependencyContext,
) Allocator.Error!bool {
    if (ext) |ext_expr| {
        if (!try self.hoistedExprAllowsStoredConst(module, ext_expr, context)) return false;
    }
    for (module.store.sliceRecordFields(fields)) |field_id| {
        const field = module.store.getRecordField(field_id);
        if (!try self.hoistedExprAllowsStoredConst(module, field.value, context)) return false;
    }
    return true;
}

fn hoistedMatchAllowsStoredConst(
    self: *Self,
    module: *const ModuleEnv,
    match: CIR.Expr.Match,
    context: *HoistedDependencyContext,
) Allocator.Error!bool {
    if (!try self.hoistedExprAllowsStoredConst(module, match.cond, context)) return false;
    for (module.store.sliceMatchBranches(match.branches)) |branch_id| {
        const branch = module.store.getMatchBranch(branch_id);
        if (branch.guard) |guard| {
            if (!try self.hoistedExprAllowsStoredConst(module, guard, context)) return false;
        }
        if (!try self.hoistedExprAllowsStoredConst(module, branch.value, context)) return false;
    }
    return true;
}

fn hoistedIfAllowsStoredConst(
    self: *Self,
    module: *const ModuleEnv,
    branches: CIR.Expr.IfBranch.Span,
    final_else: CIR.Expr.Idx,
    context: *HoistedDependencyContext,
) Allocator.Error!bool {
    for (module.store.sliceIfBranches(branches)) |branch_id| {
        const branch = module.store.getIfBranch(branch_id);
        if (!try self.hoistedExprAllowsStoredConst(module, branch.cond, context)) return false;
        if (!try self.hoistedExprAllowsStoredConst(module, branch.body, context)) return false;
    }
    return try self.hoistedExprAllowsStoredConst(module, final_else, context);
}

fn exprHasDedicatedLiteralConversionRoot(self: *Self, expr: CIR.Expr.Idx) bool {
    const node = ModuleEnv.nodeIdxFrom(expr);
    if (self.cir.numeralDispatchPlanForNode(node) != null) {
        if (self.cir.numericSuffixTargetForNode(node)) |suffix_target| {
            return switch (suffix_target.target()) {
                .builtin => false,
                .local,
                .external,
                => true,
                .invalid => false,
            };
        }
        return !self.varIsBuiltinLiteralTarget(ModuleEnv.varFrom(expr));
    }
    if (self.cir.quoteDispatchPlanForNode(node) != null and
        !self.varIsBuiltinLiteralTarget(ModuleEnv.varFrom(expr)))
    {
        return true;
    }
    return false;
}

fn varIsBuiltinLiteralTarget(self: *Self, var_: Var) bool {
    var current = var_;
    while (true) {
        const resolved = self.types.resolveVar(current);
        switch (resolved.desc.content) {
            .alias => |alias| {
                current = self.types.getAliasBackingVar(alias);
            },
            .structure => |flat| return switch (flat) {
                .nominal_type => |nominal| self.nominalIsBuiltinNumberType(nominal) or
                    self.nominalIsBuiltinStrType(nominal),
                .record,
                .record_unbound,
                .tuple,
                .fn_pure,
                .fn_effectful,
                .fn_unbound,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => false,
            },
            .err,
            .flex,
            .rigid,
            .field_presence,
            => return false,
        }
    }
}

fn hoistedRootExprSpanDependenciesAreKept(
    self: *Self,
    span: CIR.Expr.Span,
    context: *HoistedDependencyContext,
    keep_oracle: *const HoistedRootKeepOracle,
) Allocator.Error!bool {
    for (self.cir.store.sliceExpr(span)) |child| {
        if (!try self.hoistedRootDependenciesAreKeptInternal(child, context, keep_oracle)) return false;
    }
    return true;
}

fn hoistedRootBlockDependenciesAreKept(
    self: *Self,
    statements: CIR.Statement.Span,
    final_expr: CIR.Expr.Idx,
    context: *HoistedDependencyContext,
    keep_oracle: *const HoistedRootKeepOracle,
) Allocator.Error!bool {
    const mark = context.mark();
    defer context.pop(mark);

    for (self.cir.store.sliceStatements(statements)) |statement| {
        if (!try self.hoistedRootStatementDependenciesAreKept(statement, context, keep_oracle)) return false;
    }
    return try self.hoistedRootDependenciesAreKeptInternal(final_expr, context, keep_oracle);
}

fn hoistedRootStatementDependenciesAreKept(
    self: *Self,
    statement: CIR.Statement.Idx,
    context: *HoistedDependencyContext,
    keep_oracle: *const HoistedRootKeepOracle,
) Allocator.Error!bool {
    return switch (self.cir.store.getStatement(statement)) {
        .s_decl => |decl| blk: {
            if (!try self.hoistedRootDependenciesAreKeptInternal(decl.expr, context, keep_oracle)) break :blk false;
            // Binders introduced and consumed inside this root are transient
            // evaluation state. They need neither separate selected roots nor
            // representation-stable static types.
            try self.appendHoistedDependencyPatternBinders(decl.pattern, context, .internal);
            break :blk true;
        },
        .s_expr => |expr| self.hoistedRootDependenciesAreKeptInternal(expr.expr, context, keep_oracle),
        .s_import,
        .s_alias_decl,
        .s_nominal_decl,
        .s_where_alias_decl,
        .s_type_anno,
        .s_type_var_alias,
        => true,
        .s_var,
        .s_var_uninitialized,
        .s_reassign,
        .s_crash,
        .s_dbg,
        .s_expect,
        .s_for,
        .s_while,
        .s_infinite_loop,
        .s_breakable_loop,
        .s_break,
        .s_return,
        .s_runtime_error,
        => false,
    };
}

fn hoistedRootMatchDependenciesAreKept(
    self: *Self,
    match: CIR.Expr.Match,
    context: *HoistedDependencyContext,
    keep_oracle: *const HoistedRootKeepOracle,
) Allocator.Error!bool {
    if (!try self.hoistedRootDependenciesAreKeptInternal(match.cond, context, keep_oracle)) return false;
    for (self.cir.store.sliceMatchBranches(match.branches)) |branch_idx| {
        const branch = self.cir.store.getMatchBranch(branch_idx);
        const mark = context.mark();
        defer context.pop(mark);
        for (self.cir.store.sliceMatchBranchPatterns(branch.patterns)) |branch_pattern_idx| {
            const branch_pattern = self.cir.store.getMatchBranchPattern(branch_pattern_idx);
            // Branch binders are likewise local to the root evaluation; only
            // the selected root's result must have a storable concrete type.
            try self.appendHoistedDependencyPatternBinders(branch_pattern.pattern, context, .contextual);
        }
        if (branch.guard) |guard| {
            if (!try self.hoistedRootDependenciesAreKeptInternal(guard, context, keep_oracle)) return false;
        }
        if (!try self.hoistedRootDependenciesAreKeptInternal(branch.value, context, keep_oracle)) return false;
    }
    return true;
}

fn hoistedRootPatternSelectedDependenciesAreKept(
    self: *Self,
    pattern: CIR.Pattern.Idx,
    keep_oracle: *const HoistedRootKeepOracle,
) Allocator.Error!bool {
    if (keep_oracle.selectedPatternIsKept(pattern)) |kept| {
        if (!kept) return false;
    }

    return switch (self.cir.store.getPattern(pattern)) {
        .assign,
        .underscore,
        .runtime_error,
        .num_literal,
        .num_from_numeral_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .str_literal,
        => true,
        .as => |as_pattern| try self.hoistedRootPatternSelectedDependenciesAreKept(as_pattern.pattern, keep_oracle),
        .tuple => |tuple| blk: {
            for (self.cir.store.slicePatterns(tuple.patterns)) |elem_pattern| {
                if (!try self.hoistedRootPatternSelectedDependenciesAreKept(elem_pattern, keep_oracle)) break :blk false;
            }
            break :blk true;
        },
        .record_destructure => |destructure| blk: {
            for (self.cir.store.sliceRecordDestructs(destructure.destructs)) |destruct_idx| {
                const destruct = self.cir.store.getRecordDestruct(destruct_idx);
                if (!try self.hoistedRootPatternSelectedDependenciesAreKept(destruct.kind.toPatternIdx(), keep_oracle)) break :blk false;
            }
            break :blk true;
        },
        .applied_tag => |tag| blk: {
            for (self.cir.store.slicePatterns(tag.args)) |arg_pattern| {
                if (!try self.hoistedRootPatternSelectedDependenciesAreKept(arg_pattern, keep_oracle)) break :blk false;
            }
            break :blk true;
        },
        .nominal => |nominal| try self.hoistedRootPatternSelectedDependenciesAreKept(nominal.backing_pattern, keep_oracle),
        .nominal_external => |nominal| try self.hoistedRootPatternSelectedDependenciesAreKept(nominal.backing_pattern, keep_oracle),
        .list => |list| blk: {
            for (self.cir.store.slicePatterns(list.patterns)) |elem_pattern| {
                if (!try self.hoistedRootPatternSelectedDependenciesAreKept(elem_pattern, keep_oracle)) break :blk false;
            }
            if (list.rest_info) |rest_info| {
                if (rest_info.pattern) |rest_pattern| {
                    if (!try self.hoistedRootPatternSelectedDependenciesAreKept(rest_pattern, keep_oracle)) break :blk false;
                }
            }
            break :blk true;
        },
        .str_interpolation => |str| blk: {
            var step_offset: u32 = 0;
            while (step_offset < str.steps.span.len) : (step_offset += 1) {
                const step = self.cir.store.getStrPatternStep(str.steps, step_offset);
                if (step.capture) |capture| {
                    if (!try self.hoistedRootPatternSelectedDependenciesAreKept(capture, keep_oracle)) break :blk false;
                }
            }
            break :blk true;
        },
    };
}

fn hoistedRootPatternBindersAreConcrete(
    self: *Self,
    pattern: CIR.Pattern.Idx,
) Allocator.Error!bool {
    return switch (self.cir.store.getPattern(pattern)) {
        .assign => try self.varIsConcreteHoistedConstType(ModuleEnv.varFrom(pattern)),
        .as => |as_pattern| (try self.varIsConcreteHoistedConstType(ModuleEnv.varFrom(pattern))) and
            try self.hoistedRootPatternBindersAreConcrete(as_pattern.pattern),
        .tuple => |tuple| blk: {
            for (self.cir.store.slicePatterns(tuple.patterns)) |elem_pattern| {
                if (!try self.hoistedRootPatternBindersAreConcrete(elem_pattern)) break :blk false;
            }
            break :blk true;
        },
        .record_destructure => |destructure| blk: {
            for (self.cir.store.sliceRecordDestructs(destructure.destructs)) |destruct_idx| {
                const destruct = self.cir.store.getRecordDestruct(destruct_idx);
                if (!try self.hoistedRootPatternBindersAreConcrete(destruct.kind.toPatternIdx())) break :blk false;
            }
            break :blk true;
        },
        .applied_tag => |tag| blk: {
            for (self.cir.store.slicePatterns(tag.args)) |arg_pattern| {
                if (!try self.hoistedRootPatternBindersAreConcrete(arg_pattern)) break :blk false;
            }
            break :blk true;
        },
        .nominal => |nominal| try self.hoistedRootPatternBindersAreConcrete(nominal.backing_pattern),
        .nominal_external => |nominal| try self.hoistedRootPatternBindersAreConcrete(nominal.backing_pattern),
        .list => |list| blk: {
            for (self.cir.store.slicePatterns(list.patterns)) |elem_pattern| {
                if (!try self.hoistedRootPatternBindersAreConcrete(elem_pattern)) break :blk false;
            }
            if (list.rest_info) |rest_info| {
                if (rest_info.pattern) |rest_pattern| {
                    if (!try self.hoistedRootPatternBindersAreConcrete(rest_pattern)) break :blk false;
                }
            }
            break :blk true;
        },
        .str_interpolation => |str| blk: {
            var step_offset: u32 = 0;
            while (step_offset < str.steps.span.len) : (step_offset += 1) {
                const step = self.cir.store.getStrPatternStep(str.steps, step_offset);
                if (step.capture) |capture| {
                    if (!try self.hoistedRootPatternBindersAreConcrete(capture)) break :blk false;
                }
            }
            break :blk true;
        },
        .underscore,
        .runtime_error,
        .num_literal,
        .num_from_numeral_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .str_literal,
        => true,
    };
}

fn appendHoistedDependencyPatternBinders(
    self: *Self,
    pattern: CIR.Pattern.Idx,
    context: *HoistedDependencyContext,
    kind: HoistedDependencyBindingKind,
) Allocator.Error!void {
    switch (self.cir.store.getPattern(pattern)) {
        .assign => {
            try context.append(self.gpa, pattern, kind);
        },
        .as => |as_pattern| {
            try context.append(self.gpa, pattern, kind);
            try self.appendHoistedDependencyPatternBinders(as_pattern.pattern, context, kind);
        },
        .tuple => |tuple| {
            for (self.cir.store.slicePatterns(tuple.patterns)) |elem_pattern| {
                try self.appendHoistedDependencyPatternBinders(elem_pattern, context, kind);
            }
        },
        .record_destructure => |destructure| {
            for (self.cir.store.sliceRecordDestructs(destructure.destructs)) |destruct_idx| {
                const destruct = self.cir.store.getRecordDestruct(destruct_idx);
                try self.appendHoistedDependencyPatternBinders(destruct.kind.toPatternIdx(), context, kind);
            }
        },
        .applied_tag => |tag| {
            for (self.cir.store.slicePatterns(tag.args)) |arg_pattern| {
                try self.appendHoistedDependencyPatternBinders(arg_pattern, context, kind);
            }
        },
        .nominal => |nominal| {
            try self.appendHoistedDependencyPatternBinders(nominal.backing_pattern, context, kind);
        },
        .nominal_external => |nominal| {
            try self.appendHoistedDependencyPatternBinders(nominal.backing_pattern, context, kind);
        },
        .list => |list| {
            for (self.cir.store.slicePatterns(list.patterns)) |elem_pattern| {
                try self.appendHoistedDependencyPatternBinders(elem_pattern, context, kind);
            }
            if (list.rest_info) |rest_info| {
                if (rest_info.pattern) |rest_pattern| {
                    try self.appendHoistedDependencyPatternBinders(rest_pattern, context, kind);
                }
            }
        },
        .str_interpolation => |str| {
            var step_offset: u32 = 0;
            while (step_offset < str.steps.span.len) : (step_offset += 1) {
                const step = self.cir.store.getStrPatternStep(str.steps, step_offset);
                if (step.capture) |capture| {
                    try self.appendHoistedDependencyPatternBinders(capture, context, kind);
                }
            }
        },
        .underscore,
        .runtime_error,
        .num_literal,
        .num_from_numeral_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .str_literal,
        => {},
    }
}

fn hoistedRootIfDependenciesAreKept(
    self: *Self,
    branches: CIR.Expr.IfBranch.Span,
    final_else: CIR.Expr.Idx,
    context: *HoistedDependencyContext,
    keep_oracle: *const HoistedRootKeepOracle,
) Allocator.Error!bool {
    for (self.cir.store.sliceIfBranches(branches)) |branch_idx| {
        const branch = self.cir.store.getIfBranch(branch_idx);
        if (!try self.hoistedRootDependenciesAreKeptInternal(branch.cond, context, keep_oracle)) return false;
        if (!try self.hoistedRootDependenciesAreKeptInternal(branch.body, context, keep_oracle)) return false;
    }
    return try self.hoistedRootDependenciesAreKeptInternal(final_else, context, keep_oracle);
}

fn hoistedRootRecordDependenciesAreKept(
    self: *Self,
    fields: CIR.RecordField.Span,
    ext: ?CIR.Expr.Idx,
    context: *HoistedDependencyContext,
    keep_oracle: *const HoistedRootKeepOracle,
) Allocator.Error!bool {
    if (ext) |ext_expr| {
        if (!try self.hoistedRootDependenciesAreKeptInternal(ext_expr, context, keep_oracle)) return false;
    }
    for (self.cir.store.sliceRecordFields(fields)) |field_idx| {
        const field = self.cir.store.getRecordField(field_idx);
        if (!try self.hoistedRootDependenciesAreKeptInternal(field.value, context, keep_oracle)) return false;
    }
    return true;
}

/// Build the two pinnable sets for one ambiguity-judgment event into
/// `self.external_pinnable` and `self.pinnable_vars`.
///
/// `external_pinnable` holds every resolved var reachable through the complete
/// interface of the given scheme roots—the vars a future caller can still pin
/// by choosing arguments or by supplying an expected result type.
/// `pinnable_vars` additionally includes:
///
/// - Everything reachable through a still-open literal's constraint
///   signatures. Open literals are never dead ends: defaulting resolves them,
///   the deferred dispatch fires, and the resolved method's signature pins
///   every var in the constraint fn—return position included. Without this,
///   an instantiated helper's RETURN var (`add_x(5)` with
///   `add_x : a -> r where [a.plus : (a, x) -> r]`) was falsely reported
///   MISSING METHOD. Generalized entries are deliberately NOT skipped: a
///   generalized literal stays open and resolves per instantiation, which is
///   exactly why its chain is pinnable.
/// - Everything reachable from the given lambda parameter spans (recorded as
///   each lambda was checked—explicit upstream data): a direct dispatch
///   hidden inside an uncalled function value can still be pinned when that
///   function is called.
///
/// At a generalization event the inputs are the generalizing definition's own
/// scheme root, open literals, and lambdas (`*_def_start` cursors); at the
/// end-of-check residual judgment they are every top-level callable def and the
/// full recorded lists. Non-generalized values have already been evaluated and
/// cannot gain a new owner from a later use.
fn beginAmbiguityPinnableSets(self: *Self) void {
    self.external_pinnable.clearRetainingCapacity();
    self.scheme_relation_reachability.clearRetainingCapacity();
    self.scheme_relation_reachable_vars.clearRetainingCapacity();
}

/// Add one scheme root's complete interface closure to `external_pinnable`
/// (plain walk) and its requirement relations to the receiver-excluded overlay.
/// See `finishAmbiguityPinnableSets`.
fn addAmbiguityPinnableRoot(self: *Self, interface_root: Var, scheme_root: Var) std.mem.Allocator.Error!void {
    try self.collectReachableVars(interface_root, &self.external_pinnable);
    try self.addSchemeRequirementRelationsToReachableSet(scheme_root);
}

/// Add the callable side of a root scheme's explicit requirements without
/// traversing through the shared receiver. The relation is part of the
/// published interface; the receiver and its unrelated constraint graph are
/// not made reachable merely because the callable names it as argument zero.
/// The walk collects into `scheme_relation_reachable_vars`—never into a
/// plain-walk set, whose membership early-return demands closure-complete
/// entries the receiver pruning cannot provide.
fn addSchemeRequirementRelationsToReachableSet(
    self: *Self,
    scheme_root: Var,
) Allocator.Error!void {
    const scheme_idx = self.typeSchemeIndexForRoot(scheme_root) orelse return;
    for (self.type_schemes.items[scheme_idx].dispatch_requirements.items) |requirement| {
        const receiver_root = self.types.resolveVar(requirement.receiver_var).var_;
        try self.collectReachableVarsExcluding(
            requirement.constraint.fn_var,
            receiver_root,
            &self.scheme_relation_reachable_vars,
        );
    }
}

/// Complete the event's pinnable sets after every scheme root has been added.
fn finishAmbiguityPinnableSets(
    self: *Self,
    open_literal_vars: []const Var,
    lambda_param_spans: []const CIR.Pattern.Span,
) std.mem.Allocator.Error!void {
    self.pinnable_vars.clearRetainingCapacity();
    var external_iter = self.external_pinnable.keyIterator();
    while (external_iter.next()) |var_| {
        try self.pinnable_vars.put(var_.*, {});
    }

    for (open_literal_vars) |literal_var| {
        const resolved = self.types.resolveVar(literal_var);
        if (resolved.desc.content != .flex) continue;
        if (self.varLiteralKind(resolved.var_) == null) continue;
        try self.collectReachableVars(resolved.var_, &self.pinnable_vars);
    }

    for (lambda_param_spans) |arg_span| {
        for (self.cir.store.slicePatterns(arg_span)) |pattern_idx| {
            try self.collectReachableVars(ModuleEnv.varFrom(pattern_idx), &self.pinnable_vars);
        }
    }

    // The receiver-excluded relation walks contribute pinnable vars too. Merge
    // them last, after every plain walk into either set has completed, so no
    // plain walk can early-return on a receiver-pruned entry and drop part of
    // its own closure.
    var relation_iter = self.scheme_relation_reachable_vars.keyIterator();
    while (relation_iter.next()) |var_| {
        try self.external_pinnable.put(var_.*, {});
        try self.pinnable_vars.put(var_.*, {});
    }
}

/// The introducing dispatch expression recorded in a constraint's provenance,
/// or null for a synthetic constraint with no source expression. Provenance is
/// set at creation and copied verbatim by instantiation and unification, so it
/// travels with the constraint instead of alongside it in a var-keyed map.
fn constraintIntroExpr(constraint: StaticDispatchConstraint) ?CIR.Expr.Idx {
    const raw = constraint.provenance.intro_expr.get() orelse return null;
    return @enumFromInt(raw);
}

/// The source expression whose checked value becomes invalid when this
/// dispatch constraint fails. Ordinary dispatch records it in provenance;
/// literal conversions own it through their checked literal plan.
fn constraintSourceExpr(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
) ?CIR.Expr.Idx {
    if (constraintIntroExpr(constraint)) |expr_idx| return expr_idx;
    const literal_kind = constraint.origin.literalKind() orelse return null;
    if (literal_kind == .interpolation) return null;

    const dispatcher_root = self.types.resolveVar(dispatcher_var).var_;
    for (self.cir.store.literalDispatchPlans()) |plan| {
        const kind_matches = switch (literal_kind) {
            .numeral => plan.dispatchKind() == .numeral,
            .quote => plan.dispatchKind() == .quote,
            .interpolation => unreachable,
        };
        if (!kind_matches) continue;
        if (self.types.resolveVar(@enumFromInt(plan.target_var)).var_ != dispatcher_root) continue;
        const node_idx: CIR.Node.Idx = @enumFromInt(plan.node_idx);
        if (!isExprNodeTag(self.cir.store.nodes.get(node_idx).tag)) continue;
        return @enumFromInt(plan.node_idx);
    }
    return null;
}

fn poisonConstraintSourceExpr(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
) Allocator.Error!void {
    return self.poisonConstraintFailureSource(dispatcher_var, constraint, null);
}

fn deferredConstraintFailureExpr(deferred: DeferredConstraintCheck) ?CIR.Expr.Idx {
    const raw = deferred.failure_expr.get() orelse return null;
    return @enumFromInt(raw);
}

fn inheritDeferredConstraintFailureExpr(
    env: *Env,
    start: usize,
    failure_expr: StaticDispatchConstraint.Provenance.OptExprIdx,
) void {
    if (failure_expr == .none) return;
    const items = env.deferred_static_dispatch_constraints.items.items;
    var index = @min(start, items.len);
    while (index < items.len) : (index += 1) {
        if (items[index].failure_expr == .none) {
            items[index].failure_expr = failure_expr;
        }
    }
}

fn poisonConstraintFailureSource(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
    explicit_expr: ?CIR.Expr.Idx,
) Allocator.Error!void {
    const expr_idx = explicit_expr orelse self.constraintSourceExpr(dispatcher_var, constraint) orelse return;
    if (self.cir.store.getExpr(expr_idx) == .e_runtime_error) return;
    const diagnostic_idx = try self.cir.addDiagnostic(.{ .erroneous_value_expr = .{
        .region = self.cir.store.getExprRegion(expr_idx),
    } });
    try self.replaceExprWithRuntimeError(expr_idx, diagnostic_idx);
    try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
}

fn poisonConstraintFailure(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
    env: *Env,
    explicit_expr: ?CIR.Expr.Idx,
) Allocator.Error!void {
    if (explicit_expr) |expr_idx| {
        return self.poisonConstraintFailureSource(dispatcher_var, constraint, expr_idx);
    }

    // An ownerless definition-site replay can precede an owned instantiation
    // replay for the same solved obligation. Resolve that ownership only on the
    // failure path, matching both receiver and method roots so unrelated
    // constraints on the same type cannot acquire each other's owners.
    const dispatcher_root = self.types.resolveVar(dispatcher_var).var_;
    const fn_root = self.types.resolveVar(constraint.fn_var).var_;
    var found_owner = false;
    for (env.deferred_static_dispatch_constraints.items.items) |deferred| {
        const owner_expr = deferredConstraintFailureExpr(deferred) orelse continue;
        if (self.types.resolveVar(deferred.var_).var_ != dispatcher_root) continue;

        for (self.types.sliceStaticDispatchConstraints(deferred.constraints)) |candidate| {
            if (!candidate.fn_name.eql(constraint.fn_name)) continue;
            if (self.types.resolveVar(candidate.fn_var).var_ != fn_root) continue;
            try self.poisonConstraintFailureSource(dispatcher_var, constraint, owner_expr);
            found_owner = true;
            break;
        }
    }

    if (!found_owner) {
        try self.poisonConstraintFailureSource(dispatcher_var, constraint, null);
    }
}

/// Record a dispatch-constrained receiver on the ambiguity worklist (see
/// `ambiguity_candidates`). Exact repeated records are deduplicated here;
/// distinct raw vars that later unify are still deduplicated by the judgment's
/// resolved reported-var set.
fn recordAmbiguityCandidate(
    self: *Self,
    receiver_var: Var,
    source: AmbiguityCandidate.Source,
    instantiation_expr: ?CIR.Expr.Idx,
) std.mem.Allocator.Error!void {
    const dedup_owner = self.active_scheme_root orelse if (instantiation_expr orelse self.instantiation_source_expr) |expr_idx|
        ModuleEnv.varFrom(expr_idx)
    else
        null;
    const key = AmbiguityCandidateKey{
        .var_ = receiver_var,
        .source = source,
        .owner = dedup_owner,
    };
    const requires_current_resolution = self.checking_executable_root and
        self.delayed_dependency_depth == 0 and
        (source == .creation or self.instantiation_is_immediate_callee);
    const entry = try self.ambiguity_candidate_by_key.getOrPut(self.gpa, key);
    if (entry.found_existing) {
        // Repeated observations of one obligation are one judgment candidate,
        // but the payload is monotone: any direct executable observation makes
        // current resolution mandatory. An in-probe observation of a pre-probe
        // candidate flips the flag like any other—the probe's rollback
        // truncates candidate entries, not their payloads, so the flip is
        // journaled (`ambiguity_escalation_journal`) and the probe scope
        // settles it: rollback resets it (no phantom escalation from
        // speculative work), commit keeps it (a committed probe's observation
        // is as real as an unprobed one).
        const candidate_idx = entry.value_ptr.*;
        if (requires_current_resolution and
            !self.ambiguity_candidates.items[candidate_idx].requires_current_resolution)
        {
            if (self.probe_depth > 0) {
                try self.ambiguity_escalation_journal.append(self.gpa, candidate_idx);
            }
            self.ambiguity_candidates.items[candidate_idx].requires_current_resolution = true;
        }
        return;
    }
    errdefer {
        const did_remove = self.ambiguity_candidate_by_key.remove(key);
        std.debug.assert(did_remove);
    }
    entry.value_ptr.* = @intCast(self.ambiguity_candidates.items.len);
    try self.ambiguity_candidates.append(self.gpa, .{
        .var_ = receiver_var,
        .instantiation_expr = instantiation_expr,
        .source = source,
        .dedup_owner = dedup_owner,
        .requires_current_resolution = requires_current_resolution,
    });
}

fn shrinkAmbiguityCandidatesTo(self: *Self, new_len: usize) void {
    while (self.ambiguity_candidates.items.len > new_len) {
        const candidate = self.ambiguity_candidates.pop().?;
        const did_remove = self.ambiguity_candidate_by_key.remove(.{
            .var_ = candidate.var_,
            .source = candidate.source,
            .owner = candidate.dedup_owner,
        });
        std.debug.assert(did_remove);
    }
}

/// The constraint an ambiguity judgment selects for one candidate receiver,
/// plus the facts about it the verdict's report needs.
const AmbiguitySelection = struct {
    constraint: StaticDispatchConstraint,
    is_instantiated_where_clause: bool,
    /// True when every constraint on the receiver is a copied `where` contract.
    /// Any concrete-use origin means this instantiation must resolve now.
    only_where_clause_contracts: bool,
    /// The originating scheme's body provably dispatches this method (see
    /// `body_required` on the `where_clause` origin).
    body_forced: bool,
    /// The in-module dispatch expression that uses this constraint, recovered
    /// from the constraint's provenance.
    where_dispatch_use: ?StaticDispatchUse,
};

/// The origin-policy decision table of the ambiguity judgment: decide whether
/// a flex/rigid dispatch-constrained receiver is even reportable, and if so
/// select the constraint to report. Pure with respect to checker state.
///
/// For an `.instantiation` candidate (a receiver created by instantiating a
/// generalized constrained scheme):
///
/// - A generalized `where`-clause receiver is reportable only when the
///   constraint's body actually requires the method or an in-module dispatch
///   uses it. The caller-pinnability test in `judgeAmbiguityCandidate` then
///   distinguishes a valid polymorphic obligation (the receiver reaches the
///   exported scheme interface or a generalized instantiated function's
///   arguments) from a body-local dead end. This applies equally to direct
///   discards and values discarded through local aliases.
/// - A receiver carrying any literal-conversion constraint (a `from_literal`
///   origin or a `where`-clause contract naming a literal-conversion hook) is
///   skipped: defaulting owns it (at finalize and at generalization
///   boundaries), and a generalized literal resolves per instantiation.
///   Essential for numeric helpers like `|x| x + y` whose receiver carries
///   `desugared_binop` plus `from_numeral`.
/// - `is_eq` constraints are skipped: lowering compares structurally with no
///   owner needed, so a flex `is_eq` placeholder left by valid code
///   (`[1] == [1]`) is not a dead end. A genuinely ambiguous equality on a
///   bare flex value (`poly() == poly()`) is caught through its `.creation`
///   candidate instead, which keys on the expression whose OWN type is the
///   receiver.
/// - `to_hash` is deliberately NOT skipped: a structural hash on a concrete
///   key resolves its receiver before judgment, so what reaches here is a
///   `to_hash` contract on a genuinely undetermined key (issue 9644)—a real
///   dead end reported via the body-forced path like any other unsatisfiable
///   contract.
/// - An instantiated `where`-clause contract gets priority (it is an explicit
///   obligation copied from a signature), but needs an in-module dispatch use
///   or a body-forced contract to be a dead end; a phantom `where`-clause the
///   body never dispatches is not reported.
///
/// For a `.creation` candidate (the constraint was created at a dispatch
/// expression the user wrote): a `where_clause` constraint on the same
/// receiver means the dispatch is part of a declared polymorphic contract, and
/// a literal-conversion constraint means defaulting owns it—either
/// legitimizes the receiver. Only the remaining un-annotated origins
/// (`method_call`, `desugared_binop`, `desugared_unaryop`) can produce an
/// unpinnable flex dispatcher at monomorphization.
fn selectAmbiguityConstraint(
    self: *Self,
    constraints: []const StaticDispatchConstraint,
    source: AmbiguityCandidate.Source,
) Allocator.Error!?AmbiguitySelection {
    switch (source) {
        .instantiation => {
            var first_nonliteral_constraint: ?StaticDispatchConstraint = null;
            var has_literal_constraint = false;
            var only_where_clause_contracts = true;
            for (constraints) |c| {
                if (c.origin != .where_clause) only_where_clause_contracts = false;
                if (self.types.varStaticDispatchRejected(c.fn_var)) continue;
                if (self.constraintIsLiteralConversion(c)) {
                    has_literal_constraint = true;
                } else if (c.fn_name.eql(self.cir.idents.is_eq)) {
                    continue;
                } else if (c.origin != .where_clause and first_nonliteral_constraint == null) {
                    first_nonliteral_constraint = c;
                }
            }
            if (has_literal_constraint) return null;

            // Prefer an explicit where-clause obligation that this program must
            // execute. Phantom contracts do not hide a later body-required one.
            for (constraints) |constraint| {
                if (self.types.varStaticDispatchRejected(constraint.fn_var)) continue;
                if (constraint.origin != .where_clause) continue;
                if (self.constraintIsLiteralConversion(constraint)) continue;
                if (constraint.fn_name.eql(self.cir.idents.is_eq)) continue;

                const body_forced = constraint.origin.where_clause.body_required;
                const where_dispatch_use = try self.findStaticDispatchUseForConstraint(constraint);
                if (where_dispatch_use == null and !body_forced) continue;

                return .{
                    .constraint = constraint,
                    .is_instantiated_where_clause = true,
                    .only_where_clause_contracts = only_where_clause_contracts,
                    .body_forced = body_forced,
                    .where_dispatch_use = where_dispatch_use,
                };
            }

            const constraint = first_nonliteral_constraint orelse return null;
            return .{
                .constraint = constraint,
                .is_instantiated_where_clause = false,
                .only_where_clause_contracts = only_where_clause_contracts,
                .body_forced = false,
                .where_dispatch_use = null,
            };
        },
        .creation => {
            var has_excluded_origin = false;
            var first_constraint: ?StaticDispatchConstraint = null;
            for (constraints) |c| {
                switch (c.origin) {
                    .from_literal, .where_clause => {
                        has_excluded_origin = true;
                    },
                    .method_call, .desugared_binop, .desugared_unaryop => {
                        if (first_constraint == null) first_constraint = c;
                    },
                }
            }
            if (has_excluded_origin) return null;
            const constraint = first_constraint orelse return null;

            return .{
                .constraint = constraint,
                .is_instantiated_where_clause = false,
                .only_where_clause_contracts = false,
                .body_forced = false,
                .where_dispatch_use = null,
            };
        },
    }
}

/// Judge one candidate whose receiver has frozen (generalized, or settled at
/// the end-of-check residual pass): if the origin policy selects a reportable
/// constraint and the receiver resolves into neither pinnable set the event
/// built, no caller can ever pin it—record a verdict for the batch apply.
///
/// An instantiated `where`-clause with an IN-MODULE dispatch use is judged
/// against the stricter `external_pinnable` set: the method is dispatched on
/// this receiver here, so this call must satisfy the copied contract now.
/// Variables exported through the enclosing scheme's arguments or result still
/// count, but lambda parameters local to the already-instantiated call do not
/// (issue 9657: a receiver pinned to a type that lacks the method). Everything
/// else uses the broader set: its dispatch lives in another body (the
/// body-forced hole, issue 9644) or is a direct dispatch on a value a future
/// call can still pin, so an (even nested) lambda parameter an enclosing caller
/// can pin is not a dead end.
fn judgeAmbiguityCandidate(
    self: *Self,
    candidate: AmbiguityCandidate,
    resolved_var: Var,
    resolved_rank: Rank,
    constraints_range: StaticDispatchConstraint.SafeList.Range,
) Allocator.Error!void {
    const constraints = self.types.sliceStaticDispatchConstraints(constraints_range);
    const selection = (try self.selectAmbiguityConstraint(
        constraints,
        candidate.source,
    )) orelse return;

    // A generalized constrained function value can outlive this judgment even
    // when a temporary scheme copy is absent from the current outer root. Its
    // future caller can pin receivers that occur in the function's arguments.
    // Result-only receivers do not qualify here: they must escape through the
    // enclosing scheme interface (covered by the sets below), which distinguishes
    // a generic wrapper from a discarded Json.parse result.
    if (!candidate.requires_current_resolution and
        selection.only_where_clause_contracts and
        resolved_rank == .generalized and
        candidate.source == .instantiation and
        try self.instantiationArgumentsCanPin(candidate.instantiation_expr, resolved_var))
    {
        return;
    }

    const active_pinnable = if (candidate.requires_current_resolution or
        (selection.is_instantiated_where_clause and selection.where_dispatch_use != null))
        &self.external_pinnable
    else
        &self.pinnable_vars;
    if (active_pinnable.contains(resolved_var)) return;

    try self.ambiguity_verdicts.append(self.gpa, .{
        // The candidate's recorded var, not the resolved root: the apply step
        // re-resolves (dedup is by resolved root there), and a body-forced
        // report with no instantiation expression takes its region from the
        // var recorded at the site.
        .var_ = candidate.var_,
        .instantiation_expr = candidate.instantiation_expr,
        .source = candidate.source,
    });
}

fn instantiationArgumentsCanPin(
    self: *Self,
    instantiation_expr: ?CIR.Expr.Idx,
    resolved_var: Var,
) Allocator.Error!bool {
    const expr_idx = instantiation_expr orelse return false;
    const func = self.functionTypeFromVar(ModuleEnv.varFrom(expr_idx)) orelse return false;

    self.var_set.clearRetainingCapacity();
    for (self.types.sliceVars(func.args)) |arg| {
        try self.collectReachableVars(arg, &self.var_set);
    }
    return self.var_set.contains(resolved_var);
}

/// The generalization-time ambiguity rule. Runs immediately after a
/// definition's type variables are promoted to `generalized` rank (and, for a
/// recursion cycle, after the deferred def unifications have settled—a
/// constraint on the function's own type variable that unifies with the
/// definition's scheme is not ambiguous, the issue 9632 lesson): every
/// candidate receiver recorded while checking this def whose var just froze
/// is judged here, against a pinnable frontier local to this one scheme—
/// its argument positions, its own lambdas' parameters, and its still-open
/// literals. A candidate left non-generalized may still be pinned by later
/// defs or the final constraint fixpoint, so it stays on the worklist for the
/// end-of-check residual judgment.
fn judgeAmbiguityCandidatesAtGeneralization(self: *Self, root: BoundaryRoot) Allocator.Error!void {
    try self.judgeAmbiguityCandidatesAtGeneralizationMultiRoot(&.{root});
}

/// `judgeAmbiguityCandidatesAtGeneralization` for a whole binding group: the
/// pinnable frontier includes every member's scheme root.
fn judgeAmbiguityCandidatesAtGeneralizationMultiRoot(
    self: *Self,
    roots: []const BoundaryRoot,
) Allocator.Error!void {
    var sets_built = false;
    for (self.ambiguity_candidates.items[self.ambiguity_candidates_def_start..]) |*candidate| {
        if (candidate.judged) continue;
        const resolved = self.types.resolveVar(candidate.var_);
        const constraints_range = contentConstraintRange(resolved.desc.content) orelse {
            // Grounded to a concrete type (the constraint was or will be
            // discharged by ordinary solving) or poisoned to an error—
            // either way, never ambiguous.
            candidate.judged = true;
            continue;
        };
        if (constraints_range.len() == 0) {
            candidate.judged = true;
            continue;
        }
        if (resolved.desc.rank != .generalized) continue;

        candidate.judged = true;
        if (!sets_built) {
            self.beginAmbiguityPinnableSets();
            for (roots) |root| {
                try self.addAmbiguityPinnableRoot(root.interface, root.owner);
            }
            try self.finishAmbiguityPinnableSets(
                self.open_literal_vars.items[self.open_literal_vars_def_start..],
                self.checked_lambda_params.items[self.checked_lambda_params_def_start..],
            );
            sets_built = true;
        }
        try self.judgeAmbiguityCandidate(candidate.*, resolved.var_, resolved.desc.rank, constraints_range);
    }
}

/// End-of-check residual judgment for candidates that never hit a
/// generalization event: receivers in value-restricted bindings (which stay
/// open to pinning by later defs and by the final constraint fixpoint, so
/// judging them at def finalization would be premature) and instantiations
/// performed outside any def. Judged once here at the settled state, against
/// the whole module's remaining open surface—every top-level callable def's
/// interface plus all recorded lambda parameters and open literals. Gated on
/// pending candidates: a module whose receivers all resolved or were judged at
/// generalization does zero work here.
fn judgeResidualAmbiguityCandidates(self: *Self) Allocator.Error!void {
    var any_pending = false;
    for (self.ambiguity_candidates.items) |candidate| {
        if (!candidate.judged) {
            any_pending = true;
            break;
        }
    }
    if (!any_pending) return;

    self.beginAmbiguityPinnableSets();
    for (0..self.cir.all_defs.span.len) |def_offset| {
        const def_idx = self.cir.store.defAt(self.cir.all_defs, def_offset);
        const def_var = ModuleEnv.varFrom(def_idx);
        if (self.types.varResolvesToFunction(def_var)) {
            try self.addAmbiguityPinnableRoot(def_var, def_var);
        }
    }
    try self.finishAmbiguityPinnableSets(
        self.open_literal_vars.items,
        self.checked_lambda_params.items,
    );

    for (self.ambiguity_candidates.items) |*candidate| {
        if (candidate.judged) continue;
        candidate.judged = true;
        const resolved = self.types.resolveVar(candidate.var_);
        const constraints_range = contentConstraintRange(resolved.desc.content) orelse continue;
        if (constraints_range.len() == 0) continue;
        try self.judgeAmbiguityCandidate(candidate.*, resolved.var_, resolved.desc.rank, constraints_range);
    }
}

fn findStaticDispatchUseForConstraint(
    self: *Self,
    constraint: StaticDispatchConstraint,
) Allocator.Error!?StaticDispatchUse {
    const method_name = constraint.fn_name;
    const expr_idx = constraintIntroExpr(constraint) orelse return null;
    if (self.cir.store.getExpr(expr_idx) == .e_runtime_error) return null;

    const expr = self.cir.store.getExpr(expr_idx);
    if (expr != .e_dispatch_call and expr != .e_type_dispatch_call) return null;
    if (expr == .e_dispatch_call) {
        if (!expr.e_dispatch_call.method_name.eql(method_name)) return null;
    } else {
        if (!expr.e_type_dispatch_call.method_name.eql(method_name)) return null;
    }

    return .{
        .expr_idx = expr_idx,
        .region = self.cir.store.getExprRegion(expr_idx),
    };
}

/// Apply the ambiguity verdicts collected by the local judgments: emit each
/// `MISSING METHOD` problem and mark the offending expressions runtime errors
/// so lowering never reaches an ownerless dispatch. Applying is batched here,
/// at the settled end-of-check state, for two reasons: problem order stays
/// stable (all ambiguity reports follow the other end-of-check reports, as
/// they always have), and poisoning an expression mid-check would perturb the
/// checking of everything downstream of it.
///
/// Verdicts share one dedup set keyed by resolved dispatcher var, so a
/// receiver judged through several candidates—or reachable through several
/// aliased vars—is reported once. Instantiation verdicts apply first
/// because they produce the more informative two-region diagnostic; creation
/// verdicts then cover the direct cases (`poly().to_i128()`,
/// `poly() == poly()`) where the dispatch is created at the use site rather
/// than copied by an instantiation.
fn applyAmbiguityVerdicts(self: *Self) std.mem.Allocator.Error!void {
    if (builtin.mode == .Debug) {
        // The residual judgment just ran: an unjudged candidate here would
        // mean a dispatch-constrained receiver escaped both the
        // generalization events and the end-of-check pass—a worklist bug,
        // and exactly the kind of hole that lets an ambiguous dispatch reach
        // monotype lowering.
        for (self.ambiguity_candidates.items) |candidate| {
            std.debug.assert(candidate.judged);
        }
    }

    if (self.ambiguity_verdicts.items.len == 0) return;

    self.reported_dispatch_vars.clearRetainingCapacity();
    for (self.ambiguity_verdicts.items) |verdict| {
        if (verdict.source != .instantiation) continue;
        try self.applyInstantiationAmbiguityVerdict(verdict);
    }
    try self.applyCreationAmbiguityVerdicts();
}

/// Apply one `.instantiation` ambiguity verdict. The judgment already
/// established the receiver is unpinnable (see `judgeAmbiguityCandidate`);
/// everything else is re-derived here at the settled state, because the final
/// constraint fixpoint and the poison passes ran between judgment and apply—
/// a receiver they grounded or erred is silently acquitted.
fn applyInstantiationAmbiguityVerdict(self: *Self, verdict: AmbiguityVerdict) std.mem.Allocator.Error!void {
    const resolved = self.types.resolveVar(verdict.var_);
    const constraints_range = contentConstraintRange(resolved.desc.content) orelse return;
    if (constraints_range.len() == 0) return;
    if (self.reported_dispatch_vars.contains(resolved.var_)) return;

    // Re-run the origin-policy selection (see `selectAmbiguityConstraint` for
    // the decision table) so the reported constraint reflects the settled
    // state.
    const constraints = self.types.sliceStaticDispatchConstraints(constraints_range);
    const selection = (try self.selectAmbiguityConstraint(
        constraints,
        .instantiation,
    )) orelse return;
    const constraint = selection.constraint;
    const is_instantiated_where_clause = selection.is_instantiated_where_clause;
    const body_forced = selection.body_forced;
    const where_dispatch_use = selection.where_dispatch_use;

    // Locate the call site that left this receiver undetermined. Instantiated
    // where-clause contracts carry exact dispatch-expression metadata, so
    // they can report directly at that call. Ordinary hidden dispatches need
    // the structural scan: the receiver var is internal to the instantiated
    // callee type, so no expression's own type IS the receiver. Instead it
    // flows into one of a call's ARGUMENTS, whose type structurally CONTAINS
    // it in a DATA position (a tag payload, record field, tuple element, or
    // nominal argument), never inside a function type. That data-position
    // requirement distinguishes a genuine hole from a polymorphic function
    // passed as a value: in `get(none({}))` the receiver is the tag payload
    // of the `FfiOption` argument and is genuinely undetermined; in
    // `Str.inspect(f)` where `f = |x| x + 1`, the receiver is `f`'s parameter,
    // an uncalled function value whose parameter a future call would pin. A
    // higher-order constraint that IS applied, like the `e_higher_order`
    // corpus case, is caught through its creation verdict instead.
    var primary: ?Region = null;
    var secondary: ?Region = null;
    var runtime_error_inserted = false;
    if (is_instantiated_where_clause and where_dispatch_use != null) {
        const dispatch_use = where_dispatch_use.?;
        primary = dispatch_use.region;
        runtime_error_inserted = true;

        if (self.cir.store.getExpr(dispatch_use.expr_idx) != .e_runtime_error) {
            const diagnostic_idx = try self.cir.addDiagnostic(.{ .erroneous_value_expr = .{
                .region = dispatch_use.region,
            } });
            try self.replaceExprWithRuntimeError(dispatch_use.expr_idx, diagnostic_idx);
        }
    } else if (body_forced) {
        // A body-forced where-clause with no in-module dispatch use (the
        // unpinned receiver lives only in the instantiating call's result
        // type, e.g. the `Dict(x, y)` returned by `Dict.join_map(...)`). The
        // candidate recorded the exact expression whose instantiation created
        // the obligation, so report there and mark it a runtime error—codegen
        // then emits a crash instead of reaching the ownerless dispatch.
        if (verdict.instantiation_expr) |inst_expr| {
            primary = self.cir.store.getExprRegion(inst_expr);
            runtime_error_inserted = true;
            if (self.cir.store.getExpr(inst_expr) != .e_runtime_error) {
                const diagnostic_idx = try self.cir.addDiagnostic(.{ .erroneous_value_expr = .{
                    .region = primary.?,
                } });
                try self.replaceExprWithRuntimeError(inst_expr, diagnostic_idx);
            }
        } else {
            // A constraint with no source expression cannot be executed
            // directly. It still reports at its checked type region; any
            // concrete value use that forces it is poisoned by the use-site
            // paths above.
            primary = self.getRegionAt(verdict.var_);
        }
    } else {
        var raw_node_idx: u32 = 0;
        while (raw_node_idx < self.cir.store.nodes.len()) : (raw_node_idx += 1) {
            const node_idx: CIR.Node.Idx = @enumFromInt(raw_node_idx);
            if (!isExprNodeTag(self.cir.store.nodes.get(node_idx).tag)) continue;

            const expr_idx: CIR.Expr.Idx = @enumFromInt(raw_node_idx);
            if (self.cir.store.getExpr(expr_idx) == .e_runtime_error) continue;
            const expr = self.cir.store.getExpr(expr_idx);
            if (expr != .e_call) continue;
            const call = expr.e_call;

            var arg_region: ?Region = null;
            for (self.cir.store.sliceExpr(call.args)) |arg_idx| {
                self.var_set.clearRetainingCapacity();
                try self.collectDataReachableVars(ModuleEnv.varFrom(arg_idx), &self.var_set);
                if (self.var_set.contains(resolved.var_)) {
                    arg_region = self.cir.store.getExprRegion(arg_idx);
                    break;
                }
            }
            if (arg_region == null) continue;

            if (primary == null) {
                primary = self.cir.store.getExprRegion(expr_idx);
                secondary = arg_region;
            }

            const diagnostic_idx = try self.cir.addDiagnostic(.{ .erroneous_value_expr = .{
                .region = self.cir.store.getExprRegion(expr_idx),
            } });
            try self.replaceExprWithRuntimeError(expr_idx, diagnostic_idx);
            runtime_error_inserted = true;
        }
    }

    // No expression passes the receiver in the relevant position: an ordinary
    // hidden dispatch whose receiver is a polymorphic function value's own
    // parameter, which a future call can still pin—not a dead end.
    if (primary == null) return;

    try self.reported_dispatch_vars.put(resolved.var_, {});

    const primary_region = primary.?;
    const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, resolved.var_);
    const is_binop = constraint.origin == .desugared_binop;

    _ = try self.problems.appendProblem(self.gpa, .{ .static_dispatch = .{ .unresolved_dispatcher = .{
        .region = primary_region,
        .secondary_region = secondary,
        .dispatcher_snapshot = snapshot,
        .method_name = constraint.fn_name,
        .is_binop = is_binop,
        .binop_negated = constraint.origin.binopNegated(),
        .runtime_error_inserted = runtime_error_inserted,
    } } });
}

/// Validate the static-dispatch contracts copied out of generalized schemes
/// after an instantiation's caller has had a chance to pin them. Ordinary
/// unification records deferred checks while a constrained flex unifies with a
/// concrete type, but instantiating a polymorphic where-clause starts with a
/// fresh constrained flex that may only resolve after later call-site evidence.
/// Re-checking the recorded range here makes that concrete owner validation
/// explicit and leaves unresolved cases to the ambiguity verdicts.
///
/// The fixpoint returns once a round leaves no new dispatcher entry and no
/// newly grounded pending requirement. It terminates structurally: a pending
/// requirement grounds at most once (flex to non-flex is monotone) and takes
/// exactly one deferred-queue transition (the `deferred_enqueued` latch),
/// while dispatcher entries are minted dispatch edges, which the lineage
/// detectors keep finite.
fn checkInstantiatedStaticDispatchConstraints(
    self: *Self,
    env: *Env,
    is_numeric_default_pass: bool,
) std.mem.Allocator.Error!void {
    // This fixpoint compacts the pending index and advances the checked-prefix
    // cursor—positional state no probe savepoint captures. It must only run
    // outside every speculative save/restore window.
    std.debug.assert(self.probe_depth == 0);
    while (true) {
        const start = self.instantiation_dispatchers_checked;
        const end = self.instantiation_dispatchers.items.len;
        self.instantiation_dispatchers_checked = end;
        var appended_deferred = false;

        // New dispatchers take their one compatibility transition here. Flex
        // scheme requirements wait on the compact pending index below; the
        // completed prefix is never rescanned.
        var dispatcher_idx = start;
        while (dispatcher_idx < end) : (dispatcher_idx += 1) {
            // Compatibility validation can instantiate a method scheme and
            // grow this list, so copy the entry after re-fetching it by index;
            // never retain a slice across that operation.
            const dispatcher = self.instantiation_dispatchers.items[dispatcher_idx];
            if (dispatcher.constraints.len() == 0) continue;

            if (!dispatcher.compatibility_checked) {
                self.instantiation_dispatchers.items[dispatcher_idx].compatibility_checked = true;

                // The ambiguity judgment has already decided which generalized
                // instantiations are unpinnable. Only those receivers are
                // materialized through the specialization default at this use.
                if (self.hasInstantiationAmbiguityVerdict(dispatcher.dispatcher_var)) {
                    _ = try self.checkFlexVarConstraintCompatibility(
                        dispatcher.dispatcher_var,
                        env,
                        is_numeric_default_pass,
                        .{
                            .allow_generalized = true,
                            .allow_arithmetic_default = true,
                            .error_expr = dispatcher.instantiation_expr,
                        },
                    );
                }
            }

            const current = self.instantiation_dispatchers.items[dispatcher_idx];
            if (current.deferred_enqueued) continue;
            if (current.source == .scheme_requirement) {
                // A concrete copy was queued when it was instantiated. A flex
                // copy was intentionally kept out of the hot queue; enqueue it
                // exactly once whenever any work in this fixpoint grounds it.
                if (self.types.resolveVar(current.dispatcher_var).desc.content == .flex) continue;
            }

            self.instantiation_dispatchers.items[dispatcher_idx].deferred_enqueued = true;
            try self.enqueueDeferredDispatchConstraint(env, .{
                .var_ = current.dispatcher_var,
                .constraints = current.constraints,
                .failure_expr = if (current.instantiation_expr) |expr_idx|
                    .from(@intFromEnum(expr_idx))
                else
                    .none,
            }, .{ .recorded = current.owner_group_index });
            appended_deferred = true;
        }

        // Revisit only explicit requirements that previously remained flex.
        // Compatibility or ordinary dispatch in this round may have grounded
        // them even though their dispatcher lies before the cursor.
        if (try self.drainGroundedPendingSchemeRequirementDispatchers(env)) {
            appended_deferred = true;
        }

        if (appended_deferred) {
            try self.checkStaticDispatchConstraints(env, is_numeric_default_pass);
            try self.checkAllConstraints(env);
        }
        if (self.instantiation_dispatchers_checked == self.instantiation_dispatchers.items.len and
            !self.anyPendingSchemeRequirementNewlyGrounded()) return;
    }
}

/// Whether any explicit scheme requirement still waiting in the compact
/// pending index was grounded by this round's drain without yet taking its
/// one deferred-queue transition. Such an entry means another round can make
/// progress even though no new dispatcher entry was appended.
fn anyPendingSchemeRequirementNewlyGrounded(self: *Self) bool {
    for (self.pending_scheme_requirement_dispatchers.items) |pending_idx| {
        const pending = self.instantiation_dispatchers.items[pending_idx];
        if (pending.deferred_enqueued) continue;
        if (self.types.resolveVar(pending.dispatcher_var).desc.content == .flex) continue;
        return true;
    }
    return false;
}

fn hasInstantiationAmbiguityVerdict(self: *Self, var_: Var) bool {
    const root = self.types.resolveVar(var_).var_;
    for (self.ambiguity_verdicts.items) |verdict| {
        if (verdict.source != .instantiation) continue;
        if (self.types.resolveVar(verdict.var_).var_ == root) return true;
    }
    return false;
}

/// Apply the `.creation` ambiguity verdicts: for each unpinnable receiver
/// whose constraint was created directly at a dispatch expression, report at
/// the first (innermost, node-order) expression whose own type is the
/// receiver—that lands the underline on the dispatch use—and mark it a
/// runtime error so lowering never reaches an ownerless dispatch. The node
/// walk only runs when creation verdicts exist, i.e. on the error path; a
/// clean module never scans.
fn applyCreationAmbiguityVerdicts(self: *Self) std.mem.Allocator.Error!void {
    // Gather the verdict vars, re-resolved at the settled state and
    // re-validated through the origin-policy selection—the final constraint
    // fixpoint and poison passes ran between judgment and apply, and a
    // receiver they grounded or erred is silently acquitted.
    self.ambiguity_verdict_vars.clearRetainingCapacity();
    for (self.ambiguity_verdicts.items) |verdict| {
        if (verdict.source != .creation) continue;
        const resolved = self.types.resolveVar(verdict.var_);
        const constraints_range = contentConstraintRange(resolved.desc.content) orelse continue;
        if (constraints_range.len() == 0) continue;
        if (self.reported_dispatch_vars.contains(resolved.var_)) continue;
        try self.ambiguity_verdict_vars.put(resolved.var_, {});
    }
    if (self.ambiguity_verdict_vars.count() == 0) return;

    // Walk expressions in node order; flag any whose own type var is a
    // verdict receiver. Dedup by resolved var id (using the set shared with
    // the instantiation verdicts) so a value flowing through multiple
    // expressions—or already reported per-instantiation—is reported once.
    var raw_node_idx: u32 = 0;
    while (raw_node_idx < self.cir.store.nodes.len()) : (raw_node_idx += 1) {
        const node_idx: CIR.Node.Idx = @enumFromInt(raw_node_idx);
        if (!isExprNodeTag(self.cir.store.nodes.get(node_idx).tag)) continue;

        const expr_idx: CIR.Expr.Idx = @enumFromInt(raw_node_idx);
        if (self.cir.store.getExpr(expr_idx) == .e_runtime_error) continue;

        const resolved = self.types.resolveVar(ModuleEnv.varFrom(expr_idx));
        if (!self.ambiguity_verdict_vars.contains(resolved.var_)) continue;
        const constraints_range = contentConstraintRange(resolved.desc.content) orelse continue;
        if (self.reported_dispatch_vars.contains(resolved.var_)) continue;

        // Re-select the constraint to report at the settled state (see
        // `selectAmbiguityConstraint` for the decision table).
        const constraints = self.types.sliceStaticDispatchConstraints(constraints_range);
        const selection = (try self.selectAmbiguityConstraint(
            constraints,
            .creation,
        )) orelse continue;
        const constraint = selection.constraint;

        try self.reported_dispatch_vars.put(resolved.var_, {});

        const region = self.cir.store.getExprRegion(expr_idx);
        const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, resolved.var_);

        const is_binop = constraint.origin == .desugared_binop;

        _ = try self.problems.appendProblem(self.gpa, .{ .static_dispatch = .{ .unresolved_dispatcher = .{
            .region = region,
            .secondary_region = null,
            .dispatcher_snapshot = snapshot,
            .method_name = constraint.fn_name,
            .is_binop = is_binop,
            .binop_negated = constraint.origin.binopNegated(),
            .runtime_error_inserted = true,
        } } });

        const diagnostic_idx = try self.cir.addDiagnostic(.{ .erroneous_value_expr = .{
            .region = region,
        } });
        try self.replaceExprWithRuntimeError(expr_idx, diagnostic_idx);
    }
}

/// Collect, into `out`, `var_`'s resolved id and every resolved var id
/// structurally reachable from it (tuples, records, tag payloads, function args
/// and rets). Used to mark complete scheme interfaces and local pinning sources.
fn collectReachableVars(self: *Self, var_: Var, out: *std.AutoHashMap(Var, void)) std.mem.Allocator.Error!void {
    return self.collectReachableVarsExcluding(var_, null, out);
}

/// `collectReachableVars` with one resolved root treated as an opaque boundary.
/// This is the exact traversal needed for explicit scheme relations: their
/// callable structure is interface data, but walking through the shared
/// receiver would pull in unrelated sibling constraints.
fn collectReachableVarsExcluding(
    self: *Self,
    var_: Var,
    excluded_root: ?Var,
    out: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!void {
    const resolved = self.types.resolveVar(var_);
    if (excluded_root) |excluded| {
        const visit = SchemeReachabilityVisit{ .var_ = resolved.var_, .excluded_root = excluded };
        if (self.scheme_relation_reachability.contains(visit)) return;
        try self.scheme_relation_reachability.put(visit, {});
        if (resolved.var_ == excluded) return;
    } else if (out.contains(resolved.var_)) return;
    try out.put(resolved.var_, {});

    switch (resolved.desc.content) {
        .err, .field_presence => {},
        // A constrained type variable's `where` constraints relate it to other
        // type variables through the constraint method's signature. For example
        // `c.is_eq : c, d -> f` makes `d` and `f` reachable from `c`; following
        // `f.not : f -> e` then reaches `e`. When `c` is parameter-pinnable, every
        // variable reachable through its constraint signatures is pinnable too,
        // because instantiating the parameter instantiates the whole constraint
        // chain. (This is the spec's "recurse fully into arg structure".)
        .flex, .rigid => {
            const constraints_range = contentConstraintRange(resolved.desc.content) orelse unreachable;
            const constraints = self.types.sliceStaticDispatchConstraints(constraints_range);
            for (constraints) |constraint| {
                try self.collectReachableVarsExcluding(constraint.fn_var, excluded_root, out);
            }
        },
        .alias => |alias| try self.collectReachableVarsExcluding(self.types.getAliasBackingVar(alias), excluded_root, out),
        .structure => |flat| switch (flat) {
            .tuple => |tuple| {
                for (self.types.sliceVars(tuple.elems)) |elem| {
                    try self.collectReachableVarsExcluding(elem, excluded_root, out);
                }
            },
            .nominal_type => |nominal| {
                for (self.types.sliceNominalArgs(nominal)) |arg| {
                    try self.collectReachableVarsExcluding(arg, excluded_root, out);
                }
            },
            .fn_pure, .fn_effectful, .fn_unbound => |func| {
                for (self.types.sliceVars(func.args)) |arg| {
                    try self.collectReachableVarsExcluding(arg, excluded_root, out);
                }
                try self.collectReachableVarsExcluding(func.ret, excluded_root, out);
            },
            .record => |record| {
                const fields = self.types.getRecordFieldsSlice(record.fields);
                for (fields.items(.presence)) |presence| {
                    try self.collectReachableVarsExcluding(presence.typeVar(), excluded_root, out);
                    if (presence.presenceVar()) |presence_var| {
                        try self.collectReachableVarsExcluding(presence_var, excluded_root, out);
                    }
                }
                try self.collectReachableVarsExcluding(record.ext, excluded_root, out);
            },
            .record_unbound => |fields_range| {
                const fields = self.types.getRecordFieldsSlice(fields_range);
                for (fields.items(.presence)) |presence| {
                    try self.collectReachableVarsExcluding(presence.typeVar(), excluded_root, out);
                    if (presence.presenceVar()) |presence_var| {
                        try self.collectReachableVarsExcluding(presence_var, excluded_root, out);
                    }
                }
            },
            .tag_union => |tag_union| {
                const tags = self.types.getTagsSlice(tag_union.tags);
                for (tags.items(.args)) |tag_args| {
                    for (self.types.sliceVars(tag_args)) |arg| {
                        try self.collectReachableVarsExcluding(arg, excluded_root, out);
                    }
                }
                try self.collectReachableVarsExcluding(tag_union.ext, excluded_root, out);
            },
            .empty_record, .empty_tag_union => {},
        },
    }
}

/// Like `collectReachableVars`, but does NOT descend into FUNCTION types at all—
/// only into data positions (tag payloads, record fields, tuple elements, nominal
/// args). A var reachable this way is part of the actual data flowing through
/// `var_`, not a parameter or result of a function value carried by `var_`. The
/// instantiation-verdict apply uses this to distinguish a genuinely
/// undetermined dispatch receiver passed as data (report) from a parameter of an
/// uncalled polymorphic function value (do not report)—e.g. in `Str.inspect(f)`
/// where `f = |x| x + 1`, the receiver is `f`'s parameter and the `+`-preserving
/// return both live inside the function type, so neither is reached here.
fn collectDataReachableVars(self: *Self, var_: Var, out: *std.AutoHashMap(Var, void)) std.mem.Allocator.Error!void {
    const resolved = self.types.resolveVar(var_);
    if (out.contains(resolved.var_)) return;
    try out.put(resolved.var_, {});

    switch (resolved.desc.content) {
        .alias => |alias| try self.collectDataReachableVars(self.types.getAliasBackingVar(alias), out),
        .structure => |flat| switch (flat) {
            .tuple => |tuple| {
                for (self.types.sliceVars(tuple.elems)) |elem| {
                    try self.collectDataReachableVars(elem, out);
                }
            },
            .nominal_type => |nominal| {
                for (self.types.sliceNominalArgs(nominal)) |arg| {
                    try self.collectDataReachableVars(arg, out);
                }
            },
            // A function value is not data: its parameters and result are
            // determined by a future call, not by the value passed here, so we do
            // not descend into it at all.
            .fn_pure, .fn_effectful, .fn_unbound => {},
            .record => |record| {
                const fields = self.types.getRecordFieldsSlice(record.fields);
                for (fields.items(.presence)) |presence| {
                    {
                        const field_var = presence.typeVar();
                        try self.collectDataReachableVars(field_var, out);
                    }
                }
                try self.collectDataReachableVars(record.ext, out);
            },
            .record_unbound => |fields_range| {
                const fields = self.types.getRecordFieldsSlice(fields_range);
                for (fields.items(.presence)) |presence| {
                    {
                        const field_var = presence.typeVar();
                        try self.collectDataReachableVars(field_var, out);
                    }
                }
            },
            .tag_union => |tag_union| {
                const tags = self.types.getTagsSlice(tag_union.tags);
                for (tags.items(.args)) |tag_args| {
                    for (self.types.sliceVars(tag_args)) |arg| {
                        try self.collectDataReachableVars(arg, out);
                    }
                }
                try self.collectDataReachableVars(tag_union.ext, out);
            },
            .empty_record, .empty_tag_union => {},
        },
        .flex, .rigid, .field_presence, .err => {},
    }
}

fn reportPolymorphicTopLevelValues(self: *Self) std.mem.Allocator.Error!void {
    for (0..self.cir.all_defs.span.len) |def_offset| {
        const def_idx = self.cir.store.defAt(self.cir.all_defs, def_offset);
        const def = self.cir.store.getDef(def_idx);
        const def_var = ModuleEnv.varFrom(def_idx);

        if (self.erroneous_value_patterns.contains(def.pattern)) continue;
        // A function—including a zero-arg thunk (`|| …`)—may generalize to a
        // polymorphic type: each call site monomorphizes its return. Only a
        // non-function top-level *value* must be concrete, since it is computed
        // once and needs a single representation. (A thunk whose return is left
        // open is therefore allowed; if it is an app entry the platform's
        // `requires` type unifies it to a concrete type anyway.)
        if (self.varIsFunctionType(def_var)) continue;

        self.var_set.clearRetainingCapacity();
        if (!try self.varHasUnresolvedStaticDispatchConstraints(def_var, &self.var_set)) continue;

        try self.reportPolymorphicValueProblem(def_var, ModuleEnv.varFrom(def.pattern), self.getPatternIdent(def.pattern));
    }
}

fn reportPolymorphicExecutableRootResults(self: *Self) std.mem.Allocator.Error!void {
    for (self.executable_root_defs.items) |def_idx| {
        const def = self.cir.store.getDef(def_idx);
        if (self.erroneous_value_patterns.contains(def.pattern)) continue;

        const result_var = self.zeroArgFunctionReturnVar(ModuleEnv.varFrom(def_idx)) orelse continue;

        self.var_set.clearRetainingCapacity();
        if (!try self.varHasUnresolvedNonLiteralStaticDispatchConstraints(result_var, &self.var_set)) continue;

        try self.reportPolymorphicValueProblem(result_var, ModuleEnv.varFrom(def.pattern), self.getPatternIdent(def.pattern));
    }
}

fn reportPolymorphicConstrainedExpr(self: *Self, expr_idx: CIR.Expr.Idx) std.mem.Allocator.Error!void {
    const expr_var = ModuleEnv.varFrom(expr_idx);
    if (self.varIsFunctionType(expr_var)) return;

    self.var_set.clearRetainingCapacity();
    if (!try self.varHasUnresolvedStaticDispatchConstraints(expr_var, &self.var_set)) return;

    try self.reportPolymorphicValueProblem(expr_var, expr_var, null);
}

fn reportPolymorphicValueProblem(
    self: *Self,
    snapshot_var: Var,
    region_var: Var,
    def_name: ?Ident.Idx,
) std.mem.Allocator.Error!void {
    const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, snapshot_var);
    _ = try self.problems.appendProblem(self.gpa, .{ .polymorphic_value = .{
        .var_ = region_var,
        .snapshot = snapshot,
        .def_name = def_name,
    } });
}

fn checkExpectBody(
    self: *Self,
    body: CIR.Expr.Idx,
    env: *Env,
    expected: Expected,
    expect_region: Region,
) std.mem.Allocator.Error!bool {
    const slot: ExpectEffectSlotId = @enumFromInt(self.expect_effect_slots.items.len);
    try self.expect_effect_slots.append(self.gpa, .{ .region = expect_region });

    const saved_expect_slot = self.current_expect_effect_slot;
    self.current_expect_effect_slot = slot;
    defer self.current_expect_effect_slot = saved_expect_slot;

    const does_fx = try self.checkExpr(body, env, expected.suppressComptimeConditionWarnings().suppressHoistSelection());
    self.expect_effect_slots.items[@intFromEnum(slot)].effectful = does_fx;
    return does_fx;
}

fn recordCurrentExpectDispatchWatcher(self: *Self, fn_var: Var) Allocator.Error!void {
    const slot = self.current_expect_effect_slot orelse return;
    try self.expect_dispatch_effect_watchers.append(self.gpa, .{ .slot = slot, .fn_var = fn_var });
}

/// Record a committed successful dispatch edge. Expect watchers are resolved
/// once at the checked boundary, after all roots have settled; storing the raw
/// var preserves the exact edge while finalization normalizes roots in one
/// linear pass. Probes never publish success—the committed relation is revisited
/// by the ordinary dispatch pass.
fn recordSuccessfulStaticDispatch(self: *Self, constraint: StaticDispatchConstraint) Allocator.Error!void {
    if (self.probe_depth != 0 or self.expect_dispatch_effect_watchers.items.len == 0) return;
    try self.successful_dispatch_fn_vars.append(self.gpa, constraint.fn_var);
}

fn finalizeExpectEffectSlots(self: *Self) Allocator.Error!void {
    std.debug.assert(self.current_expect_effect_slot == null);
    if (self.expect_effect_slots.items.len == 0) return;

    if (self.expect_dispatch_effect_watchers.items.len > 0) {
        var successful_roots: std.AutoHashMapUnmanaged(Var, void) = .empty;
        defer successful_roots.deinit(self.gpa);
        try successful_roots.ensureTotalCapacity(self.gpa, @intCast(self.successful_dispatch_fn_vars.items.len));
        for (self.successful_dispatch_fn_vars.items) |fn_var| {
            successful_roots.putAssumeCapacity(self.types.resolveVar(fn_var).var_, {});
        }

        // Finalization runs after the last type mutation, so one memo serves
        // every watcher. Ordinary effect queries clear this cache because roots
        // may change between calls; no such invalidation is possible here.
        self.function_effect_resolution.clearRetainingCapacity();

        for (self.expect_dispatch_effect_watchers.items) |watcher| {
            const fn_root = self.types.resolveVar(watcher.fn_var).var_;
            if (!successful_roots.contains(fn_root)) continue;
            if (try self.functionEffectStateHelp(fn_root) == .effectful) {
                self.expect_effect_slots.items[@intFromEnum(watcher.slot)].effectful = true;
            }
        }
    }

    for (self.expect_effect_slots.items) |slot| {
        if (!slot.effectful) continue;
        _ = try self.problems.appendProblem(self.gpa, .{ .effectful_expect = .{
            .region = slot.region,
        } });
    }
}

fn varIsFunctionType(self: *Self, var_: Var) bool {
    var current = var_;
    while (true) {
        const resolved = self.types.resolveVar(current);
        switch (resolved.desc.content) {
            .alias => |alias| {
                current = self.types.getAliasBackingVar(alias);
                continue;
            },
            .structure => |flat| return switch (flat) {
                .fn_pure, .fn_effectful, .fn_unbound => true,
                .record, .record_unbound, .tuple, .nominal_type, .empty_record, .tag_union, .empty_tag_union => false,
            },
            .err, .flex, .rigid, .field_presence => return false,
        }
    }
}

fn zeroArgFunctionReturnVar(self: *Self, var_: Var) ?Var {
    var current = var_;
    while (true) {
        const resolved = self.types.resolveVar(current);
        switch (resolved.desc.content) {
            .alias => |alias| {
                current = self.types.getAliasBackingVar(alias);
                continue;
            },
            .structure => |flat| return switch (flat) {
                .fn_pure, .fn_effectful, .fn_unbound => |func| if (func.args.len() == 0) func.ret else null,
                .record, .record_unbound, .tuple, .nominal_type, .empty_record, .tag_union, .empty_tag_union => null,
            },
            .err, .flex, .rigid, .field_presence => return null,
        }
    }
}

fn varIsEffectfulFunction(self: *Self, var_: Var) Allocator.Error!bool {
    return try self.functionEffectState(var_) == .effectful;
}

/// Resolve the directed effect formula carried by a function type. The memo is
/// per query because union-find roots can change after any subsequent
/// unification. A visiting back-edge contributes no effect by itself; this is
/// the SCC base case, while any positive or unresolved dependency reachable
/// outside the cycle still propagates back to every caller in the cycle.
fn functionEffectState(self: *Self, var_: Var) Allocator.Error!FunctionEffectState {
    self.function_effect_resolution.clearRetainingCapacity();
    return self.functionEffectStateHelp(var_);
}

fn functionEffectStateHelp(self: *Self, var_: Var) Allocator.Error!FunctionEffectState {
    const resolved = self.types.resolveVar(var_);
    const root = resolved.var_;
    if (self.function_effect_resolution.get(root)) |memo| return memo.state();

    try self.function_effect_resolution.put(root, .visiting);
    const state: FunctionEffectState = switch (resolved.desc.content) {
        .alias => |alias| try self.functionEffectStateHelp(self.types.getAliasBackingVar(alias)),
        .err, .field_presence => .pure,
        .flex, .rigid => .unresolved,
        .structure => |flat| switch (flat) {
            .fn_pure, .fn_effectful, .fn_unbound => |func| blk: {
                var result: FunctionEffectState = switch (flat) {
                    .fn_pure => .pure,
                    .fn_effectful => .effectful,
                    .fn_unbound => if (func.effect_deps.len() == 0) .unresolved else .pure,
                    .record, .record_unbound, .tuple, .nominal_type, .empty_record, .tag_union, .empty_tag_union => unreachable,
                };
                if (result == .effectful) break :blk result;

                var i: u32 = 0;
                while (i < func.effect_deps.len()) : (i += 1) {
                    switch (try self.functionEffectStateHelp(self.types.getVarAt(func.effect_deps, i))) {
                        .effectful => {
                            result = .effectful;
                            break;
                        },
                        .unresolved => result = .unresolved,
                        .pure => {},
                    }
                }
                break :blk result;
            },
            .record, .record_unbound, .tuple, .nominal_type, .empty_record, .tag_union, .empty_tag_union => .pure,
        },
    };

    try self.function_effect_resolution.put(root, switch (state) {
        .pure => .pure,
        .effectful => .effectful,
        .unresolved => .unresolved,
    });
    return state;
}

fn recordCurrentFunctionEffectDependency(self: *Self, function_var: Var) Allocator.Error!void {
    if (self.function_effect_dependency_frame_starts.items.len == 0) return;
    const root = self.types.resolveVar(function_var).var_;
    const start = self.function_effect_dependency_frame_starts.items[self.function_effect_dependency_frame_starts.items.len - 1];
    for (self.pending_function_effect_dependencies.items[start..]) |existing| {
        if (self.types.resolveVar(existing).var_ == root) return;
    }
    try self.pending_function_effect_dependencies.append(self.gpa, root);
}

/// A dispatch can be evaluated as one module-level constant only when checking
/// has fixed both parts that make the operation context-independent: its
/// checked callable is not effectful and its complete dispatcher type is
/// concrete.
/// A constrained or otherwise open dispatcher needs specialization-edge
/// evidence, so selecting it as a caller-less compile-time root would erase the
/// evidence scope that gives the dispatch meaning.
fn staticDispatchAllowsHoistedRoot(self: *Self, dispatcher_var: Var, callable_var: Var) Allocator.Error!bool {
    if (!self.varIsFunctionType(callable_var) or try self.varIsEffectfulFunction(callable_var)) return false;
    return try self.varIsConcreteHoistedConstType(dispatcher_var);
}

fn exprHasEffectfulFunctionBody(self: *Self, expr_idx: CIR.Expr.Idx) Allocator.Error!bool {
    const expr = self.cir.store.getExpr(expr_idx);
    if (expr == .e_lambda) return self.lambdaBodyIsEffectful(expr_idx);
    if (expr == .e_closure) return self.lambdaBodyIsEffectful(expr.e_closure.lambda_idx);
    return expr == .e_hosted_lambda;
}

fn lambdaBodyIsEffectful(self: *Self, lambda_idx: CIR.Expr.Idx) Allocator.Error!bool {
    if (self.effectful_lambda_bodies.contains(lambda_idx)) return true;
    const resolved = self.types.resolveVar(ModuleEnv.varFrom(lambda_idx));
    const func = resolved.desc.content.unwrapFunc() orelse return false;
    var i: u32 = 0;
    while (i < func.effect_deps.len()) : (i += 1) {
        if (try self.functionEffectState(self.types.getVarAt(func.effect_deps, i)) == .effectful) return true;
    }
    return false;
}

/// Whether `def_idx` belongs to a binding group that is still on the check
/// stack—mid-check, or checked but suspended at its boundary, so its
/// members' vars are not yet generalized.
fn defInOnStackGroup(self: *const Self, def_idx: CIR.Def.Idx) bool {
    const group_index = self.defGroupIndex(def_idx) orelse return false;
    for (self.group_stack.items) |frame| {
        if (frame.group_index == group_index) return true;
    }
    return false;
}

/// Whether a call's callee is a recursive reference to a def that has not
/// finished checking—a self-call, or a call between members of an on-stack
/// binding group (top-level or block-local).
///
/// A binding group's effectfulness is a fixpoint over the effects its bodies
/// actually perform. A recursive call through the group's own declared `=>`
/// scheme must not seed that fixpoint: otherwise every annotated-effectful
/// recursive function would be reported as needing a `!` name even when its
/// body never performs an effect. Calls to defs of already-finished groups
/// are not exempt—their effectfulness is settled.
fn callTargetIsInFlightRecursiveRef(self: *const Self, func_expr_idx: CIR.Expr.Idx) bool {
    const func_expr = self.cir.store.getExpr(func_expr_idx);
    if (func_expr != .e_lookup_local) return false;
    const pattern_idx = func_expr.e_lookup_local.pattern_idx;
    if (self.local_processing_ptrns.contains(pattern_idx)) return true;
    const processing_def = self.topLevelPattern(pattern_idx) orelse return false;
    return switch (processing_def.status) {
        .processing => true,
        .not_processed, .processed => self.defInOnStackGroup(processing_def.def_idx),
    };
}

fn checkEffectfulFunctionName(self: *Self, pattern_idx: CIR.Pattern.Idx, expr_idx: CIR.Expr.Idx) std.mem.Allocator.Error!void {
    const ident = self.getPatternIdent(pattern_idx) orelse return;
    if (ident.attributes.effectful) return;
    if (!try self.exprHasEffectfulFunctionBody(expr_idx)) return;

    _ = try self.problems.appendProblem(self.gpa, .{ .effectful_function_name = .{
        .region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(pattern_idx)),
    } });
}

fn varHasUnresolvedInspectContent(
    self: *Self,
    var_: Var,
    position: InspectTypePosition,
    visited: *std.AutoHashMap(Var, u8),
) std.mem.Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    const position_bit = @as(u8, 1) << @intFromEnum(position);
    const visit = try visited.getOrPut(resolved.var_);
    if (!visit.found_existing) visit.value_ptr.* = 0;
    if (visit.value_ptr.* & position_bit != 0) return false;
    visit.value_ptr.* |= position_bit;

    // Checked-type publication attaches an explicit close-to-empty default to
    // each unconstrained row-tail occurrence. Ordinary value occurrences have
    // no such default, and constrained variables cannot receive a row default.
    return switch (resolved.desc.content) {
        .flex => |flex| switch (position) {
            .value => true,
            .record_row, .tag_row => flex.constraints.len() > 0,
        },
        .rigid => |rigid| switch (position) {
            .value => true,
            .record_row, .tag_row => rigid.constraints.len() > 0,
        },
        .err, .field_presence => false,
        .alias => |alias| try self.varHasUnresolvedInspectContent(self.types.getAliasBackingVar(alias), position, visited),
        .structure => |flat_type| try self.flatTypeHasUnresolvedInspectContent(flat_type, visited),
    };
}

fn flatTypeHasUnresolvedInspectContent(
    self: *Self,
    flat_type: FlatType,
    visited: *std.AutoHashMap(Var, u8),
) std.mem.Allocator.Error!bool {
    return switch (flat_type) {
        .tuple => |tuple| try self.varsHaveUnresolvedInspectContent(self.types.sliceVars(tuple.elems), visited),
        .nominal_type => |nominal| try self.varsHaveUnresolvedInspectContent(self.types.sliceNominalArgs(nominal), visited),
        .fn_pure, .fn_effectful, .fn_unbound => false,
        .record => |record| blk: {
            const fields = self.types.getRecordFieldsSlice(record.fields);
            for (fields.items(.presence)) |presence| {
                {
                    const field_var = presence.typeVar();
                    if (try self.varHasUnresolvedInspectContent(field_var, .value, visited)) break :blk true;
                }
            }
            break :blk try self.varHasUnresolvedInspectContent(record.ext, .record_row, visited);
        },
        .record_unbound => |fields_range| blk: {
            const fields = self.types.getRecordFieldsSlice(fields_range);
            for (fields.items(.presence)) |presence| {
                {
                    const field_var = presence.typeVar();
                    if (try self.varHasUnresolvedInspectContent(field_var, .value, visited)) break :blk true;
                }
            }
            break :blk false;
        },
        .tag_union => |tag_union| blk: {
            const tags = self.types.getTagsSlice(tag_union.tags);
            for (tags.items(.args)) |args| {
                if (try self.varsHaveUnresolvedInspectContent(self.types.sliceVars(args), visited)) break :blk true;
            }
            break :blk try self.varHasUnresolvedInspectContent(tag_union.ext, .tag_row, visited);
        },
        .empty_record, .empty_tag_union => false,
    };
}

fn varsHaveUnresolvedInspectContent(
    self: *Self,
    vars: []const Var,
    visited: *std.AutoHashMap(Var, u8),
) std.mem.Allocator.Error!bool {
    for (vars) |var_| {
        if (try self.varHasUnresolvedInspectContent(var_, .value, visited)) return true;
    }
    return false;
}

fn varHasUnresolvedStaticDispatchConstraints(
    self: *Self,
    var_: Var,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    if (visited.contains(resolved.var_)) return false;
    try visited.put(resolved.var_, {});

    return switch (resolved.desc.content) {
        .flex => |flex| flex.constraints.len() > 0,
        .rigid => |rigid| rigid.constraints.len() > 0,
        .err, .field_presence => false,
        .alias => |alias| try self.varHasUnresolvedStaticDispatchConstraints(self.types.getAliasBackingVar(alias), visited),
        .structure => |flat_type| try self.flatTypeHasUnresolvedStaticDispatchConstraints(flat_type, visited),
    };
}

fn flatTypeHasUnresolvedStaticDispatchConstraints(
    self: *Self,
    flat_type: FlatType,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    return switch (flat_type) {
        .tuple => |tuple| try self.varsHaveUnresolvedStaticDispatchConstraints(self.types.sliceVars(tuple.elems), visited),
        .nominal_type => |nominal| try self.varsHaveUnresolvedStaticDispatchConstraints(self.types.sliceNominalArgs(nominal), visited),
        .fn_pure, .fn_effectful, .fn_unbound => false,
        .record => |record| blk: {
            const fields = self.types.getRecordFieldsSlice(record.fields);
            for (fields.items(.presence)) |presence| {
                {
                    const field_var = presence.typeVar();
                    if (try self.varHasUnresolvedStaticDispatchConstraints(field_var, visited)) break :blk true;
                }
            }
            break :blk try self.varHasUnresolvedStaticDispatchConstraints(record.ext, visited);
        },
        .record_unbound => |fields_range| blk: {
            const fields = self.types.getRecordFieldsSlice(fields_range);
            for (fields.items(.presence)) |presence| {
                {
                    const field_var = presence.typeVar();
                    if (try self.varHasUnresolvedStaticDispatchConstraints(field_var, visited)) break :blk true;
                }
            }
            break :blk false;
        },
        .tag_union => |tag_union| blk: {
            const tags = self.types.getTagsSlice(tag_union.tags);
            for (tags.items(.args)) |args| {
                if (try self.varsHaveUnresolvedStaticDispatchConstraints(self.types.sliceVars(args), visited)) break :blk true;
            }
            break :blk try self.varHasUnresolvedStaticDispatchConstraints(tag_union.ext, visited);
        },
        .empty_record, .empty_tag_union => false,
    };
}

fn varsHaveUnresolvedStaticDispatchConstraints(
    self: *Self,
    vars: []const Var,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    for (vars) |var_| {
        if (try self.varHasUnresolvedStaticDispatchConstraints(var_, visited)) return true;
    }
    return false;
}

fn varHasUnresolvedNonLiteralStaticDispatchConstraints(
    self: *Self,
    var_: Var,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    if (visited.contains(resolved.var_)) return false;
    try visited.put(resolved.var_, {});

    return switch (resolved.desc.content) {
        .flex => |flex| self.rangeHasNonLiteralConstraint(flex.constraints),
        .rigid => |rigid| self.rangeHasNonLiteralConstraint(rigid.constraints),
        .err, .field_presence => false,
        .alias => |alias| try self.varHasUnresolvedNonLiteralStaticDispatchConstraints(self.types.getAliasBackingVar(alias), visited),
        .structure => |flat_type| try self.flatTypeHasUnresolvedNonLiteralStaticDispatchConstraints(flat_type, visited),
    };
}

fn flatTypeHasUnresolvedNonLiteralStaticDispatchConstraints(
    self: *Self,
    flat_type: FlatType,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    return switch (flat_type) {
        .tuple => |tuple| try self.varsHaveUnresolvedNonLiteralStaticDispatchConstraints(self.types.sliceVars(tuple.elems), visited),
        .nominal_type => |nominal| try self.varsHaveUnresolvedNonLiteralStaticDispatchConstraints(self.types.sliceNominalArgs(nominal), visited),
        .fn_pure, .fn_effectful, .fn_unbound => false,
        .record => |record| blk: {
            const fields = self.types.getRecordFieldsSlice(record.fields);
            for (fields.items(.presence)) |presence| {
                {
                    const field_var = presence.typeVar();
                    if (try self.varHasUnresolvedNonLiteralStaticDispatchConstraints(field_var, visited)) break :blk true;
                }
            }
            break :blk try self.varHasUnresolvedNonLiteralStaticDispatchConstraints(record.ext, visited);
        },
        .record_unbound => |fields_range| blk: {
            const fields = self.types.getRecordFieldsSlice(fields_range);
            for (fields.items(.presence)) |presence| {
                {
                    const field_var = presence.typeVar();
                    if (try self.varHasUnresolvedNonLiteralStaticDispatchConstraints(field_var, visited)) break :blk true;
                }
            }
            break :blk false;
        },
        .tag_union => |tag_union| blk: {
            const tags = self.types.getTagsSlice(tag_union.tags);
            for (tags.items(.args)) |args| {
                if (try self.varsHaveUnresolvedNonLiteralStaticDispatchConstraints(self.types.sliceVars(args), visited)) break :blk true;
            }
            break :blk try self.varHasUnresolvedNonLiteralStaticDispatchConstraints(tag_union.ext, visited);
        },
        .empty_record, .empty_tag_union => false,
    };
}

fn varsHaveUnresolvedNonLiteralStaticDispatchConstraints(
    self: *Self,
    vars: []const Var,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    for (vars) |var_| {
        if (try self.varHasUnresolvedNonLiteralStaticDispatchConstraints(var_, visited)) return true;
    }
    return false;
}

/// Validate a platform module's hosted section against the hosted functions
/// its imported type modules declare: every hosted function must appear
/// exactly once, every entry must name a real hosted function, linker symbols
/// must be unique across the hosted and provides sections, and the fixed
/// runtime symbols plus the internal roc__ namespace are reserved.
///
/// Applications never pay for this: it only runs for platform modules.
///
/// One hosted function declaration, identified by the module and definition
/// the hosted transform rewrote rather than by any name it goes under.
const HostedTarget = struct {
    module: *const ModuleEnv,
    def: CIR.Def.Idx,
};

/// Record every hosted function `module` declares, keeping one display name per
/// definition for the missing-entry diagnostic.
fn collectDeclaredHostedFunctions(
    self: *Self,
    declared: *std.AutoHashMap(HostedTarget, []const u8),
    module: *const ModuleEnv,
) std.mem.Allocator.Error!void {
    for (module.store.sliceDefs(module.hosted_defs)) |def_idx| {
        const def = module.store.getDef(def_idx);
        const expr = module.store.getExpr(def.expr);
        // A declaration the hosted transform rewrote can still be replaced by a
        // runtime error afterwards, when canonicalization rejects the
        // declaration itself. That is already reported where it was rejected,
        // and it names no host function for the section to map.
        if (expr != .e_hosted_lambda) continue;

        // A declaration this platform module makes is named in the hosted
        // section without a module, so the diagnostic names it the same way.
        const name = if (module == self.cir)
            try hostedOwnDeclarationDisplayName(self.gpa, module, expr.e_hosted_lambda.symbol_name)
        else
            try hostedDefinitionDisplayName(self.gpa, module, expr.e_hosted_lambda.symbol_name);
        const gop = try declared.getOrPut(.{ .module = module, .def = def_idx });
        if (gop.found_existing) {
            self.gpa.free(name);
        } else {
            gop.value_ptr.* = name;
        }
    }
}

fn checkPlatformHostedSection(self: *Self) std.mem.Allocator.Error!void {
    if (self.cir.module_kind != .platform) return;

    const section = self.cir.hosted_entries.items.items;

    // Exact definitions of every hosted function declared by imported modules.
    // Display names are retained only for missing-entry diagnostics.
    var declared = std.AutoHashMap(HostedTarget, []const u8).init(self.gpa);
    defer {
        var value_it = declared.valueIterator();
        while (value_it.next()) |name| self.gpa.free(name.*);
        declared.deinit();
    }
    // Walk owner modules (direct imports plus their transitive public
    // dependencies), since hosted functions can live in modules the platform
    // root never imports directly. The hosted transform publishes the exact
    // rewritten defs, including associated items of nested type modules.
    //
    // The platform root is walked alongside them. A section entry names its
    // target through an import, so an entry can never resolve to a definition
    // in the root itself; a hosted declaration written there is therefore
    // always missing from the section, and reporting it here is what tells the
    // author so instead of leaving a declaration no linker symbol reaches.
    for (self.owner_modules) |imported_env| {
        try self.collectDeclaredHostedFunctions(&declared, imported_env);
    }
    try self.collectDeclaredHostedFunctions(&declared, self.cir);

    // Walk the section's resolved targets, detect duplicate functions and
    // duplicate/reserved symbols (provides symbols share the namespace).
    var mapped = std.AutoHashMap(HostedTarget, void).init(self.gpa);
    defer mapped.deinit();
    var symbols = std.StringHashMap(void).init(self.gpa);
    defer symbols.deinit();
    for (self.cir.provides_entries.items.items) |provides_entry| {
        const symbol_text = self.cir.getString(provides_entry.ffi_symbol);
        try self.checkHostSymbol(symbol_text, &symbols);
        try self.checkProvidesEntryHostBoundaryRows(provides_entry);
    }

    for (section) |entry| {
        // A resolved entry with no import named this platform module's own
        // declaration, so the module owning the target is this one.
        const target_env = if (entry.target_import) |import_idx|
            self.hoistedImportedModule(self.cir, import_idx)
        else if (entry.target_status == .resolved)
            self.cir
        else
            null;
        const target = if (target_env) |env|
            if (entry.target_def) |def_idx| HostedTarget{ .module = env, .def = def_idx } else null
        else
            null;

        if (target) |resolved| {
            const def = resolved.module.store.getDef(resolved.def);
            const expr = resolved.module.store.getExpr(def.expr);
            if (expr != .e_hosted_lambda) {
                const display_name = try hostedEntryDisplayName(self.gpa, self.cir, entry);
                defer self.gpa.free(display_name);
                const name_idx = try self.problems.putExtraString(display_name);
                _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
                    .name = name_idx,
                    .reason = .function_has_implementation,
                } });
            } else {
                const gop = try mapped.getOrPut(resolved);
                if (gop.found_existing) {
                    const display_name = try hostedEntryDisplayName(self.gpa, self.cir, entry);
                    defer self.gpa.free(display_name);
                    const name_idx = try self.problems.putExtraString(display_name);
                    _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
                        .name = name_idx,
                        .reason = .duplicate_function,
                    } });
                }
            }
        } else {
            const display_name = try hostedEntryDisplayName(self.gpa, self.cir, entry);
            defer self.gpa.free(display_name);
            const name_idx = try self.problems.putExtraString(display_name);
            _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
                .name = name_idx,
                .reason = .unknown_function,
            } });
        }

        const symbol_text = self.cir.getString(entry.symbol);
        try self.checkHostSymbol(symbol_text, &symbols);
    }

    // Every declared hosted function needs exactly one section entry.
    var declared_it = declared.iterator();
    while (declared_it.next()) |decl| {
        if (mapped.contains(decl.key_ptr.*)) continue;
        const name_idx = try self.problems.putExtraString(decl.value_ptr.*);
        _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
            .name = name_idx,
            .reason = .function_not_in_section,
        } });
    }
}

fn hostedDefinitionDisplayName(
    allocator: Allocator,
    module: *const ModuleEnv,
    symbol_name: Ident.Idx,
) Allocator.Error![]const u8 {
    var module_name = module.module_name;
    if (Ident.textEndsWith(module_name, ".roc")) {
        module_name = module_name[0 .. module_name.len - 4];
    }
    var func_name = module.getIdent(symbol_name);
    if (Ident.textEndsWith(func_name, "!")) {
        func_name = func_name[0 .. func_name.len - 1];
    }
    return std.fmt.allocPrint(allocator, "{s}.{s}", .{ module_name, func_name });
}

/// How a declaration this platform module makes is written in its own hosted
/// section: the function name alone, with the trailing `!` dropped the way
/// every other hosted name is displayed.
fn hostedOwnDeclarationDisplayName(
    allocator: Allocator,
    module: *const ModuleEnv,
    symbol_name: Ident.Idx,
) Allocator.Error![]const u8 {
    var func_name = module.getIdent(symbol_name);
    if (Ident.textEndsWith(func_name, "!")) {
        func_name = func_name[0 .. func_name.len - 1];
    }
    return allocator.dupe(u8, func_name);
}

fn hostedEntryDisplayName(
    allocator: Allocator,
    platform: *const ModuleEnv,
    entry: ModuleEnv.HostedEntry,
) Allocator.Error![]const u8 {
    var func_name = platform.getIdent(entry.func_ident);
    if (Ident.textEndsWith(func_name, "!")) {
        func_name = func_name[0 .. func_name.len - 1];
    }
    return if (entry.module_ident) |module_ident|
        std.fmt.allocPrint(allocator, "{s}.{s}", .{ platform.getIdent(module_ident), func_name })
    else
        allocator.dupe(u8, func_name);
}

fn checkProvidesEntryHostBoundaryRows(
    self: *Self,
    provides_entry: ModuleEnv.ProvidesEntry,
) std.mem.Allocator.Error!void {
    const def_idx = provides_entry.local_def orelse return;
    const def = self.cir.store.getDef(def_idx);
    const def_var = ModuleEnv.varFrom(def_idx);

    try self.checkHostBoundaryType(def_var, self.cir.store.getPatternRegion(def.pattern));
}

fn checkHostBoundaryType(self: *Self, var_: Var, region: Region) std.mem.Allocator.Error!void {
    if (try self.varContainsOpenRowInHostBoundary(var_)) {
        _ = try self.problems.appendProblem(self.gpa, .{ .host_boundary_open_row = .{
            .region = region,
        } });
    }
    if (try self.varContainsOptionalFieldInHostBoundary(var_)) {
        _ = try self.problems.appendProblem(self.gpa, .{ .host_boundary_optional_field = .{
            .region = region,
        } });
    }
}

/// The fixed runtime symbols every host defines; platform headers may not
/// reuse them for provides or hosted entries.
const reserved_host_symbols = [_][]const u8{
    "roc_alloc",
    "roc_dealloc",
    "roc_realloc",
    "roc_dbg",
    "roc_expect_failed",
    "roc_crashed",
};

fn checkHostSymbol(
    self: *Self,
    symbol_text: []const u8,
    symbols: *std.StringHashMap(void),
) std.mem.Allocator.Error!void {
    const gop = try symbols.getOrPut(symbol_text);
    if (!isValidHostSymbol(symbol_text)) {
        if (!gop.found_existing) {
            const name_idx = try self.problems.putExtraString(symbol_text);
            _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
                .name = name_idx,
                .reason = .invalid_symbol,
            } });
        }
        return;
    }
    for (reserved_host_symbols) |reserved| {
        if (Ident.textEql(symbol_text, reserved)) {
            if (!gop.found_existing) {
                const name_idx = try self.problems.putExtraString(symbol_text);
                _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
                    .name = name_idx,
                    .reason = .reserved_symbol,
                } });
            }
            return;
        }
    }
    if (Ident.textStartsWith(symbol_text, "roc__")) {
        if (!gop.found_existing) {
            const name_idx = try self.problems.putExtraString(symbol_text);
            _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
                .name = name_idx,
                .reason = .reserved_prefix,
            } });
        }
        return;
    }
    if (gop.found_existing) {
        const name_idx = try self.problems.putExtraString(symbol_text);
        _ = try self.problems.appendProblem(self.gpa, .{ .platform_hosted_section = .{
            .name = name_idx,
            .reason = .duplicate_symbol,
        } });
    }
}

fn isValidHostSymbol(symbol_text: []const u8) bool {
    if (symbol_text.len == 0) return false;
    if (!isHostSymbolStart(symbol_text[0])) return false;
    for (symbol_text[1..]) |byte| {
        if (!isHostSymbolContinue(byte)) return false;
    }
    return true;
}

fn isHostSymbolStart(byte: u8) bool {
    return byte == '_' or std.ascii.isAlphabetic(byte);
}

fn isHostSymbolContinue(byte: u8) bool {
    return isHostSymbolStart(byte) or std.ascii.isDigit(byte);
}

/// Process the requires_types annotations for platform modules, like:
///
///   { [Model : model] for main : { init : model, ... } }
///
/// For each required type, we first process the introduced alias variables:
///   { [Model : model] for main : { init : model, ... } }
///     ^^^^^^^^^^^^^^
/// Here, we create `model` as a *rigid* var, and a type alias `Model` pointing to
/// that exact rigid var.
///
/// We create this variable at the `.outermost` rank, so that every places
/// that references this var gets the same instance
///
/// Then, we generate the type for the actual required type
///   { [Model : model] for main : { init : model, ... } }
///                                ^^^^^^^^^^^^^^^^^^^^^^
///
/// Note on scoping: Type scopes are defined in czer. So in the example above,
///   { [Model : model] for main : { init : model, ... } }
///             a^^^^^                     b^^^^^
/// So `a` get the node CIR.TypeAnno.rigid_var{ .. }
/// So `b` get the node CIR.TypeAnno.rigid_var_lookup{ .ref = <a_id> }
/// Then, any reference to `b` replaced with `a` in `generateAnnoTypeInPlace`.
fn processRequiresTypes(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Ensure we are generalized
    // This is because we do not want the type checking we do here to be let-polymorphic
    std.debug.assert(env.rank() == .outermost);

    const requires_types_slice = self.cir.requires_types.items.items;
    for (requires_types_slice) |required_type| {

        // First, processes the required type aliases
        //   { [Model : model] for main : { init : model, ... } }
        //     ^^^^^^^^^^^^^^
        const required_type_aliases_slice = self.cir.for_clause_aliases.sliceRange(required_type.type_aliases);
        for (required_type_aliases_slice) |type_alias| {
            const stmt = self.cir.store.getStatement(type_alias.alias_stmt_idx);
            const stmt_var = ModuleEnv.varFrom(type_alias.alias_stmt_idx);

            // We should only ever have alias decls here
            std.debug.assert(stmt == .s_alias_decl);
            const alias = stmt.s_alias_decl;

            // Assert that this alias header is well formed
            const alias_lhs = self.cir.store.getTypeHeader(alias.header);
            std.debug.assert(alias_lhs.name.eql(alias_lhs.relative_name));
            std.debug.assert(alias_lhs.args.span.len == 0);

            // Assert that this alias body is well formed
            const alias_rhs_var = ModuleEnv.varFrom(alias.anno);
            const alias_rhs = self.cir.store.getTypeAnno(alias.anno);
            std.debug.assert(alias_rhs == .rigid_var);

            // Set ranks to generalized
            try self.setVarRank(stmt_var, env);
            try self.setVarRank(alias_rhs_var, env);

            // Set the rhs of the expr to be a rigid var
            try self.unifyWith(alias_rhs_var, .{
                .rigid = Rigid.init(type_alias.rigid_name),
            }, env);

            const stmt_content = self.types.resolveVar(stmt_var).desc.content;
            if (stmt_content != .alias) {
                try self.unifyWithTargetRank(
                    stmt_var,
                    try self.types.mkAliasWithSourceDeclAndBuiltinOrigin(
                        .{ .ident_idx = alias_lhs.relative_name },
                        alias_rhs_var,
                        &.{},
                        self.aliasOriginModule(),
                        @intFromEnum(type_alias.alias_stmt_idx),
                        self.cir.module_role == .builtin,
                    ),
                    env,
                );
            }
        }

        // Then, generate the type for the actual required type
        //   { [Model : model] for main : { init : model, ... } }
        //                                ^^^^^^^^^^^^^^^^^^^^^^
        try self.generateAnnoTypeInPlace(required_type.type_anno, env, .{ .annotation = null });
    }
}

fn processAppPlatformRequirements(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    const input = self.platform_requirements orelse return;
    switch (self.cir.module_kind) {
        .app, .default_app => {},
        .type_module, .package, .platform, .hosted, .module, .malformed => return,
    }

    // For-clause aliases live in the platform root's module-level scope, so a
    // requirement other than the declaring one can reference an alias by name;
    // bind each alias once for the whole requires clause and share the app's
    // instantiated declaration across every requirement that mentions it.
    var alias_bindings = std.ArrayListUnmanaged(ForClauseAliasBinding).empty;
    defer alias_bindings.deinit(self.gpa);
    try self.collectForClauseAliasBindings(input, env, &alias_bindings);

    var alias_var_substitutions = std.AutoHashMap(Var, Var).init(self.gpa);
    defer alias_var_substitutions.deinit();
    var alias_source_substitutions = std.AutoHashMap(copy_import.AliasSource, Var).init(self.gpa);
    defer alias_source_substitutions.deinit();
    for (alias_bindings.items) |binding| {
        const app_type_var = binding.app_type_var orelse continue;
        try alias_var_substitutions.put(binding.platform_alias_var, app_type_var);
        try alias_var_substitutions.put(binding.platform_identity_var, app_type_var);
        try alias_source_substitutions.put(binding.platform_alias_source, app_type_var);
    }

    for (input.env.requires_types.items.items, 0..) |required_type, requires_idx| {
        const required_ident = try self.copyPlatformIdent(input.env, required_type.ident);
        const instantiated = (try self.instantiatePlatformRequiredType(
            input,
            required_type,
            env,
            alias_bindings.items,
            &alias_var_substitutions,
            &alias_source_substitutions,
        )) orelse continue;
        var identity_vars_owned = true;
        defer if (identity_vars_owned) self.gpa.free(instantiated.identity_vars);

        const def_idx = self.exposedAppDefByIdent(required_ident) orelse {
            // Without the entrypoint contract, an unsupplied requirement is
            // simply unbound: the requirements that the app does supply still
            // constrain those definitions.
            if (self.validation == .explicit_roots) continue;

            const top_level_def = self.topLevelDefByIdent(required_ident);
            const app_region = if (top_level_def) |def_idx|
                self.defPatternRegion(def_idx)
            else
                self.appModuleRegion();
            _ = try self.problems.appendProblem(self.gpa, .{ .platform_def_not_found = .{
                .expected_def_ident = required_ident,
                .app_region = app_region,
                .platform_region = required_type.region,
                .ctx = if (top_level_def == null) .not_found else .found_but_not_exported,
            } });
            continue;
        };

        const map_entry = try self.platform_required_defs.getOrPut(self.gpa, def_idx);
        if (map_entry.found_existing) {
            // One def satisfying several requirements (a platform declaring one
            // name twice): the def unifies against the retained entry, so tie
            // this requirement's instance to that entry to enforce both.
            _ = try self.unifyInContext(
                map_entry.value_ptr.expected_var,
                instantiated.expected_var,
                env,
                .{ .platform_requirement = .{ .required_ident = required_ident, .platform_region = required_type.region } },
            );
        } else {
            map_entry.value_ptr.* = .{
                .expected_var = instantiated.expected_var,
                .required_ident = required_ident,
                .platform_region = required_type.region,
            };
        }

        try self.platform_requirement_solutions.append(self.gpa, .{
            .requires_idx = @intCast(requires_idx),
            .def = def_idx,
            .solved_var = instantiated.expected_var,
            .is_function = input.env.types.varResolvesToFunction(ModuleEnv.varFrom(required_type.type_anno)),
            .identity_vars = instantiated.identity_vars,
        });
        identity_vars_owned = false;
    }
}

/// The platform requirement solutions recorded while checking this app root,
/// in requires-clause order. The rows and their identity slices are
/// checker-owned and remain valid until `deinit`.
pub fn platformRequirementSolutions(self: *const Self) []const requirement_solution.SolutionInput {
    return self.platform_requirement_solutions.items;
}

/// Whether any of this module's requires-clause type annotations still carry
/// erroneous type content after checking. A platform root in that state keeps
/// its check-time publication: the env-derived requirement context a deferred
/// publication needs is a canonical key digest, and erroneous content has no
/// canonical key.
pub fn requiresTypesContainError(self: *Self) std.mem.Allocator.Error!bool {
    for (self.cir.requires_types.items.items) |required_type| {
        if (try canonical_type_keys.containsError(
            self.gpa,
            self.types,
            self.cir,
            ModuleEnv.varFrom(required_type.type_anno),
        )) {
            return true;
        }
    }
    return false;
}

fn instantiatePlatformRequiredType(
    self: *Self,
    input: PlatformRequirementInput,
    required_type: ModuleEnv.RequiredType,
    env: *Env,
    bindings: []const ForClauseAliasBinding,
    alias_var_substitutions: *const std.AutoHashMap(Var, Var),
    alias_source_substitutions: *const std.AutoHashMap(copy_import.AliasSource, Var),
) std.mem.Allocator.Error!?InstantiatedRequirement {
    const declared_aliases = input.env.for_clause_aliases.sliceRange(required_type.type_aliases);
    for (declared_aliases) |alias| {
        const binding = forClauseAliasBinding(bindings, alias.alias_stmt_idx) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("platform requirement for-clause alias was not collected for the requires clause", .{});
            }
            unreachable;
        };
        // The alias's app declaration was not found; the diagnostic was
        // emitted when the clause's bindings were collected.
        if (binding.app_type_var == null) return null;
    }

    // Enumerate the requirement type's identity variables (flex/rigid) in the
    // platform's store, in canonical slot order—the same first-encounter
    // order the platform's published requirement payload assigns them.
    const platform_identity_vars = try canonical_type_keys.identityVarsFromVar(
        self.gpa,
        &input.env.types,
        input.env,
        ModuleEnv.varFrom(required_type.type_anno),
    );
    defer self.gpa.free(platform_identity_vars);

    // Aliases are module-scoped, so an entry can use an alias declared by an
    // earlier flat entry even though it is absent from `declared_aliases`.
    for (platform_identity_vars) |platform_var| {
        const binding = forClauseAliasBindingForIdentity(bindings, platform_var) orelse continue;
        // The alias's app declaration was not found; the diagnostic was
        // emitted when the clause's bindings were collected.
        if (binding.app_type_var == null) return null;
    }

    const copied = try self.copyVarWithSourceSubstitutions(
        ModuleEnv.varFrom(required_type.type_anno),
        input.env,
        required_type.region,
        alias_var_substitutions,
        alias_source_substitutions,
    );

    // `copyVar` keyed `var_map` by the platform store's resolved vars—the
    // same roots the identity enumeration returned—so each identity slot
    // maps to its copied var here, then to its instantiated var below.
    const identity_vars = try self.gpa.alloc(Var, platform_identity_vars.len);
    errdefer self.gpa.free(identity_vars);
    for (platform_identity_vars, identity_vars) |platform_var, *slot_var| {
        slot_var.* = self.var_map.get(platform_var) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("platform requirement identity var was not copied into the app store", .{});
            }
            unreachable;
        };
    }

    const expected_var = try self.instantiateVar(copied, env, .{ .explicit = required_type.region });

    // `instantiateVar` keyed `var_map` by the copied store's resolved vars.
    // Clause-bound identities were replaced during copying and already are
    // the exact app declaration; every other identity must have been visited
    // and instantiated with the requirement root.
    for (platform_identity_vars, identity_vars) |platform_var, *slot_var| {
        if (alias_var_substitutions.get(platform_var)) |app_type_var| {
            const resolved_app_type = self.types.resolveVar(app_type_var).var_;
            if (builtin.mode == .Debug) {
                std.debug.assert(self.types.resolveVar(slot_var.*).var_ == resolved_app_type);
            }
            slot_var.* = resolved_app_type;
            continue;
        }

        const resolved = self.types.resolveVar(slot_var.*);
        slot_var.* = self.var_map.get(resolved.var_) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("platform requirement identity var was not instantiated with its requirement root", .{});
            }
            unreachable;
        };
    }

    return .{ .expected_var = expected_var, .identity_vars = identity_vars };
}

/// An app type declaration bound to a requires clause's for-clause alias
/// (`[Model : model]` binds `Model` to the app's own `Model` declaration).
/// A null `app_type_var` records that the app declares no such type; the
/// diagnostic was emitted when the binding was collected.
const ForClauseAliasBinding = struct {
    /// Exact declaration locator in the platform root. Names are consulted
    /// only while resolving the app-side declaration at the language boundary;
    /// copied occurrences match this declaration identity thereafter.
    platform_alias_stmt_idx: CIR.Statement.Idx,
    /// Resolved platform-store roots replaced during cross-module copying.
    platform_alias_var: Var,
    platform_identity_var: Var,
    /// Declaration identity shared by every application of this alias.
    platform_alias_source: copy_import.AliasSource,
    app_type_var: ?Var,
};

fn forClauseAliasBinding(bindings: []const ForClauseAliasBinding, platform_alias_stmt_idx: CIR.Statement.Idx) ?ForClauseAliasBinding {
    for (bindings) |binding| {
        if (binding.platform_alias_stmt_idx == platform_alias_stmt_idx) return binding;
    }
    return null;
}

fn forClauseAliasBindingForIdentity(bindings: []const ForClauseAliasBinding, platform_identity_var: Var) ?ForClauseAliasBinding {
    for (bindings) |binding| {
        if (binding.platform_identity_var == platform_identity_var) return binding;
    }
    return null;
}

/// Bind every for-clause alias of the platform's requires clause to the app's
/// own type declaration, instantiating each declaration once so all
/// requirements that mention an alias share one binder.
fn collectForClauseAliasBindings(
    self: *Self,
    input: PlatformRequirementInput,
    env: *Env,
    bindings: *std.ArrayListUnmanaged(ForClauseAliasBinding),
) std.mem.Allocator.Error!void {
    for (input.env.requires_types.items.items) |required_type| {
        const aliases = input.env.for_clause_aliases.sliceRange(required_type.type_aliases);
        for (aliases) |alias| {
            if (forClauseAliasBinding(bindings.items, alias.alias_stmt_idx) != null) continue;
            const alias_statement = input.env.store.getStatement(alias.alias_stmt_idx);
            if (alias_statement != .s_alias_decl) {
                if (builtin.mode == .Debug) {
                    std.debug.panic("platform requirement for-clause alias referenced a non-alias statement", .{});
                }
                unreachable;
            }
            const alias_anno = alias_statement.s_alias_decl.anno;
            const platform_alias_resolved = input.env.types.resolveVar(ModuleEnv.varFrom(alias.alias_stmt_idx));
            const platform_alias_content = platform_alias_resolved.desc.content;
            if (platform_alias_content != .alias) {
                if (builtin.mode == .Debug) {
                    std.debug.panic("platform requirement for-clause alias statement had no alias type", .{});
                }
                unreachable;
            }
            const platform_alias = platform_alias_content.alias;
            const platform_alias_source = copy_import.AliasSource{
                .origin_module = platform_alias.origin_module,
                .source_decl = platform_alias.source_decl.toOptional() orelse {
                    if (builtin.mode == .Debug) {
                        std.debug.panic("platform requirement for-clause alias had no source declaration", .{});
                    }
                    unreachable;
                },
            };
            const platform_identity_var = input.env.types.resolveVar(ModuleEnv.varFrom(alias_anno)).var_;
            const alias_ident = try self.copyPlatformIdent(input.env, alias.alias_name);

            const app_type_stmt = self.appTypeDeclByIdent(alias_ident) orelse {
                const value_region = self.topLevelValueRegionByIdent(alias_ident);
                const app_region = value_region orelse self.appModuleRegion();
                _ = try self.problems.appendProblem(self.gpa, .{ .platform_alias_not_found = .{
                    .expected_alias_ident = alias_ident,
                    .app_region = app_region,
                    .platform_region = input.env.store.getNodeRegion(ModuleEnv.nodeIdxFrom(alias.alias_stmt_idx)),
                    .ctx = if (value_region == null) .not_found else .found_but_not_type,
                } });
                try bindings.append(self.gpa, .{
                    .platform_alias_stmt_idx = alias.alias_stmt_idx,
                    .platform_alias_var = platform_alias_resolved.var_,
                    .platform_identity_var = platform_identity_var,
                    .platform_alias_source = platform_alias_source,
                    .app_type_var = null,
                });
                continue;
            };

            const app_type_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(app_type_stmt));
            const app_type_var = try self.instantiateVar(ModuleEnv.varFrom(app_type_stmt), env, .{ .explicit = app_type_region });
            try bindings.append(self.gpa, .{
                .platform_alias_stmt_idx = alias.alias_stmt_idx,
                .platform_alias_var = platform_alias_resolved.var_,
                .platform_identity_var = platform_identity_var,
                .platform_alias_source = platform_alias_source,
                .app_type_var = app_type_var,
            });
        }
    }
}

fn copyPlatformIdent(self: *Self, platform_env: *const ModuleEnv, ident: Ident.Idx) std.mem.Allocator.Error!Ident.Idx {
    return try self.cir.insertIdent(Ident.for_text(platform_env.getIdent(ident)));
}

fn appTypeDeclByIdent(self: *Self, ident: Ident.Idx) ?CIR.Statement.Idx {
    if (self.findLocalTypeDeclByNameInSpan(self.cir.type_decls, ident)) |stmt_idx| return stmt_idx;
    return self.findLocalTypeDeclByNameInSpan(self.cir.forward_type_decls, ident);
}

fn exposedAppDefByIdent(self: *Self, ident: Ident.Idx) ?CIR.Def.Idx {
    const node_idx = self.cir.getExposedValueNodeIndexById(ident) orelse return null;
    if (node_idx >= self.cir.store.nodes.len()) return null;
    const cir_node: CIR.Node.Idx = @enumFromInt(node_idx);
    if (self.cir.store.nodes.get(cir_node).tag != .def) return null;
    return @enumFromInt(node_idx);
}

fn topLevelDefByIdent(self: *Self, ident: Ident.Idx) ?CIR.Def.Idx {
    for (self.cir.store.sliceDefs(self.cir.top_level_value_defs)) |def_idx| {
        const def_ident = self.getPatternIdent(self.cir.store.getDef(def_idx).pattern) orelse continue;
        if (def_ident == ident) return def_idx;
    }
    return null;
}

fn topLevelValueRegionByIdent(self: *Self, ident: Ident.Idx) ?Region {
    if (self.topLevelDefByIdent(ident)) |def_idx| {
        return self.defPatternRegion(def_idx);
    }
    return self.topLevelTagConstructorRegionByIdent(ident);
}

fn topLevelTagConstructorRegionByIdent(self: *Self, ident: Ident.Idx) ?Region {
    for (0..self.cir.all_statements.span.len) |stmt_offset| {
        const stmt_idx = self.cir.store.statementAt(self.cir.all_statements, stmt_offset);
        const stmt = self.cir.store.getStatement(stmt_idx);
        const anno_idx = switch (stmt) {
            .s_alias_decl => |alias| alias.anno,
            .s_nominal_decl => |nominal| nominal.anno,
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => continue,
        };
        if (self.typeAnnoTagRegionByIdent(anno_idx, ident)) |region| return region;
    }
    return null;
}

fn typeAnnoTagRegionByIdent(self: *Self, anno_idx: CIR.TypeAnno.Idx, wanted: Ident.Idx) ?Region {
    const anno = self.cir.store.getTypeAnno(anno_idx);
    switch (anno) {
        .tag_union => |tag_union| {
            for (self.cir.store.sliceTypeAnnos(tag_union.tags)) |tag_idx| {
                if (self.typeAnnoTagRegionByIdent(tag_idx, wanted)) |region| return region;
            }
            if (tag_union.ext) |ext| return self.typeAnnoTagRegionByIdent(ext, wanted);
            return null;
        },
        .tag => |tag| {
            if (tag.name == wanted) {
                return self.cir.store.getTypeAnnoRegion(anno_idx);
            }
            for (self.cir.store.sliceTypeAnnos(tag.args)) |arg_idx| {
                if (self.typeAnnoTagRegionByIdent(arg_idx, wanted)) |region| return region;
            }
            return null;
        },
        .apply => |apply| {
            for (self.cir.store.sliceTypeAnnos(apply.args)) |arg_idx| {
                if (self.typeAnnoTagRegionByIdent(arg_idx, wanted)) |region| return region;
            }
            return null;
        },
        .record => |record| {
            for (self.cir.store.sliceAnnoRecordFields(record.fields)) |field_idx| {
                const field = self.cir.store.getAnnoRecordField(field_idx);
                if (self.typeAnnoTagRegionByIdent(field.ty, wanted)) |region| return region;
            }
            if (record.ext) |ext| return self.typeAnnoTagRegionByIdent(ext, wanted);
            return null;
        },
        .tuple => |tuple| {
            for (self.cir.store.sliceTypeAnnos(tuple.elems)) |elem_idx| {
                if (self.typeAnnoTagRegionByIdent(elem_idx, wanted)) |region| return region;
            }
            return null;
        },
        .@"fn" => |func| {
            for (self.cir.store.sliceTypeAnnos(func.args)) |arg_idx| {
                if (self.typeAnnoTagRegionByIdent(arg_idx, wanted)) |region| return region;
            }
            return self.typeAnnoTagRegionByIdent(func.ret, wanted);
        },
        .parens => |parens| return self.typeAnnoTagRegionByIdent(parens.anno, wanted),
        .rigid_var,
        .rigid_var_lookup,
        .underscore,
        .lookup,
        .malformed,
        => return null,
    }
}

fn defPatternRegion(self: *Self, def_idx: CIR.Def.Idx) Region {
    const def = self.cir.store.getDef(def_idx);
    return self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(def.pattern));
}

fn appModuleRegion(self: *Self) Region {
    if (self.cir.all_defs.span.len > 0) {
        const def_idx = self.cir.store.defAt(self.cir.all_defs, 0);
        return self.defPatternRegion(def_idx);
    }
    if (self.cir.all_statements.span.len > 0) {
        const stmt_idx = self.cir.store.statementAt(self.cir.all_statements, 0);
        return self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(stmt_idx));
    }
    return Region.zero();
}

/// Check if a statement index is a for-clause alias statement.
/// For-clause alias statements are created during platform header processing
/// for type aliases like [Model : model] in the requires clause.
///
/// When these are looked up, we need to *not* instantiate the alias, so all
/// references in the module Point to the same var.
fn isForClauseAliasStatement(self: *Self, stmt_idx: CIR.Statement.Idx) bool {
    // Slice the for-clause alias statements and check if stmt_idx is in the list
    for (self.cir.for_clause_aliases.items.items) |for_clause| {
        if (stmt_idx == for_clause.alias_stmt_idx) {
            return true;
        }
    }
    return false;
}

fn generateForClauseAliasApplication(
    self: *Self,
    anno_var: Var,
    decl_var: Var,
    anno_arg_vars: []const Var,
    env: *Env,
) std.mem.Allocator.Error!void {
    const decl_resolved = self.types.resolveVar(decl_var).desc.content;
    const decl_alias = switch (decl_resolved) {
        .alias => |alias| alias,
        .err => {
            try self.markErroneous(anno_var);
            return;
        },
        .flex, .rigid, .field_presence, .structure => {
            std.debug.assert(false);
            try self.markErroneous(anno_var);
            return;
        },
    };

    try self.unifyWith(
        anno_var,
        try self.types.mkAliasWithSourceDeclAndBuiltinOrigin(
            decl_alias.ident,
            self.types.getAliasBackingVar(decl_alias),
            anno_arg_vars,
            decl_alias.origin_module,
            decl_alias.source_decl.toOptional(),
            decl_alias.source_decl.originIsBuiltin(),
        ),
        env,
    );
}

// repl //

/// Check an expr for the repl
pub fn checkExprRepl(self: *Self, expr_idx: CIR.Expr.Idx) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    try ensureTypeStoreIsFilled(self);

    // Copy builtin types into this module's type store
    try self.copyBuiltinTypes();

    // Create a solver env
    var env = try self.env_pool.acquire();
    defer self.env_pool.release(env);
    std.debug.assert(env.rank() == .generalized);

    // First, iterate over the statements, generating types for each type declaration
    for (0..self.cir.builtin_statements.span.len) |stmt_offset| {
        const stmt_idx = self.cir.store.statementAt(self.cir.builtin_statements, stmt_offset);
        // If the statement is a type declaration, then generate the it's type
        // The resulting generalized type is saved at the type var slot at `stmt_idx`
        try self.generateStmtTypeDeclType(stmt_idx, &env);
    }

    // Validate nominal declaration recursion before checking values.
    try self.finalizeTypeDeclarationValidity();

    // Set the rank to be outermost
    try env.var_pool.pushRank();
    std.debug.assert(env.rank() == .outermost);

    // Check the expr
    _ = try self.checkExpr(expr_idx, &env, Expected.none());

    try self.finalizeTypes(&env, .{ .repl_expr = expr_idx });
    try self.reportPolymorphicConstrainedExpr(expr_idx);

    // Check for infinite types, at the expression root and at every binding
    // root the expression contains
    try self.checkForInfiniteType(CIR.Expr.Idx, expr_idx);
    try self.checkBindingRootsForInfiniteTypes();
    try self.recheckNominalConstructorBackings(&env);
    try self.finalizeExpectEffectSlots();

    try self.finalizeBindingSchemeNodes();

    self.debugAssertNominalDeclTableComplete();
}

/// Check a REPL expression, also type-checking any definitions (for local type declarations)
pub fn checkExprReplWithDefs(self: *Self, expr_idx: CIR.Expr.Idx) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    try ensureTypeStoreIsFilled(self);

    // Copy builtin types into this module's type store
    try self.copyBuiltinTypes();

    // Create a solver env
    var env = try self.env_pool.acquire();
    defer self.env_pool.release(env);
    std.debug.assert(env.rank() == .generalized);

    // First, iterate over the statements, generating types for each type declaration
    // Note that any types generated will be generalized
    for (0..self.cir.builtin_statements.span.len) |stmt_offset| {
        const stmt_idx = self.cir.store.statementAt(self.cir.builtin_statements, stmt_offset);
        try self.generateStmtTypeDeclType(stmt_idx, &env);
    }

    // Validate nominal declaration recursion before checking values.
    try self.finalizeTypeDeclarationValidity();

    // Initialize top_level_ptrns with any defs from local type declarations
    for (0..self.cir.all_defs.span.len) |def_offset| {
        const def_idx = self.cir.store.defAt(self.cir.all_defs, def_offset);
        const def = self.cir.store.getDef(def_idx);
        self.setTopLevelPattern(def.pattern, DefProcessed{
            .def_idx = def_idx,
            .def_name = null,
            .status = .not_processed,
        });
    }

    // Set the rank to be outermost
    try env.var_pool.pushRank();
    std.debug.assert(env.rank() == .outermost);

    // Type-check defs from local type declarations (their associated blocks),
    // as dependency-ordered binding groups just like file checking.
    try self.setupCheckOrder();
    try self.predeclareAnnotatedDefSchemes(&env);
    const group_count: u32 = @intCast(self.check_order.?.sccs.len);
    var group_index: u32 = 0;
    while (group_index < group_count) : (group_index += 1) {
        try self.ensureGroupChecked(group_index, &env);
        std.debug.assert(env.rank() == .outermost);
    }

    // Check the expr
    _ = try self.checkExpr(expr_idx, &env, Expected.none());

    // Check any accumulated constraints
    try self.checkAllConstraints(&env);
    try self.resolvePendingTupleAccesses(&env, false);
    try self.checkAllConstraints(&env);
    try self.resolveNumericLiteralsFromContext(&env);
    // Destructure binders bind before the defaulting rounds so defaulting
    // sees them through the row (see `judgeRecordDestructBinds`).
    try self.judgeRecordDestructBinds(&env);
    try self.finalizeLiteralDefaults(&env);

    // After finalizing literal defaults, resolve any remaining deferred static
    // dispatch constraints: committing a default can generate deferred
    // method_call constraints (e.g. Dec.to_str returns Str). Without this step,
    // the return type of methods on numerics stays an unconstrained flex var,
    // causing incorrect .zst layouts.
    if (env.deferred_static_dispatch_constraints.items.items.len > 0) {
        try self.checkStaticDispatchConstraints(&env, true);
        try self.checkAllConstraints(&env);
    }

    // After solving all deferred constraints, check every binding root
    // (top-level defs and local bindings) for infinite types
    try self.checkBindingRootsForInfiniteTypes();

    // Check the result expression itself, matching checkExprRepl: its type may
    // have incompatible constraints (e.g. !3) or be infinite/anonymously
    // recursive, neither of which is covered by the per-def checks above.
    const expr_var = ModuleEnv.varFrom(expr_idx);
    try self.checkPendingDefaults(&env);
    try self.judgeFieldKindsAtBoundary(&env);
    _ = try self.checkFlexVarConstraintCompatibility(expr_var, &env, true, .{});
    try self.validateResolvedOpenNumeralLiterals(&env);
    try self.resolvePendingTupleAccesses(&env, true);
    try self.checkAllConstraints(&env);
    try self.checkDefaultRestrictions();
    // Kind defaulting, mirroring `finalizeTypes` (this path inlines its own
    // finalize sequence): last, after every judgment above, for the same
    // reasons documented there.
    try self.defaultLiteralFieldKinds(&env);
    try self.checkForInfiniteType(CIR.Expr.Idx, expr_idx);
    try self.recheckNominalConstructorBackings(&env);

    try self.reportPolymorphicConstrainedExpr(expr_idx);
    try self.poisonErroneousValueUses();
    try self.finalizeExpectEffectSlots();

    try self.finalizeBindingSchemeNodes();

    self.debugAssertNominalDeclTableComplete();
}

// defs //

/// Check the types for a single definition
fn checkDef(self: *Self, def_idx: CIR.Def.Idx, env: *Env) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    const def = self.cir.store.getDef(def_idx);

    const saved_checking_executable_root = self.checking_executable_root;
    self.checking_executable_root = self.isExecutableRootDef(def_idx);
    defer self.checking_executable_root = saved_checking_executable_root;

    if (self.topLevelPattern(def.pattern)) |processing_def| {
        if (processing_def.status == .processed) {
            // If we've already processed this def, return immediately
            return;
        }
    }

    // Scope the ambiguity-judgment cursors to this def: a generalization event
    // inside it judges only candidates recorded while checking it, against a
    // pinnable frontier built from its own lambda params and open literals.
    // Saved/restored (not reset) because groups check defs back to back and a
    // dispatch obligation can nest another group's defs at a boundary.
    const saved_ambiguity_candidates_def_start = self.ambiguity_candidates_def_start;
    self.ambiguity_candidates_def_start = self.ambiguity_candidates.items.len;
    defer self.ambiguity_candidates_def_start = saved_ambiguity_candidates_def_start;
    const saved_checked_lambda_params_def_start = self.checked_lambda_params_def_start;
    self.checked_lambda_params_def_start = self.checked_lambda_params.items.len;
    defer self.checked_lambda_params_def_start = saved_checked_lambda_params_def_start;
    const saved_open_literal_vars_def_start = self.open_literal_vars_def_start;
    self.open_literal_vars_def_start = self.open_literal_vars.items.len;
    defer self.open_literal_vars_def_start = saved_open_literal_vars_def_start;

    // Make as processing
    const def_name = self.getPatternIdent(def.pattern);
    self.setTopLevelPattern(def.pattern, .{
        .def_idx = def_idx,
        .def_name = def_name,
        .status = .processing,
    });

    // Check if this expr is one that should be generalized
    const def_var = ModuleEnv.varFrom(def_idx);
    const ptrn_var = ModuleEnv.varFrom(def.pattern);
    const expr_var = ModuleEnv.varFrom(def.expr);

    // Ensure we're at the rank the driver checks defs at: the outermost rank,
    // or a recursive group's shared frame (whose members are checked inside
    // it), or a nested group frame opened at a dispatch boundary.
    std.debug.assert(env.rank() == self.currentDefCheckRank());

    // Whether the driver already ranked this def's pattern in the current
    // recursive group's shared frame (so in-group forward references can link
    // to it monomorphically before this def's body is checked).
    const group_prechecked = self.defInCurrentRecursiveGroup(def_idx);

    if (!group_prechecked) {
        // Set the ptrn and expr rank
        try self.setVarRank(def_var, env);
        try self.setVarRank(ptrn_var, env);

        const def_pattern_ctx: PatternCtx = if (self.patternNeedsExhaustiveness(def.pattern)) .match_branch else .bound;

        // Check the pattern
        try self.checkPattern(def.pattern, def_pattern_ctx, env);
    }

    // Extract function name from the pattern (for better error messages)
    const saved_func_name = self.enclosing_func_name;
    self.enclosing_func_name = def_name;
    defer self.enclosing_func_name = saved_func_name;

    // Check the annotation, if it exists
    const platform_required = self.platform_required_defs.get(def_idx);
    const expectation = blk: {
        if (def.annotation) |annotation_idx| {
            break :blk Expected.fromAnnotation(annotation_idx);
        } else if (platform_required) |required| {
            break :blk Expected.none().withExpectedType(.{
                .var_ = required.expected_var,
                .context = .{ .platform_requirement = .{ .required_ident = required.required_ident, .platform_region = required.platform_region } },
            });
        } else {
            break :blk Expected.none();
        }
    };

    const exhaustiveness_scope = self.exhaustiveness_context.enterCompileTimeRoot();
    defer exhaustiveness_scope.leave();

    // Infer types for the body, checking against the instantiated annotation.
    // Ordinary top-level constants are already compile-time roots, so nested
    // hoisted roots inside them would duplicate compile-time work. Top-level
    // functions are not evaluated as data constants, so their bodies may still
    // contain top-level-equivalent local values.
    const def_expr = self.cir.store.getExpr(def.expr);
    const def_is_function = isFunctionDef(&self.cir.store, def_expr);
    const def_expectation = if (def_is_function)
        expectation.withHoistPosition(.eligible)
    else
        expectation.forComptimeRoot();
    const saved_checking_immediate_callee = self.checking_immediate_callee;
    if (self.checking_executable_root) self.checking_immediate_callee = true;
    defer self.checking_immediate_callee = saved_checking_immediate_callee;
    self.checking_binding_rhs = true;
    self.checking_binding_rhs_pattern = def.pattern;
    const previous_checking_predeclared_body_def = self.checking_predeclared_body_def;
    if (self.predeclaredSchemeVar(def_idx) != null) self.checking_predeclared_body_def = def_idx;
    defer self.checking_predeclared_body_def = previous_checking_predeclared_body_def;
    const saved_active_scheme_root = self.active_scheme_root;
    // A singleton value definition has no scheme boundary and therefore owns
    // no side-table candidates. Recursive groups still provisionally own every
    // member here because the shared group boundary decides which roots
    // actually generalize. A singleton closure delegates that boundary to its
    // inner lambda, so candidates must use the lambda's owner from the start;
    // recursive SCC members continue to use the def expression root captured
    // by their shared group boundary.
    const scheme_owner = if (!group_prechecked and def_expr == .e_closure)
        ModuleEnv.varFrom(def_expr.e_closure.lambda_idx)
    else
        expr_var;
    self.active_scheme_root = if (def_is_function or group_prechecked) scheme_owner else saved_active_scheme_root;
    defer self.active_scheme_root = saved_active_scheme_root;
    const def_does_fx = try self.checkExpr(def.expr, env, def_expectation);
    if (def.annotation != null) {
        if (platform_required) |required| {
            _ = try self.unifyInContext(
                required.expected_var,
                ModuleEnv.varFrom(def.expr),
                env,
                .{ .platform_requirement = .{ .required_ident = required.required_ident, .platform_region = required.platform_region } },
            );
        }
    }
    if (def_does_fx) {
        _ = try self.problems.appendProblem(self.gpa, .{ .effectful_top_level = .{
            .region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(def.expr)),
        } });
        try self.markErroneous(expr_var);
    }
    // A platform requirement is the def's explicit expected type even when the
    // source has no annotation. Only truly unconstrained crashing defs default
    // to unit; otherwise this would overwrite the requirement type with `{}`.
    if (def.annotation == null and platform_required == null and self.exprAlwaysCrashes(def.expr)) {
        try self.unifyWith(expr_var, .{ .structure = .empty_record }, env);
    }
    if (def.annotation == null and self.erroneous_value_exprs.contains(def.expr)) {
        try self.erroneous_value_patterns.put(self.gpa, def.pattern, {});
    }
    try self.closeAbsentConstructedPayloadVars(def.expr, expr_var);
    if (isFunctionDef(&self.cir.store, self.cir.store.getExpr(def.expr)) and !self.defInCurrentRecursiveGroup(def_idx)) {
        try self.checkEffectfulFunctionName(def.pattern, def.expr);
    }

    // Unify the ptrn and the expr
    const ptrn_result = try self.unify(ptrn_var, expr_var, env);

    // Unify the def and ptrn
    _ = try self.unify(def_var, ptrn_var, env);

    // Scheme identity follows stable source vars, never the mutable class
    // representative. Publish every binding alias explicitly after the
    // ordinary pattern/body unifications have completed.
    try self.bindTypeSchemeVar(expr_var, ptrn_var);
    try self.bindTypeSchemeVar(expr_var, def_var);
    if (self.predeclaredSchemeVar(def_idx)) |predeclared_scheme_var| {
        try self.bindTypeSchemeVar(expr_var, predeclared_scheme_var);
    }

    if (ptrn_result.isEstablished()) {
        const def_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(def.pattern));
        _ = try self.checkDestructureExhaustiveness(def.pattern, def.expr, expr_var, env, def_region);
        if (self.cir.store.getPattern(def.pattern) != .assign) {
            try self.recordHoistPatternExtractionProvenanceHelp(def.pattern, def.expr, def.pattern, .immediate);
        }
    }

    // Mark as processed
    self.setTopLevelPattern(def.pattern, .{
        .def_idx = def_idx,
        .def_name = def_name,
        .status = .processed,
    });
}

fn isExecutableRootDef(self: *const Self, def_idx: CIR.Def.Idx) bool {
    for (self.executable_root_defs.items) |root_def_idx| {
        if (root_def_idx == def_idx) return true;
    }
    return false;
}

// dependency-ordered driver //

/// Compute the module's dependency-ordered checking plan: the SCC condensation
/// of the name-reference graph in deterministic topological order. Transient—
/// owned by this Check instance and freed in deinit, never part of the checked
/// module.
fn setupCheckOrder(self: *Self) std.mem.Allocator.Error!void {
    if (self.check_order != null) return;
    self.check_order = try DependencyGraph.computeCheckOrder(self.cir, self.cir.all_defs, self.gpa);
    const sccs = self.check_order.?.sccs;
    try self.group_states.appendNTimes(self.gpa, .pending, sccs.len);
    for (sccs, 0..) |scc, group_index| {
        for (scc.defs) |def_idx| {
            self.setDefGroupIndex(def_idx, @intCast(group_index));
        }
    }
}

/// Declare every annotated top-level def's scheme from its annotation, before
/// any body is checked. A reference to an annotated def—by name or by
/// dispatch—then instantiates the scheme and never requires the referenced
/// body to have been checked; bodies are later checked on the ordinary path,
/// in graph order like everything else.
fn predeclareAnnotatedDefSchemes(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    std.debug.assert(env.rank() == .outermost);
    for (0..self.cir.all_defs.span.len) |def_offset| {
        const def_idx = self.cir.store.defAt(self.cir.all_defs, def_offset);
        const def = self.cir.store.getDef(def_idx);
        const annotation_idx = def.annotation orelse continue;
        if (!self.annotationIsPredeclarableScheme(def.pattern, annotation_idx)) continue;
        const scheme_var = try self.predeclareAnnotationScheme(annotation_idx, env);
        self.setPredeclaredSchemeVar(def_idx, scheme_var);
    }
}

/// Whether a def's annotation can be declared as a standalone scheme before
/// its body is checked: a simple `.assign` binding whose annotation has no
/// `_` inference hole (a hole is inferred from the body, so the annotation
/// alone does not determine the scheme). Defs that fail this are simply
/// checked in graph order like unannotated defs.
fn annotationIsPredeclarableScheme(
    self: *Self,
    pattern_idx: CIR.Pattern.Idx,
    annotation_idx: CIR.Annotation.Idx,
) bool {
    if (self.cir.store.getPattern(pattern_idx) != .assign) return false;
    return !self.cir.store.getAnnotation(annotation_idx).contains_underscore;
}

/// Build a standalone generalized scheme from an annotation, leaving the
/// annotation's CIR nodes untouched for the def's own body check.
///
/// The annotation's type is generated in place (through the one and only
/// generation path), deep-copied into orphan vars, and the copy generalized
/// in its own rank frame. The generation's side effects are then unwound: its
/// diagnostics are discarded (the body pass regenerates the annotation and
/// reports them exactly as it always has) and the annotation nodes are reset
/// to pristine unbound slots so the body-pass generation starts fresh. The
/// def itself therefore checks byte-for-byte as before this pre-pass existed—
/// in particular its body shares vars with its own scheme, which
/// dispatch-evidence publication relies on—while early references hold a
/// disjoint copy, exactly like references to an imported scheme.
fn predeclareAnnotationScheme(
    self: *Self,
    annotation_idx: CIR.Annotation.Idx,
    env: *Env,
) std.mem.Allocator.Error!Var {
    const problems_len = self.problems.len();
    const snapshots_mark = self.snapshots.mark();

    try env.var_pool.pushRank();
    const saved_predeclaring = self.predeclaring_annotation;
    self.predeclaring_annotation = true;
    defer self.predeclaring_annotation = saved_predeclaring;
    try self.generateAnnotationType(annotation_idx, env);
    const scheme_var = try self.instantiateVarOrphan(
        ModuleEnv.varFrom(annotation_idx),
        env,
        env.rank(),
        .use_last_var,
    );
    try self.judgeFieldKindsAtBoundary(env);
    try self.generalizer.generalize(self.gpa, &env.var_pool, env.rank());
    try self.publishBindingScheme(scheme_var);
    env.var_pool.popRank();

    self.problems.truncate(problems_len);
    self.snapshots.truncateToMark(snapshots_mark);
    try self.resetAnnotationNodes(annotation_idx);
    return scheme_var;
}

/// Initialize the sparse predeclared identity side of the correspondence only
/// when an actual lookup reaches the annotation before its body. The pristine
/// predeclared scheme is still available here, so canonical slot enumeration
/// is direct producer data rather than a later reconstruction.
fn ensurePredeclaredIdentityCorrespondence(
    self: *Self,
    def_idx: CIR.Def.Idx,
    scheme_var: Var,
) Allocator.Error!void {
    const entry = try self.predeclared_identity_correspondence_by_def.getOrPut(self.gpa, def_idx);
    if (entry.found_existing) return;
    errdefer _ = self.predeclared_identity_correspondence_by_def.remove(def_idx);

    const identity_vars = try canonical_type_keys.identityVarsFromVar(
        self.gpa,
        self.types,
        self.cir,
        scheme_var,
    );
    defer self.gpa.free(identity_vars);
    const pairs_start: u32 = @intCast(self.predeclared_annotation_pairs.items.len);
    for (identity_vars) |identity_var| {
        try self.predeclared_annotation_pairs.append(self.gpa, .{
            // Replaced with the regenerated body's identity var before replay.
            .old_var = identity_var,
            .fresh_var = identity_var,
        });
    }
    entry.value_ptr.* = .{ .pairs = .{
        .start = pairs_start,
        .len = @intCast(identity_vars.len),
    } };
}

/// Complete the explicit identity-slot correspondence recorded by the
/// annotation pre-pass. Canonical identity slots include generation-internal
/// open row vars that have no CIR node of their own, so pairing by slot here
/// is complete where raw annotation-node pairs would not be.
fn recordPredeclaredBodyAnnotationPairs(
    self: *Self,
    def_idx: CIR.Def.Idx,
    annotation_idx: CIR.Annotation.Idx,
) Allocator.Error!void {
    const correspondence = self.predeclared_identity_correspondence_by_def.getPtr(def_idx) orelse return;
    if (correspondence.body_recorded) return;
    const range = correspondence.pairs;
    const body_identity_vars = try canonical_type_keys.identityVarsFromVar(
        self.gpa,
        self.types,
        self.cir,
        ModuleEnv.varFrom(annotation_idx),
    );
    defer self.gpa.free(body_identity_vars);
    if (body_identity_vars.len != range.len) return;
    for (body_identity_vars, range.mutableSlice(self.predeclared_annotation_pairs.items)) |body_var, *pair| {
        pair.old_var = body_var;
    }
    correspondence.body_recorded = true;
}

/// Reset every type-annotation node var this annotation's generation wrote
/// (the annotation node itself, its type tree, and its where-clause
/// signatures) to a pristine unbound slot. Sound because nothing live
/// references those vars afterwards: the pre-declared scheme is a fully
/// disjoint orphan copy, and generation-internal fresh vars are garbage.
fn resetAnnotationNodes(self: *Self, annotation_idx: CIR.Annotation.Idx) std.mem.Allocator.Error!void {
    try self.types.resetVarToUnbound(ModuleEnv.varFrom(annotation_idx), Rank.outermost);

    var stack_allocator_state = std.heap.stackFallback(1024, self.gpa);
    const stack_allocator = stack_allocator_state.get();
    var nodes: std.ArrayList(CIR.TypeAnno.Idx) = .empty;
    defer nodes.deinit(stack_allocator);
    try self.collectAnnotationTypeAnnos(annotation_idx, &nodes, stack_allocator);
    for (nodes.items) |anno_idx| {
        try self.types.resetVarToUnbound(ModuleEnv.varFrom(anno_idx), Rank.outermost);
    }
}

/// Collect every TypeAnno node in an annotation—its type tree plus its
/// where-clause method signatures—via an explicit worklist. Rigid-var
/// lookups are NOT followed (`.ref` can point outside this annotation, e.g.
/// a local annotation referencing an enclosing def's type variable); the
/// nodes a `.ref` targets inside this annotation are reached as part of the
/// tree itself.
fn collectAnnotationTypeAnnos(
    self: *Self,
    annotation_idx: CIR.Annotation.Idx,
    out: *std.ArrayList(CIR.TypeAnno.Idx),
    allocator: std.mem.Allocator,
) std.mem.Allocator.Error!void {
    const annotation = self.cir.store.getAnnotation(annotation_idx);

    var pending: std.ArrayList(CIR.TypeAnno.Idx) = .empty;
    defer pending.deinit(allocator);

    try pending.append(allocator, annotation.anno);
    if (annotation.where) |where_span| {
        for (self.cir.store.sliceWhereClauses(where_span)) |where_idx| {
            switch (self.cir.store.getWhereClause(where_idx)) {
                .w_method => |method| {
                    try pending.append(allocator, method.var_);
                    for (self.cir.store.sliceTypeAnnos(method.args)) |arg_idx| {
                        try pending.append(allocator, arg_idx);
                    }
                    try pending.append(allocator, method.ret);
                },
                // A where alias reference's arguments are generated in place
                // (`generateWhereAliasReferenceArgs`), so its node tree must be
                // reset like any other. This matters when an argument's rigid
                // var occurs nowhere else in the annotation: its node is the
                // primary occurrence, and a stale rigid left behind here fails
                // to re-unify on the body pass.
                .w_alias => |alias| try pending.append(allocator, alias.alias),
                .w_malformed => {},
            }
        }
    }

    while (pending.pop()) |anno_idx| {
        try out.append(allocator, anno_idx);
        switch (self.cir.store.getTypeAnno(anno_idx)) {
            .underscore, .rigid_var, .rigid_var_lookup, .lookup, .malformed => {},
            .apply => |apply| {
                for (self.cir.store.sliceTypeAnnos(apply.args)) |arg_idx| {
                    try pending.append(allocator, arg_idx);
                }
            },
            .tag_union => |tag_union| {
                for (self.cir.store.sliceTypeAnnos(tag_union.tags)) |tag_idx| {
                    try pending.append(allocator, tag_idx);
                }
                if (tag_union.ext) |ext_idx| try pending.append(allocator, ext_idx);
            },
            .tag => |tag| {
                for (self.cir.store.sliceTypeAnnos(tag.args)) |arg_idx| {
                    try pending.append(allocator, arg_idx);
                }
            },
            .tuple => |tuple| {
                for (self.cir.store.sliceTypeAnnos(tuple.elems)) |elem_idx| {
                    try pending.append(allocator, elem_idx);
                }
            },
            .record => |record| {
                for (self.cir.store.sliceAnnoRecordFields(record.fields)) |field_idx| {
                    const field = self.cir.store.getAnnoRecordField(field_idx);
                    try pending.append(allocator, field.ty);
                }
                if (record.ext) |ext_idx| try pending.append(allocator, ext_idx);
            },
            .@"fn" => |func| {
                for (self.cir.store.sliceTypeAnnos(func.args)) |arg_idx| {
                    try pending.append(allocator, arg_idx);
                }
                try pending.append(allocator, func.ret);
            },
            .parens => |parens| try pending.append(allocator, parens.anno),
        }
    }
}

/// The rank `checkDef` expects the env to sit at: the current group's
/// def-check rank (a recursive group's members check inside its shared
/// frame), or the outermost rank outside any group (REPL, expect bodies).
fn currentDefCheckRank(self: *const Self) Rank {
    if (self.group_stack.items.len == 0) return .outermost;
    return self.group_stack.items[self.group_stack.items.len - 1].def_check_rank;
}

/// The rank of the current group's generalization boundary: the frame where a
/// singleton def's RHS generalizes (or a recursive group's shared frame), and
/// where pending dispatch obligations resolve. Obligation vars are pinned at
/// this rank so no inner frame can generalize them first (Invariant D).
fn currentGroupBoundaryRank(self: *const Self) Rank {
    if (self.group_stack.items.len == 0) return Rank.outermost.next();
    return self.group_stack.items[self.group_stack.items.len - 1].boundary_rank;
}

/// The binding group currently being checked (top of `group_stack`), or null
/// outside any group (REPL, expect bodies).
fn currentGroupIndex(self: *const Self) ?u32 {
    if (self.group_stack.items.len == 0) return null;
    return self.group_stack.items[self.group_stack.items.len - 1].group_index;
}

fn currentFramePendingTargetsTop(self: *const Self) usize {
    if (self.group_stack.items.len == 0) return 0;
    return self.group_stack.items[self.group_stack.items.len - 1].pending_targets_top;
}

fn currentFramePendingPredeclaredUsesTop(self: *const Self) usize {
    if (self.group_stack.items.len == 0) return 0;
    return self.group_stack.items[self.group_stack.items.len - 1].pending_predeclared_uses_top;
}

/// Whether `def_idx` is a member of the group currently on top of the stack,
/// and that group is recursive (so the driver pre-ranked its pattern in the
/// group's shared frame).
fn defInCurrentRecursiveGroup(self: *const Self, def_idx: CIR.Def.Idx) bool {
    if (self.group_stack.items.len == 0) return false;
    const frame = self.group_stack.items[self.group_stack.items.len - 1];
    if (!self.check_order.?.sccs[frame.group_index].is_recursive) return false;
    const group_index = self.defGroupIndex(def_idx) orelse return false;
    return group_index == frame.group_index;
}

fn ensureGroupsCheckedUpTo(self: *Self, group_index: u32, env: *Env) std.mem.Allocator.Error!void {
    // Groups are in topological order, so every group this one name-depends on
    // has a smaller index. Checking the whole prefix keeps nested checking
    // deterministic and guarantees the target group's name dependencies are in
    // place before its bodies run.
    var gi: u32 = 0;
    while (gi <= group_index) : (gi += 1) {
        try self.ensureGroupChecked(gi, env);
    }
}

fn ensureGroupChecked(self: *Self, group_index: u32, env: *Env) std.mem.Allocator.Error!void {
    switch (self.group_states.items[group_index]) {
        .checked => return,
        .checking => {
            // A suspended group—the current group, or an ancestor paused at
            // its own boundary. Its members are already checked (`.processed`)
            // with still-live, not-yet-generalized vars, so a dispatch
            // back-edge resolves against them directly (the monomorphic merge)—
            // the group is never re-entered. This also covers a pending
            // target recorded mid-body for a later member of the SAME group:
            // by boundary time the member loop has checked it.
            if (builtin.mode == .Debug) {
                var on_stack = false;
                for (self.group_stack.items) |frame| {
                    if (frame.group_index == group_index) {
                        on_stack = true;
                        break;
                    }
                }
                std.debug.assert(on_stack);
            }
        },
        .pending => try self.checkGroup(group_index, env),
    }
}

/// Check one binding group. A non-recursive singleton runs the ordinary
/// per-def path (its RHS frame is the group's boundary). A recursive group
/// gets one shared rank frame: members' patterns are ranked in it first (so
/// in-group references—forward or backward—link to them monomorphically),
/// unannotated function members' top-level lambdas are kept in the frame
/// instead of generalizing on their own, and the whole group generalizes at
/// the frame's boundary (the ML binding-group rule).
fn checkGroup(self: *Self, group_index: u32, env: *Env) std.mem.Allocator.Error!void {
    const scc = self.check_order.?.sccs[group_index];
    const base_rank = env.rank();

    // Invariant E (boundary cleanliness): group checks start—and nest—
    // only with no mid-body state pending.
    std.debug.assert(self.suppress_generalize_expr == null);

    // A group's recorded scheme contents are a property of its own defs, never
    // of whichever definition's boundary caused the group to be checked. A
    // group check nested inside another definition's generalization boundary
    // therefore runs with no active owner, exactly like a driver-initiated
    // check; members that generalize install their own owners in `checkDef`.
    const saved_active_scheme_root = self.active_scheme_root;
    self.active_scheme_root = null;
    defer self.active_scheme_root = saved_active_scheme_root;

    // A singleton value def never generalizes, so its obligations resolve at
    // the base rank (after checkDef); everything else's boundary is the RHS
    // or shared group frame.
    const group_is_value_def = !scc.is_recursive and
        !isFunctionDef(&self.cir.store, self.cir.store.getExpr(self.cir.store.getDef(scc.defs[0]).expr));

    self.group_states.items[group_index] = .checking;
    try self.group_stack.append(self.gpa, .{
        .group_index = group_index,
        .base_rank = base_rank,
        .def_check_rank = if (scc.is_recursive) base_rank.next() else base_rank,
        .boundary_rank = if (group_is_value_def) base_rank else base_rank.next(),
        .pending_targets_top = self.pending_dispatch_targets.items.len,
        .pending_predeclared_uses_top = self.pending_predeclared_scheme_uses.items.len,
    });

    if (!scc.is_recursive) {
        std.debug.assert(scc.defs.len == 1);
        try self.checkDef(scc.defs[0], env);
        std.debug.assert(env.rank() == base_rank);
        // A function def resolved its dispatch obligations at its RHS
        // generalization boundary (inside checkExpr); a value def has no such
        // boundary, so any obligations its RHS recorded resolve here.
        try self.resolveGroupPendingDispatchTargets(env);
        _ = try self.resolvePendingPredeclaredSchemeUses(env, false);
    } else {
        try env.var_pool.pushRank();
        const frame_rank = env.rank();

        // Rank every member's def/pattern vars in the shared frame first, so
        // an earlier member's body can reference a later member.
        for (scc.defs) |member_def_idx| {
            const member_def = self.cir.store.getDef(member_def_idx);
            try self.setVarRank(ModuleEnv.varFrom(member_def_idx), env);
            try self.setVarRank(ModuleEnv.varFrom(member_def.pattern), env);
            const member_pattern_ctx: PatternCtx = if (self.patternNeedsExhaustiveness(member_def.pattern)) .match_branch else .bound;
            try self.checkPattern(member_def.pattern, member_pattern_ctx, env);
        }

        for (scc.defs) |member_def_idx| {
            const member_def = self.cir.store.getDef(member_def_idx);
            if (isFunctionDef(&self.cir.store, self.cir.store.getExpr(member_def.expr))) {
                // Every recursive member's top-level RHS lives in the group
                // frame and generalizes at the shared boundary. Annotated
                // in-group references still instantiate their predeclared
                // schemes (polymorphic recursion), but deferring publication
                // lets forward members contribute their complete inferred
                // requirements before any member freezes.
                self.suppress_generalize_expr = member_def.expr;
            }
            try self.checkDef(member_def_idx, env);
            std.debug.assert(self.suppress_generalize_expr == null);
            std.debug.assert(env.rank() == frame_rank);
        }

        // The group's generalization boundary. (Owned copy, not scratch: the
        // boundary can nest other groups' checks, which use the scratch
        // lists themselves.)
        const member_roots = try self.gpa.alloc(BoundaryRoot, scc.defs.len);
        defer self.gpa.free(member_roots);
        for (scc.defs, 0..) |member_def_idx, i| {
            const member_def = self.cir.store.getDef(member_def_idx);
            member_roots[i] = .{
                .owner = ModuleEnv.varFrom(member_def.expr),
                .interface = ModuleEnv.varFrom(member_def.expr),
            };
        }

        // Destructure binders bind before the boundary's literal defaulting
        // (inside `runGroupBoundary`) so defaulting sees them through the
        // row (see `judgeRecordDestructBinds`).
        try self.judgeRecordDestructBinds(env);
        try self.runGroupBoundary(member_roots, env);
        // Recursive members create their schemes together at the shared group
        // boundary, after `checkDef`'s ordinary binding publication already
        // ran. Publish the stable pattern/def aliases now that the schemes
        // exist, before any use can instantiate a member through those vars.
        for (scc.defs) |member_def_idx| {
            const member_def = self.cir.store.getDef(member_def_idx);
            const expr_var = ModuleEnv.varFrom(member_def.expr);
            try self.bindTypeSchemeVar(expr_var, ModuleEnv.varFrom(member_def.pattern));
            try self.bindTypeSchemeVar(expr_var, ModuleEnv.varFrom(member_def_idx));
            if (self.predeclaredSchemeVar(member_def_idx)) |predeclared_scheme_var| {
                try self.bindTypeSchemeVar(expr_var, predeclared_scheme_var);
            }
        }
        for (scc.defs) |member_def_idx| {
            const member_def = self.cir.store.getDef(member_def_idx);
            if (isFunctionDef(&self.cir.store, self.cir.store.getExpr(member_def.expr))) {
                try self.checkEffectfulFunctionName(member_def.pattern, member_def.expr);
            }
        }
        try self.judgeFieldKindsAtBoundary(env);
        try self.generalizer.generalize(self.gpa, &env.var_pool, env.rank());
        for (scc.defs) |member_def_idx| {
            const member_def = self.cir.store.getDef(member_def_idx);
            const expr_var = ModuleEnv.varFrom(member_def.expr);
            try self.publishBindingScheme(expr_var);
            try self.bindBindingSchemeVar(expr_var, ModuleEnv.varFrom(member_def.pattern));
            try self.bindBindingSchemeVar(expr_var, ModuleEnv.varFrom(member_def_idx));
            if (self.predeclaredSchemeVar(member_def_idx)) |predeclared_scheme_var| {
                try self.bindBindingSchemeVar(expr_var, predeclared_scheme_var);
            }
        }
        self.retireNonGeneralizedTypeSchemes(member_roots);
        try self.retireStructurallyPublishedTypeSchemeRequirements(member_roots, env.rank());
        try self.judgeAmbiguityCandidatesAtGeneralizationMultiRoot(member_roots);
        env.var_pool.popRank();
    }

    std.debug.assert(env.rank() == base_rank);
    // Invariant B: every dispatch obligation this group discovered was
    // resolved at its boundary.
    std.debug.assert(self.pending_dispatch_targets.items.len ==
        self.group_stack.items[self.group_stack.items.len - 1].pending_targets_top);
    std.debug.assert(self.pending_predeclared_scheme_uses.items.len ==
        self.group_stack.items[self.group_stack.items.len - 1].pending_predeclared_uses_top);
    _ = self.group_stack.pop();
    self.group_states.items[group_index] = .checked;
}

/// Run the group generalization boundary up to (not including) the generalize
/// call: resolve pending dispatch obligations by checking their target groups
/// in nested frames (Invariant D—nothing may generalize while an obligation
/// into an unchecked group is outstanding), interleaved with boundary literal
/// defaulting to a fixpoint, since a defaulting round can pin a receiver and
/// surface a new obligation.
fn runGroupBoundary(
    self: *Self,
    roots: []const BoundaryRoot,
    env: *Env,
) std.mem.Allocator.Error!void {
    while (true) {
        // Deferred dispatch receivers may have been pinned since the last
        // in-body pass—in a recursive group, the members' def-level
        // pattern=body unifications run after their bodies' dispatch passes,
        // and they can pin a recursive call's result (e.g. #9885's
        // `reverse(rest).append(first)`). Resolve those before generalizing.
        try self.checkStaticDispatchConstraints(env, false);
        try self.resolveGroupPendingDispatchTargets(env);
        const pending_before = self.pending_dispatch_targets.items.len;
        const replayed_before_capture = try self.resolvePendingPredeclaredSchemeUses(env, false);
        try self.defaultLiteralsAtGeneralizationBoundaryMultiRoot(roots, env);
        const replayed_after_capture = try self.resolvePendingPredeclaredSchemeUses(env, true);
        if (replayed_before_capture or replayed_after_capture) continue;
        if (self.pending_dispatch_targets.items.len == pending_before) break;
    }
    try self.finalizeFunctionEffectsAtBoundary(roots, env);
    // Invariant D: every remaining deferred dispatch constraint targets a
    // checked def, an annotated scheme, or a still-flex receiver.
    std.debug.assert(self.pending_dispatch_targets.items.len == self.currentFramePendingTargetsTop());
    std.debug.assert(self.pending_predeclared_scheme_uses.items.len == self.currentFramePendingPredeclaredUsesTop());
}

/// Materialize positive directed-effect results before the enclosing type
/// scheme generalizes. Unresolved results remain `fn_unbound` because their
/// dependency formula is part of the generalized scheme and will be resolved
/// after call-site arguments instantiate and unify it.
fn finalizeFunctionEffectsAtBoundary(self: *Self, roots: []const BoundaryRoot, env: *Env) Allocator.Error!void {
    for (roots) |root| {
        const resolved = self.types.resolveVar(root.interface);
        const flat = switch (resolved.desc.content) {
            .structure => |flat| flat,
            .flex, .rigid, .alias, .field_presence, .err => continue,
        };
        if (try self.functionEffectState(resolved.var_) != .effectful) continue;
        switch (flat) {
            .fn_unbound => |func| try self.types.setVarContent(resolved.var_, .{ .structure = .{ .fn_effectful = func } }),
            .fn_pure => |func| {
                // The body was still effect-polymorphic when it met a pure
                // annotation, but a dependency became positive later in this
                // recursive group. Re-run ordinary effect unification now so
                // the annotation mismatch is reported instead of mutating the
                // annotated type behind the user's back.
                const effectful = try self.freshFromContent(.{ .structure = .{ .fn_effectful = func } }, env, self.getRegionAt(resolved.var_));
                _ = try self.unifyInContext(resolved.var_, effectful, env, .type_annotation);
            },
            .fn_effectful => {},
            .record, .record_unbound, .tuple, .nominal_type, .empty_record, .tag_union, .empty_tag_union => continue,
        }
    }
}

/// Drain the current frame's pending dispatch targets: check each target's
/// group (nested, in its own frame, together with the topological prefix it
/// may name-depend on), then re-run dispatch constraint processing, which may
/// pin further receivers and record further targets—loop to quiescence.
fn resolveGroupPendingDispatchTargets(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    const top = self.currentFramePendingTargetsTop();
    while (self.pending_dispatch_targets.items.len > top) {
        while (self.pending_dispatch_targets.items.len > top) {
            const target_def = self.pending_dispatch_targets.pop().?;
            const target_group = self.defGroupIndex(target_def).?;
            try self.ensureGroupsCheckedUpTo(target_group, env);
        }
        try self.checkStaticDispatchConstraints(env, false);
    }
}

/// Record that a dispatch obligation resolved to `target_def_idx`—an
/// unchecked, unannotated local def—for resolution at the current group's
/// boundary.
fn recordPendingDispatchTarget(self: *Self, target_def_idx: CIR.Def.Idx) std.mem.Allocator.Error!void {
    try self.pending_dispatch_targets.append(self.gpa, target_def_idx);
}

/// The `group_stack` index of the active frame that owns a deferred dispatch
/// obligation stamped with `owner_group_index`, or null when no active frame
/// matches—an unstamped obligation (created outside any group frame) or one
/// whose stamped group already finished, which the frame processing it adopts.
/// Ownership is by group identity, never by rank comparison: ranks are a
/// shared depth counter, so a nested value-def group's boundary rank aliases
/// its enclosing frame's, and unification can collapse a callable's rank all
/// the way to generalized—neither may move an obligation between frames.
fn activeDeferredDispatchObligationOwnerFrame(
    self: *const Self,
    owner_group_index: ?u32,
) ?usize {
    const owner_group = owner_group_index orelse return null;
    var frame_idx = self.group_stack.items.len;
    while (frame_idx > 0) {
        frame_idx -= 1;
        if (self.group_stack.items[frame_idx].group_index == owner_group) return frame_idx;
    }
    return null;
}

/// Whether the frame currently being checked may take over a deferred
/// dispatch obligation whose active owner frame is `owner_frame`.
///
/// An obligation with a live owner is adopted only by that owner, which is
/// the top frame exactly when the lookup found the last index. An obligation
/// with no live owner—never stamped, or stamped by a group that has already
/// popped—is an orphan, and only the outermost active frame may take it: the
/// adopting frame records the target and checks the target's topological
/// prefix inside itself, and a prefix group that names an enclosing frame's
/// still in-flight def would merge with it monomorphically instead of
/// instantiating its finished scheme. The outermost frame encloses no such
/// def, and neither does the frameless context (module finalization, REPL,
/// expect bodies), where nothing is in flight at all.
fn currentFrameAdoptsDeferredDispatchObligation(
    self: *const Self,
    owner_frame: ?usize,
) bool {
    if (owner_frame) |frame_idx| return frame_idx + 1 == self.group_stack.items.len;
    return self.group_stack.items.len <= 1;
}

/// The generalization boundary rank at which a deferred dispatch obligation's
/// callable and receiver are pinned (Invariant D): its owner frame's, the
/// outermost active frame's when the obligation is an orphan that some inner
/// frame is processing, and the current boundary rank when there are no
/// frames.
fn deferredDispatchObligationBoundaryRank(
    self: *const Self,
    owner_frame: ?usize,
) Rank {
    if (owner_frame) |frame_idx| return self.group_stack.items[frame_idx].boundary_rank;
    if (self.group_stack.items.len > 0) return self.group_stack.items[0].boundary_rank;
    return self.currentGroupBoundaryRank();
}

/// Which group owns a dispatch obligation entering the deferred queue.
const DeferredDispatchObligationOwner = union(enum) {
    /// The group frame whose checking created this obligation: the top of
    /// `group_stack`, or none outside every frame.
    current_group,
    /// The creating group captured when the obligation was first recorded,
    /// replayed here from that record.
    recorded: ?u32,
};

/// The single door into the deferred dispatch queue, so an obligation's owning
/// group is stamped in exactly one place. `owner` is explicit at every call:
/// an obligation created by the work of the frame being checked takes
/// `.current_group`, one replayed from a record that already captured its
/// creating frame takes `.recorded`. The retained entries
/// `checkStaticDispatchConstraints` copies back at the end of a pass are not
/// enqueues—they keep the stamp they entered with.
fn enqueueDeferredDispatchConstraint(
    self: *Self,
    env: *Env,
    deferred: DeferredConstraintCheck,
    owner: DeferredDispatchObligationOwner,
) Allocator.Error!void {
    var owned = deferred;
    owned.owner_group_index = switch (owner) {
        .current_group => self.currentGroupIndex(),
        .recorded => |group_index| group_index,
    };
    _ = try env.deferred_static_dispatch_constraints.append(self.gpa, owned);
}

/// Re-defer a dispatch obligation whose method target is an unchecked,
/// unannotated local def. The obligation's owning group frame records the
/// target for its own boundary and pins the relation there; any other frame
/// leaves the obligation waiting, because recording it as a nested frame's
/// pending target would check the target's topological prefix inside that
/// frame, where a prefix group can name the nested frame's still in-flight
/// def and merge with it monomorphically instead of instantiating its
/// finished scheme. An orphan obligation—one whose stamp names no active
/// frame, or that carries no stamp—goes to the outermost active frame for the
/// same reason; only that frame (and the frameless context) encloses no def
/// that a prefix group could capture. A frame that does not adopt still pins
/// the callable and receiver at the adopting frame's boundary rank
/// (Invariant D): the obligation stays waiting across every nested boundary
/// between here and its owner, and nothing it touches may generalize before
/// the owner resolves it.
///
/// Recording the target with no frames at all appends to
/// `pending_dispatch_targets` outside any frame's window, and
/// `currentGroupIndex` leaves the obligation unstamped—both correct there:
/// module finalization and REPL/expect checking have no in-flight def whose
/// boundary could own the resolution.
fn deferDispatchObligationForUncheckedTarget(
    self: *Self,
    deferred_constraint: DeferredConstraintCheck,
    constraint: StaticDispatchConstraint,
    target_def_idx: CIR.Def.Idx,
    env: *Env,
) std.mem.Allocator.Error!void {
    var waiting_constraint = deferred_constraint;
    waiting_constraint.waiting_on_target_def = true;
    const owner_frame = self.activeDeferredDispatchObligationOwnerFrame(
        deferred_constraint.owner_group_index,
    );
    if (self.currentFrameAdoptsDeferredDispatchObligation(owner_frame)) {
        waiting_constraint.owner_group_index = self.currentGroupIndex();
        try self.recordPendingDispatchTarget(target_def_idx);
    }
    const owner_boundary_rank = self.deferredDispatchObligationBoundaryRank(owner_frame);
    try self.pinVarAtRank(constraint.fn_var, owner_boundary_rank, env);
    try self.pinVarAtRank(deferred_constraint.var_, owner_boundary_rank, env);
    try self.scratch_deferred_static_dispatch_constraints.append(waiting_constraint);
}

/// Instantiate an annotation that is available before its body, then retain
/// the use until the current group boundary can replay it against the body's
/// complete scheme. The first instantiation is necessary for ordinary local
/// checking; pinning its result at the boundary keeps all call-site evidence
/// live until the replay adds body-inferred dispatch requirements.
fn instantiatePendingPredeclaredSchemeUse(
    self: *Self,
    target_def: CIR.Def.Idx,
    scheme_var: Var,
    use_var: Var,
    source_expr: CIR.Expr.Idx,
    env: *Env,
) Allocator.Error!void {
    try self.ensurePredeclaredIdentityCorrespondence(target_def, scheme_var);
    const scheme_uses_before = self.cir.scheme_uses.items.items.len;
    const instantiated = try self.instantiateBindingVar(scheme_var, env, .use_last_var);
    const use_pairs_start: u32 = @intCast(self.pending_predeclared_use_pairs.items.len);
    var use_pairs = self.var_map.iterator();
    while (use_pairs.next()) |pair| {
        try self.pending_predeclared_use_pairs.append(self.gpa, .{
            .old_var = pair.key_ptr.*,
            .fresh_var = pair.value_ptr.*,
        });
    }
    _ = try self.unify(use_var, instantiated, env);

    var initial_scheme_use_index: ?u32 = null;
    if (self.cir.scheme_uses.items.items.len > scheme_uses_before) {
        const last_index = self.cir.scheme_uses.items.items.len - 1;
        const record = self.cir.scheme_uses.items.items[last_index];
        if (record.node_idx == @intFromEnum(source_expr) and
            record.slot_kind == @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.value_use))
        {
            initial_scheme_use_index = @intCast(last_index);
        }
    }

    // Pending predeclared uses are only minted while a group frame is open.
    std.debug.assert(self.group_stack.items.len > 0);
    const current_group = self.group_stack.items[self.group_stack.items.len - 1].group_index;
    if (self.defGroupIndex(target_def).? != current_group) {
        try self.pinVarAtGroupBoundaryRank(use_var, env);
    }
    try self.pending_predeclared_scheme_uses.append(self.gpa, .{
        .target_def = target_def,
        .use_var = use_var,
        .source_expr = source_expr,
        .owner_root = self.active_scheme_root,
        .discarded_binding_rhs_expr = self.discarded_binding_rhs_expr,
        .checking_executable_root = self.checking_executable_root,
        .delayed_dependency_depth = self.delayed_dependency_depth,
        .instantiation_is_immediate_callee = self.instantiation_is_immediate_callee,
        .parent_constraint_fn_var = if (self.evidence_target_site) |target| target.constraint_fn_var else null,
        .initial_scheme_use_index = initial_scheme_use_index,
        .use_pairs = .{
            .start = use_pairs_start,
            .len = @intCast(self.pending_predeclared_use_pairs.items.len - @as(usize, use_pairs_start)),
        },
    });
}

fn replayPredeclaredSchemeUse(
    self: *Self,
    pending: PendingPredeclaredSchemeUse,
    scheme_root: Var,
    env: *Env,
) Allocator.Error!void {
    const previous_active_scheme_root = self.active_scheme_root;
    const previous_discarded_binding_rhs_expr = self.discarded_binding_rhs_expr;
    const previous_instantiation_source_expr = self.instantiation_source_expr;
    const previous_checking_executable_root = self.checking_executable_root;
    const previous_delayed_dependency_depth = self.delayed_dependency_depth;
    const previous_instantiation_is_immediate_callee = self.instantiation_is_immediate_callee;
    defer {
        self.active_scheme_root = previous_active_scheme_root;
        self.discarded_binding_rhs_expr = previous_discarded_binding_rhs_expr;
        self.instantiation_source_expr = previous_instantiation_source_expr;
        self.checking_executable_root = previous_checking_executable_root;
        self.delayed_dependency_depth = previous_delayed_dependency_depth;
        self.instantiation_is_immediate_callee = previous_instantiation_is_immediate_callee;
    }

    self.active_scheme_root = pending.owner_root;
    self.discarded_binding_rhs_expr = pending.discarded_binding_rhs_expr;
    self.instantiation_source_expr = pending.source_expr;
    self.checking_executable_root = pending.checking_executable_root;
    self.delayed_dependency_depth = pending.delayed_dependency_depth;
    self.instantiation_is_immediate_callee = pending.instantiation_is_immediate_callee;

    const scheme_idx = self.typeSchemeIndexForRoot(scheme_root).?;

    // Compose body-scheme vars with this use through two pieces of explicit
    // producer data: body identity-slot → predeclared-scheme pairs, then the
    // predeclared-scheme → use pairs saved by the early instantiation.
    // No structural matching or second root unification is involved.
    self.var_map.clearRetainingCapacity();
    var seeded_body_vars = std.AutoHashMap(Var, void).init(self.gpa);
    defer seeded_body_vars.deinit();
    const annotation_pairs = self.predeclared_identity_correspondence_by_def.get(pending.target_def).?.pairs.slice(
        self.predeclared_annotation_pairs.items,
    );
    const use_pairs = pending.use_pairs.slice(self.pending_predeclared_use_pairs.items);
    for (annotation_pairs) |annotation_pair| {
        const predeclared_root = self.types.resolveVar(annotation_pair.fresh_var).var_;
        for (use_pairs) |use_pair| {
            if (self.types.resolveVar(use_pair.old_var).var_ != predeclared_root) continue;
            const body_root = self.types.resolveVar(annotation_pair.old_var).var_;
            try self.var_map.put(body_root, use_pair.fresh_var);
            try seeded_body_vars.put(body_root, {});
            break;
        }
    }

    var instantiator = Instantiator{
        .store = self.types,
        .idents = self.cir.getIdentStoreConst(),
        .var_map = &self.var_map,
        .current_rank = env.rank(),
        .rigid_behavior = .fresh_flex,
    };
    var instantiated_requirements: std.ArrayListUnmanaged(InstantiatedSchemeDispatchRequirement) = .empty;
    defer instantiated_requirements.deinit(self.gpa);
    try self.copySchemeDispatchRequirements(
        scheme_idx,
        &instantiator,
        false,
        &instantiated_requirements,
    );

    // Register only vars created while copying the newly known requirements;
    // seeded body vars are the already-registered early-use vars. Build the
    // complete body-scheme evidence substitution at the same time.
    self.scratch_evidence_pairs.clearRetainingCapacity();
    var map_iter = self.var_map.iterator();
    while (map_iter.next()) |entry| {
        const old_var = entry.key_ptr.*;
        const fresh_var = entry.value_ptr.*;
        const old_resolved = self.types.resolveVar(old_var);
        const fresh_resolved = self.types.resolveVar(fresh_var);
        const old_constraints = switch (old_resolved.desc.content) {
            .flex => |flex| flex.constraints,
            .rigid => |rigid| rigid.constraints,
            .alias, .field_presence, .structure, .err => StaticDispatchConstraint.SafeList.Range.empty(),
        };
        if (old_constraints.len() > 0) {
            try self.scratch_evidence_pairs.append(self.gpa, .{
                .old_var = @intFromEnum(old_resolved.var_),
                .fresh_var = @intFromEnum(fresh_resolved.var_),
            });
            for (self.types.sliceStaticDispatchConstraints(old_constraints)) |old_constraint| {
                const old_fn_root = self.types.resolveVar(old_constraint.fn_var).var_;
                const fresh_fn_var = self.var_map.get(old_fn_root) orelse continue;
                try self.scratch_evidence_pairs.append(self.gpa, .{
                    .old_var = @intFromEnum(old_fn_root),
                    .fresh_var = @intFromEnum(self.types.resolveVar(fresh_fn_var).var_),
                });
            }
        }

        if (seeded_body_vars.contains(old_var)) continue;
        if (fresh_resolved.desc.content == .flex) {
            const flex = fresh_resolved.desc.content.flex;
            if (flex.constraints.len() > 0) {
                // Every constraint copied out of a selected dispatch target
                // belongs to that edge's derivation chain, literal conversions
                // included: recursive-dispatch detection walks this lineage.
                if (pending.parent_constraint_fn_var) |parent_fn_var| {
                    try self.recordDispatchDerivations(flex.constraints, parent_fn_var);
                }
                const constraints = self.types.sliceStaticDispatchConstraints(flex.constraints);
                var has_literal_constraint = false;
                var has_other_constraint = false;
                for (constraints) |constraint| {
                    if (self.constraintIsLiteralConversion(constraint)) {
                        has_literal_constraint = true;
                    } else {
                        has_other_constraint = true;
                    }
                }
                if (has_literal_constraint) try self.recordOpenLiteralVar(fresh_var, constraints, null);
                if (has_other_constraint) {
                    try self.registerInstantiatedAttachedDispatch(
                        fresh_var,
                        flex.constraints,
                        pending.source_expr,
                    );
                }
            }
        }
        try env.var_pool.addVarToRank(fresh_var, fresh_resolved.desc.rank);
        try self.fillInRegionsThrough(fresh_var);
        self.setRegionAt(fresh_var, self.regions.get(@enumFromInt(@intFromEnum(old_var))).*);
    }

    try self.appendSchemeRequirementEvidencePairs(instantiated_requirements.items);

    try self.canonicalizeSchemeUsePairs(&self.scratch_evidence_pairs);

    const scheme_uses_before = self.cir.scheme_uses.items.items.len;
    try self.cir.recordSchemeUse(
        @intFromEnum(pending.source_expr),
        .value_use,
        0,
        scheme_root,
        self.scratch_evidence_pairs.items,
    );
    self.scratch_evidence_pairs.clearRetainingCapacity();

    // If the annotation itself already carried evidence, replace that early
    // record with the complete body scheme's record. The replay appends exactly
    // one value-use record; its pair range remains valid after removing the
    // duplicate row at the tail.
    if (pending.initial_scheme_use_index) |initial_index| {
        std.debug.assert(self.cir.scheme_uses.items.items.len == scheme_uses_before + 1);
        const complete_record = self.cir.scheme_uses.items.items[scheme_uses_before];
        self.cir.scheme_uses.items.items[initial_index] = complete_record;
        self.cir.scheme_uses.items.shrinkRetainingCapacity(scheme_uses_before);
    }

    for (instantiated_requirements.items) |requirement| {
        try self.registerInstantiatedSchemeRequirement(
            requirement,
            pending.source_expr,
            pending.parent_constraint_fn_var,
            env,
        );
    }
}

/// Replay this frame's early annotated uses once their target bodies have
/// published complete schemes. `current_boundary_captured` means the current
/// recursive/SCC roots have just been captured; a current-group target with no
/// side-table scheme then has no hidden requirements and can be discarded.
fn resolvePendingPredeclaredSchemeUses(
    self: *Self,
    env: *Env,
    current_boundary_captured: bool,
) Allocator.Error!bool {
    const top = self.currentFramePendingPredeclaredUsesTop();
    const end = self.pending_predeclared_scheme_uses.items.len;
    var write = top;
    var replayed_any = false;
    var read = top;
    while (read < end) : (read += 1) {
        const pending = self.pending_predeclared_scheme_uses.items[read];
        const target_group = self.defGroupIndex(pending.target_def).?;
        try self.ensureGroupsCheckedUpTo(target_group, env);
        std.debug.assert(self.pending_predeclared_scheme_uses.items.len == end);

        const target_def = self.cir.store.getDef(pending.target_def);
        const target_scheme_root = ModuleEnv.varFrom(target_def.expr);
        const has_pending_requirements = self.typeSchemeIndexForRoot(target_scheme_root) != null;
        // Replays drain a frame's own pending list, so that frame is open.
        std.debug.assert(self.group_stack.items.len > 0);
        const current_group = self.group_stack.items[self.group_stack.items.len - 1].group_index;
        const target_boundary_finished = self.group_states.items[target_group] == .checked or
            (current_boundary_captured and target_group == current_group);
        if (has_pending_requirements) {
            try self.replayPredeclaredSchemeUse(pending, target_scheme_root, env);
            replayed_any = true;
            continue;
        }
        if (target_boundary_finished) continue;

        self.pending_predeclared_scheme_uses.items[write] = pending;
        write += 1;
    }
    self.pending_predeclared_scheme_uses.shrinkRetainingCapacity(write);
    // Saved use pairs are referenced only through the pending entries' ranges
    // (and only while a drain is on the stack, which keeps this list
    // non-empty), so once every frame's suffix has drained the pair storage
    // holds no live ranges and can be reclaimed.
    if (self.pending_predeclared_scheme_uses.items.len == 0) {
        self.pending_predeclared_use_pairs.clearRetainingCapacity();
    }
    return replayed_any;
}

/// Pin `obligation_var`'s class at the current group's boundary rank so no
/// inner frame generalizes it before the obligation resolves (Invariant D,
/// enforced by rank: rank adjustment at each inner generalization keeps
/// everything the obligation touched below the generalizing rank—escaped,
/// alive, and un-generalized until the boundary).
fn pinVarAtGroupBoundaryRank(self: *Self, obligation_var: Var, env: *Env) std.mem.Allocator.Error!void {
    try self.pinVarAtRank(obligation_var, self.currentGroupBoundaryRank(), env);
}

/// Pin `obligation_var`'s class at `boundary_rank` (some active frame's
/// generalization boundary) so no frame nested inside that boundary
/// generalizes it before the obligation pinned there resolves. Never raises a
/// rank and never touches a generalized class.
fn pinVarAtRank(self: *Self, obligation_var: Var, boundary_rank: Rank, env: *Env) std.mem.Allocator.Error!void {
    const resolved = self.types.resolveVar(obligation_var);
    if (resolved.desc.rank != .generalized and
        @intFromEnum(resolved.desc.rank) > @intFromEnum(boundary_rank))
    {
        try self.types.setDescRank(resolved.desc_idx, boundary_rank);
        try env.var_pool.addVarToRank(resolved.var_, boundary_rank);
    }
}

// create types for type decls //

/// Generate a type variable from the provided type statement.
/// If the stmt is not an alias or nominal dec, then do nothing
///
/// The created variable is put in-place at the var slot at `decl_idx`
/// The created variable will be generalized
fn generateStmtTypeDeclType(
    self: *Self,
    decl_idx: CIR.Statement.Idx,
    env: *Env,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    const decl = self.cir.store.getStatement(decl_idx);
    const decl_var = ModuleEnv.varFrom(decl_idx);

    switch (decl) {
        .s_alias_decl, .s_nominal_decl => _ = try self.registerTypeDecl(decl_idx),
        .s_decl,
        .s_var,
        .s_var_uninitialized,
        .s_reassign,
        .s_crash,
        .s_dbg,
        .s_expr,
        .s_expect,
        .s_for,
        .s_while,
        .s_infinite_loop,
        .s_breakable_loop,
        .s_break,
        .s_return,
        .s_import,
        .s_where_alias_decl,
        .s_type_anno,
        .s_type_var_alias,
        .s_runtime_error,
        => {},
    }

    switch (decl) {
        .s_alias_decl => |alias| {
            try self.generateAliasDecl(decl_idx, decl_var, alias, env);
        },
        .s_nominal_decl => |nominal| {
            try self.generateNominalDecl(decl_idx, decl_var, nominal, env);
        },
        .s_where_alias_decl => |where_alias| {
            try self.generateWhereAliasDecl(decl_var, where_alias, env);
        },
        .s_runtime_error => {
            try self.markErroneous(decl_var);
        },
        .s_decl,
        .s_var,
        .s_var_uninitialized,
        .s_reassign,
        .s_crash,
        .s_dbg,
        .s_expr,
        .s_expect,
        .s_for,
        .s_while,
        .s_infinite_loop,
        .s_breakable_loop,
        .s_break,
        .s_return,
        .s_import,
        .s_type_anno,
        .s_type_var_alias,
        => {
            // Do nothing
        },
    }
}

fn ensureTypeDeclGenerated(
    self: *Self,
    decl_idx: CIR.Statement.Idx,
    env: *Env,
) std.mem.Allocator.Error!bool {
    switch (self.typeDeclGenerationState(decl_idx)) {
        .generated => return true,
        .generating => return switch (self.cir.store.getStatement(decl_idx)) {
            // Neither aliases nor where aliases can refer to themselves, so
            // re-entering one means the declaration is cyclic.
            .s_alias_decl, .s_where_alias_decl => false,
            .s_nominal_decl => true,
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => true,
        },
        .not_generated => {},
    }

    self.setTypeDeclGenerationState(decl_idx, .generating);
    errdefer self.setTypeDeclGenerationState(decl_idx, .not_generated);

    const outer_seen_annos = self.seen_annos;
    const outer_type_decl_rigid_vars = self.type_decl_rigid_vars;
    self.seen_annos = try std.DynamicBitSetUnmanaged.initEmpty(self.gpa, @intCast(self.cir.store.nodes.len()));
    self.type_decl_rigid_vars = .{};
    defer {
        self.seen_annos.deinit(self.gpa);
        self.seen_annos = outer_seen_annos;
        self.type_decl_rigid_vars.deinit(self.gpa);
        self.type_decl_rigid_vars = outer_type_decl_rigid_vars;
    }

    try self.generateStmtTypeDeclType(decl_idx, env);
    self.setTypeDeclGenerationState(decl_idx, .generated);
    return true;
}

fn aliasOriginModule(self: *const Self) base.ModuleIdentity.Idx {
    return self.cir.selfModuleIdentity();
}

fn predeclareAliasDecl(
    self: *Self,
    decl_var: Var,
    alias: std.meta.fieldInfo(CIR.Statement, .s_alias_decl).type,
    env: *Env,
) std.mem.Allocator.Error!void {
    const header = self.cir.store.getTypeHeader(alias.header);
    const header_args = self.cir.store.sliceTypeAnnos(header.args);
    const header_vars = try self.generateHeaderVars(header_args, env);
    const backing_var: Var = ModuleEnv.varFrom(alias.anno);

    try self.unifyWithTargetRank(
        decl_var,
        try self.types.mkAliasWithSourceDeclAndBuiltinOrigin(
            .{ .ident_idx = header.relative_name },
            backing_var,
            header_vars,
            self.aliasOriginModule(),
            @intFromEnum(decl_var),
            self.cir.module_role == .builtin,
        ),
        env,
    );
}

fn predeclareNominalDecl(
    self: *Self,
    decl_var: Var,
    nominal: std.meta.fieldInfo(CIR.Statement, .s_nominal_decl).type,
    env: *Env,
) std.mem.Allocator.Error!void {
    const header = self.cir.store.getTypeHeader(nominal.header);
    const header_args = self.cir.store.sliceTypeAnnos(header.args);
    const header_vars = try self.generateHeaderVars(header_args, env);
    const backing_var: Var = ModuleEnv.varFrom(nominal.anno);

    try self.unifyWithTargetRank(
        decl_var,
        try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
            .{ .ident_idx = header.relative_name },
            header_vars,
            self.cir.selfModuleIdentity(),
            @intFromEnum(decl_var),
            nominal.is_opaque,
            self.cir.module_role == .builtin,
        ),
        env,
    );

    try self.registerLocalNominalDecl(
        @intFromEnum(decl_var),
        header.relative_name,
        header_vars,
        backing_var,
        nominal.is_opaque,
    );
}

/// Register (or refresh) the declaration-table entry for a local nominal
/// type declaration. The entry carries exactly the identity bits that nominal
/// applications of this declaration embed, so keyed lookups resolve for every
/// application in this store.
fn registerLocalNominalDecl(
    self: *Self,
    decl_statement: u32,
    name: Ident.Idx,
    header_vars: []const Var,
    backing_var: Var,
    is_opaque: bool,
) Allocator.Error!void {
    const builtin_origin = self.cir.module_role == .builtin;
    _ = try self.types.registerNominalDecl(.{
        .ident = .{ .ident_idx = name },
        .origin_module = self.cir.selfModuleIdentity(),
        .source = try types_mod.NominalType.Source.initChecked(
            try types_mod.SourceDecl.fromStatementWithBuiltinOriginChecked(decl_statement, builtin_origin),
            is_opaque,
            builtin_origin,
        ),
        .formals = try self.types.appendVars(header_vars),
        .backing = backing_var,
        .flags = .{ .valid = true },
    });
}

fn predeclaredAliasArgs(self: *const Self, decl_var: Var) ?[]Var {
    const resolved = self.types.resolveVar(decl_var).desc.content;
    if (resolved != .alias) return null;
    return self.types.sliceAliasArgs(resolved.alias);
}

fn predeclaredNominalArgs(self: *const Self, decl_var: Var) ?[]Var {
    const resolved = self.types.resolveVar(decl_var).desc.content;
    if (resolved != .structure or resolved.structure != .nominal_type) return null;
    return self.types.sliceNominalArgs(resolved.structure.nominal_type);
}

/// Generate types for an alias type declaration
fn generateAliasDecl(
    self: *Self,
    decl_idx: CIR.Statement.Idx,
    decl_var: Var,
    alias: std.meta.fieldInfo(CIR.Statement, .s_alias_decl).type,
    env: *Env,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Get the type header's args
    const header = self.cir.store.getTypeHeader(alias.header);
    const header_args = self.cir.store.sliceTypeAnnos(header.args);

    // Next, generate the provided arg types and build the map of rigid variables in the header
    const predeclared_header_vars = self.predeclaredAliasArgs(decl_var);
    const header_vars = if (predeclared_header_vars) |vars| vars else try self.generateHeaderVars(header_args, env);
    for (header_args) |header_arg_idx| {
        if (self.cir.store.getTypeAnno(header_arg_idx) == .malformed) {
            self.markTypeDeclInvalid(decl_idx);
        }
    }
    if (predeclared_header_vars == null) {
        try self.unifyWithTargetRank(
            decl_var,
            try self.types.mkAliasWithSourceDeclAndBuiltinOrigin(
                .{ .ident_idx = header.relative_name },
                ModuleEnv.varFrom(alias.anno),
                header_vars,
                self.aliasOriginModule(),
                @intFromEnum(decl_idx),
                self.cir.module_role == .builtin,
            ),
            env,
        );
    }

    self.type_decl_rigid_vars.clearRetainingCapacity();
    defer self.type_decl_rigid_vars.clearRetainingCapacity();
    for (header_args, header_vars) |header_arg_idx, header_var| {
        const header_arg = self.cir.store.getTypeAnno(header_arg_idx);
        if (header_arg == .rigid_var) {
            try self.type_decl_rigid_vars.put(self.gpa, header_arg.rigid_var.name, header_var);
        }
    }

    // Now we have a built of list of rigid variables for the decl lhs (header).
    // With this in hand, we can now generate the type for the lhs (body).
    self.seen_annos.unsetAll();
    const backing_var: Var = ModuleEnv.varFrom(alias.anno);
    try self.generateAnnoTypeInPlace(alias.anno, env, .{ .type_decl = .{
        .idx = decl_idx,
        .name = header.relative_name,
        .type_ = .alias,
        .backing_var = backing_var,
        .is_opaque = false,
        .num_args = @intCast(header_args.len),
    } });

    if (!try self.validateAliasRows(backing_var, env, self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(alias.anno)))) {
        self.markTypeDeclInvalid(decl_idx);
        try self.markErroneous(decl_var);
        return;
    }
}

/// Generate the type of a where alias declaration.
///
/// A where alias's type is its receiver: a rigid variable carrying every
/// constraint the declaration names. Referencing the alias instantiates those
/// constraints onto the referencing signature's own variable, so the receiver
/// is the whole of what the declaration contributes.
fn generateWhereAliasDecl(
    self: *Self,
    decl_var: Var,
    where_alias: std.meta.fieldInfo(CIR.Statement, .s_where_alias_decl).type,
    env: *Env,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // A where alias is generated on demand, which can happen part way through
    // building a referencing signature's constraints. Its own scratch entries
    // must not land in that signature's range.
    const scratch_static_dispatch_constraints_top = self.scratch_static_dispatch_constraints.top();
    defer self.scratch_static_dispatch_constraints.clearFrom(scratch_static_dispatch_constraints_top);

    self.seen_annos.unsetAll();
    const ctx = GenTypeAnnoCtx{ .annotation = where_alias.where };

    // Parameters are generated the same way as the receiver rather than as
    // plain header variables, because a constraint can be written against a
    // parameter and must end up on that parameter's own variable.
    const header = self.cir.store.getTypeHeader(where_alias.header);
    for (self.cir.store.sliceTypeAnnos(header.args)) |param_idx| {
        try self.generateAnnoTypeInPlace(param_idx, env, ctx);
    }
    try self.generateAnnoTypeInPlace(where_alias.receiver, env, ctx);

    if (try self.generateRemainingWhereConstraintOwners(where_alias.where, env, ctx)) {
        try self.markErroneous(decl_var);
        return;
    }

    _ = try self.unify(decl_var, ModuleEnv.varFrom(where_alias.receiver), env);
}

/// Generate types for nominal type declaration
fn generateNominalDecl(
    self: *Self,
    decl_idx: CIR.Statement.Idx,
    decl_var: Var,
    nominal: std.meta.fieldInfo(CIR.Statement, .s_nominal_decl).type,
    env: *Env,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Get the type header's args
    const header = self.cir.store.getTypeHeader(nominal.header);
    const header_args = self.cir.store.sliceTypeAnnos(header.args);

    // Next, generate the provided arg types and build the map of rigid variables in the header
    const predeclared_header_vars = self.predeclaredNominalArgs(decl_var);
    const header_vars = if (predeclared_header_vars) |vars| vars else try self.generateHeaderVars(header_args, env);
    for (header_args) |header_arg_idx| {
        if (self.cir.store.getTypeAnno(header_arg_idx) == .malformed) {
            self.markTypeDeclInvalid(decl_idx);
        }
    }
    if (predeclared_header_vars == null) {
        try self.unifyWithTargetRank(
            decl_var,
            try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
                .{ .ident_idx = header.relative_name },
                header_vars,
                self.cir.selfModuleIdentity(),
                @intFromEnum(decl_idx),
                nominal.is_opaque,
                self.cir.module_role == .builtin,
            ),
            env,
        );

        try self.registerLocalNominalDecl(
            @intFromEnum(decl_idx),
            header.relative_name,
            header_vars,
            ModuleEnv.varFrom(nominal.anno),
            nominal.is_opaque,
        );
    }

    self.type_decl_rigid_vars.clearRetainingCapacity();
    defer self.type_decl_rigid_vars.clearRetainingCapacity();
    for (header_args, header_vars) |header_arg_idx, header_var| {
        const header_arg = self.cir.store.getTypeAnno(header_arg_idx);
        if (header_arg == .rigid_var) {
            try self.type_decl_rigid_vars.put(self.gpa, header_arg.rigid_var.name, header_var);
        }
    }

    // Now we have a built of list of rigid variables for the decl lhs (header).
    // With this in hand, we can now generate the type for the lhs (body).
    self.seen_annos.unsetAll();
    const backing_var: Var = ModuleEnv.varFrom(nominal.anno);
    try self.generateAnnoTypeInPlace(nominal.anno, env, .{ .type_decl = .{
        .idx = decl_idx,
        .name = header.relative_name,
        .type_ = .nominal,
        .backing_var = backing_var,
        .is_opaque = nominal.is_opaque,
        .num_args = @intCast(header_args.len),
    } });

    // A malformed backing (its error was already reported while generating
    // the annotation) invalidates the declaration: mark it in the table and
    // poison the decl var so every use instantiates `.err` and is suppressed
    // (declaration validity replaced the unifier's err-backed-nominal
    // short-circuit).
    if (self.types.resolveVar(backing_var).desc.content == .err) {
        if (self.types.lookupNominalDeclByKey(self.cir.selfModuleIdentity(), @intFromEnum(decl_idx))) |table_idx| {
            self.types.markNominalDeclInvalid(table_idx);
        }
        try self.unifyWithTargetRank(decl_var, .err, env);
    }
}

/// Generate types for a standalone type annotation (one without a corresponding definition).
/// These are typically used for FFI function declarations or forward declarations.
fn generateStandaloneTypeAnno(
    self: *Self,
    stmt_var: Var,
    type_anno: std.meta.fieldInfo(CIR.Statement, .s_type_anno).type,
    env: *Env,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Reset seen type annos
    self.seen_annos.unsetAll();

    // Save top of scratch static dispatch constraints
    const scratch_static_dispatch_constraints_top = self.scratch_static_dispatch_constraints.top();
    defer self.scratch_static_dispatch_constraints.clearFrom(scratch_static_dispatch_constraints_top);

    // Generate the type from the annotation
    const anno_var: Var = ModuleEnv.varFrom(type_anno.anno);
    const ctx = GenTypeAnnoCtx{ .annotation = type_anno.where };
    try self.generateAnnoTypeInPlace(type_anno.anno, env, ctx);
    if (type_anno.where) |where_span| {
        if (try self.generateRemainingWhereConstraintOwners(where_span, env, ctx)) {
            try self.markErroneous(anno_var);
        }
    }

    // Unify the statement variable with the generated annotation type
    _ = try self.unify(stmt_var, anno_var, env);
}

/// Generate types for type anno args
fn generateHeaderVars(
    self: *Self,
    header_args: []CIR.TypeAnno.Idx,
    env: *Env,
) std.mem.Allocator.Error![]Var {
    const trace = tracy.trace(@src());
    defer trace.end();

    for (header_args) |header_arg_idx| {
        const header_arg = self.cir.store.getTypeAnno(header_arg_idx);
        const header_var = ModuleEnv.varFrom(header_arg_idx);
        try self.setVarRank(header_var, env);

        switch (header_arg) {
            .rigid_var => |rigid| {
                try self.unifyWith(header_var, .{ .rigid = Rigid.init(rigid.name) }, env);
            },
            .underscore, .malformed => {
                try self.markErroneous(header_var);
            },
            .apply,
            .rigid_var_lookup,
            .lookup,
            .tag_union,
            .tag,
            .tuple,
            .record,
            .@"fn",
            .parens,
            => {
                // The canonicalizer should only produce rigid_var, underscore, or malformed
                // for header args. If we hit this, there's a compiler bug.
                std.debug.assert(false);
                try self.markErroneous(header_var);
            },
        }
    }

    return @ptrCast(header_args);
}

// type gen config //

const OutVar = enum {
    in_place,
    fresh,

    pub fn voidOrVar(comptime out_var: OutVar) type {
        return switch (out_var) {
            .in_place => void,
            .fresh => Var,
        };
    }
};

// annotations //

/// The context use for free var generation
const GenTypeAnnoCtx = union(enum) {
    annotation: ?CIR.WhereClause.Span,
    type_decl: struct {
        idx: CIR.Statement.Idx,
        name: Ident.Idx,
        type_: enum { nominal, alias },
        backing_var: Var,
        is_opaque: bool,
        num_args: u32,
    },
};

fn recordTypeDeclDependencyFromContext(
    self: *Self,
    ctx: GenTypeAnnoCtx,
    dependency_idx: CIR.Statement.Idx,
) std.mem.Allocator.Error!void {
    switch (ctx) {
        .annotation => {},
        .type_decl => |decl| try self.recordTypeDeclDependency(decl.idx, dependency_idx),
    }
}

fn recordTypeDeclAnnoResult(self: *Self, ctx: GenTypeAnnoCtx, anno_var: Var) void {
    switch (ctx) {
        .annotation => {},
        .type_decl => |decl| {
            if (self.types.resolveVar(anno_var).desc.content == .err) {
                self.markTypeDeclInvalid(decl.idx);
            }
        },
    }
}

fn generateAnnotationType(self: *Self, annotation_idx: CIR.Annotation.Idx, env: *Env) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    const annotation_var = ModuleEnv.varFrom(annotation_idx);
    try self.setVarRank(annotation_var, env);

    const annotation = self.cir.store.getAnnotation(annotation_idx);

    // Reset seen type annos
    self.seen_annos.unsetAll();

    // Save top of scratch static dispatch constraints
    const scratch_static_dispatch_constraints_top = self.scratch_static_dispatch_constraints.top();
    defer self.scratch_static_dispatch_constraints.clearFrom(scratch_static_dispatch_constraints_top);

    // Then, generate the type for the annotation
    const ctx = GenTypeAnnoCtx{ .annotation = annotation.where };
    try self.generateAnnoTypeInPlace(annotation.anno, env, ctx);
    if (annotation.where) |where_span| {
        if (try self.generateRemainingWhereConstraintOwners(where_span, env, ctx)) {
            try self.markErroneous(ModuleEnv.varFrom(annotation.anno));
        }
    }

    // Redirect the root annotation to inner annotation
    _ = try self.unify(annotation_var, ModuleEnv.varFrom(annotation.anno), env);
}

/// Push every constraint one where clause places on `owner_var`. A method
/// clause declares exactly one, left for `completeOwnedStaticDispatchConstraint`
/// to type from its annotation; a where alias contributes each constraint it
/// names, already typed by instantiating the declaration.
fn declareOwnedStaticDispatchConstraints(
    self: *Self,
    where_idx: CIR.WhereClause.Idx,
    owner_var: Var,
    env: *Env,
) std.mem.Allocator.Error!void {
    const where_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(where_idx));
    switch (self.cir.store.getWhereClause(where_idx)) {
        .w_method => |method| {
            const func_var = try self.fresh(env, where_region);

            try self.scratch_static_dispatch_constraints.append(ScratchStaticDispatchConstraint{
                .where_clause = where_idx,
                .var_ = owner_var,
                .constraint = StaticDispatchConstraint{
                    .fn_name = method.method_name,
                    .fn_var = func_var,
                    .origin = .{ .where_clause = .{} },
                },
                .state = .declared,
            });
        },
        .w_alias => |alias| try self.declareWhereAliasConstraints(where_idx, alias, owner_var, env),
        .w_malformed => {
            try self.markErroneous(owner_var);
        },
    }
}

fn completeOwnedStaticDispatchConstraint(
    self: *Self,
    where_idx: CIR.WhereClause.Idx,
    method: std.meta.fieldInfo(CIR.WhereClause, .w_method).type,
    owner_var: Var,
    constraint_index: usize,
    env: *Env,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!void {
    const entry = self.scratch_static_dispatch_constraints.items.items[constraint_index];
    if (entry.state != .declared or entry.where_clause != where_idx or entry.var_ != owner_var) {
        try self.markErroneous(entry.var_);
        try self.markStaticDispatchRejected(entry.constraint);
        self.scratch_static_dispatch_constraints.items.items[constraint_index].state = .completed;
        return;
    }

    try self.generateAnnoTypeInPlace(method.var_, env, ctx);

    const args_anno_slice = self.cir.store.sliceTypeAnnos(method.args);
    for (args_anno_slice) |arg_anno_idx| {
        try self.generateAnnoTypeInPlace(arg_anno_idx, env, ctx);
    }
    const anno_arg_vars: []Var = @ptrCast(args_anno_slice);

    try self.generateAnnoTypeInPlace(method.ret, env, ctx);
    const ret_var = ModuleEnv.varFrom(method.ret);

    const func_content = if (method.effectful)
        try self.types.mkFuncEffectful(anno_arg_vars, ret_var)
    else
        try self.types.mkFuncPure(anno_arg_vars, ret_var);
    try self.unifyWith(entry.constraint.fn_var, func_content, env);
    self.scratch_static_dispatch_constraints.items.items[constraint_index].state = .completed;
}

fn generateRemainingWhereConstraintOwners(
    self: *Self,
    where_span: CIR.WhereClause.Span,
    env: *Env,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!bool {
    var invalid_receiver = false;
    for (self.cir.store.sliceWhereClauseOwners(where_span)) |owner| {
        if (owner.owned_by_annotation) {
            try self.generateAnnoTypeInPlace(@enumFromInt(owner.rigid_var), env, ctx);
            continue;
        }

        invalid_receiver = true;
        const rigid_anno = self.cir.store.getTypeAnno(@enumFromInt(owner.rigid_var));
        std.debug.assert(rigid_anno == .rigid_var);
        const type_var_name = rigid_anno.rigid_var.name;
        for (self.cir.store.sliceWhereClausesForOwner(owner)) |where_idx| {
            switch (self.cir.store.getWhereClause(where_idx)) {
                .w_method => |method| {
                    _ = try self.problems.appendProblem(self.gpa, .{ .where_clause_receiver_not_introduced = .{
                        .type_var_name = type_var_name,
                        .method_name = method.method_name,
                        .region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(where_idx)),
                    } });
                },
                .w_alias, .w_malformed => {},
            }
        }
    }
    return invalid_receiver;
}

/// Report and poison a type reference that names a where alias, which is a set
/// of method constraints rather than a type. Returns true once reported.
fn rejectWhereAliasInTypePosition(
    self: *Self,
    name: Ident.Idx,
    base_ref: CIR.TypeAnno.LocalOrExternal,
    anno_var: Var,
    anno_region: Region,
    _: *Env,
) std.mem.Allocator.Error!bool {
    const names_where_alias = switch (base_ref) {
        .local => |local| self.cir.store.getStatement(local.decl_idx) == .s_where_alias_decl,
        .external => |ext| blk: {
            const ext_ref = (try self.resolveVarFromExternal(ext.module_idx, ext.target_node_idx)) orelse break :blk false;
            const stmt: CIR.Statement.Idx = @enumFromInt(@intFromEnum(ext_ref.other_cir_node_idx));
            break :blk ext_ref.other_cir.store.getStatement(stmt) == .s_where_alias_decl;
        },
        .builtin, .pending => false,
    };
    if (!names_where_alias) return false;

    _ = try self.problems.appendProblem(self.gpa, .{ .where_alias_in_type_position = .{
        .name = name,
        .region = anno_region,
    } });
    try self.markErroneous(anno_var);
    return true;
}

/// A where alias declaration, resolved from a reference to it. Every variable
/// is in this module's type store, so a reference to an imported alias has
/// already been copied across the module boundary.
const ResolvedWhereAlias = struct {
    /// The name the where clause used to refer to the declaration.
    name: Ident.Idx,
    /// The receiver, a rigid variable carrying the alias's own constraints.
    receiver: Var,
    /// The declaration's parameters, in declared order. Each is a rigid
    /// variable, and may carry constraints of its own.
    params: []const Var,
};

/// Resolve a where clause's reference to a where alias declaration. Returns
/// null once the reason it could not resolve has been reported.
fn resolveWhereAliasReference(
    self: *Self,
    alias_anno_idx: CIR.TypeAnno.Idx,
    params_scratch: *std.ArrayListUnmanaged(Var),
    env: *Env,
) std.mem.Allocator.Error!?ResolvedWhereAlias {
    const anno = self.cir.store.getTypeAnno(alias_anno_idx);
    const region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(alias_anno_idx));
    const name, const base_ref = switch (anno) {
        .lookup => |lookup| .{ lookup.name, lookup.base },
        .apply => |apply| .{ apply.name, apply.base },
        // Canonicalization already reported why this name has no referent.
        .malformed => return null,
        .rigid_var,
        .rigid_var_lookup,
        .underscore,
        .tag_union,
        .tag,
        .tuple,
        .record,
        .@"fn",
        .parens,
        => unreachable, // canonicalization only builds a name reference here
    };

    switch (base_ref) {
        .local => |local| {
            const decl = switch (self.cir.store.getStatement(local.decl_idx)) {
                .s_where_alias_decl => |decl| decl,
                .s_decl,
                .s_var,
                .s_var_uninitialized,
                .s_reassign,
                .s_crash,
                .s_dbg,
                .s_expr,
                .s_expect,
                .s_for,
                .s_while,
                .s_infinite_loop,
                .s_breakable_loop,
                .s_break,
                .s_return,
                .s_import,
                .s_alias_decl,
                .s_nominal_decl,
                .s_type_anno,
                .s_type_var_alias,
                .s_runtime_error,
                => return try self.reportNotAWhereAlias(name, region),
            };

            if (!try self.ensureTypeDeclGenerated(local.decl_idx, env)) {
                _ = try self.problems.appendProblem(self.gpa, .{ .recursive_where_alias = .{
                    .name = name,
                    .region = region,
                } });
                return null;
            }

            for (self.cir.store.sliceTypeAnnos(self.cir.store.getTypeHeader(decl.header).args)) |param_anno_idx| {
                try params_scratch.append(self.gpa, ModuleEnv.varFrom(param_anno_idx));
            }
            return ResolvedWhereAlias{
                .name = name,
                .receiver = ModuleEnv.varFrom(decl.receiver),
                .params = params_scratch.items,
            };
        },
        .external => |ext| {
            const ext_ref = (try self.resolveVarFromExternal(ext.module_idx, ext.target_node_idx)) orelse {
                // Canonicalization already reported the unresolved import.
                return null;
            };
            const decl = switch (ext_ref.other_cir.store.getStatement(@enumFromInt(@intFromEnum(ext_ref.other_cir_node_idx)))) {
                .s_where_alias_decl => |decl| decl,
                .s_decl,
                .s_var,
                .s_var_uninitialized,
                .s_reassign,
                .s_crash,
                .s_dbg,
                .s_expr,
                .s_expect,
                .s_for,
                .s_while,
                .s_infinite_loop,
                .s_breakable_loop,
                .s_break,
                .s_return,
                .s_import,
                .s_alias_decl,
                .s_nominal_decl,
                .s_type_anno,
                .s_type_var_alias,
                .s_runtime_error,
                => return try self.reportNotAWhereAlias(name, region),
            };

            // Each parameter is copied on its own. Every type variable a where
            // alias's constraints can mention is either the receiver or a
            // parameter, and both are substituted by name below, so the copies
            // do not need to share variables with each other.
            for (ext_ref.other_cir.store.sliceTypeAnnos(ext_ref.other_cir.store.getTypeHeader(decl.header).args)) |param_anno_idx| {
                const param_ref = (try self.resolveVarFromExternal(ext.module_idx, @intFromEnum(param_anno_idx))) orelse return null;
                try params_scratch.append(self.gpa, param_ref.local_var);
            }
            return ResolvedWhereAlias{
                .name = name,
                .receiver = ext_ref.local_var,
                .params = params_scratch.items,
            };
        },
        .builtin => return try self.reportNotAWhereAlias(name, region),
        // An unresolvable import; canonicalization already reported it.
        .pending => return null,
    }
}

/// Report that a where clause named something other than a where alias. Always
/// returns null, so resolution can `return` it directly.
fn reportNotAWhereAlias(self: *Self, name: Ident.Idx, region: Region) std.mem.Allocator.Error!?ResolvedWhereAlias {
    _ = try self.problems.appendProblem(self.gpa, .{ .not_a_where_alias = .{
        .name = name,
        .region = region,
    } });
    return null;
}

/// Expand a where alias reference into the constraints it names, applied to the
/// referencing signature's own type variables.
fn declareWhereAliasConstraints(
    self: *Self,
    where_idx: CIR.WhereClause.Idx,
    alias: std.meta.fieldInfo(CIR.WhereClause, .w_alias).type,
    owner_var: Var,
    env: *Env,
) std.mem.Allocator.Error!void {
    const region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(where_idx));

    var params_scratch: std.ArrayListUnmanaged(Var) = .empty;
    defer params_scratch.deinit(self.gpa);
    const resolved = (try self.resolveWhereAliasReference(alias.alias, &params_scratch, env)) orelse {
        try self.markErroneous(owner_var);
        return;
    };

    // Already generated by `generateWhereAliasReferenceArgs`.
    const arg_vars: []const Var = @ptrCast(self.whereAliasReferenceArgs(alias));

    if (arg_vars.len != resolved.params.len) {
        _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
            .type_name = resolved.name,
            .region = region,
            .num_expected_args = @intCast(resolved.params.len),
            .num_actual_args = @intCast(arg_vars.len),
        } });
        try self.markErroneous(owner_var);
        return;
    }

    // Every rigid variable in the declaration is either the receiver or a
    // parameter, so substituting all of them by name rewrites the declaration's
    // constraints into this signature's variables.
    var subs = std.AutoHashMapUnmanaged(Ident.Idx, Var){};
    defer subs.deinit(self.gpa);
    const receiver_rigid = self.resolvedRigid(resolved.receiver) orelse return;
    try subs.put(self.gpa, receiver_rigid.name, owner_var);
    for (resolved.params, arg_vars) |param_var, arg_var| {
        if (self.resolvedRigid(param_var)) |param_rigid| {
            try subs.put(self.gpa, param_rigid.name, arg_var);
        }
    }

    // Canonicalization rejects a declaration whose constraints are not all on
    // its receiver, so the receiver carries the whole set. Instantiating one
    // appends to the constraint store, so iterate rather than hold a slice.
    var constraints = self.types.iterStaticDispatchConstraints(receiver_rigid.constraints);
    while (constraints.next()) |constraint| {
        try self.scratch_static_dispatch_constraints.append(ScratchStaticDispatchConstraint{
            .where_clause = where_idx,
            .var_ = owner_var,
            .constraint = try self.instantiateWhereAliasConstraint(constraint, &subs, region, env),
            .state = .completed,
        });
    }
}

/// The arguments a where clause supplies for a where alias's parameters.
fn whereAliasReferenceArgs(self: *Self, alias: std.meta.fieldInfo(CIR.WhereClause, .w_alias).type) []const CIR.TypeAnno.Idx {
    return switch (self.cir.store.getTypeAnno(alias.alias)) {
        .apply => |apply| self.cir.store.sliceTypeAnnos(apply.args),
        // A name canonicalization could not resolve carries no arguments; it is
        // reported when the reference is resolved.
        .lookup, .malformed => &.{},
        .rigid_var,
        .rigid_var_lookup,
        .underscore,
        .tag_union,
        .tag,
        .tuple,
        .record,
        .@"fn",
        .parens,
        => unreachable, // canonicalization only builds a name reference here
    };
}

/// Generate the types of the arguments a where alias reference supplies.
fn generateWhereAliasReferenceArgs(
    self: *Self,
    alias: std.meta.fieldInfo(CIR.WhereClause, .w_alias).type,
    env: *Env,
    ctx: GenTypeAnnoCtx,
) std.mem.Allocator.Error!void {
    for (self.whereAliasReferenceArgs(alias)) |arg_anno_idx| {
        try self.generateAnnoTypeInPlace(arg_anno_idx, env, ctx);
    }
}

/// Rewrite one of a where alias declaration's constraints into the referencing
/// signature's variables.
fn instantiateWhereAliasConstraint(
    self: *Self,
    constraint: StaticDispatchConstraint,
    subs: *std.AutoHashMapUnmanaged(Ident.Idx, Var),
    region: Region,
    env: *Env,
) std.mem.Allocator.Error!StaticDispatchConstraint {
    return StaticDispatchConstraint{
        .fn_name = constraint.fn_name,
        .fn_var = try self.instantiateVarWithSubs(constraint.fn_var, subs, env, .{ .explicit = region }),
        .origin = .{ .where_clause = .{} },
    };
}

/// The rigid variable a where alias declaration's receiver or parameter
/// resolved to. Null when the declaration was poisoned, in which case it
/// names no constraints and binds no name to substitute.
fn resolvedRigid(self: *Self, var_: Var) ?Rigid {
    return switch (self.types.resolveVar(var_).desc.content) {
        .rigid => |rigid| rigid,
        .flex, .alias, .field_presence, .structure, .err => null,
    };
}

/// Given an annotation, generate the corresponding type based on the CIR
///
/// This is used both for generation annotation types and type declaration types
///
/// This function will write the type into the type var node at `anno_idx`
///
/// Note on scoping for type decls: Type scopes are defined in czer
///   Point(x) : [Point(x, x)]
///        a^          b^  ^c
///
/// So `a` get the node CIR.TypeAnno.rigid_var{ .. }
/// And `b` & `c` get the node CIR.TypeAnno.rigid_var_lookup{ .ref = <a_id> }
/// Then, any reference to `b` or `c` are replaced with `a` in `generateAnnoTypeInPlace`.
fn generateAnnoTypeInPlace(self: *Self, anno_idx: CIR.TypeAnno.Idx, env: *Env, ctx: GenTypeAnnoCtx) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // First, check if we've seen this anno before
    // This guards against recursive types
    if (self.typeAnnoSeen(anno_idx)) {
        return;
    }

    // Get the annotation
    const anno = self.cir.store.getTypeAnno(anno_idx);
    const anno_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(anno_idx));
    const anno_var = ModuleEnv.varFrom(anno_idx);
    try self.setVarRank(anno_var, env);
    defer self.recordTypeDeclAnnoResult(ctx, anno_var);

    // Put this anno in the "seen" map immediately, to support recursive references
    self.markTypeAnnoSeen(anno_idx);

    switch (anno) {
        .rigid_var => |rigid| {
            if (ctx == .type_decl) {
                if (self.type_decl_rigid_vars.get(rigid.name)) |decl_var| {
                    _ = try self.unify(anno_var, decl_var, env);
                    return;
                }
            }
            const owned_where_clauses: []const CIR.WhereClause.Idx = switch (ctx) {
                .annotation => |mb_where| blk: {
                    const where_span = mb_where orelse break :blk &.{};
                    for (self.cir.store.sliceWhereClauseOwners(where_span)) |owner| {
                        if (owner.rigid_var == @intFromEnum(anno_idx) and owner.owned_by_annotation) {
                            break :blk self.cir.store.sliceWhereClausesForOwner(owner);
                        }
                    }
                    break :blk &.{};
                },
                .type_decl => &.{},
            };

            // A where alias reference's arguments can be this annotation's own
            // constrained type variables, whose generation declares constraints
            // of their own. Generate them before opening this dispatcher's
            // scratch range so those constraints cannot land inside it.
            for (owned_where_clauses) |where_idx| {
                switch (self.cir.store.getWhereClause(where_idx)) {
                    .w_alias => |alias| try self.generateWhereAliasReferenceArgs(alias, env, ctx),
                    .w_method, .w_malformed => {},
                }
            }

            // One source clause can declare more than one constraint: a where
            // alias contributes every constraint it names.
            const scratch_constraints_start = self.scratch_static_dispatch_constraints.top();
            for (owned_where_clauses) |where_idx| {
                try self.declareOwnedStaticDispatchConstraints(where_idx, anno_var, env);
            }
            const scratch_constraints_end = self.scratch_static_dispatch_constraints.top();

            var constraint_representatives = std.AutoHashMap(Ident.Idx, usize).init(self.gpa);
            defer constraint_representatives.deinit();
            try constraint_representatives.ensureTotalCapacity(@intCast(scratch_constraints_end - scratch_constraints_start));

            // A dispatcher's requirements are a method-keyed set. Keep the
            // first source occurrence as its stable evidence position, and
            // share its callable type with every repeated source constraint.
            const static_dispatch_constraints_start = self.types.static_dispatch_constraints.len();
            for (scratch_constraints_start..scratch_constraints_end) |scratch_index| {
                const scratch_constraint = self.scratch_static_dispatch_constraints.items.items[scratch_index];
                const representative = try constraint_representatives.getOrPut(scratch_constraint.constraint.fn_name);
                if (representative.found_existing) {
                    const representative_constraint = self.scratch_static_dispatch_constraints.items.items[representative.value_ptr.*];
                    _ = try self.unify(representative_constraint.constraint.fn_var, scratch_constraint.constraint.fn_var, env);
                    continue;
                }

                representative.value_ptr.* = scratch_index;
                _ = try self.types.static_dispatch_constraints.append(self.types.gpa, scratch_constraint.constraint);
            }
            const static_dispatch_constraints_end = self.types.static_dispatch_constraints.len();
            const static_dispatch_constraints_range = StaticDispatchConstraint.SafeList.Range{ .start = @enumFromInt(static_dispatch_constraints_start), .count = @intCast(static_dispatch_constraints_end - static_dispatch_constraints_start) };

            try self.unifyWith(anno_var, .{ .rigid = Rigid{
                .name = rigid.name,
                .constraints = static_dispatch_constraints_range,
            } }, env);

            // Where-alias constraints were typed as they were declared; only a
            // written method signature still needs its annotation generated,
            // which requires the dispatcher above to already be rigid.
            for (scratch_constraints_start..scratch_constraints_end) |scratch_index| {
                const scratch_constraint = self.scratch_static_dispatch_constraints.items.items[scratch_index];
                if (scratch_constraint.state != .declared) continue;
                switch (self.cir.store.getWhereClause(scratch_constraint.where_clause)) {
                    .w_method => |method| try self.completeOwnedStaticDispatchConstraint(
                        scratch_constraint.where_clause,
                        method,
                        anno_var,
                        scratch_index,
                        env,
                        ctx,
                    ),
                    // Only method clauses are left declared.
                    .w_alias, .w_malformed => unreachable,
                }
            }
        },
        .rigid_var_lookup => |rigid_lookup| {
            _ = try self.unify(anno_var, ModuleEnv.varFrom(rigid_lookup.ref), env);
        },
        .underscore => {
            try self.unifyWith(anno_var, .{ .flex = Flex.init() }, env);
        },
        .lookup => |lookup| {
            if (try self.rejectWhereAliasInTypePosition(lookup.name, lookup.base, anno_var, anno_region, env)) return;
            switch (lookup.base) {
                .builtin => |builtin_type| {
                    try self.setBuiltinTypeContent(anno_var, lookup.name, builtin_type, &.{}, anno_region, env);
                },
                .local => |local| {
                    try self.recordTypeDeclDependencyFromContext(ctx, local.decl_idx);

                    // Check if we're in a declaration or an annotation
                    switch (ctx) {
                        .type_decl => |this_decl| {
                            // If so, check if this is a recursive reference
                            if (this_decl.idx == local.decl_idx) {

                                // If it is a recursive ref, check that there are
                                // no arguments (since this is a lookup, not an apply)
                                if (this_decl.num_args != 0) {
                                    _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
                                        .type_name = this_decl.name,
                                        .region = anno_region,
                                        .num_expected_args = this_decl.num_args,
                                        .num_actual_args = 0,
                                    } });
                                    try self.markErroneous(anno_var);
                                    return;
                                }

                                // If so, then update this annotation to be an instance
                                // of this type using the same backing variable
                                switch (this_decl.type_) {
                                    .alias => {
                                        // Recursion is not allowed in aliases - emit error
                                        _ = try self.problems.appendProblem(self.gpa, .{ .recursive_alias = .{
                                            .type_name = this_decl.name,
                                            .region = anno_region,
                                        } });
                                        try self.markErroneous(anno_var);
                                        return;
                                    },
                                    .nominal => {
                                        // Nominal types can be recursive
                                        try self.unifyWith(anno_var, try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
                                            .{ .ident_idx = this_decl.name },
                                            &.{},
                                            self.cir.selfModuleIdentity(),
                                            @intFromEnum(this_decl.idx),
                                            this_decl.is_opaque,
                                            self.cir.module_role == .builtin,
                                        ), env);
                                    },
                                }

                                return;
                            }
                        },
                        .annotation => {
                            // Otherwise, we're in an annotation and this cannot
                            // be recursive
                        },
                    }

                    const local_decl_var = ModuleEnv.varFrom(local.decl_idx);

                    // Check if this is a for-clause alias (eg Model [Model : model]).
                    // For for-clause aliases, we do not want to instantiate the
                    // variable - each place that references it should reference
                    // the same var.
                    const is_for_clause_alias = self.isForClauseAliasStatement(local.decl_idx);
                    if (is_for_clause_alias) {
                        _ = try self.unify(anno_var, local_decl_var, env);
                    } else {
                        if (!try self.ensureTypeDeclGenerated(local.decl_idx, env)) {
                            _ = try self.problems.appendProblem(self.gpa, .{ .recursive_alias = .{
                                .type_name = lookup.name,
                                .region = anno_region,
                            } });
                            try self.markErroneous(anno_var);
                            return;
                        }
                        const instantiated_var = try self.instantiateVar(local_decl_var, env, .{ .explicit = anno_region });
                        _ = try self.unify(anno_var, instantiated_var, env);
                    }
                },
                .external => |ext| {
                    if (try self.resolveVarFromExternal(ext.module_idx, ext.target_node_idx)) |ext_ref| {
                        const ext_instantiated_var = try self.instantiateVar(
                            ext_ref.local_var,
                            env,
                            .{ .explicit = anno_region },
                        );
                        _ = try self.unify(anno_var, ext_instantiated_var, env);
                    } else {
                        // If this external type is unresolved, can should've reported
                        // an error. So we set to error and continue
                        try self.markErroneous(anno_var);
                    }
                },
                .pending => {
                    // If an import references a non-existent module (e.g., missing from
                    // platform bundle), the pending lookup can't be resolved. Treat as error.
                    try self.markErroneous(anno_var);
                },
            }
        },
        .apply => |a| {
            if (try self.rejectWhereAliasInTypePosition(a.name, a.base, anno_var, anno_region, env)) return;

            // Generate the types for the arguments
            const anno_args = self.cir.store.sliceTypeAnnos(a.args);
            for (anno_args) |anno_arg| {
                try self.generateAnnoTypeInPlace(anno_arg, env, ctx);
            }
            const anno_arg_vars: []Var = @ptrCast(anno_args);

            switch (a.base) {
                .builtin => |builtin_type| {
                    try self.setBuiltinTypeContent(anno_var, a.name, builtin_type, anno_arg_vars, anno_region, env);
                },
                .local => |local| {
                    try self.recordTypeDeclDependencyFromContext(ctx, local.decl_idx);
                    const decl_var = ModuleEnv.varFrom(local.decl_idx);
                    if (self.isForClauseAliasStatement(local.decl_idx)) {
                        try self.generateForClauseAliasApplication(anno_var, decl_var, anno_arg_vars, env);
                        return;
                    }

                    // Check if we're in a declaration or an annotation
                    switch (ctx) {
                        .type_decl => |this_decl| {
                            // If so, check if this is a recursive reference
                            if (this_decl.idx == local.decl_idx) {

                                // If it is a recursive ref, check that the args being
                                // applied here match the number of args of the decl
                                if (anno_arg_vars.len != this_decl.num_args) {
                                    _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
                                        .type_name = this_decl.name,
                                        .region = anno_region,
                                        .num_expected_args = this_decl.num_args,
                                        .num_actual_args = @intCast(anno_args.len),
                                    } });
                                    try self.markErroneous(anno_var);
                                    return;
                                }

                                // If so, then update this annotation to be an instance
                                // of this type using the same backing variable
                                switch (this_decl.type_) {
                                    .alias => {
                                        // Recursion is not allowed in aliases - emit error
                                        _ = try self.problems.appendProblem(self.gpa, .{ .recursive_alias = .{
                                            .type_name = this_decl.name,
                                            .region = anno_region,
                                        } });
                                        try self.markErroneous(anno_var);
                                        return;
                                    },
                                    .nominal => {
                                        // Nominal types can be recursive
                                        try self.unifyWith(anno_var, try self.types.mkNominalWithSourceDeclAndBuiltinOrigin(
                                            .{ .ident_idx = this_decl.name },
                                            anno_arg_vars,
                                            self.cir.selfModuleIdentity(),
                                            @intFromEnum(this_decl.idx),
                                            this_decl.is_opaque,
                                            self.cir.module_role == .builtin,
                                        ), env);
                                    },
                                }

                                return;
                            }
                        },
                        .annotation => {
                            // Otherwise, we're in an annotation and this cannot
                            // be recursive
                        },
                    }

                    if (!try self.ensureTypeDeclGenerated(local.decl_idx, env)) {
                        _ = try self.problems.appendProblem(self.gpa, .{ .recursive_alias = .{
                            .type_name = a.name,
                            .region = anno_region,
                        } });
                        try self.markErroneous(anno_var);
                        return;
                    }

                    // Resolve the referenced type
                    const decl_resolved = self.types.resolveVar(decl_var).desc.content;
                    const decl_is_alias = decl_resolved == .alias;

                    // Get the arguments & name the referenced type
                    const decl_arg_vars, const decl_name = blk: {
                        if (decl_resolved == .alias) {
                            const decl_alias = decl_resolved.alias;
                            break :blk .{ self.types.sliceAliasArgs(decl_alias), decl_alias.ident.ident_idx };
                        } else if (decl_resolved == .structure and decl_resolved.structure == .nominal_type) {
                            const decl_nominal = decl_resolved.structure.nominal_type;
                            break :blk .{ self.types.sliceNominalArgs(decl_nominal), decl_nominal.ident.ident_idx };
                        } else if (decl_resolved == .err) {
                            try self.markErroneous(anno_var);
                            return;
                        } else {
                            // Type applications should only reference aliases or nominal types.
                            // If we hit this, there's a compiler bug.
                            std.debug.assert(false);
                            try self.markErroneous(anno_var);
                            return;
                        }
                    };

                    // Check for an arity mismatch
                    if (decl_arg_vars.len != anno_arg_vars.len) {
                        _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
                            .type_name = decl_name,
                            .region = anno_region,
                            .num_expected_args = @intCast(decl_arg_vars.len),
                            .num_actual_args = @intCast(anno_args.len),
                        } });
                        try self.markErroneous(anno_var);
                        return;
                    }

                    // Then, built the map of applied variables
                    self.rigid_var_substitutions.clearRetainingCapacity();
                    for (decl_arg_vars, anno_arg_vars) |decl_arg_var, anno_arg_var| {
                        const decl_arg_resolved = self.types.resolveVar(decl_arg_var).desc.content;

                        if (decl_arg_resolved == .err) {
                            try self.markErroneous(anno_var);
                            return;
                        }
                        std.debug.assert(decl_arg_resolved == .rigid);
                        const decl_arg_rigid = decl_arg_resolved.rigid;

                        try self.rigid_var_substitutions.put(self.gpa, decl_arg_rigid.name, anno_arg_var);
                    }

                    // Then instantiate the variable, substituting the rigid
                    // variables in the definition with the applied args from
                    // the annotation
                    const instantiated_var = try self.instantiateVarWithSubs(
                        decl_var,
                        &self.rigid_var_substitutions,
                        env,
                        .{ .explicit = anno_region },
                    );
                    if (decl_is_alias and !try self.validateAliasRows(instantiated_var, env, anno_region)) {
                        try self.markErroneous(anno_var);
                        return;
                    }
                    _ = try self.unify(anno_var, instantiated_var, env);
                },
                .external => |ext| {
                    if (try self.resolveVarFromExternal(ext.module_idx, ext.target_node_idx)) |ext_ref| {
                        // Resolve the referenced type
                        const ext_resolved = self.types.resolveVar(ext_ref.local_var).desc.content;
                        const ext_is_alias = ext_resolved == .alias;

                        // Get the arguments & name the referenced type
                        const ext_arg_vars, const ext_name = blk: {
                            switch (ext_resolved) {
                                .alias => |decl_alias| {
                                    break :blk .{ self.types.sliceAliasArgs(decl_alias), decl_alias.ident.ident_idx };
                                },
                                .structure => |flat_type| {
                                    if (flat_type == .nominal_type) {
                                        const decl_nominal = flat_type.nominal_type;
                                        break :blk .{ self.types.sliceNominalArgs(decl_nominal), decl_nominal.ident.ident_idx };
                                    } else {
                                        // External type resolved to a non-nominal structure (e.g., record, func, etc.)
                                        // This shouldn't happen for type applications, treat as error
                                        try self.markErroneous(anno_var);
                                        return;
                                    }
                                },
                                .err, .field_presence => {
                                    try self.markErroneous(anno_var);
                                    return;
                                },
                                .flex, .rigid => {
                                    // External type resolved to a flex or rigid.
                                    // This can happen when the external type is polymorphic but hasn't been
                                    // instantiated yet. We need to use the variable as-is, but this means
                                    // we can't get the arity/name information. This is likely a bug in how
                                    // the external type was set up. For now, treat it as an error.
                                    try self.markErroneous(anno_var);
                                    return;
                                },
                            }
                        };

                        // Check for an arity mismatch
                        if (ext_arg_vars.len != anno_arg_vars.len) {
                            _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
                                .type_name = ext_name,
                                .region = anno_region,
                                .num_expected_args = @intCast(ext_arg_vars.len),
                                .num_actual_args = @intCast(anno_args.len),
                            } });
                            try self.markErroneous(anno_var);
                            return;
                        }

                        // Then, built the map of applied variables
                        self.rigid_var_substitutions.clearRetainingCapacity();
                        for (ext_arg_vars, anno_arg_vars) |decl_arg_var, anno_arg_var| {
                            const decl_arg_resolved = self.types.resolveVar(decl_arg_var).desc.content;

                            if (decl_arg_resolved == .err) {
                                try self.markErroneous(anno_var);
                                return;
                            }
                            std.debug.assert(decl_arg_resolved == .rigid);
                            const decl_arg_rigid = decl_arg_resolved.rigid;

                            try self.rigid_var_substitutions.put(self.gpa, decl_arg_rigid.name, anno_arg_var);
                        }

                        // Then instantiate the variable, substituting the rigid
                        // variables in the definition with the applied args from
                        // the annotation
                        const instantiated_var = try self.instantiateVarWithSubs(
                            ext_ref.local_var,
                            &self.rigid_var_substitutions,
                            env,
                            .{ .explicit = anno_region },
                        );
                        if (ext_is_alias and !try self.validateAliasRows(instantiated_var, env, anno_region)) {
                            try self.markErroneous(anno_var);
                            return;
                        }
                        _ = try self.unify(anno_var, instantiated_var, env);
                    } else {
                        // If this external type is unresolved, can should've reported
                        // an error. So we set to error and continue
                        try self.markErroneous(anno_var);
                    }
                },
                .pending => {
                    // If an import references a non-existent module (e.g., missing from
                    // platform bundle), the pending lookup can't be resolved. Treat as error.
                    try self.markErroneous(anno_var);
                },
            }
        },
        .@"fn" => |func| {
            const args_anno_slice = self.cir.store.sliceTypeAnnos(func.args);
            for (args_anno_slice) |arg_anno_idx| {
                try self.generateAnnoTypeInPlace(arg_anno_idx, env, ctx);
            }
            const args_var_slice: []Var = @ptrCast(args_anno_slice);

            try self.generateAnnoTypeInPlace(func.ret, env, ctx);

            const fn_type = inner_blk: {
                if (func.effectful) {
                    break :inner_blk try self.types.mkFuncEffectful(args_var_slice, ModuleEnv.varFrom(func.ret));
                } else {
                    break :inner_blk try self.types.mkFuncPure(args_var_slice, ModuleEnv.varFrom(func.ret));
                }
            };
            try self.unifyWith(anno_var, fn_type, env);
        },
        .tag_union => |tag_union| {
            const scratch_tags_top = self.scratch_tags.top();
            defer self.scratch_tags.clearFrom(scratch_tags_top);

            const tag_anno_slices = self.cir.store.sliceTypeAnnos(tag_union.tags);
            for (tag_anno_slices) |tag_anno_idx| {
                // Get the tag anno
                const tag_type_anno = self.cir.store.getTypeAnno(tag_anno_idx);
                try self.setVarRank(ModuleEnv.varFrom(tag_anno_idx), env);

                // If the child of the tag union is not a tag, then set as error
                // Canonicalization should have reported this error
                if (tag_type_anno != .tag) {
                    try self.markErroneous(anno_var);
                    return;
                }
                const tag = tag_type_anno.tag;

                // Generate the types for each tag arg
                const tag_anno_args_slice = self.cir.store.sliceTypeAnnos(tag.args);
                for (tag_anno_args_slice) |tag_arg_idx| {
                    try self.generateAnnoTypeInPlace(tag_arg_idx, env, ctx);
                }
                const tag_vars_slice: []Var = @ptrCast(tag_anno_args_slice);

                // Add the processed tag to scratch
                try self.scratch_tags.append(try self.types.mkTag(
                    tag.name,
                    tag_vars_slice,
                ));
            }

            // Get the slice of tags
            const tags_slice = self.scratch_tags.sliceFromStart(scratch_tags_top);
            std.mem.sort(types_mod.Tag, tags_slice, self, struct {
                fn less(checker: *const Self, a: types_mod.Tag, b: types_mod.Tag) bool {
                    return std.mem.order(u8, checker.cir.getIdentStoreConst().getText(a.name), checker.cir.getIdentStoreConst().getText(b.name)) == .lt;
                }
            }.less);

            // Materialize the tags into the types store before processing the
            // ext. `tags_slice` points into the scratch_tags buffer, and
            // generating the ext recurses and may append to scratch_tags,
            // reallocating that buffer and dangling the slice. Copying into a
            // stable range here mirrors the record case below.
            const tags_range = try self.types.appendTags(tags_slice);

            // Process the ext if it exists. Absence means it's a closed union
            const ext_var = inner_blk: {
                if (tag_union.ext) |ext_anno_idx| {
                    try self.generateAnnoTypeInPlace(ext_anno_idx, env, ctx);
                    break :inner_blk ModuleEnv.varFrom(ext_anno_idx);
                } else {
                    break :inner_blk try self.freshFromContent(.{ .structure = .empty_tag_union }, env, anno_region);
                }
            };

            // Set the anno's type
            try self.unifyWith(
                anno_var,
                .{ .structure = types_mod.FlatType{ .tag_union = .{
                    .tags = tags_range,
                    .ext = ext_var,
                } } },
                env,
            );
        },
        .tag => {
            // Tags should only exist as direct children of tag_unions in type annotations.
            // If we encounter a standalone tag here, it's a compiler bug in canonicalization.
            std.debug.assert(false);
            try self.markErroneous(anno_var);
        },
        .record => |rec| {
            const scratch_record_fields_top = self.scratch_record_fields.top();
            defer self.scratch_record_fields.clearFrom(scratch_record_fields_top);

            const recs_anno_slice = self.cir.store.sliceAnnoRecordFields(rec.fields);
            for (recs_anno_slice) |rec_anno_idx| {
                const rec_field = self.cir.store.getAnnoRecordField(rec_anno_idx);

                // Still resolve the field's annotated type (so unnamed padding
                // fields are type-checked), but unnamed fields are layout padding,
                // not real record fields: keep them out of the structural row so
                // they are never unified, name-resolved, or required at
                // construction (and so repeated `_` names cannot collide).
                try self.generateAnnoTypeInPlace(rec_field.ty, env, ctx);
                if (rec_field.is_unnamed) continue;
                const record_field_var = ModuleEnv.varFrom(rec_field.ty);

                // Add the processed field to scratch.
                //
                // Annotations pin field kinds CONCRETELY, in every syntactic
                // position and context: `?:` is the `optional` kind (tagged
                // slot, read with `.?`) and `:` is the `required` kind
                // (`present`), with no polarity split—layout is a function
                // of the annotation alone (design.md "Field Kinds
                // (All-Dynamic Optional Fields)").
                const presence: types_mod.RecordField.Presence = if (rec_field.is_optional) blk: {
                    const presence_var = try self.freshFromContent(
                        .{ .field_presence = .optional },
                        env,
                        anno_region,
                    );
                    break :blk .unknown(presence_var, record_field_var);
                } else if (rec_field.default_value) |default_expr_idx| blk: {
                    // A DEFAULTED field (design.md "Defaulted Fields"): pin
                    // the kind to `defaulted` carrying the default's stable
                    // identity, and RECORD the default expression for the
                    // finalize check—materialization can run before check
                    // order exists and before callee effects resolve, so
                    // typing and purity wait for finalize. Predeclaration's
                    // side effects are unwound, so only the body-pass
                    // materialization records.
                    if (!self.predeclaring_annotation) {
                        const seen = try self.pending_default_seen.getOrPut(self.gpa, default_expr_idx);
                        if (!seen.found_existing) {
                            try self.pending_default_checks.append(self.gpa, .{
                                .default_expr = default_expr_idx,
                                .field_type_var = record_field_var,
                                .field_name = rec_field.name,
                            });
                        }
                    }
                    const presence_var = try self.freshFromContent(
                        .{ .field_presence = .{ .defaulted = .{
                            .origin_module = self.cir.selfModuleIdentity(),
                            .expr_node = @intFromEnum(default_expr_idx),
                        } } },
                        env,
                        anno_region,
                    );
                    break :blk .unknown(presence_var, record_field_var);
                } else .required(record_field_var);
                try self.scratch_record_fields.append(types_mod.RecordField{
                    .name = rec_field.name,
                    .presence = presence,
                });
            }

            // Get the slice of record_fields
            const record_fields_slice = self.scratch_record_fields.sliceFromStart(scratch_record_fields_top);
            std.mem.sort(types_mod.RecordField, record_fields_slice, self.cir.getIdentStore(), types_mod.RecordField.sortByNameAsc);
            const fields_type_range = try self.types.appendRecordFields(record_fields_slice);

            // Process the ext if it exists. Absence (null) means it's a closed record.
            const ext_var = if (rec.ext) |ext_anno_idx| blk: {
                try self.generateAnnoTypeInPlace(ext_anno_idx, env, ctx);
                break :blk ModuleEnv.varFrom(ext_anno_idx);
            } else blk: {
                break :blk try self.freshFromContent(.{ .structure = .empty_record }, env, anno_region);
            };

            // Create the type for the anno in the store
            try self.unifyWith(
                anno_var,
                .{ .structure = types_mod.FlatType{ .record = .{
                    .fields = fields_type_range,
                    .ext = ext_var,
                } } },
                env,
            );
        },
        .tuple => |tuple| {
            const scratch_vars_top = self.scratch_vars.top();
            defer self.scratch_vars.clearFrom(scratch_vars_top);

            const elems_anno_slice = self.cir.store.sliceTypeAnnos(tuple.elems);
            for (elems_anno_slice) |arg_anno_idx| {
                try self.generateAnnoTypeInPlace(arg_anno_idx, env, ctx);
                try self.scratch_vars.append(ModuleEnv.varFrom(arg_anno_idx));
            }
            const elems_range = try self.types.appendVars(self.scratch_vars.sliceFromStart(scratch_vars_top));
            try self.unifyWith(anno_var, .{ .structure = .{ .tuple = .{ .elems = elems_range } } }, env);
        },
        .parens => |parens| {
            try self.generateAnnoTypeInPlace(parens.anno, env, ctx);
            _ = try self.unify(anno_var, ModuleEnv.varFrom(parens.anno), env);
        },
        .malformed => {
            try self.markErroneous(anno_var);
        },
    }
}

fn validateAliasRows(self: *Self, var_: Var, env: *Env, region: Region) Allocator.Error!bool {
    self.var_set.clearRetainingCapacity();
    return self.validateAliasRowsHelp(var_, env, region, &self.var_set);
}

/// Which kind of row a bad-row diagnostic is about.
const AliasRowKind = enum { record, tag_union };

/// What a row frame's step decided: it asked for a child subtree and must be
/// resumed, it exhausted the row, or it reported a bad row and the whole walk
/// is over.
const RowStep = enum { suspended, finished, failed };

/// One suspended step of alias row validation.
///
/// A `node` is a var whose content still has to be inspected; a row frame is a
/// record or tag-union row partway through its own fields, interleaving each
/// field's duplicate-name check with a full walk of that field's type exactly
/// as the row's diagnostics require. Everything a frame pushes sits above it,
/// so a frame resumes only once the subtree it asked for has drained—which is
/// what makes "check name, then walk that field completely, then check the
/// next name" hold without a native frame per level.
const AliasRowFrame = union(enum) {
    node: Var,
    record_row: RecordRowFrame,
    tag_row: TagRowFrame,
};

/// A record row: its head fields, then everything its extension chain
/// contributes. Field names collected so far live in a run of
/// `alias_row_names` starting at `names_base`.
const RecordRowFrame = struct {
    names_base: u32,
    fields: types_mod.RecordField.SafeMultiList.Range,
    idx: u32 = 0,
    /// The var whose duplicate fields report against it while walking the
    /// extension chain; unused while the head fields are being checked, which
    /// report against the offending field itself.
    ext_source_var: Var = undefined,
    /// Where the extension chain resumes once the current run is exhausted.
    ext: Var,
    /// Whether the current run is the last one this row contributes.
    ext_terminates: bool = false,
    guard: types_mod.debug.IterationGuard,
    stage: enum { head_fields, ext_chain, ext_fields } = .head_fields,
};

/// A tag-union row: its head tags, then everything its extension chain
/// contributes. Tag names collected so far live in a run of `alias_row_names`
/// starting at `names_base`.
const TagRowFrame = struct {
    names_base: u32,
    tags: types_mod.Tag.SafeMultiList.Range,
    idx: u32 = 0,
    arg_idx: u32 = 0,
    /// The var duplicate tags report against. Head tags report against the
    /// row's own extension var, extension tags against the extension record
    /// they came from.
    report_var: Var,
    ext: Var,
    ext_terminates: bool = false,
    guard: types_mod.debug.IterationGuard,
    stage: enum { head_tags, head_args, ext_chain, ext_tags, ext_args } = .head_tags,
};

fn validateAliasRowsHelp(
    self: *Self,
    root_var: Var,
    env: *Env,
    region: Region,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    // The whole walk—constructor spines and row payloads alike—runs on an
    // explicit heap stack, so a type of any depth can be validated without a
    // native frame per level. Spine children are pushed in reverse, so pops
    // replay the recursion's exact preorder: a node's first child's whole
    // subtree drains before its next sibling. Rows suspend on a frame instead
    // of re-entering the walk, which keeps their interleaved duplicate-name
    // checks in the order their diagnostics are pinned to.
    const frames = &self.alias_row_frames;
    const frames_base = frames.items.len;
    const names_base = self.alias_row_names.items.len;
    defer {
        frames.items.len = frames_base;
        self.alias_row_names.items.len = names_base;
    }
    try frames.append(self.gpa, .{ .node = root_var });

    while (frames.items.len > frames_base) {
        const top = &frames.items[frames.items.len - 1];
        switch (top.*) {
            .node => |var_| {
                frames.items.len -= 1;
                try self.stepAliasRowNode(var_, visited);
            },
            .record_row => |*frame| {
                // Read the run's base before stepping: the step can push onto
                // `frames` and move the frame this pointer refers to.
                const row_names_base = frame.names_base;
                switch (try self.stepRecordRow(frame, env, region)) {
                    .suspended => {},
                    .finished => {
                        frames.items.len -= 1;
                        self.alias_row_names.items.len = row_names_base;
                    },
                    .failed => return false,
                }
            },
            .tag_row => |*frame| {
                const row_names_base = frame.names_base;
                switch (try self.stepTagRow(frame, env, region)) {
                    .suspended => {},
                    .finished => {
                        frames.items.len -= 1;
                        self.alias_row_names.items.len = row_names_base;
                    },
                    .failed => return false,
                }
            },
        }
    }
    return true;
}

/// Inspect one node: descend constructor spines by pushing their children, and
/// hand rows to a frame that owns their duplicate-name state.
fn stepAliasRowNode(
    self: *Self,
    var_: Var,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!void {
    const resolved = self.types.resolveVar(var_);
    if (visited.contains(resolved.var_)) return;
    try visited.put(resolved.var_, {});

    switch (resolved.desc.content) {
        .alias => |alias| {
            try self.pushAliasRowVarsReversed(self.types.sliceAliasArgs(alias));
            try self.alias_row_frames.append(self.gpa, .{ .node = self.types.getAliasBackingVar(alias) });
        },
        .structure => |flat_type| switch (flat_type) {
            .tuple => |tuple| try self.pushAliasRowVarsReversed(self.types.sliceVars(tuple.elems)),
            .nominal_type => |nominal| try self.pushAliasRowVarsReversed(self.types.sliceNominalArgs(nominal)),
            .fn_pure, .fn_effectful, .fn_unbound => |func| {
                try self.alias_row_frames.append(self.gpa, .{ .node = func.ret });
                try self.pushAliasRowVarsReversed(self.types.sliceVars(func.args));
            },
            .record => |record| {
                try self.alias_row_frames.append(self.gpa, .{ .record_row = .{
                    .names_base = @intCast(self.alias_row_names.items.len),
                    .fields = record.fields,
                    .ext = record.ext,
                    .guard = types_mod.debug.IterationGuard.init("validateRecordExt"),
                } });
            },
            .record_unbound => |fields| {
                // An unbound record has no extension and no duplicate-name
                // check of its own, so its fields are ordinary spine children.
                const field_slice = self.types.getRecordFieldsSlice(fields);
                var i = field_slice.len;
                while (i > 0) {
                    i -= 1;
                    const presence = field_slice.items(.presence)[i];
                    if (presence.presenceVar()) |presence_var| {
                        try self.alias_row_frames.append(self.gpa, .{ .node = presence_var });
                    }
                    try self.alias_row_frames.append(self.gpa, .{ .node = presence.typeVar() });
                }
            },
            .tag_union => |tag_union| {
                try self.alias_row_frames.append(self.gpa, .{ .tag_row = .{
                    .names_base = @intCast(self.alias_row_names.items.len),
                    .tags = tag_union.tags,
                    .report_var = tag_union.ext,
                    .ext = tag_union.ext,
                    .guard = types_mod.debug.IterationGuard.init("validateTagUnionExt"),
                } });
            },
            .empty_record, .empty_tag_union => {},
        },
        .flex, .rigid, .field_presence, .err => {},
    }
}

/// Push a child run onto the alias row visit stack in reverse, so the stack
/// pops the children in their declared order.
fn pushAliasRowVarsReversed(self: *Self, vars: []const Var) Allocator.Error!void {
    var i = vars.len;
    while (i > 0) {
        i -= 1;
        try self.alias_row_frames.append(self.gpa, .{ .node = vars[i] });
    }
}

/// Whether `name` already appears in the row run that starts at `names_base`,
/// recording it when it does not. Names compare by identifier index, exactly
/// as the row's duplicate map keyed them.
///
/// Duplicate names are per row: a field's own type may contain rows that reuse
/// the enclosing row's names, and those are not duplicates of it. That holds
/// because a finished row frame pops its run, so once every frame this row
/// suspended on has drained, `alias_row_names[names_base..]` is exactly the
/// names this row contributed.
fn aliasRowNameIsDuplicate(self: *Self, names_base: u32, name: Ident.Idx) Allocator.Error!bool {
    for (self.alias_row_names.items[names_base..]) |seen| {
        if (seen == name) return true;
    }
    try self.alias_row_names.append(self.gpa, name);
    return false;
}

fn failAliasRow(
    self: *Self,
    comptime row_kind: AliasRowKind,
    actual_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!RowStep {
    try self.reportInvalidAliasRow(row_kind, actual_var, env, region);
    return .failed;
}

/// Read the source field at `idx` within `range`. Indexing through the run's
/// start only happens when the record has fields; start may be undefined when
/// count is 0.
fn aliasRowField(self: *Self, range: types_mod.RecordField.SafeMultiList.Range, idx: u32) types_mod.RecordField {
    return self.types.record_fields.get(@enumFromInt(@intFromEnum(range.start) + idx));
}

fn stepRecordRow(self: *Self, frame: *RecordRowFrame, env: *Env, region: Region) Allocator.Error!RowStep {
    while (true) {
        switch (frame.stage) {
            .head_fields => {
                if (frame.idx < frame.fields.count) {
                    const field = self.aliasRowField(frame.fields, frame.idx);
                    if (try self.aliasRowNameIsDuplicate(frame.names_base, field.name)) {
                        return try self.failAliasRow(.record, field.presence.typeVar(), env, region);
                    }
                    frame.idx += 1;
                    try self.alias_row_frames.append(self.gpa, .{ .node = field.presence.typeVar() });
                    return .suspended;
                }
                frame.stage = .ext_chain;
            },
            .ext_chain => {
                var current = frame.ext;
                while (true) {
                    frame.guard.tick();
                    const resolved = self.types.resolveVar(current);
                    switch (resolved.desc.content) {
                        .alias => |alias| {
                            current = self.types.getAliasBackingVar(alias);
                        },
                        .structure => |flat_type| switch (flat_type) {
                            .record => |record| {
                                frame.fields = record.fields;
                                frame.idx = 0;
                                frame.ext_source_var = current;
                                frame.ext = record.ext;
                                frame.ext_terminates = false;
                                frame.stage = .ext_fields;
                                break;
                            },
                            .record_unbound => |fields| {
                                frame.fields = fields;
                                frame.idx = 0;
                                frame.ext_source_var = current;
                                frame.ext_terminates = true;
                                frame.stage = .ext_fields;
                                break;
                            },
                            .empty_record => return .finished,
                            .tuple,
                            .nominal_type,
                            .fn_pure,
                            .fn_effectful,
                            .fn_unbound,
                            .tag_union,
                            .empty_tag_union,
                            => {
                                return try self.failAliasRow(.record, current, env, region);
                            },
                        },
                        .flex, .rigid, .field_presence, .err => return .finished,
                    }
                }
            },
            .ext_fields => {
                if (frame.idx < frame.fields.count) {
                    const field = self.aliasRowField(frame.fields, frame.idx);
                    if (try self.aliasRowNameIsDuplicate(frame.names_base, field.name)) {
                        return try self.failAliasRow(.record, frame.ext_source_var, env, region);
                    }
                    frame.idx += 1;
                    try self.alias_row_frames.append(self.gpa, .{ .node = field.presence.typeVar() });
                    return .suspended;
                }
                if (frame.ext_terminates) return .finished;
                frame.stage = .ext_chain;
            },
        }
    }
}

/// Read the source tag at `idx` within `range`. Indexing through the run's
/// start only happens when the tag union has tags; start may be undefined when
/// count is 0.
fn aliasRowTag(self: *Self, range: types_mod.Tag.SafeMultiList.Range, idx: u32) types_mod.Tag {
    return self.types.tags.get(@enumFromInt(@intFromEnum(range.start) + idx));
}

fn stepTagRow(self: *Self, frame: *TagRowFrame, env: *Env, region: Region) Allocator.Error!RowStep {
    while (true) {
        switch (frame.stage) {
            .head_tags => {
                if (frame.idx < frame.tags.count) {
                    const tag = self.aliasRowTag(frame.tags, frame.idx);
                    if (try self.aliasRowNameIsDuplicate(frame.names_base, tag.name)) {
                        return try self.failAliasRow(.tag_union, frame.report_var, env, region);
                    }
                    frame.arg_idx = 0;
                    frame.stage = .head_args;
                    continue;
                }
                frame.stage = .ext_chain;
            },
            .head_args, .ext_args => {
                const tag = self.aliasRowTag(frame.tags, frame.idx);
                const args = self.types.sliceVars(tag.args);
                if (frame.arg_idx < args.len) {
                    const arg_var = args[frame.arg_idx];
                    frame.arg_idx += 1;
                    try self.alias_row_frames.append(self.gpa, .{ .node = arg_var });
                    return .suspended;
                }
                frame.idx += 1;
                frame.stage = switch (frame.stage) {
                    .head_args => .head_tags,
                    .ext_args => .ext_tags,
                    .head_tags, .ext_chain, .ext_tags => unreachable,
                };
            },
            .ext_chain => {
                var current = frame.ext;
                while (true) {
                    frame.guard.tick();
                    const resolved = self.types.resolveVar(current);
                    switch (resolved.desc.content) {
                        .alias => |alias| {
                            current = self.types.getAliasBackingVar(alias);
                        },
                        .structure => |flat_type| switch (flat_type) {
                            .tag_union => |tag_union| {
                                frame.tags = tag_union.tags;
                                frame.idx = 0;
                                frame.report_var = current;
                                frame.ext = tag_union.ext;
                                frame.stage = .ext_tags;
                                break;
                            },
                            .empty_tag_union => return .finished,
                            .record,
                            .record_unbound,
                            .tuple,
                            .nominal_type,
                            .fn_pure,
                            .fn_effectful,
                            .fn_unbound,
                            .empty_record,
                            => {
                                return try self.failAliasRow(.tag_union, current, env, region);
                            },
                        },
                        .flex, .rigid, .field_presence, .err => return .finished,
                    }
                }
            },
            .ext_tags => {
                if (frame.idx < frame.tags.count) {
                    const tag = self.aliasRowTag(frame.tags, frame.idx);
                    if (try self.aliasRowNameIsDuplicate(frame.names_base, tag.name)) {
                        return try self.failAliasRow(.tag_union, frame.report_var, env, region);
                    }
                    frame.arg_idx = 0;
                    frame.stage = .ext_args;
                    continue;
                }
                frame.stage = .ext_chain;
            },
        }
    }
}

fn reportInvalidAliasRow(
    self: *Self,
    comptime row_kind: AliasRowKind,
    actual_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!void {
    const expected_content: Content = switch (row_kind) {
        .record => .{ .structure = .empty_record },
        .tag_union => .{ .structure = .empty_tag_union },
    };
    const expected_var = try self.freshFromContent(expected_content, env, region);
    const expected_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, expected_var);
    const actual_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, actual_var);

    _ = try self.problems.appendProblem(self.gpa, .{ .type_mismatch = .{
        .types = .{
            .expected_var = expected_var,
            .expected_snapshot = expected_snapshot,
            .actual_var = actual_var,
            .actual_snapshot = actual_snapshot,
        },
        .context = .type_annotation,
    } });
}

/// Set the content of anno_var to the builtin type.
///
/// Uses unifyWith to efficiently set content directly when possible,
/// avoiding the creation of an intermediate type variable.
fn setBuiltinTypeContent(
    self: *Self,
    anno_var: Var,
    anno_builtin_name: Ident.Idx,
    anno_builtin_type: CIR.TypeAnno.Builtin,
    anno_args: []Var,
    anno_region: Region,
    env: *Env,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    switch (anno_builtin_type) {
        // Phase 5: Use nominal types from Builtin instead of special .num content
        .u8 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.u8), env),
        .u16 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.u16), env),
        .u32 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.u32), env),
        .u64 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.u64), env),
        .u128 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.u128), env),
        .i8 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.i8), env),
        .i16 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.i16), env),
        .i32 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.i32), env),
        .i64 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.i64), env),
        .i128 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.i128), env),
        .f32 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.f32), env),
        .f64 => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.f64), env),
        .dec => try self.unifyWith(anno_var, try self.mkNumberTypeContent(.dec), env),
        .list => {
            // Then check arity
            if (anno_args.len != 1) {
                _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
                    .type_name = anno_builtin_name,
                    .region = anno_region,
                    .num_expected_args = 1,
                    .num_actual_args = @intCast(anno_args.len),
                } });

                // Set error
                try self.markErroneous(anno_var);
                return;
            }

            // Create the nominal List type
            const list_content = try self.mkListContent(anno_args[0]);
            try self.unifyWith(anno_var, list_content, env);
        },
        .box => {
            // Then check arity
            if (anno_args.len != 1) {
                _ = try self.problems.appendProblem(self.gpa, .{ .type_apply_mismatch_arities = .{
                    .type_name = anno_builtin_name,
                    .region = anno_region,
                    .num_expected_args = 1,
                    .num_actual_args = @intCast(anno_args.len),
                } });

                // Set error
                try self.markErroneous(anno_var);
                return;
            }

            // Create the nominal Box type
            const box_content = try self.mkBoxContent(anno_args[0]);
            try self.unifyWith(anno_var, box_content, env);
        },
        // Polymorphic Num type is a module, not a type itself
        .num => {
            // Set error - Num is a module containing numeric types, not a type
            try self.markErroneous(anno_var);
        },
    }
}

// types //

/// Expression-local expectations. Lambda return targets live in
/// `ReturnConstraintFrame` so a nested expression annotation cannot replace them.
const Expected = struct {
    annotation: ?CIR.Annotation.Idx = null,
    expected_type: ?ExpectedType = null,
    branch_result: ?Var = null,
    comptime_condition_warnings: enum { emit, suppress } = .emit,
    hoist_position: HoistPosition = .suppressed,

    const ExpectedType = struct {
        var_: Var,
        context: problem.Context,
    };

    fn none() Expected {
        return .{};
    }

    fn fromAnnotation(annotation_idx: CIR.Annotation.Idx) Expected {
        return Expected.none().withAnnotation(annotation_idx);
    }

    fn withAnnotation(self: Expected, annotation_idx: CIR.Annotation.Idx) Expected {
        return .{
            .annotation = annotation_idx,
            .expected_type = self.expected_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn withExpectedType(self: Expected, expected_type: ExpectedType) Expected {
        return .{
            .annotation = self.annotation,
            .expected_type = expected_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn withMaterializedAnnotation(self: Expected, expected_type: ExpectedType) Expected {
        return .{
            .annotation = null,
            .expected_type = expected_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn withBranchResult(self: Expected, branch_result: Var) Expected {
        return .{
            .annotation = self.annotation,
            .expected_type = self.expected_type,
            .branch_result = branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn withHoistPosition(self: Expected, hoist_position: HoistPosition) Expected {
        return .{
            .annotation = self.annotation,
            .expected_type = self.expected_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = hoist_position,
        };
    }

    fn suppressHoistSelection(self: Expected) Expected {
        return self.withHoistPosition(.suppressed);
    }

    fn forComptimeRoot(self: Expected) Expected {
        return .{
            .annotation = self.annotation,
            .expected_type = self.expected_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = .suppress,
            .hoist_position = .comptime_root,
        };
    }

    fn forBranchBody(self: Expected) Expected {
        return .{
            .branch_result = self.branch_result,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = .suppressed,
        };
    }

    fn forStatement(self: Expected) Expected {
        return .{
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn forReturnValue(self: Expected, expected_return: ?Var) Expected {
        return .{
            .branch_result = expected_return,
            .comptime_condition_warnings = self.comptime_condition_warnings,
            .hoist_position = self.hoist_position,
        };
    }

    fn suppressComptimeConditionWarnings(self: Expected) Expected {
        return .{
            .annotation = self.annotation,
            .expected_type = self.expected_type,
            .branch_result = self.branch_result,
            .comptime_condition_warnings = .suppress,
            .hoist_position = self.hoist_position,
        };
    }

    fn emitsComptimeConditionWarnings(self: Expected) bool {
        return self.comptime_condition_warnings == .emit;
    }
};

const TryArgs = struct {
    ok: Var,
    err: Var,
};

// pattern //

/// The "polarity" of a tag union or record
const Polarity = enum { open, closed };

/// The context that this pattern is being called in
/// This determines if, for tag unions & records, they should be inferred
/// as open or closed
const PatternCtx = enum {
    bound,
    fn_arg,
    from_annotation,
    for_,
    match_branch,

    fn toPolarity(self: PatternCtx) Polarity {
        return switch (self) {
            .bound, .fn_arg, .for_ => .closed,
            .from_annotation, .match_branch => .open,
        };
    }
};

/// Check the types for the provided pattern, saving the type in-place
fn checkPattern(
    self: *Self,
    pattern_idx: CIR.Pattern.Idx,
    ctx: PatternCtx,
    env: *Env,
) std.mem.Allocator.Error!void {
    _ = try self.checkPatternHelp(pattern_idx, ctx, env, .in_place);
}

/// Check the types for the provided pattern, either as fresh var or in-place
fn checkPatternHelp(
    self: *Self,
    pattern_idx: CIR.Pattern.Idx,
    ctx: PatternCtx,
    env: *Env,
    comptime out_var: OutVar,
) std.mem.Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();

    const pattern = self.cir.store.getPattern(pattern_idx);
    const pattern_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(pattern_idx));
    const pattern_var = switch (comptime out_var) {
        .fresh => try self.fresh(env, pattern_region),
        .in_place => blk: {
            try self.setVarRank(ModuleEnv.varFrom(pattern_idx), env);
            break :blk ModuleEnv.varFrom(pattern_idx);
        },
    };

    switch (pattern) {
        .assign => {
            // Assigned variables start out as flex (initialized in preflight),
            // and their type is refined by usage. Reassignments reuse the same
            // pattern var, so never overwrite existing constraints here.
        },
        .underscore => {
            // Underscore can be anything; leave its placeholder flex intact.
        },
        // str //
        .str_literal => {
            // A literal pattern converts through from_quote and compares the
            // matched value against the converted constant, so the type also
            // needs equality.
            const flex_var = try self.mkFlexWithFromQuoteConstraint(ModuleEnv.nodeIdxFrom(pattern_idx), pattern_region, env);
            _ = try self.unify(pattern_var, flex_var, env);
            try self.mkPatternLiteralEqConstraint(pattern_var, env, pattern_region);
        },
        .str_interpolation => |str| {
            const str_var = try self.freshStr(env, pattern_region);
            _ = try self.unify(pattern_var, str_var, env);

            var step_offset: u32 = 0;
            while (step_offset < str.steps.span.len) : (step_offset += 1) {
                const step = self.cir.store.getStrPatternStep(str.steps, step_offset);
                if (step.capture) |capture_idx| {
                    const capture_region = self.cir.store.getPatternRegion(capture_idx);
                    const capture_var = try self.checkPatternHelp(capture_idx, ctx, env, .in_place);
                    const capture_str_var = try self.freshStr(env, capture_region);
                    _ = try self.unify(capture_var, capture_str_var, env);
                }
            }
        },
        // as //
        .as => |p| {
            const var_ = try self.checkPatternHelp(p.pattern, ctx, env, out_var);
            _ = try self.unify(var_, pattern_var, env);
        },
        // tuple //
        .tuple => |tuple| {
            const elem_vars_slice = blk: {
                switch (comptime out_var) {
                    .fresh => {
                        const scratch_vars_top = self.scratch_vars.top();
                        defer self.scratch_vars.clearFrom(scratch_vars_top);

                        // Check tuple elements
                        const elems_slice = self.cir.store.slicePatterns(tuple.patterns);
                        for (elems_slice) |single_elem_ptrn_idx| {
                            const elem_var = try self.checkPatternHelp(single_elem_ptrn_idx, ctx, env, out_var);
                            try self.scratch_vars.append(elem_var);
                        }

                        // Add to types store
                        break :blk try self.types.appendVars(self.scratch_vars.sliceFromStart(scratch_vars_top));
                    },
                    .in_place => {
                        // Check tuple elements
                        const elems_slice = self.cir.store.slicePatterns(tuple.patterns);
                        for (elems_slice) |single_elem_ptrn_idx| {
                            _ = try self.checkPatternHelp(single_elem_ptrn_idx, ctx, env, out_var);
                        }

                        // Add to types store
                        // Cast the elems idxs to vars (this works because Anno Idx are 1-1 with type Vars)
                        break :blk try self.types.appendVars(@ptrCast(elems_slice));
                    },
                }
            };

            // Set the type in the store
            try self.unifyWith(pattern_var, .{ .structure = .{
                .tuple = .{ .elems = elem_vars_slice },
            } }, env);
        },
        // list //
        .list => |list| {
            const elems = self.cir.store.slicePatterns(list.patterns);
            if (elems.len == 0) {
                // Create a nominal List with a fresh unbound element type
                const elem_var = try self.fresh(env, pattern_region);
                const list_content = try self.mkListContent(elem_var);
                try self.unifyWith(pattern_var, list_content, env);
            } else {

                // Here, we use the list's 1st element as the element var to
                // constrain the rest of the list

                // Check the first elem
                const elem_var = try self.checkPatternHelp(elems[0], ctx, env, out_var);

                // Iterate over the remaining elements
                var last_elem_ptrn_idx = elems[0];
                for (elems[1..], 1..) |elem_ptrn_idx, i| {
                    const cur_elem_var = try self.checkPatternHelp(elem_ptrn_idx, ctx, env, out_var);

                    // Unify each element's var with the list's elem var
                    const result = try self.unifyInContext(elem_var, cur_elem_var, env, .{ .list_entry = .{
                        .elem_index = @intCast(i),
                        .list_length = @intCast(elems.len),
                        .last_elem_idx = ModuleEnv.nodeIdxFrom(last_elem_ptrn_idx),
                    } });

                    // If we errored, check the rest of the elements without comparing
                    // to the elem_var to catch their individual errors
                    if (!result.isEstablished()) {
                        for (elems[i + 1 ..]) |remaining_elem_expr_idx| {
                            _ = try self.checkPatternHelp(remaining_elem_expr_idx, ctx, env, out_var);
                        }

                        // Break to avoid cascading errors
                        break;
                    }

                    last_elem_ptrn_idx = elem_ptrn_idx;
                }

                // Create a nominal List type with the inferred element type
                const list_content = try self.mkListContent(elem_var);
                try self.unifyWith(pattern_var, list_content, env);
            }

            // Then, check the "rest" pattern is bound to the list value.
            // This is if the pattern is like `.. as x`.
            if (list.rest_info) |rest_info| {
                if (rest_info.pattern) |rest_pattern_idx| {
                    const rest_pattern_var = try self.checkPatternHelp(rest_pattern_idx, ctx, env, out_var);

                    _ = try self.unify(pattern_var, rest_pattern_var, env);
                }
            }
        },
        // applied tag //
        .applied_tag => |applied_tag| {
            // Create a tag type in the type system and assign it the expr_var

            const arg_vars_slice = blk: {
                switch (comptime out_var) {
                    .fresh => {
                        const scratch_vars_top = self.scratch_vars.top();
                        defer self.scratch_vars.clearFrom(scratch_vars_top);

                        // Check tuple elements
                        const arg_ptrn_idx_slice = self.cir.store.slicePatterns(applied_tag.args);
                        for (arg_ptrn_idx_slice) |arg_expr_idx| {
                            const arg_var = try self.checkPatternHelp(arg_expr_idx, ctx, env, out_var);
                            try self.scratch_vars.append(arg_var);
                        }

                        // Add to types store
                        break :blk try self.types.appendVars(self.scratch_vars.sliceFromStart(scratch_vars_top));
                    },

                    .in_place => {
                        // Process each tag arg
                        const arg_ptrn_idx_slice = self.cir.store.slicePatterns(applied_tag.args);
                        for (arg_ptrn_idx_slice) |arg_expr_idx| {
                            _ = try self.checkPatternHelp(arg_expr_idx, ctx, env, out_var);
                        }

                        // Add to types store
                        // Cast the elems idxs to vars (this works because Anno Idx are 1-1 with type Vars)
                        break :blk try self.types.appendVars(@ptrCast(arg_ptrn_idx_slice));
                    },
                }
            };

            // Create the type
            const ext_var = switch (ctx.toPolarity()) {
                .open => try self.fresh(env, pattern_region),
                .closed => try self.freshFromContent(.{ .structure = .empty_tag_union }, env, pattern_region),
            };

            const tag = types_mod.Tag{ .name = applied_tag.name, .args = arg_vars_slice };
            const tag_union_content = try self.types.mkTagUnion(&[_]types_mod.Tag{tag}, ext_var);

            // Update the expr to point to the new type
            try self.unifyWith(pattern_var, tag_union_content, env);
        },
        // nominal //
        .nominal => |nominal| {
            // Check the backing pattern first
            const actual_backing_var = try self.checkPatternHelp(nominal.backing_pattern, ctx, env, out_var);

            // Use shared nominal type checking logic
            _ = try self.checkNominalTypeUsage(
                pattern_var,
                actual_backing_var,
                ModuleEnv.varFrom(nominal.nominal_type_decl),
                nominal.backing_type,
                pattern_region,
                env,
                .exact,
                null,
            );
        },
        .nominal_external => |nominal| {
            // Check the backing pattern first
            const actual_backing_var = try self.checkPatternHelp(nominal.backing_pattern, ctx, env, out_var);

            // Resolve the external type declaration
            if (try self.resolveVarFromExternal(nominal.module_idx, nominal.target_node_idx)) |ext_ref| {
                // Use shared nominal type checking logic
                _ = try self.checkNominalTypeUsage(
                    pattern_var,
                    actual_backing_var,
                    ext_ref.local_var,
                    nominal.backing_type,
                    pattern_region,
                    env,
                    .exact,
                    null,
                );
            } else {
                try self.markErroneous(pattern_var);
            }
        },
        // record destructure //
        .record_destructure => |destructure| {
            const scratch_records_top = self.scratch_record_fields.top();
            defer self.scratch_record_fields.clearFrom(scratch_records_top);

            var mb_ext_var: ?Var = null;

            for (self.cir.store.sliceRecordDestructs(destructure.destructs)) |destruct_idx| {
                const destruct = self.cir.store.getRecordDestruct(destruct_idx);
                const destruct_var = ModuleEnv.varFrom(destruct_idx);
                try self.setVarRank(destruct_var, env);

                // Check the sub pattern
                const field_pattern_var = blk: {
                    switch (destruct.kind) {
                        .Required => |sub_pattern_idx| {
                            break :blk try self.checkPatternHelp(sub_pattern_idx, ctx, env, out_var);
                        },
                        .SubPattern => |sub_pattern_idx| {
                            break :blk try self.checkPatternHelp(sub_pattern_idx, ctx, env, out_var);
                        },
                        .Rest => |sub_pattern_idx| {
                            // If this pattern is rest pattern:
                            // eg { name, ...rest }
                            //               ^^^^
                            //
                            // Then capture this as the ext var, then  continue
                            const ext_var = try self.checkPatternHelp(sub_pattern_idx, ctx, env, out_var);
                            _ = try self.unify(destruct_var, ext_var, env);
                            mb_ext_var = ext_var;

                            continue;
                        },
                    }
                };

                // Set the destruct var to redirect to the field pattern var
                _ = try self.unify(destruct_var, field_pattern_var, env);

                // The destructured field probes the record with a
                // kind-FLEXIBLE presence var (the same mint as a record
                // update's probe): the record's kind decides what the binder
                // sees. The row's value type is a FRESH payload var—the
                // binder is deliberately NOT the field's value type here,
                // because an `optional` kind binds it to
                // `Try(payload, [MissingField])` instead of the payload
                // itself. `judgeRecordDestructBinds` performs that
                // kind-directed binding at every generalization boundary
                // (and finalize); a still-flex kind pins `required` there—
                // destructuring must not silently make a field optional—
                // which is also why this mint is NOT recorded in
                // `literal_field_kinds` (design.md "Field Kinds").
                const destruct_region = self.getRegionAt(destruct_var);
                const presence_var = try self.fresh(env, destruct_region);
                const payload_var = try self.fresh(env, destruct_region);
                try self.pending_record_destructs.append(self.gpa, .{
                    .presence_var = presence_var,
                    .payload_var = payload_var,
                    .binder_var = destruct_var,
                    .field_name = destruct.label,
                    .region = destruct_region,
                });

                // Append it to the scratch records array
                try self.scratch_record_fields.append(types_mod.RecordField{
                    .name = destruct.label,
                    .presence = .unknown(presence_var, payload_var),
                });
            }

            // Copy the scratch record fields into the types store
            const record_fields_scratch = self.scratch_record_fields.sliceFromStart(scratch_records_top);
            std.mem.sort(types_mod.RecordField, record_fields_scratch, self.cir.getIdentStore(), types_mod.RecordField.sortByNameAsc);

            const record_fields_range = try self.types.appendRecordFields(record_fields_scratch);
            // Update the pattern var. A `..` rest pattern makes the record open
            // (its extension absorbs any remaining fields); without one, the
            // pattern is closed, so destructuring a record that has extra fields
            // is a type mismatch the user must resolve (e.g. by adding the field
            // or a `..` rest).
            const ext_var = mb_ext_var orelse
                try self.freshFromContent(.{ .structure = .empty_record }, env, pattern_region);
            try self.unifyWith(pattern_var, .{ .structure = .{
                .record = .{
                    .fields = record_fields_range,
                    .ext = ext_var,
                },
            } }, env);
        },
        // nums //
        .num_from_numeral_literal => {
            try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(pattern_idx), pattern_var, pattern_region, .pattern, env);
        },
        .num_literal => |num| {
            switch (num.kind) {
                // For unannotated literals, create a flex var with from_numeral constraint
                .num_unbound, .int_unbound => try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(pattern_idx), pattern_var, pattern_region, .pattern, env),
                // Phase 5: For explicitly typed literals, use nominal types from Builtin
                .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => try self.unifyWith(pattern_var, try self.mkNumberTypeContent(num.kind), env),
            }
        },
        .frac_f32_literal => {
            // Phase 5: Use nominal F32 type
            try self.unifyWith(pattern_var, try self.mkNumberTypeContent(.f32), env);
        },
        .frac_f64_literal => {
            // Phase 5: Use nominal F64 type
            try self.unifyWith(pattern_var, try self.mkNumberTypeContent(.f64), env);
        },
        .dec_literal => |dec| {
            if (dec.has_suffix) {
                // Explicit suffix like `3.14dec` - use nominal Dec type
                try self.unifyWith(pattern_var, try self.mkNumberTypeContent(.dec), env);
            } else {
                try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(pattern_idx), pattern_var, pattern_region, .pattern, env);
            }
        },
        .small_dec_literal => |dec| {
            if (dec.has_suffix) {
                // Explicit suffix - use nominal Dec type
                try self.unifyWith(pattern_var, try self.mkNumberTypeContent(.dec), env);
            } else {
                try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(pattern_idx), pattern_var, pattern_region, .pattern, env);
            }
        },
        .runtime_error => {
            try self.markErroneous(pattern_var);
        },
    }

    return pattern_var;
}

fn getPatternIdent(self: *const Self, ptrn_idx: CIR.Pattern.Idx) ?Ident.Idx {
    const pattern = self.cir.store.getPattern(ptrn_idx);
    switch (pattern) {
        .assign => |assign| return assign.ident,
        .as => |as_pattern| return as_pattern.ident,
        .applied_tag,
        .nominal,
        .nominal_external,
        .record_destructure,
        .list,
        .tuple,
        .num_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .num_from_numeral_literal,
        .str_literal,
        .str_interpolation,
        .underscore,
        .runtime_error,
        => return null,
    }
}

const CirPatternRefutabilityAdapter = struct {
    pub const PatternId = CIR.Pattern.Idx;

    checker: *const Self,

    pub fn patternClass(self: @This(), pattern_idx: PatternId) PatternRefutability.PatternClass {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .assign,
            .underscore,
            .runtime_error,
            => .cannot_miss,
            .as,
            .nominal,
            .nominal_external,
            => .child,
            .tuple => .sequence,
            .record_destructure => .record,
            .list => .list,
            .applied_tag,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            => .can_miss,
        };
    }

    pub fn child(self: @This(), pattern_idx: PatternId) PatternId {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .as => |as_pattern| as_pattern.pattern,
            .nominal => |nominal| nominal.backing_pattern,
            .nominal_external => |nominal| nominal.backing_pattern,
            .assign,
            .applied_tag,
            .record_destructure,
            .list,
            .tuple,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn sequenceLen(self: @This(), pattern_idx: PatternId) usize {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .tuple => |tuple| self.checker.cir.store.slicePatterns(tuple.patterns).len,
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .record_destructure,
            .list,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn sequenceChild(self: @This(), pattern_idx: PatternId, index: usize) PatternId {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .tuple => |tuple| self.checker.cir.store.slicePatterns(tuple.patterns)[index],
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .record_destructure,
            .list,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn recordLen(self: @This(), pattern_idx: PatternId) usize {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .record_destructure => |destructure| self.checker.cir.store.sliceRecordDestructs(destructure.destructs).len,
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .list,
            .tuple,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn recordChild(self: @This(), pattern_idx: PatternId, index: usize) PatternId {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .record_destructure => |destructure| blk: {
                const destruct_idx = self.checker.cir.store.sliceRecordDestructs(destructure.destructs)[index];
                const destruct = self.checker.cir.store.getRecordDestruct(destruct_idx);
                break :blk destruct.kind.toPatternIdx();
            },
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .list,
            .tuple,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn listFixedLen(self: @This(), pattern_idx: PatternId) usize {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .list => |list| self.checker.cir.store.slicePatterns(list.patterns).len,
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .record_destructure,
            .tuple,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn listHasRest(self: @This(), pattern_idx: PatternId) bool {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .list => |list| list.rest_info != null,
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .record_destructure,
            .tuple,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }

    pub fn listRestPattern(self: @This(), pattern_idx: PatternId) ?PatternId {
        const pattern = self.checker.cir.store.getPattern(pattern_idx);
        return switch (pattern) {
            .list => |list| list.rest_info.?.pattern,
            .assign,
            .as,
            .applied_tag,
            .nominal,
            .nominal_external,
            .record_destructure,
            .tuple,
            .num_literal,
            .num_from_numeral_literal,
            .small_dec_literal,
            .dec_literal,
            .frac_f32_literal,
            .frac_f64_literal,
            .str_literal,
            .str_interpolation,
            .underscore,
            .runtime_error,
            => unreachable,
        };
    }
};

fn patternNeedsExhaustiveness(self: *const Self, pattern_idx: CIR.Pattern.Idx) bool {
    return PatternRefutability.canMiss(CirPatternRefutabilityAdapter, .{ .checker = self }, pattern_idx);
}

const PatternBinding = struct {
    ident: Ident.Idx,
    pattern_idx: CIR.Pattern.Idx,
};

const MatchAltBaselineEntry = struct { pattern_idx: CIR.Pattern.Idx, pattern_index: u32 };

fn reportMatchAltBinderProblem(
    self: *Self,
    expected_pattern_idx: CIR.Pattern.Idx,
    actual_pattern_idx: CIR.Pattern.Idx,
    binder_ident: Ident.Idx,
    branch_index: u32,
    first_pattern_index: u32,
    pattern_index: u32,
    num_branches: u32,
    num_patterns: u32,
    match_expr: CIR.Expr.Idx,
) std.mem.Allocator.Error!void {
    const expected_var = ModuleEnv.varFrom(expected_pattern_idx);
    const actual_var = ModuleEnv.varFrom(actual_pattern_idx);
    const expected_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, expected_var);
    const actual_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, actual_var);

    _ = try self.problems.appendProblem(self.gpa, .{ .type_mismatch = .{
        .types = .{
            .expected_var = expected_var,
            .expected_snapshot = expected_snapshot,
            .actual_var = actual_var,
            .actual_snapshot = actual_snapshot,
        },
        .context = .{ .match_alt_binder = .{
            .branch_index = branch_index,
            .first_pattern_index = first_pattern_index,
            .pattern_index = pattern_index,
            .num_branches = num_branches,
            .num_patterns = num_patterns,
            .binder_ident = binder_ident,
            .match_expr = match_expr,
        } },
    } });
}

fn collectPatternBindings(
    self: *const Self,
    pattern_idx: CIR.Pattern.Idx,
    out: *std.ArrayList(PatternBinding),
) std.mem.Allocator.Error!void {
    const pattern = self.cir.store.getPattern(pattern_idx);
    switch (pattern) {
        .assign => |assign| try out.append(self.gpa, .{ .ident = assign.ident, .pattern_idx = pattern_idx }),
        .as => |as_pat| {
            try out.append(self.gpa, .{ .ident = as_pat.ident, .pattern_idx = pattern_idx });
            try self.collectPatternBindings(as_pat.pattern, out);
        },
        .tuple => |tuple| {
            for (self.cir.store.slicePatterns(tuple.patterns)) |elem_pattern_idx| {
                try self.collectPatternBindings(elem_pattern_idx, out);
            }
        },
        .applied_tag => |tag| {
            for (self.cir.store.slicePatterns(tag.args)) |arg_pattern_idx| {
                try self.collectPatternBindings(arg_pattern_idx, out);
            }
        },
        .record_destructure => |destructure| {
            for (self.cir.store.sliceRecordDestructs(destructure.destructs)) |destruct_idx| {
                const destruct = self.cir.store.getRecordDestruct(destruct_idx);
                switch (destruct.kind) {
                    .Required => |sub_pattern_idx| try self.collectPatternBindings(sub_pattern_idx, out),
                    .SubPattern => |sub_pattern_idx| try self.collectPatternBindings(sub_pattern_idx, out),
                    .Rest => |sub_pattern_idx| try self.collectPatternBindings(sub_pattern_idx, out),
                }
            }
        },
        .list => |list| {
            for (self.cir.store.slicePatterns(list.patterns)) |elem_pattern_idx| {
                try self.collectPatternBindings(elem_pattern_idx, out);
            }
            if (list.rest_info) |rest| {
                if (rest.pattern) |rest_pattern_idx| {
                    try self.collectPatternBindings(rest_pattern_idx, out);
                }
            }
        },
        .nominal => |nom| try self.collectPatternBindings(nom.backing_pattern, out),
        .nominal_external => |nom| try self.collectPatternBindings(nom.backing_pattern, out),
        .str_interpolation => |str| {
            var step_offset: u32 = 0;
            while (step_offset < str.steps.span.len) : (step_offset += 1) {
                const step = self.cir.store.getStrPatternStep(str.steps, step_offset);
                if (step.capture) |capture_idx| {
                    try self.collectPatternBindings(capture_idx, out);
                }
            }
        },
        .num_literal,
        .num_from_numeral_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .str_literal,
        .underscore,
        .runtime_error,
        => {},
    }
}

fn unifyMatchAltPatternBindings(
    self: *Self,
    branch_ptrn_idxs: []const CIR.Expr.Match.BranchPattern.Idx,
    branch_index: u32,
    num_branches: u32,
    match_expr: CIR.Expr.Idx,
    env: *Env,
) std.mem.Allocator.Error!bool {
    if (branch_ptrn_idxs.len <= 1) return false;

    self.alt_pattern_baseline.clearRetainingCapacity();
    self.alt_pattern_bindings.clearRetainingCapacity();

    {
        const first_branch_pattern = self.cir.store.getMatchBranchPattern(branch_ptrn_idxs[0]);
        try self.collectPatternBindings(first_branch_pattern.pattern, &self.alt_pattern_bindings);
        for (self.alt_pattern_bindings.items) |binding| {
            try self.alt_pattern_baseline.put(@as(u32, @bitCast(binding.ident)), .{
                .pattern_idx = binding.pattern_idx,
                .pattern_index = 0,
            });
        }
    }

    var had_type_error = false;

    for (branch_ptrn_idxs[1..], 1..) |branch_ptrn_idx, pattern_index| {
        self.alt_pattern_bindings.clearRetainingCapacity();
        const branch_pattern = self.cir.store.getMatchBranchPattern(branch_ptrn_idx);
        try self.collectPatternBindings(branch_pattern.pattern, &self.alt_pattern_bindings);

        self.alt_pattern_current.clearRetainingCapacity();

        for (self.alt_pattern_bindings.items) |binding| {
            const key: u32 = @bitCast(binding.ident);
            try self.alt_pattern_current.put(key, binding.pattern_idx);
            const first = self.alt_pattern_baseline.get(key) orelse {
                const first_branch_pattern = self.cir.store.getMatchBranchPattern(branch_ptrn_idxs[0]);
                try self.reportMatchAltBinderProblem(
                    first_branch_pattern.pattern,
                    binding.pattern_idx,
                    binding.ident,
                    branch_index,
                    0,
                    @intCast(pattern_index),
                    num_branches,
                    @intCast(branch_ptrn_idxs.len),
                    match_expr,
                );
                had_type_error = true;
                continue;
            };
            const result = try self.unifyInContext(
                ModuleEnv.varFrom(first.pattern_idx),
                ModuleEnv.varFrom(binding.pattern_idx),
                env,
                .{ .match_alt_binder = .{
                    .branch_index = branch_index,
                    .first_pattern_index = first.pattern_index,
                    .pattern_index = @intCast(pattern_index),
                    .num_branches = num_branches,
                    .num_patterns = @intCast(branch_ptrn_idxs.len),
                    .binder_ident = binding.ident,
                    .match_expr = match_expr,
                } },
            );
            if (!result.isEstablished()) had_type_error = true;
        }

        var baseline_iter = self.alt_pattern_baseline.iterator();
        while (baseline_iter.next()) |entry| {
            if (self.alt_pattern_current.contains(entry.key_ptr.*)) continue;

            const ident: Ident.Idx = @bitCast(entry.key_ptr.*);
            try self.reportMatchAltBinderProblem(
                entry.value_ptr.pattern_idx,
                branch_pattern.pattern,
                ident,
                branch_index,
                entry.value_ptr.pattern_index,
                @intCast(pattern_index),
                num_branches,
                @intCast(branch_ptrn_idxs.len),
                match_expr,
            );
            had_type_error = true;
        }
    }

    return had_type_error;
}

// expr //

const CheckedStoredValue = struct {
    does_fx: bool,
    var_: Var,
};

/// Check an expression that a containing value stores, instantiating an
/// expression-position function scheme at this exact construction edge. The
/// containing value must refer to the fresh instance: embedding the pristine
/// generalized scheme would let later projections bypass the scheme-use edge
/// that supplies the nested function's static-dispatch evidence.
fn checkStoredValueExpr(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    env: *Env,
    expected: Expected,
) std.mem.Allocator.Error!CheckedStoredValue {
    const does_fx = try self.checkExpr(expr_idx, env, expected);
    const source_var = ModuleEnv.varFrom(expr_idx);
    const resolved_source = self.types.resolveVar(source_var);
    if (resolved_source.desc.rank != .generalized and !self.isBindingSchemeVar(source_var)) {
        return .{ .does_fx = does_fx, .var_ = source_var };
    }

    const previous_source = self.instantiation_source_expr;
    self.instantiation_source_expr = expr_idx;
    defer self.instantiation_source_expr = previous_source;
    std.debug.assert(self.pending_nested_function_use == null);
    self.pending_nested_function_use = expr_idx;
    const instance_var = try self.instantiateBindingVar(source_var, env, .use_last_var);
    std.debug.assert(self.pending_nested_function_use == null);
    return .{
        .does_fx = does_fx,
        .var_ = instance_var,
    };
}

fn checkExpr(self: *Self, expr_idx: CIR.Expr.Idx, env: *Env, expected: Expected) std.mem.Allocator.Error!bool {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Attribute any dispatcher instantiated while checking this expression to it,
    // so an ambiguity verdict can pinpoint the source of an unsatisfiable
    // body-forced where-clause. Restored on exit to track the innermost expr.
    const prev_instantiation_source = self.instantiation_source_expr;
    self.instantiation_source_expr = expr_idx;
    defer self.instantiation_source_expr = prev_instantiation_source;

    const expr = self.cir.store.getExpr(expr_idx);
    const expr_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(expr_idx));
    const expr_var_raw = ModuleEnv.varFrom(expr_idx);
    // Expression nodes can be checked again after more constraints settle. The
    // dense slot always describes this check, so a prior error cannot retire a
    // parent after the expression has checked successfully.
    self.call_operand_type_error_exprs.items[nodeSlot(expr_idx)] = false;

    // Consume the checking_call_arg flag: it applies only to this immediate
    // checkExpr call and must not propagate to recursive calls (e.g. nested call
    // arguments). Value-producing wrappers explicitly forward it only to the
    // child that supplies their result (see `checkExprInCallPosition`), keeping
    // an immediately called lambda from generalizing through a closure, block,
    // conditional, or match.
    const is_call_arg = self.checking_call_arg;
    self.checking_call_arg = false;

    const is_immediate_callee = self.checking_immediate_callee;
    self.checking_immediate_callee = false;

    const prev_instantiation_is_immediate_callee = self.instantiation_is_immediate_callee;
    self.instantiation_is_immediate_callee = is_immediate_callee;
    defer self.instantiation_is_immediate_callee = prev_instantiation_is_immediate_callee;

    // Consume the binding-RHS flag: it applies only to this immediate checkExpr
    // call and must not propagate into subexpressions.
    const is_binding_rhs = self.checking_binding_rhs;
    const binding_rhs_pattern = self.checking_binding_rhs_pattern;
    self.checking_binding_rhs = false;
    self.checking_binding_rhs_pattern = null;

    const prev_discarded_binding_rhs_expr = self.discarded_binding_rhs_expr;
    if (is_binding_rhs) {
        if (binding_rhs_pattern) |pattern_idx| {
            if (self.cir.store.getPattern(pattern_idx) == .underscore) {
                self.discarded_binding_rhs_expr = expr_idx;
            }
        }
    }
    defer self.discarded_binding_rhs_expr = prev_discarded_binding_rhs_expr;

    // A recursive group member's top-level RHS lives in the group's shared
    // rank frame and generalizes at the group boundary, not on its own.
    // Consume-once; `e_closure` re-asserts it onto its inner lambda below.
    const suppress_group_member_generalize = self.suppress_generalize_expr == expr_idx;
    if (suppress_group_member_generalize) self.suppress_generalize_expr = null;

    // Decide whether this binding generalizes—see `shouldGeneralize` for the
    // three qualifying paths and why each is sound.
    const should_generalize = !suppress_group_member_generalize and
        self.shouldGeneralize(expr, expected.annotation, is_binding_rhs, is_call_arg);

    // A generalizing expression owns every pending dispatch relation created
    // while its body is checked. Save/restore makes nested generalized lambdas
    // exact owners rather than folding their requirements into an enclosing
    // scheme.
    const previous_active_scheme_root = self.active_scheme_root;
    if (should_generalize) self.active_scheme_root = expr_var_raw;
    defer self.active_scheme_root = previous_active_scheme_root;

    // Push/pop ranks based on if we should generalize
    if (should_generalize) try env.var_pool.pushRank();
    defer if (should_generalize) {
        env.var_pool.popRank();
    };

    try self.setVarRank(expr_var_raw, env);

    // Generate the expr var and the expected type vars.
    //
    // If the current expression has an annotation, materialize it once here and
    // pass children the resulting expected var. Children must not regenerate the
    // same annotation, because that creates distinct rigid vars with the same
    // source names.
    const expr_var: Var, const mb_anno_vars: ?AnnoVars, const nested_expected: Expected = blk: {
        if (expr == .e_closure) {
            // Closures delegate to their inner lambda's checkExpr, which handles
            // annotation and generalization. Forward expected so the annotation
            // type is created at the lambda's rank.
            // (The e_closure-wraps-e_lambda invariant is asserted by isFunctionDef.)
            break :blk .{ expr_var_raw, null, expected };
        }

        if (expected.annotation) |annotation_idx| {
            // Generate the type for the annotation
            try self.generateAnnotationType(annotation_idx, env);
            if (self.checking_predeclared_body_def) |predeclared_def_idx| {
                try self.recordPredeclaredBodyAnnotationPairs(predeclared_def_idx, annotation_idx);
            }
            const anno_var = ModuleEnv.varFrom(annotation_idx);

            // Copy/paste the variable. This will be used if the expr errors to
            // preserve the type annotation for places that reference this def.
            const anno_var_backup = try self.instantiateVarOrphan(
                anno_var,
                env,
                env.rank(),
                .use_last_var,
            );

            break :blk .{
                try self.fresh(env, expr_region),
                .{
                    .anno_var = anno_var,
                    .anno_var_backup = anno_var_backup,
                    .context = .type_annotation,
                },
                // The annotation is also the expected result of any `if`/
                // `match` at the body's root: each branch checks against it
                // directly (instead of pairwise against the previous branch),
                // so annotation-declared facts—e.g. an `optional` field
                // kind—pin branch types before the branches merge
                // (design.md "Field Kinds (All-Dynamic Optional Fields)").
                expected.withMaterializedAnnotation(.{
                    .var_ = anno_var,
                    .context = .type_annotation,
                }).withBranchResult(anno_var),
            };
        } else if (expected.expected_type) |expected_type| {
            const expected_var_backup = try self.instantiateVarOrphan(
                expected_type.var_,
                env,
                env.rank(),
                .use_last_var,
            );

            break :blk .{
                try self.fresh(env, expr_region),
                .{
                    .anno_var = expected_type.var_,
                    .anno_var_backup = expected_var_backup,
                    .context = expected_type.context,
                },
                // As in the annotation path above: the expected type is the
                // expected result of any `if`/`match` at the body's root, so
                // branches check against it directly and annotation-declared
                // facts pin branch types before the branches merge.
                expected.withBranchResult(expected_type.var_),
            };
        } else {
            break :blk .{ expr_var_raw, null, expected };
        }
    };

    var does_fx = false; // Does this expression potentially perform any side effects?
    const child_expected = nested_expected.forStatement();
    self.checking_binding_rhs_pattern = binding_rhs_pattern;
    errdefer self.checking_binding_rhs_pattern = null;
    var hoist_frame = try self.beginHoistFrame(expr_idx, is_binding_rhs, nested_expected.hoist_position);
    self.checking_binding_rhs_pattern = null;
    defer hoist_frame.deinit();

    switch (expr) {
        // str //
        .e_str_segment => {
            const str_var = try self.freshStr(env, expr_region);
            _ = try self.unify(expr_var, str_var, env);
        },
        .e_bytes_literal => {
            // Create List(U8) type
            const u8_content = try self.mkNumberTypeContent(.u8);
            const u8_var = try self.freshFromContent(u8_content, env, expr_region);
            const list_content = try self.mkListContent(u8_var);
            try self.unifyWith(expr_var, list_content, env);
        },
        .e_str => |str| {
            // Iterate over the string segments, checking each one
            const segment_expr_idx_slice = self.cir.store.sliceExpr(str.span);
            var did_err = false;
            var has_interpolation = false;
            for (segment_expr_idx_slice) |seg_expr_idx| {
                const seg_expr = self.cir.store.getExpr(seg_expr_idx);

                // String literal segments are already Str type
                if (seg_expr == .e_str_segment) {
                    does_fx = try self.checkExpr(seg_expr_idx, env, child_expected) or does_fx;
                } else {
                    has_interpolation = true;
                    does_fx = try self.checkExpr(seg_expr_idx, env, child_expected) or does_fx;
                    const seg_var = ModuleEnv.varFrom(seg_expr_idx);

                    // Interpolated expressions must be of type Str
                    const seg_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(seg_expr_idx));
                    const expected_str_var = try self.freshStr(env, seg_region);

                    const unify_result = try self.unify(expected_str_var, seg_var, env);
                    if (!unify_result.isAccepted()) {
                        // Unification failed - mark as error
                        try self.markErroneous(seg_var);
                        did_err = true;
                    }
                }

                // Check if it errored (for non-interpolation segments)
                if (!did_err) {
                    const seg_var = ModuleEnv.varFrom(seg_expr_idx);
                    did_err = self.types.resolveVar(seg_var).desc.content == .err;
                }
            }

            if (did_err) {
                // If any segment errored, propagate that error to the root string
                try self.markErroneous(expr_var);
            } else if (has_interpolation) {
                // Interpolated strings are Str
                const str_var = try self.freshStr(env, expr_region);
                _ = try self.unify(expr_var, str_var, env);
            } else {
                // A plain literal converts to its target type through from_quote,
                // defaulting to Str if nothing pins it.
                const flex_var = try self.mkFlexWithFromQuoteConstraint(ModuleEnv.nodeIdxFrom(expr_idx), expr_region, env);
                if (self.cir.numericSuffixTargetForNode(ModuleEnv.nodeIdxFrom(expr_idx))) |suffix_target| {
                    // Explicit type suffix, e.g. `"foo".MyType`.
                    try self.unifyLiteralWithSuffixTarget(flex_var, suffix_target, expr_region, env);
                }
                _ = try self.unify(expr_var, flex_var, env);
            }
        },
        // nums //
        .e_num => |num| {
            switch (num.kind) {
                // For unannotated literals, create a flex var with from_numeral constraint
                .num_unbound, .int_unbound => try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(expr_idx), expr_var, expr_region, .expression, env),
                .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => try self.unifyWith(expr_var, try self.mkNumberTypeContent(num.kind), env),
            }
        },
        .e_num_from_numeral => {
            try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(expr_idx), expr_var, expr_region, .expression, env);
        },
        .e_frac_f32 => |frac| {
            if (frac.has_suffix) {
                try self.unifyWith(expr_var, try self.mkNumberTypeContent(.f32), env);
            } else {
                try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(expr_idx), expr_var, expr_region, .expression, env);
            }
        },
        .e_frac_f64 => |frac| {
            if (frac.has_suffix) {
                try self.unifyWith(expr_var, try self.mkNumberTypeContent(.f64), env);
            } else {
                try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(expr_idx), expr_var, expr_region, .expression, env);
            }
        },
        .e_dec => |frac| {
            if (frac.has_suffix) {
                const literal = self.recordedNumeralLiteralForNode(ModuleEnv.nodeIdxFrom(expr_idx));
                const num_literal_info = try self.exactNumeralInfoForLiteral(literal, expr_region);
                _ = try self.reportInvalidBuiltinFromNumeralInfo(expr_var, .dec, num_literal_info, env);
                try self.unifyWith(expr_var, try self.mkNumberTypeContent(.dec), env);
            } else {
                try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(expr_idx), expr_var, expr_region, .expression, env);
            }
        },
        .e_dec_small => |frac| {
            if (frac.has_suffix) {
                const literal = self.recordedNumeralLiteralForNode(ModuleEnv.nodeIdxFrom(expr_idx));
                const num_literal_info = try self.exactNumeralInfoForLiteral(literal, expr_region);
                _ = try self.reportInvalidBuiltinFromNumeralInfo(expr_var, .dec, num_literal_info, env);
                try self.unifyWith(expr_var, try self.mkNumberTypeContent(.dec), env);
            } else {
                try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(expr_idx), expr_var, expr_region, .expression, env);
            }
        },
        .e_typed_int => {
            // Typed integer literal like 123.U64
            try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(expr_idx), expr_var, expr_region, .expression, env);
        },
        .e_typed_frac => {
            // Typed fractional literal like 3.14.Dec
            try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(expr_idx), expr_var, expr_region, .expression, env);
        },
        .e_typed_num_from_numeral => {
            try self.checkNumeralLiteral(ModuleEnv.nodeIdxFrom(expr_idx), expr_var, expr_region, .expression, env);
        },
        // list //
        .e_empty_list => {
            // Create a nominal List with a fresh unbound element type
            const elem_var = try self.fresh(env, expr_region);
            const list_content = try self.mkListContent(elem_var);
            try self.unifyWith(expr_var, list_content, env);
        },
        .e_list => |list| {
            const elems = self.cir.store.exprSlice(list.elems);

            if (elems.len == 0) {
                // Create a nominal List with a fresh unbound element type
                const elem_var = try self.fresh(env, expr_region);
                const list_content = try self.mkListContent(elem_var);
                try self.unifyWith(expr_var, list_content, env);
            } else {
                // Element accumulator seed, mirroring the if/match branch
                // accumulator (`instantiateVarOrphanFlexed` seeding in
                // `checkIfElseExpr`/`checkMatchExpr`): when this list literal
                // is checked directly against an expected type (its def's
                // annotation or a platform requirement), seed the element
                // meet with the element of a rigids-flexed ORPHAN COPY of
                // that type, so annotation-declared facts—e.g. an
                // `optional` field kind—constrain every element as it
                // folds in, instead of the elements meeting each other first
                // with kinds still undetermined (design.md "Field Kinds
                // (All-Dynamic Optional Fields)"). The copy is unpacked to
                // its element through one unification with `List(seed)`
                // inside a CommitProbe: if the expected type is not a List
                // at all, the rollback discards the attempt (no problem is
                // recorded) and the annotation mismatch is reported after
                // the switch, exactly as without seeding.
                const mb_seed_elem_var: ?Var = seed: {
                    const expected_type = nested_expected.expected_type orelse break :seed null;
                    const expected_copy = try self.instantiateVarOrphanFlexed(expected_type.var_, env, .use_last_var);
                    const seed_elem_var = try self.fresh(env, expr_region);
                    const seed_list_var = try self.freshFromContent(try self.mkListContent(seed_elem_var), env, expr_region);

                    var commit_probe = try self.beginCommitProbe(env);
                    var committed = false;
                    defer if (!committed) commit_probe.rollback();
                    const result = try commit_probe.unify(expected_copy, seed_list_var);
                    if (!result.isEstablished()) break :seed null;
                    committed = true;
                    commit_probe.commit();
                    break :seed seed_elem_var;
                };

                // Here, we use the list's 1st element as the element var to
                // constrain the rest of the list

                // Check the first elem
                const first_elem = try self.checkStoredValueExpr(elems[0], env, child_expected);
                does_fx = first_elem.does_fx or does_fx;

                // Fold the first element into the seeded accumulator: one
                // real unify merges the seed and the element into the same
                // var, so element-to-element consistency below still flows
                // through one shared accumulator. A mismatch here is the
                // element failing the annotation, so it is reported in the
                // expected type's own context, at the element's region.
                var first_elem_ok = true;
                const elem_var = if (mb_seed_elem_var) |seed_elem_var| acc: {
                    const result = try self.unifyInContext(seed_elem_var, first_elem.var_, env, nested_expected.expected_type.?.context);
                    first_elem_ok = result.isEstablished();
                    break :acc seed_elem_var;
                } else first_elem.var_;

                if (first_elem_ok) {
                    // Iterate over the remaining elements
                    var last_elem_expr_idx = elems[0];
                    for (elems[1..], 1..) |elem_expr_idx, i| {
                        const current_elem = try self.checkStoredValueExpr(elem_expr_idx, env, child_expected);
                        does_fx = current_elem.does_fx or does_fx;
                        const cur_elem_var = current_elem.var_;

                        // Unify each element's var with the list's elem var
                        const result = try self.unifyInContext(elem_var, cur_elem_var, env, .{ .list_entry = .{
                            .elem_index = @intCast(i),
                            .list_length = @intCast(elems.len),
                            .last_elem_idx = ModuleEnv.nodeIdxFrom(last_elem_expr_idx),
                        } });

                        // If we errored, check the rest of the elements without comparing
                        // to the elem_var to catch their individual errors
                        if (!result.isEstablished()) {
                            for (elems[i + 1 ..]) |remaining_elem_expr_idx| {
                                const remaining_elem = try self.checkStoredValueExpr(remaining_elem_expr_idx, env, child_expected);
                                does_fx = remaining_elem.does_fx or does_fx;
                            }

                            // Break to avoid cascading errors
                            break;
                        }

                        last_elem_expr_idx = elem_expr_idx;
                    }
                } else {
                    // The first element failed the seeded expectation: check
                    // the remaining elements without comparing to the elem_var
                    // to catch their individual errors (mirrors the loop's
                    // failure path above).
                    for (elems[1..]) |remaining_elem_expr_idx| {
                        const remaining_elem = try self.checkStoredValueExpr(remaining_elem_expr_idx, env, child_expected);
                        does_fx = remaining_elem.does_fx or does_fx;
                    }
                }

                // Create a nominal List type with the inferred element type
                const list_content = try self.mkListContent(elem_var);
                try self.unifyWith(expr_var, list_content, env);
            }
        },
        // tuple //
        .e_tuple => |tuple| {
            // Check tuple elements
            const elems_slice = self.cir.store.exprSlice(tuple.elems);
            const scratch_vars_top = self.scratch_vars.top();
            defer self.scratch_vars.clearFrom(scratch_vars_top);
            for (elems_slice) |single_elem_expr_idx| {
                const elem = try self.checkStoredValueExpr(single_elem_expr_idx, env, child_expected);
                does_fx = elem.does_fx or does_fx;
                try self.scratch_vars.append(elem.var_);
            }

            const elem_vars_slice = try self.types.appendVars(self.scratch_vars.sliceFromStart(scratch_vars_top));

            // Set the type in the store
            try self.unifyWith(expr_var, .{ .structure = .{
                .tuple = .{ .elems = elem_vars_slice },
            } }, env);
        },
        .e_tuple_access => |tuple_access| {
            // Check the tuple expression
            does_fx = try self.checkExpr(tuple_access.tuple, env, child_expected) or does_fx;

            const tuple_var = ModuleEnv.varFrom(tuple_access.tuple);
            const pending = PendingTupleAccess{
                .tuple_var = self.types.resolveVar(tuple_var).var_,
                .result_var = expr_var,
                .elem_index = tuple_access.elem_index,
                .region = expr_region,
            };
            if (!try self.resolvePendingTupleAccess(pending, env, false)) {
                try self.pending_tuple_accesses.append(self.gpa, pending);
            }
        },
        // record //
        .e_record => |e| {
            // Check if this is a record update
            if (e.ext) |record_being_updated_expr| {
                // Create a record type in the type system and assign it the expr_var

                // Check the record being updated
                does_fx = try self.checkExpr(record_being_updated_expr, env, child_expected) or does_fx;

                const record_being_updated_var = ModuleEnv.varFrom(record_being_updated_expr);
                const record_being_updated_name: ?Ident.Idx = self.getExprPatternIdent(record_being_updated_expr);

                // Process each field
                for (self.cir.store.sliceRecordFields(e.fields)) |field_idx| {
                    const field = self.cir.store.getRecordField(field_idx);

                    // Check the field value expression
                    const field_value = try self.checkStoredValueExpr(field.value, env, child_expected);
                    does_fx = field_value.does_fx or does_fx;

                    // A supplied update field has CREATION semantics: like a
                    // record-literal field, its KIND is undetermined—the
                    // update can set a required, defaulted, or optional field
                    // (design.md "Field Kinds (All-Dynamic Optional
                    // Fields)"). Unifying the kind-flexible probe into the
                    // base does the rest: a base kind of `optional` pins the
                    // kind optional and checks the value against the payload
                    // type (lowering then wraps the value in `Present`,
                    // exactly as construction does); `required`/`defaulted`
                    // pin as before. If no context decides a still-flex kind,
                    // the update judgment commits it to required before its
                    // owning generalization boundary.
                    //
                    // TODO(optional-fields): `{ x: _ }` UNSET syntax is
                    // designed in design.md "Deferred: Unsetting an Optional
                    // Field (`{ ..r, x: _ }`)".
                    const field_kind_var = try self.fresh(env, expr_region);
                    try self.pending_record_updates.append(self.gpa, .{
                        .presence_var = field_kind_var,
                        .region = expr_region,
                    });

                    // Create an unbound record with this field
                    const single_field_record = try self.freshFromContent(.{
                        .structure = .{
                            .record_unbound = try self.types.appendRecordFields(&.{types_mod.RecordField{
                                .name = field.name,
                                .presence = .unknown(field_kind_var, field_value.var_),
                            }}),
                        },
                    }, env, expr_region);

                    // Unify this record update with the record we're updating
                    _ = try self.unifyInContext(record_being_updated_var, single_field_record, env, .{ .record_update = .{
                        .field_name = field.name,
                        .field_region_idx = @enumFromInt(@intFromEnum(field.value)),
                        .record_region_idx = @enumFromInt(@intFromEnum(record_being_updated_var)),
                        .record_name = record_being_updated_name,
                    } });
                }

                // Then unify with the actual expression
                _ = try self.unify(record_being_updated_var, expr_var, env);
            } else {
                // Write down the top of the scratch records array
                const record_fields_top = self.scratch_record_fields.top();
                defer self.scratch_record_fields.clearFrom(record_fields_top);

                // Process each field
                for (self.cir.store.sliceRecordFields(e.fields)) |field_idx| {
                    const field = self.cir.store.getRecordField(field_idx);

                    // Check the field value expression
                    const field_value = try self.checkStoredValueExpr(field.value, env, child_expected);
                    does_fx = field_value.does_fx or does_fx;

                    // A literal field's KIND is undetermined: the literal
                    // can serve as a required field or as an optional one
                    // (construction wraps the tag exactly when the solved
                    // kind is `optional`). Unification pins the kind to
                    // whichever concrete kind the context demands
                    // (design.md "Field Kinds (All-Dynamic Optional
                    // Fields)"). The mint is recorded so the finalize sweep
                    // can commit a kind nothing ever pinned to `required`
                    // (see `defaultLiteralFieldKinds`).
                    const field_kind_var = try self.fresh(env, expr_region);
                    try self.literal_field_kinds.append(self.gpa, .{
                        .presence_var = field_kind_var,
                        .region = expr_region,
                    });

                    // Append it to the scratch records array
                    try self.scratch_record_fields.append(types_mod.RecordField{
                        .name = field.name,
                        .presence = .unknown(field_kind_var, field_value.var_),
                    });
                }

                // Copy the scratch fields into the types store
                const record_fields_scratch = self.scratch_record_fields.sliceFromStart(record_fields_top);
                std.mem.sort(types_mod.RecordField, record_fields_scratch, self.cir.getIdentStore(), types_mod.RecordField.sortByNameAsc);
                const record_fields_range = try self.types.appendRecordFields(record_fields_scratch);

                // Create an unbound record with the provided fields
                const ext_var = try self.freshFromContent(.{ .structure = .empty_record }, env, expr_region);
                try self.unifyWith(expr_var, .{ .structure = .{ .record = .{
                    .fields = record_fields_range,
                    .ext = ext_var,
                } } }, env);
            }
        },
        .e_empty_record => {
            try self.unifyWith(expr_var, .{ .structure = .empty_record }, env);
        },
        // tags //
        .e_zero_argument_tag => |e| {
            const ext_var = try self.fresh(env, expr_region);

            const tag = try self.types.mkTag(e.name, &.{});
            const tag_union_content = try self.types.mkTagUnion(&[_]types_mod.Tag{tag}, ext_var);

            // Update the expr to point to the new type
            try self.unifyWith(expr_var, tag_union_content, env);
        },
        .e_tag => |e| {
            // Create a tag type in the type system and assign it the expr_var

            // Process each tag arg
            const arg_expr_idx_slice = self.cir.store.sliceExpr(e.args);
            const scratch_vars_top = self.scratch_vars.top();
            defer self.scratch_vars.clearFrom(scratch_vars_top);
            for (arg_expr_idx_slice) |arg_expr_idx| {
                const arg = try self.checkStoredValueExpr(arg_expr_idx, env, child_expected);
                does_fx = arg.does_fx or does_fx;
                try self.scratch_vars.append(arg.var_);
            }

            // Create the type
            const ext_var = try self.fresh(env, expr_region);

            const tag = try self.types.mkTag(e.name, self.scratch_vars.sliceFromStart(scratch_vars_top));
            const tag_union_content = try self.types.mkTagUnion(&[_]types_mod.Tag{tag}, ext_var);

            // Update the expr to point to the new type
            try self.unifyWith(expr_var, tag_union_content, env);
        },
        // nominal //
        .e_nominal => |nominal| {
            // Check the backing expression first
            const backing = try self.checkStoredValueExpr(nominal.backing_expr, env, child_expected);
            does_fx = backing.does_fx or does_fx;
            const actual_backing_var = backing.var_;

            // Use shared nominal type checking logic
            _ = try self.checkNominalTypeUsage(
                expr_var,
                actual_backing_var,
                ModuleEnv.varFrom(nominal.nominal_type_decl),
                nominal.backing_type,
                expr_region,
                env,
                if (self.exprIsFreshRecordConstruction(nominal.backing_expr)) .construction else .exact,
                expr_idx,
            );
        },
        .e_nominal_external => |nominal| {
            // Check the backing expression first
            const backing = try self.checkStoredValueExpr(nominal.backing_expr, env, child_expected);
            does_fx = backing.does_fx or does_fx;
            const actual_backing_var = backing.var_;

            // Resolve the external type declaration
            if (try self.resolveVarFromExternal(nominal.module_idx, nominal.target_node_idx)) |ext_ref| {
                // Use shared nominal type checking logic
                _ = try self.checkNominalTypeUsage(
                    expr_var,
                    actual_backing_var,
                    ext_ref.local_var,
                    nominal.backing_type,
                    expr_region,
                    env,
                    if (self.exprIsFreshRecordConstruction(nominal.backing_expr)) .construction else .exact,
                    expr_idx,
                );
            } else {
                try self.markErroneous(expr_var);
            }
        },
        // lookup //
        .e_lookup_local => |lookup| blk: {
            const pat_var = ModuleEnv.varFrom(lookup.pattern_idx);

            if (self.localLookupIsGeneratedDerivedMethodMarker(lookup.pattern_idx)) {
                try self.reportAnnotationOnlyValueUse(expr_var, expr_region, env);
                break :blk;
            }

            if (self.localLookupHasNoValue(lookup.pattern_idx)) {
                try self.reportValuelessDeclarationUse(expr_var, expr_region);
                break :blk;
            }

            try self.value_lookup_tracking.append(self.gpa, .{
                .expr_idx = expr_idx,
                .pattern_idx = lookup.pattern_idx,
            });

            const mb_processing_def = self.topLevelPattern(lookup.pattern_idx);
            if (mb_processing_def) |processing_def| {
                const referenced_def = self.cir.store.getDef(processing_def.def_idx);
                // A reference to an annotated def whose body has not been
                // checked yet instantiates the pre-declared scheme—the
                // uniform rule: annotated references never need the body.
                // (Once the def is `.processed`, its own pattern var carries
                // the checked scheme and the ordinary tail below applies.)
                const mb_predeclared_scheme = self.predeclaredSchemeVar(processing_def.def_idx);

                switch (processing_def.status) {
                    .not_processed => {
                        if (mb_predeclared_scheme) |scheme_var| {
                            try self.instantiatePendingPredeclaredSchemeUse(
                                processing_def.def_idx,
                                scheme_var,
                                expr_var,
                                expr_idx,
                                env,
                            );
                            break :blk;
                        }
                        {
                            // The driver checks groups in topological order, so
                            // an unchecked, un-pre-declared target can only be
                            // a later member of the CURRENT recursive group—
                            // its pattern var was ranked in the group's shared
                            // frame before any member body ran.
                            if (builtin.mode == .Debug) {
                                if (!self.defInCurrentRecursiveGroup(processing_def.def_idx)) {
                                    std.debug.panic("type checker invariant violated: name reference to unchecked def outside the current binding group", .{});
                                }
                            }
                            if (!isFunctionDef(&self.cir.store, self.cir.store.getExpr(referenced_def.expr)) and
                                self.delayed_dependency_depth == 0)
                            {
                                // A value member of a recursive group referenced
                                // outside any lambda body is a strict value
                                // cycle.
                                try self.poisonRecursiveNonFunctionProcessingDef(processing_def, expr_idx, env);
                            } else {
                                // The binding-group recursion rule: an in-group
                                // reference to an unannotated member unifies
                                // monomorphically with the member's in-flight
                                // type, so facts discovered at the call site
                                // flow into the inferred scheme.
                                _ = try self.unifyInContext(expr_var, pat_var, env, .{ .recursive_def = .{ .def_name = processing_def.def_name } });
                                try self.recordSharedSchemeUse(
                                    @intFromEnum(expr_idx),
                                    .shared_value_use,
                                    0,
                                    ModuleEnv.varFrom(processing_def.def_idx),
                                );
                            }
                            break :blk;
                        }
                    },
                    .processing => {
                        if (mb_predeclared_scheme) |scheme_var| {
                            // Annotated self-reference (or in-group reference
                            // to an in-flight annotated member): instantiate
                            // the declared scheme—sound polymorphic
                            // recursion for annotated defs. This is an internal
                            // recursive edge, not an external use of the body's
                            // eventual scheme; the enclosing body's own
                            // requirements cover the implementation cycle.
                            const instantiated = try self.instantiateBindingVar(scheme_var, env, .use_last_var);
                            _ = try self.unify(expr_var, instantiated, env);
                            break :blk;
                        }
                        if (!isFunctionDef(&self.cir.store, self.cir.store.getExpr(referenced_def.expr))) {
                            if (self.delayed_dependency_depth == 0) {
                                try self.poisonRecursiveNonFunctionProcessingDef(processing_def, expr_idx, env);
                            } else {
                                _ = try self.unify(expr_var, ModuleEnv.varFrom(referenced_def.expr), env);
                            }
                            break :blk;
                        }

                        // The def is mid-check, so it must not be generalized yet.
                        std.debug.assert(self.types.resolveVar(pat_var).desc.rank != .generalized);

                        // The binding-group recursion rule (see the
                        // .not_processed arm): a self-reference, or a
                        // reference to an in-flight unannotated member,
                        // links monomorphically. The link targets the def's
                        // RHS var—which lives in the frame that generalizes
                        // the def—rather than its pattern var: a suspended
                        // singleton's pattern sits at the outermost rank, and
                        // a dispatch back-edge linking there would pull the
                        // whole merged group out of generalization instead of
                        // generalizing with the suspended group's boundary.
                        _ = try self.unifyInContext(expr_var, ModuleEnv.varFrom(referenced_def.expr), env, .{ .recursive_def = .{ .def_name = processing_def.def_name } });
                        try self.recordSharedSchemeUse(
                            @intFromEnum(expr_idx),
                            .shared_value_use,
                            0,
                            ModuleEnv.varFrom(processing_def.def_idx),
                        );
                        break :blk;
                    },
                    .processed => {
                        if (mb_predeclared_scheme) |scheme_var| {
                            if (self.defInOnStackGroup(processing_def.def_idx)) {
                                // A previously checked member of this still-
                                // open recursive group has not reached the
                                // shared generalization boundary yet. Preserve
                                // the annotation's polymorphic-recursion rule
                                // until that boundary publishes the body scheme.
                                const instantiated = try self.instantiateBindingVar(scheme_var, env, .use_last_var);
                                _ = try self.unify(expr_var, instantiated, env);
                                break :blk;
                            }
                        }
                    },
                }
            }

            // Local block-def recursion. If this lookup targets a local `s_decl`
            // function whose body is currently being checked, it's a recursive
            // reference (to the def itself, or to an enclosing in-flight def).
            // An annotated local def's scheme is pre-declared before its body,
            // so its pattern var is already generalized and the reference falls
            // through to the instantiate tail. An unannotated one follows the
            // binding-group recursion rule: unify monomorphically with the
            // pattern var, which lives in the def's own rank frame (see the
            // recursive `s_decl` frame in `checkStatement`) so the links
            // generalize with the def.
            //
            // A reference to an already-finished sibling local def is NOT in this
            // map (removed after it generalizes), so it falls through to the tail
            // below and instantiates normally.
            if (self.local_processing_ptrns.get(lookup.pattern_idx)) |local_def| {
                if (self.predeclared_local_scheme_vars.get(lookup.pattern_idx)) |scheme_var| {
                    // Annotated local self/enclosing reference: instantiate
                    // the declared scheme (sound polymorphic recursion).
                    const instantiated = try self.instantiateBindingVar(scheme_var, env, .use_last_var);
                    _ = try self.unify(expr_var, instantiated, env);
                    break :blk;
                }

                // The def is mid-check, so it must not be generalized yet.
                std.debug.assert(self.types.resolveVar(pat_var).desc.rank != .generalized);

                _ = try self.unifyInContext(expr_var, pat_var, env, .{ .recursive_def = .{ .def_name = local_def.def_name } });
                try self.recordSharedSchemeUse(
                    @intFromEnum(expr_idx),
                    .shared_value_use,
                    0,
                    pat_var,
                );
                break :blk;
            }

            const compile_time_known_binding = known: {
                if (self.patternIsTopLevel(lookup.pattern_idx)) break :known true;
                if (expected.hoist_position == .suppressed) {
                    if (self.hoist_known_values.get(lookup.pattern_idx)) |known_value| {
                        switch (known_value) {
                            .pattern_extraction => {
                                if (try self.ensureHoistedBindingRoot(lookup.pattern_idx)) break :known true;
                            },
                            .binding_rhs,
                            .selected_root,
                            .unavailable_runtime,
                            => {},
                        }
                    }
                }
                if (self.shouldDeferHoistedBindingSelection() and self.hoistKnownBindingAvailable(lookup.pattern_idx)) {
                    try self.hoist_deferred_roots.append(self.gpa, .{ .binding = lookup.pattern_idx });
                    break :known true;
                }
                if (try self.ensureHoistedBindingRoot(lookup.pattern_idx)) break :known true;
                break :known self.markHoistContextualDependencyForLookup(lookup.pattern_idx);
            };
            if (!compile_time_known_binding) {
                self.markCurrentHoistRuntimeDependency();
            }

            const resolved_pat = self.types.resolveVar(pat_var);
            if (resolved_pat.desc.rank == Rank.generalized or self.isBindingSchemeVar(pat_var)) {
                const instantiated = try self.instantiateBindingVar(pat_var, env, .use_last_var);
                _ = try self.unify(expr_var, instantiated, env);
            } else {
                _ = try self.unify(expr_var, pat_var, env);
                if (mb_processing_def) |processing_def| {
                    try self.recordSharedSchemeUse(
                        @intFromEnum(expr_idx),
                        .shared_value_use,
                        0,
                        ModuleEnv.varFrom(processing_def.def_idx),
                    );
                }
            }
        },
        .e_lookup_external => |ext| {
            // With WaitingForDependencies phase, dependencies are guaranteed to be Done
            // before canonicalization, so target_node_idx is always valid.
            if (try self.resolveVarFromExternal(ext.module_idx, ext.target_node_idx)) |ext_ref| {
                const target_def: CIR.Def.Idx = @enumFromInt(@intFromEnum(ext_ref.other_cir_node_idx));
                if (generatedDerivedMethodDef(ext_ref.other_cir, target_def)) {
                    try self.reportAnnotationOnlyValueUse(expr_var, expr_region, env);
                } else if (annotationOnlyValueDef(ext_ref.other_cir, target_def)) {
                    try self.reportValuelessDeclarationUse(expr_var, expr_region);
                } else {
                    const ext_instantiated_var = try self.instantiateImportedBindingVar(
                        ext_ref.local_var,
                        env,
                        .{ .explicit = expr_region },
                    );
                    _ = try self.unify(expr_var, ext_instantiated_var, env);
                }
            } else {
                try self.markErroneous(expr_var);
            }
        },
        .e_lookup_associated_local => |lookup| {
            try self.checkLocalAssociatedLookup(expr_idx, expr_var, lookup, expr_region, env);
        },
        .e_lookup_associated => |lookup| {
            try self.checkAssociatedLookup(expr_idx, expr_var, lookup, expr_region, env);
        },
        .e_lookup_associated_resolved => |lookup| {
            try self.checkResolvedAssociatedLookup(expr_var, lookup, expr_region, env);
        },
        .e_lookup_required => |req| {
            self.markCurrentHoistRuntimeDependency();
            // Look up the type from the platform's requires clause
            const requires_items = self.cir.requires_types.items.items;
            const idx = req.requires_idx.toU32();
            if (idx < requires_items.len) {
                const required_type = requires_items[idx];
                const type_var = ModuleEnv.varFrom(required_type.type_anno);
                const instantiated_var = try self.instantiateVar(
                    type_var,
                    env,
                    .{ .explicit = expr_region },
                );
                _ = try self.unify(expr_var, instantiated_var, env);
            } else {
                try self.markErroneous(expr_var);
            }
        },
        // block //
        .e_block => |block| {
            const hoist_scope = self.beginHoistLexicalScope();
            defer self.endHoistLexicalScope(hoist_scope);

            // Check all statements in the block
            const stmt_result = try self.checkBlockStatements(block.stmts, env, expr_region, nested_expected.forStatement());
            does_fx = stmt_result.does_fx or does_fx;

            // Check the final expression
            const final_expr_does_fx = if (stmt_result.blocks_later_hoists)
                try self.checkExprInCallPosition(
                    block.final_expr,
                    env,
                    nested_expected.suppressHoistSelection(),
                    is_call_arg,
                    is_immediate_callee,
                )
            else
                try self.checkExprInCallPosition(
                    block.final_expr,
                    env,
                    nested_expected,
                    is_call_arg,
                    is_immediate_callee,
                );
            does_fx = final_expr_does_fx or does_fx;

            // If the block diverges (has a return/crash), use a flex var for the block's type
            // since the final expression is unreachable
            if (stmt_result.diverges) {
                try self.unifyWith(expr_var, .{ .flex = Flex.init() }, env);
            } else {
                // Link the root expr with the final expr
                _ = try self.unify(expr_var, ModuleEnv.varFrom(block.final_expr), env);
            }
        },
        // function //
        .e_lambda => |lambda| {
            // Record the parameter span for the end-of-check pinnable
            // collection (see `checked_lambda_params`).
            try self.checked_lambda_params.append(self.gpa, lambda.args);

            // Then, even if we have an expected type, it may not actually be a function
            const mb_anno_func: ?types_mod.Func = blk: {
                if (mb_anno_vars) |anno_vars| {
                    // Here, we unwrap the function, following aliases, to get
                    // the actual function we want to check against
                    var var_ = anno_vars.anno_var;
                    var guard = types_mod.debug.IterationGuard.init("checkExpr.lambda.unwrapExpectedFunc");
                    while (true) {
                        guard.tick();
                        switch (self.types.resolveVar(var_).desc.content) {
                            .structure => |flat_type| {
                                switch (flat_type) {
                                    .fn_pure => |func| break :blk func,
                                    .fn_unbound => |func| break :blk func,
                                    .fn_effectful => |func| break :blk func,
                                    .record, .record_unbound, .tuple, .nominal_type, .empty_record, .tag_union, .empty_tag_union => break :blk null,
                                }
                            },
                            .alias => |alias| {
                                var_ = self.types.getAliasBackingVar(alias);
                            },
                            .flex, .rigid, .field_presence, .err => break :blk null,
                        }
                    }
                } else {
                    break :blk null;
                }
            };
            const anno_context = if (mb_anno_vars) |anno_vars| anno_vars.context else problem.Context.type_annotation;

            // Check the argument patterns
            // This must happen *before* checking against the expected type so
            // all the pattern types are inferred
            const arg_count = lambda.args.span.len;
            var arg_vars_sfa = std.heap.stackFallback(16 * @sizeOf(Var), self.gpa);
            const arg_vars_alloc = arg_vars_sfa.get();
            const arg_vars = try arg_vars_alloc.alloc(Var, arg_count);
            defer arg_vars_alloc.free(arg_vars);
            const pattern_ctx: PatternCtx = if (mb_anno_func != null) .from_annotation else .fn_arg;
            for (0..arg_count) |i| {
                const pattern_idx = self.cir.store.patternAt(lambda.args, i);
                arg_vars[i] = ModuleEnv.varFrom(pattern_idx);
                try self.checkPattern(pattern_idx, pattern_ctx, env);
            }

            // Now, check if we have an expected function to validate against
            if (mb_anno_func) |anno_func| {
                // Use index-based iteration instead of slices because unifyInContext
                // may trigger reallocations that would invalidate slice pointers
                const anno_func_args_range = anno_func.args;
                const anno_func_args_len = anno_func_args_range.len();

                // Next, check if the arguments arities match
                if (anno_func_args_len == arg_count) {
                    // If so, check each argument, passing in the expected type

                    // First, find all the rigid variables in a the function's type
                    // and unify the matching corresponding lambda arguments together.
                    for (0..anno_func_args_len) |i| {
                        const anno_arg_1 = self.types.getVarAt(anno_func_args_range, @intCast(i));
                        const anno_resolved_1 = self.types.resolveVar(anno_arg_1);

                        // The expected type is an annotation and as such,
                        // should never contain a flex var. If it did, that
                        // would indicate that the annotation is malformed
                        // std.debug.assert(expected_resolved_1.desc.content != .flex);

                        // Skip any concrete arguments
                        if (anno_resolved_1.desc.content != .rigid) {
                            continue;
                        }

                        // Look for other arguments with the same type variable
                        for (i + 1..anno_func_args_len) |j| for_blk: {
                            const anno_arg_2 = self.types.getVarAt(anno_func_args_range, @intCast(j));
                            const anno_resolved_2 = self.types.resolveVar(anno_arg_2);
                            if (anno_resolved_1.var_ == anno_resolved_2.var_) {
                                // These two argument indexes in the called *function's*
                                // type have the same rigid variable! So, we unify
                                // the corresponding *lambda args*

                                const arg_1 = arg_vars[i];
                                const arg_2 = arg_vars[j];

                                const unify_result = try self.unifyInContext(arg_1, arg_2, env, .{
                                    .fn_args_bound_var = .{
                                        .fn_name = self.enclosing_func_name,
                                        .first_arg_var = arg_1,
                                        .second_arg_var = arg_2,
                                        .first_arg_index = @intCast(i),
                                        .second_arg_index = @intCast(j),
                                        .num_args = @intCast(arg_count),
                                    },
                                });
                                if (unify_result.isProblem()) {
                                    // Context already set by unifyInContext
                                    // Stop execution
                                    try self.markErroneous(expr_var);
                                    break :for_blk;
                                }
                            }
                        }
                    }

                    // Then, lastly, we unify the annotation types against the
                    // actual type
                    for (arg_vars, 0..) |arg_var, i| {
                        const expected_arg_var = self.types.getVarAt(anno_func_args_range, @intCast(i));
                        _ = try self.unifyInContext(expected_arg_var, arg_var, env, anno_context);
                    }
                } else {
                    // This means the expected type and the actual lambda have
                    // an arity mismatch. This will be caught by the regular
                    // expectation checking code at the bottom of this function
                }
            }

            const body_var = ModuleEnv.varFrom(lambda.body);

            // Check the the body of the expr
            // If we have an expected function, use that as the expr's expected type
            const exhaustiveness_scope = self.exhaustiveness_context.resetForRuntimeFunction();
            defer exhaustiveness_scope.leave();

            const body_is_delayed_dependency = !is_immediate_callee;
            if (body_is_delayed_dependency) self.delayed_dependency_depth += 1;
            defer {
                if (body_is_delayed_dependency) self.delayed_dependency_depth -= 1;
            }

            const lambda_body_expected = Expected.none().withHoistPosition(nested_expected.hoist_position);
            const expected_result = if (mb_anno_func) |expected_func| expected_func.ret else null;
            try self.pushReturnConstraintFrame(expr_idx, body_var, expected_result);
            var return_constraints_processed = false;
            defer if (!return_constraints_processed) self.discardReturnConstraintFrame(expr_idx);

            const effect_dependencies_start = self.pending_function_effect_dependencies.items.len;
            try self.function_effect_dependency_frame_starts.append(self.gpa, effect_dependencies_start);
            defer {
                _ = self.function_effect_dependency_frame_starts.pop();
                self.pending_function_effect_dependencies.shrinkRetainingCapacity(effect_dependencies_start);
            }

            const body_does_fx = if (mb_anno_func) |expected_func| blk: {
                const lambda_body_does_fx = try self.checkExpr(lambda.body, env, lambda_body_expected.withBranchResult(expected_func.ret));
                try self.closeAbsentConstructedPayloadVars(lambda.body, body_var);
                const body_result = try self.unifyInContext(expected_func.ret, body_var, env, anno_context);
                if (body_result.isProblem()) {
                    try self.erroneous_value_exprs.put(self.gpa, lambda.body, {});
                }
                break :blk lambda_body_does_fx;
            } else blk: {
                const lambda_body_does_fx = try self.checkExpr(lambda.body, env, lambda_body_expected);
                try self.closeAbsentConstructedPayloadVars(lambda.body, body_var);
                break :blk lambda_body_does_fx;
            };

            // Process any pending return constraints (from early returns / ? operator) before
            // creating the function type. This must happen after the body is fully checked
            // (for correct error reporting) but before the function type is generalized
            // (so instantiated copies at call sites have the complete type, including
            // both Ok and Err variants from the ? operator).
            try self.processReturnConstraints(env, expr_idx);
            return_constraints_processed = true;

            // NOTE: no occurs check here. Infinite/anonymous-recursive types
            // are detected at binding roots (top-level defs, local bindings,
            // REPL roots)—a cyclic type constructed while checking this
            // body is reachable from the enclosing binding's root type, and
            // running occurs per syntactic lambda re-traversed the whole body
            // type graph once per nesting level.

            // A dependency may already have become positive while checking a
            // later argument or definition. Materialize that result before
            // unifying with an annotation; only genuinely unresolved formulas
            // remain attached to an unbound function type.
            var body_is_effectful = body_does_fx;
            if (!body_is_effectful) {
                for (self.pending_function_effect_dependencies.items[effect_dependencies_start..]) |dependency| {
                    if (try self.functionEffectState(dependency) == .effectful) {
                        body_is_effectful = true;
                        break;
                    }
                }
            }

            // Create the function type
            if (body_is_effectful) {
                try self.effectful_lambda_bodies.put(expr_idx, {});
                try self.unifyWith(expr_var, try self.types.mkFuncEffectful(arg_vars, body_var), env);
            } else {
                try self.unifyWith(
                    expr_var,
                    try self.types.mkFuncUnboundWithEffectDeps(
                        arg_vars,
                        body_var,
                        self.pending_function_effect_dependencies.items[effect_dependencies_start..],
                    ),
                    env,
                );
            }

            // Note that so far, we have not yet unified against the
            // annotation's effectfulness/pureness. This is intentional!
            // Below this large switch statement, there's the regular expr
            // <-> expected unification. This will catch any difference in
            // effectfullness, and it'll link the root expected var with the
            // expr_var

        },
        .e_closure => |closure| {
            // Here, we must forward the expected valued to the inner lambda, so
            // the annotation type is created at the same rank as the expr.
            // A closure is only the capture wrapper around its inner lambda, so
            // the lambda inherits this closure's call-arg status: an argument
            // lambda must NOT be generalized, or its body's static-dispatch chain
            // would be quantified before the caller pins the parameter types,
            // leaving the original (un-instantiated) dispatch nodes unresolved.
            // A group member's RHS suppression applies to the lambda the
            // closure wraps, exactly like the call-arg status above.
            if (suppress_group_member_generalize) {
                self.suppress_generalize_expr = closure.lambda_idx;
            }
            does_fx = try self.checkExprInCallPosition(
                closure.lambda_idx,
                env,
                nested_expected,
                is_call_arg,
                is_immediate_callee,
            ) or does_fx;
            // The inner lambda owns generalization, while every source lookup
            // names the closure wrapper. Register that explicit source-level
            // alias instead of recovering the relationship from the mutable
            // union-find representative later.
            try self.bindTypeSchemeVar(ModuleEnv.varFrom(closure.lambda_idx), expr_var_raw);
            // The closure is the executable function-value expression. If its
            // delegated lambda check failed as a whole, poison the closure so
            // the lambda remains a valid structural child until the closure is
            // replaced with a runtime error.
            if (self.erroneous_value_exprs.remove(closure.lambda_idx)) {
                try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
            }
            const lambda_var = ModuleEnv.varFrom(closure.lambda_idx);

            _ = try self.unify(expr_var, lambda_var, env);
        },
        // function calling //
        .e_call => |call| {
            switch (call.called_via) {
                .apply, .record_builder => blk: {
                    // First, check the function being called
                    // It could be effectful, e.g. `(mk_fn!())(arg)`
                    self.checking_call_arg = true;
                    self.checking_immediate_callee = true;
                    does_fx = try self.checkExpr(call.func, env, child_expected) or does_fx;
                    const call_func_expr_var = ModuleEnv.varFrom(call.func);

                    // If the function was generalized (e.g. an immediately-invoked
                    // lambda `(|x| ...)(arg)`), instantiate it so the call site gets
                    // fresh type variables. Without this, the generalized vars would
                    // be unified directly with concrete arg types, which can leak
                    // generalization into the enclosing function's types.
                    const func_var = blk_instantiate: {
                        const resolved = self.types.resolveVar(call_func_expr_var);
                        if (resolved.desc.rank == Rank.generalized or self.isBindingSchemeVar(call_func_expr_var)) {
                            const saved_instantiation_is_immediate_callee = self.instantiation_is_immediate_callee;
                            self.instantiation_is_immediate_callee = true;
                            defer self.instantiation_is_immediate_callee = saved_instantiation_is_immediate_callee;
                            break :blk_instantiate try self.instantiateBindingVar(
                                call_func_expr_var,
                                env,
                                .use_last_var,
                            );
                        } else {
                            break :blk_instantiate call_func_expr_var;
                        }
                    };
                    // The instantiated callable is the authoritative callee result.
                    // Imported static methods can use an erroneous source placeholder
                    // whose binding scheme instantiates to a valid callable here.
                    var did_err = self.types.resolveVar(func_var).desc.content == .err;

                    // Second, check the arguments being called
                    // It could be effectful, e.g. `fn(mk_arg!())`
                    const call_arg_expr_idxs = self.cir.store.sliceExpr(call.args);
                    for (call_arg_expr_idxs) |call_arg_idx| {
                        self.checking_call_arg = true;
                        self.checking_immediate_callee = false;
                        does_fx = try self.checkExpr(call_arg_idx, env, child_expected) or does_fx;
                    }
                    const args_did_err = try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, call_arg_expr_idxs);
                    did_err = args_did_err or did_err;

                    if (did_err) {
                        try self.retireCallLikeExpr(expr_idx, expr_var);
                    } else {
                        // From the base function type, extract its shape. Effect
                        // classification happens only after arguments unify below:
                        // those unifications may resolve directed higher-order
                        // effect dependencies carried by this function type.
                        const mb_func: ?types_mod.Func = inner_blk: {
                            // Here, we unwrap the function, following aliases, to get
                            // the actual function we want to check against
                            var var_ = func_var;
                            var guard = types_mod.debug.IterationGuard.init("checkExpr.call.unwrapFuncVar");
                            while (true) {
                                guard.tick();
                                switch (self.types.resolveVar(var_).desc.content) {
                                    .structure => |flat_type| {
                                        switch (flat_type) {
                                            .fn_pure, .fn_unbound, .fn_effectful => |func| break :inner_blk func,
                                            .record,
                                            .record_unbound,
                                            .tuple,
                                            .nominal_type,
                                            .empty_record,
                                            .tag_union,
                                            .empty_tag_union,
                                            => break :inner_blk null,
                                        }
                                    },
                                    .alias => |alias| {
                                        var_ = self.types.getAliasBackingVar(alias);
                                    },
                                    .flex, .rigid, .field_presence, .err => break :inner_blk null,
                                }
                            }
                        };
                        // Get the name of the function (for error messages)
                        const func_name: ?Ident.Idx = self.getExprPatternIdent(call.func);

                        // Now, check the call args against the type of function
                        if (mb_func) |func| {
                            // Use index-based iteration instead of slices because unifyInContext
                            // may trigger reallocations that would invalidate slice pointers
                            const func_args_range = func.args;
                            const func_args_len = func_args_range.len();

                            if (func_args_len == call_arg_expr_idxs.len) {
                                // First, find all the "rigid" variables in a the function's type
                                // and unify the matching corresponding call arguments together.
                                //
                                // Here, "rigid" is in quotes because at this point, the expected function
                                // has been instantiated such that the rigid variables should all resolve
                                // to the same exact flex variable. So we are actually checking for flex
                                // variables here.
                                for (0..func_args_len) |i| {
                                    const expected_arg_1 = self.types.getVarAt(func_args_range, @intCast(i));
                                    const expected_resolved_1 = self.types.resolveVar(expected_arg_1);

                                    // Ensure the above comment is true. That is, that all
                                    // rigid vars for this function have been instantiated to
                                    // flex vars by the time we get here.
                                    // std.debug.assert(expected_resolved_1.desc.content != .rigid);

                                    // Skip any concrete arguments
                                    if (expected_resolved_1.desc.content != .flex and expected_resolved_1.desc.content != .rigid) {
                                        continue;
                                    }

                                    // Look for other arguments with the same type variable
                                    for (i + 1..func_args_len) |j| {
                                        const expected_arg_2 = self.types.getVarAt(func_args_range, @intCast(j));
                                        const expected_resolved_2 = self.types.resolveVar(expected_arg_2);
                                        if (expected_resolved_1.var_ == expected_resolved_2.var_) {
                                            // These two argument indexes in the called *function's*
                                            // type have the same rigid variable! So, we unify
                                            // the corresponding *call args*

                                            const arg_1 = @as(Var, ModuleEnv.varFrom(call_arg_expr_idxs[i]));
                                            const arg_2 = @as(Var, ModuleEnv.varFrom(call_arg_expr_idxs[j]));

                                            const row_width_relation: unifier.RowWidthRelation = if (self.exprIsFreshRecordConstruction(call_arg_expr_idxs[i]) or
                                                self.exprIsFreshRecordConstruction(call_arg_expr_idxs[j])) .construction else .exact;
                                            const unify_result = try self.unifyOwnedRelation(arg_1, arg_2, env, .{
                                                .fn_args_bound_var = .{
                                                    .fn_name = func_name,
                                                    .first_arg_var = arg_1,
                                                    .second_arg_var = arg_2,
                                                    .first_arg_index = @intCast(i),
                                                    .second_arg_index = @intCast(j),
                                                    .num_args = @intCast(call_arg_expr_idxs.len),
                                                },
                                            }, row_width_relation);
                                            if (unify_result.isProblem()) {
                                                // Context already set by unifyInContext
                                                // Stop execution
                                                try self.markErroneous(expr_var);
                                                try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
                                                break :blk;
                                            }
                                        }
                                    }
                                }

                                // Check the function's arguments against the actual
                                // called arguments, unifying each one
                                for (call_arg_expr_idxs, 0..) |call_expr_idx, arg_index| {
                                    const expected_arg_var = self.types.getVarAt(func_args_range, @intCast(arg_index));
                                    const unify_result = try self.unifyOwnedRelation(expected_arg_var, ModuleEnv.varFrom(call_expr_idx), env, .{ .fn_call_arg = .{
                                        .fn_name = func_name,
                                        .call_expr = expr_idx,
                                        .arg_index = @intCast(arg_index),
                                        .num_args = @intCast(call_arg_expr_idxs.len),
                                        .arg_var = ModuleEnv.varFrom(call_expr_idx),
                                    } }, if (self.exprIsFreshRecordConstruction(call_expr_idx)) .construction else .exact);
                                    if (unify_result.isProblem()) {
                                        // Stop execution
                                        try self.markErroneous(expr_var);
                                        try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
                                        break :blk;
                                    }
                                }

                                if (call.called_via == .record_builder) {
                                    const result = try self.enforceRecordBuilderMap2Return(func, env, expr_idx, func_name);
                                    if (result.isProblem()) {
                                        try self.markErroneous(expr_var);
                                        try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
                                        break :blk;
                                    }
                                }

                                // Redirect the expr to the function's return type
                                _ = try self.unify(expr_var, func.ret, env);
                            } else {
                                // We get here, then the arity of the function
                                // being called and the callsite do not match.
                                // This means it's a  regular type mismatch

                                // In this case, we fall back to a regular
                                // mismatch to show the actual vs expected, and
                                // allow the problem reporting  hint mechanism
                                // to add some context

                                const call_arg_vars: []Var = @ptrCast(call_arg_expr_idxs);
                                const call_func_ret = try self.fresh(env, expr_region);
                                const call_func_content = try self.types.mkFuncUnbound(call_arg_vars, call_func_ret);
                                const call_func_var = try self.freshFromContent(call_func_content, env, expr_region);

                                const arity_result = try self.unifyOwnedRelation(func_var, call_func_var, env, .{ .fn_call_arity = .{
                                    .fn_name = func_name,
                                    .expected_args = @intCast(func_args_len),
                                    .actual_args = @intCast(call_arg_expr_idxs.len),
                                } }, .exact);
                                if (arity_result.isProblem()) {
                                    try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
                                }

                                // Then, we set the root expr to redirect to the return
                                // type of that function, since a call expr ultimate
                                // resolve to the  returned type
                                _ = try self.unify(expr_var, call_func_ret, env);
                            }
                        } else {
                            // We get here if the type of expr being called
                            // (`mk_fn` in `(mk_fn())(arg)`) is NOT already
                            // inferred to be a function type.

                            // This can mean a regular type mismatch, but it can also
                            // mean that the thing being called yet has not yet been
                            // inferred (like if this is an anonymous function param)

                            // Either way, we know what the type  *should* be, based
                            // on how it's being used here. So we create that func
                            // type and unify the function being called against it

                            const call_arg_vars: []Var = @ptrCast(call_arg_expr_idxs);
                            const call_func_ret = try self.fresh(env, expr_region);
                            const call_func_content = try self.types.mkFuncUnbound(call_arg_vars, call_func_ret);
                            const call_func_var = try self.freshFromContent(call_func_content, env, expr_region);

                            const call_result = try self.unifyOwnedRelation(func_var, call_func_var, env, .none, .exact);
                            if (call_result.isProblem()) {
                                try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
                            }

                            // Then, we set the root expr to redirect to the return
                            // type of that function, since a call expr ultimate
                            // resolve to the  returned type
                            _ = try self.unify(expr_var, call_func_ret, env);
                        }

                        // Argument unification above is the point at which an
                        // effect-polymorphic callback can become pure or
                        // effectful. Resolve the directed formula now, never from
                        // the pre-unification function tag.
                        const call_effect_state: FunctionEffectState = if (self.callTargetIsInFlightRecursiveRef(call.func)) recursive_effect: {
                            // A declared pure/effectful tag on an in-flight
                            // recursive scheme must not seed the body's
                            // fixpoint. An inferred unbound slot, however, is a
                            // real directed edge between SCC members and must
                            // survive until the boundary resolves the group.
                            const recursive_func = self.types.resolveVar(func_var).desc.content;
                            break :recursive_effect switch (recursive_func) {
                                .structure => |flat| switch (flat) {
                                    .fn_unbound => .unresolved,
                                    .fn_pure, .fn_effectful => .pure,
                                    .record,
                                    .record_unbound,
                                    .tuple,
                                    .nominal_type,
                                    .empty_record,
                                    .tag_union,
                                    .empty_tag_union,
                                    => .unresolved,
                                },
                                .flex, .rigid, .alias, .field_presence, .err => .unresolved,
                            };
                        } else try self.functionEffectState(func_var);
                        switch (call_effect_state) {
                            .effectful => does_fx = true,
                            .unresolved => try self.recordCurrentFunctionEffectDependency(func_var),
                            .pure => {},
                        }

                        const published_constraint_args: []Var = @ptrCast(call_arg_expr_idxs);
                        const published_constraint_func = Func{
                            .args = try self.types.appendVars(published_constraint_args),
                            .ret = expr_var,
                            .effect_deps = if (call_effect_state == .unresolved)
                                try self.types.appendVars(&.{func_var})
                            else
                                Var.SafeList.Range.empty(),
                        };
                        const published_constraint_flat: FlatType = switch (call_effect_state) {
                            .effectful => .{ .fn_effectful = published_constraint_func },
                            .pure => .{ .fn_pure = published_constraint_func },
                            .unresolved => .{ .fn_unbound = published_constraint_func },
                        };
                        const published_constraint_fn_var = try self.freshFromContent(.{ .structure = published_constraint_flat }, env, expr_region);

                        try self.cir.store.replaceExprWithCallConstraint(
                            expr_idx,
                            call.func,
                            call.args,
                            call.called_via,
                            published_constraint_fn_var,
                        );
                    }
                },
                .binop, .unary_op, .string_interpolation => {
                    // The canonicalizer currently only produces apply, record_builder, or range for e_call expressions.
                    // Other call types (binop, unary_op, string_interpolation) are
                    // represented as different expression types. If we hit this, there's a compiler bug.
                    std.debug.assert(false);
                    try self.markErroneous(expr_var);
                },
            }
        },
        .e_if => |if_expr| {
            does_fx = try self.checkIfElseExpr(
                expr_idx,
                expr_region,
                env,
                if_expr,
                nested_expected,
                is_call_arg,
                is_immediate_callee,
            ) or does_fx;
        },
        .e_match => |match| {
            does_fx = try self.checkMatchExpr(
                expr_idx,
                env,
                match,
                nested_expected,
                is_call_arg,
                is_immediate_callee,
            ) or does_fx;
        },
        .e_binop => |binop| {
            does_fx = try self.checkBinopExpr(expr_idx, expr_var, expr_region, env, binop, nested_expected) or does_fx;
        },
        .e_unary_minus => |unary| {
            does_fx = try self.checkUnaryMinusExpr(expr_idx, expr_var, expr_region, env, unary, nested_expected) or does_fx;
        },
        .e_unary_not => |unary| {
            does_fx = try self.checkUnaryNotExpr(expr_idx, expr_var, expr_region, env, unary, nested_expected) or does_fx;
        },
        .e_field_access => |field_access| {
            std.debug.assert(field_access.segments.len > 0);

            // Check the receiver (LHS)
            does_fx = try self.checkExpr(field_access.receiver, env, child_expected) or does_fx;

            // The var that's receiving the record field
            var acc_receiver_var = ModuleEnv.varFrom(field_access.receiver);

            // Whether any segment so far was a `.?` access. The Try wrapper is
            // per-CHAIN, not per-segment: one optional segment anywhere makes
            // the whole chain produce a single `Try(τ_final, [MissingField])`,
            // with later segments (required or optional) riding in the Ok
            // path. The runtime semantics are the monadic short-circuit—the
            // first missing optional slot yields `Err(MissingField)`.
            var saw_optional = false;

            var access_failed = false;

            // Then iterate over the access segments, resolving & unifying
            for (0..field_access.segments.len) |i| {
                // Get the field access segment
                const access_idx = self.cir.store.fieldAccessSegmentAt(field_access.segments, @intCast(i));
                const access = self.cir.store.getFieldAccessSegment(access_idx);

                // Setup the CIR node
                const access_var = ModuleEnv.varFrom(access_idx);
                const access_region = self.getRegionAt(access_var);
                try self.setVarRank(access_var, env);

                // Every segment's var is the FIELD's value type—for `.?`
                // segments too, so chains keep accessing the underlying value.
                // The chain-level Try wrapper is added once, after the loop.
                try self.unifyWith(access_var, .{ .flex = Flex.init() }, env);
                const record_field_range = try self.types.appendRecordFields(&.{types_mod.RecordField{
                    .name = access.name,
                    .presence = blk: {
                        switch (access.mode) {
                            .required => break :blk .required(access_var),
                            .optional => {
                                // The row constrains the FIELD's value type
                                // (`name ?: τ` with a fresh flex kind—a
                                // concrete `optional` demand would let
                                // absorption admit the field into a closed
                                // receiver, accepting `.?` on undeclared
                                // fields and mutating annotated rows). The
                                // access is recorded and JUDGED at every
                                // generalization boundary (and finalize as
                                // backstop): a required receiver field is
                                // rejected, a still-flex kind pins to
                                // `optional` BEFORE the scheme forms—so
                                // instantiated copies carry the concrete
                                // kind and cannot escape the judgment
                                // (design.md "Field Kinds").
                                const presence_var = try self.fresh(env, access_region);
                                try self.optional_field_accesses.append(self.gpa, .{
                                    .presence_var = presence_var,
                                    .field_name = access.name,
                                    .region = access_region,
                                });
                                saw_optional = true;
                                break :blk .unknown(presence_var, access_var);
                            },
                        }
                    },
                }});
                const record_ext_var = try self.fresh(env, access_region);
                const record_being_accessed = try self.freshFromContent(.{ .structure = .{
                    .record = .{ .fields = record_field_range, .ext = record_ext_var },
                } }, env, expr_region);

                // A rejected access belongs to this expression. Preserve the
                // independently-solved receiver graph and make only the access
                // erroneous so post-check lowering emits its runtime crash.
                const access_result = try self.unifyOwnedRelation(record_being_accessed, acc_receiver_var, env, .{ .record_access = .{
                    .field_name = access.name,
                    .field_region = access_region,
                    .mode = switch (access.mode) {
                        .required => .required,
                        .optional => .optional,
                    },
                } }, .construction);
                if (access_result.isProblem()) {
                    try self.markErroneous(expr_var);
                    try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
                    access_failed = true;
                    break;
                }

                // For the next iteration, we set the field we just accessed to
                // be the new receiver. This lets us chain access, like: a.b.c
                acc_receiver_var = access_var;
            }

            // The chain's type: the final field's value type, wrapped in one
            // `Try(τ, [MissingField])` when any segment was optional.
            if (!access_failed) {
                if (saw_optional) {
                    const missing_err_var = try self.makeFieldMissingTag(env, expr_region);
                    try self.unifyWith(
                        expr_var,
                        try self.mkTryContent(acc_receiver_var, missing_err_var),
                        env,
                    );
                } else {
                    _ = try self.unify(expr_var, acc_receiver_var, env);
                }
            }
        },
        .e_interpolation => |interpolation| {
            self.checking_call_arg = true;
            does_fx = try self.checkExpr(interpolation.first, env, child_expected) or does_fx;
            const first_var = ModuleEnv.varFrom(interpolation.first);
            const str_var = try self.freshStr(env, expr_region);
            _ = try self.unify(first_var, str_var, env);
            var did_err = try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, &.{interpolation.first});

            const parts = self.cir.store.sliceExpr(interpolation.parts);
            std.debug.assert(parts.len % 2 == 0);
            const item_var = try self.fresh(env, expr_region);
            var part_i: usize = 0;
            while (part_i < parts.len) : (part_i += 2) {
                self.checking_call_arg = true;
                does_fx = try self.checkExpr(parts[part_i], env, child_expected) or does_fx;

                self.checking_call_arg = true;
                does_fx = try self.checkExpr(parts[part_i + 1], env, child_expected) or does_fx;
                const following_segment_var = ModuleEnv.varFrom(parts[part_i + 1]);
                _ = try self.unify(str_var, following_segment_var, env);
            }
            did_err = try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, parts) or did_err;

            const pair_elems = try self.types.appendVars(&.{ item_var, str_var });
            const pair_var = try self.freshFromContent(.{ .structure = .{
                .tuple = .{ .elems = pair_elems },
            } }, env, expr_region);
            const rest_var = try self.mkIterVar(pair_var, env, expr_region);
            try self.setVarRank(rest_var, env);

            const step_content = try self.mkIteratorStepContent(pair_var, rest_var, env);
            const step_ret_var = try self.freshFromContent(step_content.content, env, expr_region);
            const empty_args = try self.types.appendVars(&.{});
            const step_fn_var = try self.freshFromContent(.{ .structure = .{ .fn_unbound = Func{
                .args = empty_args,
                .ret = step_ret_var,
            } } }, env, expr_region);

            if (!did_err) {
                const dispatcher_var = (try self.explicitTypeSuffixVar(expr_idx, expr_region, env)) orelse expr_var;
                const arg_vars = [_]Var{ first_var, rest_var };
                const constraint_fn_var = try self.mkInterpolationConstraint(
                    dispatcher_var,
                    &arg_vars,
                    expr_var,
                    item_var,
                    self.cir.idents.from_interpolation,
                    env,
                    interpolation.method_name_region,
                    expr_idx,
                );
                try self.cir.store.replaceExprWithInterpolationConstraint(
                    expr_idx,
                    interpolation.first,
                    interpolation.parts,
                    interpolation.method_name_region,
                    constraint_fn_var,
                    step_fn_var,
                    dispatcher_var,
                );
            }
        },
        .e_method_call => |method_call| {
            does_fx = try self.checkExpr(method_call.receiver, env, child_expected) or does_fx;
            const receiver_var = ModuleEnv.varFrom(method_call.receiver);
            var did_err = try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, &.{method_call.receiver});

            const arg_expr_idxs = self.cir.store.sliceExpr(method_call.args);
            var arg_vars_sfa = std.heap.stackFallback(16 * @sizeOf(Var), self.gpa);
            const arg_vars_alloc = arg_vars_sfa.get();
            const arg_vars = try arg_vars_alloc.alloc(Var, arg_expr_idxs.len);
            defer arg_vars_alloc.free(arg_vars);

            for (arg_expr_idxs, 0..) |arg_expr_idx, i| {
                self.checking_call_arg = true;
                does_fx = try self.checkExpr(arg_expr_idx, env, child_expected) or does_fx;
                const arg_var = ModuleEnv.varFrom(arg_expr_idx);
                arg_vars[i] = arg_var;
            }
            did_err = try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, arg_expr_idxs) or did_err;

            if (!did_err) {
                const constraint_fn_var = try self.mkMethodCallConstraint(
                    receiver_var,
                    arg_vars,
                    expr_var,
                    method_call.method_name,
                    env,
                    method_call.method_name_region,
                    expr_idx,
                );
                try self.cir.store.replaceExprWithDispatchCall(
                    expr_idx,
                    method_call.receiver,
                    method_call.method_name,
                    method_call.method_name_region,
                    method_call.args,
                    constraint_fn_var,
                    .method_call,
                );
                if (try self.varIsEffectfulFunction(constraint_fn_var)) {
                    self.markCurrentHoistObservableEffect();
                    does_fx = true;
                }
            }
        },
        .e_dispatch_call => |method_call| {
            does_fx = try self.checkExpr(method_call.receiver, env, child_expected) or does_fx;
            _ = try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, &.{method_call.receiver});

            const arg_expr_idxs = self.cir.store.sliceExpr(method_call.args);
            for (arg_expr_idxs) |arg_expr_idx| {
                self.checking_call_arg = true;
                does_fx = try self.checkExpr(arg_expr_idx, env, child_expected) or does_fx;
            }
            _ = try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, arg_expr_idxs);

            if (try self.varIsEffectfulFunction(method_call.constraint_fn_var)) {
                self.markCurrentHoistObservableEffect();
                does_fx = true;
            }
        },
        .e_structural_eq => |eq| {
            does_fx = try self.checkExpr(eq.lhs, env, child_expected) or does_fx;
            does_fx = try self.checkExpr(eq.rhs, env, child_expected) or does_fx;

            const lhs_var = ModuleEnv.varFrom(eq.lhs);
            const rhs_var = ModuleEnv.varFrom(eq.rhs);
            _ = try self.unify(lhs_var, rhs_var, env);
            _ = try self.unify(try self.freshBool(env, expr_region), expr_var, env);
        },
        .e_structural_hash => |h| {
            does_fx = try self.checkExpr(h.value, env, child_expected) or does_fx;
            does_fx = try self.checkExpr(h.hasher, env, child_expected) or does_fx;

            // `to_hash : self, Hasher -> Hasher` threads the Hasher through, so the
            // result has the same type as the incoming Hasher argument.
            const hasher_var = ModuleEnv.varFrom(h.hasher);
            _ = try self.unify(hasher_var, expr_var, env);
        },
        .e_method_eq => |eq| {
            var arg_vars_sfa = std.heap.stackFallback(@sizeOf(Var), self.gpa);
            const arg_vars_alloc = arg_vars_sfa.get();
            const arg_vars = try arg_vars_alloc.alloc(Var, 1);
            defer arg_vars_alloc.free(arg_vars);

            self.checking_call_arg = true;
            does_fx = try self.checkExpr(eq.lhs, env, child_expected) or does_fx;
            self.checking_call_arg = true;
            does_fx = try self.checkExpr(eq.rhs, env, child_expected) or does_fx;

            const lhs_var = ModuleEnv.varFrom(eq.lhs);
            arg_vars[0] = ModuleEnv.varFrom(eq.rhs);
            if (!try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, &.{ eq.lhs, eq.rhs })) {
                const constraint_fn_var = try self.mkMethodCallConstraint(
                    lhs_var,
                    arg_vars,
                    expr_var,
                    self.cir.idents.is_eq,
                    env,
                    expr_region,
                    expr_idx,
                );
                self.cir.store.replaceExprWithMethodEq(
                    expr_idx,
                    eq.lhs,
                    eq.rhs,
                    eq.negated,
                    constraint_fn_var,
                );
            }
        },
        .e_type_method_call => |method_call| {
            const arg_expr_idxs = self.cir.store.sliceExpr(method_call.args);
            var arg_vars_sfa = std.heap.stackFallback(16 * @sizeOf(Var), self.gpa);
            const arg_vars_alloc = arg_vars_sfa.get();
            const arg_vars = try arg_vars_alloc.alloc(Var, arg_expr_idxs.len);
            defer arg_vars_alloc.free(arg_vars);

            for (arg_expr_idxs, 0..) |arg_expr_idx, i| {
                self.checking_call_arg = true;
                does_fx = try self.checkExpr(arg_expr_idx, env, child_expected) or does_fx;
                const arg_var = ModuleEnv.varFrom(arg_expr_idx);
                arg_vars[i] = arg_var;
            }
            const did_err = try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, arg_expr_idxs);

            if (!did_err) {
                const dispatcher_var = self.typeDispatchOwnerVar(method_call.type_dispatch_stmt);
                const constraint_fn_var = try self.mkTypeMethodCallConstraint(
                    dispatcher_var,
                    arg_vars,
                    expr_var,
                    method_call.method_name,
                    env,
                    method_call.method_name_region,
                    expr_idx,
                );
                try self.cir.store.replaceExprWithTypeDispatchCall(
                    expr_idx,
                    method_call.type_dispatch_stmt,
                    method_call.method_name,
                    method_call.method_name_region,
                    method_call.args,
                    constraint_fn_var,
                );
                if (try self.varIsEffectfulFunction(constraint_fn_var)) {
                    self.markCurrentHoistObservableEffect();
                    does_fx = true;
                }
            }
        },
        .e_type_dispatch_call => |method_call| {
            const arg_expr_idxs = self.cir.store.sliceExpr(method_call.args);
            for (arg_expr_idxs) |arg_expr_idx| {
                self.checking_call_arg = true;
                does_fx = try self.checkExpr(arg_expr_idx, env, child_expected) or does_fx;
            }
            _ = try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, arg_expr_idxs);

            if (try self.varIsEffectfulFunction(method_call.constraint_fn_var)) {
                self.markCurrentHoistObservableEffect();
                does_fx = true;
            }
        },
        .e_crash => {
            try self.unifyWith(expr_var, .{ .flex = Flex.init() }, env);
        },
        .e_expect_err => |expect_err| {
            self.markCurrentHoistObservableEffect();
            // The Err payload is consumed at runtime when the enclosing expect
            // fails; this expression itself never returns, so its type is free.
            _ = try self.checkExpr(expect_err.expr, env, child_expected);
            try self.unifyWith(expr_var, .{ .flex = Flex.init() }, env);
        },
        .e_dbg => |dbg| {
            self.markCurrentHoistObservableEffect();
            // dbg evaluates its inner expression but returns {} (like expect)
            _ = try self.checkExpr(dbg.expr, env, child_expected);
            does_fx = false;
            try self.unifyWith(expr_var, .{ .structure = .empty_record }, env);
        },
        .e_expect => |expect| {
            self.markCurrentHoistObservableEffect();
            const expect_does_fx = try self.checkExpectBody(expect.body, env, child_expected, expr_region);
            does_fx = expect_does_fx or does_fx;
            const body_var = ModuleEnv.varFrom(expect.body);

            const bool_var = try self.freshBool(env, expr_region);
            _ = try self.unifyInContext(bool_var, body_var, env, .expect);

            try self.unifyWith(expr_var, .{ .structure = .empty_record }, env);
        },
        .e_for => |for_expr| {
            self.markCurrentHoistObservableEffect();
            does_fx = try self.checkIteratorForLoop(
                ModuleEnv.nodeIdxFrom(expr_idx),
                .{ .expr_idx = expr_idx, .expr_var = expr_var },
                for_expr.patt,
                for_expr.expr,
                for_expr.body,
                env,
                expr_region,
                nested_expected.forStatement(),
            ) or does_fx;

            // Like cor, loop bodies are ordinary expressions whose final value is
            // discarded by the loop construct itself. The loop expression still
            // evaluates to {}, but the body is not required to produce {}.
            try self.unifyWith(expr_var, .{ .structure = .empty_record }, env);
        },
        .e_ellipsis => {
            try self.unifyWith(expr_var, .{ .flex = Flex.init() }, env);
        },
        .e_anno_only => |anno| {
            if (expected.annotation != null and
                can.BuiltinLowLevel.isBuiltinModule(self.cir) and
                can.BuiltinLowLevel.isIntrinsicAnnotation(self.cir, anno.ident))
            {
                // Builtin.roc has a small explicit set of compiler-owned intrinsic
                // wrappers that post-check lowering handles from checked data.
            } else {
                const annotation_region = if (expected.annotation) |annotation_idx|
                    self.cir.store.getAnnotationRegion(annotation_idx)
                else
                    expr_region;
                switch (anno.kind) {
                    .ordinary => _ = try self.problems.appendProblem(self.gpa, .{ .annotation_only_value = .{
                        .region = annotation_region,
                    } }),
                    .unsupported_generated_method => _ = try self.problems.appendProblem(self.gpa, .{ .unsupported_generated_method = .{
                        .method_name = anno.ident,
                        .region = annotation_region,
                    } }),
                }
                // e_anno_only is its own non-executable artifact state; preserve the declared graph.
                if (expected.annotation == null) {
                    try self.markErroneous(expr_var);
                }
            }
        },
        .e_derived_method => {
            // Canonicalization has already validated this explicit compiler-owned
            // marker. Its generated target is published in the static dispatch
            // registry after checking.
        },
        .e_return => |ret| {
            self.markCurrentHoistObservableEffect();
            const expected_return = self.expectedReturnResultFor(ret.lambda);
            const return_expected = nested_expected.forReturnValue(expected_return);
            does_fx = try self.checkExpr(ret.expr, env, return_expected) or does_fx;
            const return_kind: ReturnConstraintKind = switch (ret.context) {
                .return_expr => .return_expr,
                .try_suffix => .try_suffix,
            };

            if (expected_return) |annotated_return| {
                try self.checkReturnRelation(annotated_return, ret.expr, return_kind.problemContext(), env);
            } else {
                // Validate the lambda body type against the return value after the
                // body is fully checked, but before the lambda generalizes.
                try self.appendReturnConstraint(ret.lambda, ret.expr, return_kind);
            }

            // Note that we DO NOT unify the return type with the expr here.
            // This is so this expr can unify with anything (like {} in the an implicit `else` branch)
        },
        .e_break => {
            // Nothing to do. `break` diverges, so this expression can unify with
            // any surrounding expected type.
        },
        .e_hosted_lambda => |lambda| {
            self.markCurrentHoistObservableEffect();
            // Record the parameter span for the end-of-check pinnable
            // collection (see `checked_lambda_params`).
            try self.checked_lambda_params.append(self.gpa, lambda.args);

            // For hosted lambda expressions, the type comes from the annotation.
            // This is similar to e_anno_only - the implementation is provided by the host.
            if (expected.annotation) |annotation_idx| {
                const annotation_var = ModuleEnv.varFrom(annotation_idx);
                if (try self.varContainsUnboxedFunctionInHostedSignature(annotation_var)) {
                    const region = self.cir.store.getAnnotationRegion(annotation_idx);
                    _ = try self.problems.appendProblem(self.gpa, .{ .hosted_unboxed_function = .{
                        .region = region,
                    } });
                }
                try self.checkHostBoundaryType(annotation_var, self.cir.store.getAnnotationRegion(annotation_idx));
                // The expr will be unified with the expected type below
                // expr_var is a flex var by default, so no action is need here
            } else {
                // This shouldn't happen since hosted lambdas always have annotations
                try self.markErroneous(expr_var);
            }
        },
        .e_run_low_level => |run_ll| {
            self.markCurrentHoistObservableEffect();
            // Check each argument expression in the run_low_level node
            const args = self.cir.store.exprSlice(run_ll.args);
            for (args) |arg_idx| {
                self.checking_call_arg = true;
                does_fx = try self.checkExpr(arg_idx, env, child_expected) or does_fx;
            }
            if (run_ll.op == .crash) {
                std.debug.assert(args.len == 1);
                const msg_var = ModuleEnv.varFrom(args[0]);
                const str_var = try self.freshStr(env, self.cir.store.getExprRegion(args[0]));
                _ = try self.unify(msg_var, str_var, env);
                try self.unifyWith(expr_var, .{ .flex = Flex.init() }, env);
            }
        },
        .e_runtime_error => {
            try self.markErroneous(expr_var);
        },
    }

    // Check if we have an annotation
    if (mb_anno_vars) |anno_vars| {
        // Unify the anno with the expr var
        const annotation_result = try self.unifyInContext(anno_vars.anno_var, expr_var, env, anno_vars.context);
        if (annotation_result.isProblem()) {
            // The diagnostic belongs to checking, but later stages need an
            // explicit executable value. End-of-check poisoning replaces this
            // expression with a runtime error while the binding retains the
            // annotation's checked type for all independent consumers.
            try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
        }

        // Check if the expression type contains any errors anywhere in its
        // structure. If it does and we have an annotation, use the annotation
        // type for the pattern instead of the expression type. This preserves
        // the annotation type for other code that references this identifier,
        // even when the expression has errors.
        //
        // For example, if the annotation is `I64 -> Str` and the expression has
        // an error in the return type (making it `I64 -> Error`), the pattern
        // should still get `I64 -> Str` from the annotation.
        self.var_set.clearRetainingCapacity();
        if (try self.varContainsError(expr_var, &self.var_set)) {
            // A method's callable wrapper is explicit input to method-template
            // publication, so keep that wrapper around its already-erroneous
            // child. Other annotated values are the executable boundary and
            // must themselves become the runtime error.
            const is_method_callable = isFunctionDef(&self.cir.store, self.cir.store.getExpr(expr_idx)) and
                self.exprDefinesMethod(expr_idx);
            if (!is_method_callable) {
                try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
            }
            // If there was an annotation AND the expr contains errors, then unify the
            // raw expr var against the annotation
            _ = try self.unify(expr_var_raw, anno_vars.anno_var_backup, env);
        } else {
            // Otherwise, make the explicit annotation the checked root for
            // this expression. The body has already constrained the
            // annotation's backing and any underscore variables above.
            _ = try self.unify(expr_var_raw, anno_vars.anno_var, env);
        }
    }

    self.var_set.clearRetainingCapacity();
    if (mb_anno_vars == null) {
        if (try self.varContainsError(expr_var, &self.var_set)) {
            try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
            self.call_operand_type_error_exprs.items[nodeSlot(expr_idx)] = true;
        }
    }

    // Check any accumulated static dispatch constraints
    try self.checkStaticDispatchConstraints(env, false);

    // If this type of expr should be generalized, generalize it!
    if (should_generalize) {
        // Bind pending record-destructure binders BEFORE boundary literal
        // defaulting: a numeral flowing through a destructured field only
        // becomes signature-reachable once the binder is unified through
        // the row, and defaulting's reachability classification must see
        // that link (see `judgeRecordDestructBinds`).
        try self.judgeRecordDestructBinds(env);
        if (env.rank() == self.currentGroupBoundaryRank()) {
            // This frame is the enclosing group's generalization boundary (a
            // singleton group's def RHS). Resolve dispatch obligations into
            // unchecked groups before anything here generalizes (Invariant D),
            // interleaved with boundary defaulting.
            try self.runGroupBoundary(&.{.{ .owner = expr_var_raw, .interface = expr_var }}, env);
        } else {
            // Inner lambda: boundary defaulting runs first—it must see
            // ranks BEFORE they are promoted to generalized. Pending dispatch
            // obligations (pinned at the group's boundary rank) escape this
            // frame and stay live for the group boundary.
            try self.defaultLiteralsAtGeneralizationBoundary(.{ .owner = expr_var_raw, .interface = expr_var }, env);
        }
        try self.judgeFieldKindsAtBoundary(env);
        try self.generalizer.generalize(self.gpa, &env.var_pool, env.rank());
        try self.publishBindingScheme(expr_var_raw);
        self.retireNonGeneralizedTypeSchemes(&.{.{ .owner = expr_var_raw, .interface = expr_var }});
        try self.retireStructurallyPublishedTypeSchemeRequirements(
            &.{.{ .owner = expr_var_raw, .interface = expr_var }},
            env.rank(),
        );
        // The scheme's vars froze at generalized rank: judge this def's
        // dispatch-constrained receivers now, while the judgment is a
        // local question about one scheme (see
        // `judgeAmbiguityCandidatesAtGeneralization`).
        try self.judgeAmbiguityCandidatesAtGeneralization(.{ .owner = expr_var_raw, .interface = expr_var });
    }

    try hoist_frame.finish(does_fx);
    return does_fx;
}

/// Forward explicit call-position facts through a wrapper to the expression that
/// supplies that wrapper's value. No condition, guard, or block statement is a
/// direct callee; only a selected result can be invoked by the enclosing call.
fn checkExprInCallPosition(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    env: *Env,
    expected: Expected,
    is_call_arg: bool,
    is_immediate_callee: bool,
) std.mem.Allocator.Error!bool {
    const saved_checking_call_arg = self.checking_call_arg;
    const saved_checking_immediate_callee = self.checking_immediate_callee;
    self.checking_call_arg = is_call_arg;
    self.checking_immediate_callee = is_immediate_callee;
    defer self.checking_call_arg = saved_checking_call_arg;
    defer self.checking_immediate_callee = saved_checking_immediate_callee;
    return self.checkExpr(expr_idx, env, expected);
}

/// Retire a call-like expression before it introduces dispatch or call
/// relations when one of its already-checked operands is an erroneous value.
/// The child expression set is explicit checker output; operand identity comes
/// only from that set, never from the operand's solved type shape.
fn retireCallLikeExprWithErroneousOperands(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    expr_var: Var,
    operand_exprs: []const CIR.Expr.Idx,
) Allocator.Error!bool {
    if (!self.callLikeOperandsContainErroneousValue(operand_exprs)) return false;

    try self.retireCallLikeExpr(expr_idx, expr_var);
    return true;
}

fn retireCallLikeExpr(self: *Self, expr_idx: CIR.Expr.Idx, expr_var: Var) Allocator.Error!void {
    try self.markErroneous(expr_var);
    if (!self.erroneous_value_exprs.contains(expr_idx)) {
        try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
    }
    self.call_operand_type_error_exprs.items[nodeSlot(expr_idx)] = true;
}

fn callLikeOperandsContainErroneousValue(self: *const Self, operand_exprs: []const CIR.Expr.Idx) bool {
    for (operand_exprs) |operand_expr| {
        if (self.call_operand_type_error_exprs.items[nodeSlot(operand_expr)]) return true;
    }
    return false;
}

fn getExprPatternIdent(self: *const Self, expr_idx: CIR.Expr.Idx) ?Ident.Idx {
    const trace = tracy.trace(@src());
    defer trace.end();

    const func_expr = self.cir.store.getExpr(expr_idx);
    if (func_expr != .e_lookup_local) return null;
    // Get the pattern that defines this identifier
    const pattern = self.cir.store.getPattern(func_expr.e_lookup_local.pattern_idx);
    if (pattern != .assign) return null;
    return pattern.assign.ident;
}

fn validateToInspectMethodTypes(self: *Self, env: *Env) Allocator.Error!void {
    var raw_node_idx: u32 = 0;
    while (raw_node_idx < self.cir.store.nodes.len()) : (raw_node_idx += 1) {
        const node_idx: CIR.Node.Idx = @enumFromInt(raw_node_idx);
        if (!isExprNodeTag(self.cir.store.nodes.get(node_idx).tag)) continue;

        const expr_idx: CIR.Expr.Idx = @enumFromInt(raw_node_idx);
        const expr = self.cir.store.getExpr(expr_idx);
        if (expr != .e_call) continue;
        const call = expr.e_call;
        if (!self.exprIsBuiltinStrInspect(call.func)) continue;
        const args = self.cir.store.sliceExpr(call.args);
        if (args.len != 1) continue;
        try self.validateToInspectMethodTypeForArg(
            args[0],
            env,
            self.cir.store.getExprRegion(args[0]),
        );
    }
}

fn exprIsBuiltinStrInspect(self: *Self, expr_idx: CIR.Expr.Idx) bool {
    const expr = self.cir.store.getExpr(expr_idx);
    if (expr == .e_lookup_local) {
        const ident = self.getPatternIdent(expr.e_lookup_local.pattern_idx) orelse return false;
        return ident.eql(self.cir.idents.builtin_str_inspect);
    }
    if (expr != .e_lookup_external) return false;
    const ext = expr.e_lookup_external;
    const module_idx = self.cir.imports.getResolvedModule(ext.module_idx) orelse return false;
    if (module_idx >= self.imported_modules.len) return false;
    const other_env = self.imported_modules[module_idx];
    const def_idx: CIR.Def.Idx = @enumFromInt(@as(u32, ext.target_node_idx));
    const ident = patternIdentInModule(other_env, def_idx) orelse return false;
    return ident.eql(other_env.idents.builtin_str_inspect);
}

fn validateToInspectMethodTypeForArg(
    self: *Self,
    arg_expr_idx: CIR.Expr.Idx,
    env: *Env,
    region: Region,
) Allocator.Error!void {
    const arg_var = ModuleEnv.varFrom(arg_expr_idx);
    const resolved = self.types.resolveVar(arg_var);

    if (self.exprIsTopLevelLookup(arg_expr_idx)) {
        self.inspect_type_visits.clearRetainingCapacity();
        if (try self.varHasUnresolvedInspectContent(arg_var, .value, &self.inspect_type_visits)) {
            try self.reportPolymorphicValueProblem(arg_var, arg_var, null);
            return;
        }
    }
    switch (resolved.desc.content) {
        .structure => |structure| switch (structure) {
            .nominal_type => |nominal| try self.validateNominalToInspectMethodType(arg_var, nominal, env, region),
            .record, .record_unbound, .tuple, .fn_pure, .fn_effectful, .fn_unbound, .empty_record, .tag_union, .empty_tag_union => {},
        },
        .alias => |alias| try self.validateAliasToInspectMethodType(arg_var, alias, env, region),
        .flex,
        .rigid,
        .err,
        .field_presence,
        => {},
    }
}

fn exprIsTopLevelLookup(self: *Self, expr_idx: CIR.Expr.Idx) bool {
    const expr = self.cir.store.getExpr(expr_idx);
    if (expr != .e_lookup_local) return false;
    return self.patternIsTopLevelDef(expr.e_lookup_local.pattern_idx);
}

fn validateNominalToInspectMethodType(
    self: *Self,
    arg_var: Var,
    nominal: types_mod.NominalType,
    env: *Env,
    region: Region,
) Allocator.Error!void {
    const method = try self.toInspectMethodVarForNominal(nominal, env, region) orelse return;
    try self.validateToInspectMethodVar(arg_var, method.var_, method.dispatcher_name, env, region);
}

fn validateAliasToInspectMethodType(
    self: *Self,
    arg_var: Var,
    alias: types_mod.Alias,
    env: *Env,
    region: Region,
) Allocator.Error!void {
    const method = try self.toInspectMethodVarForAlias(alias, env, region) orelse return;
    try self.validateToInspectMethodVar(arg_var, method.var_, method.dispatcher_name, env, region);
}

const ToInspectMethodVar = struct {
    var_: Var,
    dispatcher_name: Ident.Idx,
};

fn validateToInspectMethodVar(
    self: *Self,
    arg_var: Var,
    method_var: Var,
    dispatcher_name: Ident.Idx,
    env: *Env,
    region: Region,
) Allocator.Error!void {
    const str_var = try self.freshStr(env, region);
    const args_range = try self.types.appendVars(&.{arg_var});
    const expected_fn_var = try self.freshFromContent(.{ .structure = .{ .fn_unbound = Func{
        .args = args_range,
        .ret = str_var,
    } } }, env, region);

    const result = try self.unifyInContext(method_var, expected_fn_var, env, .{ .method_type = .{
        .constraint_var = arg_var,
        .dispatcher_name = dispatcher_name,
        .method_name = self.cir.idents.to_inspect,
    } });
    if (result.isProblem()) {
        try self.markErroneous(expected_fn_var);
    }
}

fn toInspectMethodVarForNominal(
    self: *Self,
    nominal: types_mod.NominalType,
    env: *Env,
    region: Region,
) Allocator.Error!?ToInspectMethodVar {
    const original_env, const is_this_module = try self.methodOwnerEnv(
        nominal.origin_module,
        nominal.sourceDeclOptional(),
        nominal.originIsBuiltin(),
    );
    const method_binding = original_env.lookupMethodBindingFromEnvAndDeclConst(
        self.cir,
        nominal.sourceDeclOptional(),
        self.cir.idents.to_inspect,
    ) orelse return null;
    return try self.methodVarFromOriginalEnv(original_env, is_this_module, method_binding.type_node_idx, nominal.ident.ident_idx, env, region);
}

fn toInspectMethodVarForAlias(
    self: *Self,
    alias: types_mod.Alias,
    env: *Env,
    region: Region,
) Allocator.Error!?ToInspectMethodVar {
    const original_env, const is_this_module = try self.methodOwnerEnv(
        alias.origin_module,
        alias.source_decl.toOptional(),
        alias.source_decl.originIsBuiltin(),
    );
    const method_binding = original_env.lookupMethodBindingFromTwoEnvsAndDeclConst(
        alias.source_decl.toOptional(),
        self.cir,
        self.cir.idents.to_inspect,
    ) orelse return null;
    return try self.methodVarFromOriginalEnv(original_env, is_this_module, method_binding.type_node_idx, alias.ident.ident_idx, env, region);
}

fn methodOwnerEnv(
    self: *Self,
    origin_module: base.ModuleIdentity.Idx,
    source_decl: ?u32,
    origin_is_builtin: bool,
) Allocator.Error!struct { *const ModuleEnv, bool } {
    return self.ownerEnvForOriginModule(origin_module, source_decl, origin_is_builtin, "to_inspect");
}

const OwnerEnvCandidate = struct {
    env: *const ModuleEnv,
    is_this_module: bool,
};

fn appendOwnerEnvByIdentity(
    gpa: std.mem.Allocator,
    owner_envs: *std.AutoHashMapUnmanaged(base.ModuleIdentity.Hash, OwnerEnvCandidate),
    env: *const ModuleEnv,
    is_this_module: bool,
) std.mem.Allocator.Error!void {
    const identity = env.contentIdentityHash() orelse {
        std.debug.panic(
            "type checker invariant violated: owner module '{s}' has no content identity",
            .{env.module_name},
        );
    };
    const entry = try owner_envs.getOrPut(gpa, identity.*);
    if (!entry.found_existing or is_this_module) {
        entry.value_ptr.* = .{ .env = env, .is_this_module = is_this_module };
    }
}

const StaticDispatchMethodBinding = struct {
    env: *const ModuleEnv,
    is_this_module: bool,
    binding: ModuleEnv.MethodBinding,
};

const AssociatedLookupCacheKey = struct {
    owner_var: Var,
    item_ident: Ident.Idx,
};

const AssociatedLookupResolution = struct {
    target: StaticDispatchMethodBinding,
    module_identity: base.ModuleIdentity.Idx,
};

fn staticDispatchBindingIsDerivedMarker(lookup: StaticDispatchMethodBinding) bool {
    return generatedDerivedMethodDef(lookup.env, lookup.binding.def_idx);
}

fn staticDispatchBindingIsUnsupportedGeneratedMethod(lookup: StaticDispatchMethodBinding) bool {
    const def = lookup.env.store.getDef(lookup.binding.def_idx);
    const expr = lookup.env.store.getExpr(def.expr);
    if (expr != .e_anno_only) return false;
    return expr.e_anno_only.kind == .unsupported_generated_method;
}

/// Reject a dispatch whose method declaration names no value. A bare underscore
/// requesting an unsupported generated method reports itself at the declaration;
/// every other annotation without a body reports here, because the dispatch is
/// the site with nothing to call.
fn rejectValuelessMethodDispatch(
    self: *Self,
    lookup: StaticDispatchMethodBinding,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
    env: *Env,
    failure_expr: ?CIR.Expr.Idx,
) Allocator.Error!bool {
    if (!annotationOnlyValueDef(lookup.env, lookup.binding.def_idx)) return false;
    if (!staticDispatchBindingIsUnsupportedGeneratedMethod(lookup)) {
        if (failure_expr orelse self.constraintSourceExpr(dispatcher_var, constraint)) |expr_idx| {
            _ = try self.problems.appendProblem(self.gpa, .{ .annotation_only_value_use = .{
                .region = self.cir.store.getExprRegion(expr_idx),
            } });
        }
    }
    try self.poisonConstraintFailure(dispatcher_var, constraint, env, failure_expr);
    try self.markStaticDispatchRejected(constraint);
    return true;
}

fn lookupStaticDispatchMethodBinding(
    self: *const Self,
    owner_env: *const ModuleEnv,
    owner_source_decl: ?u32,
    method_source_env: *const ModuleEnv,
    method_ident: Ident.Idx,
) ?StaticDispatchMethodBinding {
    if (self.lookupStaticDispatchMethodBindingInEnv(owner_env, owner_env, owner_source_decl, method_source_env, method_ident)) |found| {
        return found;
    }

    if (owner_env != self.cir) {
        if (self.lookupStaticDispatchMethodBindingInEnv(self.cir, owner_env, owner_source_decl, method_source_env, method_ident)) |found| {
            return found;
        }
    }

    for (self.imported_modules) |candidate_env| {
        if (candidate_env == owner_env or candidate_env == self.cir) continue;
        if (self.lookupStaticDispatchMethodBindingInEnv(candidate_env, owner_env, owner_source_decl, method_source_env, method_ident)) |found| {
            return found;
        }
    }

    return null;
}

fn lookupStaticDispatchMethodBindingInEnv(
    self: *const Self,
    candidate_env: *const ModuleEnv,
    owner_env: *const ModuleEnv,
    owner_source_decl: ?u32,
    method_source_env: *const ModuleEnv,
    method_ident: Ident.Idx,
) ?StaticDispatchMethodBinding {
    const binding = candidate_env.lookupMethodBindingFromOwnerAndMethodEnvsConst(
        owner_env,
        owner_source_decl,
        method_source_env,
        method_ident,
    ) orelse return null;

    return .{
        .env = candidate_env,
        .is_this_module = candidate_env == self.cir,
        .binding = binding,
    };
}

/// Resolve the module env that declares a type from the type's content-based
/// origin identity. No name matching: two envs share an owner entry only when
/// their transitive module content is byte-identical, in which case they are
/// interchangeable as type owners by definition.
fn ownerEnvForOriginModule(
    self: *const Self,
    origin_module: base.ModuleIdentity.Idx,
    source_decl: ?u32,
    origin_is_builtin: bool,
    context: []const u8,
) struct { *const ModuleEnv, bool } {
    if (origin_is_builtin) {
        return self.builtinOwnerEnvForSourceDecl(source_decl, context);
    }

    const origin_hash = self.cir.moduleIdentityHash(origin_module);
    const owner_source_decl = nonBuiltinOwnerSourceDecl(source_decl, context, self.cir.moduleIdentityDisplayText(origin_module));

    if (self.owner_envs_by_identity.get(origin_hash.*)) |owner| {
        if (owner.env.module_role != .builtin or owner.is_this_module) {
            debugAssertOwnerEnvSourceDecl(owner.env, owner_source_decl, context);
            return .{ owner.env, owner.is_this_module };
        }
    }

    if (builtin.mode == .Debug) {
        std.debug.panic(
            "type checker invariant violated: unable to find module environment for {s} owner from module {s}, source_decl={d}, origin_is_builtin={}",
            .{ context, self.cir.moduleIdentityDisplayText(origin_module), owner_source_decl, origin_is_builtin },
        );
    }
    unreachable;
}

fn debugAssertOwnerEnvSourceDecl(candidate: *const ModuleEnv, source_decl: u32, context: []const u8) void {
    if (builtin.mode != .Debug) return;
    if (ownerModuleEnvSourceDeclMatches(candidate, source_decl)) return;
    std.debug.panic(
        "type checker invariant violated: {s} owner resolved by content identity to module '{s}' whose node {d} is not a type declaration",
        .{ context, candidate.module_name, source_decl },
    );
}

fn nonBuiltinOwnerSourceDecl(source_decl: ?u32, context: []const u8, origin_text: []const u8) u32 {
    if (source_decl) |raw_decl| return raw_decl;
    if (builtin.mode == .Debug) {
        std.debug.panic(
            "type checker invariant violated: {s} owner {s} has no source declaration",
            .{ context, origin_text },
        );
    }
    unreachable;
}

fn builtinOwnerEnvForSourceDecl(
    self: *const Self,
    source_decl: ?u32,
    context: []const u8,
) struct { *const ModuleEnv, bool } {
    if (source_decl == null) {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "type checker invariant violated: {s} compiler-builtin owner has no source declaration",
                .{context},
            );
        }
        unreachable;
    }

    if (self.maybeBuiltinOwnerEnvForSourceDecl(source_decl.?)) |owner| return .{ owner.env, owner.is_this_module };

    if (builtin.mode == .Debug) {
        std.debug.panic(
            "type checker invariant violated: unable to find compiler-builtin module environment for {s} owner",
            .{context},
        );
    }
    unreachable;
}

fn maybeBuiltinOwnerEnvForSourceDecl(
    self: *const Self,
    source_decl: u32,
) ?OwnerEnvCandidate {
    if (self.cir.module_role == .builtin and ownerModuleEnvSourceDeclMatches(self.cir, source_decl)) {
        return .{ .env = self.cir, .is_this_module = true };
    }

    if (self.builtin_ctx.builtin_module) |builtin_env| {
        if (ownerModuleEnvSourceDeclMatches(builtin_env, source_decl)) return .{ .env = builtin_env, .is_this_module = false };
    }

    for (self.imported_modules) |imported_env| {
        if (imported_env.module_role != .builtin) continue;
        if (ownerModuleEnvSourceDeclMatches(imported_env, source_decl)) return .{ .env = imported_env, .is_this_module = false };
    }
    for (self.owner_modules) |owner_env| {
        if (owner_env.module_role != .builtin) continue;
        if (ownerModuleEnvSourceDeclMatches(owner_env, source_decl)) return .{ .env = owner_env, .is_this_module = false };
    }

    return null;
}

fn ownerModuleEnvSourceDeclMatches(candidate: *const ModuleEnv, source_decl: u32) bool {
    if (source_decl >= candidate.store.nodes.len()) return false;

    const node: CIR.Node.Idx = @enumFromInt(source_decl);
    const node_tag = candidate.store.nodes.get(node).tag;
    if (node_tag != .statement_alias_decl and node_tag != .statement_nominal_decl) return false;
    return true;
}

fn methodVarFromOriginalEnv(
    self: *Self,
    original_env: *const ModuleEnv,
    is_this_module: bool,
    type_node_idx: CIR.Node.Idx,
    dispatcher_name: Ident.Idx,
    env: *Env,
    region: Region,
) Allocator.Error!ToInspectMethodVar {
    return .{
        .var_ = try self.methodTypeVarFromOriginalEnv(original_env, is_this_module, type_node_idx, env, region),
        .dispatcher_name = dispatcher_name,
    };
}

fn methodTypeVarFromOriginalEnv(
    self: *Self,
    original_env: *const ModuleEnv,
    is_this_module: bool,
    type_node_idx: CIR.Node.Idx,
    env: *Env,
    region: Region,
) Allocator.Error!Var {
    const def_var: Var = ModuleEnv.varFrom(type_node_idx);
    return if (is_this_module) blk: {
        break :blk try self.instantiateBindingVar(def_var, env, .use_last_var);
    } else blk: {
        const imported_scheme = try self.importedMethodSchemeFromSource(original_env, type_node_idx);
        break :blk try self.instantiateVar(imported_scheme, env, .{ .explicit = region });
    };
}

fn patternIdentInModule(module_env: *const ModuleEnv, def_idx: CIR.Def.Idx) ?Ident.Idx {
    const def = module_env.store.getDef(def_idx);
    const pattern = module_env.store.getPattern(def.pattern);
    return switch (pattern) {
        .assign => |assign| assign.ident,
        .as => |as_pattern| as_pattern.ident,
        .applied_tag,
        .nominal,
        .nominal_external,
        .record_destructure,
        .list,
        .tuple,
        .num_literal,
        .small_dec_literal,
        .dec_literal,
        .frac_f32_literal,
        .frac_f64_literal,
        .num_from_numeral_literal,
        .str_literal,
        .str_interpolation,
        .underscore,
        .runtime_error,
        => null,
    };
}

fn generatedDerivedMethodDef(module_env: *const ModuleEnv, def_idx: CIR.Def.Idx) bool {
    const def = module_env.store.getDef(def_idx);
    return module_env.store.getExpr(def.expr) == .e_derived_method;
}

/// A declaration that carries a type annotation and names no value. Builtin.roc
/// writes its compiler-owned intrinsic wrappers this way and post-check lowering
/// supplies their bodies, so those do name a value. A platform package's hosted
/// declarations reach checking as `e_hosted_lambda`, which this never sees;
/// `Coordinator.enable_hosted_transform` selects that rewrite and every entry
/// point that compiles a platform sets it, so a hosted declaration is never an
/// annotation without a body by the time checking runs. Every other annotation
/// without a body has nothing to evaluate.
fn annotationOnlyValueDef(module_env: *const ModuleEnv, def_idx: CIR.Def.Idx) bool {
    const def = module_env.store.getDef(def_idx);
    const expr = module_env.store.getExpr(def.expr);
    if (expr != .e_anno_only) return false;
    return !can.BuiltinLowLevel.isBuiltinModule(module_env) or
        !can.BuiltinLowLevel.isIntrinsicAnnotation(module_env, expr.e_anno_only.ident);
}

fn isExprNodeTag(tag: CIR.Node.Tag) bool {
    return Ident.textStartsWith(@tagName(tag), "expr_");
}

const AnnoVars = struct {
    anno_var: Var,
    anno_var_backup: Var,
    context: problem.Context,
};

/// Check if an expression represents a function definition that should be generalized.
/// This includes lambdas and function declarations (even those without bodies).
/// Returns true if the expression is a function definition: a closure wrapping
/// a lambda, a bare lambda, an annotation-only signature, or a hosted lambda.
/// Used for both generalization (value restriction) and cycle detection (deferred
/// generalization only applies to function defs).
fn isFunctionDef(store: *const CIR.NodeStore, expr: CIR.Expr) bool {
    if (expr == .e_closure) {
        std.debug.assert(store.getExpr(expr.e_closure.lambda_idx) == .e_lambda);
        return true;
    }
    return expr == .e_lambda or
        expr == .e_anno_only or
        expr == .e_derived_method or
        expr == .e_hosted_lambda;
}

fn exprDefinesMethod(self: *const Self, expr_idx: CIR.Expr.Idx) bool {
    for (self.cir.method_defs.entries.items) |entry| {
        if (self.cir.store.getDef(entry.value.def_idx).expr == expr_idx) return true;
    }
    return false;
}

/// Should this expression generalize in its current binding context—i.e. push
/// a rank so the generalizer can quantify its free vars? Three independent paths
/// qualify; they are checked in order so the annotation scan runs only when the
/// cheaper structural checks miss:
///
///   - **A function def.** Generalized at the inner lambda level only, not the
///     outer `e_closure` wrapper (which delegates to `e_lambda`'s own checkExpr),
///     and not a direct call argument—those are consumed immediately, and
///     generalizing one lets its vars escape into the enclosing value.
///   - **A value alias**—a binding whose RHS is a bare reference to an already-
///     generalized scheme (e.g. `shorthand = FooBar.myfunc`). The reference is
///     non-expansive: it does no work and can hide no `dbg`/`expect`, so it raises
///     none of the duplicate-work/effect concerns that restrict generalization to
///     syntactic functions. The referenced scheme is a generalized function or
///     annotated value (numeric literals use the separate defaulting path), never
///     a bare number or tag union. Restricted to binding-RHS position so bare
///     lookups in arbitrary subexpressions aren't generalized out from under their
///     surrounding context.
///   - **An annotated value binding** whose annotation introduces a free type var
///     (see `isGeneralizableValueBinding`). The rank push lets the generalizer
///     quantify exactly the generalizable vars—with none (e.g. a concrete
///     annotation) the generalize call is a no-op and the value stays monomorphic.
fn shouldGeneralize(
    self: *const Self,
    expr: CIR.Expr,
    annotation: ?CIR.Annotation.Idx,
    is_binding_rhs: bool,
    is_call_arg: bool,
) bool {
    if (isFunctionDef(&self.cir.store, expr) and expr != .e_closure and !is_call_arg) return true;
    if (is_binding_rhs and (expr == .e_lookup_local or expr == .e_lookup_external)) return true;
    return self.isGeneralizableValueBinding(annotation, is_binding_rhs);
}

/// True when a value binding generalizes to its annotated scheme: it sits in
/// binding-RHS position (only a binding's own right-hand side qualifies; a call
/// argument never generalizes on its own) and has an annotation introducing a
/// type variable. The polymorphic annotation is the opt-in, honored regardless
/// of whether the RHS does work (an expansive definition pays per-specialization—
/// the cost the author chose by writing the scheme).
fn isGeneralizableValueBinding(
    self: *const Self,
    annotation: ?CIR.Annotation.Idx,
    is_binding_rhs: bool,
) bool {
    if (!is_binding_rhs) return false;
    const annotation_idx = annotation orelse return false;
    return self.cir.store.getAnnotation(annotation_idx).mentions_type_var;
}

fn exprAlwaysCrashes(self: *const Self, expr_idx: CIR.Expr.Idx) bool {
    const expr = self.cir.store.getExpr(expr_idx);
    if (expr == .e_crash or expr == .e_ellipsis or expr == .e_expect_err or expr == .e_break) return true;
    if (expr == .e_run_low_level and expr.e_run_low_level.op == .crash) return true;
    if (expr == .e_block) return self.exprAlwaysCrashes(expr.e_block.final_expr);
    if (expr == .e_if) {
        const if_expr = expr.e_if;
        const branches = self.cir.store.sliceIfBranches(if_expr.branches);
        for (branches) |branch_idx| {
            const branch = self.cir.store.getIfBranch(branch_idx);
            if (!self.exprAlwaysCrashes(branch.body)) return false;
        }
        return self.exprAlwaysCrashes(if_expr.final_else);
    }
    return false;
}

fn exprIsAllCrashConditional(self: *const Self, expr_idx: CIR.Expr.Idx) bool {
    const expr = self.cir.store.getExpr(expr_idx);
    if (expr == .e_if) {
        const if_expr = expr.e_if;
        const branches = self.cir.store.sliceIfBranches(if_expr.branches);
        for (branches) |branch_idx| {
            const branch = self.cir.store.getIfBranch(branch_idx);
            if (!self.exprAlwaysCrashes(branch.body)) return false;
        }
        return self.exprAlwaysCrashes(if_expr.final_else);
    }
    if (expr == .e_block) return self.exprIsAllCrashConditional(expr.e_block.final_expr);
    return false;
}

fn exhaustiveBuiltinIdents(self: *const Self, open_cache: *exhaustive.NominalOpenCache) exhaustive.BuiltinIdents {
    return .{
        .idents = self.cir.getIdentStoreConst(),
        .open_cache = open_cache,
        .builtin_module = self.cir.idents.builtin_module,
        .u8_type = self.cir.idents.u8_type,
        .i8_type = self.cir.idents.i8_type,
        .u16_type = self.cir.idents.u16_type,
        .i16_type = self.cir.idents.i16_type,
        .u32_type = self.cir.idents.u32_type,
        .i32_type = self.cir.idents.i32_type,
        .u64_type = self.cir.idents.u64_type,
        .i64_type = self.cir.idents.i64_type,
        .u128_type = self.cir.idents.u128_type,
        .i128_type = self.cir.idents.i128_type,
        .f32_type = self.cir.idents.f32_type,
        .f64_type = self.cir.idents.f64_type,
        .dec_type = self.cir.idents.dec_type,
        .u8 = self.cir.idents.u8,
        .i8 = self.cir.idents.i8,
        .u16 = self.cir.idents.u16,
        .i16 = self.cir.idents.i16,
        .u32 = self.cir.idents.u32,
        .i32 = self.cir.idents.i32,
        .u64 = self.cir.idents.u64,
        .i64 = self.cir.idents.i64,
        .u128 = self.cir.idents.u128,
        .i128 = self.cir.idents.i128,
        .f32 = self.cir.idents.f32,
        .f64 = self.cir.idents.f64,
        .dec = self.cir.idents.dec,
    };
}

fn closeExhaustiveVars(
    self: *Self,
    result: exhaustive.CheckResult,
    env: *Env,
    region: Region,
) std.mem.Allocator.Error!void {
    for (result.ext_vars_to_close) |ext_var| {
        const empty_tu_var = try self.freshFromContent(.{ .structure = .empty_tag_union }, env, region);
        _ = try self.unify(ext_var, empty_tu_var, env);
    }

    for (result.payload_vars_to_close) |payload_var| {
        try self.closePayloadVarToEmpty(payload_var);
    }
}

fn appendUniqueIdent(gpa: std.mem.Allocator, out: *std.ArrayList(Ident.Idx), ident: Ident.Idx) Allocator.Error!void {
    for (out.items) |existing| {
        if (existing.eql(ident)) return;
    }
    try out.append(gpa, ident);
}

fn collectConstructedTagsForExpr(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    out: *std.ArrayList(Ident.Idx),
) Allocator.Error!bool {
    const expr = self.cir.store.getExpr(expr_idx);
    if (expr == .e_zero_argument_tag) {
        try appendUniqueIdent(self.gpa, out, expr.e_zero_argument_tag.name);
        return true;
    }
    if (expr == .e_tag) {
        try appendUniqueIdent(self.gpa, out, expr.e_tag.name);
        return true;
    }
    if (expr == .e_nominal) return self.collectConstructedTagsForExpr(expr.e_nominal.backing_expr, out);
    if (expr == .e_nominal_external) return self.collectConstructedTagsForExpr(expr.e_nominal_external.backing_expr, out);
    if (expr == .e_block) return self.collectConstructedTagsForExpr(expr.e_block.final_expr, out);
    if (expr == .e_if) {
        const if_expr = expr.e_if;
        const branches = self.cir.store.sliceIfBranches(if_expr.branches);
        for (branches) |branch_idx| {
            const branch = self.cir.store.getIfBranch(branch_idx);
            if (!try self.collectConstructedTagsForExpr(branch.body, out)) return false;
        }
        return self.collectConstructedTagsForExpr(if_expr.final_else, out);
    }
    if (expr == .e_match) {
        const match_expr = expr.e_match;
        const branches = self.cir.store.sliceMatchBranches(match_expr.branches);
        for (branches) |branch_idx| {
            const branch = self.cir.store.getMatchBranch(branch_idx);
            if (!try self.collectConstructedTagsForExpr(branch.value, out)) return false;
        }
        return true;
    }
    return false;
}

fn collectAbsentCtorPayloadBlockers(
    self: *Self,
    target_var: Var,
    constructed_tags: []const Ident.Idx,
    out: *std.ArrayList(Var),
) Allocator.Error!void {
    var arena = std.heap.ArenaAllocator.init(self.gpa);
    defer arena.deinit();

    var open_cache = exhaustive.NominalOpenCache.init(self.gpa);
    defer open_cache.deinit();

    try exhaustive.collectAbsentCtorPayloadBlockersForConstructedTags(
        arena.allocator(),
        self.types,
        self.exhaustiveBuiltinIdents(&open_cache),
        target_var,
        constructed_tags,
        out,
    );

    try self.backfillRegionsForAnalysisVars();
}

/// Exhaustiveness analysis opens nominal declarations, minting analysis-only
/// vars in the type store; keep the parallel regions array in sync with them.
fn backfillRegionsForAnalysisVars(self: *Self) Allocator.Error!void {
    const num_vars = self.types.len();
    if (num_vars == 0) return;
    try self.fillInRegionsThrough(@enumFromInt(num_vars - 1));
}

fn payloadVarCanResolveToEmpty(content: Content) bool {
    return switch (content) {
        .flex => |flex| flex.constraints.len() == 0 and if (flex.name) |name| name.attributes.ignored else true,
        .rigid => |rigid| rigid.constraints.len() == 0 and rigid.name.attributes.ignored,
        .alias, .field_presence, .structure, .err => false,
    };
}

fn closePayloadVarToEmpty(
    self: *Self,
    payload_var: Var,
) Allocator.Error!void {
    const resolved = self.types.resolveVar(payload_var);
    if (payloadVarCanResolveToEmpty(resolved.desc.content)) {
        try self.types.setVarToEmptyTagUnionDefault(resolved.var_);
    }
}

fn collectKnownEmptyPayloadVarsForExpr(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    target_var: Var,
    out: *std.ArrayList(Var),
) Allocator.Error!bool {
    self.collected_constructed_tags.clearRetainingCapacity();

    const known = try self.collectConstructedTagsForExpr(expr_idx, &self.collected_constructed_tags);
    if (!known) return false;
    if (self.collected_constructed_tags.items.len == 0) return true;

    try self.collectAbsentCtorPayloadBlockers(target_var, self.collected_constructed_tags.items, out);
    return true;
}

fn closeAbsentConstructedPayloadVars(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    target_var: Var,
) Allocator.Error!void {
    self.payload_vars_to_close.clearRetainingCapacity();

    _ = try self.collectKnownEmptyPayloadVarsForExpr(expr_idx, target_var, &self.payload_vars_to_close);

    for (self.payload_vars_to_close.items) |payload_var| {
        try self.closePayloadVarToEmpty(payload_var);
    }
}

fn pendingExhaustivenessMode(self: *const Self) ProblemStore.PendingStaticExhaustivenessMode {
    return self.exhaustiveness_context.pendingStaticMode();
}

fn checkDestructureExhaustiveness(
    self: *Self,
    pattern_idx: CIR.Pattern.Idx,
    value_expr_idx: CIR.Expr.Idx,
    value_var: Var,
    env: *Env,
    region: Region,
) std.mem.Allocator.Error!bool {
    if (!self.patternNeedsExhaustiveness(pattern_idx)) return false;

    self.known_empty_payload_vars_destructure.clearRetainingCapacity();
    const value_constructors_known = try self.collectKnownEmptyPayloadVarsForExpr(value_expr_idx, value_var, &self.known_empty_payload_vars_destructure);

    return try self.checkPatternExhaustiveness(
        pattern_idx,
        value_var,
        self.known_empty_payload_vars_destructure.items,
        value_constructors_known,
        env,
        region,
    );
}

/// Check one pattern in an irrefutable binding position against its settled
/// scrutinee type. Callers supply constructor facts only when a concrete value
/// expression proves them; function parameters and iterator items have no such
/// expression and must conservatively cover every inhabitant of their type.
fn checkPatternExhaustiveness(
    self: *Self,
    pattern_idx: CIR.Pattern.Idx,
    value_var: Var,
    known_empty_payload_vars: []const Var,
    value_constructors_known: bool,
    env: *Env,
    region: Region,
) std.mem.Allocator.Error!bool {
    if (!self.patternNeedsExhaustiveness(pattern_idx)) return false;

    // Same reasoning as the match-expression analysis site: the analysis and
    // its union-closing see sub-patterns through the scrutinee row, so the
    // pending record-destructure binds must be judged first.
    try self.judgeRecordDestructBinds(env);

    var open_cache = exhaustive.NominalOpenCache.init(self.gpa);
    defer open_cache.deinit();
    const result_or_err = exhaustive.checkDestructure(
        self.cir.gpa,
        self.types,
        self.cir,
        &self.cir.store,
        self.exhaustiveBuiltinIdents(&open_cache),
        pattern_idx,
        value_var,
        known_empty_payload_vars,
        value_constructors_known,
    );
    try self.backfillRegionsForAnalysisVars();
    const result = result_or_err catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.TypeError => return false,
    };
    defer result.deinit(self.cir.gpa);

    try self.closeExhaustiveVars(result, env, region);

    if (!result.is_exhaustive) {
        const value_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, value_var);
        const missing_patterns_start = self.problems.missing_patterns_backing.items.len;

        for (result.missing_patterns) |pattern| {
            const idx = try exhaustive.formatPattern(
                &self.problems.extra_strings_backing,
                &self.cir.common.idents,
                &self.cir.common.strings,
                pattern,
            );
            try self.problems.missing_patterns_backing.append(idx);
        }

        const missing_patterns_range = problem.MissingPatternsRange{
            .start = missing_patterns_start,
            .count = self.problems.missing_patterns_backing.items.len - missing_patterns_start,
        };

        const empirical_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(pattern_idx));
        try self.problems.appendPendingStaticExhaustiveness(self.gpa, .destructure, self.pendingExhaustivenessMode(), .{ .destructure_pattern = pattern_idx }, empirical_region, .{ .non_exhaustive_destructure = .{
            .pattern = pattern_idx,
            .value_snapshot = value_snapshot,
            .missing_patterns = missing_patterns_range,
        } });
        return true;
    }
    return false;
}

/// Run exhaustiveness analysis on every recorded lambda/function parameter
/// pattern. A parameter pattern position is irrefutable: there is no alternate
/// branch, so a refutable pattern there (e.g. `|[_, ..]|` or `|Ok(x)|`) that
/// does not cover every value of its type is a runtime `pattern match failed`
/// waiting to happen. Match expressions already get this analysis via
/// `checkMatchExpr`; this closes the same gap for parameter patterns, which were
/// previously type-checked but never checked for exhaustiveness.
fn reportNonExhaustiveLambdaParams(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    for (self.checked_lambda_params.items) |arg_span| {
        for (self.cir.store.slicePatterns(arg_span)) |pattern_idx| {
            try self.checkPatternExhaustivenessWithoutValue(pattern_idx, env);
        }
    }
}

/// Run exhaustiveness analysis on every source `for` pattern after iterator
/// dispatch has settled the item type. Iterator items are dynamic values, so
/// the iterable expression cannot supply constructor facts about them.
fn reportNonExhaustiveForPatterns(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    for (self.cir.for_loop_dispatch_plans.items.items) |plan| {
        const pattern_idx: CIR.Pattern.Idx = @enumFromInt(plan.pattern_idx);
        try self.checkPatternExhaustivenessWithoutValue(pattern_idx, env);
    }
}

/// Exhaustiveness check for a pattern without a concrete value expression.
/// The pattern's own type var is the scrutinee and there is no constructor
/// information to narrow the set of values it must cover.
fn checkPatternExhaustivenessWithoutValue(
    self: *Self,
    pattern_idx: CIR.Pattern.Idx,
    env: *Env,
) std.mem.Allocator.Error!void {
    if (!self.patternNeedsExhaustiveness(pattern_idx)) return;

    const value_var = ModuleEnv.varFrom(pattern_idx);
    const region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(pattern_idx));
    _ = try self.checkPatternExhaustiveness(pattern_idx, value_var, &.{}, false, env, region);
}

// stmts //

const BlockStatementsResult = struct {
    does_fx: bool,
    diverges: bool,
    blocks_later_hoists: bool,
};

/// Given a slice of stmts, type check each one
/// Returns whether any statement has effects and whether the block diverges (return/crash)
fn checkBlockStatements(self: *Self, statements: CIR.Statement.Span, env: *Env, _: Region, expected: Expected) std.mem.Allocator.Error!BlockStatementsResult {
    const trace = tracy.trace(@src());
    defer trace.end();

    var does_fx = false;
    var diverges = false;
    var blocks_later_hoists = false;
    var warn_unreachable = false;
    const base_statement_expected = expected.forStatement();
    for (0..statements.span.len) |stmt_offset| {
        const stmt_idx = self.cir.store.statementAt(statements, stmt_offset);
        const stmt = self.cir.store.getStatement(stmt_idx);
        const stmt_var = ModuleEnv.varFrom(stmt_idx);
        const stmt_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(stmt_idx));

        if (warn_unreachable) {
            _ = try self.problems.appendProblem(self.gpa, .{ .unreachable_code = .{
                .region = stmt_region,
            } });
        }

        try self.setVarRank(stmt_var, env);

        const statement_expected = if (blocks_later_hoists)
            base_statement_expected.suppressHoistSelection()
        else
            base_statement_expected;

        var statement_blocks_later_hoists = false;
        switch (stmt) {
            .s_decl => |decl_stmt| {
                const decl_expr_var: Var = ModuleEnv.varFrom(decl_stmt.expr);
                const decl_pattern_var: Var = ModuleEnv.varFrom(decl_stmt.pattern);

                const decl_is_fn = isFunctionDef(&self.cir.store, self.cir.store.getExpr(decl_stmt.expr));

                // An annotated local function's scheme is pre-declared from
                // its annotation so in-flight (recursive) references
                // instantiate it—the same rule as top-level defs; the
                // statement itself is checked on the ordinary path.
                // Conservatively limited to type-var-free annotations: a
                // type-var-mentioning local annotation can reference the
                // ENCLOSING def's rigids (`rigid_var_lookup`), and the
                // pre-pass generation would merge this annotation's nodes
                // into the enclosing generation's live classes before the
                // reset severs them.
                const decl_predeclared = decl_is_fn and decl_stmt.anno != null and
                    self.cir.store.getPattern(decl_stmt.pattern) == .assign and
                    !self.cir.store.getAnnotation(decl_stmt.anno.?).mentions_type_var and
                    !self.cir.store.getAnnotation(decl_stmt.anno.?).contains_underscore;
                if (decl_predeclared) {
                    const scheme_var = try self.predeclareAnnotationScheme(decl_stmt.anno.?, env);
                    try self.predeclared_local_scheme_vars.put(self.gpa, decl_stmt.pattern, scheme_var);
                }

                // A local function def is a binding group of one: its pattern
                // var lives in its own rank frame that generalizes after its
                // RHS, so a self-recursive def's monomorphic links (see the
                // local recursion branch in `e_lookup_local`) generalize with
                // the def instead of pinning it at the block's rank. Applied
                // to every function decl—a non-recursive one's frame is a
                // cheap no-op (its pattern is already an alias of the RHS's
                // generalized scheme by the time the frame closes), and
                // self-recursion cannot be detected syntactically up front
                // (a capture-free `f = |x| f(x)` has no self-capture).
                const decl_fn_frame = decl_is_fn and !decl_predeclared;
                if (decl_fn_frame) try env.var_pool.pushRank();

                const decl_pattern_ctx: PatternCtx = if (self.patternNeedsExhaustiveness(decl_stmt.pattern)) .match_branch else .bound;

                // Check the pattern
                try self.checkPattern(decl_stmt.pattern, decl_pattern_ctx, env);

                // Extract function name from the pattern (for better error messages)
                const saved_func_name = self.enclosing_func_name;
                self.enclosing_func_name = self.getPatternIdent(decl_stmt.pattern);
                defer self.enclosing_func_name = saved_func_name;

                // Check the annotation, if it exists
                const expectation = blk: {
                    if (decl_stmt.anno) |annotation_idx| {
                        break :blk statement_expected.withAnnotation(annotation_idx);
                    } else {
                        break :blk statement_expected;
                    }
                };

                // Register function defs as "currently processing" so recursive
                // references in their own body follow the binding-group
                // recursion rule (see the local recursion branch in
                // `e_lookup_local`). Only function defs can legitimately be
                // self-recursive; value defs (`x = x`) keep their existing
                // diagnostics.
                if (decl_is_fn) {
                    try self.local_processing_ptrns.put(self.gpa, decl_stmt.pattern, .{
                        .def_name = self.getPatternIdent(decl_stmt.pattern),
                        .pattern_idx = decl_stmt.pattern,
                    });
                }

                self.checking_binding_rhs = true;
                self.checking_binding_rhs_pattern = decl_stmt.pattern;
                const decl_expr_does_fx = try self.checkExpr(decl_stmt.expr, env, expectation);
                does_fx = decl_expr_does_fx or does_fx;
                statement_blocks_later_hoists = self.checkedExprBlocksLaterHoists(decl_stmt.expr, decl_expr_does_fx);
                try self.recordHoistBindingCandidate(decl_stmt.pattern, decl_stmt.expr, expectation.hoist_position);
                if (decl_stmt.anno == null and self.erroneous_value_exprs.contains(decl_stmt.expr)) {
                    try self.erroneous_value_patterns.put(self.gpa, decl_stmt.pattern, {});
                }
                try self.closeAbsentConstructedPayloadVars(decl_stmt.expr, decl_expr_var);
                if (decl_is_fn) {
                    try self.checkEffectfulFunctionName(decl_stmt.pattern, decl_stmt.expr);
                }

                // A record-destructure binding gets a dedicated context so the
                // report can suggest `field: _` or `..` when the pattern is too
                // narrow for the value (the pattern is the first/expected arg).
                const decl_pattern = self.cir.store.getPattern(decl_stmt.pattern);
                const decl_pattern_result = if (decl_pattern == .record_destructure)
                    try self.unifyInContext(decl_pattern_var, decl_expr_var, env, .record_destructure)
                else
                    try self.unify(decl_pattern_var, decl_expr_var, env);

                if (decl_pattern_result.isEstablished()) {
                    const needs_comptime_validation = try self.checkDestructureExhaustiveness(decl_stmt.pattern, decl_stmt.expr, decl_expr_var, env, stmt_region);
                    if (needs_comptime_validation) {
                        try self.recordHoistPatternValidationCandidate(decl_stmt.pattern, decl_stmt.expr, expectation.hoist_position);
                    }
                    try self.recordHoistPatternProvenance(decl_stmt.pattern, decl_stmt.expr, expectation.hoist_position);
                }
                try self.bindTypeSchemeVar(decl_expr_var, decl_pattern_var);
                if (self.predeclared_local_scheme_vars.get(decl_stmt.pattern)) |predeclared_scheme_var| {
                    try self.bindTypeSchemeVar(decl_expr_var, predeclared_scheme_var);
                }

                if (decl_fn_frame) {
                    // This statement's binding-group boundary: the pattern and
                    // any recursive links generalize together, then the frame
                    // pops so the statement's own var unifies with the
                    // finished scheme below. Destructure binders bind first
                    // so boundary defaulting sees them through the row (see
                    // `judgeRecordDestructBinds`).
                    try self.judgeRecordDestructBinds(env);
                    try self.defaultLiteralsAtGeneralizationBoundary(.{ .owner = decl_pattern_var, .interface = decl_pattern_var }, env);
                    try self.judgeFieldKindsAtBoundary(env);
                    try self.generalizer.generalize(self.gpa, &env.var_pool, env.rank());
                    try self.publishBindingScheme(decl_pattern_var);
                    try self.bindBindingSchemeVar(decl_pattern_var, decl_expr_var);
                    self.retireNonGeneralizedTypeSchemes(&.{.{ .owner = decl_pattern_var, .interface = decl_pattern_var }});
                    try self.retireStructurallyPublishedTypeSchemeRequirements(
                        &.{.{ .owner = decl_pattern_var, .interface = decl_pattern_var }},
                        env.rank(),
                    );
                    env.var_pool.popRank();
                }

                _ = try self.unify(stmt_var, decl_pattern_var, env);
                try self.bindTypeSchemeVar(decl_expr_var, stmt_var);

                if (decl_is_fn) {
                    _ = self.local_processing_ptrns.remove(decl_stmt.pattern);
                    _ = self.predeclared_local_scheme_vars.remove(decl_stmt.pattern);
                }

                // This statement is a binding root whose type may never be
                // reachable from the enclosing def's root type. Record it for
                // the settled-state occurs sweep after this statement's
                // constraints have fully determined the root graph.
                try self.local_binding_roots.append(self.gpa, decl_stmt.pattern);
            },
            .s_var => |var_stmt| {
                self.markCurrentHoistRuntimeDependency();
                const var_pattern_ctx: PatternCtx = if (self.patternNeedsExhaustiveness(var_stmt.pattern_idx)) .match_branch else .bound;

                // Check the pattern
                try self.checkPattern(var_stmt.pattern_idx, var_pattern_ctx, env);
                const var_pattern_var: Var = ModuleEnv.varFrom(var_stmt.pattern_idx);

                // Check the annotation, if it exists. A mutable `var` never
                // generalizes, so a type variable its annotation introduces can
                // never be bound; reject such an annotation and infer from the
                // body instead, so it doesn't cascade into confusing mismatches.
                const expectation = blk: {
                    if (var_stmt.anno) |annotation_idx| {
                        if (self.cir.store.getAnnotation(annotation_idx).introduces_type_var) {
                            _ = try self.problems.appendProblem(self.gpa, .{ .polymorphic_var_annotation = .{ .region = self.cir.store.getAnnotationRegion(annotation_idx) } });
                            break :blk statement_expected;
                        }
                        break :blk statement_expected.withAnnotation(annotation_idx);
                    } else {
                        break :blk statement_expected;
                    }
                };

                const var_expr_does_fx = try self.checkExpr(var_stmt.expr, env, expectation);
                does_fx = var_expr_does_fx or does_fx;
                statement_blocks_later_hoists = self.checkedExprBlocksLaterHoists(var_stmt.expr, var_expr_does_fx);
                self.discardHoistBindingCandidate(var_stmt.pattern_idx);
                if (var_stmt.anno == null and self.erroneous_value_exprs.contains(var_stmt.expr)) {
                    try self.erroneous_value_patterns.put(self.gpa, var_stmt.pattern_idx, {});
                }
                const var_expr: Var = ModuleEnv.varFrom(var_stmt.expr);
                try self.closeAbsentConstructedPayloadVars(var_stmt.expr, var_expr);

                const var_pattern_result = try self.unify(var_pattern_var, var_expr, env);
                _ = try self.unify(stmt_var, var_expr, env);

                if (var_pattern_result.isEstablished()) {
                    _ = try self.checkDestructureExhaustiveness(var_stmt.pattern_idx, var_stmt.expr, var_expr, env, stmt_region);
                }

                // `var` statements are binding roots too (they never
                // generalize, but their type can still be made cyclic).
                try self.local_binding_roots.append(self.gpa, var_stmt.pattern_idx);
            },
            .s_var_uninitialized => |var_stmt| {
                self.markCurrentHoistRuntimeDependency();
                const var_pattern_ctx: PatternCtx = if (self.patternNeedsExhaustiveness(var_stmt.pattern_idx)) .match_branch else .bound;

                try self.checkPattern(var_stmt.pattern_idx, var_pattern_ctx, env);
                const var_pattern_var: Var = ModuleEnv.varFrom(var_stmt.pattern_idx);

                // A mutable `var` never generalizes, so a type variable its
                // annotation introduces can never be bound. With no initializer
                // there is no body to infer from, so reject the annotation and
                // leave the pattern var free to be inferred from later
                // reassignments instead of cascading into confusing mismatches.
                if (var_stmt.anno) |annotation_idx| {
                    if (self.cir.store.getAnnotation(annotation_idx).introduces_type_var) {
                        _ = try self.problems.appendProblem(self.gpa, .{ .polymorphic_var_annotation = .{ .region = self.cir.store.getAnnotationRegion(annotation_idx) } });
                    } else {
                        try self.generateAnnotationType(annotation_idx, env);
                        _ = try self.unifyInContext(ModuleEnv.varFrom(annotation_idx), var_pattern_var, env, .type_annotation);
                    }
                }

                const empty_rec = try self.freshFromContent(.{ .structure = .empty_record }, env, stmt_region);
                _ = try self.unify(stmt_var, empty_rec, env);

                // Uninitialized `var` statements are binding roots too; their
                // type is determined by later reassignments rather than an
                // initializer, but it can still become cyclic.
                try self.local_binding_roots.append(self.gpa, var_stmt.pattern_idx);
            },
            .s_reassign => |reassign| {
                self.markCurrentHoistRuntimeDependency();
                // Reassignment patterns can mix existing mutable binders with
                // fresh local binders, e.g. `(word, $index) = pair`.
                // The pattern occurrence itself must therefore always be
                // checked here so its structural type and any fresh binders are
                // established explicitly before we unify it with the RHS.
                const reassign_pattern_ctx: PatternCtx = if (self.patternNeedsExhaustiveness(reassign.pattern_idx)) .match_branch else .bound;
                try self.checkPattern(reassign.pattern_idx, reassign_pattern_ctx, env);
                self.discardHoistBindingCandidate(reassign.pattern_idx);

                const reassign_pattern_var: Var = ModuleEnv.varFrom(reassign.pattern_idx);

                const reassign_expr_does_fx = try self.checkExpr(reassign.expr, env, statement_expected);
                does_fx = reassign_expr_does_fx or does_fx;
                statement_blocks_later_hoists = self.checkedExprBlocksLaterHoists(reassign.expr, reassign_expr_does_fx);
                const reassign_expr_var: Var = ModuleEnv.varFrom(reassign.expr);
                try self.closeAbsentConstructedPayloadVars(reassign.expr, reassign_expr_var);

                // Unify the pattern with the expression
                //
                // TODO: if there's a mismatch here, the region of the error is
                // the original assignment pattern, not the reassignment region
                const reassign_pattern_result = try self.unify(reassign_pattern_var, reassign_expr_var, env);

                _ = try self.unify(stmt_var, reassign_expr_var, env);

                if (reassign_pattern_result.isEstablished()) {
                    _ = try self.checkDestructureExhaustiveness(reassign.pattern_idx, reassign.expr, reassign_expr_var, env, stmt_region);
                }
            },
            .s_for => |for_stmt| {
                self.markCurrentHoistObservableEffect();
                statement_blocks_later_hoists = true;
                const for_region = self.cir.store.getStatementRegion(stmt_idx);
                const for_expected = if (blocks_later_hoists) base_statement_expected else statement_expected;
                does_fx = try self.checkIteratorForLoop(
                    ModuleEnv.nodeIdxFrom(stmt_idx),
                    null,
                    for_stmt.patt,
                    for_stmt.expr,
                    for_stmt.body,
                    env,
                    for_region,
                    for_expected,
                ) or does_fx;
                const empty_rec = try self.freshFromContent(.{ .structure = .empty_record }, env, for_region);
                _ = try self.unify(stmt_var, empty_rec, env);
            },
            .s_while => |while_stmt| {
                self.markCurrentHoistObservableEffect();
                statement_blocks_later_hoists = true;
                // Check the condition
                // while $count < 10 {
                //       ^^^^^^^^^^^
                does_fx = try self.checkExpr(while_stmt.cond, env, statement_expected) or does_fx;
                const cond_var: Var = ModuleEnv.varFrom(while_stmt.cond);
                const cond_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(while_stmt.cond));

                // Check that condition is Bool
                const bool_var = try self.freshBool(env, cond_region);
                _ = try self.unify(bool_var, cond_var, env);

                // Check the body
                // while $count < 10 {
                //     print!($count.toStr())  <<<<
                //     $count = $count + 1
                // }
                does_fx = try self.checkExpr(while_stmt.body, env, statement_expected.suppressHoistSelection()) or does_fx;
                const empty_rec = try self.freshFromContent(.{ .structure = .empty_record }, env, cond_region);
                _ = try self.unify(stmt_var, empty_rec, env);
            },
            .s_breakable_loop => |while_stmt| {
                self.markCurrentHoistObservableEffect();
                statement_blocks_later_hoists = true;
                does_fx = try self.checkExpr(while_stmt.cond, env, statement_expected) or does_fx;
                const cond_var: Var = ModuleEnv.varFrom(while_stmt.cond);
                const cond_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(while_stmt.cond));

                const bool_var = try self.freshBool(env, cond_region);
                _ = try self.unify(bool_var, cond_var, env);

                does_fx = try self.checkExpr(while_stmt.body, env, statement_expected.suppressHoistSelection()) or does_fx;
                const empty_rec = try self.freshFromContent(.{ .structure = .empty_record }, env, cond_region);
                _ = try self.unify(stmt_var, empty_rec, env);
            },
            .s_infinite_loop => |while_stmt| {
                self.markCurrentHoistObservableEffect();
                statement_blocks_later_hoists = true;
                does_fx = try self.checkExpr(while_stmt.cond, env, statement_expected) or does_fx;
                const cond_var: Var = ModuleEnv.varFrom(while_stmt.cond);
                const cond_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(while_stmt.cond));

                const bool_var = try self.freshBool(env, cond_region);
                _ = try self.unify(bool_var, cond_var, env);

                does_fx = try self.checkExpr(while_stmt.body, env, statement_expected.suppressHoistSelection()) or does_fx;
                try self.unifyWith(stmt_var, .{ .flex = Flex.init() }, env);
                diverges = true;
            },
            .s_expr => |expr| {
                const expr_does_fx = try self.checkExpr(expr.expr, env, statement_expected);
                does_fx = expr_does_fx or does_fx;
                statement_blocks_later_hoists = self.checkedExprBlocksLaterHoists(expr.expr, expr_does_fx);
                const expr_var: Var = ModuleEnv.varFrom(expr.expr);

                // Statements must evaluate to {}. Add a constraint to unify with empty record.
                // If unification fails, we get a nice type mismatch error explaining that
                // statement expressions must return {}.
                const empty_rec = try self.freshFromContent(.{ .structure = .empty_record }, env, stmt_region);
                const statement_result = try self.unifyInContext(empty_rec, expr_var, env, .statement_value);
                if (statement_result.isProblem()) {
                    try self.erroneous_value_exprs.put(self.gpa, expr.expr, {});
                }

                _ = try self.unify(stmt_var, expr_var, env);
                if (self.exprIsAllCrashConditional(expr.expr)) {
                    diverges = true;
                    warn_unreachable = true;
                }
            },
            .s_dbg => |expr| {
                self.markCurrentHoistObservableEffect();
                statement_blocks_later_hoists = true;
                does_fx = try self.checkExpr(expr.expr, env, statement_expected) or does_fx;
                const expr_var: Var = ModuleEnv.varFrom(expr.expr);

                _ = try self.unify(stmt_var, expr_var, env);
            },
            .s_expect => |expr_stmt| {
                self.markCurrentHoistObservableEffect();
                statement_blocks_later_hoists = true;
                const expect_does_fx = try self.checkExpectBody(expr_stmt.body, env, statement_expected, stmt_region);
                does_fx = expect_does_fx or does_fx;
                const body_var: Var = ModuleEnv.varFrom(expr_stmt.body);

                const bool_var = try self.freshBool(env, stmt_region);
                _ = try self.unifyInContext(bool_var, body_var, env, .expect);

                try self.unifyWith(stmt_var, .{ .structure = .empty_record }, env);
            },
            .s_crash => {
                statement_blocks_later_hoists = true;
                try self.unifyWith(stmt_var, .{ .flex = Flex.init() }, env);
                diverges = true;
            },
            .s_return => |ret| {
                self.markCurrentHoistObservableEffect();
                statement_blocks_later_hoists = true;
                // Type check the return expression
                const expected_return = self.expectedReturnResultFor(ret.lambda);
                const return_expected = expected.forReturnValue(expected_return);
                does_fx = try self.checkExpr(ret.expr, env, return_expected) or does_fx;

                if (expected_return) |annotated_return| {
                    try self.checkReturnRelation(annotated_return, ret.expr, .early_return, env);
                } else {
                    // Validate the lambda body type against the return value after the
                    // body is fully checked, but before the lambda generalizes.
                    try self.appendReturnConstraint(ret.lambda, ret.expr, .return_expr);
                }

                // A return statement's type should be a flex var so it can unify with any type.
                // This allows branches containing early returns to match any other branch type.
                try self.unifyWith(stmt_var, .{ .flex = Flex.init() }, env);
                diverges = true;
            },
            .s_nominal_decl, .s_alias_decl, .s_where_alias_decl, .s_type_anno => {
                // Local type declarations are preprocessed before type checking.
                // Avoid re-processing them inside block statements to prevent
                // duplicate unifications and spurious type mismatches.
            },
            .s_import => {
                // Imports are only valid at the top level; canonicalization reports the error.
                try self.markErroneous(stmt_var);
            },
            .s_type_var_alias => {
                // Type var alias introduces no new constraints during type checking
                // The alias is already registered in scope by canonicalization
                // The type var it references is a rigid var from the enclosing function
                try self.unifyWith(stmt_var, .{ .structure = .empty_record }, env);
            },
            .s_runtime_error => {
                try self.markErroneous(stmt_var);
            },
            .s_break => {
                statement_blocks_later_hoists = true;
                diverges = true;
            },
        }
        blocks_later_hoists = statement_blocks_later_hoists or blocks_later_hoists;
    }
    return .{
        .does_fx = does_fx,
        .diverges = diverges,
        .blocks_later_hoists = blocks_later_hoists,
    };
}

fn typeDispatchOwnerVar(self: *Self, stmt_idx: CIR.Statement.Idx) Var {
    const stmt = self.cir.store.getStatement(stmt_idx);
    return switch (stmt) {
        .s_type_var_alias => |alias| ModuleEnv.varFrom(alias.type_var_anno),
        .s_alias_decl => ModuleEnv.varFrom(stmt_idx),
        .s_decl,
        .s_var,
        .s_var_uninitialized,
        .s_reassign,
        .s_crash,
        .s_dbg,
        .s_expr,
        .s_expect,
        .s_for,
        .s_while,
        .s_infinite_loop,
        .s_breakable_loop,
        .s_break,
        .s_return,
        .s_import,
        .s_nominal_decl,
        .s_where_alias_decl,
        .s_type_anno,
        .s_runtime_error,
        => @panic("type dispatch owner statement was not a type-var alias or type alias"),
    };
}

fn enforceRecordBuilderMap2Return(
    self: *Self,
    func: Func,
    env: *Env,
    call_expr: CIR.Expr.Idx,
    func_name: ?Ident.Idx,
) std.mem.Allocator.Error!unifier.Result {
    if (func.args.len() != 3) return .unified;

    const return_payload_var = self.singleParameterWrapperPayload(func.ret) orelse return .unified;
    const mapper_var = self.types.getVarAt(func.args, 2);
    const mapper_func = self.functionTypeFromVar(mapper_var) orelse return .unified;

    return try self.unifyOwnedRelation(return_payload_var, mapper_func.ret, env, .{ .fn_call_arg = .{
        .fn_name = func_name,
        .call_expr = call_expr,
        .arg_index = 2,
        .num_args = 3,
        .arg_var = mapper_var,
    } }, .exact);
}

fn singleParameterWrapperPayload(self: *Self, wrapper_var: Var) ?Var {
    const resolved = self.types.resolveVar(wrapper_var);
    return switch (resolved.desc.content) {
        .alias => |alias| blk: {
            const args = self.types.sliceAliasArgs(alias);
            if (args.len != 1) break :blk null;
            break :blk args[0];
        },
        .structure => |flat| switch (flat) {
            .nominal_type => |nominal| blk: {
                const args = self.types.sliceNominalArgs(nominal);
                if (args.len != 1) break :blk null;
                break :blk args[0];
            },
            .record, .record_unbound, .tuple, .fn_pure, .fn_effectful, .fn_unbound, .empty_record, .tag_union, .empty_tag_union => null,
        },
        .flex, .rigid, .field_presence, .err => null,
    };
}

fn functionTypeFromVar(self: *Self, fn_var: Var) ?Func {
    var current = fn_var;
    var guard = types_mod.debug.IterationGuard.init("functionTypeFromVar");
    while (true) {
        guard.tick();
        const resolved = self.types.resolveVar(current);
        switch (resolved.desc.content) {
            .structure => |flat| switch (flat) {
                .fn_pure, .fn_effectful, .fn_unbound => |func| return func,
                .record, .record_unbound, .tuple, .nominal_type, .empty_record, .tag_union, .empty_tag_union => return null,
            },
            .alias => |alias| current = self.types.getAliasBackingVar(alias),
            .flex, .rigid, .field_presence, .err => return null,
        }
    }
}

fn tryArgsFromVar(self: *Self, try_var: Var) ?TryArgs {
    var current = try_var;
    var guard = types_mod.debug.IterationGuard.init("tryArgsFromVar");
    while (true) {
        guard.tick();
        const resolved = self.types.resolveVar(current);
        switch (resolved.desc.content) {
            .structure => |flat| switch (flat) {
                .nominal_type => |nominal| {
                    if (!self.nominalIsBuiltinTryType(nominal)) return null;
                    const args = self.types.sliceNominalArgs(nominal);
                    if (args.len != 2) return null;
                    return .{ .ok = args[0], .err = args[1] };
                },
                .record, .record_unbound, .tuple, .fn_pure, .fn_effectful, .fn_unbound, .empty_record, .tag_union, .empty_tag_union => return null,
            },
            .alias => |alias| current = self.types.getAliasBackingVar(alias),
            .flex, .rigid, .field_presence, .err => return null,
        }
    }
}

/// Whether a `?` condition is a direct call of a hosted function—the only
/// shape the hosted-try-question-widening rule (design.md "Hosted Try Question
/// Widening") applies to. The callee is statically resolved from the call's
/// function expression (the local or external lookup canonicalization
/// produced); dispatch calls and value-carried functions are never direct
/// hosted calls, so `?` on them gets no widening.
fn tryConditionIsDirectHostedCall(self: *Self, cond_idx: CIR.Expr.Idx) bool {
    const expr = self.cir.store.getExpr(cond_idx);
    if (expr != .e_call) return false;
    const call = expr.e_call;
    const callable_def = self.hoistedCallableDefForExpr(self.cir, call.func) orelse return false;
    const def = callable_def.module.store.getDef(callable_def.def);
    return callable_def.module.store.getExpr(def.expr) == .e_hosted_lambda;
}

/// The hosted-try-question-widening rule (design.md "Hosted Try Question
/// Widening"): `?` on a direct call of a hosted function widens the condition
/// to a fresh `Try` at the enclosing annotated return's error row when every
/// visible error in the callee's row is included in it. The redirect targets
/// the fresh `Try`, so the hosted callee's declared closed row—the host
/// ABI's shape—is what checking outputs for the callee itself. For every
/// other callee, a closed error row meeting an open annotated row stays a
/// type error (issue #9798's program is rejected by design); the caller gates
/// on `tryConditionIsDirectHostedCall`.
///
/// This is a typing mechanism, not the host ABI's protection. What a hosted
/// extern is emitted at is decided at the producer: Monotype lowering admits
/// only the hosted declaration's own type at an extern boundary and stops the
/// build otherwise (`requireHostedExternAtDeclaredAbi`,
/// src/postcheck/monotype/lower.zig, and design.md "Host Symbol ABI"). Widening
/// the condition here therefore changes which programs typecheck and which
/// caller-side adapter lowering generates; it cannot change the boundary. Judge
/// changes to this rewrite as type-semantics choices on that basis.
fn widenTryConditionForExpectedReturn(
    self: *Self,
    cond_var: Var,
    expected_return: Var,
    env: *Env,
    region: Region,
) std.mem.Allocator.Error!void {
    const actual_try = self.tryArgsFromVar(cond_var) orelse return;
    const expected_try = self.tryArgsFromVar(expected_return) orelse return;

    if (!try self.tryErrorRowNeedsUseSiteWidening(actual_try.err, expected_try.err)) {
        return;
    }

    // Ordinary tag-union unification rejects closed-vs-open rigid rows; this
    // use-site rewrite runs only after proving the callee's visible errors are
    // included in the expected row.
    const widened_try_var = try self.freshFromContent(
        try self.mkTryContent(actual_try.ok, expected_try.err),
        env,
        region,
    );
    const cond_root = self.types.resolveVar(cond_var).var_;
    if (cond_root != widened_try_var) {
        try self.types.dangerousSetVarRedirect(.hosted_try_question_widening, cond_root, widened_try_var);
    }
}

fn tryErrorRowNeedsUseSiteWidening(self: *Self, actual_err: Var, expected_err: Var) std.mem.Allocator.Error!bool {
    if (try self.probeCanUseAs(expected_err, actual_err)) {
        return false;
    }

    var visited_actual = std.AutoHashMap(Var, void).init(self.gpa);
    defer visited_actual.deinit();
    return try self.actualTagRowIsIncludedInExpected(actual_err, expected_err, &visited_actual);
}

fn probeCanUseAs(self: *Self, expected_var: Var, actual_var: Var) std.mem.Allocator.Error!bool {
    var probe = try self.beginProbe(null);
    defer probe.rollback();
    return try self.probeUnifyWithoutRecordingProblems(expected_var, actual_var);
}

fn actualTagRowIsIncludedInExpected(
    self: *Self,
    actual_var: Var,
    expected_var: Var,
    visited_actual: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    const actual_resolved = self.types.resolveVar(actual_var);
    if (visited_actual.contains(actual_resolved.var_)) return true;
    try visited_actual.put(actual_resolved.var_, {});

    switch (actual_resolved.desc.content) {
        .alias => |alias| return try self.actualTagRowIsIncludedInExpected(
            self.types.getAliasBackingVar(alias),
            expected_var,
            visited_actual,
        ),
        .structure => |flat| switch (flat) {
            .empty_tag_union => return true,
            .tag_union => |tag_union| {
                const tags = self.types.getTagsSlice(tag_union.tags);
                const names = tags.items(.name);
                const args_ranges = tags.items(.args);
                for (names, args_ranges) |name, args| {
                    const actual_tag = types_mod.Tag{ .name = name, .args = args };
                    if (!try self.expectedTagRowContainsTag(expected_var, actual_tag)) {
                        return false;
                    }
                }
                return try self.actualTagRowIsIncludedInExpected(tag_union.ext, expected_var, visited_actual);
            },
            .record, .record_unbound, .tuple, .nominal_type, .fn_pure, .fn_effectful, .fn_unbound, .empty_record => return false,
        },
        .err => return true,
        .flex, .rigid, .field_presence => return false,
    }
}

fn expectedTagRowContainsTag(
    self: *Self,
    expected_var: Var,
    actual_tag: types_mod.Tag,
) std.mem.Allocator.Error!bool {
    var visited_expected = std.AutoHashMap(Var, void).init(self.gpa);
    defer visited_expected.deinit();

    const expected_tag = try self.findVisibleTagInRow(expected_var, actual_tag.name, &visited_expected) orelse return false;
    return try self.tagsCanUseSamePayloads(expected_tag, actual_tag);
}

fn findVisibleTagInRow(
    self: *Self,
    row_var: Var,
    tag_name: Ident.Idx,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!?types_mod.Tag {
    const row_resolved = self.types.resolveVar(row_var);
    if (visited.contains(row_resolved.var_)) return null;
    try visited.put(row_resolved.var_, {});

    switch (row_resolved.desc.content) {
        .alias => |alias| return try self.findVisibleTagInRow(
            self.types.getAliasBackingVar(alias),
            tag_name,
            visited,
        ),
        .structure => |flat| switch (flat) {
            .tag_union => |tag_union| {
                const tags = self.types.getTagsSlice(tag_union.tags);
                const names = tags.items(.name);
                const args_ranges = tags.items(.args);
                for (names, args_ranges) |name, args| {
                    if (name.eql(tag_name)) {
                        return types_mod.Tag{ .name = name, .args = args };
                    }
                }
                return try self.findVisibleTagInRow(tag_union.ext, tag_name, visited);
            },
            .empty_tag_union => return null,
            .record, .record_unbound, .tuple, .nominal_type, .fn_pure, .fn_effectful, .fn_unbound, .empty_record => return null,
        },
        .err, .flex, .rigid, .field_presence => return null,
    }
}

fn tagsCanUseSamePayloads(self: *Self, expected_tag: types_mod.Tag, actual_tag: types_mod.Tag) std.mem.Allocator.Error!bool {
    if (expected_tag.args.len() != actual_tag.args.len()) return false;

    var expected_args = self.types.iterVars(expected_tag.args);
    var actual_args = self.types.iterVars(actual_tag.args);
    while (expected_args.next()) |expected_arg| {
        const actual_arg = actual_args.next().?;
        if (!try self.probeCanUseAs(expected_arg, actual_arg)) {
            return false;
        }
    }
    return true;
}

// if-else //

/// Check the types for an if-else expr
fn checkIfElseExpr(
    self: *Self,
    if_expr_idx: CIR.Expr.Idx,
    expr_region: Region,
    env: *Env,
    if_: @FieldType(CIR.Expr, @tagName(.e_if)),
    expected: Expected,
    is_call_arg: bool,
    is_immediate_callee: bool,
) std.mem.Allocator.Error!bool {
    const trace = tracy.trace(@src());
    defer trace.end();
    const expected_branch_ret = expected.branch_result;
    const child_expected = expected.forStatement();

    // Accumulator for the meet of all compatible branch bodies. Branches fold
    // into this instead of into the shared `expected_ret`, which is unified
    // with the whole expr (and hence the accumulator) exactly once, at the
    // end. Seeded with an ORPHAN COPY of the expected type (never the shared
    // var itself): the accumulator is the meet of the branches AND the
    // annotation, so annotation-declared facts—e.g. an `optional` field
    // kind—constrain every branch as it folds in, while the pristine
    // `expected_ret` stays the untouched reference that step-(1) probes and
    // error reports compare against (design.md "Field Kinds (All-Dynamic
    // Optional Fields)").
    const branch_acc: ?Var = if (expected_branch_ret) |expected_ret|
        try self.instantiateVarOrphanFlexed(expected_ret, env, .use_last_var)
    else
        null;

    const branches = self.cir.store.sliceIfBranches(if_.branches);

    // Should never be 0
    std.debug.assert(branches.len > 0);

    // Get the first branch
    const first_branch_idx = branches[0];
    const first_branch = self.cir.store.getIfBranch(first_branch_idx);

    // Check the condition of the 1st branch
    var does_fx = try self.checkExpr(first_branch.cond, env, child_expected);
    const first_cond_var: Var = ModuleEnv.varFrom(first_branch.cond);
    const bool_var = try self.freshBool(env, expr_region);
    const first_cond_result = try self.unifyInContext(bool_var, first_cond_var, env, .if_condition);
    if (if_.warn_unused_branches and first_cond_result.isEstablished()) {
        try self.warnIfComptimeConditionalExpr(first_branch.cond, .if_condition, expected);
    }

    // Then we check the 1st branch's body
    does_fx = try self.checkExprInCallPosition(
        first_branch.body,
        env,
        expected.forBranchBody(),
        is_call_arg,
        is_immediate_callee,
    ) or does_fx;

    if (expected_branch_ret) |expected_ret| {
        const branch_ctx = problem.Context{ .if_branch = .{
            .branch_index = 0,
            .num_branches = @intCast(branches.len + 1),
            .is_else = false,
            .parent_if_expr = if_expr_idx,
            .last_if_branch = first_branch_idx,
        } };
        try self.checkBranchBodyAgainstExpected(first_branch.body, expected_ret, branch_acc.?, branch_ctx, env);
    }

    // The 1st branch's body is the type all other branches must match (when no expected type)
    const branch_var = @as(Var, ModuleEnv.varFrom(first_branch.body));

    // Total number of branches (including final else)
    const num_branches: u32 = @intCast(branches.len + 1);

    var last_if_branch = first_branch_idx;
    for (branches[1..], 1..) |branch_idx, cur_index| {
        const branch = self.cir.store.getIfBranch(branch_idx);

        // Check the branches condition
        does_fx = try self.checkExpr(branch.cond, env, child_expected.suppressHoistSelection()) or does_fx;
        const cond_var: Var = ModuleEnv.varFrom(branch.cond);
        const branch_bool_var = try self.freshBool(env, expr_region);
        const cond_result = try self.unifyInContext(branch_bool_var, cond_var, env, .if_condition);
        if (if_.warn_unused_branches and cond_result.isEstablished()) {
            try self.warnIfComptimeConditionalExpr(branch.cond, .if_condition, expected);
        }

        // Check the branch body
        does_fx = try self.checkExprInCallPosition(
            branch.body,
            env,
            expected.forBranchBody(),
            is_call_arg,
            is_immediate_callee,
        ) or does_fx;

        // Check against expected return type BEFORE pairwise unification
        if (expected_branch_ret) |expected_ret| {
            const branch_ctx = problem.Context{ .if_branch = .{
                .branch_index = @intCast(cur_index),
                .num_branches = num_branches,
                .is_else = false,
                .parent_if_expr = if_expr_idx,
                .last_if_branch = last_if_branch,
            } };
            try self.checkBranchBodyAgainstExpected(branch.body, expected_ret, branch_acc.?, branch_ctx, env);
        } else {
            const body_var: Var = ModuleEnv.varFrom(branch.body);
            const body_result = try self.unifyInContext(branch_var, body_var, env, .{ .if_branch = .{
                .branch_index = @intCast(cur_index),
                .num_branches = num_branches,
                .is_else = false,
                .parent_if_expr = if_expr_idx,
                .last_if_branch = last_if_branch,
            } });

            if (!body_result.isAccepted()) {
                // Check remaining branches to catch their individual errors
                for (branches[cur_index + 1 ..]) |remaining_branch_idx| {
                    const remaining_branch = self.cir.store.getIfBranch(remaining_branch_idx);

                    does_fx = try self.checkExpr(remaining_branch.cond, env, child_expected.suppressHoistSelection()) or does_fx;
                    const remaining_cond_var: Var = ModuleEnv.varFrom(remaining_branch.cond);

                    const fresh_bool = try self.freshBool(env, expr_region);
                    const remaining_cond_result = try self.unifyInContext(fresh_bool, remaining_cond_var, env, .if_condition);
                    if (if_.warn_unused_branches and remaining_cond_result.isEstablished()) {
                        try self.warnIfComptimeConditionalExpr(remaining_branch.cond, .if_condition, expected);
                    }

                    does_fx = try self.checkExprInCallPosition(
                        remaining_branch.body,
                        env,
                        expected.forBranchBody(),
                        is_call_arg,
                        is_immediate_callee,
                    ) or does_fx;
                    try self.markErroneous(ModuleEnv.varFrom(remaining_branch.body));
                }

                // Break to avoid cascading errors
                break;
            }
        }

        last_if_branch = branch_idx;
    }

    // Check the final else
    does_fx = try self.checkExprInCallPosition(
        if_.final_else,
        env,
        expected.forBranchBody(),
        is_call_arg,
        is_immediate_callee,
    ) or does_fx;

    // Check final else against expected return type before pairwise unification
    if (expected_branch_ret) |expected_ret| {
        const branch_ctx = problem.Context{ .if_branch = .{
            .branch_index = num_branches - 1,
            .num_branches = num_branches,
            .is_else = true,
            .parent_if_expr = if_expr_idx,
            .last_if_branch = last_if_branch,
        } };
        try self.checkBranchBodyAgainstExpected(if_.final_else, expected_ret, branch_acc.?, branch_ctx, env);
        const if_expr_var: Var = ModuleEnv.varFrom(if_expr_idx);
        // Tie the whole expr to the accumulated branch meet, then to the shared
        // expected return type. This is the ONLY place `expected_ret` is merged
        // for the if-expr, and it runs in the load-bearing `(expr, expected)`
        // operand order so `expected_ret` survives as the union-find root (see
        // `store.union_`): flipping it ties recursive type parameters off to
        // duplicate rigids of the same name, which then fail to unify.
        _ = try self.unify(if_expr_var, branch_acc.?, env);
        _ = try self.unify(if_expr_var, expected_ret, env);
    } else {
        const final_else_var: Var = ModuleEnv.varFrom(if_.final_else);
        _ = try self.unifyInContext(branch_var, final_else_var, env, .{ .if_branch = .{
            .branch_index = num_branches - 1,
            .num_branches = num_branches,
            .is_else = true,
            .parent_if_expr = if_expr_idx,
            .last_if_branch = last_if_branch,
        } });

        // Set the entire expr's type to be the type of the branch
        const if_expr_var: Var = ModuleEnv.varFrom(if_expr_idx);
        _ = try self.unify(if_expr_var, branch_var, env);
    }

    return does_fx;
}

// match //

/// Check the types for a match expr
fn checkMatchExpr(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    env: *Env,
    match: CIR.Expr.Match,
    expected: Expected,
    is_call_arg: bool,
    is_immediate_callee: bool,
) Allocator.Error!bool {
    const trace = tracy.trace(@src());
    defer trace.end();

    const expr_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(expr_idx));
    const expected_branch_ret = expected.branch_result;
    const child_expected = expected.forStatement();

    // Accumulator for the meet of all compatible branch bodies. Branches fold
    // into this instead of into the shared `expected_ret`, which is unified
    // with the whole expr (and hence the accumulator) exactly once, at the
    // end. Seeded with an ORPHAN COPY of the expected type (never the shared
    // var itself): the accumulator is the meet of the branches AND the
    // annotation, so annotation-declared facts—e.g. an `optional` field
    // kind—constrain every branch as it folds in, while the pristine
    // `expected_ret` stays the untouched reference that step-(1) probes and
    // error reports compare against (design.md "Field Kinds (All-Dynamic
    // Optional Fields)").
    const branch_acc: ?Var = if (expected_branch_ret) |expected_ret|
        try self.instantiateVarOrphanFlexed(expected_ret, env, .use_last_var)
    else
        null;

    // Check the match's condition
    var does_fx = try self.checkExpr(match.cond, env, child_expected);
    const cond_var = ModuleEnv.varFrom(match.cond);
    const cond_always_crashes = self.exprAlwaysCrashes(match.cond);
    if (!match.is_try_suffix) {
        try self.closeAbsentConstructedPayloadVars(match.cond, cond_var);
    }

    // Assert we have at least 1 branch
    std.debug.assert(match.branches.span.len > 0);

    // Get slice of branches
    const branch_idxs = self.cir.store.sliceMatchBranches(match.branches);
    const match_hoist_owner = self.currentHoistFrameIndexForExpr(expr_idx);

    // A rejected condition is replaced with a runtime error after solving. The
    // match must become the same explicit executable boundary; otherwise later
    // lowering would try to build a decision tree whose scrutinee deliberately
    // has no checked type.
    var had_type_error = self.erroneous_value_exprs.contains(match.cond);

    // For matches desugared from `?` operator, verify the condition unifies with Try type FIRST.
    // If it doesn't, report the specific error and skip pattern checking to avoid confusing errors.
    var has_invalid_try = false;
    if (match.is_try_suffix) {
        // Get the actual Try type from builtins and instantiate it with fresh type vars
        const try_type_var = ModuleEnv.varFrom(self.builtin_ctx.try_stmt);
        const copied_try_var = if (self.builtin_ctx.builtin_module) |builtin_env|
            try self.copyVar(try_type_var, builtin_env, Region.zero())
        else
            try_type_var;
        const try_var = try self.instantiateVar(copied_try_var, env, .use_root_instantiated);

        // Unify the condition with Try type
        const try_result = try self.unifyInContext(try_var, cond_var, env, .{ .try_operator_expr = .{
            .expr = match.cond,
        } });
        if (!try_result.isEstablished()) {
            has_invalid_try = true;
            had_type_error = true;
        } else if (self.currentExpectedReturnResult()) |expected_return| {
            if (self.tryConditionIsDirectHostedCall(match.cond)) {
                try self.widenTryConditionForExpectedReturn(cond_var, expected_return, env, expr_region);
            }
        }
    }
    if (!match.is_try_suffix and !match.skip_exhaustiveness) {
        try self.warnIfComptimeConditionalExpr(match.cond, .match_scrutinee, expected);
    }

    // Every branch pattern describes the same scrutinee value, so the patterns
    // must stay mutually consistent. That relation normally travels through
    // `cond_var`. An already-erroneous scrutinee cannot carry it: unification
    // against `.err` is accepted without merging, so each pattern would be
    // solved in isolation and the bindings they share would only collide later,
    // in the branch bodies, far from the pattern that disagrees. Tie the
    // patterns to a class of their own instead. The first disagreement poisons
    // that class to `.err`, so later patterns short-circuit exactly as they do
    // when the scrutinee itself carries the relation.
    const ptrn_target_var = if (self.types.resolveVar(cond_var).desc.content == .err)
        try self.fresh(env, expr_region)
    else
        cond_var;

    // Manually check the 1st branch
    // The type of the branch's body becomes the var other branch bodies must unify
    // against.
    const first_branch_idx = branch_idxs[0];
    const first_branch = self.cir.store.getMatchBranch(first_branch_idx);
    var val_var: Var = undefined;

    {
        const branch_hoist_scope = self.beginHoistLexicalScope();
        defer self.endHoistLexicalScope(branch_hoist_scope);

        const first_branch_ptrn_idxs = self.cir.store.sliceMatchBranchPatterns(first_branch.patterns);

        // Check each of the first branch's patterns and unify it with the
        // condition type. (A failed unify poisons the target to .err, so subsequent
        // pattern unifications short-circuit rather than cascading.)
        for (first_branch_ptrn_idxs, 0..) |branch_ptrn_idx, cur_ptrn_index| {
            const branch_ptrn = self.cir.store.getMatchBranchPattern(branch_ptrn_idx);
            try self.checkPattern(branch_ptrn.pattern, .match_branch, env);

            if (!cond_always_crashes) {
                const branch_ptrn_var = ModuleEnv.varFrom(branch_ptrn.pattern);
                const ptrn_result = try self.unifyInContext(ptrn_target_var, branch_ptrn_var, env, .{ .match_pattern = .{
                    .branch_index = 0,
                    .pattern_index = @intCast(cur_ptrn_index),
                    .num_branches = @intCast(match.branches.span.len),
                    .num_patterns = @intCast(first_branch_ptrn_idxs.len),
                    .match_expr = expr_idx,
                } });
                if (!ptrn_result.isEstablished()) had_type_error = true;
            }
        }

        if (try self.unifyMatchAltPatternBindings(first_branch_ptrn_idxs, 0, @intCast(match.branches.span.len), expr_idx, env)) {
            had_type_error = true;
        }

        if (!had_type_error) {
            try self.recordHoistSingleBranchMatchPatternProvenance(match, first_branch, first_branch_ptrn_idxs, child_expected.hoist_position);
        }
        try self.recordHoistMatchBranchContextualBindings(first_branch_ptrn_idxs, match_hoist_owner);

        // Check guard if present
        if (first_branch.guard) |guard_idx| {
            does_fx = try self.checkExpr(guard_idx, env, child_expected.suppressHoistSelection()) or does_fx;
            const guard_var = ModuleEnv.varFrom(guard_idx);
            const guard_bool_var = try self.freshBool(env, expr_region);
            const guard_result = try self.unifyInContext(guard_bool_var, guard_var, env, .if_condition);
            if (!guard_result.isEstablished()) had_type_error = true;
            if (!match.skip_exhaustiveness and guard_result.isEstablished()) {
                try self.warnIfComptimeConditionalExpr(guard_idx, .if_guard, expected);
            }
        }

        // Check the first branch's value, then use that at the branch_var
        does_fx = try self.checkExprInCallPosition(
            first_branch.value,
            env,
            expected.forBranchBody(),
            is_call_arg,
            is_immediate_callee,
        ) or does_fx;
        val_var = ModuleEnv.varFrom(first_branch.value);

        // Check first branch body against expected return type
        if (expected_branch_ret) |expected_ret| {
            const branch_ctx = problem.Context{ .match_branch = .{
                .branch_index = 0,
                .num_branches = @intCast(match.branches.span.len),
                .match_expr = expr_idx,
            } };
            try self.checkBranchBodyAgainstExpected(first_branch.value, expected_ret, branch_acc.?, branch_ctx, env);
        }
    }

    // Then iterate over the rest of the branches
    for (branch_idxs[1..], 1..) |branch_idx, branch_cur_index| {
        const branch = self.cir.store.getMatchBranch(branch_idx);
        const branch_hoist_scope = self.beginHoistLexicalScope();
        defer self.endHoistLexicalScope(branch_hoist_scope);

        // First, check the patterns of this branch (skip if invalid try to avoid confusing errors)
        const branch_ptrn_idxs = self.cir.store.sliceMatchBranchPatterns(branch.patterns);
        for (branch_ptrn_idxs, 0..) |branch_ptrn_idx, cur_ptrn_index| {
            // Check the pattern's sub types
            const branch_ptrn = self.cir.store.getMatchBranchPattern(branch_ptrn_idx);
            try self.checkPattern(branch_ptrn.pattern, .match_branch, env);

            // Check the pattern against the cond
            if (!cond_always_crashes) {
                const branch_ptrn_var = ModuleEnv.varFrom(branch_ptrn.pattern);
                const ptrn_result = try self.unifyInContext(ptrn_target_var, branch_ptrn_var, env, .{ .match_pattern = .{
                    .branch_index = @intCast(branch_cur_index),
                    .pattern_index = @intCast(cur_ptrn_index),
                    .num_branches = @intCast(match.branches.span.len),
                    .num_patterns = @intCast(branch_ptrn_idxs.len),
                    .match_expr = expr_idx,
                } });
                if (!ptrn_result.isEstablished()) had_type_error = true;
            }
        }

        if (try self.unifyMatchAltPatternBindings(branch_ptrn_idxs, @intCast(branch_cur_index), @intCast(match.branches.span.len), expr_idx, env)) {
            had_type_error = true;
        }
        try self.recordHoistMatchBranchContextualBindings(branch_ptrn_idxs, match_hoist_owner);

        // Check guard if present
        if (branch.guard) |guard_idx| {
            does_fx = try self.checkExpr(guard_idx, env, child_expected.suppressHoistSelection()) or does_fx;
            const guard_var = ModuleEnv.varFrom(guard_idx);
            const branch_guard_bool_var = try self.freshBool(env, expr_region);
            const guard_result = try self.unifyInContext(branch_guard_bool_var, guard_var, env, .if_condition);
            if (!guard_result.isEstablished()) had_type_error = true;
            if (!match.skip_exhaustiveness and guard_result.isEstablished()) {
                try self.warnIfComptimeConditionalExpr(guard_idx, .if_guard, expected);
            }
        }

        // Then, check the body
        does_fx = try self.checkExprInCallPosition(
            branch.value,
            env,
            expected.forBranchBody(),
            is_call_arg,
            is_immediate_callee,
        ) or does_fx;

        // Check branch body against expected return type BEFORE pairwise unification.
        // Pairwise unification poisons ALL connected vars via union-find on failure,
        // making it impossible to distinguish correct from incorrect branches afterward.
        if (expected_branch_ret) |expected_ret| {
            const branch_ctx = problem.Context{ .match_branch = .{
                .branch_index = @intCast(branch_cur_index),
                .num_branches = @intCast(match.branches.span.len),
                .match_expr = expr_idx,
            } };
            try self.checkBranchBodyAgainstExpected(branch.value, expected_ret, branch_acc.?, branch_ctx, env);
        } else {
            const branch_result = try self.unifyInContext(val_var, ModuleEnv.varFrom(branch.value), env, .{ .match_branch = .{
                .branch_index = @intCast(branch_cur_index),
                .num_branches = @intCast(match.branches.span.len),
                .match_expr = expr_idx,
            } });

            if (!branch_result.isAccepted()) {
                had_type_error = true;
                // If there was a body mismatch, do not check other branches to stop
                // cascading errors. But still check each other branch's sub types
                for (branch_idxs[branch_cur_index + 1 ..], branch_cur_index + 1..) |other_branch_idx, other_branch_cur_index| {
                    const other_branch = self.cir.store.getMatchBranch(other_branch_idx);
                    const other_branch_hoist_scope = self.beginHoistLexicalScope();
                    defer self.endHoistLexicalScope(other_branch_hoist_scope);

                    // Still check the other patterns (skip if invalid try to avoid confusing errors)
                    const other_branch_ptrn_idxs = self.cir.store.sliceMatchBranchPatterns(other_branch.patterns);
                    for (other_branch_ptrn_idxs, 0..) |other_branch_ptrn_idx, other_cur_ptrn_index| {
                        // Check the pattern's sub types
                        const other_branch_ptrn = self.cir.store.getMatchBranchPattern(other_branch_ptrn_idx);
                        try self.checkPattern(other_branch_ptrn.pattern, .match_branch, env);

                        // Check the pattern against the cond
                        if (!cond_always_crashes) {
                            const other_branch_ptrn_var = ModuleEnv.varFrom(other_branch_ptrn.pattern);
                            _ = try self.unifyInContext(ptrn_target_var, other_branch_ptrn_var, env, .{ .match_pattern = .{
                                .branch_index = @intCast(other_branch_cur_index),
                                .pattern_index = @intCast(other_cur_ptrn_index),
                                .num_branches = @intCast(match.branches.span.len),
                                .num_patterns = @intCast(other_branch_ptrn_idxs.len),
                                .match_expr = expr_idx,
                            } });
                        }
                    }
                    try self.recordHoistMatchBranchContextualBindings(other_branch_ptrn_idxs, match_hoist_owner);

                    // Then check the other branch's exprs
                    does_fx = try self.checkExprInCallPosition(
                        other_branch.value,
                        env,
                        expected.forBranchBody(),
                        is_call_arg,
                        is_immediate_callee,
                    ) or does_fx;
                    try self.markErroneous(ModuleEnv.varFrom(other_branch.value));
                }

                // Then stop type checking for this branch
                break;
            }
        }
    }

    // Unify the root expr with the match value
    if (expected_branch_ret) |expected_ret| {
        // Tie the whole expr to the accumulated branch meet, then to the shared
        // expected return type. This is the ONLY place `expected_ret` is merged
        // for the match expr, and it runs in the load-bearing `(expr, expected)`
        // operand order so `expected_ret` survives as the union-find root (see
        // `store.union_`): flipping it ties recursive type parameters off to
        // duplicate rigids of the same name, which then fail to unify.
        _ = try self.unify(ModuleEnv.varFrom(expr_idx), branch_acc.?, env);
        _ = try self.unify(ModuleEnv.varFrom(expr_idx), expected_ret, env);
    } else {
        _ = try self.unify(ModuleEnv.varFrom(expr_idx), val_var, env);
    }

    // Perform exhaustiveness and redundancy checking
    // Only do this if there were no type errors - type errors can lead to invalid types
    // that confuse the exhaustiveness checker
    // Also skip if the condition type is an error type (can happen with complex inference)
    // Also skip if we already reported an invalid try operator error
    // Also skip if the condition explicitly diverges; no pattern is observed at runtime.
    const resolved_cond = self.types.resolveVar(cond_var);
    const cond_is_error = resolved_cond.desc.content == .err;

    if (!match.skip_exhaustiveness and !had_type_error and !cond_is_error and !has_invalid_try and !cond_always_crashes) {
        const match_region = self.getRegionAt(@enumFromInt(@intFromEnum(expr_idx)));

        // Exhaustiveness analysis (and its union-closing) walks the SCRUTINEE
        // type, so every record-destructure binder in the branch patterns must
        // already be bound through its row (the closure of a tag union inside
        // a destructured field is discovered via the field's value type).
        // Judge the pending destructure binds now—an analysis site is a
        // commitment point exactly like a generalization boundary (a
        // still-flex kind pins `required` here; see `judgeRecordDestructBinds`).
        try self.judgeRecordDestructBinds(env);

        self.known_empty_payload_vars_match.clearRetainingCapacity();
        const cond_constructors_known = try self.collectKnownEmptyPayloadVarsForExpr(match.cond, cond_var, &self.known_empty_payload_vars_match);

        var open_cache = exhaustive.NominalOpenCache.init(self.gpa);
        defer open_cache.deinit();
        const result_or_err = exhaustive.checkMatch(
            self.cir.gpa,
            self.types,
            self.cir,
            &self.cir.store,
            self.exhaustiveBuiltinIdents(&open_cache),
            match.branches,
            cond_var,
            match_region,
            self.known_empty_payload_vars_match.items,
            cond_constructors_known,
        );
        try self.backfillRegionsForAnalysisVars();
        const result = result_or_err catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.TypeError => {
                // Type error in pattern - exhaustiveness checking can't proceed
                // This is expected when there are polymorphic types or type mismatches
                // Don't report exhaustiveness errors in this case
                return does_fx;
            },
        };
        defer result.deinit(self.cir.gpa);

        try self.closeExhaustiveVars(result, env, match_region);

        // Report non-exhaustive match if any patterns are missing
        if (!result.is_exhaustive) {
            const condition_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, cond_var);

            // Format missing patterns and store in problems store for lifecycle management
            // Track the start position for the missing patterns range
            const missing_patterns_start = self.problems.missing_patterns_backing.items.len;

            for (result.missing_patterns) |pattern| {
                const idx = try exhaustive.formatPattern(&self.problems.extra_strings_backing, &self.cir.common.idents, &self.cir.common.strings, pattern);
                try self.problems.missing_patterns_backing.append(idx);
            }

            const missing_patterns_range = problem.MissingPatternsRange{
                .start = missing_patterns_start,
                .count = self.problems.missing_patterns_backing.items.len - missing_patterns_start,
            };

            try self.problems.appendPendingStaticExhaustiveness(self.gpa, .match, self.pendingExhaustivenessMode(), .{ .match_expr = expr_idx }, match_region, .{ .non_exhaustive_match = .{
                .match_expr = expr_idx,
                .condition_snapshot = condition_snapshot,
                .missing_patterns = missing_patterns_range,
            } });
        }

        // Report redundant patterns
        for (result.redundant_indices) |idx| {
            _ = try self.problems.appendProblem(self.gpa, .{ .redundant_pattern = .{
                .match_expr = expr_idx,
                .num_branches = @intCast(match.branches.span.len),
                .problem_branch_index = idx,
            } });
        }

        // Report unmatchable patterns (patterns on uninhabited types)
        for (result.unmatchable_indices) |idx| {
            _ = try self.problems.appendProblem(self.gpa, .{ .unmatchable_pattern = .{
                .match_expr = expr_idx,
                .num_branches = @intCast(match.branches.span.len),
                .problem_branch_index = idx,
            } });
        }
    }

    // A match whose pattern matrix, guard contract, or branch result failed to
    // type-check has no valid decision tree to lower. Preserve the diagnostic
    // and publish the match itself as the exact executable crash boundary;
    // independent expressions and functions remain fully compilable.
    if (had_type_error) {
        try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
    }

    return does_fx;
}

// unary minus //

/// Check the unary expr.
/// Desugars `-a` to `a.negate() : a -> a`,
fn checkUnaryMinusExpr(self: *Self, expr_idx: CIR.Expr.Idx, expr_var: Var, expr_region: Region, env: *Env, unary: CIR.Expr.UnaryMinus, expected: Expected) Allocator.Error!bool {
    const trace = tracy.trace(@src());
    defer trace.end();

    const child_expected = expected.forStatement();

    // Check the operand expression
    const does_fx = try self.checkExpr(unary.expr, env, child_expected);
    if (try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, &.{unary.expr})) return does_fx;

    // Get the not method + ret var
    // Here, we assert that the arg and ret of `not` are same type
    const not_method_name = self.cir.idents.negate;
    const not_arg_var = @as(Var, ModuleEnv.varFrom(unary.expr));
    const not_ret_var = not_arg_var;

    // Create the not static dispatch function on the not_arg + not_ret
    // This function attaches the dispatch fn to the not_arg
    try self.mkUnaryOp(not_arg_var, not_ret_var, not_method_name, env, expr_region, expr_idx);

    // The result type is the operand type (the desugaring is `a -> a`).
    _ = try self.unify(expr_var, not_ret_var, env);

    return does_fx;
}

// unary not //

/// Check the unary expr.
/// Desugars `!a` to `a.not() : a -> a`,
fn checkUnaryNotExpr(self: *Self, expr_idx: CIR.Expr.Idx, expr_var: Var, expr_region: Region, env: *Env, unary: CIR.Expr.UnaryNot, expected: Expected) Allocator.Error!bool {
    const trace = tracy.trace(@src());
    defer trace.end();

    const child_expected = expected.forStatement();

    // Check the operand expression
    const does_fx = try self.checkExpr(unary.expr, env, child_expected);
    if (try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, &.{unary.expr})) return does_fx;

    // Get the not method + ret var
    // Here, we assert that the arg and ret of `not` are same type
    const not_method_name = self.cir.idents.not;
    const not_arg_var = @as(Var, ModuleEnv.varFrom(unary.expr));
    const not_ret_var = not_arg_var;

    // Create the not static dispatch function on the not_arg + not_ret
    // This function attaches the dispatch fn to the not_arg
    try self.mkUnaryOp(not_arg_var, not_ret_var, not_method_name, env, expr_region, expr_idx);

    // The result type is the operand type (the desugaring is `a -> a`).
    _ = try self.unify(expr_var, not_ret_var, env);

    return does_fx;
}

// binop //

/// Check the types for a binary operation expression
fn checkBinopExpr(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    expr_var: Var,
    expr_region: Region,
    env: *Env,
    binop: CIR.Expr.Binop,
    expected: Expected,
) Allocator.Error!bool {
    const trace = tracy.trace(@src());
    defer trace.end();

    const lhs_var = @as(Var, ModuleEnv.varFrom(binop.lhs));
    const rhs_var = @as(Var, ModuleEnv.varFrom(binop.rhs));
    const child_expected = expected.forStatement();

    // Check operands first
    var does_fx = false;
    does_fx = try self.checkExpr(binop.lhs, env, child_expected) or does_fx;
    does_fx = try self.checkExpr(binop.rhs, env, child_expected) or does_fx;

    if (binop.op != .@"and" and binop.op != .@"or" and
        try self.retireCallLikeExprWithErroneousOperands(expr_idx, expr_var, &.{ binop.lhs, binop.rhs }))
    {
        return does_fx;
    }

    switch (binop.op) {
        .add, .sub, .mul, .div, .rem, .div_trunc => {
            const method_name =
                switch (binop.op) {
                    .add => self.cir.idents.plus,
                    .sub => self.cir.idents.minus,
                    .mul => self.cir.idents.times,
                    .div => self.cir.idents.div_by,
                    .div_trunc => self.cir.idents.div_trunc_by,
                    .rem => self.cir.idents.rem_by,
                    .lt,
                    .gt,
                    .le,
                    .ge,
                    .eq,
                    .ne,
                    .@"and",
                    .@"or",
                    .range_exclusive,
                    .range_inclusive,
                    => unreachable,
                };

            const lhs_is_numeric = self.isBuiltinNumericNominal(lhs_var);
            const rhs_is_numeric = self.isBuiltinNumericNominal(rhs_var);
            const lhs_is_from_numeral = self.varLiteralKind(lhs_var) == .numeral;
            const rhs_is_from_numeral = self.varLiteralKind(rhs_var) == .numeral;

            if (lhs_is_from_numeral and try self.reportDefinitelyInvalidNumericBinopOperand(rhs_var, expr_var, expr_idx, binop.op, .rhs, env, expr_region)) {
                return does_fx;
            }
            if (rhs_is_from_numeral and try self.reportDefinitelyInvalidNumericBinopOperand(lhs_var, expr_var, expr_idx, binop.op, .lhs, env, expr_region)) {
                return does_fx;
            }

            // Eagerly unify the operands, but ONLY when the dispatcher's
            // arithmetic method is known homogeneous (`T, T -> T`), so one
            // operand FORCES the other—propagation of an implied fact, not a
            // guess. Two gates, each forced:
            //
            //   1. `lhs_is_numeric`: the lhs is the dispatcher and a concrete
            //      builtin numeric nominal. Builtin arithmetic methods are
            //      homogeneous (e.g. `Dec.plus : Dec, Dec -> Dec`), so the rhs
            //      MUST be the same type.
            //   2. `rhs_is_numeric and lhs_is_from_numeral`: the lhs is an open
            //      numeric LITERAL. Every numeral defaulting candidate is a
            //      builtin numeric nominal with homogeneous arithmetic, so
            //      whatever the literal resolves to forces operand equality—the
            //      concrete builtin rhs pins it now.
            //
            // A concrete builtin rhs with a NON-literal, non-numeric lhs must NOT
            // be unified eagerly: the lhs/dispatcher could be a user nominal with
            // a heterogeneous method (e.g. `times : Duration, I64 -> Duration`
            // used as `my_duration * count` with `count : I64`). That case falls
            // through to the dispatch constraint below
            // (`lhs.times : (lhs, rhs) -> lhs`), which resolves against the user
            // method correctly.
            if (lhs_is_numeric or (rhs_is_numeric and lhs_is_from_numeral)) {
                const target = if (lhs_is_numeric) lhs_var else rhs_var;
                const other = if (lhs_is_numeric) rhs_var else lhs_var;
                const arg_unify_result = try self.unify(target, other, env);
                if (!arg_unify_result.isEstablished()) {
                    try self.markErroneous(expr_var);
                    return does_fx;
                }
            }

            if (try self.reportMissingNominalMethodForBinop(lhs_var, rhs_var, expr_var, method_name, env, expr_region)) {
                return does_fx;
            }

            // Arithmetic binops are homogeneous in the RETURN only: the result
            // type IS the receiver type. Do NOT also unify lhs with rhs—user
            // nominal methods may be heterogeneous (e.g.
            // `times : Duration, I64 -> Duration`). Result-position context
            // (`x : I64 = 1 + 2`) flows in here; argument-position context
            // reaches an open literal via constraint-aware defaulting.
            const ret_var = lhs_var;

            // Create the binop static dispatch function: lhs.method(rhs) -> lhs
            try self.mkBinopConstraint(
                lhs_var,
                rhs_var,
                ret_var,
                method_name,
                false,
                env,
                expr_region,
                expr_idx,
            );

            // Set the expression to redirect to the return type
            _ = try self.unify(expr_var, ret_var, env);
        },
        .lt, .gt, .le, .ge => {
            const method_name, const ret_var =
                switch (binop.op) {
                    .lt => .{ self.cir.idents.is_lt, try self.freshBool(env, expr_region) },
                    .gt => .{ self.cir.idents.is_gt, try self.freshBool(env, expr_region) },
                    .le => .{ self.cir.idents.is_lte, try self.freshBool(env, expr_region) },
                    .ge => .{ self.cir.idents.is_gte, try self.freshBool(env, expr_region) },
                    .add,
                    .sub,
                    .mul,
                    .div,
                    .rem,
                    .eq,
                    .ne,
                    .div_trunc,
                    .@"and",
                    .@"or",
                    .range_exclusive,
                    .range_inclusive,
                    => unreachable,
                };

            if (try self.reportMissingNominalMethodForBinop(lhs_var, rhs_var, expr_var, method_name, env, expr_region)) {
                return does_fx;
            }

            // For comparison binops, lhs and rhs must have the same type.
            const arg_unify_result = try self.unify(lhs_var, rhs_var, env);

            if (!arg_unify_result.isEstablished()) {
                try self.markErroneous(expr_var);
                return does_fx;
            }

            const arg_var = rhs_var;

            // Create the binop constraint with unified arg type
            try self.mkBinopConstraint(
                arg_var,
                arg_var,
                ret_var,
                method_name,
                false,
                env,
                expr_region,
                expr_idx,
            );

            // Set the expression to redirect to the return type
            _ = try self.unify(expr_var, ret_var, env);
        },
        .range_exclusive, .range_inclusive => {
            const method_name = switch (binop.op) {
                .range_exclusive => self.cir.idents.range_exclusive_to,
                .range_inclusive => self.cir.idents.range_inclusive_to,
                .add,
                .sub,
                .mul,
                .div,
                .rem,
                .lt,
                .gt,
                .le,
                .ge,
                .eq,
                .ne,
                .div_trunc,
                .@"and",
                .@"or",
                => unreachable,
            };

            if (try self.reportMissingNominalMethodForBinop(lhs_var, rhs_var, expr_var, method_name, env, expr_region)) {
                return does_fx;
            }

            // For range binops, both bounds must have the same type.
            const arg_unify_result = try self.unify(lhs_var, rhs_var, env);

            if (!arg_unify_result.isEstablished()) {
                try self.markErroneous(expr_var);
                return does_fx;
            }

            const arg_var = rhs_var;

            // Range binops carry the contract `ret = Range(bound)`: the
            // operator exists to produce a reusable range over the bound type,
            // and pinning that shape here lets context at the range (a `for`
            // loop's item type, a `Range(U8)` annotation) flow back into
            // still-open numeral bounds before they default.
            const ret_var = try self.mkRangeVar(arg_var, env, expr_region);

            // Create the binop static dispatch function: bound.method(bound) -> Range(bound)
            try self.mkBinopConstraint(
                arg_var,
                arg_var,
                ret_var,
                method_name,
                false,
                env,
                expr_region,
                expr_idx,
            );

            // Set the expression to redirect to the return type
            _ = try self.unify(expr_var, ret_var, env);
        },
        .eq => {
            if (try self.reportMissingNominalMethodForBinop(lhs_var, rhs_var, expr_var, self.cir.idents.is_eq, env, expr_region)) {
                return does_fx;
            }

            const arg_unify_result = try self.unify(lhs_var, rhs_var, env);
            if (!arg_unify_result.isEstablished()) {
                try self.markErroneous(expr_var);
                return does_fx;
            }

            const eq_ret_var = try self.freshBool(env, expr_region);
            try self.mkBinopConstraint(
                rhs_var,
                rhs_var,
                eq_ret_var,
                self.cir.idents.is_eq,
                false,
                env,
                expr_region,
                expr_idx,
            );

            _ = try self.unify(expr_var, eq_ret_var, env);
        },
        .ne => {
            // `a != b` desugars to `a.is_eq(b).not()`.
            //
            // a.is_eq(b) : x, x -> y
            // y.not() : y -> y
            //
            // Currently, we required `y` to be a `Bool`. This is more
            // restrictive, but makes inferred types easier to understand. We
            // may revisit this in the future, but relaxing the restriction
            // should be a non-breaking change.

            if (try self.reportMissingNominalMethodForBinop(lhs_var, rhs_var, expr_var, self.cir.idents.is_eq, env, expr_region)) {
                return does_fx;
            }

            // Unify lhs and rhs to ensure both operands have the same type
            const arg_unify_result = try self.unify(lhs_var, rhs_var, env);

            // If unification failed, short-circuit and set the expression to error
            if (!arg_unify_result.isEstablished()) {
                try self.markErroneous(expr_var);
                return does_fx;
            }

            // Get the eq method + ret var
            const eq_method_name = self.cir.idents.is_eq;
            const eq_arg_var = rhs_var;
            const eq_ret_var = try self.freshBool(env, expr_region);

            // Create the eq static dispatch function: arg.is_eq(arg) -> Bool
            try self.mkBinopConstraint(eq_arg_var, eq_arg_var, eq_ret_var, eq_method_name, true, env, expr_region, expr_idx);

            // Get the not method + ret var
            const not_method_name = self.cir.idents.not;
            const not_arg_var = eq_ret_var;
            const not_ret_var = eq_ret_var;

            // Create the not static dispatch function on the not_arg + not_ret
            // This function attaches the dispatch fn to the not_arg
            try self.mkUnaryOp(not_arg_var, not_ret_var, not_method_name, env, expr_region, null);

            // IMPORTANT: We currently required the eq_ret_var to be  a bool.
            // This is more restrictive, but makes inferred types easier to
            // understand. We may revisit this in the future, but relaxing the
            // restriction should be a non-breaking change.

            // The expression type is the return type of not
            _ = try self.unify(expr_var, not_ret_var, env);
        },
        .@"and", .@"or" => {
            const lhs_fresh_bool = try self.freshBool(env, expr_region);

            const binop_ctx: problem.Context.BinopContext.Binop = switch (binop.op) {
                .@"and" => .@"and",
                .@"or" => .@"or",
                .add,
                .sub,
                .mul,
                .div,
                .rem,
                .lt,
                .gt,
                .le,
                .ge,
                .eq,
                .ne,
                .div_trunc,
                .range_exclusive,
                .range_inclusive,
                => unreachable,
            };
            const lhs_result = try self.unifyInContext(lhs_fresh_bool, lhs_var, env, .{ .binop_lhs = .{
                .operator = binop_ctx,
                .binop_expr = expr_idx,
            } });

            // If lhs unified successfully, then reuse that var, otherwise
            // create a fresh one. This is so we can get nice errors on both
            // sides of the binop.
            const rhs_fresh_bool = if (lhs_result.isEstablished()) lhs_fresh_bool else try self.freshBool(env, expr_region);

            _ = try self.unifyInContext(rhs_fresh_bool, rhs_var, env, .{ .binop_rhs = .{
                .operator = binop_ctx,
                .binop_expr = expr_idx,
            } });

            // Unify left and right together to ensure both are bools
            _ = try self.unify(lhs_var, rhs_var, env);

            // Set the expression to redirect to the return type
            _ = try self.unify(expr_var, lhs_var, env);
        },
    }

    return does_fx;
}

fn reportDefinitelyInvalidNumericBinopOperand(
    self: *Self,
    operand_var: Var,
    expr_var: Var,
    expr_idx: CIR.Expr.Idx,
    op: CIR.Expr.Binop.Op,
    side: enum { lhs, rhs },
    env: *Env,
    region: Region,
) Allocator.Error!bool {
    if (!self.varIsDefinitelyNonNumericOperand(operand_var)) return false;

    const expected_num = try self.freshFromContent(try self.mkBuiltinNumberTypeContentFromKind(.dec), env, region);
    const binop_ctx: problem.Context.BinopContext.Binop = switch (op) {
        .add => .plus,
        .sub => .minus,
        .mul => .times,
        .div => .div,
        .rem => .div,
        .div_trunc => .div,
        .lt,
        .gt,
        .le,
        .ge,
        .eq,
        .ne,
        .@"and",
        .@"or",
        .range_exclusive,
        .range_inclusive,
        => return false,
    };

    const ctx: problem.Context = switch (side) {
        .lhs => .{ .binop_lhs = .{ .operator = binop_ctx, .binop_expr = expr_idx } },
        .rhs => .{ .binop_rhs = .{ .operator = binop_ctx, .binop_expr = expr_idx } },
    };

    _ = try self.unifyInContext(expected_num, operand_var, env, ctx);
    try self.markErroneous(expr_var);
    return true;
}

fn varIsDefinitelyNonNumericOperand(self: *Self, var_: Var) bool {
    var current = var_;
    while (true) {
        const resolved = self.types.resolveVar(current);
        return switch (resolved.desc.content) {
            .alias => |alias| {
                current = self.types.getAliasBackingVar(alias);
                continue;
            },
            .structure => |flat| switch (flat) {
                .record,
                .record_unbound,
                .tuple,
                .fn_pure,
                .fn_effectful,
                .fn_unbound,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => true,
                .nominal_type => false,
            },
            .err, .flex, .rigid, .field_presence => false,
        };
    }
}

fn reportMissingNominalMethodForBinop(
    self: *Self,
    lhs_var: Var,
    rhs_var: Var,
    expr_var: Var,
    method_name: Ident.Idx,
    env: *Env,
    region: Region,
) Allocator.Error!bool {
    const resolved_lhs = self.types.resolveVar(lhs_var);
    if (resolved_lhs.desc.content == .err) return false;

    if (resolved_lhs.desc.content != .structure or resolved_lhs.desc.content.structure != .nominal_type) {
        return false;
    }

    const nominal_type = resolved_lhs.desc.content.structure.nominal_type;
    const original_env = self.getNominalOriginEnv(nominal_type);
    if (self.lookupStaticDispatchMethodBinding(original_env, nominal_type.sourceDeclOptional(), self.cir, method_name) == null) {
        try self.reportMissingNominalMethodForBinopConstraint(lhs_var, rhs_var, expr_var, method_name, env, region);
        return true;
    }

    return false;
}

fn reportMissingNominalMethodForBinopConstraint(
    self: *Self,
    lhs_var: Var,
    rhs_var: Var,
    expr_var: Var,
    method_name: Ident.Idx,
    env: *Env,
    region: Region,
) Allocator.Error!void {
    const args_range = try self.types.appendVars(&.{ lhs_var, rhs_var });
    const ret_var = try self.fresh(env, region);
    const constraint_fn_var = try self.freshFromContent(.{ .structure = .{ .fn_unbound = Func{
        .args = args_range,
        .ret = ret_var,
    } } }, env, region);

    const constraint = StaticDispatchConstraint{
        .fn_name = method_name,
        .fn_var = constraint_fn_var,
        .origin = .{ .desugared_binop = .{ .negated = false } },
    };

    try self.reportConstraintError(lhs_var, constraint, .{ .missing_method = .nominal }, env, false);
    try self.markErroneous(expr_var);
}

fn getNominalOriginEnv(self: *Self, nominal_type: types_mod.NominalType) *const ModuleEnv {
    const original_env, _ = self.ownerEnvForOriginModule(
        nominal_type.origin_module,
        nominal_type.sourceDeclOptional(),
        nominal_type.originIsBuiltin(),
        "nominal type",
    );
    return original_env;
}

// binop + unary op exprs //

/// Create a static dispatch fn like: `lhs, rhs -> ret` and assert the
/// constraint to the lhs (receiver) var.
/// Constrain a literal pattern's type to support equality, since matching the
/// pattern compares the scrutinee against the literal's converted value.
fn mkPatternLiteralEqConstraint(
    self: *Self,
    pattern_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!void {
    const ret_var = try self.freshBool(env, region);
    try self.mkBinopConstraint(pattern_var, pattern_var, ret_var, self.cir.idents.is_eq, false, env, region, null);
}

fn mkBinopConstraint(
    self: *Self,
    lhs_var: Var,
    rhs_var: Var,
    ret_var: Var,
    method_name: Ident.Idx,
    negated: bool,
    env: *Env,
    region: Region,
    binop_expr_idx: ?CIR.Expr.Idx,
) Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Create the function type: lhs_type, rhs_type -> ret_type
    const args_range = try self.types.appendVars(&.{ lhs_var, rhs_var });

    // Create the constraint function type
    const constraint_fn_var = try self.freshFromContent(.{ .structure = .{ .fn_unbound = Func{
        .args = args_range,
        .ret = ret_var,
    } } }, env, region);

    // Create the static dispatch constraint
    const constraint = StaticDispatchConstraint{
        .fn_name = method_name,
        .fn_var = constraint_fn_var,
        .origin = .{ .desugared_binop = .{ .negated = negated } },
        .provenance = constraintProvenance(binop_expr_idx),
    };
    try self.recordCurrentExpectDispatchWatcher(constraint_fn_var);
    const constraint_range = try self.types.appendStaticDispatchConstraints(&.{constraint});
    if (binop_expr_idx) |expr_idx| {
        try self.publishBinopDispatchExpr(expr_idx, method_name, region, constraint_fn_var);
    }

    // Create a constrained flex and unify it with the lhs (receiver)
    const constrained_var = try self.freshFromContent(
        .{ .flex = Flex{ .name = null, .constraints = constraint_range } },
        env,
        region,
    );

    _ = try self.unify(constrained_var, lhs_var, env);
    try self.recordSchemeRequirementCandidate(lhs_var, constraint, .creation, null);
    try self.recordAmbiguityCandidate(lhs_var, .creation, constraintIntroExpr(constraint));
}

fn publishBinopDispatchExpr(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    method_name: Ident.Idx,
    region: Region,
    constraint_fn_var: Var,
) Allocator.Error!void {
    const expr = self.cir.store.getExpr(expr_idx);
    if (expr == .e_binop) {
        const binop = expr.e_binop;
        switch (binop.op) {
            .eq, .ne => {
                self.cir.store.replaceExprWithMethodEq(
                    expr_idx,
                    binop.lhs,
                    binop.rhs,
                    binop.op == .ne,
                    constraint_fn_var,
                );
            },
            .@"and", .@"or" => {},
            .add,
            .sub,
            .mul,
            .div,
            .rem,
            .lt,
            .gt,
            .le,
            .ge,
            .div_trunc,
            .range_exclusive,
            .range_inclusive,
            => {
                const args = try self.cir.store.appendExprSpan(&.{binop.rhs});
                try self.cir.store.replaceExprWithDispatchCall(
                    expr_idx,
                    binop.lhs,
                    method_name,
                    region,
                    args,
                    constraint_fn_var,
                    .{ .binop = binop.op },
                );
            },
        }
    }
}

/// Create a static dispatch fn like: `arg, arg -> ret` and assert the
/// constraint to the argument var.
fn mkUnaryOp(
    self: *Self,
    arg_var: Var,
    ret_var: Var,
    method_name: Ident.Idx,
    env: *Env,
    region: Region,
    unary_expr_idx: ?CIR.Expr.Idx,
) Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Create the function type: lhs_type, rhs_type -> ret_type
    const args_range = try self.types.appendVars(&.{arg_var});

    // Create the constraint function type
    const constraint_fn_var = try self.freshFromContent(.{ .structure = .{ .fn_unbound = Func{
        .args = args_range,
        .ret = ret_var,
    } } }, env, region);

    // Create the static dispatch constraint
    const constraint = StaticDispatchConstraint{
        .fn_name = method_name,
        .fn_var = constraint_fn_var,
        .origin = .desugared_unaryop,
        .provenance = constraintProvenance(unary_expr_idx),
    };
    try self.recordCurrentExpectDispatchWatcher(constraint_fn_var);
    const constraint_range = try self.types.appendStaticDispatchConstraints(&.{constraint});
    if (unary_expr_idx) |expr_idx| {
        try self.publishUnaryDispatchExpr(expr_idx, method_name, region, constraint_fn_var);
    }

    // Create a constrained flex and unify it with the arg
    const constrained_var = try self.freshFromContent(
        .{ .flex = Flex{ .name = null, .constraints = constraint_range } },
        env,
        region,
    );

    _ = try self.unify(constrained_var, arg_var, env);
    try self.recordSchemeRequirementCandidate(arg_var, constraint, .creation, null);
    try self.recordAmbiguityCandidate(arg_var, .creation, constraintIntroExpr(constraint));
}

fn publishUnaryDispatchExpr(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    method_name: Ident.Idx,
    region: Region,
    constraint_fn_var: Var,
) Allocator.Error!void {
    const expr = self.cir.store.getExpr(expr_idx);
    const receiver: CIR.Expr.Idx, const surface_origin: CIR.Expr.SurfaceOrigin = if (expr == .e_unary_minus)
        .{ expr.e_unary_minus.expr, .unary_minus }
    else if (expr == .e_unary_not)
        .{ expr.e_unary_not.expr, .unary_not }
    else
        return;
    try self.cir.store.replaceExprWithDispatchCall(
        expr_idx,
        receiver,
        method_name,
        region,
        .{ .span = base.DataSpan.empty() },
        constraint_fn_var,
        surface_origin,
    );
}

const IteratorLoopExpr = struct {
    expr_idx: CIR.Expr.Idx,
    expr_var: Var,
};

fn checkIteratorForLoop(
    self: *Self,
    loop_node: CIR.Node.Idx,
    loop_expr: ?IteratorLoopExpr,
    pattern: CIR.Pattern.Idx,
    iterable: CIR.Expr.Idx,
    body: CIR.Expr.Idx,
    env: *Env,
    loop_region: Region,
    expected: Expected,
) Allocator.Error!bool {
    var does_fx = false;
    const child_expected = expected.forStatement();

    const pattern_ctx: PatternCtx = if (self.patternNeedsExhaustiveness(pattern)) .match_branch else .for_;
    try self.checkPattern(pattern, pattern_ctx, env);
    const item_var: Var = ModuleEnv.varFrom(pattern);

    does_fx = try self.checkExpr(iterable, env, child_expected) or does_fx;
    const iterable_region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(iterable));
    const iterable_var: Var = ModuleEnv.varFrom(iterable);

    const iterable_is_erroneous = if (loop_expr) |expr|
        try self.retireCallLikeExprWithErroneousOperands(expr.expr_idx, expr.expr_var, &.{iterable})
    else
        self.callLikeOperandsContainErroneousValue(&.{iterable});
    const iterator_var = try self.mkIterVar(item_var, env, iterable_region);
    const iter_method = try @constCast(self.cir).insertIdent(base.Ident.for_text("iter"));
    const iter_fn_var = if (iterable_is_erroneous)
        try self.mkRejectedSyntheticReceiverDispatchFn(iterable_var, &.{}, iterator_var, env, iterable_region)
    else
        try self.mkSyntheticReceiverDispatchConstraint(
            iterable_var,
            &.{},
            iterator_var,
            iter_method,
            env,
            iterable_region,
        );

    const step = try self.mkIteratorStepContent(item_var, iterator_var, env);
    const step_var = try self.freshFromContent(step.content, env, loop_region);
    const next_method = try @constCast(self.cir).insertIdent(base.Ident.for_text("next"));
    const next_fn_var = if (iterable_is_erroneous)
        try self.mkRejectedSyntheticReceiverDispatchFn(iterator_var, &.{}, step_var, env, loop_region)
    else
        try self.mkSyntheticReceiverDispatchConstraint(
            iterator_var,
            &.{},
            step_var,
            next_method,
            env,
            loop_region,
        );

    try self.cir.recordForLoopDispatchPlan(
        loop_node,
        ModuleEnv.nodeIdxFrom(pattern),
        ModuleEnv.nodeIdxFrom(iterable),
        iterator_var,
        step_var,
        iter_fn_var,
        next_fn_var,
        step.topology,
    );

    does_fx = try self.checkExpr(body, env, child_expected.suppressHoistSelection()) or does_fx;
    return does_fx;
}

fn mkMethodCallConstraint(
    self: *Self,
    receiver_var: Var,
    arg_vars: []const Var,
    ret_var: Var,
    method_name: Ident.Idx,
    env: *Env,
    region: Region,
    method_expr_idx: CIR.Expr.Idx,
) Allocator.Error!Var {
    return try self.mkReceiverDispatchConstraint(
        receiver_var,
        arg_vars,
        ret_var,
        method_name,
        env,
        region,
        method_expr_idx,
    );
}

/// Build provenance for a static dispatch constraint from its introducing
/// expression (if any). This is the data the ambiguity judgment and the
/// constraint-error reports consume; it replaced the old var-keyed side
/// tables. Provenance is metadata: it never participates in type identity.
fn constraintProvenance(intro_expr: ?CIR.Expr.Idx) StaticDispatchConstraint.Provenance {
    return .{
        .intro_expr = if (intro_expr) |e|
            StaticDispatchConstraint.Provenance.OptExprIdx.from(@intFromEnum(e))
        else
            .none,
    };
}

fn mkSyntheticReceiverDispatchConstraint(
    self: *Self,
    receiver_var: Var,
    arg_vars: []const Var,
    ret_var: Var,
    method_name: Ident.Idx,
    env: *Env,
    region: Region,
) Allocator.Error!Var {
    return try self.mkReceiverDispatchConstraint(
        receiver_var,
        arg_vars,
        ret_var,
        method_name,
        env,
        region,
        null,
    );
}

fn mkRejectedSyntheticReceiverDispatchFn(
    self: *Self,
    receiver_var: Var,
    arg_vars: []const Var,
    ret_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!Var {
    const fn_var = try self.mkReceiverDispatchFnVar(receiver_var, arg_vars, ret_var, env, region);
    try self.markStaticDispatchFnRejected(fn_var);
    return fn_var;
}

fn mkReceiverDispatchFnVar(
    self: *Self,
    receiver_var: Var,
    arg_vars: []const Var,
    ret_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!Var {
    var all_args_sfa = std.heap.stackFallback(16 * @sizeOf(Var), self.gpa);
    const all_args_alloc = all_args_sfa.get();
    const all_args = try all_args_alloc.alloc(Var, arg_vars.len + 1);
    defer all_args_alloc.free(all_args);
    all_args[0] = receiver_var;
    @memcpy(all_args[1..], arg_vars);

    const args_range = try self.types.appendVars(all_args);
    return self.freshFromContent(.{ .structure = .{ .fn_unbound = Func{
        .args = args_range,
        .ret = ret_var,
    } } }, env, region);
}

fn mkReceiverDispatchConstraint(
    self: *Self,
    receiver_var: Var,
    arg_vars: []const Var,
    ret_var: Var,
    method_name: Ident.Idx,
    env: *Env,
    region: Region,
    method_expr_idx: ?CIR.Expr.Idx,
) Allocator.Error!Var {
    const constraint_fn_var = try self.mkReceiverDispatchFnVar(receiver_var, arg_vars, ret_var, env, region);

    const constraint = StaticDispatchConstraint{
        .fn_name = method_name,
        .fn_var = constraint_fn_var,
        .origin = .method_call,
        .provenance = constraintProvenance(method_expr_idx),
    };
    try self.recordCurrentExpectDispatchWatcher(constraint_fn_var);
    const constraint_range = try self.types.appendStaticDispatchConstraints(&.{constraint});

    const constrained_var = try self.freshFromContent(
        .{ .flex = Flex{ .name = null, .constraints = constraint_range } },
        env,
        region,
    );

    _ = try self.unify(constrained_var, receiver_var, env);
    try self.recordSchemeRequirementCandidate(receiver_var, constraint, .creation, null);
    try self.recordAmbiguityCandidate(receiver_var, .creation, constraintIntroExpr(constraint));
    return constraint_fn_var;
}

fn mkTypeMethodCallConstraint(
    self: *Self,
    dispatcher_var: Var,
    arg_vars: []const Var,
    ret_var: Var,
    method_name: Ident.Idx,
    env: *Env,
    region: Region,
    method_expr_idx: CIR.Expr.Idx,
) Allocator.Error!Var {
    const args_range = try self.types.appendVars(arg_vars);
    const constraint_fn_var = try self.freshFromContent(.{ .structure = .{ .fn_unbound = Func{
        .args = args_range,
        .ret = ret_var,
    } } }, env, region);

    const constraint = StaticDispatchConstraint{
        .fn_name = method_name,
        .fn_var = constraint_fn_var,
        .origin = .method_call,
        .provenance = constraintProvenance(method_expr_idx),
    };
    try self.recordCurrentExpectDispatchWatcher(constraint_fn_var);
    const constraint_range = try self.types.appendStaticDispatchConstraints(&.{constraint});

    const constrained_var = try self.freshFromContent(
        .{ .flex = Flex{ .name = null, .constraints = constraint_range } },
        env,
        region,
    );

    _ = try self.unify(constrained_var, dispatcher_var, env);
    try self.recordSchemeRequirementCandidate(dispatcher_var, constraint, .creation, null);
    try self.recordAmbiguityCandidate(dispatcher_var, .creation, constraintIntroExpr(constraint));
    return constraint_fn_var;
}

fn mkInterpolationMetadata(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    item_var: Var,
) Allocator.Error!StaticDispatchConstraint.InterpolationMetadata {
    const interpolation = self.cir.store.getExpr(expr_idx).e_interpolation;
    const parts = self.cir.store.sliceExpr(interpolation.parts);
    std.debug.assert(parts.len % 2 == 0);

    const interpolated_len = parts.len / 2;
    var interpolated_parts_sfa = std.heap.stackFallback(8 * @sizeOf(InterpolationPartMetadata), self.gpa);
    const interpolated_parts_alloc = interpolated_parts_sfa.get();
    var interpolated_parts = try std.ArrayList(InterpolationPartMetadata).initCapacity(interpolated_parts_alloc, interpolated_len);
    defer interpolated_parts.deinit(interpolated_parts_alloc);

    var part_i: usize = 0;
    while (part_i < parts.len) : (part_i += 2) {
        const part_expr_idx = parts[part_i];
        interpolated_parts.appendAssumeCapacity(.{
            .var_ = ModuleEnv.varFrom(part_expr_idx),
            .region = self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(part_expr_idx)),
        });
    }

    return .{
        .expr_region = StaticDispatchConstraint.OptRegion.some(
            self.cir.store.getNodeRegion(ModuleEnv.nodeIdxFrom(expr_idx)),
        ),
        .item_var = item_var,
        .interpolated_parts = try self.types.appendInterpolationParts(interpolated_parts.items),
    };
}

fn mkInterpolationConstraint(
    self: *Self,
    dispatcher_var: Var,
    arg_vars: []const Var,
    ret_var: Var,
    item_var: Var,
    method_name: Ident.Idx,
    env: *Env,
    region: Region,
    expr_idx: CIR.Expr.Idx,
) Allocator.Error!Var {
    const args_range = try self.types.appendVars(arg_vars);
    const constraint_fn_var = try self.freshFromContent(.{ .structure = .{ .fn_unbound = Func{
        .args = args_range,
        .ret = ret_var,
    } } }, env, region);

    const constraint = StaticDispatchConstraint{
        .fn_name = method_name,
        .fn_var = constraint_fn_var,
        .origin = .{ .from_literal = .interpolation },
        .provenance = constraintProvenance(expr_idx),
        .interpolation = try self.mkInterpolationMetadata(expr_idx, item_var),
    };
    try self.recordCurrentExpectDispatchWatcher(constraint_fn_var);
    const constraint_range = try self.types.appendStaticDispatchConstraints(&.{constraint});

    const constrained_var = try self.freshFromContent(
        .{ .flex = Flex{ .name = null, .constraints = constraint_range } },
        env,
        region,
    );

    _ = try self.unify(constrained_var, dispatcher_var, env);

    try self.recordOpenLiteralVar(constrained_var, &.{constraint}, ModuleEnv.nodeIdxFrom(expr_idx));

    return constraint_fn_var;
}

/// Rewrite a derived `is_eq` method call into an explicit structural-eq node.
///
/// RESTAMP RULE (all discharge-time plan rewrites): only the node's own
/// constraint may restamp a node that already carries a stamped plan
/// (`constraint_fn_var`). A discharge of an instantiated copy carries the
/// copy's fn var, so the guarded arms below return early on a mismatch,
/// keeping the scheme-pristine fn var stamped at plan creation. Restamping
/// from a foreign constraint would pin the stamped plan to one
/// instantiation's concrete types (the issue #9971 failure).
fn rewriteDerivedIsEqMethodCallAsStructuralEq(
    self: *Self,
    constraint: StaticDispatchConstraint,
) bool {
    const expr_idx = constraintIntroExpr(constraint) orelse return true;

    const expr = self.cir.store.getExpr(expr_idx);
    if (expr == .e_method_call) {
        const method_call = expr.e_method_call;
        const args = self.cir.store.sliceExpr(method_call.args);
        if (args.len != 1) return false;

        self.cir.store.replaceExprWithStructuralEq(expr_idx, method_call.receiver, args[0], constraint.origin.binopNegated());
    } else if (expr == .e_dispatch_call) {
        const method_call = expr.e_dispatch_call;
        if (method_call.constraint_fn_var != constraint.fn_var) return true;
        const args = self.cir.store.sliceExpr(method_call.args);
        if (args.len != 1) return false;

        self.cir.store.replaceExprWithStructuralEq(expr_idx, method_call.receiver, args[0], constraint.origin.binopNegated());
    } else if (expr == .e_type_method_call) {
        const method_call = expr.e_type_method_call;
        const args = self.cir.store.sliceExpr(method_call.args);
        if (args.len != 2) return false;

        self.cir.store.replaceExprWithStructuralEq(expr_idx, args[0], args[1], constraint.origin.binopNegated());
    } else if (expr == .e_type_dispatch_call) {
        const method_call = expr.e_type_dispatch_call;
        if (method_call.constraint_fn_var != constraint.fn_var) return true;
        const args = self.cir.store.sliceExpr(method_call.args);
        if (args.len != 2) return false;

        self.cir.store.replaceExprWithStructuralEq(expr_idx, args[0], args[1], constraint.origin.binopNegated());
    } else if (expr == .e_method_eq) {
        const eq = expr.e_method_eq;
        if (eq.constraint_fn_var != constraint.fn_var) return true;
        self.cir.store.replaceExprWithStructuralEq(expr_idx, eq.lhs, eq.rhs, constraint.origin.binopNegated());
    } else if (expr == .e_binop) {
        const binop = expr.e_binop;
        if (binop.op != .eq and binop.op != .ne) return true;
        self.cir.store.replaceExprWithStructuralEq(expr_idx, binop.lhs, binop.rhs, constraint.origin.binopNegated());
    } else if (expr == .e_structural_eq) {
        const eq = expr.e_structural_eq;
        self.cir.store.replaceExprWithStructuralEq(expr_idx, eq.lhs, eq.rhs, constraint.origin.binopNegated());
    }

    return true;
}

/// Rewrite a derived `to_hash` method call into an explicit structural-hash node.
/// The call is `value.to_hash(hasher)`, so the receiver is the value being hashed
/// and the single argument is the Hasher being threaded through.
///
/// Subject to the RESTAMP RULE documented on
/// `rewriteDerivedIsEqMethodCallAsStructuralEq`: the dispatch-call arms only
/// rewrite when the node's own constraint is discharging.
fn rewriteDerivedMethodCallAsStructuralHash(
    self: *Self,
    constraint: StaticDispatchConstraint,
) bool {
    const expr_idx = constraintIntroExpr(constraint) orelse return true;

    const expr = self.cir.store.getExpr(expr_idx);
    if (expr == .e_method_call) {
        const method_call = expr.e_method_call;
        const args = self.cir.store.sliceExpr(method_call.args);
        if (args.len != 1) return false;

        self.cir.store.replaceExprWithStructuralHash(expr_idx, method_call.receiver, args[0]);
    } else if (expr == .e_dispatch_call) {
        const method_call = expr.e_dispatch_call;
        if (method_call.constraint_fn_var != constraint.fn_var) return true;
        const args = self.cir.store.sliceExpr(method_call.args);
        if (args.len != 1) return false;

        self.cir.store.replaceExprWithStructuralHash(expr_idx, method_call.receiver, args[0]);
    } else if (expr == .e_type_method_call) {
        const method_call = expr.e_type_method_call;
        const args = self.cir.store.sliceExpr(method_call.args);
        if (args.len != 2) return false;

        self.cir.store.replaceExprWithStructuralHash(expr_idx, args[0], args[1]);
    } else if (expr == .e_type_dispatch_call) {
        const method_call = expr.e_type_dispatch_call;
        if (method_call.constraint_fn_var != constraint.fn_var) return true;
        const args = self.cir.store.sliceExpr(method_call.args);
        if (args.len != 2) return false;

        self.cir.store.replaceExprWithStructuralHash(expr_idx, args[0], args[1]);
    } else if (expr == .e_structural_hash) {
        const h = expr.e_structural_hash;
        self.cir.store.replaceExprWithStructuralHash(expr_idx, h.value, h.hasher);
    }

    return true;
}

/// Rewrite a desugared `==`/`!=` binop into an explicit method-eq node.
///
/// Subject to the RESTAMP RULE documented on
/// `rewriteDerivedIsEqMethodCallAsStructuralEq`: the `e_method_eq` arm only
/// restamps when the node's own constraint is discharging, enforced by its
/// guard at the restamp site (not only by checked-module output checks).
fn rewriteEqBinopAsMethodEq(self: *Self, constraint: StaticDispatchConstraint) void {
    if (constraint.origin != .desugared_binop) return;
    const expr_idx = constraintIntroExpr(constraint) orelse return;
    const expr = self.cir.store.getExpr(expr_idx);
    if (expr == .e_binop) {
        const binop = expr.e_binop;
        if (binop.op != .eq and binop.op != .ne) return;
        self.cir.store.replaceExprWithMethodEq(
            expr_idx,
            binop.lhs,
            binop.rhs,
            constraint.origin.binopNegated(),
            constraint.fn_var,
        );
    } else if (expr == .e_method_eq) {
        const eq = expr.e_method_eq;
        // A discharge of an instantiated copy carries the copy's fn var;
        // the node must keep the scheme-pristine fn var stamped at plan
        // creation, so only the node's own constraint may restamp it.
        if (eq.constraint_fn_var != constraint.fn_var) return;
        self.cir.store.replaceExprWithMethodEq(
            expr_idx,
            eq.lhs,
            eq.rhs,
            constraint.origin.binopNegated(),
            constraint.fn_var,
        );
    }
}

// problems //

// copy type from other module //

// external type lookups //

const ExternalType = struct {
    local_var: Var,
    other_cir_node_idx: CIR.Node.Idx,
    other_cir: *const ModuleEnv,
};

/// Copy a variable from a different module into this module's types store.
///
/// IMPORTANT: The caller must instantiate this variable before unifying
/// against it. This avoid poisoning the copied variable in the types store if
/// unification fails.
fn resolveVarFromExternal(
    self: *Self,
    import_idx: CIR.Import.Idx,
    node_idx: u32,
) std.mem.Allocator.Error!?ExternalType {
    const trace = tracy.trace(@src());
    defer trace.end();

    const module_idx = self.cir.imports.getResolvedModule(import_idx) orelse {
        // Canonicalization should already have reported an import error.
        // Keep checking by treating this type reference as unresolved.
        return null;
    };
    if (module_idx < self.imported_modules.len) {
        const other_module_env = self.imported_modules[module_idx];

        // The idx of the expression in the other module
        const target_node_idx = @as(CIR.Node.Idx, @enumFromInt(node_idx));

        // Check if we've already copied this import
        const cache_key = ImportCacheKey{
            .resolved_module_idx = module_idx,
            .node_idx = target_node_idx,
        };

        const copied_var = if (self.import_cache.get(cache_key)) |cached_var|
            // Reuse the previously copied type.
            cached_var
        else blk: {
            // First time importing this type - copy it and cache the result
            const imported_var: Var = @as(Var, @enumFromInt(@intFromEnum(target_node_idx)));

            // Every node should have a corresponding type entry
            std.debug.assert(@intFromEnum(imported_var) < other_module_env.types.len());

            const new_copy = try self.copyVar(imported_var, other_module_env, null);
            try self.import_cache.put(self.gpa, cache_key, new_copy);
            break :blk new_copy;
        };

        if (other_module_env.nodeIsBindingScheme(target_node_idx)) {
            try self.markBindingSchemeVar(copied_var);
        }

        return .{
            .local_var = copied_var,
            .other_cir_node_idx = target_node_idx,
            .other_cir = other_module_env,
        };
    } else {
        // Stale/invalid import mapping; surface as unresolved and continue
        // producing type errors instead of crashing.
        return null;
    }
}

fn checkAssociatedLookup(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    expr_var: Var,
    lookup: @FieldType(CIR.Expr, "e_lookup_associated"),
    region: Region,
    env: *Env,
) Allocator.Error!void {
    const external_type = (try self.resolveVarFromExternal(lookup.module_idx, lookup.type_node_idx)) orelse {
        try self.markErroneous(expr_var);
        return;
    };

    try self.checkAssociatedLookupFromOwnerVar(
        expr_idx,
        expr_var,
        external_type.local_var,
        lookup.type_ident,
        lookup.item_ident,
        region,
        env,
    );
}

fn checkLocalAssociatedLookup(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    expr_var: Var,
    lookup: @FieldType(CIR.Expr, "e_lookup_associated_local"),
    region: Region,
    env: *Env,
) Allocator.Error!void {
    try self.checkAssociatedLookupFromOwnerVar(
        expr_idx,
        expr_var,
        @enumFromInt(lookup.type_node_idx),
        lookup.type_ident,
        lookup.item_ident,
        region,
        env,
    );
}

fn checkAssociatedLookupFromOwnerVar(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    expr_var: Var,
    initial_owner_var: Var,
    type_ident: Ident.Idx,
    item_ident: Ident.Idx,
    region: Region,
    env: *Env,
) Allocator.Error!void {
    const resolution = (try self.resolveAssociatedLookup(initial_owner_var, item_ident)) orelse {
        try self.failAssociatedLookup(expr_idx, expr_var, type_ident, item_ident, region, env);
        return;
    };
    const source_ident = try self.cir.insertQualifiedIdent(
        self.cir.getIdent(type_ident),
        self.cir.getIdent(item_ident),
    );

    self.cir.store.replaceExprWithResolvedAssociatedLookup(
        expr_idx,
        resolution.module_identity,
        resolution.target.binding.type_node_idx,
        resolution.target.binding.def_idx,
        source_ident,
    );

    try self.checkResolvedAssociatedTarget(
        expr_var,
        resolution.target.env,
        resolution.target.is_this_module,
        resolution.target.binding.type_node_idx,
        resolution.target.binding.def_idx,
        region,
        env,
    );
}

fn resolveAssociatedLookup(
    self: *Self,
    initial_owner_var: Var,
    item_ident: Ident.Idx,
) Allocator.Error!?AssociatedLookupResolution {
    const cache_key = AssociatedLookupCacheKey{ .owner_var = initial_owner_var, .item_ident = item_ident };
    if (self.associated_lookup_cache.get(cache_key)) |cached| return cached;

    var owner_var = initial_owner_var;
    const nominal = while (true) {
        const owner = self.types.resolveVar(owner_var);
        switch (owner.desc.content) {
            .alias => |alias| owner_var = self.types.getAliasBackingVar(alias),
            .structure => |flat| {
                if (flat != .nominal_type) {
                    try self.associated_lookup_cache.put(self.gpa, cache_key, null);
                    return null;
                }
                break flat.nominal_type;
            },
            .err, .flex, .rigid, .field_presence => {
                try self.associated_lookup_cache.put(self.gpa, cache_key, null);
                return null;
            },
        }
    };

    const owner_env, _ = self.ownerEnvForOriginModule(
        nominal.origin_module,
        nominal.sourceDeclOptional(),
        nominal.originIsBuiltin(),
        "associated value lookup",
    );
    const target = self.lookupStaticDispatchMethodBinding(
        owner_env,
        nominal.sourceDeclOptional(),
        self.cir,
        item_ident,
    ) orelse {
        try self.associated_lookup_cache.put(self.gpa, cache_key, null);
        return null;
    };
    const resolution = AssociatedLookupResolution{
        .target = target,
        .module_identity = try self.internCheckedTargetModuleIdentity(target.env),
    };
    try self.associated_lookup_cache.put(self.gpa, cache_key, resolution);
    return resolution;
}

fn checkResolvedAssociatedLookup(
    self: *Self,
    expr_var: Var,
    lookup: @FieldType(CIR.Expr, "e_lookup_associated_resolved"),
    region: Region,
    env: *Env,
) Allocator.Error!void {
    const target = self.moduleEnvForIdentity(lookup.module_identity) orelse {
        std.debug.panic("type checker invariant violated: resolved associated lookup target is unavailable", .{});
    };
    try self.checkResolvedAssociatedTarget(
        expr_var,
        target.env,
        target.is_this_module,
        @enumFromInt(lookup.target_node_idx),
        lookup.target_def_idx,
        region,
        env,
    );
}

fn checkResolvedAssociatedTarget(
    self: *Self,
    expr_var: Var,
    target_env: *const ModuleEnv,
    is_this_module: bool,
    target_node_idx: CIR.Node.Idx,
    target_def_idx: CIR.Def.Idx,
    region: Region,
    env: *Env,
) Allocator.Error!void {
    if (generatedDerivedMethodDef(target_env, target_def_idx)) {
        try self.reportAnnotationOnlyValueUse(expr_var, region, env);
        return;
    }

    if (annotationOnlyValueDef(target_env, target_def_idx)) {
        try self.reportValuelessDeclarationUse(expr_var, region);
        return;
    }

    const target_var = try self.methodTypeVarFromOriginalEnv(
        target_env,
        is_this_module,
        target_node_idx,
        env,
        region,
    );
    _ = try self.unify(expr_var, target_var, env);
}

fn failAssociatedLookup(
    self: *Self,
    expr_idx: CIR.Expr.Idx,
    expr_var: Var,
    type_ident: Ident.Idx,
    item_ident: Ident.Idx,
    region: Region,
    _: *Env,
) Allocator.Error!void {
    _ = try self.problems.appendProblem(self.gpa, .{ .associated_item_not_found = .{
        .type_name = type_ident,
        .item_name = item_ident,
        .region = region,
    } });
    const diagnostic_idx = try self.cir.store.addDiagnosticUnregistered(.{ .nested_value_not_found = .{
        .parent_name = type_ident,
        .nested_name = item_ident,
        .region = region,
    } });
    try self.replaceExprWithRuntimeError(expr_idx, diagnostic_idx);
    try self.markErroneous(expr_var);
}

fn internCheckedTargetModuleIdentity(
    self: *Self,
    target_env: *const ModuleEnv,
) Allocator.Error!base.ModuleIdentity.Idx {
    if (target_env == self.cir) return self.cir.selfModuleIdentity();
    const target_hash = target_env.contentIdentityHash() orelse {
        std.debug.panic("type checker invariant violated: associated lookup target has no content identity", .{});
    };
    const display_ident = try self.cir.insertIdent(base.Ident.for_text(target_env.module_name));
    return try self.cir.internModuleIdentity(target_hash, display_ident);
}

fn moduleEnvForIdentity(
    self: *const Self,
    module_identity: base.ModuleIdentity.Idx,
) ?OwnerEnvCandidate {
    const target_hash = self.cir.moduleIdentityHash(module_identity);
    return self.owner_envs_by_identity.get(target_hash.*);
}

/// Copy a variable from another module into this module
/// The ranks of all variables copied will be generalized
fn copyVar(self: *Self, other_module_var: Var, other_module_env: *const ModuleEnv, mb_region: ?Region) std.mem.Allocator.Error!Var {
    return self.copyVarWithSourceSubstitutions(other_module_var, other_module_env, mb_region, null, null);
}

/// Copy a variable from another module, replacing exact source roots and alias
/// declaration occurrences with existing destination roots while traversing.
fn copyVarWithSourceSubstitutions(
    self: *Self,
    other_module_var: Var,
    other_module_env: *const ModuleEnv,
    mb_region: ?Region,
    source_var_substitutions: ?*const std.AutoHashMap(Var, Var),
    source_alias_substitutions: ?*const std.AutoHashMap(copy_import.AliasSource, Var),
) std.mem.Allocator.Error!Var {
    const trace = tracy.trace(@src());
    defer trace.end();

    // First, reset state
    self.var_map.clearRetainingCapacity();
    if (source_var_substitutions) |substitutions| {
        var iterator = substitutions.iterator();
        while (iterator.next()) |entry| {
            try self.var_map.put(entry.key_ptr.*, entry.value_ptr.*);
        }
    }

    // Copy the var from the dest type store into this type store
    const first_new_var: usize = @intCast(self.types.len());
    const copied_var = try copy_import.copyVar(
        &other_module_env.*.types,
        self.types,
        other_module_var,
        &self.var_map,
        source_alias_substitutions,
        other_module_env,
        self.cir,
        self.gpa,
    );

    const region = if (mb_region) |region| region else base.Region.zero();

    try self.postProcessCopiedVars(first_new_var, region);

    return copied_var;
}

/// Bookkeeping for vars newly minted in this store by a cross-module copy
/// (`[first_new_var, types.len())` is the exact allocation range): fill in
/// regions for error reporting and register copied open literals on the
/// defaulting worklist.
fn postProcessCopiedVars(self: *Self, first_new_var: usize, region: Region) std.mem.Allocator.Error!void {
    // If we had to insert any new type variables, ensure that we have
    // corresponding regions for them. This is essential for error reporting.
    for (first_new_var..@as(usize, @intCast(self.types.len()))) |raw_var| {
        const fresh_var: Var = @enumFromInt(@as(u32, @intCast(raw_var)));
        try self.fillInRegionsThrough(fresh_var);

        self.setRegionAt(fresh_var, region);

        // Register a copied open literal on the worklist so this module's
        // defaulting passes find it without a whole-store scan—the same
        // bookkeeping the other literal-creation sites do.
        const fresh_content = self.types.resolveVar(fresh_var).desc.content;
        if (fresh_content == .flex) {
            const constraints = self.types.sliceStaticDispatchConstraints(fresh_content.flex.constraints);
            for (constraints) |c| {
                if (self.constraintIsLiteralConversion(c)) {
                    try self.recordOpenLiteralVar(fresh_var, constraints, null);
                    break;
                }
            }
        }
    }

    // Assert that we have regions for every type variable
    self.debugAssertArraysInSync();
}

// nominal type checking helpers //

/// Result of checking a nominal type usage
const NominalCheckResult = enum {
    /// Successfully checked the nominal type
    ok,
    /// An error occurred (already reported and target_var set to error)
    err,
};

/// Check a nominal type usage (either in pattern or expression context).
/// The checker-side explicit opening operation (issue #9983): resolve the
/// application's declaration in this module's declaration table and
/// instantiate its backing template, substituting the application's actual
/// args for the declaration's formals (by rigid name, mirroring the type-
/// application annotation path). Returns null when the declaration is
/// invalid or unresolvable—callers poison the use.
fn openNominalBackingForApp(
    self: *Self,
    nominal_type: types_mod.NominalType,
    env: *Env,
    region: Region,
) std.mem.Allocator.Error!?Var {
    const decl_idx = self.types.lookupNominalDecl(nominal_type) orelse {
        if (nominal_type.sourceDecl().present) {
            if (builtin.mode == .Debug) {
                std.debug.panic(
                    "type checker invariant violated: nominal application '{s}' has a source declaration but no declaration table entry",
                    .{self.cir.getIdentStoreConst().getText(nominal_type.ident.ident_idx)},
                );
            }
            unreachable;
        }
        return null;
    };
    const decl = self.types.getNominalDecl(decl_idx);
    if (!decl.isValid()) return null;

    // Substitute the application's args for the declaration's formals by
    // rigid name (formals are rigid vars with distinct names; the same
    // mapping the annotation application path builds).
    const formals = self.types.sliceVars(decl.formals);
    const args = self.types.sliceNominalArgs(nominal_type);
    std.debug.assert(formals.len == args.len);

    self.rigid_var_substitutions.clearRetainingCapacity();
    for (formals, args) |formal_var, arg_var| {
        const formal_resolved = self.types.resolveVar(formal_var).desc.content;
        // A malformed header arg (underscore/malformed anno) is err, not
        // rigid; the template cannot reference it by name, so it has no
        // substitution entry.
        if (formal_resolved != .rigid) continue;
        try self.rigid_var_substitutions.put(self.gpa, formal_resolved.rigid.name, arg_var);
    }

    return try self.instantiateVarWithSubs(
        decl.backing,
        &self.rigid_var_substitutions,
        env,
        .{ .explicit = region },
    );
}

/// This is the shared logic for `.nominal`, `.nominal_external`, `.e_nominal`, and `.e_nominal_external`.
///
/// Parameters:
/// - target_var: The type variable to unify with (pattern_var or expr_var)
/// - actual_backing_var: The type variable of the backing expression/pattern
/// - nominal_type_decl_var: The type variable from the nominal type declaration
/// - backing_type: The kind of backing type (tag, record, tuple, value)
/// - region: The source region for instantiation
/// - env: The type checking environment
/// - owner_expr: the constructor expression, for the expression forms. A
///   nominal pattern's backing is a sub-pattern of the same pattern, and a
///   pattern has no node a rejection could replace with a runtime error, so the
///   pattern forms pass null and are decided once, at relation time. Their
///   operand is pinned by the scrutinee the pattern is checked against, so the
///   widening the settled-state re-decision exists to catch cannot reach them.
fn checkNominalTypeUsage(
    self: *Self,
    target_var: Var,
    actual_backing_var: Var,
    nominal_type_decl_var: Var,
    backing_type: CIR.Expr.NominalBackingType,
    region: Region,
    env: *Env,
    row_width_relation: unifier.RowWidthRelation,
    owner_expr: ?CIR.Expr.Idx,
) std.mem.Allocator.Error!NominalCheckResult {
    const trace = tracy.trace(@src());
    defer trace.end();

    // Instantiate the nominal type declaration
    const nominal_var = try self.instantiateVar(nominal_type_decl_var, env, .{ .explicit = region });
    const nominal_resolved = self.types.resolveVar(nominal_var).desc.content;

    if (nominal_resolved == .structure and nominal_resolved.structure == .nominal_type) {
        const nominal_type = nominal_resolved.structure.nominal_type;

        // If this nominal type is opaque and we're not in the defining module
        // then report an error
        if (!nominal_type.canLiftInner(self.cir.selfModuleIdentity())) {
            _ = try self.problems.appendProblem(self.cir.gpa, .{ .cannot_access_opaque_nominal = .{
                .var_ = target_var,
                .nominal_type_name = nominal_type.ident.ident_idx,
            } });

            // Mark the entire expression as having a type error
            try self.markErroneous(target_var);
            return .err;
        }

        // The explicit opening operation: resolve the declaration and
        // instantiate its backing template with the fresh application's args
        // substituted for the declaration's formals.
        // E.g. ConList(a) := [Cons(a, ConstList), Nil]
        //                    ^^^^^^^^^^^^^^^^^^^^^^^^^
        const nominal_backing_var = (try self.openNominalBackingForApp(nominal_type, env, region)) orelse {
            // The declaration is invalid (already reported) or unresolvable;
            // poison this use silently.
            try self.markErroneous(target_var);
            return .err;
        };

        // Unify what the user wrote with the backing type of the nominal
        // E.g. ConList.Cons(...) <-> [Cons(a, ConsList(a)), Nil]
        //              ^^^^^^^^^     ^^^^^^^^^^^^^^^^^^^^^^^^^
        // Convert CIR.Expr.NominalBackingType to Context.NominalConstructorContext.BackingType
        const context_backing_type: problem.Context.NominalConstructorContext.BackingType = @enumFromInt(@intFromEnum(backing_type));
        const constructor_context: problem.Context.NominalConstructorContext = .{ .backing_type = context_backing_type };
        // Only an anonymous expected backing can be inverse-lifted through, and
        // an accepted relation merges that side away, so the settled state can
        // no longer read it: take both the verdict and the shape it describes
        // here, while they still mean something.
        const recheck_at_settled_state: ?struct { expr: CIR.Expr.Idx, expected: types_mod.Content } = blk: {
            const owner = owner_expr orelse break :blk null;
            const is_anonymous = unifier.constructorBackingIsAnonymous(self.types, nominal_backing_var) orelse
                break :blk null;
            if (!is_anonymous) break :blk null;
            break :blk .{ .expr = owner, .expected = self.types.resolveVar(nominal_backing_var).desc.content };
        };
        const result = try self.unifyNominalConstructorBacking(
            nominal_backing_var,
            actual_backing_var,
            env,
            constructor_context,
            row_width_relation,
        );

        // Handle the result of unification
        switch (result) {
            .unified => {
                // If unification succeeded, this is a valid instance of the nominal type
                // So we set the target's type to be the nominal type
                _ = try self.unify(target_var, nominal_var, env);
                if (recheck_at_settled_state) |recheck| {
                    try self.accepted_nominal_constructor_backings.append(self.gpa, .{
                        .expr_idx = recheck.expr,
                        .expected_backing_content = recheck.expected,
                        .actual_backing = actual_backing_var,
                        .context = constructor_context,
                    });
                }
                return .ok;
            },
            .suppressed_by_error => {
                // The backing relation was not established, so it cannot
                // authorize the nominal wrapper. The existing nested error is
                // already responsible for the diagnostic.
                try self.markErroneous(target_var);
                return .err;
            },
            // `.mismatch` cannot occur here (this path never passes
            // `write_no_report`), but a reported problem and an unreported
            // mismatch both mean the constructor is incompatible.
            .problem, .mismatch => {
                // Only the constructor node becomes erroneous. Its operand keeps
                // the type it legitimately has, so every other expression that
                // shares that solved class stays lowerable.
                try self.markErroneous(target_var);
                return .err;
            },
        }
    } else if (nominal_resolved == .err) {
        // The declaration itself is poisoned (malformed backing or invalid
        // recursion) and that error was already reported at the declaration.
        // Poison this use silently instead of piling on a resolution error.
        try self.markErroneous(target_var);
        return .err;
    } else {
        // If the nominal type resolves to something other than a nominal_type structure,
        // report the error and set the expression to error type
        _ = try self.problems.appendProblem(self.cir.gpa, .{ .nominal_type_resolution_failed = .{
            .var_ = target_var,
            .nominal_type_decl_var = nominal_type_decl_var,
        } });
        try self.markErroneous(target_var);
        return .err;
    }
}

// validate constraints //

/// Drive ordinary constraints and every runnable static-dispatch relation to
/// quiescence. A semantic judgment can ground a dispatch receiver without
/// adding an ordinary constraint (record-destructure binder judgment is one
/// example), so the ordinary queue alone cannot decide whether this fixpoint
/// has work left.
///
/// `anyDeferredDispatchReceiverResolved` keeps inert flex receivers parked:
/// we only pay for a dispatch pass when at least one queued relation can make
/// progress. Static dispatch can add ordinary constraints, and checking those
/// constraints can ground more dispatch receivers, hence the joint loop.
fn quiesceConstraints(
    self: *Self,
    env: *Env,
    is_numeric_default_pass: bool,
) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    while (true) {
        if (self.constraints.items.items.len > 0) {
            try self.checkConstraints(env);
        }

        if (!try self.anyDeferredDispatchReceiverResolved(env)) return;
        try self.checkStaticDispatchConstraints(env, is_numeric_default_pass);
    }
}

/// Check all non-defaulting constraints.
fn checkAllConstraints(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    try self.quiesceConstraints(env, false);
}

fn poisonRecursiveNonFunctionProcessingDef(
    self: *Self,
    processing_def: DefProcessed,
    use_expr: ?CIR.Expr.Idx,
    _: *Env,
) Allocator.Error!void {
    const def = self.cir.store.getDef(processing_def.def_idx);
    const diagnostic_idx = if (processing_def.def_name) |ident|
        try self.cir.addDiagnostic(.{ .circular_value_definition = .{
            .ident = ident,
            .region = self.cir.store.getPatternRegion(def.pattern),
        } })
    else
        try self.cir.addDiagnostic(.{ .erroneous_value_expr = .{
            .region = self.cir.store.getExprRegion(def.expr),
        } });

    if (self.cir.store.getExpr(def.expr) != .e_runtime_error) {
        try self.replaceExprWithRuntimeError(def.expr, diagnostic_idx);
    }
    try self.erroneous_value_exprs.put(self.gpa, def.expr, {});
    try self.erroneous_value_patterns.put(self.gpa, def.pattern, {});

    if (use_expr) |expr_idx| {
        if (self.cir.store.getExpr(expr_idx) != .e_runtime_error) {
            try self.replaceExprWithRuntimeError(expr_idx, diagnostic_idx);
        }
        try self.erroneous_value_exprs.put(self.gpa, expr_idx, {});
        try self.markErroneous(ModuleEnv.varFrom(expr_idx));
    }
}

fn poisonErroneousValueUses(self: *Self) Allocator.Error!void {
    for (self.value_lookup_tracking.items) |entry| {
        const pattern_var = ModuleEnv.varFrom(entry.pattern_idx);
        if (!self.erroneous_value_patterns.contains(entry.pattern_idx) and
            self.types.resolveVar(pattern_var).desc.content != .err)
        {
            continue;
        }

        if (self.cir.store.getExpr(entry.expr_idx) == .e_runtime_error) continue;

        const ident = self.getPatternIdent(entry.pattern_idx) orelse continue;
        const diagnostic_idx = try self.cir.addDiagnostic(.{ .erroneous_value_use = .{
            .ident = ident,
            .region = self.cir.store.getExprRegion(entry.expr_idx),
        } });
        try self.replaceExprWithRuntimeError(entry.expr_idx, diagnostic_idx);
    }
}

fn poisonErroneousValueExprs(self: *Self) Allocator.Error!void {
    var iter = self.erroneous_value_exprs.keyIterator();
    while (iter.next()) |expr_idx| {
        if (self.cir.store.getExpr(expr_idx.*) == .e_runtime_error) continue;
        const diagnostic_idx = try self.cir.addDiagnostic(.{ .erroneous_value_expr = .{
            .region = self.cir.store.getExprRegion(expr_idx.*),
        } });
        try self.replaceExprWithRuntimeError(expr_idx.*, diagnostic_idx);
    }
}

fn resolveNumericLiteralsFromContext(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    // An open literal resolves only through direct unification (annotations,
    // signatures, the binop return contract) or through defaulting—never by
    // guessing a type from a concrete peer (the removed "peer resolution").
    // This still processes dispatch constraints deferred since the last pass.
    try self.checkAllConstraints(env);
}

/// A speculative-probe scope. Brackets type-store speculation together with the
/// Check-level append-only buffers a probe also grows (`regions`,
/// `instantiation_dispatchers`, `open_literal_vars`), so the probe sites don't
/// repeat the bookkeeping. Begin before invoking the unifier; `rollback`
/// discards everything the probe did to the store and those buffers. (The store's
/// own child lists—vars, tags, etc.—are handled inside
/// begin/rollbackToSavepoint.)
const Probe = struct {
    check: *Self,
    env: ?*Env,
    savepoint: types_mod.Store.Savepoint,
    deferred_constraints_len: usize,
    regions_len: usize,
    instantiation_dispatchers_len: usize,
    instantiation_dispatchers_checked: usize,
    pending_scheme_requirement_dispatchers_len: usize,
    ambiguity_candidates_len: usize,
    ambiguity_escalation_journal_len: usize,
    scheme_requirement_candidates_len: usize,
    open_literal_vars_len: usize,
    open_numeral_literals_len: usize,
    pending_tuple_accesses_len: usize,
    scheme_uses_len: usize,
    scheme_use_pairs_len: usize,
    generated_codec_derivations_len: usize,
    generated_codec_calls_len: usize,
    rejected_static_dispatches_len: usize,
    record_omitted_defaults_len: usize,
    accepted_nominal_constructor_backings_len: usize,
    dispatch_target_instantiations_len: usize,
    dispatch_derivations_len: usize,
    imported_method_schemes_len: usize,

    fn rollback(self: *Probe) void {
        std.debug.assert(self.check.probe_depth > 0);
        self.check.types.rollbackToSavepoint(&self.savepoint);
        if (self.env) |env| {
            // Instantiation inside a probe can enqueue a range allocated after
            // the type-store savepoint. Rewind the owning env before any later
            // pass can observe those now-invalid indices.
            env.deferred_static_dispatch_constraints.items.shrinkRetainingCapacity(self.deferred_constraints_len);
        }
        self.check.regions.items.shrinkRetainingCapacity(self.regions_len);
        // Per-instantiation dispatchers recorded during the probe reference fresh
        // receiver vars that were just rolled back with the type store.
        self.check.instantiation_dispatchers.shrinkRetainingCapacity(self.instantiation_dispatchers_len);
        self.check.instantiation_dispatchers_checked = self.instantiation_dispatchers_checked;
        self.check.pending_scheme_requirement_dispatchers.shrinkRetainingCapacity(self.pending_scheme_requirement_dispatchers_len);
        // Escalation flips journaled by this probe scope were speculative
        // work: reset them before the candidate truncation below, while every
        // journaled index is still in bounds.
        while (self.check.ambiguity_escalation_journal.items.len > self.ambiguity_escalation_journal_len) {
            const flipped_idx = self.check.ambiguity_escalation_journal.pop().?;
            self.check.ambiguity_candidates.items[flipped_idx].requires_current_resolution = false;
        }
        self.check.shrinkAmbiguityCandidatesTo(self.ambiguity_candidates_len);
        self.check.shrinkSchemeRequirementCandidatesTo(self.scheme_requirement_candidates_len);
        // Likewise, open literals registered during the probe (by in-probe
        // instantiation) reference vars the savepoint rollback just discarded.
        self.check.open_literal_vars.shrinkRetainingCapacity(self.open_literal_vars_len);
        self.check.open_numeral_literals.shrinkRetainingCapacity(self.open_numeral_literals_len);
        self.check.pending_tuple_accesses.shrinkRetainingCapacity(self.pending_tuple_accesses_len);
        // Scheme-use evidence recorded during the probe can reference fresh
        // vars the savepoint rollback just discarded.
        self.check.cir.scheme_uses.items.shrinkRetainingCapacity(self.scheme_uses_len);
        self.check.cir.scheme_use_pairs.items.shrinkRetainingCapacity(self.scheme_use_pairs_len);
        self.check.cir.generated_codec_derivations.items.shrinkRetainingCapacity(self.generated_codec_derivations_len);
        self.check.cir.generated_codec_calls.items.shrinkRetainingCapacity(self.generated_codec_calls_len);
        // The durable records drop here; the rejection markers they mirror live
        // on descriptors the savepoint rollback above already restored.
        self.check.cir.rejected_static_dispatches.items.shrinkRetainingCapacity(self.rejected_static_dispatches_len);
        self.check.cir.record_omitted_defaults.items.shrinkRetainingCapacity(self.record_omitted_defaults_len);
        // Constructor relations recorded during the probe name the operand var
        // and the backing content the savepoint rollback just discarded.
        self.check.accepted_nominal_constructor_backings.shrinkRetainingCapacity(self.accepted_nominal_constructor_backings_len);
        while (self.check.dispatch_target_instantiations.items.len > self.dispatch_target_instantiations_len) {
            const removed = self.check.dispatch_target_instantiations.pop().?;
            const did_remove = self.check.dispatch_target_instantiation_by_fn_var.remove(removed.constraint_fn_var);
            std.debug.assert(did_remove);
        }
        self.check.probe_depth -= 1;
        self.check.shrinkDispatchDerivationsTo(self.dispatch_derivations_len);
        while (self.check.imported_method_schemes.items.len > self.imported_method_schemes_len) {
            const removed = self.check.imported_method_schemes.pop().?;
            const did_remove = self.check.imported_method_scheme_by_source.remove(removed.key);
            std.debug.assert(did_remove);
        }
    }

    /// Close the probe scope KEEPING everything it did: the type-store
    /// speculation is committed and the appended regions / per-instantiation
    /// dispatchers stay (they describe vars that now survive). Only `CommitProbe`
    /// commits; pure-predicate probes always roll back.
    fn commit(self: *Probe) void {
        std.debug.assert(self.check.probe_depth > 0);
        self.check.types.commitSavepoint(&self.savepoint);
        self.check.probe_depth -= 1;
        // Escalation flips this scope journaled are kept—the committed
        // observations are real—so the journal entries are dead weight and
        // drop with the scope.
        self.check.ambiguity_escalation_journal.shrinkRetainingCapacity(self.ambiguity_escalation_journal_len);
    }
};

fn beginProbe(self: *Self, env: ?*Env) std.mem.Allocator.Error!Probe {
    const regions_len = self.regions.items.items.len;
    const instantiation_dispatchers_len = self.instantiation_dispatchers.items.len;
    const pending_scheme_requirement_dispatchers_len = self.pending_scheme_requirement_dispatchers.items.len;
    const ambiguity_candidates_len = self.ambiguity_candidates.items.len;
    const ambiguity_escalation_journal_len = self.ambiguity_escalation_journal.items.len;
    const scheme_requirement_candidates_len = self.scheme_requirement_candidates.items.len;
    const open_literal_vars_len = self.open_literal_vars.items.len;
    const open_numeral_literals_len = self.open_numeral_literals.items.len;
    const pending_tuple_accesses_len = self.pending_tuple_accesses.items.len;
    const scheme_uses_len = self.cir.scheme_uses.items.items.len;
    const scheme_use_pairs_len = self.cir.scheme_use_pairs.items.items.len;
    const generated_codec_derivations_len = self.cir.generated_codec_derivations.items.items.len;
    const generated_codec_calls_len = self.cir.generated_codec_calls.items.items.len;
    const rejected_static_dispatches_len = self.cir.rejected_static_dispatches.items.items.len;
    const record_omitted_defaults_len = self.cir.record_omitted_defaults.items.items.len;
    const accepted_nominal_constructor_backings_len = self.accepted_nominal_constructor_backings.items.len;
    const dispatch_target_instantiations_len = self.dispatch_target_instantiations.items.len;
    const dispatch_derivations_len = self.dispatch_derivations.items.len;
    const imported_method_schemes_len = self.imported_method_schemes.items.len;
    const savepoint = try self.types.createSavepoint();
    self.probe_depth += 1;
    return .{
        .check = self,
        .env = env,
        .deferred_constraints_len = if (env) |probe_env|
            probe_env.deferred_static_dispatch_constraints.items.items.len
        else
            0,
        .regions_len = regions_len,
        .instantiation_dispatchers_len = instantiation_dispatchers_len,
        .instantiation_dispatchers_checked = self.instantiation_dispatchers_checked,
        .pending_scheme_requirement_dispatchers_len = pending_scheme_requirement_dispatchers_len,
        .ambiguity_candidates_len = ambiguity_candidates_len,
        .ambiguity_escalation_journal_len = ambiguity_escalation_journal_len,
        .scheme_requirement_candidates_len = scheme_requirement_candidates_len,
        .open_literal_vars_len = open_literal_vars_len,
        .open_numeral_literals_len = open_numeral_literals_len,
        .pending_tuple_accesses_len = pending_tuple_accesses_len,
        .scheme_uses_len = scheme_uses_len,
        .scheme_use_pairs_len = scheme_use_pairs_len,
        .generated_codec_derivations_len = generated_codec_derivations_len,
        .generated_codec_calls_len = generated_codec_calls_len,
        .rejected_static_dispatches_len = rejected_static_dispatches_len,
        .record_omitted_defaults_len = record_omitted_defaults_len,
        .accepted_nominal_constructor_backings_len = accepted_nominal_constructor_backings_len,
        .dispatch_target_instantiations_len = dispatch_target_instantiations_len,
        .dispatch_derivations_len = dispatch_derivations_len,
        .imported_method_schemes_len = imported_method_schemes_len,
        .savepoint = savepoint,
    };
}

/// A speculative scope whose SUCCESS is committed in place instead of being
/// rolled back and redone. Unlike a plain `Probe` (whose unifications run against
/// throwaway problem/snapshot stores precisely because they never survive), a
/// commit-probe runs its unifications through the REAL `runUnify` wrapper—full
/// bookkeeping: fresh vars ranked into the caller env's var pool, regions
/// stamped, and deferred dispatch constraints copied out. Its unification
/// methods hardcode `.write_no_report`: a failed speculative relation is rolled
/// back before its caller reports or poisons anything. The ordinary poisoning
/// wrappers assert if called while this savepoint is active. On failure the
/// probe must rewind everything that bookkeeping grew:
///   - problems / snapshots recorded by any other in-probe operation;
///   - the caller env's var-pool rank lists (entries for vars the savepoint
///     rollback just discarded would dangle into the generalizer);
///   - the caller env's deferred dispatch constraints (their receivers and
///     constraint ranges were rolled back with the type store).
const CommitProbe = struct {
    check: *Self,
    env: *Env,
    probe: Probe,
    problems_len: usize,
    extra_strings_len: usize,
    missing_patterns_len: usize,
    snapshots_mark: SnapshotStore.Mark,

    fn unify(self: *CommitProbe, a: Var, b: Var) std.mem.Allocator.Error!unifier.Result {
        return self.check.runUnify(a, b, self.env, .{ .on_mismatch = .write_no_report });
    }

    fn unifyInContext(self: *CommitProbe, a: Var, b: Var, ctx: problem.Context) std.mem.Allocator.Error!unifier.Result {
        return self.check.runUnify(a, b, self.env, unifyOptionsForContext(ctx, .write_no_report));
    }

    fn rollback(self: *CommitProbe) void {
        std.debug.assert(self.check.commit_probe_active);
        self.check.commit_probe_active = false;
        self.probe.rollback();
        // `truncate` rewinds only the problem entries; the string/pattern backing
        // arrays are assumed untouched by probe paths (only exhaustiveness
        // checking writes them, and it never runs inside a probe). Assert that so
        // a future probe path that grows them fails loudly instead of leaking
        // entries past the rollback.
        std.debug.assert(self.check.problems.extra_strings_backing.items.len == self.extra_strings_len);
        std.debug.assert(self.check.problems.missing_patterns_backing.items.len == self.missing_patterns_len);
        self.check.problems.truncate(self.problems_len);
        self.check.snapshots.truncateToMark(self.snapshots_mark);
        for (self.check.probe_var_pool_lens.items, 0..) |pool_len, rank_idx| {
            self.env.var_pool.shrinkRank(@enumFromInt(rank_idx), pool_len);
        }
    }

    fn commit(self: *CommitProbe) void {
        std.debug.assert(self.check.commit_probe_active);
        self.check.commit_probe_active = false;
        self.probe.commit();
    }
};

fn beginCommitProbe(self: *Self, env: *Env) std.mem.Allocator.Error!CommitProbe {
    // Commit-probes must not nest: a nested `beginCommitProbe` would clobber the
    // shared `probe_var_pool_lens` buffer the outer probe's rollback depends on.
    if (self.probe_depth != 0) {
        @panic("commit probes cannot nest inside another solver probe");
    }
    self.commit_probe_active = true;
    errdefer self.commit_probe_active = false;
    // Capture the var pool's per-rank lengths (through the current rank): real
    // unification can rank a fresh var BELOW the current rank (it takes the min of
    // the unified descriptors), so capturing only the current rank's list would
    // miss entries.
    self.probe_var_pool_lens.clearRetainingCapacity();
    const rank_count = @intFromEnum(env.rank()) + 1;
    try self.probe_var_pool_lens.ensureTotalCapacity(self.gpa, rank_count);
    for (0..rank_count) |rank_idx| {
        const rank: Rank = @enumFromInt(rank_idx);
        self.probe_var_pool_lens.appendAssumeCapacity(env.var_pool.getVarsForRank(rank).len);
    }
    return .{
        .check = self,
        .env = env,
        .problems_len = self.problems.len(),
        .extra_strings_len = self.problems.extra_strings_backing.items.len,
        .missing_patterns_len = self.problems.missing_patterns_backing.items.len,
        .snapshots_mark = self.snapshots.mark(),
        .probe = try self.beginProbe(env),
    };
}

fn probeUnifyWithoutRecordingProblems(
    self: *Self,
    expected: Var,
    actual: Var,
) Allocator.Error!bool {
    var probe_problems = try ProblemStore.initCapacity(self.gpa, 1);
    defer probe_problems.deinit(self.gpa);

    var probe_snapshots = try SnapshotStore.initCapacity(self.gpa, 8);
    defer probe_snapshots.deinit();

    // Probe against throwaway problem/snapshot stores so a mismatch here is
    // neither recorded nor poisoned—only whether the relation was established
    // matters.
    var env = self.unifyEnv();
    env.problems = &probe_problems;
    env.snapshots = &probe_snapshots;
    const result = try unifier.unify(&env, expected, actual, .{ .on_mismatch = .write_no_report });

    return result.isEstablished();
}

/// Finalize still-open literal defaults at end of module checking, via the
/// shared interference-component machinery (`runLiteralDefaultingRounds`) over a
/// snapshot of the open-literal worklist.
///
/// HARD REQUIREMENT: top-level def order must never affect whether a program
/// type-checks or which types are inferred. The worklist (`open_literal_vars`) is
/// registered in check order, which IS def order, so the rounds must never let
/// worklist position influence a commit's outcome—see the ORDER-INDEPENDENCE
/// contract on `runLiteralDefaultingRounds`.
///
/// Already-resolved and generalized (let-polymorphic) literals are skipped to
/// preserve let-polymorphism; entries appended mid-finalize by in-probe
/// instantiation are intentionally outside the snapshot, exactly as before.
fn finalizeLiteralDefaults(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    try self.runLiteralDefaultingRounds(env, .{ .finalize = .{
        .literal_count = self.open_literal_vars.items.len,
    } });
}

/// What `finalizeTypes` is finalizing: the whole module, or a single REPL
/// expression (whose var gets the expression-scoped compatibility check the
/// module-wide passes would skip).
const FinalizeScope = union(enum) {
    module: struct {
        /// True when the caller intentionally leaves numeric defaults open
        /// (e.g. type-introspection flows that re-check with context later).
        skip_numeric_defaults: bool,
    },
    repl_expr: CIR.Expr.Idx,
};

/// Judge the recorded `.?field` accesses now that the module's types have
/// settled: an access whose presence variable resolved to the concrete
/// `present` kind is rejected—the field can never be missing, so the
/// optional access is almost certainly not what the user intended (design.md
/// "Field Kinds (All-Dynamic Optional Fields)").
///
/// The same walk pins a kind still undetermined here to `optional`: only
/// `.?` ever constrained the field, so the program treats it as optional.
/// Judged at finalize (recorded per access, resolved after types settle) so
/// both judgments are order-independent within the module.
/// Judge every not-yet-judged `.?` access (design.md "Field Kinds"):
/// rejects `.?` on a field whose kind resolved required/defaulted (always
/// present—use `.`), and pins a still-flex kind to `optional`. Called at
/// every generalization boundary—receivers are settled by then, and
/// pinning BEFORE the scheme forms is what makes the judgment survive
/// instantiation—and at finalize as the monomorphic backstop.
/// The field-kind judgment choreography run at every generalization
/// boundary: `.?`-driven optional pins land first
/// (`judgeOptionalFieldAccesses`), then destructure binders are judged
/// against the pinned rows (`judgeRecordDestructBinds`). The internal
/// ordering is load-bearing—see the two judges' doc comments—and this
/// helper is the single place it lives.
fn judgeFieldKindsAtBoundary(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    try self.judgeOptionalFieldAccesses(env);
    try self.judgeRecordUpdates(env);
    try self.judgeRecordDestructBinds(env);
}

fn judgeRecordUpdates(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    var retained: usize = 0;
    for (self.pending_record_updates.items) |pending| {
        const resolved = self.types.resolveVar(pending.presence_var);
        if (resolved.desc.content == .flex) {
            if (@intFromEnum(resolved.desc.rank) < @intFromEnum(env.rank())) {
                self.pending_record_updates.items[retained] = pending;
                retained += 1;
                continue;
            }
            const required_var = try self.freshFromContent(
                .{ .field_presence = .required },
                env,
                pending.region,
            );
            _ = try self.unify(pending.presence_var, required_var, env);
        }
    }
    self.pending_record_updates.shrinkRetainingCapacity(retained);
}

fn judgeOptionalFieldAccesses(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    var retained: usize = 0;
    var index: usize = 0;
    while (index < self.optional_field_accesses.items.len) : (index += 1) {
        const access = self.optional_field_accesses.items[index];
        const resolved = self.types.resolveVar(access.presence_var);
        switch (resolved.desc.content) {
            .field_presence => |field_presence| switch (field_presence) {
                .required, .defaulted => {
                    _ = try self.problems.appendProblem(self.gpa, .{ .optional_access_of_required_field = .{
                        .region = access.region,
                        .field_name = access.field_name,
                    } });
                },
                .optional => {},
            },
            .flex => {
                if (@intFromEnum(resolved.desc.rank) < @intFromEnum(env.rank())) {
                    self.optional_field_accesses.items[retained] = access;
                    retained += 1;
                    continue;
                }
                const optional_var = try self.freshFromContent(
                    .{ .field_presence = .optional },
                    env,
                    access.region,
                );
                _ = try self.unify(access.presence_var, optional_var, env);
            },
            .rigid, .alias, .structure, .err => {},
        }
    }
    self.optional_field_accesses.shrinkRetainingCapacity(retained);
}

/// Judge every not-yet-judged record-destructure field bind (design.md
/// "Field Kinds"): the destructure probed the record with a kind-flexible
/// presence var and left the binder unbound, so the record's OWN kind
/// directs what the binder sees:
///
/// - `required`/`defaulted`: the binder is the field's value (plain bind,
///   the pre-optional-fields semantics).
/// - `optional`: the binder is `Try(payload, [MissingField])`, constructed
///   exactly as a `.?` access's chain result (`mkTryContent` over
///   `makeFieldMissingTag`)—destructuring an optional field surfaces its
///   runtime presence, it never invents the value.
/// - still-flex: pinned to `required` FIRST (the mirror of
///   `judgeOptionalFieldAccesses`' optional pin—a destructure alone must
///   not silently make a field optional), then bound plainly.
/// - `.err` (or any poisoned content): bound plainly to the payload—the
///   kind mismatch was already reported and err absorbs; no cascade.
///
/// Called at every generalization boundary—BEFORE the boundary's literal
/// defaulting (a numeral flowing through a destructured field is only
/// signature-reachable once the binder is unified through the row, and
/// defaulting's reachability classification must see that link) and again
/// after `judgeOptionalFieldAccesses`—and at finalize as the monomorphic
/// backstop; pinning before the scheme forms is what makes the judgment
/// survive instantiation, exactly like the access judgment. Consequence of
/// the pre-defaulting pass: a field that is BOTH destructured and
/// `.?`-accessed in one def with no annotation ever pinning its kind
/// resolves destructure-first (required) at that boundary, and the `.?` is
/// then rejected as an access of an always-present field.
///
/// ALSO called at every exhaustiveness-analysis site (match expressions and
/// refutable destructure statements): the analysis and its union-closing
/// walk the SCRUTINEE type, so a destructured field's sub-pattern facts are
/// only visible to them through the row once the binder is bound. An
/// analysis site is therefore a commitment point too—a destructure whose
/// field kind is still flex there commits to `required` at the site (in
/// checking order), which is also what the pre-optional-fields `.required`
/// row demand did at pattern-check time.
fn judgeRecordDestructBinds(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    var retained: usize = 0;
    var index: usize = 0;
    while (index < self.pending_record_destructs.items.len) : (index += 1) {
        const pending = self.pending_record_destructs.items[index];
        const resolved = self.types.resolveVar(pending.presence_var);
        switch (resolved.desc.content) {
            .field_presence => |field_presence| switch (field_presence) {
                .required, .defaulted => {
                    _ = try self.unify(pending.binder_var, pending.payload_var, env);
                },
                .optional => {
                    const missing_err_var = try self.makeFieldMissingTag(env, pending.region);
                    const try_var = try self.freshFromContent(
                        try self.mkTryContent(pending.payload_var, missing_err_var),
                        env,
                        pending.region,
                    );
                    _ = try self.unify(pending.binder_var, try_var, env);
                },
            },
            .flex => {
                // A still-flex kind commits to `required` only at a
                // commitment point that OWNS the var: the boundary's
                // generalize call is about to promote exactly the vars at
                // (or above) the current rank. A lower-ranked presence var
                // belongs to an enclosing scope still mid-inference—a
                // nested boundary (an annotation predeclare or inner
                // lambda fired while checking the destructure's own RHS)
                // must not pin it before the destructure statement's own
                // unification has run. The entry stays pending for the
                // scope that owns it (finalize as the monomorphic
                // backstop, where every remaining non-generalized var is
                // at rank).
                if (@intFromEnum(resolved.desc.rank) < @intFromEnum(env.rank())) {
                    self.pending_record_destructs.items[retained] = pending;
                    retained += 1;
                    continue;
                }
                const required_var = try self.freshFromContent(
                    .{ .field_presence = .required },
                    env,
                    pending.region,
                );
                _ = try self.unify(pending.presence_var, required_var, env);
                _ = try self.unify(pending.binder_var, pending.payload_var, env);
            },
            .rigid, .alias, .structure, .err => {
                // `.err` and other poisoned contents: the kind mismatch was
                // already reported; bind the binder to the payload so its
                // uses don't cascade (err absorbs).
                _ = try self.unify(pending.binder_var, pending.payload_var, env);
            },
        }
    }
    self.pending_record_destructs.shrinkRetainingCapacity(retained);
}

/// Kind defaulting as a checker pass (design.md "Field Kinds"): commit every
/// literal-minted field kind that is still undetermined at finalize—nothing
/// ever pinned it to either kind—to `required`, the zero-cost kind, by
/// ordinary unification. After this sweep a MONOMORPHIC module-level type can
/// no longer carry a literal-minted flex kind, so the read boundaries
/// (TypeWriter rendering, checked-artifact publication, canonical-key
/// writing) read one committed fact instead of each re-applying a
/// flex-means-required convention.
///
/// A kind var whose root is GENERALIZED is skipped, permanently: it is the
/// interior of a scheme (e.g. `mk = |v| { a: v }`), and instantiations of
/// that scheme may legitimately join a `?:` annotation later—committing it
/// would mutate the scheme and change which programs typecheck. This is why
/// the sweep runs at MODULE (and REPL-expression) finalize only, never at
/// per-def generalization boundaries.
fn defaultLiteralFieldKinds(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    while (self.literal_field_kind_watermark < self.literal_field_kinds.items.len) {
        const entry = self.literal_field_kinds.items[self.literal_field_kind_watermark];
        self.literal_field_kind_watermark += 1;
        const resolved = self.types.resolveVar(entry.presence_var);
        // Only a still-flex kind defaults: `.field_presence` is already
        // committed (annotation pin, `.?` optional pin, absorption), and
        // `.err` is a poisoned kind whose mismatch was already reported.
        if (resolved.desc.content != .flex) continue;
        // Scheme interior—stays flex by design (see doc comment above).
        if (resolved.desc.rank == .generalized) continue;
        const required_var = try self.freshFromContent(
            .{ .field_presence = .required },
            env,
            entry.region,
        );
        _ = try self.unify(entry.presence_var, required_var, env);
    }
}

/// Check every recorded default expression (design.md "Defaulted Fields"),
/// once, after all defs are checked and callee effects are resolved: type
/// the default against an INSTANTIATED copy of its field's type (a
/// generalized annotation scheme must not be mutated at finalize), and
/// reject effectful defaults—the compiler materializes a default at
/// every construction site that omits the field, so it must be pure.
fn checkPendingDefaults(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    for (self.pending_default_checks.items) |pending| {
        const default_does_fx = try self.checkExpr(pending.default_expr, env, .{});
        // BACKSTOP invariant: canonicalization restricts defaults to closed
        // literals (design.md "Defaulted Fields"), and a literal is never
        // effectful, so this branch is unreachable from source. It stays as
        // a cheap guard because a default that somehow carried effects would
        // be materialized at construction sites where running them is
        // unpredictable.
        if (default_does_fx) {
            _ = try self.problems.appendProblem(self.gpa, .{ .effectful_default_value = .{
                .region = self.getRegionAt(ModuleEnv.varFrom(pending.default_expr)),
                .field_name = pending.field_name,
            } });
            // Diagnostic recovery after the reported problem (the standard
            // poisoning convention): the default's var becomes `.err`, so
            // downstream judgments treat it as an already-reported error
            // instead of a well-typed default. Unifying the poisoned var
            // against the field type would be a no-op (err absorbs), so
            // skip it.
            try self.unifyWith(ModuleEnv.varFrom(pending.default_expr), .err, env);
            continue;
        }
        const expected_field_type = try self.instantiateVar(pending.field_type_var, env, .use_last_var);
        _ = try self.unify(ModuleEnv.varFrom(pending.default_expr), expected_field_type, env);
    }
    // The list is kept for `checkDefaultRestrictions`, which runs after the
    // defaulting rounds and constraint validation settle the types.
}

/// Post-settlement restriction on defaults (design.md "Defaulted Fields"):
/// the reusable field/default pair must be CONCRETE (the default is evaluated
/// once at compile time and materialized at every construction site, so the
/// field must have exactly one runtime representation—judged after the
/// defaulting rounds so numeral defaults have committed). Checking only the
/// default expression is insufficient: unifying a literal with an instantiated
/// copy of a parametric field type can make that copy concrete while leaving
/// the declared field polymorphic.
fn checkDefaultRestrictions(self: *Self) std.mem.Allocator.Error!void {
    var recursive_defaults: std.ArrayList(PendingDefaultCheck) = .empty;
    defer recursive_defaults.deinit(self.gpa);

    for (self.pending_default_checks.items) |pending| {
        // An erroring default already reported (effectful poisoning above, or
        // a unify mismatch against its field type—both leave the var `.err`);
        // judging concreteness of an err var would cascade a second problem
        // onto the same default.
        if (self.types.resolveVar(ModuleEnv.varFrom(pending.default_expr)).desc.content == .err) continue;
        const default_is_concrete = try self.varIsConcreteHoistedConstType(ModuleEnv.varFrom(pending.default_expr));
        const field_is_concrete = try self.varIsConcreteHoistedConstType(pending.field_type_var);
        if (!default_is_concrete or !field_is_concrete) {
            _ = try self.problems.appendProblem(self.gpa, .{ .non_concrete_default_value = .{
                .region = self.getRegionAt(ModuleEnv.varFrom(pending.default_expr)),
                .field_name = pending.field_name,
            } });
        }
        if (try self.defaultMaterializationIsRecursive(pending.default_expr)) {
            try recursive_defaults.append(self.gpa, pending);
        }
    }

    // Diagnose every cycle against the original checked expressions before
    // applying error recovery; poisoning one side of a mutual cycle must not
    // hide the other side's cycle from this judgment.
    const omitted_defaults = try self.gpa.dupe(
        ModuleEnv.RecordOmittedDefault,
        self.cir.record_omitted_defaults.items.items,
    );
    defer self.gpa.free(omitted_defaults);

    for (recursive_defaults.items) |pending| {
        const region = self.cir.store.getExprRegion(pending.default_expr);
        _ = try self.problems.appendProblem(self.gpa, .{ .recursive_default_value = .{
            .region = region,
            .field_name = pending.field_name,
        } });

        // The checked-module pipeline still builds an artifact after type
        // errors so it can render diagnostics. Replace the rejected default
        // before that boundary; otherwise post-check lowering tries to
        // materialize the same default forever.
        const diagnostic_idx = try self.cir.addDiagnostic(.{ .erroneous_value_expr = .{
            .region = region,
        } });

        // A construction that omits this rejected default would otherwise
        // restore the replacement runtime-error expression during postcheck
        // or compile-time evaluation. Match the checker's exact omission
        // identity and replace those construction sites without reporting a
        // second problem.
        for (omitted_defaults) |omitted| {
            if (omitted.origin_module != self.cir.selfModuleIdentity()) continue;
            if (omitted.default_expr_node != @intFromEnum(pending.default_expr)) continue;
            if (self.cir.store.getExpr(omitted.expr) == .e_runtime_error) continue;
            try self.replaceExprWithRuntimeError(omitted.expr, diagnostic_idx);
            try self.erroneous_value_exprs.put(self.gpa, omitted.expr, {});
        }

        try self.replaceExprWithRuntimeError(pending.default_expr, diagnostic_idx);
        try self.erroneous_value_exprs.put(self.gpa, pending.default_expr, {});
    }

    self.pending_default_checks.clearRetainingCapacity();
}

/// Whether materializing `root` transitively omits a field carrying `root` as
/// its own default. This is an explicit dependency walk over checked literal
/// expressions and their solved record rows: every omitted defaulted field
/// contributes its `DefaultId`, and local identities resolve directly to the
/// corresponding CIR expression. Foreign defaults were already validated in
/// their declaring module, and the module import graph cannot cycle.
fn defaultMaterializationIsRecursive(self: *Self, root: CIR.Expr.Idx) std.mem.Allocator.Error!bool {
    const target_expr_node: u32 = @intFromEnum(root);
    const self_module = self.cir.selfModuleIdentity();

    var expr_work: std.ArrayList(CIR.Expr.Idx) = .empty;
    defer expr_work.deinit(self.gpa);
    try expr_work.append(self.gpa, root);

    var visited_defaults: std.AutoHashMapUnmanaged(u32, void) = .empty;
    defer visited_defaults.deinit(self.gpa);

    while (expr_work.pop()) |expr_idx| {
        const expr = self.cir.store.getExpr(expr_idx);
        switch (expr) {
            .e_unary_minus => |unary| try expr_work.append(self.gpa, unary.expr),
            .e_str => |str| try expr_work.appendSlice(self.gpa, self.cir.store.sliceExpr(str.span)),
            .e_list => |list| try expr_work.appendSlice(self.gpa, self.cir.store.sliceExpr(list.elems)),
            .e_tuple => |tuple| try expr_work.appendSlice(self.gpa, self.cir.store.sliceExpr(tuple.elems)),
            .e_tag => |tag| try expr_work.appendSlice(self.gpa, self.cir.store.sliceExpr(tag.args)),
            .e_nominal => |nominal| try expr_work.append(self.gpa, nominal.backing_expr),
            .e_nominal_external => |nominal| try expr_work.append(self.gpa, nominal.backing_expr),
            .e_empty_record => {
                if (try self.appendOmittedDefaultDependencies(
                    expr_idx,
                    &.{},
                    self_module,
                    target_expr_node,
                    &visited_defaults,
                    &expr_work,
                )) return true;
            },
            .e_record => |record| {
                const fields = self.cir.store.sliceRecordFields(record.fields);
                if (try self.appendOmittedDefaultDependencies(
                    expr_idx,
                    fields,
                    self_module,
                    target_expr_node,
                    &visited_defaults,
                    &expr_work,
                )) return true;
                for (fields) |field_idx| {
                    try expr_work.append(self.gpa, self.cir.store.getRecordField(field_idx).value);
                }
            },
            .e_num,
            .e_frac_f32,
            .e_frac_f64,
            .e_dec,
            .e_dec_small,
            .e_num_from_numeral,
            .e_typed_int,
            .e_typed_frac,
            .e_typed_num_from_numeral,
            .e_str_segment,
            .e_empty_list,
            .e_zero_argument_tag,
            => {},
            // Canonicalization admits only the literal forms above. An error
            // elsewhere can replace a child with another expression kind; it
            // has already produced a diagnostic and contributes no usable
            // default-materialization dependency.
            .e_bytes_literal,
            .e_lookup_local,
            .e_lookup_external,
            .e_lookup_associated_local,
            .e_lookup_associated,
            .e_lookup_associated_resolved,
            .e_lookup_required,
            .e_block,
            .e_match,
            .e_if,
            .e_call,
            .e_closure,
            .e_lambda,
            .e_binop,
            .e_unary_not,
            .e_field_access,
            .e_method_call,
            .e_dispatch_call,
            .e_interpolation,
            .e_structural_eq,
            .e_structural_hash,
            .e_method_eq,
            .e_type_method_call,
            .e_type_dispatch_call,
            .e_tuple_access,
            .e_runtime_error,
            .e_crash,
            .e_dbg,
            .e_expect_err,
            .e_expect,
            .e_ellipsis,
            .e_anno_only,
            .e_derived_method,
            .e_return,
            .e_for,
            .e_break,
            .e_hosted_lambda,
            .e_run_low_level,
            => {},
        }
    }
    return false;
}

fn recordLiteralSuppliesField(
    self: *const Self,
    fields: []const CIR.RecordField.Idx,
    field_name: Ident.Idx,
) bool {
    for (fields) |field_idx| {
        if (self.cir.store.getRecordField(field_idx).name == field_name) return true;
    }
    return false;
}

/// Append the local default expressions that `record_expr` materializes by
/// omission. Returns true immediately when one is the target default.
fn appendOmittedDefaultDependencies(
    self: *Self,
    record_expr: CIR.Expr.Idx,
    supplied_fields: []const CIR.RecordField.Idx,
    self_module: base.ModuleIdentity.Idx,
    target_expr_node: u32,
    visited_defaults: *std.AutoHashMapUnmanaged(u32, void),
    expr_work: *std.ArrayList(CIR.Expr.Idx),
) std.mem.Allocator.Error!bool {
    var current = ModuleEnv.varFrom(record_expr);
    var visited_rows: std.AutoHashMapUnmanaged(Var, void) = .empty;
    defer visited_rows.deinit(self.gpa);

    while (true) {
        const resolved = self.types.resolveVar(current);
        const seen = try visited_rows.getOrPut(self.gpa, resolved.var_);
        if (seen.found_existing) return false;

        switch (resolved.desc.content) {
            .alias => |alias| current = self.types.getAliasBackingVar(alias),
            .structure => |flat| switch (flat) {
                .record => |record| {
                    if (try self.appendDefaultsFromRecordFields(
                        record.fields,
                        supplied_fields,
                        self_module,
                        target_expr_node,
                        visited_defaults,
                        expr_work,
                    )) return true;
                    current = record.ext;
                },
                .record_unbound => |fields| return try self.appendDefaultsFromRecordFields(
                    fields,
                    supplied_fields,
                    self_module,
                    target_expr_node,
                    visited_defaults,
                    expr_work,
                ),
                .empty_record => return false,
                .tuple,
                .nominal_type,
                .fn_pure,
                .fn_effectful,
                .fn_unbound,
                .tag_union,
                .empty_tag_union,
                => return false,
            },
            .flex, .rigid, .field_presence, .err => return false,
        }
    }
}

fn appendDefaultsFromRecordFields(
    self: *Self,
    fields_range: types_mod.RecordField.SafeMultiList.Range,
    supplied_fields: []const CIR.RecordField.Idx,
    self_module: base.ModuleIdentity.Idx,
    target_expr_node: u32,
    visited_defaults: *std.AutoHashMapUnmanaged(u32, void),
    expr_work: *std.ArrayList(CIR.Expr.Idx),
) std.mem.Allocator.Error!bool {
    const fields = self.types.getRecordFieldsSlice(fields_range);
    for (fields.items(.name), fields.items(.presence)) |field_name, presence| {
        if (self.recordLiteralSuppliesField(supplied_fields, field_name)) continue;
        const presence_var = presence.presenceVar() orelse continue;
        const presence_content = self.types.resolveVar(presence_var).desc.content;
        if (presence_content != .field_presence or presence_content.field_presence != .defaulted) continue;
        const default_id = presence_content.field_presence.defaulted;
        if (default_id.origin_module != self_module) continue;
        if (default_id.expr_node == target_expr_node) return true;
        const seen = try visited_defaults.getOrPut(self.gpa, default_id.expr_node);
        if (!seen.found_existing) {
            try expr_work.append(self.gpa, @enumFromInt(default_id.expr_node));
        }
    }
    return false;
}

/// THE type-finalization point: every checking entry point (module check and
/// both REPL flavors) lands here exactly once, after its own constraint
/// traversal. Literal defaults are decided here—by the defaulting oracle
/// (src/types/literal_defaulting.zig) driving `runLiteralDefaultingRounds`—
/// and every validation that needs final types (open-numeral range checks,
/// default-type method compatibility, instantiated dispatch constraints)
/// runs after the decision, so dispatch plans and evidence freeze only on
/// finalized types.
///
/// The generalization-boundary defaulting (`defaultLiteralsAtGeneralizationBoundary`)
/// is NOT a second decision point: it runs the same engine under the same
/// oracle for the vars a def's generalize call is about to promote—a rank
/// constraint (the leak warning and let-polymorphism filtering must see
/// pre-promotion ranks), not a separate policy.
fn finalizeTypes(self: *Self, env: *Env, scope: FinalizeScope) std.mem.Allocator.Error!void {
    // Defaults check first: every def is checked (so their references
    // instantiate finished schemes and callee effects are resolved), and the
    // default expressions' own numerals/constraints must still flow through
    // the defaulting rounds and constraint validation below (design.md
    // "Defaulted Fields").
    try self.checkPendingDefaults(env);
    try self.judgeFieldKindsAtBoundary(env);

    try self.checkAllConstraints(env);
    try self.resolvePendingTupleAccesses(env, false);
    try self.checkAllConstraints(env);

    try self.resolveNumericLiteralsFromContext(env);
    const run_defaults = switch (scope) {
        .module => |module| !module.skip_numeric_defaults,
        .repl_expr => true,
    };
    if (run_defaults) {
        try self.finalizeLiteralDefaults(env);

        // Committing a default can spawn deferred static-dispatch
        // constraints (e.g. Dec.plus, Dec.to_str returning Str); resolve
        // them so the validations below see settled types.
        if (env.deferred_static_dispatch_constraints.items.items.len > 0) {
            try self.checkStaticDispatchConstraints(env, true);
            try self.checkAllConstraints(env);
        }
    }

    switch (scope) {
        .module => {
            try self.validateToInspectMethodTypes(env);
            try self.checkAllFromNumeralFlexConstraintCompatibility(env, true);
        },
        // The REPL result expression is not module state; its type may have
        // incompatible constraints (e.g. !3) the module-wide walk over open
        // literal vars would not visit.
        .repl_expr => |expr_idx| {
            _ = try self.checkFlexVarConstraintCompatibility(ModuleEnv.varFrom(expr_idx), env, true, .{});
        },
    }
    try self.validateResolvedOpenNumeralLiterals(env);
    if (scope == .module) {
        try self.checkInstantiatedStaticDispatchConstraints(env, true);
        try self.checkGroundedStoredTypeSchemeRequirementsAtFinalization(env, true);
    }
    try self.resolvePendingTupleAccesses(env, true);
    try self.checkAllConstraints(env);
    try self.checkDefaultRestrictions();

    // LAST, deliberately: every acceptance/rejection judgment above—
    // `judgeOptionalFieldAccesses` (which may pin a literal-minted kind to
    // `optional` first), the literal-defaulting rounds and the constraint
    // validations (whose commits can run rows together and pin kinds from
    // annotations), and `checkDefaultRestrictions`—must run on the exact
    // pre-commit states, so the sweep is a pure commitment of already-final
    // facts and cannot alter any accept/reject outcome. Nothing after
    // finalize unifies types, so a kind committed here is a fact every
    // consumer reads.
    try self.defaultLiteralFieldKinds(env);
}

/// The candidate universe `runLiteralDefaultingRounds` gathers from—the only
/// structural difference between module finalize and a def's generalization
/// boundary. Both lengths are SNAPSHOTS taken before the first round: committing
/// a default appends fresh vars (default candidates, in-probe instantiations) to
/// the same worklist / pool entry, and those must never be rescanned by a later
/// round.
const LiteralDefaultUniverse = union(enum) {
    /// `finalizeLiteralDefaults`: the first `literal_count` entries of the
    /// open-literal worklist; a candidate is still flex, not generalized
    /// (let-polymorphism preserved), with literal-conversion provenance.
    finalize: struct { literal_count: usize },
    /// `defaultLiteralsAtGeneralizationBoundary`: the first `pool_len` entries of
    /// the var-pool rank the boundary's generalize call will promote; a candidate
    /// is still flex AT that rank with literal-conversion provenance AND not
    /// signature-reachable (`boundary_reachable_vars`, populated by the caller for
    /// the current boundary before the rounds run)—signature-reachable literals
    /// must stay open so generalization quantifies them. The pool slice is
    /// re-fetched every round (commits can grow and reallocate the pool), but only
    /// the snapshotted prefix is scanned. Boundary commits additionally carry the
    /// per-literal LITERAL DEFAULTED leak warning (see
    /// `boundaryWarningBeforeCommit`).
    boundary: struct { rank: Rank, pool_len: usize },
};

/// Default every still-open literal in `universe`—ORDER-INDEPENDENT BY
/// CONSTRUCTION. Shared core of `finalizeLiteralDefaults` and
/// `defaultLiteralsAtGeneralizationBoundary`.
///
/// A commit-one-by-one implementation (in worklist or var-pool order) is unsound
/// here: a literal's first-satisfier probe can "satisfy" a constraint by
/// speculatively pinning a still-open PEER literal (or a flex var another open
/// literal's constraints also reach) without consulting that peer's own
/// constraints—so whichever literal came first won, and reordering defs (or
/// statements within a def) flipped programs between accept and reject.
///
/// Structure: rounds, each over the universe snapshot taken at entry.
///
///   1. GATHER the still-open literal roots from the universe (per-universe
///      filters documented on `LiteralDefaultUniverse`); deduped by union-find
///      root.
///   2. PARTITION them into interference components. A literal with
///      non-literal constraints (a DRIVER) owns a footprint: every
///      still-flex root reachable from those constraints' fn signatures
///      (`collectReachableVars`, which recurses through nested constraint
///      signatures, so the footprint is transitively closed). A literal with only
///      literal-conversion provenance (a PASSIVE) has footprint {itself}. Two
///      literals share a component iff their footprints intersect. Only
///      still-flex roots interfere: a commit pins exactly the flex vars its
///      unifications reach, all inside the committing literal's footprint—so
///      disjoint components cannot observe each other's commits, and
///      concrete/rigid/err vars cannot be re-pinned by anyone.
///   3. COMMIT each component:
///        - lone passive: canonical head default (Dec), as before;
///        - single driver: the existing first-satisfier probe
///          (`commitLiteralDefault`). Its in-probe pinning of the component's
///          passives is now sound: every var it can pin lies inside this
///          component, so no OTHER pending literal's constraints are speculated
///          away;
///        - several drivers: `commitLiteralGroupDefault`—one shared candidate
///          for the whole group, the first candidate satisfying ALL the drivers'
///          constraints simultaneously.
///      Passives inside a driver's component are NOT committed this round: their
///      type is the drivers' business (the probe or the cascade pins them). If
///      the resolved method signatures leave one open, it becomes a lone passive
///      next round and defaults canonically then.
///   4. CASCADE the deferred dispatches the commits unblocked, to fixpoint, so
///      pins propagate across multi-hop dispatch chains before the next round
///      re-gathers. One pass can be too few—a constraint re-defers while its
///      receiver is flex AT VISIT TIME, so a dispatch pinned by a later commit in
///      the same pass waits for the next one. Each pass consumes every resolved
///      receiver. A selected method target records the exact parent edge that
///      derived each child; repeating the same canonical receiver/callable
///      state with the same binding is rejected as recursive dispatch, so a genuinely
///      finite chain is never truncated. `is_numeric_default_pass = true`:
///      any receiver that became concrete since the previous pass did so because
///      we just defaulted it, so error reporting must treat it as
///      defaulted-from-a-literal.
///
/// ORDER-INDEPENDENCE: the gathered SET of literal roots, each literal's
/// constraint SET, and therefore the component partition depend only on the
/// program's constraint graph, never on worklist/pool order. Commits of distinct
/// components touch disjoint flex vars (their footprints), so component commit
/// order is unobservable. A multi-driver group assigns the same candidate to
/// every driver before checking anything, then verifies the conjunction of all
/// the drivers' constraints; a conjunction of unifications succeeds iff the
/// equation set is simultaneously unifiable, independent of equation order—so
/// driver enumeration order is unobservable too. The single-driver probe consults
/// only that driver's own constraint set, in canonical candidate order—no order
/// input there either.
///
/// TERMINATION: rounds iterate a universe snapshot of fixed length, and an open
/// literal can only go flex -> resolved (probe rollbacks restore exactly the
/// pre-probe state). Every round with a non-empty gather commits at least one
/// literal: every component contains a lone passive or at least one driver, all
/// committed, and a commit always resolves the var away from flex (candidate on
/// success, the head default—possibly merging to `.err`—otherwise). Passives
/// deferred behind drivers become lone passives once their drivers resolve, so
/// rounds <= snapshot length + 1. The per-round cascade terminates by
/// `checkStaticDispatchConstraints`' own consume-or-re-defer contract (see
/// `anyDeferredDispatchReceiverResolved`) and its semantic dispatch-cycle
/// detection.
fn runLiteralDefaultingRounds(self: *Self, env: *Env, universe: LiteralDefaultUniverse) std.mem.Allocator.Error!void {
    // Round zero: semantic judgments immediately before this boundary can
    // ground a deferred receiver without adding an ordinary constraint. Let
    // every such relation propagate through its callable signature before we
    // classify any literal as an unconstrained default candidate.
    try self.quiesceConstraints(env, false);

    // Round-scoped scratch. Front-loaded as Check fields; cleared at the start
    // of each step. Safe despite cascade reentrancy: every buffer is cleared
    // before use and never read across the step-4 cascade.

    // Conflicted-default entries recorded by THIS invocation's commits are
    // consumed by its own step-4 cascades (see the scoping contract on
    // `conflicted_default_literal_vars`); drop exactly them on exit—a
    // watermark rather than a clear, so an invocation reentered from a
    // cascade (a delayed def's generalization boundary) cannot drop entries an
    // enclosing invocation's cascade still owns.
    const conflicted_defaults_watermark = self.conflicted_default_literal_vars.items.len;
    defer self.conflicted_default_literal_vars.shrinkRetainingCapacity(conflicted_defaults_watermark);

    while (true) {
        // --- 1. Gather the still-open literal roots (deduped). ---
        self.literal_defaulting_open_roots.clearRetainingCapacity();
        self.literal_defaulting_seen_roots.clearRetainingCapacity();
        switch (universe) {
            .finalize => |finalize| {
                for (self.open_literal_vars.items[0..finalize.literal_count]) |literal_var| {
                    const resolved = self.types.resolveVar(literal_var);
                    if (resolved.desc.content != .flex) continue;
                    if (resolved.desc.rank == .generalized) continue;
                    if (self.varLiteralKind(resolved.var_) == null) continue;
                    const gop = try self.literal_defaulting_seen_roots.getOrPut(resolved.var_);
                    if (gop.found_existing) continue;
                    try self.literal_defaulting_open_roots.append(self.gpa, resolved.var_);
                }
            },
            .boundary => |boundary| {
                // Re-fetch the pool slice each round (commits may have grown and
                // reallocated it) but scan only the snapshotted prefix: defaulting
                // appends fresh default vars to this same pool entry, and those
                // must not be rescanned.
                for (env.var_pool.getVarsForRank(boundary.rank)[0..boundary.pool_len]) |pool_var| {
                    const resolved = self.types.resolveVar(pool_var);
                    if (resolved.desc.content != .flex) continue;
                    if (resolved.desc.rank != boundary.rank) continue;
                    if (self.varLiteralKind(resolved.var_) == null) continue;
                    // A signature-reachable literal stays open (let-polymorphic) and
                    // generalizes—quotes and interpolations included (interpolations
                    // are publishable while open thanks to the checked-interpolation
                    // reachability handling). A zero-arg thunk's return is
                    // signature-reachable too, so its literal also stays open; the
                    // thunk simply generalizes as a polymorphic function (see
                    // `reportPolymorphicTopLevelValues`).
                    if (self.boundary_reachable_vars.contains(resolved.var_)) continue;
                    const gop = try self.literal_defaulting_seen_roots.getOrPut(resolved.var_);
                    if (gop.found_existing) continue;
                    try self.literal_defaulting_open_roots.append(self.gpa, resolved.var_);
                }
            },
        }
        if (self.literal_defaulting_open_roots.items.len == 0) return;

        // --- 1b. Default unambiguous quote literals before ambiguous numerals. ---
        // A quote literal has exactly one possible type (Str), so committing it is
        // never a guess. A numeral's first-satisfier probe IS a guess: when several
        // candidate types satisfy its constraints it commits the head candidate
        // (Dec). Resolving every open quote first—and letting step 4's cascade
        // propagate the dispatches that unblocks—lets a producer dispatch whose
        // receiver is a string (e.g. `s.count_utf8_bytes() : Str -> U64`) pin a
        // numeral's type BEFORE the numeral would otherwise be guessed. Without
        // this, `intermediate.count_utf8_bytes() > 0` commits `0` to Dec (the head
        // `is_gt` candidate, since the `count_utf8_bytes` dispatch is still latent
        // behind the receiver's own open quote literal) and then conflicts when the
        // Str-keyed dispatch resolves to U64.
        //
        // Numerals are only held back while a quote is actually open; once the
        // quote round(s) have cascaded, numerals default through the unchanged
        // component machinery below. The quote/numeral split is a pure function of
        // the gathered kinds, so order-independence is preserved, and termination
        // holds because every non-empty round still commits at least one literal (a
        // quote if any is open, else a numeral).
        {
            var any_quote = false;
            for (self.literal_defaulting_open_roots.items) |root| {
                if (self.varLiteralKind(root) == .quote) {
                    any_quote = true;
                    break;
                }
            }
            if (any_quote) {
                var write_idx: usize = 0;
                for (self.literal_defaulting_open_roots.items) |root| {
                    if (self.varLiteralKind(root) != .quote) continue;
                    self.literal_defaulting_open_roots.items[write_idx] = root;
                    write_idx += 1;
                }
                self.literal_defaulting_open_roots.shrinkRetainingCapacity(write_idx);
            }
        }

        // --- 2. Partition into interference components. ---
        self.literal_defaulting_component_parent.clearRetainingCapacity();
        self.literal_defaulting_is_driver.clearRetainingCapacity();
        self.literal_defaulting_footprint_owner.clearRetainingCapacity();
        for (self.literal_defaulting_open_roots.items, 0..) |root, idx| {
            try self.literal_defaulting_component_parent.append(self.gpa, idx);
            // Seed each literal's own root so any driver whose footprint reaches
            // it is merged into its component. Roots are deduped, so no collision
            // is possible here.
            try self.literal_defaulting_footprint_owner.putNoClobber(root, idx);
        }
        for (self.literal_defaulting_open_roots.items, 0..) |root, idx| {
            const constraint_range = self.types.resolveVar(root).desc.content.flex.constraints;
            const drives = self.rangeHasNonLiteralConstraint(constraint_range);
            try self.literal_defaulting_is_driver.append(self.gpa, drives);
            if (!drives) continue;

            try self.collectConstraintSignatureReachable(constraint_range, &self.literal_defaulting_footprint);
            var fp_iter = self.literal_defaulting_footprint.keyIterator();
            while (fp_iter.next()) |fp_var| {
                // Only still-flex roots interfere; everything else is immune to
                // pinning. (Union order is irrelevant: unions commute, so the
                // partition is independent of hash-map iteration order.)
                if (self.types.resolveVar(fp_var.*).desc.content != .flex) continue;
                const gop = try self.literal_defaulting_footprint_owner.getOrPut(fp_var.*);
                if (gop.found_existing) {
                    componentUnion(self.literal_defaulting_component_parent.items, idx, gop.value_ptr.*);
                } else {
                    gop.value_ptr.* = idx;
                }
            }
        }

        // --- 3. Commit every component (disjoint, so order is unobservable). ---
        for (0..self.literal_defaulting_open_roots.items.len) |leader| {
            if (componentFind(self.literal_defaulting_component_parent.items, leader) != leader) continue;
            self.literal_defaulting_group_drivers.clearRetainingCapacity();
            var member_count: usize = 0;
            // A candidate the component commits pins EVERY member literal, so
            // the digit-fit precheck must consult every member's exact value
            // facts—not just the driver's own. Intersecting the members'
            // precomputed fit sets keeps the check O(1) per candidate and
            // makes the outcome independent of which member carries the
            // driving constraint (mirror-image programs commit identically).
            var component_fits = exact_numeral.FitSet.initFull();
            for (self.literal_defaulting_open_roots.items, 0..) |member_root, member_idx| {
                if (componentFind(self.literal_defaulting_component_parent.items, member_idx) != leader) continue;
                member_count += 1;
                const member_range = self.types.resolveVar(member_root).desc.content.flex.constraints;
                for (self.types.sliceStaticDispatchConstraints(member_range)) |constraint| {
                    if (constraint.origin.numeralInfo()) |info| {
                        component_fits = component_fits.intersectWith(info.fits);
                    }
                }
                if (self.literal_defaulting_is_driver.items[member_idx]) {
                    try self.literal_defaulting_group_drivers.append(self.gpa, member_root);
                }
            }
            // Within a round, every gathered root is still flex with its
            // literal-conversion provenance when its component commits: commits
            // of OTHER components only touch their own (disjoint) footprints, and
            // this component commits exactly once. So the kind lookups below
            // cannot fail—gather guaranteed them non-null.
            if (self.literal_defaulting_group_drivers.items.len == 0) {
                // A component without drivers is a lone passive (a passive's
                // footprint is just itself, so only a driver can merge it).
                std.debug.assert(member_count == 1);
                const passive_root = self.literal_defaulting_open_roots.items[leader];
                const kind = self.varLiteralKind(passive_root) orelse unreachable;
                try self.commitGatheredLiteral(passive_root, kind, component_fits, universe, env);
            } else if (self.literal_defaulting_group_drivers.items.len == 1) {
                const driver_root = self.literal_defaulting_group_drivers.items[0];
                const kind = self.varLiteralKind(driver_root) orelse unreachable;
                try self.commitGatheredLiteral(driver_root, kind, component_fits, universe, env);
            } else {
                try self.commitGatheredGroup(self.literal_defaulting_group_drivers.items, component_fits, &self.literal_defaulting_group_warnings, universe, env);
            }
        }

        // --- 4. Cascade the constraints the commits unblocked. ---
        try self.quiesceConstraints(env, true);
    }
}

/// Commit one gathered literal root (lone passive or single driver) via the
/// single-literal first-satisfier probe—plus, at a generalization boundary, the
/// per-literal LITERAL DEFAULTED leak warning. The leak check and warning region
/// capture run while the literal is still flex (before the commit resolves it);
/// the warning is emitted after, rendered from the committed default var.
fn commitGatheredLiteral(
    self: *Self,
    root: Var,
    kind: StaticDispatchConstraint.LiteralKind,
    component_fits: exact_numeral.FitSet,
    universe: LiteralDefaultUniverse,
    env: *Env,
) std.mem.Allocator.Error!void {
    switch (universe) {
        .finalize => _ = try self.commitLiteralDefault(root, kind, component_fits, env),
        .boundary => {
            const pending = try self.boundaryWarningBeforeCommit(root);
            const default_var = try self.commitLiteralDefault(root, kind, component_fits, env);
            try self.emitBoundaryWarningAfterCommit(pending, root, default_var);
        },
    }
}

/// Commit a multi-driver literal component via the shared group probe—plus, at
/// a generalization boundary, a per-driver LITERAL DEFAULTED leak warning
/// bracketing the commit, exactly as `commitGatheredLiteral` does for the single
/// case. `warnings_scratch` is a caller-owned reused buffer (cleared here).
///
/// BOUNDARY WARNING SEMANTICS FOR GROUPS: the leak check is per literal (it walks
/// one literal's constraint signatures), so it runs for EVERY group member
/// pre-commit—while all drivers are still flex—and each leaking member gets
/// its own LITERAL DEFAULTED warning post-commit, exactly as if it had committed
/// alone. Non-leaking members default silently (def-local), and the component's
/// passives are never committed here, matching the single-commit paths.
fn commitGatheredGroup(
    self: *Self,
    drivers: []const Var,
    component_fits: exact_numeral.FitSet,
    warnings_scratch: *std.ArrayListUnmanaged(PendingBoundaryWarning),
    universe: LiteralDefaultUniverse,
    env: *Env,
) std.mem.Allocator.Error!void {
    switch (universe) {
        .finalize => try self.commitLiteralGroupDefault(drivers, component_fits, env),
        .boundary => {
            warnings_scratch.clearRetainingCapacity();
            for (drivers) |driver| {
                try warnings_scratch.append(self.gpa, try self.boundaryWarningBeforeCommit(driver));
            }
            try self.commitLiteralGroupDefault(drivers, component_fits, env);
            // The group commit unified each driver with its committed var, so the
            // driver root itself renders the committed type for the snapshot.
            for (drivers, warnings_scratch.items) |driver, pending| {
                try self.emitBoundaryWarningAfterCommit(pending, driver, driver);
            }
        },
    }
}

/// Union-find `find` with path compression over the per-round component index
/// array in `runLiteralDefaultingRounds`.
fn componentFind(parent: []usize, idx: usize) usize {
    var root = idx;
    while (parent[root] != root) root = parent[root];
    var cur = idx;
    while (parent[cur] != cur) {
        const next = parent[cur];
        parent[cur] = root;
        cur = next;
    }
    return root;
}

/// Union-find `union` for `componentFind`. Commutative and associative, so the
/// resulting partition does not depend on the order unions are performed.
fn componentUnion(parent: []usize, a: usize, b: usize) void {
    const root_a = componentFind(parent, a);
    const root_b = componentFind(parent, b);
    if (root_a != root_b) parent[root_b] = root_a;
}

/// GROUP DEFAULT POLICY for a component with SEVERAL drivers: mutually
/// constrained open literals where no single literal's first-satisfier scan may
/// run alone (it would speculatively pin its peers while ignoring their
/// constraints—the order-dependence `runLiteralDefaultingRounds` exists to
/// prevent). The group defaults TOGETHER against the canonical candidate list:
/// the first candidate satisfying the WHOLE group's constraints wins.
///
/// MIXED KINDS: a group may contain quote drivers alongside numeral drivers (e.g.
/// `"s".foo(y)` and `1.bar(y)` interfering through `y`). A quote driver's
/// candidate list is the single entry Str, so it is assigned Str on every attempt
/// while the numeral scan iterates its list; an all-quote group needs exactly one
/// attempt.
///
/// Per candidate, inside one commit-probe:
///   phase 1—assign: unify EVERY driver (all still flex; the round committed
///     nothing else in this component) with its own fresh candidate var. All
///     assignments happen before any constraint is consulted, so no driver's
///     verification can observe a not-yet-assigned peer.
///   phase 2—verify: check every driver's every non-literal constraint
///     against the candidate (`staticDispatchConstraintAcceptsCandidate`, the
///     same check the single-literal probe uses). Passives and other in-footprint
///     vars are pinned here by the resolved method signatures—with every driver
///     already concrete, the verification is a plain conjunction of unifications.
/// Success commits the probe in place; failure rolls everything back and the next
/// candidate is tried.
///
/// ORDER-INDEPENDENCE: phase 1's outcome is the same var-disjoint assignment
/// regardless of driver enumeration order; phase 2 succeeds iff its equation set
/// is simultaneously unifiable, which is order-independent. So the chosen
/// candidate—and the types it pins—depend only on the group's constraint set
/// and the canonical candidate order.
///
/// The structural refutation pre-filter (`numeralCandidateStructurallyRefuted`)
/// is deliberately NOT consulted here: its safety-build witness guard is specified
/// against the single-literal probe (`commitLiteralDefault`), and multi-driver
/// groups are rare enough that probing every candidate directly costs nothing
/// measurable. (The bench counters likewise stay singleton-only.)
///
/// When no candidate satisfies the group, each driver falls back to its kind's
/// canonical head default (`commitLiteralDefaultHead` / Dec for numerals,
/// `commitQuoteDefault` / Str for quotes), so the dispatch cascade reports the
/// conflicts against the documented default type—the same failure shape as the
/// single-literal path.
fn commitLiteralGroupDefault(self: *Self, drivers: []const Var, component_fits: exact_numeral.FitSet, env: *Env) Allocator.Error!void {
    std.debug.assert(drivers.len >= 2);

    // Constraint ranges and literal kinds captured while the drivers are still
    // flex; the ranges index the constraint store, whose entries outlive the
    // unifications below.
    self.literal_defaulting_constraint_ranges.clearRetainingCapacity();
    self.literal_defaulting_kinds.clearRetainingCapacity();
    var has_numeral_driver = false;
    for (drivers) |driver| {
        try self.literal_defaulting_constraint_ranges.append(self.gpa, self.types.resolveVar(driver).desc.content.flex.constraints);
        // Every group driver is an open literal (the component gather keyed
        // on `varLiteralKind`), so the kind always exists.
        const kind = self.varLiteralKind(driver).?;
        try self.literal_defaulting_kinds.append(self.gpa, kind);
        if (kind == .numeral) has_numeral_driver = true;
    }

    // Quote drivers have exactly one candidate (Str) and are assigned it on
    // every attempt; only numeral drivers consume the candidate scan, so an
    // all-quote group needs exactly one attempt.
    const candidate_scan: []const CIR.NumKind = if (has_numeral_driver)
        numeral_default_candidates[0..]
    else
        numeral_default_candidates[0..1];

    candidate: for (candidate_scan) |candidate_kind| {
        // The component's passive literals get pinned by phase 1's assignments
        // too, so their exact values must accept the candidate—the O(1) bit
        // test on the precomputed intersection runs before the per-driver walk.
        if (has_numeral_driver and !componentFitsAcceptNumKind(component_fits, candidate_kind)) continue :candidate;
        // Digit-fit precheck for every numeral driver's literal payload—pure
        // arithmetic on the constraint payloads, before any speculation. Not
        // subsumed by the bit test above: a driver's range can carry
        // from_literal QUOTE constraints (a numeral flex unified with a quote
        // flex defers the conflict), which refute every numeric candidate but
        // contribute nothing to the numeral fit-set intersection. Quote
        // drivers are assigned Str, which their own literal-conversion
        // provenance accepts by definition, so they have nothing to precheck.
        for (self.literal_defaulting_constraint_ranges.items, self.literal_defaulting_kinds.items) |range, kind| {
            if (kind != .numeral) continue;
            if (!self.rangeNumeralDigitsFit(range, candidate_kind)) continue :candidate;
        }

        var commit_probe = try self.beginCommitProbe(env);
        var committed = false;
        // Runs on every exit from this loop body, `continue :candidate` included.
        defer if (!committed) commit_probe.rollback();

        // Phase 1: assign each driver its kind's candidate—the scanned numeric
        // candidate for numeral drivers, Str for quote drivers. Driver roots are
        // distinct and still flex, so these unifications are independent of each
        // other; flex-vs-concrete cannot mismatch (the drivers' dispatch
        // constraints defer onto the candidate as usual).
        self.literal_defaulting_candidate_vars.clearRetainingCapacity();
        for (drivers, self.literal_defaulting_kinds.items) |driver, kind| {
            const candidate_var = switch (kind) {
                .numeral => try self.freshFromContent(
                    try self.mkBuiltinNumberTypeContentFromKind(candidate_kind),
                    env,
                    self.getRegionAt(driver),
                ),
                .quote, .interpolation => try self.freshStr(env, self.getRegionAt(driver)),
            };
            try self.literal_defaulting_candidate_vars.append(self.gpa, candidate_var);
            const unify_result = try commit_probe.unify(driver, candidate_var);
            if (!unify_result.isEstablished()) continue :candidate;
        }

        // Phase 2: verify every driver's every non-literal constraint.
        for (0..drivers.len) |driver_idx| {
            if (!try self.candidateSatisfiesRangeConstraints(
                &commit_probe,
                self.literal_defaulting_constraint_ranges.items[driver_idx],
                self.literal_defaulting_candidate_vars.items[driver_idx],
                env,
            )) continue :candidate;
        }

        committed = true;
        commit_probe.commit();
        return;
    }

    // No candidate satisfies the group: commit each driver's documented head
    // default (Dec for numerals, Str for quotes) so the dispatch pass reports the
    // conflicts. (All drivers are flex again—every failed probe rolled back—
    // but re-check defensively.) A driver is recorded as conflicted—so the
    // dispatch pass's failure path rewinds its speculative merges (see
    // `conflicted_default_literal_vars`)—only when its own head default is the
    // rejected one: every shared candidate failed a numeral driver's scan, but
    // a quote driver is assigned Str on every attempt, so the group's failure
    // may be entirely its peers' doing; the per-driver predicate probe keeps a
    // Str-satisfied quote driver off the list (its dispatches discharge
    // normally against Str).
    for (drivers, self.literal_defaulting_kinds.items, self.literal_defaulting_constraint_ranges.items) |driver, kind, range| {
        if (self.types.resolveVar(driver).desc.content != .flex) continue;
        switch (kind) {
            .numeral => {
                if (self.rangeHasNonLiteralConstraint(range)) {
                    try self.recordConflictedDefaultLiteral(driver);
                }
                _ = try self.commitLiteralDefaultHead(driver, env);
            },
            .quote, .interpolation => {
                if (self.rangeHasNonLiteralConstraint(range) and
                    !try self.quoteDefaultSatisfiesConstraints(driver, range, env))
                {
                    try self.recordConflictedDefaultLiteral(driver);
                }
                _ = try self.commitQuoteDefault(driver, env);
            },
        }
    }
}

/// Boundary defaulting—the Haskell Report §4.3.4 / GHC `-Wtype-defaults`
/// analogue. At a def's generalization boundary, default every still-open literal
/// var NOT reachable from the def's type (constraint-signature edges included),
/// then cascade the deferred dispatches it unblocks BEFORE generalization.
///
/// Why forced: instantiation copies only signature-reachable vars, so an
/// unreachable literal is SHARED by every use of the def—it cannot adapt per
/// call site even in principle. This is Haskell's "ambiguous type variable"
/// (constrained but not appearing in the type).
///
/// A LITERAL DEFAULTED warning fires only when the default leaks into the def's
/// interface (`boundaryDefaultLeaksIntoSignature`); def-local defaults are silent
/// (GHC warns on those too—which is why `-Wtype-defaults` is muted in practice).
///
/// Signature-reachable literals stay open (e.g. `|x| 5 + x`): generalization
/// quantifies them and each use defaults its own instantiated copy.
/// Whether committing a boundary default to `literal_var` would LEAK into the
/// def's interface: some dispatch-constraint signature of the literal reaches a
/// var itself reachable from the def's type, so firing the dispatch after
/// defaulting narrows the def's signature (e.g. defaulting `5` in `add_x(5)` fires
/// `plus : (5, x) -> r`, pinning the enclosing param `x`). That narrowing is the
/// warning-worthy act; constraints touching nothing signature-reachable default
/// silently.
///
/// Must run while `literal_var` is still flex (before the default unify) and after
/// `boundary_reachable_vars` is populated for the current boundary.
/// Clear `out`, then collect every var reachable from the var's non-`from_literal`
/// dispatch constraints into it. Single source of truth for the "signature
/// footprint" used by both interference partitioning (runLiteralDefaultingRounds)
/// and boundary-leak detection (boundaryDefaultLeaksIntoSignature)—they MUST
/// agree, or a literal could be partitioned non-interfering yet warned.
/// collectReachableVars only reads the store, so holding the constraint slice
/// across it is safe.
fn collectConstraintSignatureReachable(
    self: *Self,
    constraint_range: StaticDispatchConstraint.SafeList.Range,
    out: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!void {
    out.clearRetainingCapacity();
    for (self.types.sliceStaticDispatchConstraints(constraint_range)) |constraint| {
        if (constraint.origin == .from_literal) continue;
        try self.collectReachableVars(constraint.fn_var, out);
    }
}

fn boundaryDefaultLeaksIntoSignature(self: *Self, literal_var: Var) std.mem.Allocator.Error!bool {
    const resolved = self.types.resolveVar(literal_var);
    if (resolved.desc.content != .flex) return false;

    try self.collectConstraintSignatureReachable(resolved.desc.content.flex.constraints, &self.boundary_leak_vars);

    var leak_iter = self.boundary_leak_vars.keyIterator();
    while (leak_iter.next()) |leak_var| {
        if (self.boundary_reachable_vars.contains(leak_var.*)) return true;
    }
    return false;
}

/// Per-literal boundary-warning state, computed BEFORE the literal's commit
/// resolves the flex away: the leak check walks the still-open constraint
/// signatures, and for numerals the warning region comes from the `from_numeral`
/// payload (exact even when the root is an instantiated copy), reachable only
/// while the var is flex. Quote constraints carry no payload, so they fall back to
/// the var's own region—right for direct literals, possibly imprecise for
/// instantiated copies.
const PendingBoundaryWarning = struct {
    leaks_into_signature: bool,
    region: Region,
    kind: StaticDispatchConstraint.LiteralKind,
};

/// See `PendingBoundaryWarning`—must be called while `literal_root` is
/// still flex, with `boundary_reachable_vars` populated for the current
/// boundary.
fn boundaryWarningBeforeCommit(self: *Self, literal_root: Var) std.mem.Allocator.Error!PendingBoundaryWarning {
    const root_var = self.types.resolveVar(literal_root).var_;
    const is_int_unbound = blk: {
        var iter = self.int_unbound_vars.keyIterator();
        while (iter.next()) |var_ptr| {
            if (self.types.resolveVar(var_ptr.*).var_ == root_var) break :blk true;
        }
        break :blk false;
    };
    return .{
        .leaks_into_signature = if (is_int_unbound) false else try self.boundaryDefaultLeaksIntoSignature(literal_root),
        .region = self.literalSourceRegion(literal_root) orelse self.getRegionAt(literal_root),
        // Every commit path only reaches here for a var with literal-conversion
        // provenance, and the var is still flex pre-commit, so the kind is
        // always derivable.
        .kind = self.varLiteralKind(literal_root) orelse unreachable,
    };
}

/// Emit the LITERAL DEFAULTED warning for a just-committed boundary default when
/// it leaks into the def's interface. `snapshot_var` is any var in the committed
/// equivalence class (the returned default var for single commits, the driver
/// root itself for group commits): its union-find root carries the concrete
/// committed content, so the snapshot renders the clean committed type either way—
/// identical to a pre-commit snapshot of the fresh candidate.
fn emitBoundaryWarningAfterCommit(
    self: *Self,
    pending: PendingBoundaryWarning,
    literal_root: Var,
    snapshot_var: Var,
) std.mem.Allocator.Error!void {
    // Only numerals warn on default. A numeral has many sensible types (I8…U64,
    // Dec, F64), so silently committing it to Dec is a real choice worth flagging.
    // A quote/interpolation defaults to Str—almost always what was meant, and how
    // main defaulted them (silently)—so flagging it is just noise.
    if (pending.kind != .numeral) return;
    if (!pending.leaks_into_signature) return;
    const default_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, snapshot_var);
    _ = try self.problems.appendProblem(self.gpa, .{ .literal_defaulted = .{
        .literal_var = literal_root,
        .kind = pending.kind,
        .default_snapshot = default_snapshot,
        .region = pending.region,
    } });
}

fn defaultLiteralsAtGeneralizationBoundary(
    self: *Self,
    root: BoundaryRoot,
    env: *Env,
) std.mem.Allocator.Error!void {
    try self.defaultLiteralsAtGeneralizationBoundaryMultiRoot(&.{root}, env);
}

fn ensureTypeScheme(self: *Self, root_var: Var, capture_rank: Rank) Allocator.Error!usize {
    if (self.typeSchemeIndexForRoot(root_var)) |scheme_idx| return scheme_idx;
    try self.type_scheme_by_var.ensureUnusedCapacity(self.gpa, 1);
    const scheme_idx = self.type_schemes.items.len;
    try self.type_schemes.append(self.gpa, .{
        .root_var = root_var,
        .capture_rank = capture_rank,
        .capture_group_index = self.currentGroupIndex(),
    });
    errdefer _ = self.type_schemes.pop();
    try self.type_schemes.items[scheme_idx].indexed_vars.append(self.gpa, root_var);
    self.type_scheme_by_var.putAssumeCapacityNoClobber(root_var, @intCast(scheme_idx));
    return scheme_idx;
}

/// Register another stable source var that names an existing side-table
/// scheme. This is called when a binding receives another source var; it does
/// not inspect union-find classes.
fn bindTypeSchemeVar(self: *Self, scheme_var: Var, alias_var: Var) Allocator.Error!void {
    try self.bindBindingSchemeVar(scheme_var, alias_var);
    const scheme_idx = self.typeSchemeIndexForRoot(scheme_var) orelse return;
    if (self.type_scheme_by_var.get(alias_var)) |existing_idx| {
        std.debug.assert(existing_idx == @as(u32, @intCast(scheme_idx)));
        return;
    }
    try self.type_scheme_by_var.ensureUnusedCapacity(self.gpa, 1);
    try self.type_schemes.items[scheme_idx].indexed_vars.append(self.gpa, alias_var);
    self.type_scheme_by_var.putAssumeCapacityNoClobber(alias_var, @intCast(scheme_idx));
}

fn removeTypeSchemeAt(self: *Self, scheme_idx: usize) void {
    const last_idx = self.type_schemes.items.len - 1;
    var removed = self.type_schemes.swapRemove(scheme_idx);
    for (removed.indexed_vars.items) |indexed_var| {
        const did_remove = self.type_scheme_by_var.remove(indexed_var);
        std.debug.assert(did_remove);
    }
    removed.indexed_vars.deinit(self.gpa);
    removed.dispatch_requirements.deinit(self.gpa);

    if (scheme_idx != last_idx) {
        for (self.type_schemes.items[scheme_idx].indexed_vars.items) |indexed_var| {
            const moved_index = self.type_scheme_by_var.getPtr(indexed_var) orelse unreachable;
            std.debug.assert(moved_index.* == @as(u32, @intCast(last_idx)));
            moved_index.* = @intCast(scheme_idx);
        }
    }
}

fn typeSchemeHasRequirement(
    self: *Self,
    scheme_idx: usize,
    receiver_var: Var,
    constraint: StaticDispatchConstraint,
) bool {
    const receiver_root = self.types.resolveVar(receiver_var).var_;
    const fn_root = self.types.resolveVar(constraint.fn_var).var_;
    for (self.type_schemes.items[scheme_idx].dispatch_requirements.items) |existing| {
        if (self.types.resolveVar(existing.receiver_var).var_ != receiver_root) continue;
        if (self.types.resolveVar(existing.constraint.fn_var).var_ != fn_root) continue;
        if (!existing.constraint.fn_name.eql(constraint.fn_name)) continue;
        return true;
    }
    return false;
}

/// Retire side-table requirements only after their exact deferred callable was
/// consumed or rejected. A receiver becoming concrete, rigid, aliased, or
/// erroneous is not by itself evidence that this relation was visited.
fn retireResolvedTypeSchemeRequirements(self: *Self) void {
    var scheme_idx: usize = 0;
    while (scheme_idx < self.type_schemes.items.len) {
        const scheme = &self.type_schemes.items[scheme_idx];
        std.debug.assert(self.type_scheme_by_var.get(scheme.root_var) == @as(?u32, @intCast(scheme_idx)));

        var write: usize = 0;
        for (scheme.dispatch_requirements.items) |requirement| {
            const still_pending = !self.settled_static_dispatch_constraint_fns.contains(requirement.constraint.fn_var) and
                !self.types.varStaticDispatchRejected(requirement.constraint.fn_var);
            if (!still_pending) continue;
            scheme.dispatch_requirements.items[write] = requirement;
            write += 1;
        }
        scheme.dispatch_requirements.shrinkRetainingCapacity(write);
        if (write == 0) {
            self.removeTypeSchemeAt(scheme_idx);
        } else {
            scheme_idx += 1;
        }
    }
}

fn requirementHasPublishedStructuralOrigin(
    self: *Self,
    requirement: SchemeDispatchRequirement,
    published_vars: *const std.AutoHashMap(Var, void),
) bool {
    const receiver = self.types.resolveVar(requirement.receiver_var);
    const origin_receiver = self.types.resolveVar(requirement.structural_origin.receiver_var);
    if (receiver.var_ != origin_receiver.var_) return false;
    if (receiver.desc.rank != .generalized) return false;
    if (!published_vars.contains(receiver.var_)) return false;

    const constraints_range = contentConstraintRange(origin_receiver.desc.content) orelse return false;
    const origin_fn_root = self.types.resolveVar(requirement.structural_origin.constraint_fn_var).var_;
    for (self.types.sliceStaticDispatchConstraints(constraints_range)) |constraint| {
        if (self.types.resolveVar(constraint.fn_var).var_ == origin_fn_root) return true;
    }
    return false;
}

/// A requirement's recorded creation relation is already attached to its
/// receiver. Once a boundary publishes both the side-table scheme root and
/// that generalized receiver, the structural constraint plus the checked
/// scheme-use substitution are the durable representation and the temporary
/// side-table copy is redundant. Requiring the exact mapped origin prevents
/// one definition from retiring an unrelated scheme merely because its
/// interface mentions the same receiver.
fn retireStructurallyPublishedTypeSchemeRequirements(
    self: *Self,
    roots: []const BoundaryRoot,
    boundary_rank: Rank,
) Allocator.Error!void {
    if (self.type_schemes.items.len == 0) return;

    var published_vars = std.AutoHashMap(Var, void).init(self.gpa);
    defer published_vars.deinit();
    for (roots) |root| {
        try self.collectReachableVars(root.interface, &published_vars);
    }

    var scheme_idx: usize = 0;
    while (scheme_idx < self.type_schemes.items.len) {
        const scheme = &self.type_schemes.items[scheme_idx];
        const scheme_root_published = published_vars.contains(self.types.resolveVar(scheme.root_var).var_);
        if (!scheme_root_published and
            std.meta.eql(scheme.capture_group_index, self.currentGroupIndex()) and
            @intFromEnum(scheme.capture_rank) > @intFromEnum(boundary_rank))
        {
            // This scheme belongs to a nested lexical frame of the closing
            // boundary's own group and its root did not escape through the
            // closing interface. No later source expression can name it, so
            // retaining checker-only requirements would manufacture an
            // obligation after the binding left scope. The capture group must
            // match by identity: ranks are a shared depth counter, so a
            // sibling module-level group checked one rank deeper inside this
            // boundary (resolving a pending dispatch target) owns live
            // module-level schemes that this boundary must leave intact.
            self.removeTypeSchemeAt(scheme_idx);
            continue;
        }
        if (!scheme_root_published) {
            scheme_idx += 1;
            continue;
        }

        var write: usize = 0;
        for (scheme.dispatch_requirements.items) |requirement| {
            const structurally_published = self.requirementHasPublishedStructuralOrigin(
                requirement,
                &published_vars,
            );
            if (structurally_published) continue;
            scheme.dispatch_requirements.items[write] = requirement;
            write += 1;
        }
        scheme.dispatch_requirements.shrinkRetainingCapacity(write);
        if (write == 0) {
            self.removeTypeSchemeAt(scheme_idx);
        } else {
            scheme_idx += 1;
        }
    }
}

/// TypeScheme is deliberately checker-local and is never serialized. At the
/// checked-module boundary every requirement must therefore be either exactly
/// discharged/rejected or absorbed into a receiver whose structural
/// constraints generalized normally. Any remaining relation is an explicit
/// unresolved-dispatch error; silently dropping it would make importing the
/// module less constrained than checking it locally.
fn finalizeTypeSchemeRequirementsAtCheckedBoundary(self: *Self) Allocator.Error!void {
    self.retireResolvedTypeSchemeRequirements();

    for (self.type_schemes.items) |scheme| {
        const scheme_is_err = self.types.resolveVar(scheme.root_var).desc.content == .err;
        for (scheme.dispatch_requirements.items) |requirement| {
            if (self.types.varStaticDispatchRejected(requirement.constraint.fn_var)) continue;

            if (scheme_is_err) {
                try self.markStaticDispatchRejected(requirement.constraint);
                continue;
            }

            const receiver = self.types.resolveVar(requirement.receiver_var);
            if (receiver.desc.content != .err and !self.reported_dispatch_vars.contains(receiver.var_)) {
                const source_expr = requirement.failure_expr orelse constraintIntroExpr(requirement.constraint);
                const region = if (source_expr) |expr_idx|
                    self.cir.store.getExprRegion(expr_idx)
                else
                    self.getRegionAt(requirement.receiver_var);
                const snapshot = try self.snapshots.snapshotVarForError(
                    self.types,
                    &self.type_writer,
                    requirement.receiver_var,
                );
                _ = try self.problems.appendProblem(self.gpa, .{ .static_dispatch = .{ .unresolved_dispatcher = .{
                    .region = region,
                    .secondary_region = null,
                    .dispatcher_snapshot = snapshot,
                    .method_name = requirement.constraint.fn_name,
                    .is_binop = requirement.constraint.origin == .desugared_binop,
                    .binop_negated = requirement.constraint.origin.binopNegated(),
                    .runtime_error_inserted = source_expr != null,
                } } });
                try self.reported_dispatch_vars.put(receiver.var_, {});
                try self.poisonConstraintFailureSource(
                    requirement.receiver_var,
                    requirement.constraint,
                    source_expr,
                );
            }
            try self.markStaticDispatchRejected(requirement.constraint);
        }
    }

    while (self.type_schemes.items.len > 0) self.removeTypeSchemeAt(self.type_schemes.items.len - 1);

    if (builtin.mode == .Debug) {
        std.debug.assert(self.type_scheme_by_var.count() == 0);
        std.debug.assert(self.scheme_requirement_candidate_indices_by_owner.count() == 0);
    }
}

/// A recursive binding group can contain value-restricted members alongside
/// functions. Capture runs before generalization so it cannot know which roots
/// will become schemes; discard side-table entries for members that the
/// boundary did not explicitly classify as schemes. Root rank is insufficient:
/// a partially generalized scheme can have a monomorphic structural root.
fn retireNonGeneralizedTypeSchemes(self: *Self, roots: []const BoundaryRoot) void {
    for (roots) |root| {
        const scheme_idx = self.typeSchemeIndexForRoot(root.owner) orelse continue;
        const scheme = &self.type_schemes.items[scheme_idx];
        if (self.isBindingSchemeVar(scheme.root_var)) continue;
        self.removeTypeSchemeAt(scheme_idx);
    }
}

/// Move every still-open dispatch relation owned by this generalization
/// boundary into its explicit scheme. A relation needs the side table only
/// while its receiver belongs to an outer rank. Captured candidates are
/// removed immediately, so later boundaries never rescan completed sites.
fn captureSchemeDispatchRequirements(
    self: *Self,
    roots: []const BoundaryRoot,
    env: *Env,
) Allocator.Error!void {
    // Generalization boundaries are never speculative solver work. Keeping
    // this invariant explicit means probes only need to rewind append-only
    // candidates; they can never create or destructively capture TypeSchemes.
    if (self.probe_depth != 0) {
        @panic("scheme requirements cannot be captured inside a solver probe");
    }
    const rank = env.rank();
    for (roots) |root| {
        var owner_indices = (self.scheme_requirement_candidate_indices_by_owner.fetchRemove(root.owner) orelse continue).value;
        defer owner_indices.deinit(self.gpa);
        for (owner_indices.items) |candidate_idx| {
            const candidate = self.scheme_requirement_candidates.items[candidate_idx];
            std.debug.assert(candidate.owner_root == root.owner);

            // This is the candidate's one declared owner boundary. Whether it
            // needs an explicit entry is decided here and never reconstructed
            // at a later enclosing boundary.
            const receiver = self.types.resolveVar(candidate.receiver_var);
            if (receiver.desc.content != .flex) continue;
            if (receiver.desc.rank == .generalized) continue;
            const needs_explicit_requirement = switch (candidate.source) {
                .creation => @intFromEnum(receiver.desc.rank) < @intFromEnum(rank),
                // A copied relation is detached from its receiver descriptor.
                // Its structural origin is retained separately so publication
                // can prove when checked evidence makes this copy redundant.
                .scheme_copy => true,
            };
            if (!needs_explicit_requirement) continue;

            // Do not materialize a scheme merely to discover that this exact
            // requirement was already captured through another alias/copy.
            // Empty schemes have no semantic meaning and only add hot-path
            // lookup state.
            const scheme_idx = if (self.typeSchemeIndexForRoot(root.owner)) |existing_scheme_idx| blk: {
                if (self.typeSchemeHasRequirement(existing_scheme_idx, candidate.receiver_var, candidate.constraint)) continue;
                break :blk existing_scheme_idx;
            } else try self.ensureTypeScheme(root.owner, rank);
            try self.type_schemes.items[scheme_idx].dispatch_requirements.append(self.gpa, .{
                .receiver_var = candidate.receiver_var,
                .constraint = candidate.constraint,
                .failure_expr = candidate.failure_expr,
                .structural_origin = candidate.structural_origin,
            });
        }
    }
    if (self.scheme_requirement_candidate_indices_by_owner.count() == 0) {
        self.scheme_requirement_candidates.clearRetainingCapacity();
    }
}

fn addSchemeDispatchRequirementsToBoundaryReachability(
    self: *Self,
    roots: []const BoundaryRoot,
) Allocator.Error!void {
    self.scheme_relation_reachability.clearRetainingCapacity();
    self.scheme_relation_reachable_vars.clearRetainingCapacity();
    for (roots) |root| {
        try self.addSchemeRequirementRelationsToReachableSet(root.owner);
    }
}

/// Boundary reachability including the receiver-excluded relation overlay,
/// which is merged into `boundary_reachable_vars` only after the `eql`-edge
/// fixpoint's plain walks have all run.
fn boundaryReachableIncludingRelations(self: *const Self, var_: Var) bool {
    const root = self.types.resolveVar(var_).var_;
    return self.boundary_reachable_vars.contains(root) or
        self.scheme_relation_reachable_vars.contains(root);
}

fn assertSchemeRequirementBoundaryQuiescent(self: *const Self, roots: []const BoundaryRoot) void {
    if (builtin.mode != .Debug) return;
    for (roots) |root| {
        std.debug.assert(!self.scheme_requirement_candidate_indices_by_owner.contains(root.owner));
    }
}

/// `defaultLiteralsAtGeneralizationBoundary` for a whole binding group: the
/// reachable protection set is seeded from every member's root, so a literal
/// reachable from any member's signature stays open across the shared
/// boundary.
fn defaultLiteralsAtGeneralizationBoundaryMultiRoot(
    self: *Self,
    roots: []const BoundaryRoot,
    env: *Env,
) std.mem.Allocator.Error!void {
    const rank = env.rank();

    // Generalization publishes a complete scheme: its root type plus every
    // unresolved method relation the definition owns. Capture those relations
    // even when this boundary has no literal candidates of its own.
    try self.captureSchemeDispatchRequirements(roots, env);

    // The candidate universe is the var pool entry this generalize call will
    // promote. (The global open-literal worklist is NOT usable here: a sub-def
    // checked mid-flight runs in its own env at the same numeric rank, so rank
    // alone cannot tell this def's literals from an enclosing def's.) A candidate
    // is still flex at this rank with literal-conversion provenance.
    const pool_vars = env.var_pool.getVarsForRank(rank);

    // Fast path: no open literal at this boundary, nothing to do.
    var has_candidate = false;
    for (pool_vars) |pool_var| {
        const resolved = self.types.resolveVar(pool_var);
        if (resolved.desc.content != .flex) continue;
        if (resolved.desc.rank != rank) continue;
        if (self.varLiteralKind(resolved.var_) == null) continue;
        has_candidate = true;
        break;
    }
    if (!has_candidate) {
        try self.quiesceSchemeRequirementsAtBoundary(roots, env);
        return;
    }

    // Collect the module's `.eql` edges once so the recursive-def pass and the
    // fixpoint below iterate just the edges, not the whole constraint list.
    // Safe to snapshot here: nothing between this point and the fixpoint adds an
    // `.eql` constraint (the passes only collect reachable vars).
    self.boundary_eql_edges.clearRetainingCapacity();
    {
        var edge_iter = self.constraints.iterIndices();
        while (edge_iter.next()) |constraint_idx| {
            switch (self.constraints.get(constraint_idx).*) {
                .eql => |eql| try self.boundary_eql_edges.append(self.gpa, eql),
            }
        }
    }

    // The reachable closure of every def root at this boundary (recursing into
    // `where`-constraint signatures). A recursive group generalizes as one
    // unit, so all members' roots seed the same protection set. Recursive
    // references need no special seeding: the binding-group recursion rule
    // unifies them with the member's in-flight type immediately, so a literal
    // constrained through a recursive call is already reachable from the
    // member's root.
    self.boundary_reachable_vars.clearRetainingCapacity();
    for (roots) |root| {
        try self.collectReachableVars(root.interface, &self.boundary_reachable_vars);
    }
    try self.addSchemeDispatchRequirementsToBoundaryReachability(roots);

    // Pending `eql` constraints are recursive-group cross-reference edges; a
    // literal awaiting unification with the def's type through one is NOT
    // ambiguous. Close the set over them—when one side of an edge is in,
    // collect both sides—to fixpoint, since collecting one edge can make
    // another edge's side reachable.
    var changed = true;
    while (changed) {
        changed = false;
        for (self.boundary_eql_edges.items) |eql| {
            const expected_in = self.boundaryReachableIncludingRelations(eql.expected);
            const actual_in = self.boundaryReachableIncludingRelations(eql.actual);
            if (expected_in == actual_in) continue;
            try self.collectReachableVars(eql.expected, &self.boundary_reachable_vars);
            try self.collectReachableVars(eql.actual, &self.boundary_reachable_vars);
            changed = true;
        }
    }

    // Every plain walk into the boundary set is done; fold in the
    // receiver-excluded relation overlay for the membership-only consumers
    // (defaulting protection and leak detection).
    var relation_iter = self.scheme_relation_reachable_vars.keyIterator();
    while (relation_iter.next()) |var_| {
        try self.boundary_reachable_vars.put(var_.*, {});
    }

    // Default every unreachable candidate through the shared component machinery—
    // identical to `finalizeLiteralDefaults` except for the candidate universe
    // and the per-commit leak warnings—and cascade the dispatches whose
    // receivers each round defaulted, pinning their signatures' other vars before
    // generalization promotes them. The pool length is snapshotted here:
    // defaulting appends fresh default vars to this same pool entry, and those
    // must not be rescanned.
    try self.runLiteralDefaultingRounds(env, .{ .boundary = .{
        .rank = rank,
        .pool_len = pool_vars.len,
    } });
    try self.quiesceSchemeRequirementsAtBoundary(roots, env);
}

/// The boundary defaulting pass's shared epilogue: drive the grounded
/// pending-requirement worklist to its exact fixpoint, then capture what it
/// produced. Target selection inside that fixpoint can instantiate a method
/// scheme that contributes a transitive requirement under this boundary's
/// still-active owner; capturing after the fixpoint is the lifecycle
/// counterpart to the capture before defaulting—no solver work follows on
/// either exit path, so the owner is quiescent when this returns.
fn quiesceSchemeRequirementsAtBoundary(
    self: *Self,
    roots: []const BoundaryRoot,
    env: *Env,
) std.mem.Allocator.Error!void {
    try self.checkGroundedSchemeRequirementsAtBoundary(env);
    try self.captureSchemeDispatchRequirements(roots, env);
    self.assertSchemeRequirementBoundaryQuiescent(roots);
}

/// A copied explicit requirement stays out of the hot deferred queue while its
/// receiver is flex. If that receiver grounds at the boundary that owns the
/// copy's callable variables, validate it before generalization freezes those
/// variables. This scans only at generalization boundaries, never after every
/// expression.
fn checkGroundedSchemeRequirementsAtBoundary(
    self: *Self,
    env: *Env,
) Allocator.Error!void {
    while (true) {
        if (!try self.drainGroundedPendingSchemeRequirementDispatchers(env)) return;
        try self.checkStaticDispatchConstraints(env, false);
        try self.checkAllConstraints(env);
    }
}

/// One drain of the compact pending index: every explicit scheme requirement
/// whose receiver has grounded takes its single deferred-queue transition;
/// still-flex entries are compacted in place to wait. Returns whether any
/// entry was enqueued.
fn drainGroundedPendingSchemeRequirementDispatchers(
    self: *Self,
    env: *Env,
) Allocator.Error!bool {
    var appended = false;
    var pending_write: usize = 0;
    for (self.pending_scheme_requirement_dispatchers.items) |dispatcher_idx| {
        const dispatcher = &self.instantiation_dispatchers.items[dispatcher_idx];
        std.debug.assert(dispatcher.source == .scheme_requirement);
        if (dispatcher.deferred_enqueued) continue;
        if (self.types.resolveVar(dispatcher.dispatcher_var).desc.content == .flex) {
            self.pending_scheme_requirement_dispatchers.items[pending_write] = dispatcher_idx;
            pending_write += 1;
            continue;
        }

        try self.enqueueDeferredDispatchConstraint(env, .{
            .var_ = dispatcher.dispatcher_var,
            .constraints = dispatcher.constraints,
            .failure_expr = if (dispatcher.instantiation_expr) |expr_idx|
                .from(@intFromEnum(expr_idx))
            else
                .none,
        }, .{ .recorded = dispatcher.owner_group_index });
        dispatcher.deferred_enqueued = true;
        appended = true;
    }
    self.pending_scheme_requirement_dispatchers.shrinkRetainingCapacity(pending_write);
    return appended;
}

/// A creation requirement can outlive the group-local deferred queue when its
/// receiver belongs to an outer scope and grounds only during module literal
/// defaulting. The TypeScheme is the durable owner of that exact relation.
/// Enqueue every newly concrete stored relation and drive both ordinary and
/// instantiated dispatch work to a fixpoint before checked-module publication.
/// Retirement still depends on `recordSettledDeferredDispatchRelation`; a
/// concrete receiver alone never counts as discharge.
///
/// A stored relation the drain retains rather than settles (an unresolved
/// derived codec, a target def still being checked) is copied back into the
/// deferred queue by `checkStaticDispatchConstraints`, so it is already
/// scheduled for the next drain. Enqueueing it again would leave two live
/// entries for one relation and fire its dispatch twice per round—for a
/// derived codec, a second set of fresh parse-result vars and a second
/// derivation snapshot. `enqueued_fn_vars` plus the live-queue check give
/// each relation exactly one entry, and the loop keeps draining while the
/// retained entries make progress.
///
/// Termination is measured over this loop's own relations. A relation is
/// enqueued only when its callable is absent from `enqueued_fn_vars`, which
/// never shrinks, so enqueues are bounded by the number of distinct stored
/// callables. A round that enqueues nothing runs only when the previous drain
/// discharged one of those relations; `settled` and `rejected` are permanent,
/// so that count is monotone and bounded by the same set. Both quantities are
/// finite, so the loop ends. `settled_static_dispatch_constraint_fns` as a
/// whole cannot serve as the progress measure: the drain instantiates method
/// schemes that mint and settle brand-new callables, so its count changes on
/// rounds that discharged no stored relation at all.
fn checkGroundedStoredTypeSchemeRequirementsAtFinalization(
    self: *Self,
    env: *Env,
    is_numeric_default_pass: bool,
) Allocator.Error!void {
    var enqueued_fn_vars = std.AutoHashMap(Var, void).init(self.gpa);
    defer enqueued_fn_vars.deinit();
    var discharged: usize = 0;
    var retained_relations_progressed = false;
    while (true) {
        var appended = false;
        for (self.type_schemes.items) |scheme| {
            for (scheme.dispatch_requirements.items) |requirement| {
                if (self.settled_static_dispatch_constraint_fns.contains(requirement.constraint.fn_var) or
                    self.types.varStaticDispatchRejected(requirement.constraint.fn_var))
                {
                    continue;
                }
                if (self.types.resolveVar(requirement.receiver_var).desc.content == .flex) continue;
                if (enqueued_fn_vars.contains(requirement.constraint.fn_var)) continue;
                if (self.deferredDispatchRelationIsQueued(
                    env.deferred_static_dispatch_constraints.items.items,
                    requirement.receiver_var,
                    requirement.constraint.fn_var,
                )) continue;
                try enqueued_fn_vars.put(requirement.constraint.fn_var, {});

                const constraint_range = try self.types.appendStaticDispatchConstraints(&.{requirement.constraint});
                try self.enqueueDeferredDispatchConstraint(env, .{
                    .var_ = requirement.receiver_var,
                    .constraints = constraint_range,
                    .failure_expr = if (requirement.failure_expr) |expr_idx|
                        .from(@intFromEnum(expr_idx))
                    else
                        .none,
                }, .current_group);
                appended = true;
            }
        }
        if (!appended and !retained_relations_progressed) return;

        try self.checkStaticDispatchConstraints(env, is_numeric_default_pass);
        try self.checkAllConstraints(env);
        try self.checkInstantiatedStaticDispatchConstraints(env, is_numeric_default_pass);
        try self.checkAllConstraints(env);

        const discharged_now = self.dischargedDispatchRelationCount(&enqueued_fn_vars);
        retained_relations_progressed = discharged_now > discharged;
        discharged = discharged_now;
    }
}

/// Whether the deferred queue already holds a live entry for this exact
/// receiver/callable relation. `sameDeferredDispatchRelation` cannot answer
/// this: it compares constraint ranges by index, and every enqueue of a stored
/// requirement copies the constraint into a freshly allocated range, so two
/// entries for one relation never share a range start.
fn deferredDispatchRelationIsQueued(
    self: *const Self,
    queued_constraints: []const DeferredConstraintCheck,
    receiver_var: Var,
    fn_var: Var,
) bool {
    for (queued_constraints) |queued| {
        if (queued.var_ != receiver_var) continue;
        for (self.types.sliceStaticDispatchConstraints(queued.constraints)) |constraint| {
            if (constraint.fn_var == fn_var) return true;
        }
    }
    return false;
}

/// How many of `fn_vars` name a callable whose dispatch relation is now
/// discharged—settled or rejected. Both are permanent, so this count only
/// grows while `fn_vars` does not shrink, which is what makes it usable as a
/// progress measure. Counting the callables directly (instead of rescanning
/// the stored requirements) is what survives retirement: a discharged
/// requirement is removed from its scheme by
/// `retireResolvedTypeSchemeRequirements`, so a rescan of what remains stored
/// would show the discharge as no change at all.
fn dischargedDispatchRelationCount(
    self: *const Self,
    fn_vars: *const std.AutoHashMap(Var, void),
) usize {
    var count: usize = 0;
    var fn_var_iter = fn_vars.keyIterator();
    while (fn_var_iter.next()) |fn_var| {
        if (self.settled_static_dispatch_constraint_fns.contains(fn_var.*) or
            self.types.varStaticDispatchRejected(fn_var.*))
        {
            count += 1;
        }
    }
    return count;
}

/// Whether any deferred static-dispatch constraint's receiver has resolved to
/// something other than a flex var—i.e. whether another
/// `checkStaticDispatchConstraints` pass can make progress (it re-defers only
/// still-flex receivers; every other receiver is consumed: fired or errored).
fn anyDeferredDispatchReceiverResolved(self: *Self, env: *Env) Allocator.Error!bool {
    for (env.deferred_static_dispatch_constraints.items.items) |deferred| {
        if (self.types.resolveVar(deferred.var_).desc.content == .flex) continue;
        if (deferred.waiting_on_target_def) continue;
        if (try self.deferredConstraintWaitsOnDerivedParse(deferred, env)) continue;
        if (try self.deferredConstraintWaitsOnDerivedEncode(deferred, env)) continue;
        return true;
    }
    return false;
}

fn deferredConstraintWaitsOnDerivedParse(self: *Self, deferred: DeferredConstraintCheck, env: *Env) Allocator.Error!bool {
    var has_parser_for = false;
    for (self.types.sliceStaticDispatchConstraints(deferred.constraints)) |constraint| {
        if (constraint.fn_name.eql(self.cir.idents.parser_for)) {
            has_parser_for = true;
            break;
        }
    }
    if (!has_parser_for) return false;

    const region = self.getRegionAt(deferred.var_);
    return (try self.varSupportsDerivedParseShape(deferred.var_, env, region)) == .unresolved;
}

fn deferredConstraintWaitsOnDerivedEncode(self: *Self, deferred: DeferredConstraintCheck, env: *Env) Allocator.Error!bool {
    var maybe_encoding_var: ?Var = null;
    for (self.types.sliceStaticDispatchConstraints(deferred.constraints)) |constraint| {
        if (constraint.fn_name.eql(self.cir.idents.encoder_for)) {
            maybe_encoding_var = self.encoderForConstraintEncodingVar(constraint);
            break;
        }
    }
    const encoding_var = maybe_encoding_var orelse return false;

    const region = self.getRegionAt(deferred.var_);
    return (try self.varSupportsDerivedEncodeShape(deferred.var_, encoding_var, env, region)) == .unresolved;
}

fn encoderForConstraintEncodingVar(self: *Self, constraint: StaticDispatchConstraint) ?Var {
    const resolved_constraint = self.types.resolveVar(constraint.fn_var);
    const resolved_func = resolved_constraint.desc.content.unwrapFunc() orelse return null;
    const args = self.types.sliceVars(resolved_func.args);
    if (args.len != 1) return null;
    return args[0];
}

fn deferredEncodeHasPendingOpenLiteral(self: *Self, deferred: DeferredConstraintCheck, env: *Env) Allocator.Error!bool {
    self.var_set.clearRetainingCapacity();
    return try self.varHasPendingOpenLiteralForDerivedEncode(deferred.var_, env, &self.var_set);
}

fn deferredParseHasPendingOpenLiteral(self: *Self, deferred: DeferredConstraintCheck, env: *Env) Allocator.Error!bool {
    self.var_set.clearRetainingCapacity();
    return try self.varHasPendingOpenLiteralForDerivedParse(deferred.var_, env, &self.var_set);
}

fn varHasPendingOpenLiteralForDerivedParse(
    self: *Self,
    var_: Var,
    env: *Env,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    if (visited.contains(resolved.var_)) return false;
    try visited.put(resolved.var_, {});

    return switch (resolved.desc.content) {
        .structure => |structure| try self.structureHasPendingOpenLiteralForDerivedParse(structure, env, visited),
        .alias => |alias| try self.varHasPendingOpenLiteralForDerivedParse(self.types.getAliasBackingVar(alias), env, visited),
        // A presence variable is a field-kind fact, never a literal carrier.
        .err, .rigid, .field_presence => false,
        .flex => resolved.desc.rank != .generalized and self.varLiteralKind(resolved.var_) != null,
    };
}

fn structureHasPendingOpenLiteralForDerivedParse(
    self: *Self,
    structure: types_mod.FlatType,
    env: *Env,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    return switch (structure) {
        .nominal_type => |nominal| try self.nominalHasPendingOpenLiteralForDerivedParse(nominal, env, visited),
        .record => |record| try self.recordHasPendingOpenLiteralForDerivedParse(record.fields, env, visited) or
            try self.varHasPendingOpenLiteralForDerivedParse(record.ext, env, visited),
        .record_unbound => |fields| try self.recordHasPendingOpenLiteralForDerivedParse(fields, env, visited),
        .tag_union => |tag_union| try self.tagUnionHasPendingOpenLiteralForDerivedParse(tag_union, env, visited),
        .tuple => |tuple| blk: {
            const elems = self.types.sliceVars(tuple.elems);
            for (elems) |elem_var| {
                if (try self.varHasPendingOpenLiteralForDerivedParse(elem_var, env, visited)) break :blk true;
            }
            break :blk false;
        },
        .fn_pure, .fn_effectful, .fn_unbound, .empty_record, .empty_tag_union => false,
    };
}

fn recordHasPendingOpenLiteralForDerivedParse(
    self: *Self,
    fields_range: types_mod.RecordField.SafeMultiList.Range,
    env: *Env,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    const fields = self.types.getRecordFieldsSlice(fields_range);
    for (fields.items(.presence)) |presence| {
        if (try self.varHasPendingOpenLiteralForDerivedParse(presence.typeVar(), env, visited)) return true;
    }
    return false;
}

fn tagUnionHasPendingOpenLiteralForDerivedParse(
    self: *Self,
    tag_union: types_mod.TagUnion,
    env: *Env,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    const tags = self.types.getTagsSlice(tag_union.tags);
    for (tags.items(.args)) |tag_args_range| {
        for (self.types.sliceVars(tag_args_range)) |tag_arg| {
            if (try self.varHasPendingOpenLiteralForDerivedParse(tag_arg, env, visited)) return true;
        }
    }
    return try self.tagExtHasPendingOpenLiteralForDerivedParse(tag_union.ext, env, visited);
}

fn tagExtHasPendingOpenLiteralForDerivedParse(
    self: *Self,
    ext_var: Var,
    env: *Env,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    return switch (self.types.resolveVar(ext_var).desc.content) {
        .structure => |structure| switch (structure) {
            .tag_union => |tag_union| try self.tagUnionHasPendingOpenLiteralForDerivedParse(tag_union, env, visited),
            .record, .record_unbound, .tuple, .nominal_type, .fn_pure, .fn_effectful, .fn_unbound, .empty_record, .empty_tag_union => false,
        },
        .alias => |alias| try self.tagExtHasPendingOpenLiteralForDerivedParse(self.types.getAliasBackingVar(alias), env, visited),
        .flex, .rigid, .field_presence, .err => false,
    };
}

fn nominalHasPendingOpenLiteralForDerivedParse(
    self: *Self,
    nominal: types_mod.NominalType,
    env: *Env,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    if (self.nominalListPayloadVar(nominal)) |payload_var| {
        return try self.varHasPendingOpenLiteralForDerivedParse(payload_var, env, visited);
    }
    if (self.nominalBoxPayloadVar(nominal)) |payload_var| {
        return try self.varHasPendingOpenLiteralForDerivedParse(payload_var, env, visited);
    }
    if (self.nominalSetPayloadVar(nominal)) |payload_var| {
        return try self.varHasPendingOpenLiteralForDerivedParse(payload_var, env, visited);
    }
    if (self.nominalDictKeyValueVars(nominal)) |args| {
        return try self.varHasPendingOpenLiteralForDerivedParse(args.key, env, visited) or
            try self.varHasPendingOpenLiteralForDerivedParse(args.value, env, visited);
    }
    if (self.nominalIsBuiltinTryType(nominal)) {
        if (try self.nullTryInfoFromNominal(nominal)) |info| {
            return try self.varHasPendingOpenLiteralForDerivedParse(info.ok_var, env, visited);
        }
        if (try self.missingTryInfoFromNominal(nominal)) |info| {
            return try self.varHasPendingOpenLiteralForDerivedParse(info.ok_var, env, visited);
        }
        if (try self.unboundTryInfoFromNominal(nominal)) |info| {
            return try self.varHasPendingOpenLiteralForDerivedParse(info.ok_var, env, visited);
        }
    }
    return false;
}

fn varHasPendingOpenLiteralForDerivedEncode(
    self: *Self,
    var_: Var,
    env: *Env,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    if (visited.contains(resolved.var_)) return false;
    try visited.put(resolved.var_, {});

    return switch (resolved.desc.content) {
        .structure => |structure| try self.structureHasPendingOpenLiteralForDerivedEncode(structure, env, visited),
        .alias => |alias| try self.varHasPendingOpenLiteralForDerivedEncode(self.types.getAliasBackingVar(alias), env, visited),
        .err, .rigid, .field_presence => false,
        .flex => resolved.desc.rank != .generalized and self.varLiteralKind(resolved.var_) != null,
    };
}

fn structureHasPendingOpenLiteralForDerivedEncode(
    self: *Self,
    structure: types_mod.FlatType,
    env: *Env,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    return switch (structure) {
        .nominal_type => |nominal| try self.nominalHasPendingOpenLiteralForDerivedEncode(nominal, env, visited),
        .record => |record| try self.recordHasPendingOpenLiteralForDerivedEncode(record.fields, env, visited) or
            try self.varHasPendingOpenLiteralForDerivedEncode(record.ext, env, visited),
        .record_unbound => |fields| try self.recordHasPendingOpenLiteralForDerivedEncode(fields, env, visited),
        .tag_union => |tag_union| try self.tagUnionHasPendingOpenLiteralForDerivedEncode(tag_union, env, visited),
        .tuple => |tuple| blk: {
            const elems = self.types.sliceVars(tuple.elems);
            for (elems) |elem_var| {
                if (try self.varHasPendingOpenLiteralForDerivedEncode(elem_var, env, visited)) break :blk true;
            }
            break :blk false;
        },
        .fn_pure, .fn_effectful, .fn_unbound, .empty_record, .empty_tag_union => false,
    };
}

fn recordHasPendingOpenLiteralForDerivedEncode(
    self: *Self,
    fields_range: types_mod.RecordField.SafeMultiList.Range,
    env: *Env,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    const fields = self.types.getRecordFieldsSlice(fields_range);
    for (fields.items(.presence)) |presence| {
        {
            const field_var = presence.typeVar();
            const child_var = if (try self.missingTryInfoForVar(field_var)) |info| info.ok_var else field_var;
            if (try self.varHasPendingOpenLiteralForDerivedEncode(child_var, env, visited)) return true;
        }
    }
    return false;
}

fn tagUnionHasPendingOpenLiteralForDerivedEncode(
    self: *Self,
    tag_union: types_mod.TagUnion,
    env: *Env,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    const tags = self.types.getTagsSlice(tag_union.tags);
    for (tags.items(.args)) |tag_args_range| {
        for (self.types.sliceVars(tag_args_range)) |tag_arg| {
            if (try self.varHasPendingOpenLiteralForDerivedEncode(tag_arg, env, visited)) return true;
        }
    }
    return try self.tagExtHasPendingOpenLiteralForDerivedEncode(tag_union.ext, env, visited);
}

fn tagExtHasPendingOpenLiteralForDerivedEncode(
    self: *Self,
    ext_var: Var,
    env: *Env,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    return switch (self.types.resolveVar(ext_var).desc.content) {
        .structure => |structure| switch (structure) {
            .tag_union => |tag_union| try self.tagUnionHasPendingOpenLiteralForDerivedEncode(tag_union, env, visited),
            .record, .record_unbound, .tuple, .nominal_type, .fn_pure, .fn_effectful, .fn_unbound, .empty_record, .empty_tag_union => false,
        },
        .alias => |alias| try self.tagExtHasPendingOpenLiteralForDerivedEncode(self.types.getAliasBackingVar(alias), env, visited),
        .flex, .rigid, .field_presence, .err => false,
    };
}

fn nominalHasPendingOpenLiteralForDerivedEncode(
    self: *Self,
    nominal: types_mod.NominalType,
    env: *Env,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    if (self.nominalListPayloadVar(nominal)) |payload_var| {
        return try self.varHasPendingOpenLiteralForDerivedEncode(payload_var, env, visited);
    }
    if (self.nominalBoxPayloadVar(nominal)) |payload_var| {
        return try self.varHasPendingOpenLiteralForDerivedEncode(payload_var, env, visited);
    }
    if (self.nominalSetPayloadVar(nominal)) |payload_var| {
        return try self.varHasPendingOpenLiteralForDerivedEncode(payload_var, env, visited);
    }
    if (self.nominalDictKeyValueVars(nominal)) |args| {
        return try self.varHasPendingOpenLiteralForDerivedEncode(args.key, env, visited) or
            try self.varHasPendingOpenLiteralForDerivedEncode(args.value, env, visited);
    }
    if (self.nominalIsBuiltinTryType(nominal)) {
        if (try self.nullTryInfoFromNominal(nominal)) |info| {
            return try self.varHasPendingOpenLiteralForDerivedEncode(info.ok_var, env, visited);
        }
        if (try self.missingTryInfoFromNominal(nominal)) |info| {
            return try self.varHasPendingOpenLiteralForDerivedEncode(info.ok_var, env, visited);
        }
    }
    return false;
}

/// The source region of the numeral literal that put a `from_numeral` constraint
/// on this var, straight from the numeral payload—explicit upstream data, exact
/// even after the literal var was unified with other vars. Quote constraints
/// carry no payload, so this returns null for them and the caller falls back to
/// the var's own region.
fn literalSourceRegion(self: *Self, var_: Var) ?Region {
    const resolved = self.types.resolveVar(var_);
    if (resolved.desc.content != .flex) return null;
    for (self.types.sliceStaticDispatchConstraints(resolved.desc.content.flex.constraints)) |constraint| {
        if (constraint.origin.numeralInfo()) |info| return info.region;
    }
    return null;
}

/// The literal kind this var is an open literal of—derived from its constraint
/// set, never stored. Returns null if the var carries no literal-conversion
/// constraint. The kind tie-break lives in the defaulting oracle
/// (src/types/literal_defaulting.zig), the one implementation every stage uses.
fn varLiteralKind(self: *Self, var_: Var) ?StaticDispatchConstraint.LiteralKind {
    const resolved = self.types.resolveVar(var_);
    if (resolved.desc.content != .flex) return null;
    const constraints = self.types.sliceStaticDispatchConstraints(resolved.desc.content.flex.constraints);
    return literal_defaulting.dominantKind(self.literalMethodIdents(), constraints);
}

// --- Per-kind literal facts, each an exhaustive `switch (LiteralKind)` ---------
//
// Adding a `LiteralKind` variant turns each switch below into a compile error
// until the new kind is handled: the exhaustiveness *is* the checklist for the
// next literal kind (e.g. strings).

/// Default a still-open literal var and COMMIT the result, returning the var the
/// literal was resolved against (for the boundary warning's snapshot).
/// Haskell-style: commit the FIRST candidate in the kind's canonical order that
/// satisfies every dispatch constraint the var accumulated—and the successful
/// probe IS the commit (no rollback-and-redo; see `tryCommitNumeralCandidate`). A
/// literal whose only obligation is its own literal conversion takes the list head
/// directly (the common case, no probing). If no candidate satisfies, the head is
/// committed via the normal unify path anyway, so the post-finalize dispatch pass
/// reports the conflict against the documented default type.
fn commitLiteralDefault(self: *Self, literal_var: Var, kind: StaticDispatchConstraint.LiteralKind, component_fits: exact_numeral.FitSet, env: *Env) Allocator.Error!Var {
    switch (kind) {
        .numeral => {
            const constraint_range = self.types.resolveVar(literal_var).desc.content.flex.constraints;
            if (self.rangeHasNonLiteralConstraint(constraint_range)) {
                for (numeral_default_candidates) |candidate_kind| {
                    // Cheap structural pre-filter: skip the full probe when
                    // read-only inspection PROVES it would fail. Skipping is
                    // observably identical to probing-and-rolling-back, and the
                    // candidate order (first-satisfier semantics) is untouched.
                    if (self.numeralCandidateStructurallyRefuted(candidate_kind, constraint_range)) {
                        // In safety-checked builds, prove the refutation: run the
                        // skipped probe and assert it fails. A failed probe rolls
                        // back completely (`CommitProbe`), so a passing assertion
                        // leaves observable state—var numbering included—
                        // identical to having skipped. A firing assertion means
                        // the refutation logic has drifted from the unifier's
                        // actual semantics (see the per-pair soundness fence on
                        // `structurallyIncompatiblePair` in src/check/unify.zig and
                        // the range-wide fence on
                        // `numeralCandidateStructurallyRefuted`); the witness
                        // commit it leaves behind is moot since we crash.
                        //
                        // This witness probe is deliberately NOT counted in
                        // `bench_probe_attempts`: this candidate was refuted (and
                        // counted as such below via `bench_probe_refuted`), so
                        // counting the safety-only re-probe as an attempt would make
                        // the refuted-count guard test's attempt/refuted bookkeeping
                        // diverge between safety and release builds. Both counters are
                        // per-instance debug-only fields, compiled out entirely in
                        // release builds (no global state, no hot-path cost).
                        if (comptime std.debug.runtime_safety) {
                            const witness = try self.tryCommitNumeralCandidate(literal_var, candidate_kind, constraint_range, component_fits, env);
                            std.debug.assert(witness == null);
                            self.bench_probe_refuted += 1;
                        }
                        continue;
                    }
                    if (comptime std.debug.runtime_safety) self.bench_probe_attempts += 1;
                    if (try self.tryCommitNumeralCandidate(literal_var, candidate_kind, constraint_range, component_fits, env)) |committed_var| {
                        return committed_var;
                    }
                }
                // No candidate satisfied the constraints: the head commit
                // below is a documented conflict. Record the receiver so the
                // dispatch pass's failure path rewinds its speculative merges
                // (see `conflicted_default_literal_vars`).
                try self.recordConflictedDefaultLiteral(literal_var);
            }
            return try self.commitLiteralDefaultHead(literal_var, env);
        },
        // Str is the single candidate for string literals—a one-element
        // candidate list whose head is always committed (and no structural
        // pre-filter: there is no scan to prune). The append-after-validation-
        // failure discipline is the numeral branch's: only a receiver whose
        // method constraints Str provably cannot satisfy is recorded, so the
        // dispatch pass's failure path rewinds its speculative merges instead
        // of retyping the constraint's argument graph against a type the
        // program never chose (see `conflicted_default_literal_vars`). The
        // dispatch pass still reports the conflict against Str. Satisfied
        // constraints go entirely unrecorded; their dispatches discharge
        // normally in the cascade.
        .quote, .interpolation => {
            const constraint_range = self.types.resolveVar(literal_var).desc.content.flex.constraints;
            if (self.rangeHasNonLiteralConstraint(constraint_range) and
                !try self.quoteDefaultSatisfiesConstraints(literal_var, constraint_range, env))
            {
                try self.recordConflictedDefaultLiteral(literal_var);
            }
            return try self.commitQuoteDefault(literal_var, env);
        },
    }
}

/// Record a literal receiver whose documented head default is about to commit
/// even though validation rejected it (see `conflicted_default_literal_vars`).
/// Sole append site, so the debug-only recording counter cannot drift from the
/// list.
fn recordConflictedDefaultLiteral(self: *Self, literal_var: Var) Allocator.Error!void {
    if (comptime std.debug.runtime_safety) self.bench_conflicted_default_records += 1;
    try self.conflicted_default_literal_vars.append(self.gpa, literal_var);
}

/// Pure validation probe for the quote default: whether committing Str to the
/// still-flex quote literal satisfies every non-literal constraint in
/// `constraint_range`—the same acceptance rule the numeral candidate scan
/// applies (`candidateSatisfiesRangeConstraints`), asked as a predicate. The
/// probe always rolls back, leaving observable state identical to never having
/// run: Str is the single candidate, so the commit itself goes through the
/// ordinary head-commit path either way, and the group failure path can ask
/// the same question per quote driver without perturbing its peers.
fn quoteDefaultSatisfiesConstraints(
    self: *Self,
    literal_var: Var,
    constraint_range: StaticDispatchConstraint.SafeList.Range,
    env: *Env,
) Allocator.Error!bool {
    var commit_probe = try self.beginCommitProbe(env);
    defer commit_probe.rollback();

    const candidate_var = try self.freshStr(env, self.getRegionAt(literal_var));
    const unify_result = try commit_probe.unify(literal_var, candidate_var);
    if (!unify_result.isEstablished()) return false;
    return try self.candidateSatisfiesRangeConstraints(&commit_probe, constraint_range, candidate_var, env);
}

/// Commit Str—the single (and therefore default) candidate for string literals—
/// to `literal_var` through the normal unify path. The committed var reuses the
/// literal's region so later diagnostics stay anchored to the source; the deferred
/// from_quote dispatch fires against Str as usual.
fn commitQuoteDefault(self: *Self, literal_var: Var, env: *Env) Allocator.Error!Var {
    const default_var = try self.freshStr(env, self.getRegionAt(literal_var));
    _ = try self.unify(literal_var, default_var, env);
    return default_var;
}

/// Commit the canonical default (the candidate list head, Dec) to `literal_var`
/// through the normal unify path: the literal's dispatch constraints defer as
/// usual, so when no candidate satisfied them the dispatch pass reports the
/// conflict against the documented default type with problems recorded.
fn commitLiteralDefaultHead(self: *Self, literal_var: Var, env: *Env) Allocator.Error!Var {
    // The synthetic default var reuses the literal's region: if it ends up the
    // union-find root, a later diagnostic would otherwise anchor at Region.zero()—
    // the useless 1:1.
    const literal_region = self.getRegionAt(literal_var);
    const default_var = try self.freshFromContent(
        try self.mkBuiltinNumberTypeContentFromKind(numeral_default_candidates[0]),
        env,
        literal_region,
    );
    _ = try self.unify(literal_var, default_var, env);
    return default_var;
}

/// Candidate order for numeral defaulting, owned by the defaulting oracle
/// (src/types/literal_defaulting.zig—see its doc for the ordering rationale)
/// and mapped here into the `CIR.NumKind` values the probe machinery consumes.
const numeral_default_candidates = blk: {
    var kinds: [literal_defaulting.numeral_default_candidates.len]CIR.NumKind = undefined;
    for (literal_defaulting.numeral_default_candidates, 0..) |target, index| {
        kinds[index] = numKindFromNumeralTarget(target);
    }
    break :blk kinds;
};

/// The `CIR.NumKind` for a builtin numeral target type (exhaustive by tag
/// name: a new target fails to compile until NumKind has a matching tag).
fn numKindFromNumeralTarget(target: exact_numeral.Target) CIR.NumKind {
    return switch (target) {
        inline .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => |t| @field(CIR.NumKind, @tagName(t)),
    };
}

/// Whether `var_` resolves to a literal whose documented head default was
/// committed after validation rejected it—every numeral candidate failed, or
/// Str failed the quote predicate probe (see
/// `conflicted_default_literal_vars`). Both sides re-resolve at query time:
/// the class root can drift as later unifications merge into it—which is why
/// the entries only live until the recording rounds' cascade has consumed
/// them.
fn varIsConflictedDefaultLiteral(self: *const Self, var_: Var) bool {
    if (self.conflicted_default_literal_vars.items.len == 0) return false;
    const root = self.types.resolveVar(var_).var_;
    for (self.conflicted_default_literal_vars.items) |recorded| {
        if (self.types.resolveVar(recorded).var_ == root) return true;
    }
    return false;
}

/// Whether the constraint range carries any obligation besides literal-conversion
/// provenance—i.e. whether defaulting must consult the candidate probe at all.
fn rangeHasNonLiteralConstraint(self: *Self, range: StaticDispatchConstraint.SafeList.Range) bool {
    for (self.types.sliceStaticDispatchConstraints(range)) |constraint| {
        if (constraint.origin != .from_literal) return true;
    }
    return false;
}

/// Structural pre-filter for `tryCommitNumeralCandidate`: returns true only when
/// read-only inspection PROVES the full probe would fail, so the probe can be
/// skipped without observable difference (a failed probe is fully rolled back, so
/// skipping it leaves identical state). Resolves vars in the relevant stores but
/// NEVER mutates them. Anything uncertain returns false (fall through to the
/// probe)—refutation is exact logic, probing is the default.
///
/// This filter implements no language rule of its own: the acceptance rule is
/// `staticDispatchConstraintAcceptsCandidate`'s (see its doc comment), and this
/// function must refute exactly when that probe would fail. Safety-checked
/// builds prove every refutation by running the skipped probe and asserting it
/// fails (the witness in `commitLiteralDefault`), so a drift between this
/// logic and the unifier's semantics crashes rather than changing which
/// default a literal picks.
///
/// Two refutation facts, per non-literal constraint (the literal-conversion
/// ones are pre-filtered by digit-fit inside `tryCommitNumeralCandidate` via
/// `literalInfoAcceptsBuiltinNumKind`):
///
/// 1. Method lookup miss: the candidate's owner env has no method for the
///    constraint's `fn_name`. The probe performs the IDENTICAL lookup
///    (`staticDispatchConstraintAcceptsCandidate` resolves the candidate nominal's
///    origin/source-decl—the very values computed here without minting the
///    candidate var—and calls `lookupMethodBindingFromEnvAndDeclConst`, a pure
///    read of finalized tables) and returns false on a miss, failing the probe.
///    This fact does not depend on any mutable type state, so it refutes
///    unconditionally.
///
/// 2. Dispatcher-position mismatch: a `.refuting` pair from
///    `unifier.structurallyIncompatiblePair`—a signature position where the
///    method is the dispatcher type C itself while the constraint's corresponding
///    position is already a CONCRETE builtin numeric nominal with a different
///    source decl. Nominal unification requires identical identity
///    (`sameNominalIdentity`: origin + source decl), so that position's unify must
///    throw—the probe cannot succeed. (The dispatcher-position check is made per
///    position, not assumed; the filter's EFFECTIVENESS comes from builtin numeric
///    methods being homogeneous (`T, T -> T`, e.g. `Dec.plus : Dec, Dec -> Dec`),
///    which puts the dispatcher type at every position.)
///
/// Fact 2's per-pair soundness fence—the unifier's err-backed-nominal
/// short-circuit (a SUCCESSFUL err merge), flex-side constraint deferral, and
/// never-written nominal backings—is documented on and encoded in
/// `structurallyIncompatiblePair` in src/check/unify.zig, co-located with the
/// unify internals it reasons about. This function supplies the RANGE-WIDE side of
/// that fence: it classifies every argument/return position of EVERY constraint in
/// the range, requires matching arities (so every classified pair is exactly the
/// pair `unifyFunc` would visit), and abandons refutation for the whole candidate
/// on any `.uninspectable` position. Any deviation—aliases, records, tag unions,
/// tuples, err content, polymorphic method positions, unexpected arity, non-fn
/// shapes—makes the whole candidate fall through to the probe rather than
/// weakening soundness.
fn numeralCandidateStructurallyRefuted(
    self: *Self,
    candidate_kind: CIR.NumKind,
    constraint_range: StaticDispatchConstraint.SafeList.Range,
) bool {
    // The candidate's identity, computed without creating its var: the same origin
    // module + source decl `mkNumberTypeContent` embeds in the nominal the probe
    // would mint.
    const candidate_source_decl = self.sourceDeclForBuiltinNominal(.{ .num = candidate_kind });
    const candidate_origin_module = self.builtinOriginModule();
    const owner_env, _ = self.ownerEnvForOriginModule(
        candidate_origin_module,
        candidate_source_decl,
        true,
        "static dispatch candidate",
    );

    var found_refuting_pair = false;
    for (self.types.sliceStaticDispatchConstraints(constraint_range)) |constraint| {
        if (constraint.origin == .from_literal) continue;

        // Method lookup short of instantiation—same env, owner decl, and method
        // ident the probe's lookup uses, via the same const lookup.
        const method_lookup = self.lookupStaticDispatchMethodBinding(
            owner_env,
            candidate_source_decl,
            self.cir,
            constraint.fn_name,
        ) orelse return true;
        const method_types: *const types_mod.Store = if (method_lookup.is_this_module) self.types else &method_lookup.env.types;
        const def_var: Var = ModuleEnv.varFrom(method_lookup.binding.type_node_idx);

        // From here on, refutation needs the closed-world structural walk;
        // any uncertainty falls through to the probe (return false).
        const method_func = method_types.resolveVar(def_var).desc.content.unwrapFunc() orelse return false;
        const constraint_func = self.types.resolveVar(constraint.fn_var).desc.content.unwrapFunc() orelse return false;
        if (method_func.args.len() != constraint_func.args.len()) return false;

        const method_args = method_types.sliceVars(method_func.args);
        const constraint_args = self.types.sliceVars(constraint_func.args);
        for (method_args, constraint_args) |method_pos, constraint_pos| {
            switch (unifier.structurallyIncompatiblePair(method_types, self.types, candidate_source_decl, method_pos, constraint_pos)) {
                .uninspectable => return false,
                .refuting => found_refuting_pair = true,
                .safe => {},
            }
        }
        switch (unifier.structurallyIncompatiblePair(method_types, self.types, candidate_source_decl, method_func.ret, constraint_func.ret)) {
            .uninspectable => return false,
            .refuting => found_refuting_pair = true,
            .safe => {},
        }
    }
    return found_refuting_pair;
}

/// Probe whether committing builtin numeric `candidate_kind` to the open
/// numeral `literal_var` satisfies every constraint in `constraint_range`—and
/// if so, COMMIT the probe's work in place, returning the committed candidate var.
/// The probe runs against the real stores through the normal `unify` wrapper, so
/// success needs no rollback-and-redo: the literal var is already resolved to the
/// candidate, with full bookkeeping (var pool, regions, deferred dispatch
/// constraints—which the later dispatch pass fires exactly as it fires the
/// redo-unify's today). Failure returns null after `CommitProbe.rollback` restores
/// every store and buffer the attempt grew.
fn tryCommitNumeralCandidate(
    self: *Self,
    literal_var: Var,
    candidate_kind: CIR.NumKind,
    constraint_range: StaticDispatchConstraint.SafeList.Range,
    component_fits: exact_numeral.FitSet,
    env: *Env,
) Allocator.Error!?Var {
    // The candidate must be able to represent every literal in this literal's
    // interference component—the O(1) bit test on the precomputed
    // intersection runs first—AND every from_literal payload in the
    // driver's own range. The walk is NOT subsumed by the bit test: a range
    // can carry from_literal QUOTE constraints (a numeral flex unified with a
    // quote flex defers the conflict), which refute every numeric candidate
    // but contribute nothing to the numeral fit-set intersection. Both are
    // pure arithmetic, checked before any store mutation so refuting a
    // candidate on digits alone costs no speculation at all.
    if (!componentFitsAcceptNumKind(component_fits, candidate_kind)) return null;
    if (!self.rangeNumeralDigitsFit(constraint_range, candidate_kind)) return null;

    var commit_probe = try self.beginCommitProbe(env);
    var committed = false;
    defer if (!committed) commit_probe.rollback();

    // The candidate (and every other var this attempt creates—the unify's fresh
    // vars, instantiated method vars) registers in the CALLER's env pool: on
    // success the work survives into generalization, so the generalizer must see
    // these vars at their real ranks. (A probe-local pool—the previous design—
    // would be released on success and leave the committed store vars invisible to
    // rank adjustment; conversely, the dangling-entry hazard that design avoided
    // is now closed by `CommitProbe.rollback` truncating the pool's rank lists on
    // failure.) Region: the literal's own, so vars the probe stamps stay anchored
    // to the real source span.
    const candidate_var = try self.freshFromContent(
        try self.mkBuiltinNumberTypeContentFromKind(candidate_kind),
        env,
        self.getRegionAt(literal_var),
    );
    const unify_result = try commit_probe.unify(literal_var, candidate_var);
    if (!unify_result.isEstablished()) return null;

    if (!try self.candidateSatisfiesRangeConstraints(&commit_probe, constraint_range, candidate_var, env)) return null;

    committed = true;
    commit_probe.commit();
    return candidate_var;
}

/// Whether the concrete builtin numeric candidate of `num_kind` can represent
/// the literal payload `lit`. The numeral arm validates the digits fit;
/// future kinds fill in their own arm (compiler-enforced).
fn literalInfoAcceptsBuiltinNumKind(lit: StaticDispatchConstraint.LiteralInfo, num_kind: CIR.NumKind) bool {
    return switch (lit) {
        .numeral => |info| validateBuiltinFromNumeralLiteral(num_kind, info) == null,
        // A string or interpolation literal can never be represented by a builtin
        // numeric type; its sole candidate (Str) is not a builtin num kind.
        .quote, .interpolation => false,
    };
}

/// The method-acceptance rule of static dispatch—the intended language rule,
/// not an implementation convenience: a candidate nominal type satisfies a
/// dispatch constraint `fn_name : F` iff the type's declaring module provides
/// a method binding named `fn_name` whose declared type, instantiated fresh,
/// unifies with `F`. The two rejected sides are a missing binding and a
/// signature mismatch; nothing structural is consulted here (structural
/// eq/hash derivation is decided by the constraint's own origin/allowance,
/// upstream of this check).
///
/// Speculatively mutates the real stores (copyVar/instantiateVar, real
/// unification) and does NOT roll them back itself—the caller's commit-probe
/// rollback does (or its commit keeps them). The `*CommitProbe` parameter is a
/// scope-proof token making that contract compile-time: this function is
/// unreachable without an open commit-probe scope that settles the speculation one
/// way or the other.
fn staticDispatchConstraintAcceptsCandidate(
    self: *Self,
    probe: *CommitProbe,
    constraint: StaticDispatchConstraint,
    candidate_var: Var,
    env: *Env,
) Allocator.Error!bool {
    const candidate_resolved = self.types.resolveVar(candidate_var);
    const nominal_type = candidate_resolved.desc.content.unwrapNominalType() orelse return false;
    const owner_env, _ = self.ownerEnvForOriginModule(
        nominal_type.origin_module,
        nominal_type.sourceDeclOptional(),
        nominal_type.originIsBuiltin(),
        "static dispatch candidate",
    );

    const method_lookup = self.lookupStaticDispatchMethodBinding(
        owner_env,
        nominal_type.sourceDeclOptional(),
        self.cir,
        constraint.fn_name,
    ) orelse return false;
    const def_var: Var = ModuleEnv.varFrom(method_lookup.binding.type_node_idx);

    const method_var = if (method_lookup.is_this_module) blk: {
        break :blk try self.instantiateBindingVar(def_var, env, .use_last_var);
    } else blk: {
        const imported_scheme = try self.importedMethodScheme(method_lookup);
        break :blk try self.instantiateVar(imported_scheme, env, .{ .explicit = self.getRegionAt(candidate_var) });
    };

    // The real unify wrapper, not the throwaway-store probe unify: on the commit
    // path this merge (and its rank/region/deferred-constraint bookkeeping) is
    // kept. The probe owns failure, so a mismatch must not run occurrence-directed
    // poisoning while the store savepoint is active.
    const result = try probe.unify(method_var, constraint.fn_var);
    return result.isEstablished();
}

/// Whether every numeral literal in a defaulting component's combined fit set
/// accepts the candidate. Unbound kinds impose no obligation.
fn componentFitsAcceptNumKind(component_fits: exact_numeral.FitSet, candidate_kind: CIR.NumKind) bool {
    const target = numeralTargetFromNumKind(candidate_kind) orelse return true;
    return component_fits.contains(target);
}

/// Whether the builtin numeric candidate `candidate_kind` can represent every
/// `from_literal` numeral payload in `range` (digit fit). Pure arithmetic on the
/// constraint payloads—no speculation. Shared digit-fit precheck for the
/// single-literal and group numeral probes.
fn rangeNumeralDigitsFit(
    self: *Self,
    range: StaticDispatchConstraint.SafeList.Range,
    candidate_kind: CIR.NumKind,
) bool {
    for (self.types.sliceStaticDispatchConstraints(range)) |constraint| {
        switch (constraint.origin) {
            .from_literal => |lit| {
                if (!literalInfoAcceptsBuiltinNumKind(lit, candidate_kind)) return false;
            },
            .desugared_binop, .desugared_unaryop, .method_call, .where_clause => {},
        }
    }
    return true;
}

/// Whether `candidate_var` satisfies every non-`from_literal` dispatch constraint
/// in `range`, under the open `probe` scope. Uses the store-backed iterator (not a
/// held slice) because verification appends to the constraint store, which can
/// reallocate. Shared phase-2 verify for the single-literal and group numeral
/// probes.
fn candidateSatisfiesRangeConstraints(
    self: *Self,
    probe: *CommitProbe,
    range: StaticDispatchConstraint.SafeList.Range,
    candidate_var: Var,
    env: *Env,
) Allocator.Error!bool {
    var constraints_iter = self.types.iterStaticDispatchConstraints(range);
    while (constraints_iter.next()) |constraint| {
        switch (constraint.origin) {
            .from_literal => {},
            .desugared_binop, .desugared_unaryop, .method_call, .where_clause => {
                if (!try self.staticDispatchConstraintAcceptsCandidate(probe, constraint, candidate_var, env)) {
                    return false;
                }
            },
        }
    }
    return true;
}

fn isBuiltinNumericNominal(self: *Self, var_: Var) bool {
    const resolved = self.types.resolveVar(var_);
    const nominal = resolved.desc.content.unwrapNominalType() orelse return false;
    const ident = nominal.ident.ident_idx;
    return ident.eql(self.cir.idents.u8_type) or
        ident.eql(self.cir.idents.i8_type) or
        ident.eql(self.cir.idents.u16_type) or
        ident.eql(self.cir.idents.i16_type) or
        ident.eql(self.cir.idents.u32_type) or
        ident.eql(self.cir.idents.i32_type) or
        ident.eql(self.cir.idents.u64_type) or
        ident.eql(self.cir.idents.i64_type) or
        ident.eql(self.cir.idents.u128_type) or
        ident.eql(self.cir.idents.i128_type) or
        ident.eql(self.cir.idents.f32_type) or
        ident.eql(self.cir.idents.f64_type) or
        ident.eql(self.cir.idents.dec_type);
}

/// Whether `var_` resolved to the builtin `Dec` nominal—the canonical head
/// default a numeral literal falls to. Distinguishes a numeral-defaulted
/// dispatcher (Dec) from a quote-defaulted one (Str), so the "this numeric
/// literal was given the type Dec" hint only fires for the former. The hint text
/// hardcodes `Dec`, so a literal pinned to some other numeric type must not
/// claim it.
fn isDecNominal(self: *Self, var_: Var) bool {
    const resolved = self.types.resolveVar(var_);
    const nominal = resolved.desc.content.unwrapNominalType() orelse return false;
    return nominal.ident.ident_idx.eql(self.cir.idents.dec_type);
}

fn pushReturnConstraintFrame(
    self: *Self,
    lambda_idx: CIR.Expr.Idx,
    body_result: Var,
    expected_result: ?Var,
) std.mem.Allocator.Error!void {
    try self.return_constraint_frames.append(self.gpa, .{
        .lambda = lambda_idx,
        .start = self.return_constraints.items.len,
        .body_result = body_result,
        .expected_result = expected_result,
    });
}

fn currentExpectedReturnResult(self: *const Self) ?Var {
    if (self.return_constraint_frames.items.len == 0) return null;
    return self.return_constraint_frames.items[self.return_constraint_frames.items.len - 1].expected_result;
}

fn expectedReturnResultFor(self: *const Self, lambda_idx: CIR.Expr.Idx) ?Var {
    std.debug.assert(self.return_constraint_frames.items.len > 0);
    const frame = self.return_constraint_frames.items[self.return_constraint_frames.items.len - 1];
    std.debug.assert(frame.lambda == lambda_idx);
    return frame.expected_result;
}

fn discardReturnConstraintFrame(self: *Self, lambda_idx: CIR.Expr.Idx) void {
    std.debug.assert(self.return_constraint_frames.items.len > 0);
    const frame_idx = self.return_constraint_frames.items.len - 1;
    const frame = self.return_constraint_frames.items[frame_idx];
    std.debug.assert(frame.lambda == lambda_idx);
    self.return_constraints.shrinkRetainingCapacity(frame.start);
    self.return_constraint_frames.shrinkRetainingCapacity(frame_idx);
}

fn appendReturnConstraint(
    self: *Self,
    lambda_idx: CIR.Expr.Idx,
    actual_expr: CIR.Expr.Idx,
    kind: ReturnConstraintKind,
) std.mem.Allocator.Error!void {
    std.debug.assert(self.return_constraint_frames.items.len > 0);
    const frame = self.return_constraint_frames.items[self.return_constraint_frames.items.len - 1];
    std.debug.assert(frame.lambda == lambda_idx);
    try self.return_constraints.append(self.gpa, .{
        .actual_expr = actual_expr,
        .kind = kind,
    });
}

fn checkReturnRelation(
    self: *Self,
    expected: Var,
    actual_expr: CIR.Expr.Idx,
    ctx: problem.Context,
    env: *Env,
) std.mem.Allocator.Error!void {
    const result = try self.unifyInContext(expected, ModuleEnv.varFrom(actual_expr), env, ctx);
    if (result.isProblem()) {
        try self.erroneous_value_exprs.put(self.gpa, actual_expr, {});
    }
}

/// Process the return-flow constraints owned by this lambda. Called at the end
/// of e_lambda to ensure return type information is unified with the body type
/// before the function type is generalized.
fn processReturnConstraints(self: *Self, env: *Env, lambda_idx: CIR.Expr.Idx) std.mem.Allocator.Error!void {
    std.debug.assert(self.return_constraint_frames.items.len > 0);
    const frame_idx = self.return_constraint_frames.items.len - 1;
    const frame = self.return_constraint_frames.items[frame_idx];
    std.debug.assert(frame.lambda == lambda_idx);

    for (self.return_constraints.items[frame.start..]) |constraint| {
        try self.checkReturnRelation(
            frame.body_result,
            constraint.actual_expr,
            constraint.kind.problemContext(),
            env,
        );
    }

    self.return_constraints.shrinkRetainingCapacity(frame.start);
    self.return_constraint_frames.shrinkRetainingCapacity(frame_idx);
}

/// Resolve one `eql` constraint.
fn resolveEqlConstraint(self: *Self, eql: anytype, env: *Env) std.mem.Allocator.Error!void {
    _ = try self.unifyInContext(eql.expected, eql.actual, env, eql.ctx);
}

/// Check any accumulated constraints
fn checkConstraints(self: *Self, env: *Env) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    var iter = self.constraints.iterIndices();
    while (iter.next()) |idx| {
        const constraint = self.constraints.get(idx);
        switch (constraint.*) {
            .eql => |eql| {
                try self.resolveEqlConstraint(eql, env);
            },
        }
    }
    self.constraints.items.clearRetainingCapacity();
}

/// Check static dispatch constraints
///
/// Note that new constraints can be added as we are processing. For example:
///
///  Test := [Val(Str)].{
///    to_str = |Test.Val(s)| s
///    to_str2 = |test| test.to_str()
///  }
///  main = Test.Val("hello").to_str2()
///
/// Initially, we only have to check constraint for `Test.to_str2`. But when we
/// process that, we then have to check `Test.to_str`.
fn importedMethodScheme(
    self: *Self,
    method_lookup: StaticDispatchMethodBinding,
) Allocator.Error!Var {
    std.debug.assert(!method_lookup.is_this_module);
    return self.importedMethodSchemeFromSource(method_lookup.env, method_lookup.binding.type_node_idx);
}

fn importedMethodSchemeFromSource(
    self: *Self,
    source_env: *const ModuleEnv,
    type_node_idx: CIR.Node.Idx,
) Allocator.Error!Var {
    const key = ImportedMethodSchemeKey{
        .env = source_env,
        .type_node_idx = type_node_idx,
    };
    if (self.imported_method_scheme_by_source.get(key)) |index| {
        return self.imported_method_schemes.items[index].scheme_var;
    }

    try self.imported_method_schemes.ensureUnusedCapacity(self.gpa, 1);
    try self.imported_method_scheme_by_source.ensureUnusedCapacity(self.gpa, 1);

    // The cached graph is the generalized import scheme, not a use. Keep it
    // source-owned and regionless; each fresh instantiation below receives its
    // own use-site region and can be unified or rejected independently.
    const source_var = ModuleEnv.varFrom(type_node_idx);
    const scheme_var = try self.copyVar(source_var, source_env, null);
    const index: u32 = @intCast(self.imported_method_schemes.items.len);
    self.imported_method_schemes.appendAssumeCapacity(.{
        .key = key,
        .scheme_var = scheme_var,
    });
    self.imported_method_scheme_by_source.putAssumeCapacityNoClobber(key, index);
    return scheme_var;
}

fn recordDispatchDerivations(
    self: *Self,
    constraints: StaticDispatchConstraint.SafeList.Range,
    parent_fn_var: Var,
) Allocator.Error!void {
    for (self.types.sliceStaticDispatchConstraints(constraints)) |constraint| {
        // A child that has already selected a dispatch target, or that
        // already carries a parent, keeps its first recorded edge.
        if (self.dispatch_target_instantiation_by_fn_var.contains(constraint.fn_var)) continue;
        const derived_parent = self.dispatchDerivationParentOutsideClass(
            constraint.fn_var,
            parent_fn_var,
        ) orelse continue;
        const entry = try self.dispatch_derivation_by_child_fn_var.getOrPut(self.gpa, constraint.fn_var);
        if (entry.found_existing) continue;
        errdefer _ = self.dispatch_derivation_by_child_fn_var.remove(constraint.fn_var);
        entry.value_ptr.* = derived_parent;
        try self.dispatch_derivations.append(self.gpa, .{
            .child_fn_var = constraint.fn_var,
            .parent_fn_var = derived_parent,
        });
    }
}

/// The edge target for a child derived under `parent_fn_var`: the nearest
/// entry at or above the parent on the parent's own derivation chain whose
/// union-find class differs from the child's, or null when the chain holds
/// none and the child genuinely is a chain root.
///
/// The parent graph must stay acyclic, so an edge is recorded only when its
/// target is outside the child's class. A child can land in its parent's own
/// class: instantiating a scheme can share a non-generalized callable rather
/// than copy it, so a receiver whose own relation is the dispatch target
/// re-attaches that relation to itself, and unification can merge a fresh
/// child into the class its parent already names. Skipping such an edge
/// entirely would make the child a chain root, and both lineage detectors
/// stop at a root—so the divergent chain running through it, and every
/// descendant below it, would never be rejected. Hopping to the nearest
/// ancestor outside the class keeps the chain intact and still cannot create
/// a cycle: the recorded target is a strict ancestor that the child's class
/// does not contain. Classes are compared through resolved roots, since a
/// unified var no longer equal to its root still names the same class.
fn dispatchDerivationParentOutsideClass(
    self: *const Self,
    child_fn_var: Var,
    parent_fn_var: Var,
) ?Var {
    const child_root = self.types.resolveVar(child_fn_var).var_;
    var ancestor_fn_var = parent_fn_var;
    var followed_edges: usize = 0;
    while (true) {
        if (self.types.resolveVar(ancestor_fn_var).var_ != child_root) return ancestor_fn_var;
        ancestor_fn_var = self.dispatch_derivation_by_child_fn_var.get(ancestor_fn_var) orelse return null;
        followed_edges += 1;
        // The walk follows one recorded edge per step and the graph is
        // acyclic, so the recorded edge count bounds it. Exhausting that
        // bound would mean the graph holds a cycle, which the rule above
        // forbids.
        if (followed_edges > self.dispatch_derivations.items.len) {
            std.debug.assert(false);
            return null;
        }
    }
}

fn shrinkDispatchDerivationsTo(self: *Self, new_len: usize) void {
    while (self.dispatch_derivations.items.len > new_len) {
        const derivation = self.dispatch_derivations.pop().?;
        const did_remove = self.dispatch_derivation_by_child_fn_var.remove(derivation.child_fn_var);
        std.debug.assert(did_remove);
    }
}

/// Canonical receiver+callable digest for one dispatch edge. Fresh
/// instantiated vars are deliberately ignored as identities: the canonical
/// type digest alpha-normalizes them, while concrete structural progress
/// changes the digest. Erroneous content digests per poisoned var, so two
/// states poisoned by unrelated failures never compare equal while a chain
/// that genuinely cycles through one poisoned var still digests stably.
fn dispatchStateTypeKey(
    self: *Self,
    dispatcher_var: Var,
    constraint_fn_var: Var,
) Allocator.Error![32]u8 {
    const receiver_key = try canonical_type_keys.fromVarErrSensitive(self.gpa, self.types, self.cir, dispatcher_var);
    const callable_key = try canonical_type_keys.fromVarErrSensitive(self.gpa, self.types, self.cir, constraint_fn_var);
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    hasher.update(&receiver_key.bytes);
    hasher.update(&callable_key.bytes);
    return hasher.finalResult();
}

/// Whether selecting `method_lookup` for this obligation would repeat a
/// semantic dispatch state already on its explicit derivation chain. A state
/// repeats only when its digest and the exact selected method binding both
/// match an ancestor. Every ancestor's key was computed at its own record
/// time, so the comparison never depends on which descendant or fixpoint
/// pass walks the lineage first.
fn dispatchStateKeyRepeatsAncestor(
    self: *Self,
    constraint: StaticDispatchConstraint,
    parent_constraint_fn_var: ?Var,
    method_lookup: StaticDispatchMethodBinding,
    state_type_key: [32]u8,
) bool {
    var steps: usize = 0;
    var ancestor_fn = parent_constraint_fn_var;
    while (ancestor_fn) |fn_var| {
        const ancestor_idx = self.dispatch_target_instantiation_by_fn_var.get(fn_var) orelse return false;
        steps += 1;
        std.debug.assert(steps <= self.dispatch_target_instantiations.items.len);
        const ancestor = self.dispatch_target_instantiations.items[ancestor_idx];
        if (ancestor.target_env == method_lookup.env and
            std.meta.eql(ancestor.target_binding, method_lookup.binding) and
            ancestor.method_name.eql(constraint.fn_name))
        {
            if (std.meta.eql(state_type_key, ancestor.state_type_key)) return true;
        }
        ancestor_fn = ancestor.parent_constraint_fn_var;
    }
    return false;
}

/// Whether selecting `method_lookup` re-enters an ancestor edge's exact
/// method binding with a dispatch state into which that ancestor's state
/// strictly embeds, on a lineage that already grew once before. A state
/// embeds when both its receiver and its required callable embed and at
/// least one of them does so strictly: a chain can pump either component
/// (a growing receiver, or a constant receiver whose `where`-shape feeds an
/// ever-deeper type through a non-receiver argument), and every such chain
/// re-derives a strictly larger copy of the same obligation forever even
/// though no two of its states are ever digest-equal. One growth step alone
/// proves nothing: a legal chain may pass through one strictly larger state
/// that simply arrived from a call-site argument (a `where`-clause
/// obligation on a non-receiver type variable). A growth step whose
/// embedded ancestor itself already grew can only come from the derivation
/// pumping its own state, so that edge is rejected. Returns the matched
/// ancestor's receiver for reporting; `grew_from_ancestor` reports whether
/// this edge took a permitted first growth step.
fn dispatchStateGrowsAlongLineage(
    self: *Self,
    dispatcher_var: Var,
    parent_constraint_fn_var: ?Var,
    constraint: StaticDispatchConstraint,
    method_lookup: StaticDispatchMethodBinding,
    grew_from_ancestor: *bool,
) Allocator.Error!?Var {
    grew_from_ancestor.* = false;
    if (parent_constraint_fn_var == null) return null;

    self.scratch_embed_memo.clearRetainingCapacity();
    self.scratch_embed_active_pairs.clearRetainingCapacity();
    self.scratch_embed_cut_count = 0;

    // Embedding never shrinks the normalized walk, so a linear-cost size
    // comparison on the receivers skips the pairwise embedding walks for
    // every ancestor whose receiver cannot possibly embed—on a legal
    // same-binding chain each requirement hop peels structure off the
    // receiver, so every ancestor is larger and the walks never run. Equal
    // sizes must fall through: a chain can hold its receiver fixed and pump
    // the callable instead. A size walk that crossed cyclic structure has no
    // reliable total, so it runs the embedding walk (which cuts cycles
    // pairwise) instead of pruning.
    var dispatcher_size: ?DispatchSizeResult = null;

    var steps: usize = 0;
    var ancestor_fn = parent_constraint_fn_var;
    while (ancestor_fn) |fn_var| {
        const ancestor_idx = self.dispatch_target_instantiation_by_fn_var.get(fn_var) orelse return null;
        steps += 1;
        std.debug.assert(steps <= self.dispatch_target_instantiations.items.len);
        const ancestor = self.dispatch_target_instantiations.items[ancestor_idx];
        if (ancestor.target_env == method_lookup.env and
            std.meta.eql(ancestor.target_binding, method_lookup.binding) and
            ancestor.method_name.eql(constraint.fn_name))
        {
            if (dispatcher_size == null) {
                dispatcher_size = try self.dispatchReceiverSize(dispatcher_var);
            }
            const ancestor_size = try self.dispatchReceiverSize(ancestor.receiver_var);
            const sizes_conclusive = !dispatcher_size.?.saw_cycle and !ancestor_size.saw_cycle;
            if (!sizes_conclusive or ancestor_size.count <= dispatcher_size.?.count) {
                const receiver_grade = try self.dispatchReceiverEmbedGrade(ancestor.receiver_var, dispatcher_var);
                if (receiver_grade != .none) {
                    const callable_grade = try self.dispatchReceiverEmbedGrade(ancestor.constraint_fn_var, constraint.fn_var);
                    if (callable_grade != .none and (receiver_grade == .strict or callable_grade == .strict)) {
                        if (ancestor.grew_from_ancestor) return ancestor.receiver_var;
                        grew_from_ancestor.* = true;
                    }
                }
            }
        }
        ancestor_fn = ancestor.parent_constraint_fn_var;
    }
    return null;
}

const DispatchEmbedPair = struct { small: Var, big: Var };

/// Result of one receiver-embedding comparison. `equal` means the two types
/// coupled at every position without ever descending past a constructor on
/// the big side; `strict` means the walk dove into the big side somewhere or
/// coupled a strictly embedded child, so the big receiver properly grew.
const DispatchEmbedGrade = enum(u8) { none, equal, strict };

const DispatchSizeResult = struct { count: u32, saw_cycle: bool };

const DispatchRowTailKind = enum { closed, open, unbound };

const DispatchRowTail = struct { kind: DispatchRowTailKind, var_: Var };

const DispatchRecordField = struct { name: Ident.Idx, presence: types_mod.RecordField.Presence };

const DispatchUnionTag = struct { name: Ident.Idx, args: Var.SafeList.Range };

fn dispatchSameAliasIdentity(a: types_mod.Alias, b: types_mod.Alias) bool {
    if (a.origin_module != b.origin_module) return false;
    if (a.source_decl.present or b.source_decl.present) {
        return a.source_decl.eql(b.source_decl);
    }
    return a.ident.ident_idx.eql(b.ident.ident_idx);
}

fn dispatchSameNominalIdentity(a: types_mod.NominalType, b: types_mod.NominalType) bool {
    if (a.origin_module != b.origin_module) return false;
    const a_source_decl = a.sourceDecl();
    const b_source_decl = b.sourceDecl();
    if (a_source_decl.present or b_source_decl.present) {
        return a_source_decl.eql(b_source_decl);
    }
    return a.ident.ident_idx.eql(b.ident.ident_idx);
}

fn dispatchVarInList(vars: []const Var, var_: Var) bool {
    for (vars) |candidate| {
        if (candidate == var_) return true;
    }
    return false;
}

/// Homeomorphic-embedding comparison between an ancestor receiver (`small`)
/// and a descendant dispatcher (`big`), mirroring unification's view of type
/// equality position by position:
///
/// - Constructors couple with the same constructor and pair their children;
///   the walk may also dive past any big-side constructor into one of its
///   children, which is what makes growth by insertion visible.
/// - Identity variables couple with any identity variable: a divergent chain
///   mints fresh receiver variables every hop, so pinning them to specific
///   vars would blind the rule to every pumped chain. Structure never couples
///   with a variable.
/// - Erroneous content matches only its own resolved var (the fast path), so
///   receivers poisoned by unrelated failures never compare related while a
///   chain threading one poisoned var is still tracked.
/// - Same-identity aliases pair their arguments and backing exactly as
///   unification does, phantom arguments included. Any other alias on the
///   big side is transparent spelling and is looked through; an alias on the
///   small side couples only with its own identity, so its arguments are
///   never silently discarded.
/// - Rows normalize their extension chains first and couple only on an
///   identical field/tag layout, then pair the member types and tails.
///
/// In-progress pairs cut the walk (`.none`) so cyclic structure terminates;
/// completed pairs are memoized unless an in-progress cut fired somewhere
/// below them, since such a result is specific to the path that computed it.
fn dispatchReceiverEmbedGrade(self: *Self, small_var: Var, big_var: Var) Allocator.Error!DispatchEmbedGrade {
    const small = self.types.resolveVar(small_var);
    const big = self.types.resolveVar(big_var);
    if (small.var_ == big.var_) return .equal;

    const pair: DispatchEmbedPair = .{ .small = small.var_, .big = big.var_ };
    if (self.scratch_embed_memo.get(pair)) |grade| return grade;
    for (self.scratch_embed_active_pairs.items) |active_pair| {
        if (active_pair.small == pair.small and active_pair.big == pair.big) {
            self.scratch_embed_cut_count += 1;
            return .none;
        }
    }
    try self.scratch_embed_active_pairs.append(self.gpa, pair);
    const cuts_before = self.scratch_embed_cut_count;

    const grade = blk: {
        const couple = try self.dispatchEmbedCoupleGrade(small, big);
        if (couple == .strict) break :blk DispatchEmbedGrade.strict;
        if (try self.dispatchEmbedDivesIntoChild(small.var_, big)) break :blk DispatchEmbedGrade.strict;
        break :blk couple;
    };

    const popped = self.scratch_embed_active_pairs.pop().?;
    std.debug.assert(popped.small == pair.small and popped.big == pair.big);
    if (self.scratch_embed_cut_count == cuts_before) {
        try self.scratch_embed_memo.put(self.gpa, pair, grade);
    }
    return grade;
}

fn dispatchEmbedCoupleGrade(
    self: *Self,
    small: types_mod.ResolvedVarDesc,
    big: types_mod.ResolvedVarDesc,
) Allocator.Error!DispatchEmbedGrade {
    const small_content = small.desc.content;
    const big_content = big.desc.content;

    if (small_content == .alias and big_content == .alias and
        dispatchSameAliasIdentity(small_content.alias, big_content.alias))
    {
        const small_alias = small_content.alias;
        const big_alias = big_content.alias;
        const small_args = self.types.sliceAliasArgs(small_alias);
        const big_args = self.types.sliceAliasArgs(big_alias);
        if (small_args.len != big_args.len) return .none;
        var strict = false;
        switch (try self.dispatchReceiverEmbedGrade(
            self.types.getAliasBackingVar(small_alias),
            self.types.getAliasBackingVar(big_alias),
        )) {
            .none => return .none,
            .strict => strict = true,
            .equal => {},
        }
        for (small_args, big_args) |small_arg, big_arg| {
            switch (try self.dispatchReceiverEmbedGrade(small_arg, big_arg)) {
                .none => return .none,
                .strict => strict = true,
                .equal => {},
            }
        }
        return if (strict) .strict else .equal;
    }
    if (big_content == .alias) {
        return try self.dispatchReceiverEmbedGrade(
            small.var_,
            self.types.getAliasBackingVar(big_content.alias),
        );
    }

    switch (small_content) {
        .err => return .none,
        .flex, .rigid => return switch (big_content) {
            .flex, .rigid => .equal,
            .alias, .field_presence, .structure, .err => .none,
        },
        .alias => return .none,
        .field_presence => |small_presence| {
            if (big_content != .field_presence) return .none;
            return if (std.meta.eql(small_presence, big_content.field_presence)) .equal else .none;
        },
        .structure => |small_flat| {
            if (big_content != .structure) return .none;
            const big_flat = big_content.structure;
            switch (small_flat) {
                .tuple => |small_tuple| {
                    if (big_flat != .tuple) return .none;
                    const small_elems = self.types.sliceVars(small_tuple.elems);
                    const big_elems = self.types.sliceVars(big_flat.tuple.elems);
                    if (small_elems.len != big_elems.len) return .none;
                    return try self.dispatchEmbedPairwiseGrade(small_elems, big_elems);
                },
                .nominal_type => |small_nominal| {
                    if (big_flat != .nominal_type) return .none;
                    const big_nominal = big_flat.nominal_type;
                    if (!dispatchSameNominalIdentity(small_nominal, big_nominal)) return .none;
                    const small_args = self.types.sliceNominalArgs(small_nominal);
                    const big_args = self.types.sliceNominalArgs(big_nominal);
                    if (small_args.len != big_args.len) return .none;
                    return try self.dispatchEmbedPairwiseGrade(small_args, big_args);
                },
                .fn_pure, .fn_unbound, .fn_effectful => |small_func| {
                    const big_func = switch (big_flat) {
                        .fn_pure, .fn_unbound, .fn_effectful => |func| func,
                        .empty_record, .record, .record_unbound, .empty_tag_union, .tag_union, .tuple, .nominal_type => return .none,
                    };
                    // An unbound function can still commit either way, so it
                    // couples with everything; pure and effectful couple only
                    // with themselves, exactly as unification allows.
                    const small_is_pure = small_flat == .fn_pure;
                    const small_is_effectful = small_flat == .fn_effectful;
                    const big_is_pure = big_flat == .fn_pure;
                    const big_is_effectful = big_flat == .fn_effectful;
                    if ((small_is_pure and big_is_effectful) or (small_is_effectful and big_is_pure)) return .none;
                    const small_args = self.types.sliceVars(small_func.args);
                    const big_args = self.types.sliceVars(big_func.args);
                    if (small_args.len != big_args.len) return .none;
                    var strict = false;
                    switch (try self.dispatchEmbedPairwiseGrade(small_args, big_args)) {
                        .none => return .none,
                        .strict => strict = true,
                        .equal => {},
                    }
                    switch (try self.dispatchReceiverEmbedGrade(small_func.ret, big_func.ret)) {
                        .none => return .none,
                        .strict => strict = true,
                        .equal => {},
                    }
                    return if (strict) .strict else .equal;
                },
                .empty_record, .record, .record_unbound => {
                    switch (big_flat) {
                        .empty_record, .record, .record_unbound => {},
                        .empty_tag_union, .tag_union, .tuple, .nominal_type, .fn_pure, .fn_unbound, .fn_effectful => return .none,
                    }
                    return try self.dispatchEmbedRecordRowGrade(small.var_, big.var_);
                },
                .empty_tag_union, .tag_union => {
                    switch (big_flat) {
                        .empty_tag_union, .tag_union => {},
                        .empty_record, .record, .record_unbound, .tuple, .nominal_type, .fn_pure, .fn_unbound, .fn_effectful => return .none,
                    }
                    return try self.dispatchEmbedTagRowGrade(small.var_, big.var_);
                },
            }
        },
    }
}

const DispatchFieldKind = union(enum) {
    required,
    optional,
    defaulted: types_mod.DefaultId,
    variable: Var,
    poisoned,
};

fn dispatchFieldKind(self: *Self, presence: types_mod.RecordField.Presence) DispatchFieldKind {
    return switch (presence.decode()) {
        .required => .required,
        .unknown => |unknown| blk: {
            const resolved = self.types.resolveVar(unknown.presence);
            break :blk switch (resolved.desc.content) {
                .field_presence => |kind| switch (kind) {
                    .required => .required,
                    .optional => .optional,
                    .defaulted => |id| .{ .defaulted = id },
                },
                .flex, .rigid => .{ .variable = resolved.var_ },
                .err => .poisoned,
                .alias, .structure => unreachable,
            };
        },
    };
}

fn dispatchFieldPresenceGrade(
    self: *Self,
    small: types_mod.RecordField.Presence,
    big: types_mod.RecordField.Presence,
) Allocator.Error!DispatchEmbedGrade {
    var strict = false;
    switch (try self.dispatchReceiverEmbedGrade(small.typeVar(), big.typeVar())) {
        .none => return .none,
        .strict => strict = true,
        .equal => {},
    }

    const kind_grade: DispatchEmbedGrade = switch (self.dispatchFieldKind(small)) {
        .required => switch (self.dispatchFieldKind(big)) {
            .required => .equal,
            .optional, .defaulted, .variable, .poisoned => .none,
        },
        .optional => switch (self.dispatchFieldKind(big)) {
            .optional => .equal,
            .required, .defaulted, .variable, .poisoned => .none,
        },
        .defaulted => |small_id| switch (self.dispatchFieldKind(big)) {
            .defaulted => |big_id| if (std.meta.eql(small_id, big_id)) .equal else .none,
            .required, .optional, .variable, .poisoned => .none,
        },
        .variable => |small_var| switch (self.dispatchFieldKind(big)) {
            .variable => |big_var| try self.dispatchReceiverEmbedGrade(small_var, big_var),
            .required, .optional, .defaulted, .poisoned => .none,
        },
        .poisoned => .none,
    };
    return switch (kind_grade) {
        .none => .none,
        .strict => .strict,
        .equal => if (strict) .strict else .equal,
    };
}

fn dispatchEmbedPairwiseGrade(
    self: *Self,
    small_vars: []const Var,
    big_vars: []const Var,
) Allocator.Error!DispatchEmbedGrade {
    std.debug.assert(small_vars.len == big_vars.len);
    var strict = false;
    for (small_vars, big_vars) |small_var, big_var| {
        switch (try self.dispatchReceiverEmbedGrade(small_var, big_var)) {
            .none => return .none,
            .strict => strict = true,
            .equal => {},
        }
    }
    return if (strict) .strict else .equal;
}

fn dispatchEmbedRecordRowGrade(self: *Self, small_var: Var, big_var: Var) Allocator.Error!DispatchEmbedGrade {
    var small_fields: std.ArrayListUnmanaged(DispatchRecordField) = .empty;
    defer small_fields.deinit(self.gpa);
    var big_fields: std.ArrayListUnmanaged(DispatchRecordField) = .empty;
    defer big_fields.deinit(self.gpa);
    const small_tail = try self.dispatchCollectRecordRow(small_var, &small_fields);
    const big_tail = try self.dispatchCollectRecordRow(big_var, &big_fields);
    if (small_tail.kind != big_tail.kind) return .none;
    if (small_fields.items.len != big_fields.items.len) return .none;

    const idents = self.cir.getIdentStoreConst();
    var strict = false;
    for (small_fields.items) |small_field| {
        const big_field_presence = blk: {
            for (big_fields.items) |big_field| {
                if (idents.idxTextEql(small_field.name, big_field.name)) break :blk big_field.presence;
            }
            return .none;
        };
        switch (try self.dispatchFieldPresenceGrade(small_field.presence, big_field_presence)) {
            .none => return .none,
            .strict => strict = true,
            .equal => {},
        }
    }
    if (small_tail.kind == .open) {
        switch (try self.dispatchReceiverEmbedGrade(small_tail.var_, big_tail.var_)) {
            .none => return .none,
            .strict => strict = true,
            .equal => {},
        }
    }
    return if (strict) .strict else .equal;
}

fn dispatchEmbedTagRowGrade(self: *Self, small_var: Var, big_var: Var) Allocator.Error!DispatchEmbedGrade {
    var small_tags: std.ArrayListUnmanaged(DispatchUnionTag) = .empty;
    defer small_tags.deinit(self.gpa);
    var big_tags: std.ArrayListUnmanaged(DispatchUnionTag) = .empty;
    defer big_tags.deinit(self.gpa);
    const small_tail = try self.dispatchCollectTagRow(small_var, &small_tags);
    const big_tail = try self.dispatchCollectTagRow(big_var, &big_tags);
    if (small_tail.kind != big_tail.kind) return .none;
    if (small_tags.items.len != big_tags.items.len) return .none;

    const idents = self.cir.getIdentStoreConst();
    var strict = false;
    for (small_tags.items) |small_tag| {
        const big_tag_args = blk: {
            for (big_tags.items) |big_tag| {
                if (idents.idxTextEql(small_tag.name, big_tag.name)) break :blk big_tag.args;
            }
            return .none;
        };
        const small_args = self.types.sliceVars(small_tag.args);
        const big_args = self.types.sliceVars(big_tag_args);
        if (small_args.len != big_args.len) return .none;
        switch (try self.dispatchEmbedPairwiseGrade(small_args, big_args)) {
            .none => return .none,
            .strict => strict = true,
            .equal => {},
        }
    }
    if (small_tail.kind == .open) {
        switch (try self.dispatchReceiverEmbedGrade(small_tail.var_, big_tail.var_)) {
            .none => return .none,
            .strict => strict = true,
            .equal => {},
        }
    }
    return if (strict) .strict else .equal;
}

/// Whether `small_var` embeds into any child of the resolved big-side node.
/// The child set is exactly the structure the size walk counts, so a strict
/// embedding always implies a strictly smaller size.
fn dispatchEmbedDivesIntoChild(
    self: *Self,
    small_var: Var,
    big: types_mod.ResolvedVarDesc,
) Allocator.Error!bool {
    switch (big.desc.content) {
        .flex, .rigid, .field_presence, .err => return false,
        .alias => |alias| {
            if (try self.dispatchEmbedsInto(small_var, self.types.getAliasBackingVar(alias))) return true;
            for (self.types.sliceAliasArgs(alias)) |arg| {
                if (try self.dispatchEmbedsInto(small_var, arg)) return true;
            }
            return false;
        },
        .structure => |flat| switch (flat) {
            .empty_record, .empty_tag_union => return false,
            .tuple => |tuple| {
                for (self.types.sliceVars(tuple.elems)) |elem| {
                    if (try self.dispatchEmbedsInto(small_var, elem)) return true;
                }
                return false;
            },
            .nominal_type => |nominal| {
                for (self.types.sliceNominalArgs(nominal)) |arg| {
                    if (try self.dispatchEmbedsInto(small_var, arg)) return true;
                }
                return false;
            },
            .fn_pure, .fn_unbound, .fn_effectful => |func| {
                for (self.types.sliceVars(func.args)) |arg| {
                    if (try self.dispatchEmbedsInto(small_var, arg)) return true;
                }
                return try self.dispatchEmbedsInto(small_var, func.ret);
            },
            .record, .record_unbound => {
                var fields: std.ArrayListUnmanaged(DispatchRecordField) = .empty;
                defer fields.deinit(self.gpa);
                const tail = try self.dispatchCollectRecordRow(big.var_, &fields);
                for (fields.items) |field| {
                    if (try self.dispatchEmbedsInto(small_var, field.presence.typeVar())) return true;
                    if (field.presence.presenceVar()) |presence_var| {
                        if (try self.dispatchEmbedsInto(small_var, presence_var)) return true;
                    }
                }
                if (tail.kind == .open) return try self.dispatchEmbedsInto(small_var, tail.var_);
                return false;
            },
            .tag_union => {
                var tags: std.ArrayListUnmanaged(DispatchUnionTag) = .empty;
                defer tags.deinit(self.gpa);
                const tail = try self.dispatchCollectTagRow(big.var_, &tags);
                for (tags.items) |tag| {
                    for (self.types.sliceVars(tag.args)) |arg| {
                        if (try self.dispatchEmbedsInto(small_var, arg)) return true;
                    }
                }
                if (tail.kind == .open) return try self.dispatchEmbedsInto(small_var, tail.var_);
                return false;
            },
        },
    }
}

fn dispatchEmbedsInto(self: *Self, small_var: Var, big_var: Var) Allocator.Error!bool {
    return (try self.dispatchReceiverEmbedGrade(small_var, big_var)) != .none;
}

/// Collect one record row's normalized layout: every field along the
/// extension chain plus the terminal tail. Mirrors the canonical key
/// builder's row normalization so two spellings of one row compare equal.
fn dispatchCollectRecordRow(
    self: *Self,
    row_var: Var,
    fields: *std.ArrayListUnmanaged(DispatchRecordField),
) Allocator.Error!DispatchRowTail {
    var seen: std.ArrayListUnmanaged(Var) = .empty;
    defer seen.deinit(self.gpa);
    var tail_var = row_var;
    while (true) {
        const resolved = self.types.resolveVar(tail_var);
        if (dispatchVarInList(seen.items, resolved.var_)) return .{ .kind = .open, .var_ = resolved.var_ };
        try seen.append(self.gpa, resolved.var_);
        switch (resolved.desc.content) {
            .structure => |flat| switch (flat) {
                .empty_record => return .{ .kind = .closed, .var_ = resolved.var_ },
                .record => |record| {
                    const slice = self.types.getRecordFieldsSlice(record.fields);
                    const names = slice.items(.name);
                    const presences = slice.items(.presence);
                    for (names, presences) |name, presence| {
                        try fields.append(self.gpa, .{ .name = name, .presence = presence });
                    }
                    tail_var = record.ext;
                },
                .record_unbound => |fields_range| {
                    const slice = self.types.getRecordFieldsSlice(fields_range);
                    const names = slice.items(.name);
                    const presences = slice.items(.presence);
                    for (names, presences) |name, presence| {
                        try fields.append(self.gpa, .{ .name = name, .presence = presence });
                    }
                    return .{ .kind = .unbound, .var_ = resolved.var_ };
                },
                .empty_tag_union, .tag_union, .tuple, .nominal_type, .fn_pure, .fn_unbound, .fn_effectful => {
                    return .{ .kind = .open, .var_ = resolved.var_ };
                },
            },
            .flex, .rigid, .alias, .field_presence, .err => return .{ .kind = .open, .var_ = resolved.var_ },
        }
    }
}

/// Collect one tag-union row's normalized layout: every tag along the
/// extension chain plus the terminal tail.
fn dispatchCollectTagRow(
    self: *Self,
    row_var: Var,
    tags: *std.ArrayListUnmanaged(DispatchUnionTag),
) Allocator.Error!DispatchRowTail {
    var seen: std.ArrayListUnmanaged(Var) = .empty;
    defer seen.deinit(self.gpa);
    var tail_var = row_var;
    while (true) {
        const resolved = self.types.resolveVar(tail_var);
        if (dispatchVarInList(seen.items, resolved.var_)) return .{ .kind = .open, .var_ = resolved.var_ };
        try seen.append(self.gpa, resolved.var_);
        switch (resolved.desc.content) {
            .structure => |flat| switch (flat) {
                .empty_tag_union => return .{ .kind = .closed, .var_ = resolved.var_ },
                .tag_union => |tag_union| {
                    const slice = self.types.getTagsSlice(tag_union.tags);
                    const names = slice.items(.name);
                    const args = slice.items(.args);
                    for (names, args) |name, arg_range| {
                        try tags.append(self.gpa, .{ .name = name, .args = arg_range });
                    }
                    tail_var = tag_union.ext;
                },
                .empty_record, .record, .record_unbound, .tuple, .nominal_type, .fn_pure, .fn_unbound, .fn_effectful => {
                    return .{ .kind = .open, .var_ = resolved.var_ };
                },
            },
            .flex, .rigid, .alias, .field_presence, .err => return .{ .kind = .open, .var_ = resolved.var_ },
        }
    }
}

/// Size of one receiver over exactly the structure the embedding walk can
/// couple or dive through: identity leaves count one apiece (their attached
/// callable relations are not receiver structure), aliases count their
/// backing and arguments, rows count their normalized chain. Any strictly
/// embedded receiver therefore has a strictly smaller size, which is what
/// lets the size comparison prune the pairwise walk. Crossing an in-progress
/// var means cyclic structure whose totals are path-dependent, so the result
/// is flagged inconclusive.
fn dispatchReceiverSize(self: *Self, var_: Var) Allocator.Error!DispatchSizeResult {
    var active: std.ArrayListUnmanaged(Var) = .empty;
    defer active.deinit(self.gpa);
    var result: DispatchSizeResult = .{ .count = 0, .saw_cycle = false };
    try self.dispatchReceiverSizeInner(&active, var_, &result);
    return result;
}

fn dispatchReceiverSizeInner(
    self: *Self,
    active: *std.ArrayListUnmanaged(Var),
    var_: Var,
    result: *DispatchSizeResult,
) Allocator.Error!void {
    const resolved = self.types.resolveVar(var_);
    result.count +|= 1;
    if (dispatchVarInList(active.items, resolved.var_)) {
        result.saw_cycle = true;
        return;
    }
    try active.append(self.gpa, resolved.var_);
    defer _ = active.pop();

    switch (resolved.desc.content) {
        .flex, .rigid, .field_presence, .err => {},
        .alias => |alias| {
            try self.dispatchReceiverSizeInner(active, self.types.getAliasBackingVar(alias), result);
            for (self.types.sliceAliasArgs(alias)) |arg| {
                try self.dispatchReceiverSizeInner(active, arg, result);
            }
        },
        .structure => |flat| switch (flat) {
            .empty_record, .empty_tag_union => {},
            .tuple => |tuple| {
                for (self.types.sliceVars(tuple.elems)) |elem| {
                    try self.dispatchReceiverSizeInner(active, elem, result);
                }
            },
            .nominal_type => |nominal| {
                for (self.types.sliceNominalArgs(nominal)) |arg| {
                    try self.dispatchReceiverSizeInner(active, arg, result);
                }
            },
            .fn_pure, .fn_unbound, .fn_effectful => |func| {
                for (self.types.sliceVars(func.args)) |arg| {
                    try self.dispatchReceiverSizeInner(active, arg, result);
                }
                try self.dispatchReceiverSizeInner(active, func.ret, result);
            },
            .record, .record_unbound => {
                var fields: std.ArrayListUnmanaged(DispatchRecordField) = .empty;
                defer fields.deinit(self.gpa);
                const tail = try self.dispatchCollectRecordRow(resolved.var_, &fields);
                for (fields.items) |field| {
                    try self.dispatchReceiverSizeInner(active, field.presence.typeVar(), result);
                    if (field.presence.presenceVar()) |presence_var| {
                        try self.dispatchReceiverSizeInner(active, presence_var, result);
                    }
                }
                if (tail.kind == .open) try self.dispatchReceiverSizeInner(active, tail.var_, result);
            },
            .tag_union => {
                var tags: std.ArrayListUnmanaged(DispatchUnionTag) = .empty;
                defer tags.deinit(self.gpa);
                const tail = try self.dispatchCollectTagRow(resolved.var_, &tags);
                for (tags.items) |tag| {
                    for (self.types.sliceVars(tag.args)) |arg| {
                        try self.dispatchReceiverSizeInner(active, arg, result);
                    }
                }
                if (tail.kind == .open) try self.dispatchReceiverSizeInner(active, tail.var_, result);
            },
        },
    }
}

/// Return an already-selected target for this raw dispatch edge. Parent
/// chains and state keys are frozen at record time, so a fixpoint revisit of
/// a cached edge can never newly repeat an ancestor; a revisit reuses the
/// stored target without rebuilding canonical receiver/callable keys.
fn cachedDispatchTargetInstantiationIndex(
    self: *const Self,
    constraint: StaticDispatchConstraint,
    method_lookup: StaticDispatchMethodBinding,
) ?u32 {
    const raw_index = self.dispatch_target_instantiation_by_fn_var.get(constraint.fn_var) orelse return null;
    const existing = self.dispatch_target_instantiations.items[raw_index];
    if (existing.target_env != method_lookup.env or
        !std.meta.eql(existing.target_binding, method_lookup.binding) or
        !existing.method_name.eql(constraint.fn_name))
    {
        std.debug.panic("one static-dispatch edge selected two different method bindings", .{});
    }
    return raw_index;
}

fn rejectRecursiveStaticDispatch(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
    env: *Env,
    failure_expr: ?CIR.Expr.Idx,
    grown_from_receiver: ?Var,
) Allocator.Error!void {
    const snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, dispatcher_var);
    const grown_from_snapshot = if (grown_from_receiver) |ancestor_receiver|
        try self.snapshots.snapshotVarForError(self.types, &self.type_writer, ancestor_receiver)
    else
        null;
    _ = try self.problems.appendProblem(self.cir.gpa, .{ .static_dispatch = .{
        .recursive_dispatch = .{
            .dispatcher_snapshot = snapshot,
            .fn_var = constraint.fn_var,
            .method_name = constraint.fn_name,
            .grown_from_snapshot = grown_from_snapshot,
        },
    } });
    try self.poisonConstraintFailure(dispatcher_var, constraint, env, failure_expr);
    try self.markStaticDispatchRejected(constraint);
    try self.markErroneous(dispatcher_var);
}

/// Copy the selected method target for a new raw dispatch edge and record its
/// nested evidence plus canonical state. The cache-aware resolver guarantees
/// this is called exactly once per edge.
fn instantiateDispatchTargetMethodVar(
    self: *Self,
    dispatcher_var: Var,
    parent_constraint_fn_var: ?Var,
    state_type_key: [32]u8,
    grew_from_ancestor: bool,
    constraint: StaticDispatchConstraint,
    method_lookup: StaticDispatchMethodBinding,
    cycle_method_expr_var: ?Var,
    predeclared_scheme_for_method: ?Var,
    env: *Env,
    region: Region,
) Allocator.Error!Var {
    std.debug.assert(self.dispatch_target_instantiation_by_fn_var.get(constraint.fn_var) == null);

    try self.dispatch_target_instantiations.ensureUnusedCapacity(self.gpa, 1);
    try self.dispatch_target_instantiation_by_fn_var.ensureUnusedCapacity(self.gpa, 1);

    const previous_evidence_target_site = self.evidence_target_site;
    self.evidence_target_site = .{
        .node_idx = if (constraintIntroExpr(constraint)) |expr| @intFromEnum(expr) else 0,
        .constraint_fn_var = constraint.fn_var,
    };
    defer self.evidence_target_site = previous_evidence_target_site;

    const method_type_var: Var = ModuleEnv.varFrom(method_lookup.binding.type_node_idx);
    const records_before = self.cir.scheme_uses.items.items.len;
    const method_var = if (cycle_method_expr_var) |expr_var_for_method| blk: {
        break :blk expr_var_for_method;
    } else if (method_lookup.is_this_module) blk: {
        const local_method_type_var = predeclared_scheme_for_method orelse method_type_var;
        break :blk try self.instantiateBindingVar(local_method_type_var, env, .use_last_var);
    } else blk: {
        const imported_scheme = try self.importedMethodScheme(method_lookup);
        break :blk try self.instantiateVar(imported_scheme, env, .{ .explicit = region });
    };

    // A target that reused an in-flight cycle var performed no instantiation,
    // but its checked scheme still owns the nested evidence contract. Publish
    // an explicit zero-pair edge so checked-artifact construction receives the
    // exact selected scheme root instead of attempting to infer it later.
    const record_scheme_root = cycle_method_expr_var orelse method_type_var;
    var target_requires_record = cycle_method_expr_var != null or self.localProcedureMethodBinding(method_lookup);
    if (!target_requires_record and method_lookup.is_this_module) {
        // Same-module targets can own body-introduced evidence params (for
        // example pathless literal conversions) that are not visible from the
        // surface method type alone.
        target_requires_record = true;
    }
    if (target_requires_record and
        self.cir.scheme_uses.items.items.len == records_before)
    {
        try self.cir.recordSchemeUse(
            self.evidence_target_site.?.node_idx,
            .dispatch_target,
            @intFromEnum(constraint.fn_var),
            record_scheme_root,
            &.{},
        );
    }

    const raw_index: u32 = @intCast(self.dispatch_target_instantiations.items.len);
    self.dispatch_target_instantiations.appendAssumeCapacity(.{
        .constraint_fn_var = constraint.fn_var,
        .is_literal_conversion = constraint.origin.literalKind() != null,
        .receiver_var = dispatcher_var,
        .parent_constraint_fn_var = parent_constraint_fn_var,
        .state_type_key = state_type_key,
        .grew_from_ancestor = grew_from_ancestor,
        .target_env = method_lookup.env,
        .target_binding = method_lookup.binding,
        .method_name = constraint.fn_name,
        .method_var = method_var,
    });
    self.dispatch_target_instantiation_by_fn_var.putAssumeCapacityNoClobber(constraint.fn_var, raw_index);
    return method_var;
}

/// Resolve one selected dispatch target. Revisiting an edge is the common
/// fixpoint case, so cache lookup comes first. Only a genuinely new edge pays
/// for canonical state construction and ancestor-cycle comparison.
fn resolveDispatchTargetMethodVar(
    self: *Self,
    dispatcher_var: Var,
    parent_constraint_fn_var: ?Var,
    constraint: StaticDispatchConstraint,
    method_lookup: StaticDispatchMethodBinding,
    cycle_method_expr_var: ?Var,
    predeclared_scheme_for_method: ?Var,
    env: *Env,
    region: Region,
    failure_expr: ?CIR.Expr.Idx,
) Allocator.Error!?Var {
    if (self.cachedDispatchTargetInstantiationIndex(constraint, method_lookup)) |raw_index| {
        const existing = self.dispatch_target_instantiations.items[raw_index];
        std.debug.assert(existing.parent_constraint_fn_var == parent_constraint_fn_var);
        return existing.method_var;
    }

    const state_type_key = try self.dispatchStateTypeKey(dispatcher_var, constraint.fn_var);
    if (self.dispatchStateKeyRepeatsAncestor(
        constraint,
        parent_constraint_fn_var,
        method_lookup,
        state_type_key,
    )) {
        try self.rejectRecursiveStaticDispatch(dispatcher_var, constraint, env, failure_expr, null);
        return null;
    }

    var grew_from_ancestor = false;
    if (try self.dispatchStateGrowsAlongLineage(
        dispatcher_var,
        parent_constraint_fn_var,
        constraint,
        method_lookup,
        &grew_from_ancestor,
    )) |ancestor_receiver| {
        try self.rejectRecursiveStaticDispatch(dispatcher_var, constraint, env, failure_expr, ancestor_receiver);
        return null;
    }

    return try self.instantiateDispatchTargetMethodVar(
        dispatcher_var,
        parent_constraint_fn_var,
        state_type_key,
        grew_from_ancestor,
        constraint,
        method_lookup,
        cycle_method_expr_var,
        predeclared_scheme_for_method,
        env,
        region,
    );
}

fn localProcedureMethodBinding(self: *const Self, method_lookup: StaticDispatchMethodBinding) bool {
    if (!method_lookup.is_this_module) return false;
    const raw_node = @intFromEnum(method_lookup.binding.type_node_idx);
    if (raw_node >= self.cir.store.nodes.len()) return false;
    if (self.cir.store.nodes.get(@enumFromInt(raw_node)).tag != .statement_decl) return false;
    const stmt = self.cir.store.getStatement(@enumFromInt(raw_node));
    if (stmt != .s_decl) return false;
    const expr = self.cir.store.getExpr(stmt.s_decl.expr);
    return expr == .e_lambda or expr == .e_closure;
}

fn sameDeferredDispatchRelation(a: DeferredConstraintCheck, b: DeferredConstraintCheck) bool {
    return a.var_ == b.var_ and
        a.constraints.start == b.constraints.start and
        a.constraints.len() == b.constraints.len();
}

fn deferredDispatchRelationWasRetained(
    self: *Self,
    deferred: DeferredConstraintCheck,
    scratch_top: u32,
) bool {
    for (self.scratch_deferred_static_dispatch_constraints.sliceFromStart(scratch_top)) |retained| {
        if (sameDeferredDispatchRelation(deferred, retained)) return true;
    }
    return false;
}

/// Record exact callable relations that this pass conclusively consumed. This
/// is checker lifecycle data, so speculative commit-probes never update it;
/// their committed constraints are revisited by the ordinary post-commit pass.
fn recordSettledDeferredDispatchRelation(
    self: *Self,
    deferred: DeferredConstraintCheck,
) Allocator.Error!void {
    if (self.commit_probe_active) return;
    for (self.types.sliceStaticDispatchConstraints(deferred.constraints)) |constraint| {
        try self.settled_static_dispatch_constraint_fns.put(self.gpa, constraint.fn_var, {});
    }
}

fn checkStaticDispatchConstraints(self: *Self, env: *Env, is_numeric_default_pass: bool) std.mem.Allocator.Error!void {
    const trace = tracy.trace(@src());
    defer trace.end();

    // During this pass, we want to hold onto any flex vars we encounter and
    // check them again later, when maybe they've been resolved
    const scratch_deferred_top = self.scratch_deferred_static_dispatch_constraints.top();
    defer self.scratch_deferred_static_dispatch_constraints.clearFrom(scratch_deferred_top);
    const settled_relations_before = self.settled_static_dispatch_constraint_fns.count();

    // The drain runs until the queue is exhausted. Termination is structural:
    // every re-deferred relation keeps a still-flex receiver whose eventual
    // grounding consumes it, and every fresh child edge passes the lineage
    // detectors, which reject an exact repeated state or a strictly grown
    // re-entry of the same binding before it can extend the queue further.
    var deferred_constraint_index: usize = 0;
    while (deferred_constraint_index < env.deferred_static_dispatch_constraints.items.items.len) : (deferred_constraint_index += 1) {
        const deferred_constraint = env.deferred_static_dispatch_constraints.items.items[deferred_constraint_index];
        const retained_top = self.scratch_deferred_static_dispatch_constraints.top();
        const failure_expr = deferredConstraintFailureExpr(deferred_constraint);
        const deferred_children_start = env.deferred_static_dispatch_constraints.items.items.len;
        defer inheritDeferredConstraintFailureExpr(env, deferred_children_start, deferred_constraint.failure_expr);

        const dispatcher_resolved = self.types.resolveVar(deferred_constraint.var_);
        const dispatcher_content = dispatcher_resolved.desc.content;
        dispatch_resolution: while (true) {
            if (dispatcher_content == .err) {
                // If the root type is an error, then skip constraint checking
                const constraints = self.types.sliceStaticDispatchConstraints(deferred_constraint.constraints);
                for (constraints) |constraint| {
                    try self.markStaticDispatchRejected(constraint);
                }
                try self.markErroneous(deferred_constraint.var_);
                break :dispatch_resolution;
            } else if (dispatcher_content == .rigid) {
                // Get the rigid variable and the constraints it has defined
                const rigid = dispatcher_content.rigid;
                const rigid_constraints = self.types.sliceStaticDispatchConstraints(rigid.constraints);

                // Build a map of constraints the rigid has
                self.ident_to_var_map.clearRetainingCapacity();
                try self.ident_to_var_map.ensureUnusedCapacity(@intCast(rigid_constraints.len));
                for (rigid_constraints) |rigid_constraint| {
                    self.ident_to_var_map.putAssumeCapacity(rigid_constraint.fn_name, rigid_constraint.fn_var);
                }

                // Iterate over the deferred constraints to validate against.
                // iterRange re-fetches each item through the SafeList, so it stays valid
                // even if the unify below appends and reallocates the backing array.
                var constraints_iter = self.types.static_dispatch_constraints.iterRange(deferred_constraint.constraints);
                while (constraints_iter.next()) |constraint| {
                    if (constraint.origin == .from_literal) {
                        if (self.builtinNumKindFromTypeName(rigid.name)) |num_kind| {
                            if (try self.reportInvalidBuiltinFromNumeralLiteral(
                                deferred_constraint.var_,
                                constraint,
                                num_kind,
                                env,
                            )) {
                                continue;
                            }
                        }
                    }
                    if (constraint.origin.literalKind() == .interpolation) {
                        try self.ensureCustomInterpolationPartsChecked(constraint, env);
                    }

                    // Then, lookup the inferred constraint in the actual list of rigid constraints
                    if (self.ident_to_var_map.get(constraint.fn_name)) |rigid_var| {
                        // Unify the actual function var against the inferred var
                        //
                        // TODO: For better error messages, we should check if these
                        // types are functions, unify each arg, etc. This should look
                        // similar to e_call
                        const result = try self.unify(rigid_var, constraint.fn_var, env);
                        if (result.isEstablished()) {
                            try self.recordSuccessfulStaticDispatch(constraint);

                            // The body provably forces this where-clause method: a
                            // body dispatch matched it and unified successfully. Mark
                            // the rigid scheme's matching where-clause `body_required`
                            // so a later unpinnable instantiation of this scheme is
                            // reported as ambiguous rather than silently lowering to an
                            // ownerless dispatch. Re-fetch the backing slice: the unify
                            // above may have appended to (and reallocated) the
                            // constraint store, but it only grows it, so the rigid
                            // range indices stay valid.
                            const rc_start: usize = @intFromEnum(rigid.constraints.start);
                            const rc_len: usize = rigid.constraints.len();
                            const backing = self.types.static_dispatch_constraints.items.items;
                            for (rc_start..rc_start + rc_len) |i| {
                                if (backing[i].origin == .where_clause and backing[i].fn_name.eql(constraint.fn_name)) {
                                    backing[i].origin.where_clause.body_required = true;
                                    // Stamp the where-clause constraint's provenance with the
                                    // body dispatch that forced it, so instantiated copies point
                                    // at a concrete dispatch use (what the old side table's
                                    // cross-unification linking supplied). Only adopt a real
                                    // introducing expression; never clobber an existing one.
                                    if (backing[i].provenance.intro_expr == .none) {
                                        backing[i].provenance.intro_expr = constraint.provenance.intro_expr;
                                    }
                                }
                            }
                        } else {
                            if (result.isProblem()) {
                                try self.poisonConstraintFailure(deferred_constraint.var_, constraint, env, failure_expr);
                            }
                            try self.markStaticDispatchRejected(constraint);
                        }
                    } else {
                        try self.reportConstraintError(
                            deferred_constraint.var_,
                            constraint,
                            .{ .missing_method = .nominal },
                            env,
                            is_numeric_default_pass,
                        );
                        continue;
                    }
                }
                break :dispatch_resolution;
            } else if (dispatcher_content == .structure and dispatcher_content.structure == .nominal_type) {
                // If the root type is a nominal type, then this is valid static dispatch
                const nominal_type = dispatcher_content.structure.nominal_type;

                // Get the module ident that this type was defined in
                const original_module_ident = nominal_type.origin_module;

                // Check if the nominal type in question is defined in this module
                const original_env, _ = self.ownerEnvForOriginModule(
                    original_module_ident,
                    nominal_type.sourceDeclOptional(),
                    nominal_type.originIsBuiltin(),
                    "static dispatch nominal",
                );

                // Get some data about the nominal type
                const region = self.getRegionAt(deferred_constraint.var_);

                // Iterate over the constraints
                const constraints_range = deferred_constraint.constraints;
                const constraints_len = constraints_range.len();
                const constraints_start: usize = @intFromEnum(constraints_range.start);
                var constraint_i: usize = 0;
                while (constraint_i < constraints_len) : (constraint_i += 1) {
                    // Re-fetch by index each iteration because nested unification can append
                    // constraints and reallocate the backing array.
                    const constraint = self.types.static_dispatch_constraints.items.items[constraints_start + constraint_i];
                    if (self.types.varStaticDispatchRejected(constraint.fn_var)) continue;
                    const constraint_fn_resolved = self.types.resolveVar(constraint.fn_var).desc.content;
                    if (constraint_fn_resolved == .err) {
                        // If this constraint is already an error, the skip this pass
                        continue;
                    }
                    // A literal resolves only against the type it was annotated with:
                    // either this nominal is a builtin (validated just below) or it
                    // declares its own `from_` (dispatched further down). We do NOT walk
                    // into the backing chain to manufacture an opt-in the nominal never
                    // declared—`from_` is the explicit, per-nominal opt-in. To put a
                    // literal into a transparent newtype that declares no `from_`, use
                    // explicit construction (`Nominal.(value)`).
                    if (!try self.validateFromNumeralLiteralForBuiltinNominal(
                        deferred_constraint.var_,
                        constraint,
                        nominal_type,
                        env,
                    )) {
                        continue;
                    }
                    // Builtin literals are a primitive checking rule: the
                    // parser-owned exact value was validated above, and
                    // Monotype materializes it directly. There is no callable
                    // to look up, copy, instantiate, or unify for this edge.
                    if (constraint.origin == .from_literal) {
                        if (constraint.fn_name.eql(self.cir.idents.from_numeral) and
                            self.nominalIsBuiltinNumberType(nominal_type))
                        {
                            continue;
                        }
                        if (constraint.fn_name.eql(self.cir.idents.from_quote) and
                            self.nominalIsBuiltinStrType(nominal_type))
                        {
                            continue;
                        }
                    }
                    if (constraint.origin.literalKind() == .interpolation) {
                        if (self.nominalIsBuiltinStrType(nominal_type)) {
                            if (try self.satisfyBuiltinStrInterpolation(deferred_constraint.var_, constraint, env)) {
                                continue;
                            }
                        } else {
                            try self.ensureCustomInterpolationPartsChecked(constraint, env);
                        }
                    }
                    const method_lookup = self.lookupStaticDispatchMethodBinding(
                        original_env,
                        nominal_type.sourceDeclOptional(),
                        self.cir,
                        constraint.fn_name,
                    ) orelse {
                        try self.reportConstraintError(
                            deferred_constraint.var_,
                            constraint,
                            .{ .missing_method = .nominal },
                            env,
                            is_numeric_default_pass,
                        );
                        continue;
                    };
                    if (staticDispatchBindingIsDerivedMarker(method_lookup)) {
                        if (constraint.fn_name.eql(self.cir.idents.is_eq)) {
                            if (!try self.nominalSupportsStructuralDerive(nominal_type, .equality)) {
                                try self.reportEqualityError(deferred_constraint.var_, constraint, env);
                                continue;
                            }
                            try self.satisfyDerivedIsEqConstraint(
                                deferred_constraint.var_,
                                constraint,
                                constraint.fn_var,
                                env,
                                region,
                            );
                            continue;
                        }
                        if (constraint.fn_name.eql(self.cir.idents.to_hash)) {
                            if (!try self.nominalSupportsStructuralDerive(nominal_type, .hash)) {
                                try self.reportConstraintError(
                                    deferred_constraint.var_,
                                    constraint,
                                    .{ .missing_method = .nominal },
                                    env,
                                    is_numeric_default_pass,
                                );
                                continue;
                            }
                            try self.satisfyDerivedToHashConstraint(
                                deferred_constraint.var_,
                                constraint,
                                constraint.fn_var,
                                env,
                                region,
                            );
                            continue;
                        }
                        if (constraint.fn_name.eql(self.cir.idents.parser_for)) {
                            switch (try self.nominalSupportsDerivedParseShape(nominal_type, env, region)) {
                                .supported => try self.satisfyImplicitParserConstraint(
                                    deferred_constraint.var_,
                                    constraint,
                                    constraint.fn_var,
                                    env,
                                    region,
                                    failure_expr,
                                ),
                                .unresolved => if (!is_numeric_default_pass or try self.deferredParseHasPendingOpenLiteral(deferred_constraint, env)) {
                                    try self.scratch_deferred_static_dispatch_constraints.append(deferred_constraint);
                                    break :dispatch_resolution;
                                },
                                .unsupported => try self.reportConstraintError(
                                    deferred_constraint.var_,
                                    constraint,
                                    .{ .missing_method = .nominal },
                                    env,
                                    is_numeric_default_pass,
                                ),
                            }
                            continue;
                        }
                        if (constraint.fn_name.eql(self.cir.idents.encoder_for)) {
                            const encoding_var = self.encoderForConstraintEncodingVar(constraint) orelse {
                                try self.reportConstraintError(
                                    deferred_constraint.var_,
                                    constraint,
                                    .not_nominal,
                                    env,
                                    is_numeric_default_pass,
                                );
                                continue;
                            };
                            switch (try self.nominalSupportsDerivedEncodeShape(nominal_type, encoding_var, env, region)) {
                                .supported => try self.satisfyImplicitEncoderForConstraint(
                                    deferred_constraint.var_,
                                    constraint,
                                    constraint.fn_var,
                                    env,
                                    region,
                                ),
                                .unresolved => if (!is_numeric_default_pass or try self.deferredEncodeHasPendingOpenLiteral(deferred_constraint, env)) {
                                    try self.scratch_deferred_static_dispatch_constraints.append(deferred_constraint);
                                    break :dispatch_resolution;
                                },
                                .unsupported => try self.reportConstraintError(
                                    deferred_constraint.var_,
                                    constraint,
                                    .{ .missing_method = .nominal },
                                    env,
                                    is_numeric_default_pass,
                                ),
                            }
                            continue;
                        }
                        if (constraint.fn_name.eql(self.cir.idents.map) or constraint.fn_name.eql(self.cir.idents.map_bang)) {
                            switch (try self.satisfyDerivedMapConstraint(
                                deferred_constraint.var_,
                                constraint,
                                env,
                                region,
                                constraint.fn_name.eql(self.cir.idents.map_bang),
                            )) {
                                .satisfied, .suppressed_by_error => {},
                                .unsupported => try self.reportDerivedMapError(
                                    deferred_constraint.var_,
                                    constraint,
                                    env,
                                ),
                            }
                            continue;
                        }
                        if (builtin.mode == .Debug) {
                            std.debug.panic("derived-method marker registered for unsupported method", .{});
                        }
                        unreachable;
                    }
                    if (try self.rejectValuelessMethodDispatch(
                        method_lookup,
                        deferred_constraint.var_,
                        constraint,
                        env,
                        failure_expr,
                    )) continue;
                    if (constraint.fn_name.eql(self.cir.idents.from_numeral) and
                        !self.nominalIsBuiltinNumberType(nominal_type))
                    {
                        if (try self.reportUnmaterializableNumeralLiteral(deferred_constraint.var_, constraint, env)) {
                            continue;
                        }
                    }
                    if (constraint.fn_name.eql(self.cir.idents.is_eq)) {
                        self.rewriteEqBinopAsMethodEq(constraint);
                    }

                    const method_env = method_lookup.env;
                    const method_is_this_module = method_lookup.is_this_module;
                    const method_binding = method_lookup.binding;
                    const def_idx = method_binding.def_idx;
                    const def = method_env.store.getDef(def_idx);
                    // Track whether we just processed or referenced a cycle participant.
                    var cycle_method_expr_var: ?Var = null;

                    var predeclared_scheme_for_method: ?Var = null;
                    if (method_is_this_module) {
                        // Check if we've processed this def already. An
                        // annotated def whose body is unchecked or in flight
                        // resolves through its pre-declared scheme instead.
                        const mb_processing_def = self.topLevelPattern(def.pattern);
                        if (mb_processing_def) |processing_def| {
                            std.debug.assert(processing_def.def_idx == def_idx);
                            const mb_predeclared_scheme = self.predeclaredSchemeVar(def_idx);
                            switch (processing_def.status) {
                                .not_processed => if (mb_predeclared_scheme) |scheme_var| {
                                    predeclared_scheme_for_method = scheme_var;
                                } else {
                                    // Unannotated, unchecked local target. A
                                    // dispatch edge cannot be in the name
                                    // graph, so this is discovered here—but
                                    // never checked here: the obligation's
                                    // owning group frame records the target
                                    // for its boundary, the relation is
                                    // pinned at that boundary's rank
                                    // (Invariant D), and the constraint stays
                                    // deferred. A relation owned by an
                                    // enclosing frame only waits here.
                                    try self.deferDispatchObligationForUncheckedTarget(
                                        deferred_constraint,
                                        constraint,
                                        def_idx,
                                        env,
                                    );
                                    continue;
                                },
                                .processing => if (mb_predeclared_scheme) |scheme_var| {
                                    predeclared_scheme_for_method = scheme_var;
                                } else {
                                    if (!isFunctionDef(&self.cir.store, self.cir.store.getExpr(def.expr))) {
                                        if (self.delayed_dependency_depth == 0) {
                                            try self.poisonRecursiveNonFunctionProcessingDef(processing_def, null, env);
                                            try self.poisonConstraintFailure(deferred_constraint.var_, constraint, env, failure_expr);
                                            try self.markStaticDispatchRejected(constraint);
                                            try self.markErroneous(deferred_constraint.var_);
                                            continue;
                                        } else {
                                            cycle_method_expr_var = ModuleEnv.varFrom(def.expr);
                                        }
                                    } else {
                                        // In-flight unannotated target (self-
                                        // dispatch, or an in-group member):
                                        // the binding-group recursion rule—
                                        // link monomorphically to the def's
                                        // in-flight RHS var, which lives in
                                        // the frame that generalizes it.
                                        cycle_method_expr_var = ModuleEnv.varFrom(def.expr);
                                    }
                                },
                                .processed => if (mb_predeclared_scheme) |scheme_var| {
                                    if (self.defInOnStackGroup(def_idx)) {
                                        // A previously checked member of this
                                        // still-open recursive group has not
                                        // reached the shared generalization
                                        // boundary, so its def var is not a
                                        // scheme yet. Dispatch instantiates
                                        // the predeclared scheme—the same
                                        // polymorphic-recursion rule a name
                                        // reference to such a member follows.
                                        predeclared_scheme_for_method = scheme_var;
                                    }
                                },
                            }
                        }
                    }

                    const method_var = (try self.resolveDispatchTargetMethodVar(
                        deferred_constraint.var_,
                        self.dispatch_derivation_by_child_fn_var.get(constraint.fn_var),
                        constraint,
                        method_lookup,
                        cycle_method_expr_var,
                        predeclared_scheme_for_method,
                        env,
                        region,
                        failure_expr,
                    )) orelse continue;

                    // Unwrap the constraint type
                    if (constraint_fn_resolved.unwrapFunc() == null) {
                        _ = try self.unifyInContext(method_var, constraint.fn_var, env, .{
                            .method_type = .{
                                .constraint_var = constraint.fn_var,
                                .dispatcher_name = nominal_type.ident.ident_idx,
                                .method_name = constraint.fn_name,
                            },
                        });
                        try self.poisonConstraintFailure(deferred_constraint.var_, constraint, env, failure_expr);
                        try self.markStaticDispatchRejected(constraint);
                        continue;
                    }

                    const fn_ctx: problem.Context = .{
                        .method_type = .{
                            .constraint_var = deferred_constraint.var_,
                            .dispatcher_name = nominal_type.ident.ident_idx,
                            .method_name = constraint.fn_name,
                        },
                    };
                    const fn_result = fn_result: {
                        if (self.probe_depth != 0) {
                            break :fn_result try self.runUnify(
                                method_var,
                                constraint.fn_var,
                                env,
                                unifyOptionsForContext(fn_ctx, .write_no_report),
                            );
                        }
                        if (!self.varIsConflictedDefaultLiteral(deferred_constraint.var_)) {
                            break :fn_result try self.unifyInContext(method_var, constraint.fn_var, env, fn_ctx);
                        }
                        // This receiver's type is the documented head default,
                        // committed while its method constraints were still
                        // unvalidated—a type the program never chose. The
                        // failed validation must not retype anything the
                        // relation's argument graph reaches: bracket the unify
                        // in a probe and rewind the store, the deferred queue,
                        // and the var-pool tails on mismatch. The caller owns
                        // the mismatch diagnostic (`unifyOwnedRelation`), per
                        // the store rule that occurrence-directed poisoning
                        // never runs under an active savepoint; the problem
                        // and snapshots it records live outside the type store
                        // and survive the rollback. Success commits—a default
                        // target that satisfies a constraint is real. An
                        // enclosing probe takes the explicit non-poisoning path
                        // above instead of nesting another savepoint.
                        self.probe_var_pool_lens.clearRetainingCapacity();
                        const rank_count = @intFromEnum(env.rank()) + 1;
                        try self.probe_var_pool_lens.ensureTotalCapacity(self.gpa, rank_count);
                        for (0..rank_count) |rank_idx| {
                            const rank: Rank = @enumFromInt(rank_idx);
                            self.probe_var_pool_lens.appendAssumeCapacity(env.var_pool.getVarsForRank(rank).len);
                        }
                        var probe = try self.beginProbe(env);
                        var committed = false;
                        defer if (!committed) {
                            probe.rollback();
                            for (self.probe_var_pool_lens.items, 0..) |pool_len, rank_idx| {
                                env.var_pool.shrinkRank(@enumFromInt(rank_idx), pool_len);
                            }
                        };
                        const probed_result = try self.unifyOwnedRelation(method_var, constraint.fn_var, env, fn_ctx, .exact);
                        if (probed_result.isEstablished()) {
                            committed = true;
                            probe.commit();
                        }
                        break :fn_result probed_result;
                    };
                    if (fn_result.isEstablished()) {
                        try self.recordSuccessfulStaticDispatch(constraint);
                    } else {
                        if (fn_result.isProblem()) {
                            try self.poisonConstraintFailure(deferred_constraint.var_, constraint, env, failure_expr);
                        }
                        try self.markStaticDispatchRejected(constraint);
                    }
                }
                break :dispatch_resolution;
            } else if (dispatcher_content == .alias) {
                const alias = dispatcher_content.alias;

                // Get the module ident that this alias type was defined in
                const original_module_ident = alias.origin_module;
                const original_env, _ = self.ownerEnvForOriginModule(
                    original_module_ident,
                    alias.source_decl.toOptional(),
                    alias.source_decl.originIsBuiltin(),
                    "static dispatch alias",
                );

                const region = self.getRegionAt(deferred_constraint.var_);
                const constraints_range = deferred_constraint.constraints;
                const constraints_len = constraints_range.len();
                const constraints_start: usize = @intFromEnum(constraints_range.start);
                var constraint_i: usize = 0;
                while (constraint_i < constraints_len) : (constraint_i += 1) {
                    const constraint = self.types.static_dispatch_constraints.items.items[constraints_start + constraint_i];
                    if (self.types.varStaticDispatchRejected(constraint.fn_var)) continue;
                    const constraint_fn_resolved = self.types.resolveVar(constraint.fn_var).desc.content;
                    if (constraint_fn_resolved == .err) continue;

                    if (!try self.validateFromNumeralLiteralForBuiltinAlias(
                        deferred_constraint.var_,
                        constraint,
                        alias,
                        env,
                        is_numeric_default_pass,
                    )) {
                        continue;
                    }
                    if (constraint.origin.literalKind() == .interpolation) {
                        try self.ensureCustomInterpolationPartsChecked(constraint, env);
                    }
                    if (constraint.fn_name.eql(self.cir.idents.is_eq)) {
                        const method_lookup = self.lookupStaticDispatchMethodBinding(
                            original_env,
                            alias.source_decl.toOptional(),
                            self.cir,
                            constraint.fn_name,
                        );
                        if (method_lookup == null or staticDispatchBindingIsDerivedMarker(method_lookup.?)) {
                            const backing_var = self.types.getAliasBackingVar(alias);
                            if (try self.varSupportsIsEq(backing_var)) {
                                try self.satisfyDerivedIsEqConstraint(
                                    deferred_constraint.var_,
                                    constraint,
                                    constraint.fn_var,
                                    env,
                                    region,
                                );
                            } else {
                                try self.reportEqualityError(
                                    deferred_constraint.var_,
                                    constraint,
                                    env,
                                );
                            }
                            continue;
                        }
                    }
                    if (constraint.fn_name.eql(self.cir.idents.to_hash)) {
                        const method_lookup = self.lookupStaticDispatchMethodBinding(
                            original_env,
                            alias.source_decl.toOptional(),
                            self.cir,
                            constraint.fn_name,
                        );
                        if (method_lookup == null or staticDispatchBindingIsDerivedMarker(method_lookup.?)) {
                            const backing_var = self.types.getAliasBackingVar(alias);
                            if (try self.varSupportsToHash(backing_var)) {
                                try self.satisfyDerivedToHashConstraint(
                                    deferred_constraint.var_,
                                    constraint,
                                    constraint.fn_var,
                                    env,
                                    region,
                                );
                            } else {
                                try self.reportConstraintError(
                                    deferred_constraint.var_,
                                    constraint,
                                    .{ .missing_method = .nominal },
                                    env,
                                    is_numeric_default_pass,
                                );
                            }
                            continue;
                        }
                    }
                    if (constraint.fn_name.eql(self.cir.idents.parser_for)) {
                        const method_lookup = self.lookupStaticDispatchMethodBinding(
                            original_env,
                            alias.source_decl.toOptional(),
                            self.cir,
                            constraint.fn_name,
                        );
                        if (method_lookup == null or staticDispatchBindingIsDerivedMarker(method_lookup.?)) {
                            const backing_var = self.types.getAliasBackingVar(alias);
                            switch (try self.varSupportsDerivedParseShape(backing_var, env, region)) {
                                .supported => {
                                    try self.satisfyImplicitParserConstraint(
                                        deferred_constraint.var_,
                                        constraint,
                                        constraint.fn_var,
                                        env,
                                        region,
                                        failure_expr,
                                    );
                                    continue;
                                },
                                .unresolved => if (!is_numeric_default_pass or try self.deferredParseHasPendingOpenLiteral(deferred_constraint, env)) {
                                    try self.scratch_deferred_static_dispatch_constraints.append(deferred_constraint);
                                    break :dispatch_resolution;
                                },
                                .unsupported => {},
                            }
                        }
                    }
                    if (constraint.fn_name.eql(self.cir.idents.encoder_for)) {
                        const method_lookup = self.lookupStaticDispatchMethodBinding(
                            original_env,
                            alias.source_decl.toOptional(),
                            self.cir,
                            constraint.fn_name,
                        );
                        if (method_lookup != null and !staticDispatchBindingIsDerivedMarker(method_lookup.?)) {
                            // Exact attached implementations win over derivation.
                        } else {
                            const backing_var = self.types.getAliasBackingVar(alias);
                            const encoding_var = self.encoderForConstraintEncodingVar(constraint) orelse {
                                try self.reportConstraintError(
                                    deferred_constraint.var_,
                                    constraint,
                                    .not_nominal,
                                    env,
                                    is_numeric_default_pass,
                                );
                                continue;
                            };
                            switch (try self.varSupportsDerivedEncodeShape(backing_var, encoding_var, env, region)) {
                                .supported => {
                                    try self.satisfyImplicitEncoderForConstraint(
                                        deferred_constraint.var_,
                                        constraint,
                                        constraint.fn_var,
                                        env,
                                        region,
                                    );
                                    continue;
                                },
                                .unresolved => if (!is_numeric_default_pass or try self.deferredEncodeHasPendingOpenLiteral(deferred_constraint, env)) {
                                    try self.scratch_deferred_static_dispatch_constraints.append(deferred_constraint);
                                    break :dispatch_resolution;
                                },
                                .unsupported => {},
                            }
                        }
                    }
                    if (constraint.fn_name.eql(self.cir.idents.map) or constraint.fn_name.eql(self.cir.idents.map_bang)) {
                        const method_lookup = self.lookupStaticDispatchMethodBinding(
                            original_env,
                            alias.source_decl.toOptional(),
                            self.cir,
                            constraint.fn_name,
                        );
                        if (method_lookup == null or staticDispatchBindingIsDerivedMarker(method_lookup.?)) {
                            switch (try self.satisfyDerivedMapConstraint(
                                deferred_constraint.var_,
                                constraint,
                                env,
                                region,
                                constraint.fn_name.eql(self.cir.idents.map_bang),
                            )) {
                                .satisfied, .suppressed_by_error => continue,
                                .unsupported => {},
                            }
                            try self.reportDerivedMapError(
                                deferred_constraint.var_,
                                constraint,
                                env,
                            );
                            continue;
                        }
                    }

                    const method_lookup = self.lookupStaticDispatchMethodBinding(
                        original_env,
                        alias.source_decl.toOptional(),
                        self.cir,
                        constraint.fn_name,
                    ) orelse {
                        try self.reportConstraintError(
                            deferred_constraint.var_,
                            constraint,
                            .{ .missing_method = .nominal },
                            env,
                            is_numeric_default_pass,
                        );
                        continue;
                    };
                    if (try self.rejectValuelessMethodDispatch(
                        method_lookup,
                        deferred_constraint.var_,
                        constraint,
                        env,
                        failure_expr,
                    )) continue;
                    const method_env = method_lookup.env;
                    const method_is_this_module = method_lookup.is_this_module;
                    const method_binding = method_lookup.binding;
                    const def_idx = method_binding.def_idx;
                    if (constraint.fn_name.eql(self.cir.idents.from_numeral)) {
                        if (try self.reportUnmaterializableNumeralLiteral(deferred_constraint.var_, constraint, env)) {
                            continue;
                        }
                    }
                    if (constraint.fn_name.eql(self.cir.idents.is_eq)) {
                        self.rewriteEqBinopAsMethodEq(constraint);
                    }

                    const def = method_env.store.getDef(def_idx);
                    var cycle_method_expr_var: ?Var = null;
                    var predeclared_scheme_for_method: ?Var = null;
                    if (method_is_this_module) {
                        // See the nominal branch above: annotated targets
                        // resolve through their pre-declared scheme;
                        // unannotated unchecked targets are recorded for the
                        // group boundary; in-flight unannotated targets link
                        // monomorphically (the binding-group recursion rule).
                        const mb_processing_def = self.topLevelPattern(def.pattern);
                        if (mb_processing_def) |processing_def| {
                            std.debug.assert(processing_def.def_idx == def_idx);
                            const mb_predeclared_scheme = self.predeclaredSchemeVar(def_idx);
                            switch (processing_def.status) {
                                .not_processed => if (mb_predeclared_scheme) |scheme_var| {
                                    predeclared_scheme_for_method = scheme_var;
                                } else {
                                    try self.deferDispatchObligationForUncheckedTarget(
                                        deferred_constraint,
                                        constraint,
                                        def_idx,
                                        env,
                                    );
                                    continue;
                                },
                                .processing => if (mb_predeclared_scheme) |scheme_var| {
                                    predeclared_scheme_for_method = scheme_var;
                                } else {
                                    if (!isFunctionDef(&self.cir.store, self.cir.store.getExpr(def.expr))) {
                                        if (self.delayed_dependency_depth == 0) {
                                            try self.poisonRecursiveNonFunctionProcessingDef(processing_def, null, env);
                                            try self.poisonConstraintFailure(deferred_constraint.var_, constraint, env, failure_expr);
                                            try self.markStaticDispatchRejected(constraint);
                                            try self.markErroneous(deferred_constraint.var_);
                                            continue;
                                        } else {
                                            cycle_method_expr_var = ModuleEnv.varFrom(def.expr);
                                        }
                                    } else {
                                        cycle_method_expr_var = ModuleEnv.varFrom(def.expr);
                                    }
                                },
                                .processed => if (mb_predeclared_scheme) |scheme_var| {
                                    if (self.defInOnStackGroup(def_idx)) {
                                        // See the nominal branch: a checked
                                        // member of a still-open group
                                        // dispatches through its predeclared
                                        // scheme until the shared boundary
                                        // publishes the body scheme.
                                        predeclared_scheme_for_method = scheme_var;
                                    }
                                },
                            }
                        }
                    }

                    const method_var = (try self.resolveDispatchTargetMethodVar(
                        deferred_constraint.var_,
                        self.dispatch_derivation_by_child_fn_var.get(constraint.fn_var),
                        constraint,
                        method_lookup,
                        cycle_method_expr_var,
                        predeclared_scheme_for_method,
                        env,
                        region,
                        failure_expr,
                    )) orelse continue;

                    if (constraint_fn_resolved.unwrapFunc() == null) {
                        _ = try self.unifyInContext(method_var, constraint.fn_var, env, .{
                            .method_type = .{
                                .constraint_var = constraint.fn_var,
                                .dispatcher_name = alias.ident.ident_idx,
                                .method_name = constraint.fn_name,
                            },
                        });
                        try self.poisonConstraintFailure(deferred_constraint.var_, constraint, env, failure_expr);
                        try self.markStaticDispatchRejected(constraint);
                        continue;
                    }

                    const fn_result = try self.unifyInContext(method_var, constraint.fn_var, env, .{
                        .method_type = .{
                            .constraint_var = deferred_constraint.var_,
                            .dispatcher_name = alias.ident.ident_idx,
                            .method_name = constraint.fn_name,
                        },
                    });
                    if (fn_result.isEstablished()) {
                        try self.recordSuccessfulStaticDispatch(constraint);
                    } else {
                        if (fn_result.isProblem()) {
                            try self.poisonConstraintFailure(deferred_constraint.var_, constraint, env, failure_expr);
                        }
                        try self.markStaticDispatchRejected(constraint);
                    }
                }
                break :dispatch_resolution;
            } else if (dispatcher_content == .structure and
                (dispatcher_content.structure == .record or
                    dispatcher_content.structure == .record_unbound or
                    dispatcher_content.structure == .tuple or
                    dispatcher_content.structure == .tag_union or
                    dispatcher_content.structure == .empty_record or
                    dispatcher_content.structure == .empty_tag_union))
            {
                // Anonymous structural types (records, tuples, tag unions) have derived is_eq
                // only if all their components also support is_eq
                // iterRange re-fetches each item through the SafeList, so it stays valid even if
                // satisfyDerivedIsEqConstraint appends and reallocates the backing array.
                var constraints_iter = self.types.static_dispatch_constraints.iterRange(deferred_constraint.constraints);
                while (constraints_iter.next()) |constraint| {
                    // Check if this is a call to is_eq (anonymous types have derived is_eq)
                    if (constraint.fn_name.eql(self.cir.idents.is_eq)) {
                        // Check if all components of this anonymous type support is_eq
                        if (try self.typeSupportsIsEq(dispatcher_content.structure)) {
                            try self.satisfyDerivedIsEqConstraint(
                                deferred_constraint.var_,
                                constraint,
                                constraint.fn_var,
                                env,
                                self.getRegionAt(deferred_constraint.var_),
                            );
                        } else {
                            // Some component doesn't support is_eq (e.g., contains a function)
                            try self.reportEqualityError(
                                deferred_constraint.var_,
                                constraint,
                                env,
                            );
                        }
                    } else if (constraint.fn_name.eql(self.cir.idents.to_hash)) {
                        // Anonymous structural types have derived to_hash if all their
                        // components also support to_hash.
                        if (try self.typeSupportsToHash(dispatcher_content.structure)) {
                            try self.satisfyDerivedToHashConstraint(
                                deferred_constraint.var_,
                                constraint,
                                constraint.fn_var,
                                env,
                                self.getRegionAt(deferred_constraint.var_),
                            );
                        } else {
                            // Some component doesn't support to_hash (e.g., contains a function)
                            try self.reportConstraintError(
                                deferred_constraint.var_,
                                constraint,
                                .{ .missing_method = .nominal },
                                env,
                                is_numeric_default_pass,
                            );
                        }
                    } else if (constraint.fn_name.eql(self.cir.idents.map) or constraint.fn_name.eql(self.cir.idents.map_bang)) {
                        const region = self.getRegionAt(deferred_constraint.var_);
                        switch (try self.satisfyDerivedMapConstraint(
                            deferred_constraint.var_,
                            constraint,
                            env,
                            region,
                            constraint.fn_name.eql(self.cir.idents.map_bang),
                        )) {
                            .satisfied, .suppressed_by_error => {},
                            .unsupported => try self.reportDerivedMapError(
                                deferred_constraint.var_,
                                constraint,
                                env,
                            ),
                        }
                    } else if (constraint.fn_name.eql(self.cir.idents.parser_for)) {
                        const region = self.getRegionAt(deferred_constraint.var_);
                        switch (try self.typeSupportsDerivedParse(dispatcher_content.structure, env, region)) {
                            .supported => {
                                try self.satisfyImplicitParserConstraint(
                                    deferred_constraint.var_,
                                    constraint,
                                    constraint.fn_var,
                                    env,
                                    region,
                                    failure_expr,
                                );
                            },
                            .unresolved => {
                                if (!is_numeric_default_pass or try self.deferredParseHasPendingOpenLiteral(deferred_constraint, env)) {
                                    try self.scratch_deferred_static_dispatch_constraints.append(deferred_constraint);
                                    break :dispatch_resolution;
                                }
                                // Nothing further will arrive to close the row,
                                // so the fields it has are the fields it gets.
                                if (try self.closeRecordRowForDerivedParse(deferred_constraint.var_, env, region)) {
                                    try self.satisfyImplicitParserConstraint(
                                        deferred_constraint.var_,
                                        constraint,
                                        constraint.fn_var,
                                        env,
                                        region,
                                        failure_expr,
                                    );
                                    continue;
                                }
                                try self.reportConstraintError(
                                    deferred_constraint.var_,
                                    constraint,
                                    .not_nominal,
                                    env,
                                    is_numeric_default_pass,
                                );
                            },
                            .unsupported => {
                                try self.reportConstraintError(
                                    deferred_constraint.var_,
                                    constraint,
                                    .not_nominal,
                                    env,
                                    is_numeric_default_pass,
                                );
                            },
                        }
                    } else if (constraint.fn_name.eql(self.cir.idents.encoder_for)) {
                        const region = self.getRegionAt(deferred_constraint.var_);
                        const encoding_var = self.encoderForConstraintEncodingVar(constraint) orelse {
                            try self.reportConstraintError(
                                deferred_constraint.var_,
                                constraint,
                                .not_nominal,
                                env,
                                is_numeric_default_pass,
                            );
                            continue;
                        };
                        switch (try self.typeSupportsDerivedEncode(dispatcher_content.structure, encoding_var, env, region)) {
                            .supported => {
                                try self.satisfyImplicitEncoderForConstraint(
                                    deferred_constraint.var_,
                                    constraint,
                                    constraint.fn_var,
                                    env,
                                    region,
                                );
                            },
                            .unresolved => {
                                if (!is_numeric_default_pass or try self.deferredEncodeHasPendingOpenLiteral(deferred_constraint, env)) {
                                    try self.scratch_deferred_static_dispatch_constraints.append(deferred_constraint);
                                    break :dispatch_resolution;
                                }
                                // Nothing further will arrive to close the row,
                                // so the fields it has are the fields it gets.
                                if (try self.closeRecordRowForDerivedEncode(deferred_constraint.var_, encoding_var, env, region)) {
                                    try self.satisfyImplicitEncoderForConstraint(
                                        deferred_constraint.var_,
                                        constraint,
                                        constraint.fn_var,
                                        env,
                                        region,
                                    );
                                    continue;
                                }
                                try self.reportConstraintError(
                                    deferred_constraint.var_,
                                    constraint,
                                    .not_nominal,
                                    env,
                                    is_numeric_default_pass,
                                );
                            },
                            .unsupported => {
                                try self.reportConstraintError(
                                    deferred_constraint.var_,
                                    constraint,
                                    .not_nominal,
                                    env,
                                    is_numeric_default_pass,
                                );
                            },
                        }
                    } else {
                        // Structural types (other than is_eq, to_hash, parser_for, and
                        // encoder_for) cannot have methods called on them. The user must
                        // explicitly wrap the value in a nominal type.
                        try self.reportConstraintError(
                            deferred_constraint.var_,
                            constraint,
                            .not_nominal,
                            env,
                            is_numeric_default_pass,
                        );
                    }
                }
                break :dispatch_resolution;
            } else if (dispatcher_content == .flex) {
                // If the dispatcher is a flex, hold onto the constraint to try again later.
                // Note: flex vars with from_numeral constraints are validated separately
                // in checkFlexVarConstraintCompatibility after type checking completes.
                try self.scratch_deferred_static_dispatch_constraints.append(deferred_constraint);
                break :dispatch_resolution;
            } else {
                // If the root type is anything but a nominal type or anonymous structural type, push an error
                // This handles function types, which do not support any methods

                const constraints = self.types.sliceStaticDispatchConstraints(deferred_constraint.constraints);
                if (constraints.len > 0) {
                    // Report errors for ALL failing constraints, not just the first one
                    for (constraints) |constraint| {
                        // For is_eq constraints, use the specific equality error message
                        // Use ident index comparison instead of string comparison
                        if (constraint.fn_name.eql(self.cir.idents.is_eq)) {
                            try self.reportEqualityError(
                                deferred_constraint.var_,
                                constraint,
                                env,
                            );
                        } else {
                            try self.reportConstraintError(
                                deferred_constraint.var_,
                                constraint,
                                .not_nominal,
                                env,
                                is_numeric_default_pass,
                            );
                        }
                    }
                } else {
                    // Deferred constraint checks should always have at least one constraint.
                    // If we hit this, there's a compiler bug in how constraints are tracked.
                    std.debug.assert(false);
                }
                break :dispatch_resolution;
            }
        }

        if (!self.deferredDispatchRelationWasRetained(deferred_constraint, retained_top)) {
            try self.recordSettledDeferredDispatchRelation(deferred_constraint);
        }
    }

    // Now that we've processed all constraints, reset the array
    env.deferred_static_dispatch_constraints.items.clearRetainingCapacity();

    // Copy any flex constraints to try again later
    try env.deferred_static_dispatch_constraints.items.appendSlice(
        self.gpa,
        self.scratch_deferred_static_dispatch_constraints.sliceFromStart(scratch_deferred_top),
    );

    // A failed commit-probe must leave checker side tables untouched along
    // with the solved graph. Normal solve passes can retire requirements whose
    // receivers this pass conclusively discharged.
    if (!self.commit_probe_active and
        self.settled_static_dispatch_constraint_fns.count() != settled_relations_before)
    {
        self.retireResolvedTypeSchemeRequirements();
    }
}

fn recordInterpolationPartTypeMismatch(self: *Self, expected_var: Var, actual_var: Var, region: Region) Allocator.Error!void {
    const expected_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, expected_var);
    const actual_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, actual_var);
    _ = try self.problems.appendProblem(self.gpa, .{ .type_mismatch = .{
        .types = .{
            .expected_var = expected_var,
            .expected_snapshot = expected_snapshot,
            .actual_var = actual_var,
            .actual_snapshot = actual_snapshot,
        },
        .context = .{ .interpolation_part = region },
    } });
}

/// Under an open commit-probe, validate the constraints already attached to an
/// interpolation part against builtin Str. Str discharges its primitive quote
/// and interpolation conversions directly; every other obligation must resolve
/// through the ordinary static-dispatch acceptance rule.
fn interpolationPartConstraintsAcceptBuiltinStr(
    self: *Self,
    probe: *CommitProbe,
    constraints_range: StaticDispatchConstraint.SafeList.Range,
    expected_str_var: Var,
    env: *Env,
) Allocator.Error!bool {
    var constraints = self.types.iterStaticDispatchConstraints(constraints_range);
    while (constraints.next()) |constraint| {
        switch (constraint.origin) {
            .from_literal => |literal| switch (literal) {
                .quote, .interpolation => continue,
                .numeral => return false,
            },
            .desugared_binop,
            .desugared_unaryop,
            .method_call,
            .where_clause,
            => {},
        }

        if (!try self.staticDispatchConstraintAcceptsCandidate(probe, constraint, expected_str_var, env)) {
            return false;
        }
    }
    return true;
}

fn constrainInterpolationPartToStr(self: *Self, part: InterpolationPartMetadata, expected_str_var: Var, env: *Env) Allocator.Error!bool {
    const resolved_expr = self.types.resolveVar(part.var_);
    if (resolved_expr.desc.content == .err) return false;

    const constraints_range = contentConstraintRange(resolved_expr.desc.content) orelse StaticDispatchConstraint.SafeList.Range.empty();

    const compatible = blk: {
        var probe = try self.beginCommitProbe(env);
        var committed = false;
        defer if (!committed) probe.rollback();

        // Keep successful writes for the commit path, but leave mismatch
        // reporting and recovery to this function after the probe rolls back.
        const result = try probe.unify(expected_str_var, part.var_);
        if (!result.isEstablished()) break :blk false;
        if (!try self.interpolationPartConstraintsAcceptBuiltinStr(&probe, constraints_range, expected_str_var, env)) {
            break :blk false;
        }

        committed = true;
        probe.commit();
        break :blk true;
    };

    if (!compatible) {
        try self.recordInterpolationPartTypeMismatch(expected_str_var, part.var_, part.region);
        for (self.types.sliceStaticDispatchConstraints(constraints_range)) |constraint| {
            try self.markStaticDispatchRejected(constraint);
        }
        return true;
    }

    return false;
}

fn satisfyBuiltinStrInterpolation(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
    env: *Env,
) Allocator.Error!bool {
    const metadata = constraint.interpolation;
    const expr_region = metadata.expr_region.get() orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic("type checker invariant violated: builtin Str interpolation constraint had no metadata", .{});
        }
        unreachable;
    };
    const expected_str_var = try self.freshStr(env, expr_region);

    var did_err = false;
    for (0..metadata.interpolated_parts.len()) |part_i| {
        const part = self.types.getInterpolationPartAt(metadata.interpolated_parts, @intCast(part_i));
        did_err = (try self.constrainInterpolationPartToStr(part, expected_str_var, env)) or did_err;
    }

    if (did_err) {
        try self.markErroneous(dispatcher_var);
        try self.markStaticDispatchRejected(constraint);
        try self.poisonConstraintSourceExpr(dispatcher_var, constraint);
    }
    return true;
}

fn ensureCustomInterpolationPartsChecked(
    self: *Self,
    constraint: StaticDispatchConstraint,
    env: *Env,
) Allocator.Error!void {
    const metadata = constraint.interpolation;
    if (!metadata.isPresent()) {
        if (builtin.mode == .Debug) {
            std.debug.panic("type checker invariant violated: checked interpolation constraint had no generated item type", .{});
        }
        unreachable;
    }

    const checked_key = self.types.resolveVar(constraint.fn_var).var_;
    if ((try self.checked_interpolation_part_constraints.getOrPut(checked_key)).found_existing) return;

    const item_var = metadata.item_var;
    // Use the captured part metadata, not the original CIR `parts`, so an instantiated call
    // site unifies the item type against its instantiated arguments and reports at the
    // interpolation use site.
    const interpolated_parts = metadata.interpolated_parts;

    var did_err = false;
    for (0..interpolated_parts.len()) |part_i| {
        const part = self.types.getInterpolationPartAt(interpolated_parts, @intCast(part_i));
        const result = try self.unifyInContext(item_var, part.var_, env, .{ .interpolation_part = part.region });
        did_err = did_err or result.isProblem() or self.types.resolveVar(part.var_).desc.content == .err;
    }

    if (did_err) {
        try self.markStaticDispatchRejected(constraint);
        // Interpolation constraints always retain their introducing expression
        // in provenance, so the function var is only a placeholder for the
        // dispatcher parameter that constraintSourceExpr does not consult.
        try self.poisonConstraintSourceExpr(constraint.fn_var, constraint);
    }
}

const EqHashDerivation = enum { equality, hash };

/// Whether a structural type supports `is_eq` or `to_hash`. Anonymous
/// structures recurse through their components, but a nominal component is a
/// method boundary: it must explicitly declare the active method. A derived
/// marker on that nominal is valid only when its backing shape also qualifies.
fn typeSupportsStructuralDeriveInternal(
    self: *Self,
    flat_type: types_mod.FlatType,
    derivation: EqHashDerivation,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    return switch (flat_type) {
        // Function types support neither is_eq nor to_hash.
        .fn_pure, .fn_effectful, .fn_unbound => false,

        // Empty types trivially qualify.
        .empty_record, .empty_tag_union => true,

        // Records qualify if all field types qualify.
        .record => |record| {
            const fields_slice = self.types.getRecordFieldsSlice(record.fields);
            for (fields_slice.items(.presence)) |presence| {
                {
                    const field_var = presence.typeVar();
                    if (!try self.varSupportsStructuralDeriveInternal(field_var, derivation, visited)) return false;
                }
            }
            return true;
        },

        // Tuples qualify if all element types qualify.
        .tuple => |tuple| {
            const elems = self.types.sliceVars(tuple.elems);
            for (elems) |elem_var| {
                if (!try self.varSupportsStructuralDeriveInternal(elem_var, derivation, visited)) return false;
            }
            return true;
        },

        // Tag unions qualify if all payload types qualify.
        .tag_union => |tag_union| {
            const tags_slice = self.types.getTagsSlice(tag_union.tags);
            for (tags_slice.items(.args)) |tag_args| {
                const args = self.types.sliceVars(tag_args);
                for (args) |arg_var| {
                    if (!try self.varSupportsStructuralDeriveInternal(arg_var, derivation, visited)) return false;
                }
            }
            return true;
        },

        // Nominal types qualify if their args and their declaration's backing
        // template qualify (builtin numbers/Str/Bool/List declare both
        // derivations; Box declares neither). Formals in the template are
        // optimistically admitted like any rigid; the args are checked
        // directly.
        .nominal_type => |nominal| {
            const method_lookup = self.nominalEqHashMethod(nominal, derivation) orelse return false;
            if (!staticDispatchBindingIsDerivedMarker(method_lookup)) return true;
            if (self.nominalIsBoxType(nominal)) return false;
            for (self.types.sliceNominalArgs(nominal)) |arg_var| {
                if (!try self.varSupportsStructuralDeriveInternal(arg_var, derivation, visited)) return false;
            }
            const template = self.nominalDeclBackingTemplate(nominal) orelse return true;
            return try self.varSupportsStructuralDeriveInternal(template, derivation, visited);
        },

        // Unbound records: check each field.
        .record_unbound => |fields| {
            const fields_slice = self.types.getRecordFieldsSlice(fields);
            for (fields_slice.items(.presence)) |presence| {
                {
                    const field_var = presence.typeVar();
                    if (!try self.varSupportsStructuralDeriveInternal(field_var, derivation, visited)) return false;
                }
            }
            return true;
        },
    };
}

/// Check if a structural type supports is_eq. See
/// `typeSupportsStructuralDeriveInternal`.
fn typeSupportsIsEq(self: *Self, flat_type: types_mod.FlatType) std.mem.Allocator.Error!bool {
    self.var_set.clearRetainingCapacity();
    return try self.typeSupportsStructuralDeriveInternal(flat_type, .equality, &self.var_set);
}

fn nominalIsBoxType(self: *Self, nominal_type: types_mod.NominalType) bool {
    if (!nominal_type.originIsBuiltin()) return false;
    return (self.builtinNominalDeclForBuiltinSourceDecl(nominal_type.sourceDeclOptional()) orelse return false) == .box;
}

fn nominalIsBuiltinListType(self: *Self, nominal_type: types_mod.NominalType) bool {
    if (!nominal_type.originIsBuiltin()) return false;
    return (self.builtinNominalDeclForBuiltinSourceDecl(nominal_type.sourceDeclOptional()) orelse return false) == .list;
}

fn nominalListPayloadVar(self: *Self, nominal_type: types_mod.NominalType) ?Var {
    if (!self.nominalIsBuiltinListType(nominal_type)) return null;
    const args = self.types.sliceNominalArgs(nominal_type);
    if (args.len != 1) return null;
    return args[0];
}

fn nominalIsBuiltinSetType(self: *Self, nominal_type: types_mod.NominalType) bool {
    if (!nominal_type.originIsBuiltin()) return false;
    return (self.builtinNominalDeclForBuiltinSourceDecl(nominal_type.sourceDeclOptional()) orelse return false) == .set;
}

fn nominalSetPayloadVar(self: *Self, nominal_type: types_mod.NominalType) ?Var {
    if (!self.nominalIsBuiltinSetType(nominal_type)) return null;
    const args = self.types.sliceNominalArgs(nominal_type);
    if (args.len != 1) return null;
    return args[0];
}

fn nominalIsBuiltinDictType(self: *Self, nominal_type: types_mod.NominalType) bool {
    if (!nominal_type.originIsBuiltin()) return false;
    return (self.builtinNominalDeclForBuiltinSourceDecl(nominal_type.sourceDeclOptional()) orelse return false) == .dict;
}

const DictKeyValueVars = struct {
    key: Var,
    value: Var,
};

fn nominalDictKeyValueVars(self: *Self, nominal_type: types_mod.NominalType) ?DictKeyValueVars {
    if (!self.nominalIsBuiltinDictType(nominal_type)) return null;
    const args = self.types.sliceNominalArgs(nominal_type);
    if (args.len != 2) return null;
    return .{ .key = args[0], .value = args[1] };
}

fn nominalBoxPayloadVar(self: *Self, nominal_type: types_mod.NominalType) ?Var {
    if (!self.nominalIsBoxType(nominal_type)) return null;
    const args = self.types.sliceNominalArgs(nominal_type);
    if (args.len != 1) return null;
    return args[0];
}

fn varContainsUnboxedFunctionInHostedSignature(self: *Self, var_: Var) std.mem.Allocator.Error!bool {
    self.var_set.clearRetainingCapacity();
    return try self.varContainsUnboxedFunctionInHostedSignatureInternal(var_, true, &self.var_set);
}

const HostBoundaryRule = enum {
    closed_rows,
    no_optional_fields,
};

fn varContainsOpenRowInHostBoundary(self: *Self, var_: Var) std.mem.Allocator.Error!bool {
    self.var_set.clearRetainingCapacity();
    return try self.varViolatesHostBoundaryRuleInternal(var_, &self.var_set, .closed_rows);
}

fn varContainsOptionalFieldInHostBoundary(self: *Self, var_: Var) std.mem.Allocator.Error!bool {
    self.var_set.clearRetainingCapacity();
    return try self.varViolatesHostBoundaryRuleInternal(var_, &self.var_set, .no_optional_fields);
}

fn varViolatesHostBoundaryRuleInternal(
    self: *Self,
    var_: Var,
    visited: *std.AutoHashMap(Var, void),
    comptime rule: HostBoundaryRule,
) std.mem.Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    switch (resolved.desc.content) {
        .flex, .rigid, .err => return false,
        .field_presence => |presence| return rule == .no_optional_fields and presence == .optional,
        .alias, .structure => {},
    }
    if (visited.contains(resolved.var_)) return false;
    try visited.put(resolved.var_, {});

    return switch (resolved.desc.content) {
        .structure => |flat_type| try self.flatTypeViolatesHostBoundaryRule(flat_type, visited, rule),
        .alias => |alias| blk: {
            if (try self.varsViolateHostBoundaryRule(self.types.sliceAliasArgs(alias), visited, rule)) break :blk true;
            break :blk try self.varViolatesHostBoundaryRuleInternal(self.types.getAliasBackingVar(alias), visited, rule);
        },
        .flex, .rigid, .err, .field_presence => unreachable,
    };
}

fn varsViolateHostBoundaryRule(
    self: *Self,
    vars: []const Var,
    visited: *std.AutoHashMap(Var, void),
    comptime rule: HostBoundaryRule,
) std.mem.Allocator.Error!bool {
    for (vars) |var_| {
        if (try self.varViolatesHostBoundaryRuleInternal(var_, visited, rule)) return true;
    }
    return false;
}

fn recordFieldsViolateHostBoundaryRule(
    self: *Self,
    fields: types_mod.RecordField.SafeMultiList.Range,
    visited: *std.AutoHashMap(Var, void),
    comptime rule: HostBoundaryRule,
) std.mem.Allocator.Error!bool {
    const fields_slice = self.types.getRecordFieldsSlice(fields);
    for (fields_slice.items(.presence)) |presence| {
        if (presence.presenceVar()) |presence_var| {
            if (try self.varViolatesHostBoundaryRuleInternal(presence_var, visited, rule)) return true;
        }
        if (try self.varViolatesHostBoundaryRuleInternal(presence.typeVar(), visited, rule)) return true;
    }
    return false;
}

fn tagsViolateHostBoundaryRule(
    self: *Self,
    tags: types_mod.Tag.SafeMultiList.Range,
    visited: *std.AutoHashMap(Var, void),
    comptime rule: HostBoundaryRule,
) std.mem.Allocator.Error!bool {
    const tags_slice = self.types.getTagsSlice(tags);
    for (tags_slice.items(.args)) |args| {
        if (try self.varsViolateHostBoundaryRule(self.types.sliceVars(args), visited, rule)) return true;
    }
    return false;
}

fn flatTypeViolatesHostBoundaryRule(
    self: *Self,
    flat_type: types_mod.FlatType,
    visited: *std.AutoHashMap(Var, void),
    comptime rule: HostBoundaryRule,
) std.mem.Allocator.Error!bool {
    return switch (flat_type) {
        .empty_record, .empty_tag_union => false,
        .record => |record| blk: {
            if (try self.recordFieldsViolateHostBoundaryRule(record.fields, visited, rule)) break :blk true;
            break :blk switch (rule) {
                .closed_rows => !try self.recordExtIsClosedForHostBoundary(record.ext, visited),
                .no_optional_fields => try self.varViolatesHostBoundaryRuleInternal(record.ext, visited, rule),
            };
        },
        .record_unbound => |fields| blk: {
            if (try self.recordFieldsViolateHostBoundaryRule(fields, visited, rule)) break :blk true;
            break :blk rule == .closed_rows;
        },
        .tuple => |tuple| try self.varsViolateHostBoundaryRule(self.types.sliceVars(tuple.elems), visited, rule),
        .tag_union => |tag_union| blk: {
            if (try self.tagsViolateHostBoundaryRule(tag_union.tags, visited, rule)) break :blk true;
            break :blk switch (rule) {
                .closed_rows => !try self.tagUnionExtIsClosedForHostBoundary(tag_union.ext, visited),
                .no_optional_fields => try self.varViolatesHostBoundaryRuleInternal(tag_union.ext, visited, rule),
            };
        },
        .fn_pure, .fn_effectful, .fn_unbound => |func| blk: {
            if (try self.varsViolateHostBoundaryRule(self.types.sliceVars(func.args), visited, rule)) break :blk true;
            break :blk try self.varViolatesHostBoundaryRuleInternal(func.ret, visited, rule);
        },
        .nominal_type => |nominal| blk: {
            if (try self.varsViolateHostBoundaryRule(self.types.sliceNominalArgs(nominal), visited, rule)) break :blk true;
            // The declaration's backing template covers the structural rows;
            // its formals are rigid leaves (never open rows) standing for the
            // args checked above.
            const template = self.nominalDeclBackingTemplate(nominal) orelse break :blk false;
            break :blk try self.varViolatesHostBoundaryRuleInternal(template, visited, rule);
        },
    };
}

fn recordExtIsClosedForHostBoundary(
    self: *Self,
    ext_var: Var,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    var current = ext_var;
    var guard = types_mod.debug.IterationGuard.init("recordExtIsClosedForHostBoundary");
    while (true) {
        guard.tick();
        const resolved = self.types.resolveVar(current);
        if (visited.contains(resolved.var_)) return true;
        try visited.put(resolved.var_, {});

        switch (resolved.desc.content) {
            .alias => |alias| {
                if (try self.varsViolateHostBoundaryRule(self.types.sliceAliasArgs(alias), visited, .closed_rows)) return false;
                current = self.types.getAliasBackingVar(alias);
            },
            .structure => |flat_type| switch (flat_type) {
                .record => |record| {
                    if (try self.recordFieldsViolateHostBoundaryRule(record.fields, visited, .closed_rows)) return false;
                    current = record.ext;
                },
                .record_unbound => |fields| {
                    _ = try self.recordFieldsViolateHostBoundaryRule(fields, visited, .closed_rows);
                    return false;
                },
                .empty_record => return true,
                .tuple,
                .nominal_type,
                .fn_pure,
                .fn_effectful,
                .fn_unbound,
                .tag_union,
                .empty_tag_union,
                => return false,
            },
            .flex, .rigid, .field_presence => return false,
            .err => return true,
        }
    }
}

fn tagUnionExtIsClosedForHostBoundary(
    self: *Self,
    ext_var: Var,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    var current = ext_var;
    var guard = types_mod.debug.IterationGuard.init("tagUnionExtIsClosedForHostBoundary");
    while (true) {
        guard.tick();
        const resolved = self.types.resolveVar(current);
        if (visited.contains(resolved.var_)) return true;
        try visited.put(resolved.var_, {});

        switch (resolved.desc.content) {
            .alias => |alias| {
                if (try self.varsViolateHostBoundaryRule(self.types.sliceAliasArgs(alias), visited, .closed_rows)) return false;
                current = self.types.getAliasBackingVar(alias);
            },
            .structure => |flat_type| switch (flat_type) {
                .tag_union => |tag_union| {
                    if (try self.tagsViolateHostBoundaryRule(tag_union.tags, visited, .closed_rows)) return false;
                    current = tag_union.ext;
                },
                .empty_tag_union => return true,
                .record,
                .record_unbound,
                .tuple,
                .nominal_type,
                .fn_pure,
                .fn_effectful,
                .fn_unbound,
                .empty_record,
                => return false,
            },
            .flex, .rigid, .field_presence => return false,
            .err => return true,
        }
    }
}

fn varContainsUnboxedFunctionInHostedSignatureInternal(
    self: *Self,
    var_: Var,
    allow_top_fn: bool,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    // Cycle guard: recursive nominal/structural types would otherwise recurse
    // forever through their backing vars. A var already on the stack
    // contributes no new unboxed function we haven't already considered.
    if (visited.contains(resolved.var_)) return false;
    try visited.put(resolved.var_, {});
    return switch (resolved.desc.content) {
        .structure => |s| switch (s) {
            .fn_pure, .fn_effectful, .fn_unbound => |func| blk: {
                if (!allow_top_fn) break :blk true;
                const args = self.types.sliceVars(func.args);
                for (args) |arg_var| {
                    if (try self.varContainsUnboxedFunctionInternal(arg_var, false, visited)) break :blk true;
                }
                if (try self.varContainsUnboxedFunctionInternal(func.ret, false, visited)) break :blk true;
                break :blk false;
            },
            .record,
            .record_unbound,
            .tuple,
            .nominal_type,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => try self.flatTypeContainsUnboxedFunction(s, false, visited),
        },
        .alias => |alias| try self.varContainsUnboxedFunctionInHostedSignatureInternal(self.types.getAliasBackingVar(alias), allow_top_fn, visited),
        .flex, .rigid, .err, .field_presence => false,
    };
}

fn varContainsUnboxedFunctionInternal(
    self: *Self,
    var_: Var,
    boxed_allowed: bool,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    if (visited.contains(resolved.var_)) return false;
    try visited.put(resolved.var_, {});
    return switch (resolved.desc.content) {
        .structure => |s| try self.flatTypeContainsUnboxedFunction(s, boxed_allowed, visited),
        .alias => |alias| try self.varContainsUnboxedFunctionInternal(self.types.getAliasBackingVar(alias), boxed_allowed, visited),
        .flex, .rigid, .err, .field_presence => false,
    };
}

fn flatTypeContainsUnboxedFunction(
    self: *Self,
    flat_type: types_mod.FlatType,
    boxed_allowed: bool,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    return switch (flat_type) {
        .fn_pure, .fn_effectful, .fn_unbound => !boxed_allowed,
        .empty_record, .empty_tag_union => false,
        .record => |record| blk: {
            const fields_slice = self.types.getRecordFieldsSlice(record.fields);
            for (fields_slice.items(.presence)) |presence| {
                {
                    const field_var = presence.typeVar();
                    if (try self.varContainsUnboxedFunctionInternal(field_var, boxed_allowed, visited)) break :blk true;
                }
            }
            break :blk false;
        },
        .record_unbound => |fields| blk: {
            const fields_slice = self.types.getRecordFieldsSlice(fields);
            for (fields_slice.items(.presence)) |presence| {
                {
                    const field_var = presence.typeVar();
                    if (try self.varContainsUnboxedFunctionInternal(field_var, boxed_allowed, visited)) break :blk true;
                }
            }
            break :blk false;
        },
        .tuple => |tuple| blk: {
            const elems = self.types.sliceVars(tuple.elems);
            for (elems) |elem_var| {
                if (try self.varContainsUnboxedFunctionInternal(elem_var, boxed_allowed, visited)) break :blk true;
            }
            break :blk false;
        },
        .tag_union => |tag_union| blk: {
            const tags_slice = self.types.getTagsSlice(tag_union.tags);
            for (tags_slice.items(.args)) |tag_args| {
                const args = self.types.sliceVars(tag_args);
                for (args) |arg_var| {
                    if (try self.varContainsUnboxedFunctionInternal(arg_var, boxed_allowed, visited)) break :blk true;
                }
            }
            break :blk false;
        },
        .nominal_type => |nominal| blk: {
            if (self.nominalIsBoxType(nominal)) break :blk false;
            for (self.types.sliceNominalArgs(nominal)) |arg_var| {
                if (try self.varContainsUnboxedFunctionInternal(arg_var, boxed_allowed, visited)) break :blk true;
            }
            // Formals in the template are rigid leaves (never functions)
            // standing for the args checked above.
            const template = self.nominalDeclBackingTemplate(nominal) orelse break :blk false;
            break :blk try self.varContainsUnboxedFunctionInternal(template, boxed_allowed, visited);
        },
    };
}

/// Check if a structural type supports to_hash. See
/// `typeSupportsStructuralDeriveInternal`.
fn typeSupportsToHash(self: *Self, flat_type: types_mod.FlatType) std.mem.Allocator.Error!bool {
    self.var_set.clearRetainingCapacity();
    return try self.typeSupportsStructuralDeriveInternal(flat_type, .hash, &self.var_set);
}

/// Resolve a type variable and report whether its content supports the
/// structural derivations is_eq and to_hash. Flex/rigid vars are optimistically
/// admitted: if later unified with a non-deriving type (a function),
/// unification fails. Already-visited vars (recursive types) return true.
fn varSupportsStructuralDeriveInternal(
    self: *Self,
    var_: Var,
    derivation: EqHashDerivation,
    visited: *std.AutoHashMap(Var, void),
) std.mem.Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    if (visited.contains(resolved.var_)) return true;
    try visited.put(resolved.var_, {});

    return switch (resolved.desc.content) {
        .structure => |s| try self.typeSupportsStructuralDeriveInternal(s, derivation, visited),
        .flex, .rigid => true,
        .alias => |alias| try self.varSupportsStructuralDeriveInternal(self.types.getAliasBackingVar(alias), derivation, visited),
        .err, .field_presence => true,
    };
}

fn nominalEqHashMethod(self: *Self, nominal_type: types_mod.NominalType, derivation: EqHashDerivation) ?StaticDispatchMethodBinding {
    const method_name = switch (derivation) {
        .equality => self.cir.idents.is_eq,
        .hash => self.cir.idents.to_hash,
    };
    const original_env = self.getNominalOriginEnv(nominal_type);
    return self.lookupStaticDispatchMethodBinding(
        original_env,
        nominal_type.sourceDeclOptional(),
        self.cir,
        method_name,
    );
}

/// Whether a nominal's explicit derived marker has a structurally admissible
/// backing. The caller has already established that the nominal declared the
/// marker; nested nominal components must independently opt in.
fn nominalSupportsStructuralDerive(self: *Self, nominal_type: types_mod.NominalType, derivation: EqHashDerivation) std.mem.Allocator.Error!bool {
    if (self.nominalIsBuiltinNumberType(nominal_type)) return true;
    if (self.nominalIsBoxType(nominal_type)) return false;
    self.var_set.clearRetainingCapacity();
    for (self.types.sliceNominalArgs(nominal_type)) |arg_var| {
        if (!try self.varSupportsStructuralDeriveInternal(arg_var, derivation, &self.var_set)) return false;
    }
    const template = self.nominalDeclBackingTemplate(nominal_type) orelse return true;
    return try self.varSupportsStructuralDeriveInternal(template, derivation, &self.var_set);
}

/// Check if a type variable supports is_eq. See
/// `varSupportsStructuralDeriveInternal`.
fn varSupportsIsEq(self: *Self, var_: Var) std.mem.Allocator.Error!bool {
    self.var_set.clearRetainingCapacity();
    return try self.varSupportsStructuralDeriveInternal(var_, .equality, &self.var_set);
}

/// Check if a type variable supports to_hash. See
/// `varSupportsStructuralDeriveInternal`.
fn varSupportsToHash(self: *Self, var_: Var) std.mem.Allocator.Error!bool {
    self.var_set.clearRetainingCapacity();
    return try self.varSupportsStructuralDeriveInternal(var_, .hash, &self.var_set);
}

fn varSupportsStringRenderedDictKey(self: *Self, var_: Var) std.mem.Allocator.Error!bool {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| try self.typeSupportsStringRenderedDictKey(structure),
        .alias => |alias| try self.varSupportsStringRenderedDictKey(self.types.getAliasBackingVar(alias)),
        .err => true,
        .flex, .rigid, .field_presence => false,
    };
}

/// A dict key is supported when the format can read it at a key position:
/// key-string keys through `parse_key_*`, anything else through the key's own
/// derived parser, which the `parse_key_start` gate admits.
fn varSupportsDerivedDictKeyParse(self: *Self, key_var: Var, env: *Env, region: Region) std.mem.Allocator.Error!DerivedSupport {
    if (try self.varSupportsStringRenderedDictKey(key_var)) return .supported;
    return try self.varSupportsDerivedParseShape(key_var, env, region);
}

fn varSupportsDerivedDictKeyEncode(self: *Self, key_var: Var, encoding_var: Var, env: *Env, region: Region) std.mem.Allocator.Error!DerivedSupport {
    const string_rendered = try self.varSupportsStringRenderedKeyForDerivedEncode(key_var);
    if (string_rendered == .supported) return .supported;
    return try self.varSupportsDerivedEncodeShape(key_var, encoding_var, env, region);
}

/// Whether a dict key type can be rendered as a key string, which is what the
/// `parse_key_*`/`encode_key_*` methods read and write. Composite keys are
/// excluded here, so derived codecs reject them for every format even though
/// `Dict` itself accepts any key that supports `is_eq` and `to_hash`.
fn typeSupportsStringRenderedDictKey(self: *Self, flat_type: types_mod.FlatType) std.mem.Allocator.Error!bool {
    return switch (flat_type) {
        .nominal_type => |nominal| self.nominalIsBuiltinBoolType(nominal) or
            self.nominalIsBuiltinStrType(nominal) or
            self.nominalIsBuiltinNumberType(nominal),
        .tag_union => |tag_union| try self.tagUnionIsClosedAndUnit(tag_union),
        .empty_tag_union => false,
        .record,
        .record_unbound,
        .tuple,
        .fn_pure,
        .fn_effectful,
        .fn_unbound,
        .empty_record,
        => false,
    };
}

fn varSupportsStringRenderedKeyForDerivedEncode(self: *Self, var_: Var) std.mem.Allocator.Error!DerivedSupport {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| derivedSupportFromBool(try self.typeSupportsStringRenderedDictKey(structure)),
        .alias => |alias| try self.varSupportsStringRenderedKeyForDerivedEncode(self.types.getAliasBackingVar(alias)),
        .err => .supported,
        .flex => .unresolved,
        .rigid, .field_presence => .unsupported,
    };
}

fn varIsClosedUnitTagUnion(self: *Self, var_: Var) std.mem.Allocator.Error!bool {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| switch (structure) {
            .tag_union => |tag_union| try self.tagUnionIsClosedAndUnit(tag_union),
            .record,
            .record_unbound,
            .tuple,
            .nominal_type,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            .empty_tag_union,
            => false,
        },
        .alias => |alias| try self.varIsClosedUnitTagUnion(self.types.getAliasBackingVar(alias)),
        .flex, .rigid, .field_presence, .err => false,
    };
}

fn tagUnionIsClosedAndUnit(self: *Self, tag_union: types_mod.TagUnion) std.mem.Allocator.Error!bool {
    const tags = self.types.getTagsSlice(tag_union.tags);
    if (tags.items(.name).len == 0) return false;
    for (tags.items(.args)) |tag_args_range| {
        if (tag_args_range.len() != 0) return false;
    }
    return try self.tagExtIsClosedAndUnit(tag_union.ext);
}

fn tagExtIsClosedAndUnit(self: *Self, ext_var: Var) std.mem.Allocator.Error!bool {
    return switch (self.types.resolveVar(ext_var).desc.content) {
        .structure => |structure| switch (structure) {
            .empty_tag_union => true,
            .tag_union => |tag_union| try self.tagUnionIsClosedAndUnit(tag_union),
            .record,
            .record_unbound,
            .tuple,
            .nominal_type,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            => false,
        },
        .alias => |alias| try self.tagExtIsClosedAndUnit(self.types.getAliasBackingVar(alias)),
        .err => true,
        .flex, .rigid, .field_presence => false,
    };
}

fn builtinNumKindFromNominalType(self: *const Self, nominal_type: types_mod.NominalType) ?CIR.NumKind {
    if (!nominal_type.originIsBuiltin()) return null;
    return self.builtinNumKindFromBuiltinSourceDecl(nominal_type.sourceDeclOptional());
}

fn varResolvesToBuiltinScalarNominal(self: *const Self, var_: Var) bool {
    const resolved = self.types.resolveVar(var_);
    return switch (resolved.desc.content) {
        .structure => |structure| switch (structure) {
            .nominal_type => |nominal| self.nominalIsBuiltinBoolType(nominal) or
                self.nominalIsBuiltinStrType(nominal) or
                (self.builtinNumKindFromNominalType(nominal) != null),
            .record,
            .record_unbound,
            .tuple,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => false,
        },
        .alias => |alias| self.varResolvesToBuiltinScalarNominal(self.types.getAliasBackingVar(alias)),
        .flex, .rigid, .field_presence, .err => false,
    };
}

fn nominalIsBuiltinStrType(self: *const Self, nominal_type: types_mod.NominalType) bool {
    if (!nominal_type.originIsBuiltin()) return false;
    if (nominal_type.sourceDeclOptional()) |source_decl| {
        if (self.builtin_ctx.builtin_indices) |indices| {
            if (source_decl == @intFromEnum(indices.str_type)) return true;
        }
    }
    const ident = nominal_type.ident.ident_idx;
    return ident.eql(self.cir.idents.str) or ident.eql(self.cir.idents.builtin_str);
}

fn nominalIsBuiltinBoolType(self: *const Self, nominal_type: types_mod.NominalType) bool {
    if (!nominal_type.originIsBuiltin()) return false;
    if (nominal_type.sourceDeclOptional()) |source_decl| {
        if (self.builtin_ctx.builtin_indices) |indices| {
            if (source_decl == @intFromEnum(indices.bool_type)) return true;
        }
    }
    const ident = nominal_type.ident.ident_idx;
    return ident.eql(self.cir.idents.bool) or ident.eql(self.cir.idents.bool_type);
}

fn typeSupportsDerivedParse(
    self: *Self,
    flat_type: types_mod.FlatType,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    return switch (flat_type) {
        .record => |record| blk: {
            const fields_slice = self.types.getRecordFieldsSlice(record.fields);
            var support: DerivedSupport = .supported;
            for (fields_slice.items(.presence)) |presence| {
                const field_var = presence.typeVar();
                support = combineDerivedSupport(support, try self.varSupportsDerivedParseField(field_var, env, region));
                if (support == .unsupported) break;
            }
            if (support == .unsupported) break :blk support;
            break :blk combineDerivedSupport(support, try self.varSupportsDerivedParseRecordExt(record.ext, env, region));
        },
        .record_unbound => |fields| blk: {
            const fields_slice = self.types.getRecordFieldsSlice(fields);
            var support: DerivedSupport = .supported;
            for (fields_slice.items(.presence)) |presence| {
                const field_var = presence.typeVar();
                support = combineDerivedSupport(support, try self.varSupportsDerivedParseField(field_var, env, region));
                if (support == .unsupported) break;
            }
            break :blk support;
        },
        .tag_union => |tag_union| blk: {
            switch (try self.derivedParseTagUnionHasAnyTag(tag_union)) {
                .supported => {},
                .unsupported, .unresolved => |support| break :blk support,
            }
            const tags_slice = self.types.getTagsSlice(tag_union.tags);
            var support: DerivedSupport = .supported;
            for (tags_slice.items(.args)) |tag_args_range| {
                const tag_args = self.types.sliceVars(tag_args_range);
                for (tag_args) |tag_arg| {
                    support = combineDerivedSupport(support, try self.varSupportsDerivedParseShape(tag_arg, env, region));
                    if (support == .unsupported) break :blk .unsupported;
                }
            }
            break :blk combineDerivedSupport(support, try self.varSupportsDerivedParseTagExt(tag_union.ext, env, region));
        },
        .tuple => |tuple| blk: {
            const elems = try self.gpa.dupe(Var, self.types.sliceVars(tuple.elems));
            defer self.gpa.free(elems);
            var support: DerivedSupport = .supported;
            for (elems) |elem_var| {
                support = combineDerivedSupport(support, try self.varSupportsDerivedParseShape(elem_var, env, region));
                if (support == .unsupported) break;
            }
            break :blk support;
        },
        .empty_record => .supported,
        .empty_tag_union => .unsupported,
        .nominal_type => |nominal| try self.nominalSupportsDerivedParseShape(nominal, env, region),
        .fn_pure, .fn_effectful, .fn_unbound => .unsupported,
    };
}

fn varSupportsDerivedParseShape(
    self: *Self,
    var_: Var,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| try self.typeSupportsDerivedParse(structure, env, region),
        .alias => |alias| try self.varSupportsDerivedParseShape(self.types.getAliasBackingVar(alias), env, region),
        .err => .supported,
        .flex => .unresolved,
        .rigid, .field_presence => .unsupported,
    };
}

fn derivedParseTagUnionHasAnyTag(self: *Self, tag_union: types_mod.TagUnion) Allocator.Error!DerivedSupport {
    if (self.types.getTagsSlice(tag_union.tags).items(.name).len > 0) return .supported;
    return try self.derivedParseExtHasAnyTag(tag_union.ext);
}

fn derivedParseExtHasAnyTag(self: *Self, ext_var: Var) Allocator.Error!DerivedSupport {
    return switch (self.types.resolveVar(ext_var).desc.content) {
        .structure => |structure| switch (structure) {
            .empty_tag_union => .unsupported,
            .tag_union => |tag_union| try self.derivedParseTagUnionHasAnyTag(tag_union),
            .record,
            .record_unbound,
            .tuple,
            .nominal_type,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            => .unsupported,
        },
        .alias => |alias| try self.derivedParseExtHasAnyTag(self.types.getAliasBackingVar(alias)),
        .err => .supported,
        .flex => .unresolved,
        .rigid, .field_presence => .unsupported,
    };
}

/// Whether a record row is settled enough to derive a parser for it. A row
/// still open on a flex var can gain fields, and the parser derivation needs
/// the exact field set, so report it unresolved and let the dispatch defer
/// until the row closes—or until `closeRecordRowForDerivedParse` closes it.
fn varSupportsDerivedParseRecordExt(
    self: *Self,
    var_: Var,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| switch (structure) {
            .empty_record => .supported,
            .record => |record| try self.typeSupportsDerivedParse(.{ .record = record }, env, region),
            .record_unbound => |fields| try self.typeSupportsDerivedParse(.{ .record_unbound = fields }, env, region),
            .tag_union,
            .empty_tag_union,
            .tuple,
            .nominal_type,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            => .unsupported,
        },
        .alias => |alias| try self.varSupportsDerivedParseRecordExt(self.types.getAliasBackingVar(alias), env, region),
        .flex => .unresolved,
        .err => .supported,
        .rigid, .field_presence => .unsupported,
    };
}

/// Close an inferred record row so a parser can be derived for it.
///
/// A record whose shape comes only from use sites keeps an open row: every
/// field access adds a field and leaves the rest of the row a flex var that
/// another access could still extend. Deriving a parser needs the exact field
/// set, so once the dispatch has been deferred as far as it can go and nothing
/// further is coming, take the fields the row has as the fields it gets and
/// close it. Reports whether the row closed and now supports derivation, which
/// it does not when a field's own type never resolved.
fn closeRecordRowForDerivedParse(
    self: *Self,
    var_: Var,
    env: *Env,
    region: Region,
) Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_).desc.content;
    if (resolved != .structure or resolved.structure != .record) return false;
    const record = resolved.structure.record;
    if (self.types.resolveVar(record.ext).desc.content != .flex) return false;

    try self.unifyWith(record.ext, .{ .structure = .empty_record }, env);
    return (try self.varSupportsDerivedParseShape(var_, env, region)) == .supported;
}

fn varSupportsDerivedParseTagExt(
    self: *Self,
    var_: Var,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| switch (structure) {
            .empty_tag_union => .supported,
            .tag_union => |tag_union| try self.typeSupportsDerivedParse(.{ .tag_union = tag_union }, env, region),
            .record,
            .record_unbound,
            .tuple,
            .nominal_type,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            => .unsupported,
        },
        .alias => |alias| try self.varSupportsDerivedParseTagExt(self.types.getAliasBackingVar(alias), env, region),
        .err, .flex => .supported,
        .rigid, .field_presence => .unsupported,
    };
}

fn varSupportsDerivedParseField(
    self: *Self,
    var_: Var,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| switch (structure) {
            .nominal_type => |nominal| try self.nominalSupportsDerivedParseField(nominal, env, region),
            .record => |record| try self.typeSupportsDerivedParse(.{ .record = record }, env, region),
            .record_unbound => |fields| try self.typeSupportsDerivedParse(.{ .record_unbound = fields }, env, region),
            .tag_union => |tag_union| try self.typeSupportsDerivedParse(.{ .tag_union = tag_union }, env, region),
            .tuple => |tuple| try self.typeSupportsDerivedParse(.{ .tuple = tuple }, env, region),
            .empty_record => .supported,
            .empty_tag_union => .unsupported,
            .fn_pure, .fn_effectful, .fn_unbound => .unsupported,
        },
        .alias => |alias| try self.varSupportsDerivedParseField(self.types.getAliasBackingVar(alias), env, region),
        .err => .supported,
        .flex => .unresolved,
        .rigid, .field_presence => .unsupported,
    };
}

fn nominalSupportsDerivedParseShape(
    self: *Self,
    nominal: types_mod.NominalType,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    if (self.nominalIsBuiltinBoolType(nominal)) return .supported;
    if (self.nominalIsBuiltinStrType(nominal)) return .supported;
    if (self.nominalIsBuiltinNumberType(nominal)) return .supported;
    if (self.nominalListPayloadVar(nominal)) |payload_var| {
        return try self.varSupportsDerivedParseShape(payload_var, env, region);
    }
    if (self.nominalBoxPayloadVar(nominal)) |payload_var| {
        return try self.varSupportsDerivedParseShape(payload_var, env, region);
    }
    if (self.nominalSetPayloadVar(nominal)) |payload_var| {
        if (!try self.varSupportsIsEq(payload_var)) return .unsupported;
        return try self.varSupportsDerivedParseShape(payload_var, env, region);
    }
    if (self.nominalDictKeyValueVars(nominal)) |args| {
        if (!try self.varSupportsIsEq(args.key)) return .unsupported;
        if (!try self.varSupportsToHash(args.key)) return .unsupported;
        return combineDerivedSupport(
            try self.varSupportsDerivedDictKeyParse(args.key, env, region),
            try self.varSupportsDerivedParseShape(args.value, env, region),
        );
    }
    if (self.nominalIsBuiltinTryType(nominal)) {
        if (try self.nullTryInfoFromNominal(nominal)) |info| {
            return try self.varSupportsDerivedParseShape(info.ok_var, env, region);
        }
        return .unsupported;
    }
    if (nominal.originIsBuiltin()) return .unsupported;
    return .supported;
}

fn nominalSupportsDerivedParseField(
    self: *Self,
    nominal: types_mod.NominalType,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    if (self.nominalIsBuiltinBoolType(nominal)) return .supported;
    if (self.nominalIsBuiltinStrType(nominal)) return .supported;
    if (self.nominalIsBuiltinNumberType(nominal)) return .supported;
    if (self.nominalListPayloadVar(nominal)) |payload_var| {
        return try self.varSupportsDerivedParseShape(payload_var, env, region);
    }
    if (self.nominalBoxPayloadVar(nominal)) |payload_var| {
        return try self.varSupportsDerivedParseShape(payload_var, env, region);
    }
    if (self.nominalSetPayloadVar(nominal)) |payload_var| {
        if (!try self.varSupportsIsEq(payload_var)) return .unsupported;
        return try self.varSupportsDerivedParseShape(payload_var, env, region);
    }
    if (self.nominalDictKeyValueVars(nominal)) |args| {
        if (!try self.varSupportsIsEq(args.key)) return .unsupported;
        if (!try self.varSupportsToHash(args.key)) return .unsupported;
        return combineDerivedSupport(
            try self.varSupportsDerivedDictKeyParse(args.key, env, region),
            try self.varSupportsDerivedParseShape(args.value, env, region),
        );
    }
    if (self.nominalIsBuiltinTryType(nominal)) {
        if (try self.missingTryInfoFromNominal(nominal)) |info| {
            return try self.varSupportsDerivedParseShape(info.ok_var, env, region);
        }
        if (try self.nullTryInfoFromNominal(nominal)) |info| {
            return try self.varSupportsDerivedParseShape(info.ok_var, env, region);
        }
        if (try self.unboundTryInfoFromNominal(nominal)) |info| {
            return try self.varSupportsDerivedParseShape(info.ok_var, env, region);
        }
        return .unsupported;
    }

    return if (nominal.originIsBuiltin()) .unsupported else .supported;
}

const DerivedSupport = enum {
    supported,
    unsupported,
    unresolved,
};

fn derivedSupportFromBool(value: bool) DerivedSupport {
    return if (value) .supported else .unsupported;
}

fn combineDerivedSupport(a: DerivedSupport, b: DerivedSupport) DerivedSupport {
    if (a == .unsupported or b == .unsupported) return .unsupported;
    if (a == .unresolved or b == .unresolved) return .unresolved;
    return .supported;
}

fn typeSupportsDerivedEncode(
    self: *Self,
    flat_type: types_mod.FlatType,
    encoding_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    return switch (flat_type) {
        .record => |record| blk: {
            const fields_slice = self.types.getRecordFieldsSlice(record.fields);
            var support: DerivedSupport = .supported;
            for (fields_slice.items(.presence)) |presence| {
                {
                    const field_var = presence.typeVar();
                    support = combineDerivedSupport(support, try self.varSupportsDerivedEncodeRecordField(field_var, encoding_var, env, region));
                    if (support == .unsupported) break;
                }
            }
            if (support == .unsupported) break :blk support;
            break :blk combineDerivedSupport(support, try self.varSupportsDerivedEncodeRecordExt(record.ext, encoding_var, env, region));
        },
        .record_unbound => |fields| blk: {
            const fields_slice = self.types.getRecordFieldsSlice(fields);
            var support: DerivedSupport = .supported;
            for (fields_slice.items(.presence)) |presence| {
                {
                    const field_var = presence.typeVar();
                    support = combineDerivedSupport(support, try self.varSupportsDerivedEncodeRecordField(field_var, encoding_var, env, region));
                    if (support == .unsupported) break;
                }
            }
            break :blk support;
        },
        .tag_union => |tag_union| blk: {
            switch (try self.derivedParseTagUnionHasAnyTag(tag_union)) {
                .supported => {},
                .unsupported, .unresolved => |support| break :blk support,
            }
            const tags_slice = self.types.getTagsSlice(tag_union.tags);
            var support: DerivedSupport = .supported;
            for (tags_slice.items(.args)) |tag_args_range| {
                const tag_args = self.types.sliceVars(tag_args_range);
                for (tag_args) |tag_arg| {
                    support = combineDerivedSupport(support, try self.varSupportsDerivedEncodeShape(tag_arg, encoding_var, env, region));
                    if (support == .unsupported) break :blk .unsupported;
                }
            }
            break :blk combineDerivedSupport(support, try self.varSupportsDerivedEncodeTagExt(tag_union.ext, encoding_var, env, region));
        },
        .tuple => |tuple| blk: {
            const elems = try self.gpa.dupe(Var, self.types.sliceVars(tuple.elems));
            defer self.gpa.free(elems);
            var support: DerivedSupport = .supported;
            for (elems) |elem_var| {
                support = combineDerivedSupport(support, try self.varSupportsDerivedEncodeShape(elem_var, encoding_var, env, region));
                if (support == .unsupported) break;
            }
            break :blk support;
        },
        .empty_record => .supported,
        .nominal_type,
        .fn_pure,
        .fn_effectful,
        .fn_unbound,
        .empty_tag_union,
        => .unsupported,
    };
}

fn varSupportsDerivedEncodeRecordField(
    self: *Self,
    var_: Var,
    encoding_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    if (try self.missingTryInfoForVar(var_)) |info| {
        return try self.varSupportsDerivedEncodeShape(info.ok_var, encoding_var, env, region);
    }
    return try self.varSupportsDerivedEncodeShape(var_, encoding_var, env, region);
}

fn varSupportsDerivedEncodeShape(
    self: *Self,
    var_: Var,
    encoding_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| switch (structure) {
            .nominal_type => |nominal| try self.nominalSupportsDerivedEncodeShape(nominal, encoding_var, env, region),
            .record => |record| try self.typeSupportsDerivedEncode(.{ .record = record }, encoding_var, env, region),
            .record_unbound => |fields| try self.typeSupportsDerivedEncode(.{ .record_unbound = fields }, encoding_var, env, region),
            .tag_union => |tag_union| try self.typeSupportsDerivedEncode(.{ .tag_union = tag_union }, encoding_var, env, region),
            .tuple => |tuple| try self.typeSupportsDerivedEncode(.{ .tuple = tuple }, encoding_var, env, region),
            .empty_record => .supported,
            .empty_tag_union => .unsupported,
            .fn_pure, .fn_effectful, .fn_unbound => .unsupported,
        },
        .alias => |alias| try self.varSupportsDerivedEncodeShape(self.types.getAliasBackingVar(alias), encoding_var, env, region),
        .err => .supported,
        .flex => .unresolved,
        .rigid, .field_presence => .unsupported,
    };
}

/// Whether a record row is settled enough to derive an encoder for it. A row
/// still open on a flex var can gain fields, and the encoder derivation needs
/// the exact field set, so report it unresolved and let the dispatch defer
/// until the row closes—or until `closeRecordRowForDerivedEncode` closes it.
fn varSupportsDerivedEncodeRecordExt(
    self: *Self,
    var_: Var,
    encoding_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| switch (structure) {
            .empty_record => .supported,
            .record => |record| try self.typeSupportsDerivedEncode(.{ .record = record }, encoding_var, env, region),
            .record_unbound => |fields| try self.typeSupportsDerivedEncode(.{ .record_unbound = fields }, encoding_var, env, region),
            .tag_union,
            .empty_tag_union,
            .tuple,
            .nominal_type,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            => .unsupported,
        },
        .alias => |alias| try self.varSupportsDerivedEncodeRecordExt(self.types.getAliasBackingVar(alias), encoding_var, env, region),
        .flex => .unresolved,
        .err => .supported,
        .rigid, .field_presence => .unsupported,
    };
}

/// Close an inferred record row so an encoder can be derived for it.
///
/// A record whose shape comes only from use sites keeps an open row: every
/// field access adds a field and leaves the rest of the row a flex var that
/// another access could still extend. Deriving an encoder needs the exact field
/// set, so once the dispatch has been deferred as far as it can go and nothing
/// further is coming, take the fields the row has as the fields it gets and
/// close it. Reports whether the row closed and now supports derivation, which
/// it does not when a field's own type never resolved.
fn closeRecordRowForDerivedEncode(
    self: *Self,
    var_: Var,
    encoding_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_).desc.content;
    if (resolved != .structure or resolved.structure != .record) return false;
    const record = resolved.structure.record;
    if (self.types.resolveVar(record.ext).desc.content != .flex) return false;

    try self.unifyWith(record.ext, .{ .structure = .empty_record }, env);
    return (try self.varSupportsDerivedEncodeShape(var_, encoding_var, env, region)) == .supported;
}

fn varSupportsDerivedEncodeTagExt(
    self: *Self,
    var_: Var,
    encoding_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| switch (structure) {
            .empty_tag_union => .supported,
            .tag_union => |tag_union| try self.typeSupportsDerivedEncode(.{ .tag_union = tag_union }, encoding_var, env, region),
            .record,
            .record_unbound,
            .tuple,
            .nominal_type,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            => .unsupported,
        },
        .alias => |alias| try self.varSupportsDerivedEncodeTagExt(self.types.getAliasBackingVar(alias), encoding_var, env, region),
        .err => .supported,
        .flex => .supported,
        .rigid, .field_presence => .unsupported,
    };
}

fn nominalSupportsDerivedEncodeShape(
    self: *Self,
    nominal: types_mod.NominalType,
    encoding_var: Var,
    env: *Env,
    region: Region,
) Allocator.Error!DerivedSupport {
    if (self.nominalIsBuiltinBoolType(nominal)) return .supported;
    if (self.nominalIsBuiltinStrType(nominal)) return .supported;
    if (self.nominalIsBuiltinNumberType(nominal)) return .supported;
    if (self.nominalListPayloadVar(nominal)) |payload_var| {
        return try self.varSupportsDerivedEncodeShape(payload_var, encoding_var, env, region);
    }
    if (self.nominalBoxPayloadVar(nominal)) |payload_var| {
        return try self.varSupportsDerivedEncodeShape(payload_var, encoding_var, env, region);
    }
    if (self.nominalSetPayloadVar(nominal)) |payload_var| {
        return try self.varSupportsDerivedEncodeShape(payload_var, encoding_var, env, region);
    }
    if (self.nominalDictKeyValueVars(nominal)) |args| {
        return combineDerivedSupport(
            try self.varSupportsDerivedDictKeyEncode(args.key, encoding_var, env, region),
            try self.varSupportsDerivedEncodeShape(args.value, encoding_var, env, region),
        );
    }
    if (self.nominalIsBuiltinTryType(nominal)) {
        return if ((try self.nullTryInfoFromNominal(nominal)) != null) .supported else .unsupported;
    }
    if (nominal.originIsBuiltin()) return .unsupported;
    return .supported;
}

fn missingTryInfoForVar(
    self: *Self,
    var_: Var,
) Allocator.Error!?MissingTryInfo {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| switch (structure) {
            .nominal_type => |nominal| try self.missingTryInfoFromNominal(nominal),
            .record,
            .record_unbound,
            .tuple,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => null,
        },
        .alias => |alias| try self.missingTryInfoForVar(self.types.getAliasBackingVar(alias)),
        .err => null,
        .flex, .rigid, .field_presence => null,
    };
}

fn builtinTryInfoFromNominal(
    self: *Self,
    nominal: types_mod.NominalType,
) Allocator.Error!?BuiltinTryInfo {
    if (!self.nominalIsBuiltinTryType(nominal)) return null;
    const args = self.types.sliceNominalArgs(nominal);
    if (args.len != 2) return null;
    return .{
        .ok_var = args[0],
        .err_var = args[1],
    };
}

fn nullTryInfoFromNominal(
    self: *Self,
    nominal: types_mod.NominalType,
) Allocator.Error!?NullTryInfo {
    const try_info = (try self.builtinTryInfoFromNominal(nominal)) orelse return null;
    if (!try self.varIsExactUnitTagUnion(try_info.err_var, "Null")) return null;
    return .{
        .ok_var = try_info.ok_var,
        .err_var = try_info.err_var,
    };
}

fn missingTryInfoFromNominal(
    self: *Self,
    nominal: types_mod.NominalType,
) Allocator.Error!?MissingTryInfo {
    const try_info = (try self.builtinTryInfoFromNominal(nominal)) orelse return null;
    if (!try self.varIsExactMissingTagUnion(try_info.err_var)) return null;
    return .{
        .ok_var = try_info.ok_var,
        .err_var = try_info.err_var,
    };
}

/// A builtin `Try` whose error row is still an unbound flex var, as in a
/// record field annotated `Try(ok, _)`. Such a field opts into the
/// optional-field convention; parse derivation pins the row to `[Missing]`.
fn unboundTryInfoFromNominal(
    self: *Self,
    nominal: types_mod.NominalType,
) Allocator.Error!?BuiltinTryInfo {
    const try_info = (try self.builtinTryInfoFromNominal(nominal)) orelse return null;
    return switch (self.types.resolveVar(try_info.err_var).desc.content) {
        .flex => try_info,
        .rigid, .alias, .field_presence, .structure, .err => null,
    };
}

fn unboundTryInfoForVar(self: *Self, var_: Var) Allocator.Error!?BuiltinTryInfo {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| switch (structure) {
            .nominal_type => |nominal| try self.unboundTryInfoFromNominal(nominal),
            .record,
            .record_unbound,
            .tuple,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => null,
        },
        .alias => |alias| try self.unboundTryInfoForVar(self.types.getAliasBackingVar(alias)),
        .err, .flex, .rigid, .field_presence => null,
    };
}

fn varIsExactMissingTagUnion(self: *Self, var_: Var) Allocator.Error!bool {
    return try self.varIsExactUnitTagUnion(var_, "Missing");
}

fn varIsExactUnitTagUnion(
    self: *Self,
    var_: Var,
    tag_text: []const u8,
) Allocator.Error!bool {
    return switch (self.types.resolveVar(var_).desc.content) {
        .alias => |alias| try self.varIsExactUnitTagUnion(self.types.getAliasBackingVar(alias), tag_text),
        .structure => |structure| switch (structure) {
            .tag_union => |tag_union| blk: {
                const tags = self.types.getTagsSlice(tag_union.tags);
                const tag_names = tags.items(.name);
                const tag_args = tags.items(.args);
                if (tag_names.len != 1) break :blk false;
                if (!try self.tagExtIsClosedEmpty(tag_union.ext)) break :blk false;
                if (self.types.sliceVars(tag_args[0]).len != 0) break :blk false;
                const text = self.cir.getIdentStoreConst().getText(tag_names[0]);
                break :blk Ident.textEql(text, tag_text);
            },
            .record,
            .record_unbound,
            .tuple,
            .nominal_type,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            .empty_tag_union,
            => false,
        },
        .err, .flex, .rigid, .field_presence => false,
    };
}

fn tagExtIsClosedEmpty(self: *Self, var_: Var) Allocator.Error!bool {
    return switch (self.types.resolveVar(var_).desc.content) {
        .alias => |alias| try self.tagExtIsClosedEmpty(self.types.getAliasBackingVar(alias)),
        .structure => |structure| structure == .empty_tag_union,
        .err, .flex, .rigid, .field_presence => false,
    };
}

fn varIsBuiltinStr(self: *Self, var_: Var) std.mem.Allocator.Error!bool {
    return switch (self.types.resolveVar(var_).desc.content) {
        .structure => |structure| switch (structure) {
            .nominal_type => |nominal| self.nominalIsBuiltinStrType(nominal),
            .record,
            .record_unbound,
            .tuple,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => false,
        },
        .alias => |alias| try self.varIsBuiltinStr(self.types.getAliasBackingVar(alias)),
        .err => true,
        .flex, .rigid => false,
    };
}

fn nominalIsBuiltinTryType(self: *const Self, nominal_type: types_mod.NominalType) bool {
    if (!nominal_type.originIsBuiltin()) return false;
    return (self.builtinNominalDeclForBuiltinSourceDecl(nominal_type.sourceDeclOptional()) orelse return false) == .try_type;
}

fn nominalIsBuiltinNumberType(self: *Self, nominal_type: types_mod.NominalType) bool {
    return self.builtinNumKindFromNominalType(nominal_type) != null;
}

const BuiltinFromNumeralLiteralProblem = enum {
    fractional_integer,
    negative_unsigned,
    out_of_range,
};

/// The exact-numeral target for a concrete builtin NumKind, or null for the
/// unbound kinds (which impose no fit obligation).
fn numeralTargetFromNumKind(num_kind: CIR.NumKind) ?exact_numeral.Target {
    return switch (num_kind) {
        .num_unbound, .int_unbound => null,
        inline .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => |k| @field(exact_numeral.Target, @tagName(k)),
    };
}

/// Whether the literal's exact value is representable at the builtin target—
/// answered by the precomputed fit set (the one fits() authority)—and, when
/// it is not, which problem flavor the diagnostic should carry.
fn validateBuiltinFromNumeralLiteral(
    num_kind: CIR.NumKind,
    num_literal: types_mod.NumeralInfo,
) ?BuiltinFromNumeralLiteralProblem {
    const target = numeralTargetFromNumKind(num_kind) orelse return null;
    if (num_literal.fits.contains(target)) return null;
    return switch (target) {
        // Floats represent every materializable literal (out-of-range becomes
        // ±inf), so they are in every materialized fit set; only a literal
        // whose digits were never recorded reaches this branch.
        .f32, .f64 => .out_of_range,
        .u8, .u16, .u32, .u64, .u128 => blk: {
            if (num_literal.is_fractional) break :blk .fractional_integer;
            // `is_negative` is a syntactic flag (a leading `-`); a `-0` has a
            // zero magnitude and is IN the fit set, so reaching here negative
            // means a genuinely negative value.
            if (num_literal.is_negative) break :blk .negative_unsigned;
            break :blk .out_of_range;
        },
        .i8, .i16, .i32, .i64, .i128 => if (num_literal.is_fractional) .fractional_integer else .out_of_range,
        .dec => .out_of_range,
    };
}

test "unsuffixed positive integer literal validates against unsigned builtin type" {
    const info = types_mod.NumeralInfo.testOnlyInt(42, false, Region.zero());
    try std.testing.expectEqual(@as(?BuiltinFromNumeralLiteralProblem, null), validateBuiltinFromNumeralLiteral(.u64, info));
}

test "out-of-range and negative literals report the right problem flavor" {
    const too_big = types_mod.NumeralInfo.testOnlyInt(300, false, Region.zero());
    try std.testing.expectEqual(@as(?BuiltinFromNumeralLiteralProblem, .out_of_range), validateBuiltinFromNumeralLiteral(.u8, too_big));
    const negative = types_mod.NumeralInfo.testOnlyInt(5, true, Region.zero());
    try std.testing.expectEqual(@as(?BuiltinFromNumeralLiteralProblem, .negative_unsigned), validateBuiltinFromNumeralLiteral(.u8, negative));
    try std.testing.expectEqual(@as(?BuiltinFromNumeralLiteralProblem, null), validateBuiltinFromNumeralLiteral(.i8, negative));
    const negative_zero = types_mod.NumeralInfo.testOnlyInt(0, true, Region.zero());
    try std.testing.expectEqual(@as(?BuiltinFromNumeralLiteralProblem, null), validateBuiltinFromNumeralLiteral(.u8, negative_zero));
}

fn reportInvalidBuiltinFromNumeralLiteral(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
    num_kind: CIR.NumKind,
    env: *Env,
) Allocator.Error!bool {
    const num_literal = constraint.origin.numeralInfo() orelse return false;
    if (!try self.reportInvalidBuiltinFromNumeralInfo(dispatcher_var, num_kind, num_literal, env)) return false;

    try self.poisonConstraintSourceExpr(dispatcher_var, constraint);
    try self.markStaticDispatchRejected(constraint);
    return true;
}

fn reportInvalidBuiltinFromNumeralInfo(
    self: *Self,
    dispatcher_var: Var,
    num_kind: CIR.NumKind,
    num_literal: types_mod.NumeralInfo,
    _: *Env,
) Allocator.Error!bool {
    const literal_problem = validateBuiltinFromNumeralLiteral(num_kind, num_literal);
    if (literal_problem == null) return false;

    const expected_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, dispatcher_var);
    _ = try self.problems.appendProblem(self.gpa, .{ .invalid_numeric_literal = .{
        .literal_var = dispatcher_var,
        .expected_type = expected_snapshot,
        .is_fractional = num_literal.is_fractional,
        .region = num_literal.region,
    } });

    try self.markErroneous(dispatcher_var);
    return true;
}

fn reportUnmaterializableNumeralLiteral(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
    _: *Env,
) Allocator.Error!bool {
    const num_literal = constraint.origin.numeralInfo() orelse return false;
    if (num_literal.can_materialize_numeral) return false;

    const expected_snapshot = try self.snapshots.snapshotVarForError(self.types, &self.type_writer, dispatcher_var);
    _ = try self.problems.appendProblem(self.gpa, .{ .invalid_numeric_literal = .{
        .literal_var = dispatcher_var,
        .expected_type = expected_snapshot,
        .is_fractional = num_literal.is_fractional,
        .region = num_literal.region,
    } });

    try self.poisonConstraintSourceExpr(dispatcher_var, constraint);
    try self.markErroneous(dispatcher_var);
    try self.markStaticDispatchRejected(constraint);
    return true;
}

fn validateFromNumeralLiteralForBuiltinNominal(
    self: *Self,
    dispatcher_var: Var,
    constraint: StaticDispatchConstraint,
    nominal_type: types_mod.NominalType,
    env: *Env,
) Allocator.Error!bool {
    if (constraint.origin != .from_literal) return true;
    const num_kind = self.builtinNumKindFromNominalType(nominal_type) orelse return true;

    return !try self.reportInvalidBuiltinFromNumeralLiteral(dispatcher_var, constraint, num_kind, env);
}

fn validateFromNumeralLiteralForBuiltinAlias(
    _: *Self,
    _: Var,
    _: StaticDispatchConstraint,
    _: types_mod.Alias,
    _: *Env,
    _: bool,
) Allocator.Error!bool {
    return true;
}

fn validateResolvedOpenNumeralLiterals(
    self: *Self,
    env: *Env,
) Allocator.Error!void {
    const literal_count = self.open_numeral_literals.items.len;
    var i: usize = 0;
    while (i < literal_count) : (i += 1) {
        const entry = self.open_numeral_literals.items[i];
        const resolved = self.types.resolveVar(entry.var_);
        if (resolved.desc.content == .err) continue;
        if (try self.reportUnmaterializableNumeralLiteral(resolved.var_, entry.constraint, env)) {
            if (entry.source_node) |node_idx| {
                if (isExprNodeTag(self.cir.store.nodes.get(node_idx).tag)) {
                    try self.erroneous_value_exprs.put(self.gpa, @enumFromInt(@intFromEnum(node_idx)), {});
                }
            }
            continue;
        }

        const nominal_type = switch (resolved.desc.content) {
            .structure => |flat_type| switch (flat_type) {
                .nominal_type => |nominal| nominal,
                .record,
                .record_unbound,
                .tuple,
                .fn_pure,
                .fn_effectful,
                .fn_unbound,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => continue,
            },
            .err => continue,
            .flex, .rigid, .alias, .field_presence => continue,
        };
        const num_kind = self.builtinNumKindFromNominalType(nominal_type) orelse continue;
        _ = try self.reportInvalidBuiltinFromNumeralInfo(resolved.var_, num_kind, entry.constraint.origin.numeralInfo().?, env);
    }
}

fn literalTargetContainsIdentity(
    self: *Self,
    var_: Var,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    if (visited.contains(resolved.var_)) return false;
    try visited.put(resolved.var_, {});

    return switch (resolved.desc.content) {
        .flex, .rigid => true,
        .err, .field_presence => false,
        .alias => |alias| blk: {
            if (try self.literalTargetContainsIdentity(self.types.getAliasBackingVar(alias), visited)) break :blk true;
            for (self.types.sliceAliasArgs(alias)) |arg| {
                if (try self.literalTargetContainsIdentity(arg, visited)) break :blk true;
            }
            break :blk false;
        },
        .structure => |structure| switch (structure) {
            .empty_record, .empty_tag_union => false,
            .tuple => |tuple| blk: {
                for (self.types.sliceVars(tuple.elems)) |elem| {
                    if (try self.literalTargetContainsIdentity(elem, visited)) break :blk true;
                }
                break :blk false;
            },
            .nominal_type => |nominal| blk: {
                for (self.types.sliceNominalArgs(nominal)) |arg| {
                    if (try self.literalTargetContainsIdentity(arg, visited)) break :blk true;
                }
                break :blk false;
            },
            .fn_pure, .fn_effectful, .fn_unbound => |function| blk: {
                for (self.types.sliceVars(function.args)) |arg| {
                    if (try self.literalTargetContainsIdentity(arg, visited)) break :blk true;
                }
                break :blk try self.literalTargetContainsIdentity(function.ret, visited);
            },
            .record => |record| blk: {
                const fields = self.types.getRecordFieldsSlice(record.fields);
                for (fields.items(.presence)) |presence| {
                    if (try self.literalTargetContainsIdentity(presence.typeVar(), visited)) break :blk true;
                }
                break :blk try self.literalTargetContainsIdentity(record.ext, visited);
            },
            .record_unbound => |record_fields| blk: {
                const fields = self.types.getRecordFieldsSlice(record_fields);
                for (fields.items(.presence)) |presence| {
                    if (try self.literalTargetContainsIdentity(presence.typeVar(), visited)) break :blk true;
                }
                break :blk false;
            },
            .tag_union => |tag_union| blk: {
                const tags = self.types.getTagsSlice(tag_union.tags);
                for (tags.items(.args)) |args| {
                    for (self.types.sliceVars(args)) |arg| {
                        if (try self.literalTargetContainsIdentity(arg, visited)) break :blk true;
                    }
                }
                break :blk try self.literalTargetContainsIdentity(tag_union.ext, visited);
            },
        },
    };
}

fn literalTargetIsBuiltinDirect(
    self: *Self,
    var_: Var,
    kind: can.NodeStore.LiteralDispatchPlan.Kind,
    visited: *std.AutoHashMap(Var, void),
) Allocator.Error!bool {
    const resolved = self.types.resolveVar(var_);
    if (visited.contains(resolved.var_)) return false;
    try visited.put(resolved.var_, {});

    return switch (resolved.desc.content) {
        .alias => |alias| try self.literalTargetIsBuiltinDirect(
            self.types.getAliasBackingVar(alias),
            kind,
            visited,
        ),
        .structure => |structure| switch (structure) {
            .nominal_type => |nominal| switch (kind) {
                .numeral => self.nominalIsBuiltinNumberType(nominal),
                .quote => self.nominalIsBuiltinStrType(nominal),
            },
            .record,
            .record_unbound,
            .tuple,
            .fn_pure,
            .fn_effectful,
            .fn_unbound,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => false,
        },
        .err, .flex, .rigid, .field_presence => false,
    };
}

/// Seal every live literal record with the exact decision checking made. The
/// method-instantiation table is positive evidence for a concrete custom
/// target; an identity-bearing target remains a specialization obligation.
fn finalizeLiteralDispatchResolutions(self: *Self) Allocator.Error!void {
    const plans = self.cir.store.literalDispatchPlans();
    if (plans.len == 0) return;

    var visited = std.AutoHashMap(Var, void).init(self.gpa);
    defer visited.deinit();

    // Evidence is recorded under each discharged constraint's raw fn_var, but
    // same-name literal constraints deduplicate when their receivers unify
    // (e.g. two elements of one list): the callable vars are unified and only
    // one raw fn_var survives on the merged constraint. Solving is settled
    // here, so comparing resolved roots recovers every literal's share of that
    // one discharged edge.
    var evidence_fn_roots = std.AutoHashMap(Var, void).init(self.gpa);
    defer evidence_fn_roots.deinit();
    try evidence_fn_roots.ensureTotalCapacity(self.dispatch_target_instantiation_by_fn_var.count());
    var evidence_key_it = self.dispatch_target_instantiation_by_fn_var.keyIterator();
    while (evidence_key_it.next()) |evidence_fn_var| {
        try evidence_fn_roots.put(self.types.resolveVar(evidence_fn_var.*).var_, {});
    }

    var plan_index: usize = 0;
    while (plan_index < plans.len) : (plan_index += 1) {
        // Finalization mutates only the record's resolution field and cannot
        // reallocate the dense plan list, so index-based iteration is stable.
        const plan = self.cir.store.literalDispatchPlans()[plan_index];
        if (plan.dispatchResolution() != .unresolved) {
            std.debug.panic("literal dispatch plan reached finalization already resolved", .{});
        }

        const target_var: Var = @enumFromInt(plan.target_var);
        const fn_var: Var = @enumFromInt(plan.fn_var);
        const resolution: can.NodeStore.LiteralDispatchPlan.Resolution = resolution: {
            // A dispatch-specific rejection is stronger than a concrete
            // builtin target (for example, an out-of-range U8 literal).
            if (self.types.varStaticDispatchRejected(fn_var)) {
                break :resolution .checked_error;
            }

            const node_idx: CIR.Node.Idx = @enumFromInt(plan.node_idx);
            if (isExprNodeTag(self.cir.store.nodes.get(node_idx).tag) and
                self.erroneous_value_exprs.contains(@enumFromInt(plan.node_idx)))
            {
                break :resolution .checked_error;
            }

            // An independently reported error can poison the receiver after
            // this dispatch checked successfully. Preserve that distinct,
            // explicit value-error fence at the checked boundary.
            visited.clearRetainingCapacity();
            if (try self.varContainsError(target_var, &visited)) {
                break :resolution .checked_error;
            }

            visited.clearRetainingCapacity();
            if (try self.literalTargetIsBuiltinDirect(target_var, plan.dispatchKind(), &visited)) {
                break :resolution .builtin_direct;
            }

            visited.clearRetainingCapacity();
            if (try self.literalTargetContainsIdentity(target_var, &visited)) {
                break :resolution .specialization_dispatch;
            }
            if (evidence_fn_roots.contains(self.types.resolveVar(fn_var).var_)) {
                break :resolution .custom_dispatch;
            }

            // Error recovery can leave a literal live after another mismatch
            // pins its target to a concrete type that has no conversion (for
            // example, a quote coerced to I64 by a failing loop body). The
            // settled checker state is total here: successful concrete
            // conversions have positive builtin/callable evidence above. Seal
            // this exact raw edge as rejected, but never let that recovery path
            // hide missing evidence in an otherwise valid module.
            if (self.problems.len() != 0) {
                try self.markStaticDispatchFnRejected(fn_var);
                break :resolution .checked_error;
            }

            const target = self.types.resolveVar(target_var);
            const callable = self.types.resolveVar(fn_var);
            const target_shape = switch (target.desc.content) {
                .structure => |structure| @tagName(structure),
                .flex, .rigid, .alias, .field_presence, .err => @tagName(target.desc.content),
            };
            const callable_shape = switch (callable.desc.content) {
                .structure => |structure| @tagName(structure),
                .flex, .rigid, .alias, .field_presence, .err => @tagName(callable.desc.content),
            };
            const target_name = switch (target.desc.content) {
                .structure => |structure| switch (structure) {
                    .nominal_type => |nominal| self.cir.getIdent(nominal.ident.ident_idx),
                    .record,
                    .record_unbound,
                    .tuple,
                    .fn_pure,
                    .fn_effectful,
                    .fn_unbound,
                    .empty_record,
                    .tag_union,
                    .empty_tag_union,
                    => "<unnamed>",
                },
                .alias => |alias| self.cir.getIdent(alias.ident.ident_idx),
                .flex, .rigid, .field_presence, .err => "<unnamed>",
            };
            std.debug.panic(
                "live concrete {s} literal plan for node {d} has no checked builtin or custom resolution (target var {d}: {s} {s}, callable var {d}: {s})",
                .{
                    @tagName(plan.dispatchKind()),
                    plan.node_idx,
                    @intFromEnum(target.var_),
                    target_shape,
                    target_name,
                    @intFromEnum(callable.var_),
                    callable_shape,
                },
            );
        };
        self.cir.finalizeLiteralDispatchResolution(@enumFromInt(plan.node_idx), resolution);
    }
}

